    }
  }
}

resource "aws_api_gateway_rest_api" "hello_world_api" {
  name        = "HelloWorldAPI"
  description = "API Gateway for Hello World Lambda"
}

resource "aws_api_gateway_resource" "hello" {
  rest_api_id = aws_api_gateway_rest_api.hello_world_api.id
  parent_id   = aws_api_gateway_rest_api.hello_world_api.root_resource_id
  path_part   = "hello"
}

resource "aws_api_gateway_method" "any_method" {
  rest_api_id      = aws_api_gateway_rest_api.hello_world_api.id
  resource_id      = aws_api_gateway_resource.hello.id
  http_method      = "ANY"
  authorization    = "NONE"
  api_key_required = true
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
  required_version = ">= 1.0"
}

resource "aws_kms_key" "sqs" {
  description             = "SQS encryption key"
  enable_key_rotation     = true
  rotation_period_in_days = 365
}

resource "aws_kms_alias" "sqs" {
  name          = "alias/sqs-encryption-key"
  target_key_id = aws_kms_key.sqs.id
}

resource "aws_sqs_queue" "test_sqs" {
  name                       = "test-sqs"
  delay_seconds              = 90
  max_message_size           = 2048
  message_retention_seconds  = 86400
  receive_wait_time_seconds  = 10
  kms_master_key_id          = aws_kms_key.sqs.id
  tags = {
    Environment = "production"
  }
}

resource "aws_sqs_queue" "test_sqs1" {
  name                       = "test-sqs1"
  delay_seconds              = 90
  max_message_size           = 2048
  message_retention_seconds  = 86400
  receive_wait_time_seconds  = 10
  kms_master_key_id          = aws_kms_key.sqs.id
  tags = {
    Environment = "production"
  }
}

terraform {
  required_version = "~> 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "base_bucket_name" {
  description = "Base name for the S3 bucket"
  type        = string
  default     = "doc-io-files"
}

variable "force_destroy_bucket" {
  description = "Force destroy the bucket even if it contains objects"
  type        = bool
  default     = true
}

variable "authorized_account_id" {
  description = "AWS account ID authorized for full S3 access"
  type        = string
  default     = "566373416292"
}

resource "random_integer" "bucket_suffix" {
  min = 1
  max = 50000
}

# ------------------------------------------------
# Main document I/O bucket
# ------------------------------------------------
resource "aws_s3_bucket" "doc_io" {
  bucket        = "${random_integer.bucket_suffix.result}-${var.base_bucket_name}"
  force_destroy = var.force_destroy_bucket
}

resource "aws_s3_bucket_public_access_block" "doc_io_public_access_block" {
  bucket = aws_s3_bucket.doc_io.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "doc_io_versioning" {
  bucket = aws_s3_bucket.doc_io.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "doc_io_encryption" {
  bucket = aws_s3_bucket.doc_io.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.doc_io_encryption_key.arn
    }
  }
}

resource "aws_s3_bucket_policy" "doc_io_policy" {
  bucket = aws_s3_bucket.doc_io.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "FullS3AccessForSpecifiedAccount"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${var.authorized_account_id}:root"
        }
        Action   = "s3:*"
        Resource = [
          aws_s3_bucket.doc_io.arn,
          "${aws_s3_bucket.doc_io.arn}/*"
        ]
      }
    ]
  })
}

# ------------------------------------------------
# KMS key with automatic rotation
# ------------------------------------------------
resource "aws_kms_key" "doc_io_encryption_key" {
  description             = "KMS key for S3 bucket default encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

# ------------------------------------------------
# Logging target bucket
# ------------------------------------------------
resource "aws_s3_bucket" "doc_io_logs" {
  bucket        = "${random_integer.bucket_suffix.result}-${var.base_bucket_name}-logs"
  force_destroy = var.force_destroy_bucket
}

resource "aws_s3_bucket_public_access_block" "doc_io_logs_public_access_block" {
  bucket = aws_s3_bucket.doc_io_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "doc_io_logs_versioning" {
  bucket = aws_s3_bucket.doc_io_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "doc_io_logs_encryption" {
  bucket = aws_s3_bucket.doc_io_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.doc_io_encryption_key.arn
    }
  }
}

resource "aws_s3_bucket_policy" "doc_io_logs_policy" {
  bucket = aws_s3_bucket.doc_io_logs.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "S3ServerAccessLogsWrite"
        Effect    = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.doc_io_logs.arn}/*"
      }
    ]
  })
}

# ------------------------------------------------
# Enable logging on the main bucket
# ------------------------------------------------
resource "aws_s3_bucket_logging" "doc_io_logging" {
  bucket = aws_s3_bucket.doc_io.id

  target_bucket = aws_s3_bucket.doc_io_logs.id
  target_prefix = "log/"
}

