terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

variable "api_name" {
  description = "The name of the API Gateway REST API"
  type        = string
  default     = "terraform-api-gateway-example"
}

resource "aws_kms_key" "cloudwatch" {
  enable_key_rotation = true
  description         = "KMS key for API Gateway access logs"
  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-policy-cloudwatch"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          ArnEquals = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/api-gw/movies-api"
          }
        }
      }
    ]
  })
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/api-gw-logs"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

resource "aws_cloudwatch_log_group" "api_gw_access_logs" {
  name              = "/aws/api-gw/movies-api"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.cloudwatch.arn
}

resource "aws_api_gateway_rest_api" "movies_api" {
  name        = var.api_name
  description = "Mock testing API for movies endpoint"
}

resource "aws_api_gateway_resource" "movies_resource" {
  rest_api_id = aws_api_gateway_rest_api.movies_api.id
  parent_id   = aws_api_gateway_rest_api.movies_api.root_resource_id
  path_part   = "movies"
}

resource "aws_api_gateway_method" "movies_get_method" {
  rest_api_id      = aws_api_gateway_rest_api.movies_api.id
  resource_id      = aws_api_gateway_resource.movies_resource.id
  http_method      = "GET"
  authorization    = "NONE"
  api_key_required = true
}

resource "aws_api_gateway_integration" "movies_get_integration" {
  rest_api_id = aws_api_gateway_rest_api.movies_api.id
  resource_id = aws_api_gateway_resource.movies_resource.id
  http_method = aws_api_gateway_method.movies_get_method.http_method
  type        = "MOCK"

  request_templates = {
    "application/json" = jsonencode({
      statusCode = 200
    })
  }
}

resource "aws_api_gateway_method_response" "movies_get_method_response_200" {
  rest_api_id = aws_api_gateway_rest_api.movies_api.id
  resource_id = aws_api_gateway_resource.movies_resource.id
  http_method = aws_api_gateway_method.movies_get_method.http_method
  status_code = "200"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "movies_get_integration_response_200" {
  rest_api_id = aws_api_gateway_rest_api.movies_api.id
  resource_id = aws_api_gateway_resource.movies_resource.id
  http_method = aws_api_gateway_method.movies_get_method.http_method
  status_code = aws_api_gateway_method_response.movies_get_method_response_200.status_code

  response_templates = {
    "application/json" = jsonencode({
      message = "Hello from the movies API!"
    })
  }
}

resource "aws_api_gateway_deployment" "movies_deployment" {
  rest_api_id = aws_api_gateway_rest_api.movies_api.id

  triggers = {
    redeployment = sha256(join(",", [
      aws_api_gateway_integration.movies_get_integration.id,
      aws_api_gateway_integration_response.movies_get_integration_response_200.id,
    ]))
  }

  depends_on = [
    aws_api_gateway_integration.movies_get_integration,
    aws_api_gateway_integration_response.movies_get_integration_response_200,
  ]
}

resource "aws_api_gateway_stage" "movies_stage" {
  stage_name           = "test"
  rest_api_id          = aws_api_gateway_rest_api.movies_api.id
  deployment_id        = aws_api_gateway_deployment.movies_deployment.id
  xray_tracing_enabled = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_gw_access_logs.arn
    format = jsonencode({
      requestId      = "$context.requestId"
      sourceIp       = "$context.identity.sourceIp"
      httpMethod     = "$context.httpMethod"
      resourcePath   = "$context.resourcePath"
      status         = "$context.status"
      responseLength = "$context.responseLength"
      error          = "$context.error.messageString"
    })
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "kms_alias_name" {
  type    = string
  default = "kms-cmk-example"
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "key_policy" {
  statement {
    sid    = "KmsCmkPolicy"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.arn]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }
}

resource "aws_kms_key" "test_cmk" {
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.key_policy.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "test_alias" {
  name          = "alias/${var.kms_alias_name}"
  target_key_id = aws_kms_key.test_cmk.key_id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  alias  = "us-east-nv"
  region = "us-east-1"
  default_tags {
    tags = {
      Terraform = "yes"
      Region    = "N.Virginia"
    }
  }
}

provider "aws" {
  alias  = "ap-south-mumbai"
  region = "ap-south-1"
  default_tags {
    tags = {
      Terraform = "yes"
      Region    = "Mumbai"
    }
  }
}

data "aws_caller_identity" "current" {
  provider = aws.us-east-nv
}

resource "aws_vpc" "north_virginia" {
  provider   = aws.us-east-nv
  cidr_block = "10.1.0.0/16"
  tags = {
    Name = "North-Virginia-VPC"
  }
}

resource "aws_vpc" "mumbai" {
  provider   = aws.ap-south-mumbai
  cidr_block = "10.2.0.0/16"
  tags = {
    Name = "Mumbai-VPC"
  }
}

# IAM role for VPC Flow Logs (global, created in us-east-1)
resource "aws_iam_role" "flow_logs" {
  provider = aws.us-east-nv
  name     = "vpc-flow-logs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "flow_logs" {
  provider = aws.us-east-nv
  name     = "vpc-flow-logs-policy"
  role     = aws_iam_role.flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      }
    ]
  })
}

# KMS keys for CloudWatch Log Groups (with key policy allowing CloudWatch Logs and root account)
resource "aws_kms_key" "cloudwatch_nv" {
  provider            = aws.us-east-nv
  enable_key_rotation = true
  description         = "KMS key for CloudWatch Log Group in N.Virginia"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableCloudWatchLogs"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "cloudwatch_nv" {
  provider      = aws.us-east-nv
  name          = "alias/cloudwatch-nv"
  target_key_id = aws_kms_key.cloudwatch_nv.key_id
}

resource "aws_kms_key" "cloudwatch_mumbai" {
  provider            = aws.ap-south-mumbai
  enable_key_rotation = true
  description         = "KMS key for CloudWatch Log Group in Mumbai"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableCloudWatchLogs"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "cloudwatch_mumbai" {
  provider      = aws.ap-south-mumbai
  name          = "alias/cloudwatch-mumbai"
  target_key_id = aws_kms_key.cloudwatch_mumbai.key_id
}

# CloudWatch Log Groups encrypted with KMS (using key ARN, not alias)
resource "aws_cloudwatch_log_group" "north_virginia" {
  provider = aws.us-east-nv
  name     = "north-virginia-vpc-flow-logs"
  retention_in_days = 7
  kms_key_id        = aws_kms_key.cloudwatch_nv.arn
}

resource "aws_cloudwatch_log_group" "mumbai" {
  provider = aws.ap-south-mumbai
  name     = "mumbai-vpc-flow-logs"
  retention_in_days = 7
  kms_key_id        = aws_kms_key.cloudwatch_mumbai.arn
}

# VPC Flow Logs (using log_destination instead of deprecated log_group_name)
resource "aws_flow_log" "north_virginia" {
  provider = aws.us-east-nv
  vpc_id               = aws_vpc.north_virginia.id
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.north_virginia.arn
  iam_role_arn         = aws_iam_role.flow_logs.arn
  traffic_type         = "ALL"
}

resource "aws_flow_log" "mumbai" {
  provider = aws.ap-south-mumbai
  vpc_id               = aws_vpc.mumbai.id
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.mumbai.arn
  iam_role_arn         = aws_iam_role.flow_logs.arn
  traffic_type         = "ALL"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "main"
  }
}

resource "aws_security_group" "allow_tcp" {
  name        = "allow_tcp"
  description = "Allow TCP traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow TCP egress"
    protocol    = "tcp"
    from_port   = 10000
    to_port     = 10000
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "allow_tcp"
  }
}

resource "aws_security_group" "allow_udp" {
  name        = "allow_udp"
  description = "Allow UDP traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow UDP egress"
    protocol    = "udp"
    from_port   = 10000
    to_port     = 10000
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "allow_udp"
  }
}

resource "aws_security_group" "allow_icmp" {
  name        = "allow_icmp"
  description = "Allow ICMP traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow ICMP egress"
    protocol    = "icmp"
    from_port   = -1
    to_port     = -1
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "allow_icmp"
  }
}

resource "aws_security_group" "allow_all" {
  name        = "allow_all"
  description = "Allow ALL traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow ALL egress"
    protocol    = "-1"
    from_port   = 0
    to_port     = 0
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "allow_all"
  }
}

resource "aws_kms_key" "cloudwatch" {
  enable_key_rotation = true
  description         = "CMK for VPC Flow Logs"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable root user administration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/cloudwatch-flow-logs"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

resource "aws_cloudwatch_log_group" "flow_log" {
  name       = "/aws/vpc/flow-log"
  kms_key_id = aws_kms_alias.cloudwatch.arn
}

resource "aws_iam_role" "flow_log" {
  name = "vpc-flow-log-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "flow_log" {
  name = "vpc-flow-log-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "${aws_cloudwatch_log_group.flow_log.arn}:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "flow_log" {
  role       = aws_iam_role.flow_log.name
  policy_arn = aws_iam_policy.flow_log.arn
}

resource "aws_flow_log" "main" {
  log_destination      = aws_cloudwatch_log_group.flow_log.arn
  log_destination_type = "cloud-watch-logs"
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.main.id
  iam_role_arn         = aws_iam_role.flow_log.arn
}

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

resource "aws_s3_bucket" "terraform_state" {
  bucket_prefix = "terraform-state-"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "state_kms" {
  description             = "Terraform state bucket encryption key"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "state_kms_alias" {
  name          = "alias/terraform-state-key"
  target_key_id = aws_kms_key.state_kms.id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state_kms.arn
    }
  }
}

resource "aws_s3_bucket" "terraform_state_logs" {
  bucket_prefix = "terraform-state-logs-"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "terraform_state_logs" {
  bucket = aws_s3_bucket.terraform_state_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state_logs" {
  bucket = aws_s3_bucket.terraform_state_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state_logs" {
  bucket = aws_s3_bucket.terraform_state_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_policy" "terraform_state_logs" {
  bucket = aws_s3_bucket.terraform_state_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.terraform_state_logs.arn}/log/*"
      }
    ]
  })
}

resource "aws_s3_bucket_logging" "terraform_state" {
  depends_on = [
    aws_s3_bucket_policy.terraform_state_logs,
  ]

  bucket = aws_s3_bucket.terraform_state.id

  target_bucket = aws_s3_bucket.terraform_state_logs.id
  target_prefix = "log/"
}

resource "aws_kms_key" "dynamodb_lock_kms" {
  description             = "DynamoDB Terraform lock table encryption key"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "terraform_lock" {
  name         = "terraform-lock"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.dynamodb_lock_kms.arn
  }

  lifecycle {
    prevent_destroy = true
  }
}

output "state_bucket_name" {
  value = aws_s3_bucket.terraform_state.id
}

output "lock_table_name" {
  value = aws_dynamodb_table.terraform_lock.name
}

output "kms_key_arn" {
  value = aws_kms_key.state_kms.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  account_id = data.aws_caller_identity.current.account_id
}

variable "regions" {
  type        = list(string)
  default     = ["*"]
  description = "List of AWS regions for the policy resource"
}

data "aws_caller_identity" "current" {}

resource "aws_iam_policy" "powerscale_node_runtime_policy" {
  name        = "${local.account_id}-powerscale-node-runtime-policy"
  description = "Policy for PowerScale node runtime operations"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "ec2:AssignPrivateIpAddresses"
        Resource = [for region in var.regions : "arn:aws:ec2:${region}:${local.account_id}:network-interface/*"]
      }
    ]
  })
}

resource "aws_iam_role" "powerscale_node_runtime_role" {
  name = "${local.account_id}-powerscale-node-runtime-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "powerscale_node_runtime_attachment" {
  role       = aws_iam_role.powerscale_node_runtime_role.name
  policy_arn = aws_iam_policy.powerscale_node_runtime_policy.arn
}

resource "aws_iam_instance_profile" "powerscale_node_runtime_instance_profile" {
  name = "${local.account_id}-powerscale-node-runtime-instance-profile"
  role = aws_iam_role.powerscale_node_runtime_role.name
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "192.168.0.0/16"
}

variable "environment" {
  description = "Environment tag for all resources"
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "main"
    Environment = var.environment
  }
}

resource "aws_subnet" "web" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, 0)
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name        = "web"
    Environment = var.environment
  }
}

resource "aws_subnet" "app" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, 1)
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name        = "app"
    Environment = var.environment
  }
}

resource "aws_subnet" "db" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, 2)
  availability_zone = data.aws_availability_zones.available.names[2]

  tags = {
    Name        = "db"
    Environment = var.environment
  }
}

resource "aws_subnet" "mgmt" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, 3)
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name        = "mgmt"
    Environment = var.environment
  }
}

resource "aws_kms_key" "flow_log" {
  description         = "KMS key for VPC flow log CloudWatch log group encryption"
  enable_key_rotation = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "vpc-flow-logs-key-policy"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name        = "vpc-flow-logs-kms"
    Environment = var.environment
  }
}

resource "aws_kms_alias" "flow_log" {
  name          = "alias/vpc-flow-logs"
  target_key_id = aws_kms_key.flow_log.id
}

resource "aws_cloudwatch_log_group" "flow_log" {
  name              = "vpc-flow-logs"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.flow_log.arn

  tags = {
    Name        = "vpc-flow-logs"
    Environment = var.environment
  }
}

resource "aws_iam_role" "flow_log" {
  name = "vpc-flow-logs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name        = "vpc-flow-logs-role"
    Environment = var.environment
  }
}

resource "aws_iam_role_policy" "flow_log" {
  name = "vpc-flow-logs-policy"
  role = aws_iam_role.flow_log.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.flow_log.arn}:*"
      },
      {
        Effect = "Allow"
        Action = "logs:DescribeLogGroups"
        Resource = aws_cloudwatch_log_group.flow_log.arn
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.flow_log.arn
  iam_role_arn         = aws_iam_role.flow_log.arn

  tags = {
    Name        = "main-vpc-flow-logs"
    Environment = var.environment
  }

  depends_on = [aws_iam_role_policy.flow_log]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Environment tag value"
  type        = string
  default     = "dev"
}

resource "aws_iam_user" "tj" {
  name = "TJ"
  tags = {
    Name        = "TJ"
    Environment = var.environment
  }
}

resource "aws_iam_access_key" "tj" {
  user = aws_iam_user.tj.name
}

resource "aws_iam_group" "glacier_efs_ec2" {
  name = "GlacierEFSEC2-group"
}

resource "aws_iam_group_policy" "glacier_efs_ec2" {
  name  = "GlacierEFSEC2"
  group = aws_iam_group.glacier_efs_ec2.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "ec2:*"
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = ["true"]
          }
        }
      },
      {
        Effect   = "Allow"
        Action   = "elasticfilesystem:ClientMount"
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = ["true"]
          }
        }
      },
      {
        Effect = "Allow"
        Action = [
          "glacier:CreateVault",
          "glacier:DeleteVault",
          "glacier:ListVaults",
          "glacier:RetrieveArchive",
          "glacier:DeleteArchive",
          "glacier:InitiateMultipartUpload",
          "glacier:UploadMultipartPart",
          "glacier:CompleteMultipartUpload",
          "glacier:AbortMultipartUpload"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = ["true"]
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_membership" "tj" {
  name  = "tj-membership"
  group = aws_iam_group.glacier_efs_ec2.name
  users = [aws_iam_user.tj.name]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_partition" "current" {}

locals {
  ec2_service_principal = data.aws_partition.current.partition == "aws-cn" ? "ec2.amazonaws.com.cn" : "ec2.amazonaws.com"
}

data "aws_iam_policy_document" "ec2_trust_policy" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = [local.ec2_service_principal]
    }
  }
}

variable "role_name" {
  description = "Name of the IAM role and instance profile"
  type        = string
  default     = "ec2-role"
}

variable "managed_policy_arns" {
  description = "List of managed IAM policy ARNs to attach to the role"
  type        = list(string)
  default     = []
}

variable "inline_policies" {
  description = "Map of inline policy names to policy JSON documents"
  type        = map(string)
  default     = {}
}

resource "aws_iam_role" "ec2_role" {
  name               = var.role_name
  assume_role_policy = data.aws_iam_policy_document.ec2_trust_policy.json
}

resource "aws_iam_instance_profile" "ec2_profile" {
  name = var.role_name
  role = aws_iam_role.ec2_role.name
}

resource "aws_iam_role_policy_attachment" "managed" {
  count      = length(var.managed_policy_arns)
  role       = aws_iam_role.ec2_role.name
  policy_arn = var.managed_policy_arns[count.index]
}

resource "aws_iam_role_policy" "inline" {
  for_each = var.inline_policies
  name     = each.key
  role     = aws_iam_role.ec2_role.name
  policy   = each.value
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

resource "aws_vpc" "fast_app" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "Fast-App"
  }
}

resource "aws_internet_gateway" "fast_app" {
  vpc_id = aws_vpc.fast_app.id

  tags = {
    Name = "Fast-App-IGW"
  }
}

resource "aws_subnet" "public" {
  count                   = length(data.aws_availability_zones.available.names)
  vpc_id                  = aws_vpc.fast_app.id
  cidr_block              = cidrsubnet(aws_vpc.fast_app.cidr_block, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "Fast-App-Public-${count.index}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.fast_app.id

  tags = {
    Name = "Fast-App-Public-RT"
  }
}

resource "aws_route" "internet_access" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.fast_app.id
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public[*].id)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_subnet" "private" {
  count                   = length(data.aws_availability_zones.available.names)
  vpc_id                  = aws_vpc.fast_app.id
  cidr_block              = cidrsubnet(aws_vpc.fast_app.cidr_block, 8, count.index + 101)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "Fast-App-Private-${count.index}"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.fast_app.id

  tags = {
    Name = "Fast-App-Private-RT"
  }
}

resource "aws_route_table_association" "private" {
  count          = length(aws_subnet.private[*].id)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for CloudWatch Logs encryption (Fast-App VPC Flow Logs)"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable CloudWatch Logs service"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Enable root account full access"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "Fast-App-FlowLogs-KMS"
  }
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/fast-app-flow-logs"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = "/aws/vpc/fast-app-flow-logs"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.cloudwatch.arn

  tags = {
    Name = "Fast-App-FlowLogs"
  }
}

resource "aws_iam_role" "flow_logs" {
  name = "Fast-App-FlowLogs-Role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "Fast-App-FlowLogs-Role"
  }
}

resource "aws_iam_role_policy" "flow_logs" {
  name = "Fast-App-FlowLogs-Policy"
  role = aws_iam_role.flow_logs.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${aws_cloudwatch_log_group.flow_logs.name}:*"
        ]
      }
    ]
  })
}

resource "aws_flow_log" "fast_app" {
  log_destination_type = "cloud-watch-logs"
  log_group_name       = aws_cloudwatch_log_group.flow_logs.name
  iam_role_arn         = aws_iam_role.flow_logs.arn
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.fast_app.id

  tags = {
    Name = "Fast-App-FlowLogs"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "monitoring_account_ids" {
  description = "List of AWS account IDs allowed to assume the Grafana cross-account role"
  type        = list(string)
  default     = null
}

data "aws_caller_identity" "current" {}

locals {
  allowed_account_ids = var.monitoring_account_ids != null ? var.monitoring_account_ids : [data.aws_caller_identity.current.account_id]
}

data "aws_iam_policy_document" "grafana_trust_policy" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["grafana.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = local.allowed_account_ids
    }
  }
}

resource "aws_iam_role" "grafana_cross_account" {
  name               = "GrafanaCrossAccountRole"
  assume_role_policy = data.aws_iam_policy_document.grafana_trust_policy.json
  description        = "Role assumed by AWS Managed Grafana to query monitoring data"
}

data "aws_iam_policy_document" "grafana_monitoring_query_policy" {
  statement {
    sid    = "QueryAMP"
    effect = "Allow"
    actions = [
      "aps:QueryMetrics",
      "aps:GetSeries",
      "aps:GetLabels",
      "aps:GetMetricMetadata"
    ]
    resources = [
      "arn:aws:aps:*:${data.aws_caller_identity.current.account_id}:workspace/*"
    ]
  }

  statement {
    sid    = "QueryCloudWatch"
    effect = "Allow"
    actions = [
      "cloudwatch:GetMetricData",
      "cloudwatch:GetMetricStatistics",
      "cloudwatch:ListMetrics"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "grafana_monitoring_query" {
  name        = "GrafanaMonitoringQueryPolicy"
  description = "Policy allowing Grafana to query Amazon Managed Service for Prometheus and CloudWatch metrics"
  policy      = data.aws_iam_policy_document.grafana_monitoring_query_policy.json
}

resource "aws_iam_role_policy_attachment" "grafana_monitoring_query_attach" {
  role       = aws_iam_role.grafana_cross_account.name
  policy_arn = aws_iam_policy.grafana_monitoring_query.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Environment tag for resources"
  type        = string
  default     = "test"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "main-vpc"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name        = "private-subnet-a"
    Environment = var.environment
    Type        = "private"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name        = "private-subnet-b"
    Environment = var.environment
    Type        = "private"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for CloudWatch log group encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name        = "cloudwatch-kms-key"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/cloudwatch"
  target_key_id = aws_kms_key.cloudwatch.key_id

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cloudwatch_log_group" "flow_log" {
  name = "/aws/vpc/flow-logs"

  kms_key_id = aws_kms_alias.cloudwatch.arn

  tags = {
    Name        = "vpc-flow-logs"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_flow_log" "main" {
  iam_role_arn    = aws_iam_role.flow_log.arn
  log_group_name  = aws_cloudwatch_log_group.flow_log.name
  traffic_type    = "ALL"
  vpc_id          = aws_vpc.main.id

  tags = {
    Name        = "main-vpc-flow-log"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "flow_log" {
  name = "vpc-flow-log-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name        = "vpc-flow-log-role"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy" "flow_log" {
  name = "vpc-flow-log-policy"
  role = aws_iam_role.flow_log.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

output "vpc_id" {
  description = "ID of the VPC"
