  }
}

resource "aws_iam_role" "flow_logs" {
  name = "trade-tariff-development-vpc-flow-logs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "trade-tariff-development-vpc-flow-logs-role"
  }
