resource "aws_iam_policy" "flow_logs" {
  name = "trade-tariff-development-vpc-flow-logs-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DescribeLogGroups"
        Effect = "Allow"
        Action = [
