terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

variable "repository_name" {
  description = "Name of the ECR repository"
  type        = string
  default     = "my-app-repo"
}

variable "enable_kms_encryption" {
  description = "Enable KMS encryption for the ECR repository"
  type        = bool
  default     = true
}

variable "repository_policy_json" {
  description = "JSON policy document to attach to the ECR repository (null to skip)"
  type        = string
  default     = null
}

variable "lifecycle_policy_json" {
  description = "JSON lifecycle policy to attach to the ECR repository (null to skip)"
  type        = string
  default     = null
}

resource "aws_kms_key" "ecr" {
  count = var.enable_kms_encryption ? 1 : 0

  description             = "KMS key for ECR repository ${var.repository_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowRootAdmin"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowECRService"
        Effect = "Allow"
        Principal = {
          Service = "ecr.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_ecr_repository" "main" {
  name                 = var.repository_name
  image_tag_mutability = "IMMUTABLE"
  force_delete         = false

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = var.enable_kms_encryption ? "KMS" : "AES256"
    kms_key         = var.enable_kms_encryption ? aws_kms_key.ecr[0].arn : null
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecr_repository_policy" "restrict_pull" {
  count = var.repository_policy_json != null ? 1 : 0

  repository = aws_ecr_repository.main.name
  policy     = var.repository_policy_json
}

resource "aws_ecr_lifecycle_policy" "cleanup" {
  count = var.lifecycle_policy_json != null ? 1 : 0

  repository = aws_ecr_repository.main.name
  policy     = var.lifecycle_policy_json
}

# main.tf
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "environment" {
  description = "Deployment environment (e.g., dev, staging, prod)"
  type        = string
  default     = "dev"
}

variable "queue_name" {
  description = "Base name for the SQS queue"
  type        = string
  default     = "app-queue"
}

variable "enable_fifo_queue" {
  description = "Enable FIFO queue (adds .fifo suffix and enables content-based deduplication)"
  type        = bool
  default     = false
}

variable "enable_access_policy" {
  description = "Whether to attach a policy granting sqs:SendMessage to a specific principal"
  type        = bool
  default     = false
}

variable "allowed_principal_arn" {
  description = "ARN of the principal allowed to send messages (required when enable_access_policy is true)"
  type        = string
  default     = ""

  validation {
    condition     = !var.enable_access_policy || (var.enable_access_policy && length(var.allowed_principal_arn) > 0)
    error_message = "allowed_principal_arn must be non-empty when enable_access_policy is true."
  }
}

# ------------------------------------------------------------------------------
# Local naming and tagging (replaces the module)
# ------------------------------------------------------------------------------
locals {
  queue_name = var.enable_fifo_queue ? "${var.queue_name}.fifo" : var.queue_name
  tags = {
    Name        = local.queue_name
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

# ------------------------------------------------------------------------------
# SQS Queue
# ------------------------------------------------------------------------------
resource "aws_sqs_queue" "main" {
  name                        = local.queue_name
  fifo_queue                  = var.enable_fifo_queue
  content_based_deduplication = var.enable_fifo_queue ? true : null
  sqs_managed_sse_enabled     = true
  tags                        = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Access Policy (conditional)
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "sqs_send_message" {
  count   = var.enable_access_policy ? 1 : 0
  version = "2012-10-17"

  statement {
    effect    = "Allow"
    actions   = ["sqs:SendMessage"]
    resources = [aws_sqs_queue.main.arn]

    principals {
      type        = "AWS"
      identifiers = [var.allowed_principal_arn]
    }
  }
}

resource "aws_sqs_queue_policy" "main" {
  count = var.enable_access_policy ? 1 : 0

  queue_url = aws_sqs_queue.main.id
  policy    = data.aws_iam_policy_document.sqs_send_message[0].json
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------
output "queue_name" {
  description = "Name of the SQS queue"
  value       = aws_sqs_queue.main.name
}

output "queue_arn" {
  description = "ARN of the SQS queue"
  value       = aws_sqs_queue.main.arn
}

output "queue_url" {
  description = "URL of the SQS queue"
  value       = aws_sqs_queue.main.id
}

# Required providers and version pinning
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Input variables
variable "create_cluster" {
  description = "Whether to create the primary DSQL cluster"
  type        = bool
  default     = true
}

variable "deletion_protection" {
  description = "Enable deletion protection on the DSQL cluster"
  type        = bool
  default     = true
}

variable "kms_key_arn" {
  description = "ARN of the KMS key for encryption. Empty uses default AWS managed key."
  type        = string
  default     = ""
}

variable "force_destroy" {
  description = "Allow the cluster to be destroyed even if it contains data (not currently supported by the provider)"
  type        = bool
  default     = false
}

variable "enable_peering" {
  description = "Whether to create cluster peering relationships"
  type        = bool
  default     = false
}

variable "peer_cluster_arns" {
  description = "List of ARNs of clusters to peer with"
  type        = list(string)
  default     = []
}

variable "peering_witness_region" {
  description = "Optional witness region for cluster peering. If empty, defaults to 'us-east-1'."
  type        = string
  default     = ""
}

variable "peering_create_timeout" {
  description = "Timeout for creating each cluster peering resource"
  type        = string
  default     = "10m"
}

# Primary DSQL cluster
resource "aws_dsql_cluster" "primary" {
  count = var.create_cluster ? 1 : 0

  deletion_protection_enabled = var.deletion_protection
  kms_encryption_key          = var.kms_key_arn != "" ? var.kms_key_arn : null
}

# Cluster peering relationships (only when peering is enabled and peer list is non‑empty)
resource "aws_dsql_cluster_peering" "this" {
  count = var.create_cluster && var.enable_peering ? length(var.peer_cluster_arns) : 0

  identifier = "peering-${count.index}"

  clusters = toset([
    aws_dsql_cluster.primary[0].arn,
    var.peer_cluster_arns[count.index]
  ])

  witness_region = var.peering_witness_region != "" ? var.peering_witness_region : "us-east-1"

  timeouts {
    create = var.peering_create_timeout
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "bucket_name" {
  description = "Name of the S3 bucket"
  type        = string
  default     = "my-bucket"
}

variable "tags" {
  description = "Tags to apply to resources"
  type        = map(string)
  default     = {}
}

variable "object_lock_enabled" {
  description = "Enable object lock on the bucket"
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Force destroy the bucket even if non-empty"
  type        = bool
  default     = false
}

variable "bucket_policies" {
  description = "Map of bucket policy objects"
  type = map(object({
    version = string
    statements = list(object({
      sid        = string
      actions    = list(string)
      effect     = optional(string)
      resources  = list(string)
      principals = map(list(string))
    }))
  }))
  default = {}
}

resource "random_id" "this" {
  byte_length = 4
}

resource "aws_s3_bucket" "this" {
  bucket              = "${var.bucket_name}-${random_id.this.hex}"
  tags                = var.tags
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled
}

resource "aws_s3_bucket_logging" "this" {
  bucket        = aws_s3_bucket.this.id
  target_bucket = aws_s3_bucket.log_bucket.id
  target_prefix = "logs/"
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  ignore_public_acls      = true
  block_public_policy     = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "encryption" {
  enable_key_rotation     = true
  deletion_window_in_days = 7
  tags                    = var.tags
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.encryption.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket" "log_bucket" {
  bucket        = "${var.bucket_name}-logs-${random_id.this.hex}"
  force_destroy = true
  tags          = var.tags
}

resource "aws_s3_bucket_public_access_block" "log_bucket" {
  bucket                  = aws_s3_bucket.log_bucket.id
  block_public_acls       = true
  ignore_public_acls      = true
  block_public_policy     = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.encryption.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "log_bucket" {
  bucket     = aws_s3_bucket.log_bucket.id
  acl        = "log-delivery-write"
  depends_on = [aws_s3_bucket_ownership_controls.log_bucket]
}

data "aws_iam_policy_document" "bucket_policy_document" {
  for_each = var.bucket_policies

  policy_id = each.key
  version   = each.value.version

  dynamic "statement" {
    for_each = each.value.statements
    content {
      sid       = statement.value.sid
      actions   = statement.value.actions
      effect    = try(statement.value.effect, "Allow")
      resources = statement.value.resources
      dynamic "principals" {
        for_each = statement.value.principals
        content {
          type        = principals.key
          identifiers = principals.value
        }
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  for_each = var.bucket_policies

  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket_policy_document[each.key].json
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
  required_version = ">= 1.3.0"
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------
variable "create_topic" {
  description = "Main toggle to create all SNS topic resources"
  type        = bool
  default     = true
}

variable "topic_name" {
  description = "Explicit topic name (if set, name_prefix is ignored)"
  type        = string
  default     = null
}

variable "topic_name_prefix" {
  description = "Topic name prefix (used when topic_name is not set)"
  type        = string
  default     = "sns-topic-"
}

variable "display_name" {
  description = "Display name for the topic"
  type        = string
  default     = null
}

variable "fifo_topic" {
  description = "Enable FIFO topic"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content‑based deduplication for FIFO topics"
  type        = bool
  default     = false
}

variable "kms_master_key_id" {
  description = "KMS master key ID for encryption (empty uses default AWS managed key)"
  type        = string
  default     = ""
}

variable "subscriptions" {
  description = "Map of topic subscriptions"
  type = map(object({
    protocol                      = string
    endpoint                      = string
    filter_policy                 = optional(string)
    confirmation_timeout_seconds  = optional(number)  # kept for documentation only; not used in resource
    raw_message_delivery          = optional(bool)
    delivery_policy               = optional(string)
    redrive_policy                = optional(string)
    replay_policy                 = optional(string)
    subscription_role_arn         = optional(string)
  }))
  default = {}
}

variable "topic_policy_statements" {
  description = "Additional policy statements for the topic policy (each must include Effect, Principal, Action, Resource; Condition is optional)"
  type = list(object({
    Effect    = string
    Principal = any
    Action    = any
    Resource  = any
    Condition = optional(any)
  }))
  default = []
}

# ------------------------------------------------------------------------------
# DATA SOURCES
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# SNS TOPIC
# ------------------------------------------------------------------------------
resource "aws_sns_topic" "main" {
  count = var.create_topic ? 1 : 0

  name         = var.topic_name != null ? var.topic_name : null
  name_prefix  = var.topic_name == null ? var.topic_name_prefix : null
  display_name = var.display_name

  fifo_topic                 = var.fifo_topic
  content_based_deduplication = var.content_based_deduplication

  kms_master_key_id = var.kms_master_key_id != "" ? var.kms_master_key_id : null
}

# ------------------------------------------------------------------------------
# IAM ROLE FOR DELIVERY FEEDBACK
# ------------------------------------------------------------------------------
resource "aws_iam_role" "delivery_feedback" {
  count = var.create_topic ? 1 : 0

  name = "sns-delivery-feedback-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "delivery_feedback" {
  count = var.create_topic ? 1 : 0

  name = "sns-delivery-feedback-policy"
  role = aws_iam_role.delivery_feedback[0].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sns:Publish"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# SNS TOPIC POLICY
# ------------------------------------------------------------------------------
resource "aws_sns_topic_policy" "main" {
  count = var.create_topic ? 1 : 0

  arn = aws_sns_topic.main[0].arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Effect = "Allow"
          Principal = {
            AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
          }
          Action   = "sns:Publish"
          Resource = aws_sns_topic.main[0].arn
        }
      ],
      var.topic_policy_statements
    )
  })
}

# ------------------------------------------------------------------------------
# SNS TOPIC SUBSCRIPTIONS
# ------------------------------------------------------------------------------
resource "aws_sns_topic_subscription" "main" {
  for_each = var.create_topic ? var.subscriptions : {}

  topic_arn = aws_sns_topic.main[0].arn
  protocol  = each.value.protocol
  endpoint  = each.value.endpoint

  filter_policy          = try(each.value.filter_policy, null)
  raw_message_delivery   = try(each.value.raw_message_delivery, null)
  delivery_policy        = try(each.value.delivery_policy, null)
  redrive_policy         = try(each.value.redrive_policy, null)
  replay_policy          = try(each.value.replay_policy, null)
  subscription_role_arn  = try(each.value.subscription_role_arn, null)
}

# ------------------------------------------------------------------------------
# OUTPUTS
# ------------------------------------------------------------------------------
output "topic_arn" {
  description = "ARN of the created SNS topic"
  value       = try(aws_sns_topic.main[0].arn, null)
}

output "topic_name" {
  description = "Name of the created SNS topic"
  value       = try(aws_sns_topic.main[0].name, null)
}

output "delivery_feedback_role_arn" {
  description = "ARN of the IAM role used for delivery feedback logging"
  value       = try(aws_iam_role.delivery_feedback[0].arn, null)
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

resource "aws_vpc" "ansible_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "ansible-vpc"
  }
}

resource "aws_subnet" "ansible_vpc_private_subnet_1" {
  vpc_id                  = aws_vpc.ansible_vpc.id
  cidr_block              = "10.0.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "ansible-vpc-private-subnet-1"
  }
}

resource "aws_subnet" "ansible_vpc_public_subnet_1" {
  vpc_id                  = aws_vpc.ansible_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "ansible-vpc-public-subnet-1"
  }
}

resource "aws_internet_gateway" "ansible_vpc_igw" {
  vpc_id = aws_vpc.ansible_vpc.id

  tags = {
    Name = "ansible-vpc-igw"
  }
}

resource "aws_route_table" "ansible_vpc_public_rt" {
  vpc_id = aws_vpc.ansible_vpc.id

  tags = {
    Name = "ansible-vpc-public-rt"
  }
}

resource "aws_route" "ansible_vpc_public_route" {
  route_table_id         = aws_route_table.ansible_vpc_public_rt.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.ansible_vpc_igw.id
}

resource "aws_route_table_association" "ansible_vpc_public_rta" {
  subnet_id      = aws_subnet.ansible_vpc_public_subnet_1.id
  route_table_id = aws_route_table.ansible_vpc_public_rt.id
}

resource "aws_route_table" "ansible_vpc_private_rt" {
  vpc_id = aws_vpc.ansible_vpc.id

  tags = {
    Name = "ansible-vpc-private-rt"
  }
}

resource "aws_route_table_association" "ansible_vpc_private_rta" {
  subnet_id      = aws_subnet.ansible_vpc_private_subnet_1.id
  route_table_id = aws_route_table.ansible_vpc_private_rt.id
}

# VPC Flow Logs
resource "aws_cloudwatch_log_group" "ansible_vpc_flow_logs" {
  name              = "ansible-vpc-flow-logs"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.ansible_vpc_flow_logs_key_alias.arn
}

resource "aws_kms_key" "ansible_vpc_flow_logs_key" {
  description         = "KMS key for CloudWatch Logs encryption"
  enable_key_rotation = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Enable CloudWatch Logs service"
        Effect = "Allow"
        Principal = {
          Service = "logs.us-east-1.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "ansible-vpc-flow-logs-key"
  }
}

resource "aws_kms_alias" "ansible_vpc_flow_logs_key_alias" {
  name          = "alias/ansible-vpc-flow-logs"
  target_key_id = aws_kms_key.ansible_vpc_flow_logs_key.key_id
}

resource "aws_iam_role" "flow_logs_role" {
  name = "ansible-vpc-flow-logs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "flow_logs_policy" {
  name = "ansible-vpc-flow-logs-policy"
  role = aws_iam_role.flow_logs_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = aws_cloudwatch_log_group.ansible_vpc_flow_logs.arn
      }
    ]
  })
}

resource "aws_flow_log" "ansible_vpc_flow_logs" {
  log_destination      = aws_cloudwatch_log_group.ansible_vpc_flow_logs.arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.flow_logs_role.arn
  vpc_id               = aws_vpc.ansible_vpc.id
  traffic_type         = "REJECT"
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 6.0"
    }
  }
}

variable "vpcs" {
  description = "Map of VPCs to attach to the Transit Gateway. Each VPC defines a CIDR block and subnet CIDRs spread across Availability Zones."
  type = map(object({
    cidr_block             = string
    subnet_cidrs           = list(string)
    destination_cidr_block = optional(string, "0.0.0.0/0")
    tags                   = optional(map(string), {})
  }))
  default = {
    vpc-alpha = {
      cidr_block   = "10.0.0.0/16"
      subnet_cidrs = ["10.0.1.0/24", "10.0.2.0/24"]
      tags         = { Name = "vpc-alpha" }
    }
  }
  validation {
    condition     = length(var.vpcs) > 0
    error_message = "At least one VPC must be defined."
  }
  validation {
    condition = alltrue([
      for vpc in var.vpcs : length(vpc.subnet_cidrs) >= 2
    ])
    error_message = "Each VPC must define at least two subnet CIDRs to span multiple Availability Zones."
  }
}

variable "tags" {
  description = "Common tags applied to all resources."
  type        = map(string)
  default     = {}
}

variable "transit_gateway_name" {
  description = "Name tag for the Transit Gateway."
  type        = string
  default     = "central-tgw"
}

variable "create_custom_transit_gateway_route_table" {
  description = "Set to true to create a custom Transit Gateway route table and associate/propagate all VPC attachments to it instead of using the default route table."
  type        = bool
  default     = false
}

variable "ram_share_name" {
  description = "Name of the RAM resource share when sharing the Transit Gateway."
  type        = string
  default     = "central-tgw-share"
}

variable "ram_share_principals" {
  description = "AWS account IDs or principals to share the Transit Gateway with via RAM. Leave empty to skip sharing."
  type        = list(string)
  default     = []
}

variable "ram_allow_external_principals" {
  description = "Allow external principals in the RAM resource share."
  type        = bool
  default     = false
}

variable "flow_logs_retention_days" {
  description = "CloudWatch Logs retention period for VPC Flow Logs."
  type        = number
  default     = 30
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

locals {
  subnet_list = flatten([
    for vpc_key, vpc in var.vpcs : [
      for index, cidr_block in vpc.subnet_cidrs : {
        key               = "${vpc_key}-${index}"
        vpc_key           = vpc_key
        subnet_index      = index
        cidr_block        = cidr_block
        availability_zone = data.aws_availability_zones.available.names[index % length(data.aws_availability_zones.available.names)]
      }
    ]
  ])

  subnet_map = {
    for subnet in local.subnet_list : subnet.key => subnet
  }

  ram_principals = distinct(var.ram_share_principals)
}

resource "aws_ec2_transit_gateway" "this" {
  description                     = "Central Transit Gateway for inter-VPC routing"
  default_route_table_association = var.create_custom_transit_gateway_route_table ? "disable" : "enable"
  default_route_table_propagation = var.create_custom_transit_gateway_route_table ? "disable" : "enable"
  tags                            = merge(var.tags, { Name = var.transit_gateway_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_vpc" "this" {
  for_each = var.vpcs

  cidr_block           = each.value.cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags                 = merge(var.tags, lookup(each.value, "tags", {}), { Name = each.key })
}

resource "aws_subnet" "this" {
  for_each = local.subnet_map

  vpc_id                  = aws_vpc.this[each.value.vpc_key].id
  cidr_block              = each.value.cidr_block
  availability_zone       = each.value.availability_zone
  map_public_ip_on_launch = false

  tags = merge(var.tags, lookup(var.vpcs[each.value.vpc_key], "tags", {}), { Name = "${each.value.vpc_key}-subnet-${each.value.subnet_index}" })
}

resource "aws_ec2_transit_gateway_vpc_attachment" "this" {
  for_each = var.vpcs

  transit_gateway_id = aws_ec2_transit_gateway.this.id
  vpc_id             = aws_vpc.this[each.key].id
  subnet_ids = [
    for key in sort(keys(local.subnet_map)) :
    aws_subnet.this[key].id
    if local.subnet_map[key].vpc_key == each.key
  ]

  tags = merge(var.tags, lookup(each.value, "tags", {}), { Name = "${each.key}-tgw-attachment" })
}

resource "aws_route" "to_tgw" {
  for_each = var.vpcs

  route_table_id         = aws_vpc.this[each.key].default_route_table_id
  destination_cidr_block = coalesce(lookup(each.value, "destination_cidr_block", null), "0.0.0.0/0")
  transit_gateway_id     = aws_ec2_transit_gateway.this.id

  depends_on = [aws_ec2_transit_gateway_vpc_attachment.this]
}

resource "aws_ec2_transit_gateway_route_table" "this" {
  count = var.create_custom_transit_gateway_route_table ? 1 : 0

  transit_gateway_id = aws_ec2_transit_gateway.this.id
  tags               = merge(var.tags, { Name = "${var.transit_gateway_name}-custom" })
}

resource "aws_ec2_transit_gateway_route_table_association" "this" {
  for_each = var.create_custom_transit_gateway_route_table ? var.vpcs : {}

  transit_gateway_route_table_id = one(aws_ec2_transit_gateway_route_table.this[*].id)
  transit_gateway_attachment_id  = aws_ec2_transit_gateway_vpc_attachment.this[each.key].id
}

resource "aws_ec2_transit_gateway_route_table_propagation" "this" {
  for_each = var.create_custom_transit_gateway_route_table ? var.vpcs : {}

  transit_gateway_route_table_id = one(aws_ec2_transit_gateway_route_table.this[*].id)
  transit_gateway_attachment_id  = aws_ec2_transit_gateway_vpc_attachment.this[each.key].id
}

resource "aws_kms_key" "flow_logs" {
  description             = "KMS key for VPC Flow Logs CloudWatch Log Groups"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "vpc-flow-logs-kms-key"
    Statement = [
      {
        Sid       = "Enable IAM User Permissions"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "Allow CloudWatch Logs to use the key"
        Effect    = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(var.tags, { Name = "vpc-flow-logs-kms-key" })
}

resource "aws_kms_alias" "flow_logs" {
  name          = "alias/vpc-flow-logs"
  target_key_id = aws_kms_key.flow_logs.key_id
}

resource "aws_cloudwatch_log_group" "flow_logs" {
  for_each = var.vpcs

  name              = "/aws/vpc-flow-logs/${each.key}"
  retention_in_days = var.flow_logs_retention_days
  kms_key_id        = aws_kms_key.flow_logs.arn
  tags              = merge(var.tags, { Name = "/aws/vpc-flow-logs/${each.key}" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "flow_logs" {
  name = "vpc-flow-logs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(var.tags, { Name = "vpc-flow-logs-role" })
}

resource "aws_iam_role_policy" "flow_logs" {
  name = "vpc-flow-logs-policy"
  role = aws_iam_role.flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = [
          for arn in values(aws_cloudwatch_log_group.flow_logs)[*].arn : "${arn}:*"
        ]
      }
    ]
  })
}

resource "aws_flow_log" "this" {
  for_each = var.vpcs

  vpc_id               = aws_vpc.this[each.key].id
  traffic_type         = "ALL"
  log_destination      = aws_cloudwatch_log_group.flow_logs[each.key].arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.flow_logs.arn
  tags                 = merge(var.tags, lookup(each.value, "tags", {}), { Name = "${each.key}-flow-log" })
}

resource "aws_ram_resource_share" "this" {
  count = length(local.ram_principals) > 0 ? 1 : 0

  name                      = var.ram_share_name
  allow_external_principals = var.ram_allow_external_principals
  tags                      = merge(var.tags, { Name = var.ram_share_name })
}

resource "aws_ram_resource_association" "this" {
  count = length(local.ram_principals) > 0 ? 1 : 0

  resource_share_arn = one(aws_ram_resource_share.this[*].arn)
  resource_arn       = aws_ec2_transit_gateway.this.arn
}

resource "aws_ram_principal_association" "this" {
  count = length(local.ram_principals)

  resource_share_arn = one(aws_ram_resource_share.this[*].arn)
  principal          = local.ram_principals[count.index]
}

terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "tags" {
  description = "Tags to apply to resources"
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = var.tags
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = var.tags
}

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = var.tags
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = var.tags
}

resource "aws_route_table_association" "main" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.main.id
}

resource "aws_security_group" "ecs_fargate_sg" {
  name        = "dragondrop-compute-ecs-fargate-sg"
  description = "Security group for ECS Fargate compute tasks"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Outbound traffic within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = var.tags
}

resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for CloudWatch log group encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "cloudwatch-logs-key-policy"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "kms:CancelKeyDeletion",
          "kms:DescribeKey",
          "kms:EnableKeyRotation",
          "kms:GetKeyPolicy",
          "kms:GetKeyRotationStatus",
          "kms:ListResourceTags",
          "kms:PutKeyPolicy",
          "kms:ScheduleKeyDeletion",
          "kms:TagResource",
          "kms:UntagResource"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Decrypt*",
          "kms:DescribeKey",
          "kms:Encrypt*",
          "kms:GenerateDataKey*",
          "kms:ReEncrypt*"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow KMS Alias Management for Terraform User"
        Effect = "Allow"
        Principal = {
          AWS = data.aws_caller_identity.current.arn
        }
        Action = [
          "kms:CreateAlias",
          "kms:DeleteAlias",
          "kms:UpdateAlias"
        ]
        Resource = "*"
      }
    ]
  })

  tags = var.tags
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/cloudwatch-logs"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

resource "aws_cloudwatch_log_group" "flow_log" {
  name              = "/aws/vpc/flow-logs"
  retention_in_days = 14
  kms_key_id        = aws_kms_alias.cloudwatch.arn

  depends_on = [
    aws_kms_key.cloudwatch,
    aws_kms_alias.cloudwatch
  ]

  tags = var.tags
}

resource "aws_iam_role" "flow_log" {
  name = "vpc-flow-logs-to-cloudwatch"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "flow_log" {
  name = "vpc-flow-logs-to-cloudwatch"
  role = aws_iam_role.flow_log.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.flow_log.arn,
          "${aws_cloudwatch_log_group.flow_log.arn}:log-stream:*"
        ]
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  iam_role_arn         = aws_iam_role.flow_log.arn
  log_destination      = aws_cloudwatch_log_group.flow_log.arn
  log_destination_type = "cloud-watch-logs"
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.main.id

  tags = var.tags

  depends_on = [
    aws_iam_role_policy.flow_log
  ]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

resource "aws_kms_key" "dynamodb_encryption" {
  description          = "KMS key for DynamoDB encryption"
  enable_key_rotation  = true
}

resource "aws_dynamodb_table" "raw_metrics" {
  name         = "raw_metrics"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "uuid"

  attribute {
    name = "uuid"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.dynamodb_encryption.arn
  }

  stream_enabled   = true
  stream_view_type = "NEW_IMAGE"

  ttl {
    enabled        = true
    attribute_name = "expdate"
  }

  point_in_time_recovery {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "aggregate_metrics" {
  name         = "aggregate_metrics"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "pk"
  range_key    = "sk"

  attribute {
    name = "pk"
    type = "S"
  }

  attribute {
    name = "sk"
    type = "S"
  }

  attribute {
    name = "identifier"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.dynamodb_encryption.arn
  }

  point_in_time_recovery {
    enabled = true
  }

  global_secondary_index {
    name            = "IdentifierIndex"
    hash_key        = "identifier"
    projection_type = "ALL"
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "instance_type" {
  description = "EC2 instance size"
  type        = string
  default     = "t3.micro"
}

variable "server_name" {
  description = "Name of the server"
  type        = string
  default     = "demo"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.server_name}-vpc"
  }
}

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.server_name}-subnet"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.server_name}-igw"
  }
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.server_name}-rt"
  }
}

resource "aws_route" "internet_access" {
  route_table_id         = aws_route_table.main.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "main" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.main.id
}

resource "aws_security_group" "web" {
  name        = "${var.server_name}-sg"
  description = "Allow HTTP inbound and restrict egress to VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Only to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.server_name}-sg"
  }
}

resource "aws_kms_key" "ebs" {
  description             = "KMS key for EC2 root volume encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "ebs-key-policy"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "${var.server_name}-ebs-kms"
  }
}

resource "aws_instance" "web" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.main.id
  vpc_security_group_ids      = [aws_security_group.web.id]
  associate_public_ip_address = false
  user_data                   = <<-EOF
#!/bin/bash
sudo yum update -y
sudo yum install -y httpd
sudo systemctl enable httpd
sudo systemctl start httpd
sudo hostnamectl set-hostname ${var.server_name}
EOF

  metadata_options {
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  root_block_device {
    encrypted = true
    kms_key_id = aws_kms_key.ebs.arn
  }

  tags = {
    Name = var.server_name
  }
}

resource "aws_eip" "demo" {
  domain = "vpc"

  tags = {
    Name = "${var.server_name}-eip"
  }
}

resource "aws_eip_association" "demo" {
  instance_id   = aws_instance.web.id
  allocation_id = aws_eip.demo.id
}

resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for VPC flow log encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "flow-log-key-policy"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "${var.server_name}-cloudwatch-kms"
  }
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/${var.server_name}-cloudwatch-logs"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

resource "aws_cloudwatch_log_group" "flow_log" {
  name              = "/aws/vpc/flow-logs/${var.server_name}"
  retention_in_days = 14
  kms_key_id        = aws_kms_alias.cloudwatch.arn

  tags = {
    Name = "${var.server_name}-flow-log-group"
  }
}

resource "aws_iam_role" "flow_log" {
  name = "${var.server_name}-flow-log-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${var.server_name}-flow-log-role"
  }
}

resource "aws_iam_policy" "flow_log" {
  name = "${var.server_name}-flow-log-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.flow_log.arn,
          "${aws_cloudwatch_log_group.flow_log.arn}:log-stream:*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "flow_log" {
  role       = aws_iam_role.flow_log.name
  policy_arn = aws_iam_policy.flow_log.arn
}

resource "aws_flow_log" "example" {
  vpc_id               = aws_vpc.main.id
  log_destination      = aws_cloudwatch_log_group.flow_log.arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.flow_log.arn
  traffic_type         = "ALL"

  tags = {
    Name = "${var.server_name}-flow-log"
  }

  depends_on = [aws_iam_role_policy_attachment.flow_log]
}

output "public_ip" {
  description = "Public IP address of the web server"
  value       = aws_eip.demo.public_ip
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# KMS Key for SNS encryption
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "EnableRootAccountPermissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowSNSServiceToUseKey"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey*",
      "kms:ReEncrypt*"
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key" "sns" {
  description             = "Customer-managed KMS key for SNS topics"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
  tags = {
    Environment = "testing"
    Purpose     = "SNS integration testing"
  }
}

resource "aws_kms_alias" "sns" {
  name          = "alias/sns-key"
  target_key_id = aws_kms_key.sns.key_id
}

# ------------------------------------------------------------------------------
# SNS Topics
# ------------------------------------------------------------------------------
resource "aws_sns_topic" "topic_with_policy" {
  name              = "my-topic-with-policy"
  kms_master_key_id = aws_kms_alias.sns.arn
  tags = {
    Environment = "testing"
    Purpose     = "SNS integration testing"
  }
}

resource "aws_sns_topic" "topic_with_policy2" {
  name              = "my-topic-with-policy2"
  kms_master_key_id = aws_kms_alias.sns.arn
  tags = {
    Environment = "testing"
    Purpose     = "SNS integration testing"
  }
}

resource "aws_sns_topic" "user_updates_topic" {
  name              = "user-updates-topic"
  kms_master_key_id = aws_kms_alias.sns.arn
  delivery_policy   = jsonencode({
    http = {
      defaultHealthyRetryPolicy = {
        minDelayTarget     = 20
        maxDelayTarget     = 300
        numRetries         = 10
        numMaxDelayRetries = 0
        numNoDelayRetries  = 0
        numMinDelayRetries = 0
        backoffFunction    = "linear"
      }
      defaultThrottlePolicy = {
        maxReceivesPerSecond = 5
      }
    }
  })
  tags = {
    Environment = "testing"
    Purpose     = "SNS integration testing"
  }
}

# ------------------------------------------------------------------------------
# IAM Policy Document and Policy Attachment for the first topic
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "sns_open_policy" {
  statement {
    sid    = "AllowAllPrincipalsFullSNSAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    actions = [
      "SNS:GetTopicAttributes",
      "SNS:SetTopicAttributes",
      "SNS:AddPermission",
      "SNS:RemovePermission",
      "SNS:DeleteTopic",
      "SNS:Subscribe",
      "SNS:ListSubscriptionsByTopic",
      "SNS:Publish",
      "SNS:Receive",
    ]
    resources = [aws_sns_topic.topic_with_policy.arn]
  }
}

resource "aws_sns_topic_policy" "topic_with_policy" {
  arn    = aws_sns_topic.topic_with_policy.arn
  policy = data.aws_iam_policy_document.sns_open_policy.json
}

