  retention_in_days = 30
  kms_key_id        = aws_kms_key.flow_log.arn

  tags = {
    Name        = "custom-test-vpc-flow-logs"
    Environment = local.environment
  }
}

resource "aws_iam_role" "flow_log" {
  name = "custom-test-vpc-flow-log-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name        = "custom-test-vpc-flow-log-role"
    Environment = local.environment
  }
}

resource "aws_iam_role_policy" "flow_log" {
  name = "custom-test-vpc-flow-log-policy"
  role = aws_iam_role.flow_log.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = aws_cloudwatch_log_group.flow_log.arn
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.flow_log.arn}:*"
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.flow_log.arn
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  log_destination      = aws_cloudwatch_log_group.flow_log.arn
  log_destination_type = "cloud-watch-logs"
  traffic_type         = "REJECT"
  vpc_id               = aws_vpc.main.id
  iam_role_arn         = aws_iam_role.flow_log.arn

  tags = {
    Name        = "custom-test-vpc-flow-log"
    Environment = local.environment
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

locals {
  api_gateway_log_group_base_arn = trimsuffix(aws_cloudwatch_log_group.api_gateway_event_api.arn, ":*")
}

resource "aws_kms_key" "event_topic_sns" {
  description             = "KMS key for encrypting the event-topic SNS topic"
  enable_key_rotation     = true
  is_enabled              = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableRootAdmin"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "AllowSnsServiceToUseKey"
        Effect    = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:Encrypt"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "event_topic_sns" {
  name_prefix   = "alias/event-topic-sns-"
  target_key_id = aws_kms_key.event_topic_sns.key_id
}

resource "aws_kms_key" "cloudwatch_logs" {
  description             = "KMS key for encrypting the API Gateway event-api access log group"
  enable_key_rotation     = true
  is_enabled              = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableRootAdmin"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "AllowCloudWatchLogsToUseKey"
        Effect    = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "cloudwatch_logs" {
  name_prefix   = "alias/cloudwatch-logs-api-gateway-"
  target_key_id = aws_kms_key.cloudwatch_logs.key_id
}

resource "aws_sns_topic" "event_topic" {
  name              = "event-topic"
  kms_master_key_id = aws_kms_key.event_topic_sns.key_id

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "api_gateway_sns_publish" {
  name_prefix = "api-gateway-sns-publish-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "api_gateway_sns_publish" {
  name_prefix = "api-gateway-sns-publish-policy-"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowSnsPublish"
        Effect   = "Allow"
        Action   = ["sns:Publish"]
        Resource = [aws_sns_topic.event_topic.arn]
      },
      {
        Sid      = "AllowKmsDecryptAndGenerateDataKey"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = [aws_kms_key.event_topic_sns.arn]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "api_gateway_sns_publish" {
  role       = aws_iam_role.api_gateway_sns_publish.name
  policy_arn = aws_iam_policy.api_gateway_sns_publish.arn
}

resource "aws_cloudwatch_log_group" "api_gateway_event_api" {
  name_prefix       = "api-gateway-event-api-v1-"
  retention_in_days = 7
  kms_key_id        = aws_kms_key.cloudwatch_logs.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "api_gateway_cloudwatch_xray" {
  name_prefix = "api-gateway-cloudwatch-xray-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "api_gateway_cloudwatch_xray" {
  name_prefix = "api-gateway-cloudwatch-xray-policy-"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowAPIGatewayCloudWatchLogs"
        Effect   = "Allow"
        Action   = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents",
          "logs:GetLogEvents",
          "logs:FilterLogEvents"
        ]
        Resource = "*"
      },
      {
        Sid      = "AllowAPIGatewayXRay"
        Effect   = "Allow"
        Action   = [
          "xray:PutTraceSegments",
          "xray:PutTelemetryRecords"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "api_gateway_cloudwatch_xray" {
  role       = aws_iam_role.api_gateway_cloudwatch_xray.name
  policy_arn = aws_iam_policy.api_gateway_cloudwatch_xray.arn
}

resource "aws_api_gateway_account" "api_gateway" {
  cloudwatch_role_arn = aws_iam_role.api_gateway_cloudwatch_xray.arn

  depends_on = [
    aws_iam_role_policy_attachment.api_gateway_cloudwatch_xray
  ]
}

resource "aws_api_gateway_rest_api" "event_api" {
  name        = "event-api"
  description = "API Gateway that forwards POST requests to the SNS event-topic"

  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

resource "aws_api_gateway_resource" "publish" {
  rest_api_id = aws_api_gateway_rest_api.event_api.id
  parent_id   = aws_api_gateway_rest_api.event_api.root_resource_id
  path_part   = "publish"
}

resource "aws_api_gateway_method" "publish_post" {
  rest_api_id      = aws_api_gateway_rest_api.event_api.id
  resource_id      = aws_api_gateway_resource.publish.id
  http_method      = "POST"
  authorization    = "AWS_IAM"
  api_key_required = false
  request_models   = {}
}

resource "aws_api_gateway_integration" "sns_publish" {
  rest_api_id             = aws_api_gateway_rest_api.event_api.id
  resource_id             = aws_api_gateway_resource.publish.id
  http_method             = aws_api_gateway_method.publish_post.http_method
  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = "arn:aws:apigateway:${data.aws_region.current.name}:sns:action/Publish"
  credentials             = aws_iam_role.api_gateway_sns_publish.arn
  passthrough_behavior    = "NEVER"

  request_templates = {
    "application/json" = "Action=Publish&TopicArn=$util.urlEncode('${aws_sns_topic.event_topic.arn}')&Message=$util.urlEncode($input.body)"
  }
}

resource "aws_api_gateway_method_response" "publish_post_200" {
  rest_api_id = aws_api_gateway_rest_api.event_api.id
  resource_id = aws_api_gateway_resource.publish.id
  http_method = aws_api_gateway_method.publish_post.http_method
  status_code = "200"
}

resource "aws_api_gateway_integration_response" "sns_publish_200" {
  rest_api_id       = aws_api_gateway_rest_api.event_api.id
  resource_id       = aws_api_gateway_resource.publish.id
  http_method       = aws_api_gateway_method.publish_post.http_method
  status_code       = aws_api_gateway_method_response.publish_post_200.status_code
  selection_pattern = "^2\\d\\d"

  depends_on = [
    aws_api_gateway_integration.sns_publish
  ]
}

resource "aws_api_gateway_deployment" "event_api" {
  depends_on = [
    aws_api_gateway_method.publish_post,
    aws_api_gateway_integration.sns_publish,
    aws_api_gateway_method_response.publish_post_200,
    aws_api_gateway_integration_response.sns_publish_200
  ]

  rest_api_id = aws_api_gateway_rest_api.event_api.id

  triggers = {
    redeployment = sha1(jsonencode({
      method_id               = aws_api_gateway_method.publish_post.id
      authorization           = aws_api_gateway_method.publish_post.authorization
      integration_id          = aws_api_gateway_integration.sns_publish.id
      method_response_id      = aws_api_gateway_method_response.publish_post_200.id
      integration_response_id = aws_api_gateway_integration_response.sns_publish_200.id
    }))
  }
}

resource "aws_api_gateway_stage" "v1" {
  stage_name           = "v1"
  rest_api_id          = aws_api_gateway_rest_api.event_api.id
  deployment_id        = aws_api_gateway_deployment.event_api.id
  xray_tracing_enabled = true

  access_log_settings {
    destination_arn = local.api_gateway_log_group_base_arn
    format = jsonencode({
      requestId                = "$context.requestId"
      requestTime              = "$context.requestTime"
      httpMethod               = "$context.httpMethod"
      resourcePath             = "$context.resourcePath"
      status                   = "$context.status"
      integrationErrorMessage = "$context.integrationErrorMessage"
    })
  }

  depends_on = [
    aws_api_gateway_account.api_gateway
  ]
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "terraform-aws-vpc"
  }
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "terraform-aws-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# KMS key for CloudWatch Logs encryption
resource "aws_kms_key" "flow_log" {
  description             = "KMS key for VPC Flow Logs CloudWatch Log Group"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "flow_log" {
  name          = "alias/terraform-aws-vpc-flow-logs"
  target_key_id = aws_kms_key.flow_log.key_id
}

# VPC Flow Logs resources
resource "aws_cloudwatch_log_group" "flow_log" {
  name              = "/aws/vpc/terraform-aws-vpc-flow-logs"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.flow_log.arn
}

resource "aws_iam_role" "flow_log" {
  name = "terraform-aws-vpc-flow-log-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "flow_log" {
  name = "terraform-aws-vpc-flow-log-policy"
  role = aws_iam_role.flow_log.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          aws_cloudwatch_log_group.flow_log.arn,
          "${aws_cloudwatch_log_group.flow_log.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
  log_destination      = aws_cloudwatch_log_group.flow_log.arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.flow_log.arn
}

