# KMS key for flow log bucket encryption
resource "aws_kms_key" "flow_logs" {
  description             = "KMS key for VPC flow log bucket encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "ntier-flow-log-key"
  }
}

# S3 bucket for VPC Flow Logs
resource "aws_s3_bucket" "flow_logs" {
  bucket_prefix = "ntier-vpc-flow-logs-"

  tags = {
    Name = "ntier-vpc-flow-logs"
  }
}

resource "aws_s3_bucket_public_access_block" "flow_logs" {
  bucket = aws_s3_bucket.flow_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "flow_logs" {
  bucket = aws_s3_bucket.flow_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.flow_logs.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "flow_logs" {
  bucket = aws_s3_bucket.flow_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Logging destination bucket for flow log bucket access logs
resource "aws_s3_bucket" "flow_logs_logging" {
  bucket_prefix = "ntier-vpc-flow-logs-logging-"

  tags = {
    Name = "ntier-vpc-flow-logs-logging"
  }
}

resource "aws_s3_bucket_ownership_controls" "flow_logs_logging" {
  bucket = aws_s3_bucket.flow_logs_logging.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "flow_logs_logging" {
  bucket = aws_s3_bucket.flow_logs_logging.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_acl" "flow_logs_logging" {
  bucket = aws_s3_bucket.flow_logs_logging.id
  acl    = "log-delivery-write"

  depends_on = [aws_s3_bucket_ownership_controls.flow_logs_logging]
}

resource "aws_s3_bucket_versioning" "flow_logs_logging" {
  bucket = aws_s3_bucket.flow_logs_logging.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "flow_logs_logging" {
  bucket = aws_s3_bucket.flow_logs_logging.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_logging" "flow_logs" {
  bucket = aws_s3_bucket.flow_logs.id

  target_bucket = aws_s3_bucket.flow_logs_logging.id
  target_prefix = "access-logs/"
}

# VPC Flow Logs
resource "aws_flow_log" "main" {
  log_destination      = aws_s3_bucket.flow_logs.arn
  log_destination_type = "s3"
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.main.id

  tags = {
    Name = "ntier-vpc-flow-log"
  }
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "create_kms_key" {
  description = "Set to true to create a standard customer-managed KMS key with AWS-provided key material."
  type        = bool
  default     = true
}

variable "create_external_key" {
  description = "Set to true to create an external KMS key with imported key material."
  type        = bool
  default     = false
}

variable "create_replica_key" {
  description = "Set to true to create a multi-Region replica KMS key from a primary key ARN."
  type        = bool
  default     = false
}

variable "create_replica_external_key" {
  description = "Set to true to create a multi-Region replica external KMS key from a primary external key ARN."
  type        = bool
  default     = false
}

variable "key_material_base64" {
  description = "Base64-encoded 256-bit symmetric key material to import into an external KMS key or replica external KMS key."
  type        = string
  default     = null
  sensitive   = true
}

variable "primary_key_arn" {
  description = "ARN of the primary multi-Region KMS key. Required when create_replica_key is true."
  type        = string
  default     = null
}

variable "primary_external_key_arn" {
  description = "ARN of the primary multi-Region external KMS key. Required when create_replica_external_key is true."
  type        = string
  default     = null
}

variable "description" {
  description = "Description of the KMS key."
  type        = string
  default     = "KMS key managed by Terraform"
}

variable "key_usage" {
  description = "Intended use of the KMS key."
  type        = string
  default     = "ENCRYPT_DECRYPT"

  validation {
    condition     = contains(["ENCRYPT_DECRYPT", "SIGN_VERIFY", "GENERATE_VERIFY_MAC"], var.key_usage)
    error_message = "key_usage must be one of ENCRYPT_DECRYPT, SIGN_VERIFY, or GENERATE_VERIFY_MAC."
  }
}

variable "customer_master_key_spec" {
  description = "Specifies the KMS key specification for a standard KMS key."
  type        = string
  default     = "SYMMETRIC_DEFAULT"
}

variable "multi_region" {
  description = "Indicates whether the standard or external KMS key is a multi-Region primary key."
  type        = bool
  default     = false
}

variable "is_enabled" {
  description = "Specifies whether the KMS key is enabled."
  type        = bool
  default     = true
}

variable "enable_key_rotation" {
  description = "Specifies whether automatic key rotation is enabled. Only valid for symmetric KMS keys with AWS-provided key material."
  type        = bool
  default     = true
}

variable "deletion_window_in_days" {
  description = "Waiting period before KMS deletes the key."
  type        = number
  default     = 30

  validation {
    condition     = var.deletion_window_in_days >= 7 && var.deletion_window_in_days <= 30
    error_message = "deletion_window_in_days must be between 7 and 30."
  }
}

variable "tags" {
  description = "Tags to apply to all KMS resources."
  type        = map(string)
  default     = {}
}

variable "key_owners" {
  description = "IAM role ARNs permitted to administer and own the KMS key."
  type        = list(string)
  default     = []
}

variable "key_administrators" {
  description = "IAM role ARNs permitted to administer the KMS key."
  type        = list(string)
  default     = []
}

variable "key_users" {
  description = "IAM role ARNs permitted to use the KMS key for standard cryptographic operations."
  type        = list(string)
  default     = []
}

variable "service_users" {
  description = "AWS service principals permitted to use the KMS key for standard cryptographic operations."
  type        = list(string)
  default     = []
}

variable "autoscaling_role_arns" {
  description = "IAM role ARNs used by EC2 Auto Scaling to use the KMS key."
  type        = list(string)
  default     = []
}

variable "symmetric_users" {
  description = "IAM role ARNs permitted to perform symmetric encryption and data key operations."
  type        = list(string)
  default     = []
}

variable "hmac_users" {
  description = "IAM role ARNs permitted to generate and verify MACs with an HMAC KMS key."
  type        = list(string)
  default     = []
}

variable "asymmetric_public_encryption_users" {
  description = "IAM role ARNs permitted to encrypt and decrypt with an asymmetric public encryption KMS key."
  type        = list(string)
  default     = []
}

variable "asymmetric_sign_verify_users" {
  description = "IAM role ARNs permitted to sign and verify with an asymmetric signing KMS key."
  type        = list(string)
  default     = []
}

variable "enable_route53_dnssec" {
  description = "Set to true to add a Route 53 DNSSEC signing statement to the KMS key policy."
  type        = bool
  default     = false
}

variable "policy_statements" {
  description = "List of JSON IAM policy statement objects to append to the generated KMS key policy."
  type        = list(string)
  default     = []

  validation {
    condition     = alltrue([for statement in var.policy_statements : can(jsondecode(statement))])
    error_message = "Every entry in policy_statements must be valid JSON."
  }
}

variable "override_policy_document" {
  description = "A complete valid JSON KMS key policy document. When provided, it replaces the entire generated policy."
  type        = string
  default     = null

  validation {
    condition     = var.override_policy_document == null || can(jsondecode(var.override_policy_document))
    error_message = "override_policy_document must be valid JSON."
  }
}

variable "aliases" {
  description = "List of KMS aliases to create. Each entry must set exactly one of name or name_prefix."
  type = list(object({
    name        = optional(string)
    name_prefix = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for alias in var.aliases :
      (alias.name == null || startswith(alias.name, "alias/")) &&
      (alias.name_prefix == null || startswith(alias.name_prefix, "alias/"))
    ])
    error_message = "Alias names and name prefixes must begin with 'alias/'."
  }

  validation {
    condition = alltrue([
      for alias in var.aliases :
      (alias.name != null) != (alias.name_prefix != null)
    ])
    error_message = "Each alias must set exactly one of name or name_prefix."
  }
}

variable "grants" {
  description = "List of KMS grants to create."
  type = list(object({
    grantee_principal         = string
    operations                = list(string)
    retiring_principal        = optional(string)
    encryption_context_subset = optional(map(string))
  }))
  default = []

  validation {
    condition = alltrue(flatten([
      for grant in var.grants : [
        for operation in grant.operations : contains([
          "Decrypt",
          "Encrypt",
          "GenerateDataKey",
          "GenerateDataKeyWithoutPlaintext",
          "GenerateDataKeyPair",
          "GenerateDataKeyPairWithoutPlaintext",
          "ReEncryptFrom",
          "ReEncryptTo",
          "Sign",
          "Verify",
          "GetPublicKey",
          "CreateGrant",
          "RetireGrant",
          "DescribeKey",
          "GenerateMac",
          "VerifyMac",
        ], operation)
      ]
    ]))
    error_message = "grants contains an unsupported KMS grant operation."
  }

  validation {
    condition     = alltrue([for grant in var.grants : grant.grantee_principal != ""])
    error_message = "Each grant must specify a non-empty grantee_principal."
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  admin_actions = [
    "kms:DescribeKey",
    "kms:EnableKey",
    "kms:DisableKey",
    "kms:PutKeyPolicy",
    "kms:GetKeyPolicy",
    "kms:ScheduleKeyDeletion",
    "kms:TagResource",
    "kms:UntagResource",
    "kms:CreateGrant",
    "kms:RevokeGrant",
  ]

  standard_user_actions = [
    "kms:DescribeKey",
    "kms:Encrypt",
    "kms:Decrypt",
    "kms:ReEncryptFrom",
    "kms:ReEncryptTo",
    "kms:GenerateDataKey",
    "kms:GenerateDataKeyWithoutPlaintext",
  ]

  symmetric_actions = [
    "kms:Encrypt",
    "kms:Decrypt",
    "kms:GenerateDataKey",
    "kms:GenerateDataKeyWithoutPlaintext",
    "kms:GenerateDataKeyPair",
    "kms:GenerateDataKeyPairWithoutPlaintext",
    "kms:ReEncryptFrom",
    "kms:ReEncryptTo",
  ]

  autoscaling_actions = [
    "kms:DescribeKey",
    "kms:Encrypt",
    "kms:Decrypt",
    "kms:GenerateDataKeyWithoutPlaintext",
    "kms:CreateGrant",
  ]

  key_policy_json = var.override_policy_document != null ? var.override_policy_document : data.aws_iam_policy_document.kms_key_policy.json

  key_id = one(concat(
    aws_kms_key.this[*].id,
    aws_kms_external_key.this[*].id,
    aws_kms_replica_key.this[*].id,
    aws_kms_replica_external_key.this[*].id,
  ))

  key_arn = one(concat(
    aws_kms_key.this[*].arn,
    aws_kms_external_key.this[*].arn,
    aws_kms_replica_key.this[*].arn,
    aws_kms_replica_external_key.this[*].arn,
  ))
}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "Enable IAM User Permissions"
    effect    = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  dynamic "statement" {
    for_each = length(var.key_owners) > 0 ? [1] : []
    content {
      sid    = "KeyOwnerPermissions"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.key_owners
      }
      actions   = local.admin_actions
      resources = ["*"]
    }
  }

  dynamic "statement" {
    for_each = length(var.key_administrators) > 0 ? [1] : []
    content {
      sid    = "KeyAdministratorPermissions"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.key_administrators
      }
      actions   = local.admin_actions
      resources = ["*"]
    }
  }

  dynamic "statement" {
    for_each = length(var.key_users) > 0 ? [1] : []
    content {
      sid    = "KeyUserPermissions"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.key_users
      }
      actions   = local.standard_user_actions
      resources = ["*"]
    }
  }

  dynamic "statement" {
    for_each = length(var.service_users) > 0 ? [1] : []
    content {
      sid    = "ServiceUserPermissions"
      effect = "Allow"
      principals {
        type        = "Service"
        identifiers = var.service_users
      }
      actions   = local.standard_user_actions
      resources = ["*"]
    }
  }

  dynamic "statement" {
    for_each = length(var.autoscaling_role_arns) > 0 ? [1] : []
    content {
      sid    = "EC2AutoScalingPermissions"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.autoscaling_role_arns
      }
      actions   = local.autoscaling_actions
      resources = ["*"]
    }
  }

  dynamic "statement" {
    for_each = length(var.symmetric_users) > 0 ? [1] : []
    content {
      sid    = "SymmetricUserPermissions"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.symmetric_users
      }
      actions   = local.symmetric_actions
      resources = ["*"]
    }
  }

  dynamic "statement" {
    for_each = length(var.hmac_users) > 0 ? [1] : []
    content {
      sid    = "HMACUserPermissions"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.hmac_users
      }
      actions   = ["kms:GenerateMac", "kms:VerifyMac"]
      resources = ["*"]
    }
  }

  dynamic "statement" {
    for_each = length(var.asymmetric_public_encryption_users) > 0 ? [1] : []
    content {
      sid    = "AsymmetricPublicEncryptionUserPermissions"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.asymmetric_public_encryption_users
      }
      actions   = ["kms:Encrypt", "kms:Decrypt"]
      resources = ["*"]
    }
  }

  dynamic "statement" {
    for_each = length(var.asymmetric_sign_verify_users) > 0 ? [1] : []
    content {
      sid    = "AsymmetricSignVerifyUserPermissions"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.asymmetric_sign_verify_users
      }
      actions   = ["kms:Sign", "kms:Verify"]
      resources = ["*"]
    }
  }

  dynamic "statement" {
    for_each = var.enable_route53_dnssec ? [1] : []
    content {
      sid    = "Route53DnssecSigning"
      effect = "Allow"
      principals {
        type        = "Service"
        identifiers = ["dnssec-route53.amazonaws.com"]
      }
      actions   = ["kms:DescribeKey", "kms:GetPublicKey", "kms:Sign"]
      resources = ["*"]
      condition {
        test     = "StringEquals"
        variable = "aws:SourceAccount"
        values   = [data.aws_caller_identity.current.account_id]
      }
    }
  }

  source_policy_documents = [
    for statement_json in var.policy_statements :
    jsonencode({
      Version   = "2012-10-17"
      Statement = jsondecode(statement_json)
    })
  ]
}

resource "terraform_data" "configuration_validation" {
  lifecycle {
    precondition {
      condition     = (var.create_kms_key ? 1 : 0) + (var.create_external_key ? 1 : 0) + (var.create_replica_key ? 1 : 0) + (var.create_replica_external_key ? 1 : 0) == 1
      error_message = "Exactly one of create_kms_key, create_external_key, create_replica_key, or create_replica_external_key must be true."
    }

    precondition {
      condition     = !var.create_replica_key || var.primary_key_arn != null
      error_message = "primary_key_arn is required when create_replica_key is true."
    }

    precondition {
      condition     = !var.create_replica_external_key || var.primary_external_key_arn != null
      error_message = "primary_external_key_arn is required when create_replica_external_key is true."
    }

    precondition {
      condition     = (!var.create_external_key && !var.create_replica_external_key) || var.key_material_base64 != null
      error_message = "key_material_base64 is required when create_external_key or create_replica_external_key is true."
    }

    precondition {
      condition     = (!var.create_external_key && !var.create_replica_external_key) || var.key_usage == "ENCRYPT_DECRYPT"
      error_message = "External KMS keys are always ENCRYPT_DECRYPT; set key_usage to ENCRYPT_DECRYPT."
    }

    precondition {
      condition     = !var.create_kms_key || !var.enable_key_rotation || (var.key_usage == "ENCRYPT_DECRYPT" && var.customer_master_key_spec == "SYMMETRIC_DEFAULT")
      error_message = "enable_key_rotation can only be true for symmetric KMS keys with AWS-provided key material."
    }
  }
}

resource "aws_kms_key" "this" {
  count                    = var.create_kms_key ? 1 : 0
  description              = var.description
  key_usage                = var.key_usage
  customer_master_key_spec = var.customer_master_key_spec
  multi_region             = var.multi_region
  is_enabled               = var.is_enabled
  enable_key_rotation      = var.enable_key_rotation
  deletion_window_in_days  = var.deletion_window_in_days
  policy                   = local.key_policy_json
  tags                     = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_external_key" "this" {
  count                   = var.create_external_key ? 1 : 0
  description             = var.description
  enabled                 = var.is_enabled
  multi_region            = var.multi_region
  key_material_base64     = var.key_material_base64
  deletion_window_in_days = var.deletion_window_in_days
  policy                  = local.key_policy_json
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_replica_key" "this" {
  count                   = var.create_replica_key ? 1 : 0
  description             = var.description
  enabled                 = var.is_enabled
  primary_key_arn         = var.primary_key_arn
  deletion_window_in_days = var.deletion_window_in_days
  policy                  = local.key_policy_json
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_replica_external_key" "this" {
  count                   = var.create_replica_external_key ? 1 : 0
  description             = var.description
  enabled                 = var.is_enabled
  primary_key_arn         = var.primary_external_key_arn
  key_material_base64     = var.key_material_base64
  deletion_window_in_days = var.deletion_window_in_days
  policy                  = local.key_policy_json
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "this" {
  count         = length(var.aliases)
  name          = var.aliases[count.index].name
  name_prefix   = var.aliases[count.index].name_prefix
  target_key_id = local.key_id
}

resource "aws_kms_grant" "this" {
  count              = length(var.grants)
  key_id             = local.key_id
  grantee_principal  = var.grants[count.index].grantee_principal
  operations         = var.grants[count.index].operations
  retiring_principal = var.grants[count.index].retiring_principal

  dynamic "constraints" {
    for_each = var.grants[count.index].encryption_context_subset != null ? [var.grants[count.index].encryption_context_subset] : []
    content {
      encryption_context_subset = constraints.value
    }
  }
}

output "key_id" {
  description = "ID of the selected KMS key."
  value       = local.key_id
}

output "key_arn" {
  description = "ARN of the selected KMS key."
  value       = local.key_arn
}

output "key_policy_json" {
  description = "Final KMS key policy JSON document."
  value       = local.key_policy_json
}

output "alias_names" {
  description = "Names of created KMS aliases."
  value       = aws_kms_alias.this[*].name
}

output "alias_arns" {
  description = "ARNs of created KMS aliases."
  value       = aws_kms_alias.this[*].arn
}

output "grant_ids" {
  description = "IDs of created KMS grants."
  value       = aws_kms_grant.this[*].grant_id
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

variable "topic_name" {
  description = "Name of the SNS topic"
  type        = string
  default     = "my-sns-topic"
}

variable "create_kms_key" {
  description = "Whether to create a dedicated KMS key for the SNS topic"
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "Explicit KMS master key ARN to use for encryption (overrides created key if non-empty)"
  type        = string
  default     = ""
}

variable "fifo_topic" {
  description = "Whether to create a FIFO SNS topic"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication for FIFO topics"
  type        = bool
  default     = false
}

variable "application_success_feedback_role_arn" {
  description = "IAM role ARN for Application success feedback"
  type        = string
  default     = ""
}

variable "application_success_feedback_sample_rate" {
  description = "Sample rate for Application success feedback (0-100)"
  type        = number
  default     = null
}

variable "application_failure_feedback_role_arn" {
  description = "IAM role ARN for Application failure feedback"
  type        = string
  default     = ""
}

variable "http_success_feedback_role_arn" {
  description = "IAM role ARN for HTTP success feedback"
  type        = string
  default     = ""
}

variable "http_success_feedback_sample_rate" {
  description = "Sample rate for HTTP success feedback (0-100)"
  type        = number
  default     = null
}

variable "http_failure_feedback_role_arn" {
  description = "IAM role ARN for HTTP failure feedback"
  type        = string
  default     = ""
}

variable "lambda_success_feedback_role_arn" {
  description = "IAM role ARN for Lambda success feedback"
  type        = string
  default     = ""
}

variable "lambda_success_feedback_sample_rate" {
  description = "Sample rate for Lambda success feedback (0-100)"
  type        = number
  default     = null
}

variable "lambda_failure_feedback_role_arn" {
  description = "IAM role ARN for Lambda failure feedback"
  type        = string
  default     = ""
}

variable "sqs_success_feedback_role_arn" {
  description = "IAM role ARN for SQS success feedback"
  type        = string
  default     = ""
}

variable "sqs_success_feedback_sample_rate" {
  description = "Sample rate for SQS success feedback (0-100)"
  type        = number
  default     = null
}

variable "sqs_failure_feedback_role_arn" {
  description = "IAM role ARN for SQS failure feedback"
  type        = string
  default     = ""
}

variable "firehose_success_feedback_role_arn" {
  description = "IAM role ARN for Firehose success feedback"
  type        = string
  default     = ""
}

variable "firehose_success_feedback_sample_rate" {
  description = "Sample rate for Firehose success feedback (0-100)"
  type        = number
  default     = null
}

variable "firehose_failure_feedback_role_arn" {
  description = "IAM role ARN for Firehose failure feedback"
  type        = string
  default     = ""
}

variable "sns_topic_policy" {
  description = "Custom JSON policy for the SNS topic (optional)"
  type        = string
  default     = ""
}

variable "subscriptions" {
  description = "Map of subscriptions to create on the SNS topic"
  type = map(object({
    endpoint                        = string
    protocol                        = string
    confirmation_timeout_in_minutes = optional(number, 1)
    raw_message_delivery            = optional(bool, false)
    filter_policy                   = optional(string, "")
    redrive_policy                  = optional(string, "")
    subscription_role_arn           = optional(string, "")
  }))
  default = {}
}

locals {
  raw_topic_name     = var.topic_name
  fifo_suffix        = ".fifo"
  has_fifo_suffix    = endswith(local.raw_topic_name, local.fifo_suffix)
  effective_topic_name = var.fifo_topic ? (local.has_fifo_suffix ? local.raw_topic_name : "${local.raw_topic_name}${local.fifo_suffix}") : local.raw_topic_name

  sanitized_topic_name = replace(local.effective_topic_name, "/[^a-zA-Z0-9-]/", "-")

  created_key_arn = try(aws_kms_key.sns[0].arn, "")

  effective_kms_key_id = var.create_kms_key ? local.created_key_arn : var.kms_master_key_id
}

resource "aws_kms_key" "sns" {
  count = var.create_kms_key ? 1 : 0

  description             = "KMS key for SNS topic ${local.effective_topic_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAdminPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogsEncryption"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "sns" {
  count = var.create_kms_key ? 1 : 0

  name          = "alias/sns/${local.sanitized_topic_name}"
  target_key_id = aws_kms_key.sns[0].arn
}

resource "aws_sns_topic" "main" {
  name = local.effective_topic_name

  kms_master_key_id = local.effective_kms_key_id

  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.content_based_deduplication

  application_success_feedback_role_arn    = var.application_success_feedback_role_arn
  application_success_feedback_sample_rate = var.application_success_feedback_sample_rate
  application_failure_feedback_role_arn    = var.application_failure_feedback_role_arn

  http_success_feedback_role_arn    = var.http_success_feedback_role_arn
  http_success_feedback_sample_rate = var.http_success_feedback_sample_rate
  http_failure_feedback_role_arn    = var.http_failure_feedback_role_arn

  lambda_success_feedback_role_arn    = var.lambda_success_feedback_role_arn
  lambda_success_feedback_sample_rate = var.lambda_success_feedback_sample_rate
  lambda_failure_feedback_role_arn    = var.lambda_failure_feedback_role_arn

  sqs_success_feedback_role_arn    = var.sqs_success_feedback_role_arn
  sqs_success_feedback_sample_rate = var.sqs_success_feedback_sample_rate
  sqs_failure_feedback_role_arn    = var.sqs_failure_feedback_role_arn

  firehose_success_feedback_role_arn    = var.firehose_success_feedback_role_arn
  firehose_success_feedback_sample_rate = var.firehose_success_feedback_sample_rate
  firehose_failure_feedback_role_arn    = var.firehose_failure_feedback_role_arn
}

resource "aws_sns_topic_policy" "main" {
  count = var.sns_topic_policy != "" ? 1 : 0

  arn    = aws_sns_topic.main.arn
  policy = var.sns_topic_policy
}

resource "aws_sns_topic_subscription" "this" {
  for_each = var.subscriptions

  topic_arn = aws_sns_topic.main.arn

  endpoint                        = each.value.endpoint
  protocol                        = each.value.protocol
  confirmation_timeout_in_minutes = each.value.confirmation_timeout_in_minutes
  raw_message_delivery            = each.value.raw_message_delivery
  filter_policy                   = each.value.filter_policy != "" ? each.value.filter_policy : null
  redrive_policy                  = each.value.redrive_policy != "" ? each.value.redrive_policy : null
  subscription_role_arn           = each.value.subscription_role_arn != "" ? each.value.subscription_role_arn : null
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "create_iam_group" {
  description = "Toggle to create the IAM developer group"
  type        = bool
  default     = true
}

variable "create_iam_policy_readonly_s3" {
  description = "Toggle to create the IAM read-only and S3 read/write access policy"
  type        = bool
  default     = true
}

variable "create_group_policy_attachment" {
  description = "Toggle to attach the policy to the group"
  type        = bool
  default     = true
}

variable "create_iam_users" {
  description = "Toggle to create IAM users"
  type        = bool
  default     = true
}

variable "create_ec2_screenshot_policy" {
  description = "Toggle to create the EC2 console screenshot policy"
  type        = bool
  default     = true
}

variable "create_ec2_screenshot_group_attachment" {
  description = "Toggle to attach the EC2 screenshot policy to the developers group (instead of directly to users)"
  type        = bool
  default     = true
}

variable "create_group_memberships" {
  description = "Toggle to add users to the developers group"
  type        = bool
  default     = true
}

variable "create_ec2_instance_role" {
  description = "Toggle to create the EC2 instance role"
  type        = bool
  default     = true
}

variable "iam_group_name" {
  description = "Name of the IAM group"
  type        = string
  default     = "developers"
}

variable "iam_users" {
  description = "List of IAM users to create"
  type = list(object({
    name = string
    tags = map(string)
  }))
  default = [
    {
      name = "jack"
      tags = { user_created_by = "terraform" }
    },
    {
      name = "jones"
      tags = { user_created_by = "terraform" }
    }
  ]
}

# IAM Group
resource "aws_iam_group" "developers" {
  count = var.create_iam_group ? 1 : 0
  name  = var.iam_group_name

  lifecycle {
    prevent_destroy = true
  }
}

# IAM Users
resource "aws_iam_user" "users" {
  for_each = var.create_iam_users ? { for u in var.iam_users : u.name => u } : {}
  name     = each.value.name
  tags     = each.value.tags

  lifecycle {
    prevent_destroy = true
  }
}

# IAM Policy: IAM Read Only + S3 Full Access (with MFA enforcement)
data "aws_iam_policy_document" "iam_read_only_and_s3_full_access" {
  statement {
    sid    = "IAMReadOnly"
    effect = "Allow"
    actions = [
      "iam:Get*",
      "iam:List*"
    ]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid    = "S3FullAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket",
      "s3:DeleteObject"
    ]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "iam_read_only_and_s3_full_access" {
  count       = var.create_iam_policy_readonly_s3 ? 1 : 0
  name        = "iam_read_only_and_s3_full_access"
  description = "Policy granting IAM read-only and S3 read/write access (MFA required)"
  policy      = data.aws_iam_policy_document.iam_read_only_and_s3_full_access.json

  lifecycle {
    prevent_destroy = true
  }
}

# Group Policy Attachment (read-only + S3)
resource "aws_iam_group_policy_attachment" "readonly_s3" {
  count      = var.create_group_policy_attachment && var.create_iam_group && var.create_iam_policy_readonly_s3 ? 1 : 0
  group      = aws_iam_group.developers[0].name
  policy_arn = aws_iam_policy.iam_read_only_and_s3_full_access[0].arn
}

# IAM Policy: EC2 Console Screenshot
data "aws_iam_policy_document" "ec2_get_console_screenshot" {
  statement {
    sid    = "EC2ConsoleScreenshot"
    effect = "Allow"
    actions = [
      "ec2:GetConsoleScreenshot"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "ec2_get_console_screenshot" {
  count       = var.create_ec2_screenshot_policy ? 1 : 0
  name        = "ec2_get_console_screenshot"
  description = "Policy granting EC2 console screenshot access"
  policy      = data.aws_iam_policy_document.ec2_get_console_screenshot.json

  lifecycle {
    prevent_destroy = true
  }
}

# Group Policy Attachment (EC2 screenshot) – replaces direct user attachment
resource "aws_iam_group_policy_attachment" "screenshot" {
  count = var.create_ec2_screenshot_group_attachment && var.create_group_memberships && var.create_iam_group && var.create_ec2_screenshot_policy ? 1 : 0
  group      = aws_iam_group.developers[0].name
  policy_arn = aws_iam_policy.ec2_get_console_screenshot[0].arn
}

# Group Membership
resource "aws_iam_group_membership" "developers" {
  count = var.create_group_memberships && var.create_iam_group && var.create_iam_users ? 1 : 0
  name  = "developers-membership"
  group = aws_iam_group.developers[0].name
  users = [for u in var.iam_users : u.name]
}

# IAM Role for EC2
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid    = "EC2AssumeRole"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "instance_role" {
  count              = var.create_ec2_instance_role ? 1 : 0
  name               = "instance_role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  lifecycle {
    prevent_destroy = true
  }
}

# Role Policy Attachment (AWS-managed IAMReadOnlyAccess)
resource "aws_iam_role_policy_attachment" "instance_role_readonly" {
  count      = var.create_ec2_instance_role ? 1 : 0
  role       = aws_iam_role.instance_role[0].name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_name" {
  description = "Name of the VPC and the Blueprint tag value"
  type        = string
  default     = "multi-cluster-vpc"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

locals {
  vpc_cidr = "10.0.0.0/16"
  azs      = slice(data.aws_availability_zones.available.names, 0, 3)
  common_tags = {
    Blueprint  = var.vpc_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
  flow_log_group_name = "/aws/vpc-flow-logs/${var.vpc_name}"
  flow_log_group_arn  = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${local.flow_log_group_name}"
  flow_log_stream_arn = "${local.flow_log_group_arn}:log-stream:*"
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = var.vpc_name
  cidr = local.vpc_cidr

  azs = local.azs

  private_subnets = [
    cidrsubnet(local.vpc_cidr, 4, 0),
    cidrsubnet(local.vpc_cidr, 4, 1),
    cidrsubnet(local.vpc_cidr, 4, 2),
  ]

  public_subnets = [
    cidrsubnet(local.vpc_cidr, 8, 48),
    cidrsubnet(local.vpc_cidr, 8, 49),
    cidrsubnet(local.vpc_cidr, 8, 50),
  ]

  enable_nat_gateway   = true
  single_nat_gateway   = true
  enable_dns_hostnames = true
  enable_dns_support   = true

  public_subnet_tags = merge(local.common_tags, {
    "kubernetes.io/role/elb" = "1"
  })

  private_subnet_tags = merge(local.common_tags, {
    "kubernetes.io/role/internal-elb" = "1"
  })

  tags = local.common_tags
}

resource "aws_kms_key" "flow_log" {
  description         = "CMK for VPC Flow Logs CloudWatch Log Group"
  enable_key_rotation = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableRootAdminPermissions"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "AllowCloudWatchLogsToUseKey"
        Effect    = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*",
          "kms:CreateGrant"
        ]
        Resource = "*"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "flow_log" {
  name              = local.flow_log_group_name
  retention_in_days = 30
  kms_key_id        = aws_kms_key.flow_log.arn
  tags              = local.common_tags
}

resource "aws_iam_role" "flow_log" {
  name = "vpc-flow-log-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action    = "sts:AssumeRole"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_policy" "flow_log" {
  name = "vpc-flow-log-policy"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          local.flow_log_group_arn,
          local.flow_log_stream_arn
        ]
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "flow_log" {
  role       = aws_iam_role.flow_log.name
  policy_arn = aws_iam_policy.flow_log.arn
}

resource "aws_flow_log" "flow_log" {
  log_destination      = aws_cloudwatch_log_group.flow_log.arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.flow_log.arn
  vpc_id               = module.vpc.vpc_id
  traffic_type         = "ALL"
  tags                 = local.common_tags

  depends_on = [
    aws_iam_role_policy_attachment.flow_log
  ]
}

resource "aws_security_group" "cluster1_additional_sg" {
  name        = "cluster1_additional_sg"
  description = "Additional security group for cluster1 allowing all traffic to/from cluster2 additional security group"
  vpc_id      = module.vpc.vpc_id

  tags = merge(local.common_tags, {
    Name = "cluster1_additional_sg"
  })
}

resource "aws_security_group" "cluster2_additional_sg" {
  name        = "cluster2_additional_sg"
  description = "Additional security group for cluster2 allowing all traffic to/from cluster1 additional security group"
  vpc_id      = module.vpc.vpc_id

  tags = merge(local.common_tags, {
    Name = "cluster2_additional_sg"
  })
}

resource "aws_security_group_rule" "cluster1_ingress_from_cluster2" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.cluster2_additional_sg.id
  security_group_id        = aws_security_group.cluster1_additional_sg.id
  description              = "Allow all traffic from cluster2_additional_sg"
}

resource "aws_security_group_rule" "cluster1_egress_to_cluster2" {
  type                     = "egress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.cluster2_additional_sg.id
  security_group_id        = aws_security_group.cluster1_additional_sg.id
  description              = "Allow all traffic to cluster2_additional_sg"
}

resource "aws_security_group_rule" "cluster2_ingress_from_cluster1" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.cluster1_additional_sg.id
  security_group_id        = aws_security_group.cluster2_additional_sg.id
  description              = "Allow all traffic from cluster1_additional_sg"
}

resource "aws_security_group_rule" "cluster2_egress_to_cluster1" {
  type                     = "egress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.cluster1_additional_sg.id
  security_group_id        = aws_security_group.cluster2_additional_sg.id
  description              = "Allow all traffic to cluster1_additional_sg"
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------

variable "pool_name" {
  type    = string
  default = "Pool name"
}

variable "alias_attributes" {
  type    = list(string)
  default = ["email", "phone_number"]
}

variable "auto_verified_attributes" {
  type    = list(string)
  default = []
}

variable "email_verification_message" {
  type    = string
  default = "Some message {####}"
}

variable "email_verification_subject" {
  type    = string
  default = "Some subject"
}

variable "mfa_configuration" {
  type    = string
  default = "OPTIONAL"
}

variable "sms_authentication_message" {
  type    = string
  default = "SMS authentication message {####}"
}

variable "sms_verification_message" {
  type    = string
  default = "SMS verification message {####}"
}

variable "email_message_by_link" {
  type    = string
  default = null
}

variable "email_subject_by_link" {
  type    = string
  default = null
}

variable "default_email_option" {
  type    = string
  default = null
}

variable "sms_configuration" {
  type = map(string)
  default = {
    external_id   = ""
    sns_caller_arn = ""
  }
}

variable "recovery_mechanisms" {
  type = list(map(any))
  default = [
    { name = "verified_phone_number", priority = 1 },
    { name = "verified_email", priority = 2 }
  ]
}

variable "invite_message_template" {
  type    = any
  default = null
}

variable "admin_create_user_only" {
  type    = bool
  default = false
}

variable "software_token_mfa_enabled" {
  type    = bool
  default = true
}

variable "username_case_sensitivity" {
  type    = bool
  default = null
}

variable "device_configuration" {
  type = object({
    challenge_required_on_new_device      = bool
    device_only_remembered_on_user_prompt = bool
  })
  default = null
}

variable "lambda_config" {
  type    = map(any)
  default = {}
}

variable "custom_schema" {
  type = list(map(any))
  default = [
    {
      name                = "email"
      attribute_data_type = "String"
      required            = true
      mutable             = true
    }
  ]
}

variable "client_app_names" {
  type    = list(string)
  default = []
}

variable "client_generate_secret" {
  type    = bool
  default = false
}

variable "client_access_token_validity" {
  type    = number
  default = 120
}

variable "client_id_token_validity" {
  type    = number
  default = 120
}

variable "client_refresh_token_validity" {
  type    = number
  default = 7
}

variable "client_access_token_validity_unit" {
  type    = string
  default = "minutes"
}

variable "client_id_token_validity_unit" {
  type    = string
  default = "minutes"
}

variable "client_refresh_token_validity_unit" {
  type    = string
  default = "days"
}

variable "client_allowed_oauth_flows_user_pool_client" {
  type    = bool
  default = false
}

variable "client_enable_token_revocation" {
  type    = bool
  default = true
}

variable "client_explicit_auth_flows" {
  type = list(string)
  default = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_USER_SRP_AUTH"
  ]
}

variable "client_prevent_user_existence_errors" {
  type    = string
  default = "LEGACY"
}

variable "client_read_attributes" {
  type    = list(string)
  default = []
}

variable "client_write_attributes" {
  type    = list(string)
  default = []
}

variable "client_callback_urls" {
  type    = list(string)
  default = []
}

variable "client_logout_urls" {
  type    = list(string)
  default = []
}

variable "client_allowed_oauth_flows" {
  type    = list(string)
  default = []
}

variable "client_allowed_oauth_scopes" {
  type    = list(string)
  default = ["email", "openid", "profile"]
}

variable "client_supported_identity_providers" {
  type    = list(string)
  default = ["COGNITO"]
}

variable "group_name" {
  type    = string
  default = ""
}

variable "group_precedence" {
  type    = number
  default = 0
}

variable "group_role_arn" {
  type    = string
  default = null
}

variable "user_pool_domain" {
  type    = string
  default = ""
}

variable "user_pool_domain_certificate_arn" {
  type    = string
  default = null
}

variable "create_route53_record" {
  type    = bool
  default = false
}

variable "route53_zone_id" {
  type    = string
  default = null
}

# ------------------------------------------------------------------------------
# RESOURCES
# ------------------------------------------------------------------------------

resource "aws_cognito_user_pool" "main" {
  name                     = var.pool_name
  alias_attributes         = var.alias_attributes
  auto_verified_attributes = var.auto_verified_attributes
  mfa_configuration        = var.mfa_configuration

  sms_authentication_message = var.sms_authentication_message

  verification_message_template {
    email_message        = var.email_verification_message
    email_subject        = var.email_verification_subject
    sms_message          = var.sms_verification_message
    email_message_by_link = var.email_message_by_link
    email_subject_by_link = var.email_subject_by_link
    default_email_option  = var.default_email_option
  }

  dynamic "sms_configuration" {
    for_each = var.sms_configuration["external_id"] != "" && var.sms_configuration["sns_caller_arn"] != "" ? [var.sms_configuration] : []
    content {
      external_id   = each.value.external_id
      sns_caller_arn = each.value.sns_caller_arn
    }
  }

  dynamic "account_recovery_setting" {
    for_each = length(var.recovery_mechanisms) > 0 ? [true] : []
    content {
      dynamic "recovery_mechanism" {
        for_each = { for idx, rm in var.recovery_mechanisms : idx => rm }
        iterator = recovery
        content {
          name     = recovery.value.name
          priority = recovery.value.priority
        }
      }
    }
  }

  admin_create_user_config {
    allow_admin_create_user_only = var.admin_create_user_only

    dynamic "invite_message_template" {
      for_each = var.invite_message_template != null ? [var.invite_message_template] : []
      content {
        email_message = each.value.email_message
        email_subject = each.value.email_subject
        sms_message   = each.value.sms_message
      }
    }
  }

  software_token_mfa_configuration {
    enabled = var.software_token_mfa_enabled
  }

  dynamic "username_configuration" {
    for_each = var.username_case_sensitivity != null ? [var.username_case_sensitivity] : []
    content {
      case_sensitive = each.value
    }
  }

  dynamic "device_configuration" {
    for_each = var.device_configuration != null ? [var.device_configuration] : []
    content {
      challenge_required_on_new_device      = each.value.challenge_required_on_new_device
      device_only_remembered_on_user_prompt = each.value.device_only_remembered_on_user_prompt
    }
  }

  dynamic "lambda_config" {
    for_each = length(keys(var.lambda_config)) > 0 ? [var.lambda_config] : []
    iterator = lambda_cfg
    content {
      # Scalar trigger ARN attributes
      custom_message         = lookup(lambda_cfg.value, "custom_message", null)
      pre_token_generation   = lookup(lambda_cfg.value, "pre_token_generation", null)
      post_confirmation      = lookup(lambda_cfg.value, "post_confirmation", null)
      pre_sign_up            = lookup(lambda_cfg.value, "pre_sign_up", null)
      create_auth_challenge  = lookup(lambda_cfg.value, "create_auth_challenge", null)
      define_auth_challenge  = lookup(lambda_cfg.value, "define_auth_challenge", null)
      post_authentication    = lookup(lambda_cfg.value, "post_authentication", null)
      pre_authentication     = lookup(lambda_cfg.value, "pre_authentication", null)
      user_migration         = lookup(lambda_cfg.value, "user_migration", null)

      # Block-type triggers
      dynamic "custom_email_sender" {
        for_each = lookup(lambda_cfg.value, "custom_email_sender", null) != null ? [lambda_cfg.value["custom_email_sender"]] : []
        content {
          lambda_arn     = each.value.lambda_arn
          lambda_version = lookup(each.value, "lambda_version", "V1_0")
        }
      }
      dynamic "custom_sms_sender" {
        for_each = lookup(lambda_cfg.value, "custom_sms_sender", null) != null ? [lambda_cfg.value["custom_sms_sender"]] : []
        content {
          lambda_arn     = each.value.lambda_arn
          lambda_version = lookup(each.value, "lambda_version", "V1_0")
        }
      }
    }
  }

  dynamic "schema" {
    for_each = var.custom_schema
    iterator = schema_entry
    content {
      name                = schema_entry.value.name
      attribute_data_type = schema_entry.value.attribute_data_type
      required            = schema_entry.value.required
      mutable             = schema_entry.value.mutable

      dynamic "string_attribute_constraints" {
        for_each = schema_entry.value.attribute_data_type == "String" && (lookup(schema_entry.value, "min_length", null) != null || lookup(schema_entry.value, "max_length", null) != null) ? [schema_entry.value] : []
        content {
          min_length = lookup(schema_entry.value, "min_length", null)
          max_length = lookup(schema_entry.value, "max_length", null)
        }
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cognito_user_pool_client" "app" {
  for_each = toset(var.client_app_names)

  user_pool_id = aws_cognito_user_pool.main.id
  name         = each.key
  generate_secret = var.client_generate_secret

  explicit_auth_flows              = var.client_explicit_auth_flows
  prevent_user_existence_errors    = var.client_prevent_user_existence_errors
  enable_token_revocation          = var.client_enable_token_revocation
  allowed_oauth_flows_user_pool_client = var.client_allowed_oauth_flows_user_pool_client

  access_token_validity  = var.client_access_token_validity
  id_token_validity      = var.client_id_token_validity
  refresh_token_validity = var.client_refresh_token_validity

  token_validity_units {
    access_token  = var.client_access_token_validity_unit
    id_token      = var.client_id_token_validity_unit
    refresh_token = var.client_refresh_token_validity_unit
  }

  read_attributes              = length(var.client_read_attributes) > 0 ? var.client_read_attributes : null
  write_attributes             = length(var.client_write_attributes) > 0 ? var.client_write_attributes : null
  callback_urls                = length(var.client_callback_urls) > 0 ? var.client_callback_urls : null
  logout_urls                  = length(var.client_logout_urls) > 0 ? var.client_logout_urls : null
  allowed_oauth_flows          = length(var.client_allowed_oauth_flows) > 0 ? var.client_allowed_oauth_flows : null
  allowed_oauth_scopes         = length(var.client_allowed_oauth_scopes) > 0 ? var.client_allowed_oauth_scopes : null
  supported_identity_providers = length(var.client_supported_identity_providers) > 0 ? var.client_supported_identity_providers : null
}

resource "aws_cognito_user_group" "group" {
  count = var.group_name != "" ? 1 : 0

  user_pool_id = aws_cognito_user_pool.main.id
  name         = var.group_name
  precedence   = var.group_precedence
  role_arn     = var.group_role_arn
}

resource "aws_cognito_user_pool_domain" "domain" {
  count = var.user_pool_domain != "" ? 1 : 0

  domain       = var.user_pool_domain
  user_pool_id = aws_cognito_user_pool.main.id
  certificate_arn = var.user_pool_domain_certificate_arn
}

resource "aws_route53_record" "alias" {
  count = var.create_route53_record && var.route53_zone_id != null && var.user_pool_domain != "" ? 1 : 0

  zone_id = var.route53_zone_id
  name    = var.user_pool_domain
  type    = "A"

  alias {
    name                   = aws_cognito_user_pool_domain.domain[0].cloudfront_distribution_arn
    zone_id                = "Z2FDTNDATAQYW2"
    evaluate_target_health = false
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

variable "vpc_cidr_block" {
  type    = string
  default = "10.0.0.0/16"
}

variable "vpc_name" {
  type    = string
  default = "DevOps-Project-VPC"
}

variable "internet_gateway_name" {
  type    = string
  default = "devops-project-igw"
}

variable "route_table_name" {
  type    = string
  default = "DevOps-project-RT"
}

variable "public_subnet_identifier" {
  type    = string
  default = "subnet_a"
}

variable "nat_gateway_name" {
  type    = string
  default = "DevOps-NAT-GW"
}

variable "public_ipv4_pool" {
  type    = string
  default = "amazon"
}

variable "subnet_a_cidr_block" {
  type    = string
  default = "10.0.1.0/24"
}

variable "subnet_a_availability_zone" {
  type    = string
  default = ""
}

variable "subnet_a_map_public_ip_on_launch" {
  type    = bool
  default = false
}

variable "subnet_a_name" {
  type    = string
  default = "Subnet-A-Public"
}

variable "subnet_b_cidr_block" {
  type    = string
  default = "10.0.2.0/24"
}

variable "subnet_b_availability_zone" {
  type    = string
  default = ""
}

variable "subnet_b_map_public_ip_on_launch" {
  type    = bool
  default = false
}

variable "subnet_b_name" {
  type    = string
  default = "Subnet-B-Private"
}

variable "subnet_c_cidr_block" {
  type    = string
  default = "10.0.3.0/24"
}

variable "subnet_c_availability_zone" {
  type    = string
  default = ""
}

variable "subnet_c_map_public_ip_on_launch" {
  type    = bool
  default = false
}

variable "subnet_c_name" {
  type    = string
  default = "Subnet-C-Private"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_a_cidr_block
  availability_zone       = coalesce(var.subnet_a_availability_zone, data.aws_availability_zones.available.names[0])
  map_public_ip_on_launch = var.subnet_a_map_public_ip_on_launch

  tags = {
    Name                   = var.subnet_a_name
    PublicSubnetIdentifier = var.public_subnet_identifier
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_b_cidr_block
  availability_zone       = coalesce(var.subnet_b_availability_zone, data.aws_availability_zones.available.names[1])
  map_public_ip_on_launch = var.subnet_b_map_public_ip_on_launch

  tags = {
    Name = var.subnet_b_name
  }
}

resource "aws_subnet" "subnet_c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_c_cidr_block
  availability_zone       = coalesce(var.subnet_c_availability_zone, data.aws_availability_zones.available.names[2])
  map_public_ip_on_launch = var.subnet_c_map_public_ip_on_launch

  tags = {
    Name = var.subnet_c_name
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.internet_gateway_name
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.route_table_name
  }
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.subnet_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain           = "vpc"
  public_ipv4_pool = var.public_ipv4_pool
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.subnet_b.id
  depends_on    = [aws_internet_gateway.main]

  tags = {
    Name = var.nat_gateway_name
  }
}

resource "aws_security_group" "default" {
  name        = "DefaultSecurityGroup"
  description = "Default security group allowing outbound traffic only within the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
    description = "Outbound traffic within VPC CIDR"
  }

  tags = {
    Name = "DefaultSecurityGroup"
  }
}

resource "aws_kms_key" "flow_log" {
  description         = "KMS key for VPC Flow Log encryption"
  enable_key_rotation = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "flow_log" {
  name          = "alias/DevOps-Project-VPC-FlowLog"
  target_key_id = aws_kms_key.flow_log.key_id
}

resource "aws_cloudwatch_log_group" "flow_log" {
  name_prefix       = "/aws/vpc/flow-logs-"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.flow_log.arn
}

resource "aws_iam_role" "flow_log" {
  name = "DevOps-Project-VPC-FlowLog-Role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "flow_log" {
  name_prefix = "DevOps-Project-VPC-FlowLog-"
  description = "IAM policy for VPC Flow Logs to publish to CloudWatch Logs"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "flow_log" {
  role       = aws_iam_role.flow_log.name
  policy_arn = aws_iam_policy.flow_log.arn
}

resource "aws_flow_log" "main" {
  vpc_id               = aws_vpc.main.id
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.flow_log.arn
  iam_role_arn         = aws_iam_role.flow_log.arn
  traffic_type         = "ALL"

  tags = {
    Name = "DevOps-Project-VPC-Flow-Log"
  }
}

output "nat_gateway_public_ip" {
  value = aws_eip.nat.public_ip
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "vault_name" {
  description = "Name of the backup vault"
  type        = string
  default     = "my-backup-vault"
}

variable "tags" {
  description = "Optional tags to apply to backup resources"
  type        = map(string)
  default     = {}
}

variable "tag_key" {
  description = "Tag key used to select resources for backup plans"
  type        = string
  default     = "backup"
}

variable "continuous_backup" {
  description = "Enable continuous backup for the daily plan"
  type        = bool
  default     = false
}

variable "notification_enabled" {
  description = "Flag to enable backup vault notifications via SNS"
  type        = bool
  default     = false
}

variable "sns_topic_name" {
  description = "Name of the SNS topic for backup notifications"
  type        = string
  default     = "backup-notifications"
}

variable "notification_events" {
  description = "Set of backup events to send notifications for"
  type        = set(string)
  default = [
    "BACKUP_JOB_FAILED",
    "RESTORE_JOB_FAILED",
    "COPY_JOB_FAILED",
    "S3_BACKUP_OBJECT_FAILED",
    "S3_RESTORE_OBJECT_FAILED"
  ]
}

# ------------------------------------------------------------------------------
# KMS Key for Backup Vault Encryption
# ------------------------------------------------------------------------------
resource "aws_kms_key" "backup_vault" {
  description             = "KMS key for encrypting AWS Backup vault ${var.vault_name}"
  enable_key_rotation     = true
  rotation_period_in_days = 365
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "backup_vault" {
  name          = "alias/backup-vault-${var.vault_name}"
  target_key_id = aws_kms_key.backup_vault.id
}

# ------------------------------------------------------------------------------
# Backup Vault
# ------------------------------------------------------------------------------
resource "aws_backup_vault" "main" {
  name        = var.vault_name
  kms_key_arn = aws_kms_key.backup_vault.arn
  tags        = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# IAM Role for Backup Service
# ------------------------------------------------------------------------------
resource "aws_iam_role" "backup_service" {
  name               = "backup-service-role"
  assume_role_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Action    = "sts:AssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "backup_service" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
  role       = aws_iam_role.backup_service.name
}

# ------------------------------------------------------------------------------
# Backup Plans
# ------------------------------------------------------------------------------
resource "aws_backup_plan" "daily" {
  name = "${var.vault_name}-daily"

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  rule {
    rule_name         = "daily_backup_rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = "cron(0 12 ? * * *)"
    lifecycle {
      delete_after = 7
    }
    enable_continuous_backup = var.continuous_backup
  }
}

resource "aws_backup_plan" "weekly" {
  name = "${var.vault_name}-weekly"

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  rule {
    rule_name         = "weekly_backup_rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = "cron(0 12 ? * 1 *)"
    lifecycle {
      delete_after = 31
    }
  }
}

resource "aws_backup_plan" "monthly" {
  name = "${var.vault_name}-monthly"

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  rule {
    rule_name         = "monthly_backup_rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = "cron(0 12 1 * ? *)"
    lifecycle {
      delete_after = 366
    }
  }
}

# ------------------------------------------------------------------------------
# Backup Selections
# ------------------------------------------------------------------------------
resource "aws_backup_selection" "daily" {
  name         = "daily_backup_selection"
  plan_id      = aws_backup_plan.daily.id
  iam_role_arn = aws_iam_role.backup_service.arn

  resources = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.tag_key
    value = "daily"
  }
}

resource "aws_backup_selection" "weekly" {
  name         = "weekly_backup_selection"
  plan_id      = aws_backup_plan.weekly.id
  iam_role_arn = aws_iam_role.backup_service.arn

  resources = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.tag_key
    value = "weekly"
  }
}

resource "aws_backup_selection" "monthly" {
  name         = "monthly_backup_selection"
  plan_id      = aws_backup_plan.monthly.id
  iam_role_arn = aws_iam_role.backup_service.arn

  resources = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.tag_key
    value = "monthly"
  }
}

# ------------------------------------------------------------------------------
# Conditional SNS Topic and Backup Vault Notification
# ------------------------------------------------------------------------------
resource "aws_sns_topic" "backup_notifications" {
  count = var.notification_enabled ? 1 : 0
  name  = var.sns_topic_name
  tags  = var.tags
}

resource "aws_backup_vault_notifications" "main" {
  count             = var.notification_enabled ? 1 : 0
  backup_vault_name = aws_backup_vault.main.name
  sns_topic_arn     = aws_sns_topic.backup_notifications[0].arn
  backup_vault_events = var.notification_events
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "region" {
  type    = string
  default = "us-east-1"
}

variable "env" {
  type    = string
  default = "test"
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  type    = list(string)
  default = ["10.0.10.0/24", "10.0.11.0/24"]
}

variable "private_subnet_cidrs" {
  type    = list(string)
  default = ["10.0.20.0/24", "10.0.21.0/24"]
}

variable "common_tags" {
  type = map(string)
  default = {
    Owner   = "Valerii Vasianovych"
    Project = "Terraform AWS"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.common_tags, {
    Name   = "${var.env}-vpc"
    Region = var.region
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.common_tags, {
    Name = "${var.env}-igw"
  })
}

resource "aws_subnet" "public" {
  count                   = length(var.public_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.common_tags, {
    Name = "${var.env}-public-subnet-${count.index}"
  })
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(var.common_tags, {
    Name = "${var.env}-private-subnet-${count.index}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(var.common_tags, {
    Name = "${var.env}-route-public-subnets"
  })
}

resource "aws_route_table_association" "public" {
  count          = length(var.public_subnet_cidrs)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count  = length(var.private_subnet_cidrs)
  domain = "vpc"

  tags = merge(var.common_tags, {
    Name = "${var.env}-nat-eip-${count.index}"
  })
}

resource "aws_nat_gateway" "nat" {
  count         = length(var.private_subnet_cidrs)
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  depends_on = [aws_internet_gateway.main]

  tags = merge(var.common_tags, {
    Name = "${var.env}-nat-gw-${count.index}"
  })
}

resource "aws_route_table" "private" {
  count  = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[count.index].id
  }

  tags = merge(var.common_tags, {
    Name = "${var.env}-route-private-subnets-${count.index}"
  })
}

resource "aws_route_table_association" "private" {
  count          = length(var.private_subnet_cidrs)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for CloudWatch Logs VPC flow log encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs"
        Effect = "Allow"
        Principal = {
          Service = "logs.${var.region}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(var.common_tags, {
    Name = "${var.env}-vpc-flow-log-key"
  })
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/${var.env}-vpc-flow-log"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

resource "aws_cloudwatch_log_group" "flow_log" {
  name              = "/aws/vpc/flow-logs"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.cloudwatch.arn

  tags = merge(var.common_tags, {
    Name = "${var.env}-vpc-flow-logs"
  })
}

resource "aws_iam_role" "flow_log" {
  name = "${var.env}-vpc-flow-log-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = "sts:AssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(var.common_tags, {
    Name = "${var.env}-vpc-flow-log-role"
  })
}

resource "aws_iam_policy" "flow_log" {
  name        = "${var.env}-vpc-flow-log-policy"
  description = "Policy for VPC Flow Logs to publish to CloudWatch Logs"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "VPCFlowLogsToCloudWatch"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          aws_cloudwatch_log_group.flow_log.arn,
          "${aws_cloudwatch_log_group.flow_log.arn}:*"
        ]
      }
    ]
  })

  tags = merge(var.common_tags, {
    Name = "${var.env}-vpc-flow-log-policy"
  })
}

resource "aws_iam_role_policy_attachment" "flow_log" {
  role       = aws_iam_role.flow_log.name
  policy_arn = aws_iam_policy.flow_log.arn
}

resource "aws_flow_log" "main" {
  iam_role_arn         = aws_iam_role.flow_log.arn
  log_destination      = aws_cloudwatch_log_group.flow_log.arn
  log_destination_type = "cloud-watch-logs"
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"

  tags = merge(var.common_tags, {
    Name = "${var.env}-vpc-flow-log"
  })
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "nat_gateway_ids" {
  value = aws_nat_gateway.nat[*].id
}

output "public_route_table_id" {
  value = aws_route_table.public.id
}

output "private_route_table_ids" {
  value = aws_route_table.private[*].id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

variable "create_eks" {
  type    = bool
  default = true
}

variable "cluster_name" {
  type    = string
  default = ""
}

variable "cluster_version" {
  type    = string
  default = null
}

variable "authentication_mode" {
  type    = string
  default = "API_AND_CONFIG_MAP"
}

variable "subnet_ids" {
  type    = list(string)
  default = []
}

variable "control_plane_subnet_ids" {
  type    = list(string)
  default = []
}

locals {
  cluster_name = var.cluster_name != "" ? var.cluster_name : "eks-cluster"

  eks_subnet_ids = length(var.control_plane_subnet_ids) > 0 ? var.control_plane_subnet_ids : (
    length(var.subnet_ids) > 0 ? var.subnet_ids : tolist(aws_subnet.private[*].id)
  )
}

resource "random_id" "eks_suffix" {
  count = var.create_eks ? 1 : 0

  byte_length = 4
}

resource "aws_vpc" "main" {
  count                = var.create_eks ? 1 : 0
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.cluster_name
  }
}

resource "aws_subnet" "private" {
  count = var.create_eks ? min(3, length(data.aws_availability_zones.available.names)) : 0

  vpc_id                  = aws_vpc.main[0].id
  cidr_block              = cidrsubnet(aws_vpc.main[0].cidr_block, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name                                   = "${local.cluster_name}-private-${count.index + 1}"
    "kubernetes.io/cluster/${local.cluster_name}" = "shared"
  }
}

resource "aws_iam_role" "eks_cluster" {
  count = var.create_eks ? 1 : 0

  name_prefix = "eks-cluster"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  count = var.create_eks ? 1 : 0

  role       = aws_iam_role.eks_cluster[0].name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  count = var.create_eks ? 1 : 0

  role       = aws_iam_role.eks_cluster[0].name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
}

resource "aws_kms_key" "eks" {
  count                   = var.create_eks ? 1 : 0
  description             = "EKS secret encryption key"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "EKSKeyPolicy"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow EKS Service"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
          "kms:CreateGrant",
          "kms:ListGrants",
          "kms:RevokeGrant"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = local.cluster_name
  }
}

resource "aws_kms_key" "cloudwatch" {
  count                   = var.create_eks ? 1 : 0
  description             = "CloudWatch Logs encryption key for EKS VPC flow logs"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "CloudWatchKeyPolicy"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs Service"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = local.cluster_name
  }
}

resource "aws_cloudwatch_log_group" "flow_log" {
  count = var.create_eks ? 1 : 0

  name_prefix = "/aws/vpc-flow-log/${local.cluster_name}-"
  kms_key_id  = aws_kms_key.cloudwatch[0].arn
}

resource "aws_iam_policy" "vpc_flow_log" {
  count = var.create_eks ? 1 : 0

  name_prefix = "vpc-flow-log-policy-${local.cluster_name}-"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role" "vpc_flow_log" {
  count = var.create_eks ? 1 : 0

  name_prefix = "vpc-flow-log-${local.cluster_name}-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "vpc_flow_log" {
  count = var.create_eks ? 1 : 0

  role       = aws_iam_role.vpc_flow_log[0].name
  policy_arn = aws_iam_policy.vpc_flow_log[0].arn
}

resource "aws_flow_log" "this" {
  count = var.create_eks ? 1 : 0

  vpc_id               = aws_vpc.main[0].id
  traffic_type         = "ALL"
  log_destination      = aws_cloudwatch_log_group.flow_log[0].arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.vpc_flow_log[0].arn

  depends_on = [
    aws_iam_role_policy_attachment.vpc_flow_log
  ]
}

resource "aws_eks_cluster" "this" {
  count = var.create_eks ? 1 : 0

  name     = var.cluster_name != "" ? var.cluster_name : "${local.cluster_name}-${random_id.eks_suffix[0].hex}"
  role_arn = aws_iam_role.eks_cluster[0].arn
  version  = var.cluster_version

  enabled_cluster_log_types = ["api", "audit", "authenticator", "controllerManager", "scheduler"]

  vpc_config {
    subnet_ids              = local.eks_subnet_ids
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  access_config {
    authentication_mode                          = var.authentication_mode
    bootstrap_cluster_creator_admin_permissions = true
  }

  encryption_config {
    resources = ["secrets"]

    provider {
      key_arn = aws_kms_key.eks[0].arn
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

locals {
  common_tags = {
    Name       = "rwwise.dev Infrastructure Setup"
    Repository = "https://github.com/zangrum/setup.inf.rwwise.dev"
    AccountID  = data.aws_caller_identity.current.account_id
    UserID     = data.aws_caller_identity.current.arn
  }

  cicd_policy_json = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadOnlyListAccess"
        Effect = "Allow"
        Action = [
          "codebuild:BatchGet*",
          "codebuild:Describe*",
          "codebuild:List*",
          "codecommit:BatchGet*",
          "codecommit:Describe*",
          "codecommit:Get*",
          "codecommit:GitPull",
          "codecommit:List*",
          "cloudwatch:Describe*",
          "cloudwatch:Get*",
          "cloudwatch:List*",
          "events:Describe*",
          "events:List*",
          "logs:Describe*",
          "logs:Get*",
          "logs:List*",
          "logs:FilterLogEvents"
        ]
        Resource = "*"
      },
      {
        Sid    = "CodeStarConnectionsUserAccess"
        Effect = "Allow"
        Action = [
          "codestar-connections:GetConnection*",
          "codestar-connections:ListConnections"
        ]
        Resource = "arn:aws:codestar-connections:*:*:connection/*"
      },
      {
        Sid    = "CodeStarNotificationsPowerUserAccess"
        Effect = "Allow"
        Action = [
          "codestar-notifications:DescribeNotificationRule"
        ]
        Resource = "*"
        Condition = {
          StringLike = {
            "codestar-notifications:NotificationsForResource" = "arn:aws:codebuild:*"
          }
        }
      },
      {
        Sid    = "CodeStarNotificationsListAccess"
        Effect = "Allow"
        Action = [
          "codestar-notifications:ListNotificationRules",
          "codestar-notifications:ListEventTypes",
          "codestar-notifications:ListTargets"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowSTSSessionToken"
        Effect = "Allow"
        Action = [
          "sts:GetSessionToken"
        ]
        Resource = "*"
      },
      {
        Sid    = "EnforceMFA"
        Effect = "Deny"
        NotAction = [
          "sts:GetSessionToken"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_iam_user" "dev" {
  name = "DevUser-rwwise.dev"
  path = "/system/"
  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_user" "test" {
  name = "TestUser-rwwise.dev"
  path = "/system/"
  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_user" "prod" {
  name = "ProdUser-rwwise.dev"
  path = "/system/"
  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_access_key" "dev" {
  user   = aws_iam_user.dev.name
  status = "Active"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_access_key" "test" {
  user   = aws_iam_user.test.name
  status = "Active"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_access_key" "prod" {
  user   = aws_iam_user.prod.name
  status = "Active"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_group" "dev" {
  name = "DevGroup-rwwise.dev"
  path = "/system/"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_group" "test" {
  name = "TestGroup-rwwise.dev"
  path = "/system/"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_group" "prod" {
  name = "ProdGroup-rwwise.dev"
  path = "/system/"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_group_policy" "dev" {
  name   = "dev_cicd_user_policy"
  group  = aws_iam_group.dev.name
  policy = local.cicd_policy_json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_group_policy" "test" {
  name   = "test_cicd_user_policy"
  group  = aws_iam_group.test.name
  policy = local.cicd_policy_json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_group_policy" "prod" {
  name   = "prod_cicd_user_policy"
  group  = aws_iam_group.prod.name
  policy = local.cicd_policy_json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_group_membership" "dev" {
  name  = "DevGroup-rwwise.dev-membership"
  group = aws_iam_group.dev.name
  users = [aws_iam_user.dev.name]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_group_membership" "test" {
  name  = "TestGroup-rwwise.dev-membership"
  group = aws_iam_group.test.name
  users = [aws_iam_user.test.name]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_group_membership" "prod" {
  name  = "ProdGroup-rwwise.dev-membership"
  group = aws_iam_group.prod.name
  users = [aws_iam_user.prod.name]

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "name" {
  type    = string
  default = null
}

variable "tags" {
  type    = map(string)
  default = {}
}

variable "bus_config" {
  type    = map(string)
  default = {}

  validation {
    condition     = var.bus_config != null
    error_message = "bus_config must not be null."
  }
}

variable "rules" {
  type    = list(map(string))
  default = []

  validation {
    condition     = var.rules != null
    error_message = "rules must not be null."
  }
}

variable "targets" {
  type    = list(map(string))
  default = []

  validation {
    condition     = var.targets != null
    error_message = "targets must not be null."
  }
}

locals {
  module_name       = var.name != null && var.name != "" ? var.name : "default"
  create_custom_bus = local.module_name != "default"
}

data "aws_partition" "current" {}

resource "aws_cloudwatch_event_bus" "this" {
  count = local.create_custom_bus ? 1 : 0

  name              = local.module_name
  event_source_name = lookup(var.bus_config, "event_source_name", null)
  tags              = var.tags
}

resource "aws_cloudwatch_event_rule" "this" {
  for_each = { for rule in var.rules : rule.name => rule }

  name                = each.value.name
  description         = lookup(each.value, "description", null)
  event_pattern       = lookup(each.value, "event_pattern", null)
  schedule_expression = lookup(each.value, "schedule_expression", null)
  event_bus_name      = local.create_custom_bus ? aws_cloudwatch_event_bus.this[0].name : null
  tags                = var.tags
}

resource "aws_iam_role" "this" {
  name = "${local.module_name}-invoke"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "events.${data.aws_partition.current.dns_suffix}"
        }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "this" {
  name = "${local.module_name}-invoke-targets"
  role = aws_iam_role.this.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "lambda:InvokeFunction",
          "states:StartExecution",
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_cloudwatch_event_target" "this" {
  for_each = {
    for target in var.targets :
    "${target.rule}-${target.arn}" => target
  }

  rule           = each.value.rule
  arn            = each.value.arn
  event_bus_name = local.create_custom_bus ? aws_cloudwatch_event_bus.this[0].name : null
  role_arn       = can(regex("stateMachine", each.value.arn)) ? aws_iam_role.this.arn : null

  depends_on = [aws_cloudwatch_event_rule.this]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "name" {
  description = "Base name used to generate AWS Backup resource names."
  type        = string
  default     = "hr"
}

variable "kms_key_arn" {
  description = "ARN of the KMS key used for backup vault encryption. Empty string uses the AWS-managed KMS key."
  type        = string
  default     = ""
}

variable "vault_policy" {
  description = "JSON policy document for the backup vault. Empty string disables the policy attachment."
  type        = string
  default     = ""
}

variable "sns_topic_arn" {
  description = "ARN of the SNS topic for backup vault notifications. Empty string disables notifications."
  type        = string
  default     = ""
}

variable "schedule" {
  description = "Cron or rate expression for the backup schedule."
  type        = string
  default     = "cron(0 5 * * ? *)"
}

variable "start_window" {
  description = "Amount of time in minutes before the backup job starts."
  type        = number
  default     = 60
}

variable "completion_window" {
  description = "Amount of time in minutes the backup job is allowed to complete."
  type        = number
  default     = 120
}

variable "cold_storage_after_days" {
  description = "Number of days after which recovery points transition to cold storage."
  type        = number
  default     = 30
}

variable "delete_after_days" {
  description = "Number of days after which recovery points are deleted."
  type        = number
  default     = 120
}

variable "copy_actions" {
  description = "Map of copy action names to destination backup vault ARNs. Default is no cross-region copies."
  type        = map(string)
  default     = {}
}

variable "events" {
  description = "List of backup vault events to publish to the SNS topic."
  type        = list(string)
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

variable "selection_tag_type" {
  description = "Tag comparison type for backup resource selection."
  type        = string
  default     = "STRINGEQUALS"
}

variable "selection_tag_key" {
  description = "Tag key used to select resources for backup."
  type        = string
  default     = "Backup"
}

variable "selection_tag_value" {
  description = "Tag value used to select resources for backup."
  type        = string
  default     = "true"
}

locals {
  job_tag = "${var.name}-backup"
}

resource "aws_iam_role" "backup" {
  name = "aws-backup-${var.name}-${substr(uuid(), 0, 8)}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Job = local.job_tag
  }
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_backup_vault" "this" {
  name        = "vault-${local.job_tag}-${substr(uuid(), 0, 8)}"
  kms_key_arn = var.kms_key_arn != "" ? var.kms_key_arn : null

  tags = {
    Job = local.job_tag
  }
}

resource "aws_backup_vault_policy" "this" {
  count = var.vault_policy != "" ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  policy            = var.vault_policy
}

resource "aws_backup_vault_notifications" "this" {
  count = var.sns_topic_arn != "" ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.events
}

resource "aws_backup_plan" "this" {
  name = "plan-${local.job_tag}-${substr(uuid(), 0, 8)}"

  tags = {
    Job = local.job_tag
  }

  rule {
    rule_name         = "rule-${local.job_tag}"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.schedule
    start_window      = var.start_window
    completion_window = var.completion_window

    recovery_point_tags = {
      Job = local.job_tag
    }

    lifecycle {
      cold_storage_after = var.cold_storage_after_days
      delete_after       = var.delete_after_days
    }

    dynamic "copy_action" {
      for_each = var.copy_actions
      content {
        destination_vault_arn = copy_action.value

        lifecycle {
          cold_storage_after = var.cold_storage_after_days
          delete_after       = var.delete_after_days
        }
      }
    }
  }
}

resource "aws_backup_selection" "this" {
  name         = "selection-${local.job_tag}-${substr(uuid(), 0, 8)}"
  iam_role_arn = aws_iam_role.backup.arn
  plan_id      = aws_backup_plan.this.id

  condition {}

  selection_tag {
    type  = var.selection_tag_type
    key   = var.selection_tag_key
    value = var.selection_tag_value
  }
}

output "backup_iam_role_arn" {
  description = "ARN of the AWS Backup IAM role."
  value       = aws_iam_role.backup.arn
}

output "backup_vault_arn" {
  description = "ARN of the AWS Backup vault."
  value       = aws_backup_vault.this.arn
}

output "backup_vault_name" {
  description = "Name of the AWS Backup vault."
  value       = aws_backup_vault.this.name
}

output "backup_plan_id" {
  description = "ID of the AWS Backup plan."
  value       = aws_backup_plan.this.id
}

output "backup_plan_arn" {
  description = "ARN of the AWS Backup plan."
  value       = aws_backup_plan.this.arn
}

output "backup_selection_id" {
  description = "ID of the AWS Backup selection."
  value       = aws_backup_selection.this.id
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------

variable "create" {
  description = "Whether to create a new Transit Gateway (true) or look up an existing one (false)."
  type        = bool
  default     = true
}

variable "id" {
  description = "ID of an existing Transit Gateway to use when create is false."
  type        = string
  default     = null
}

variable "name" {
  description = "Name tag of an existing Transit Gateway to look up when create is false and id is not provided."
  type        = string
  default     = null
}

variable "bgp_asn" {
  description = "BGP ASN for the Amazon side of the Transit Gateway."
  type        = number
  default     = 65200

  validation {
    condition     = (var.bgp_asn >= 64512 && var.bgp_asn <= 65534) || (var.bgp_asn >= 4200000000 && var.bgp_asn <= 4294967294)
    error_message = "bgp_asn must be in the range 64512-65534 (16-bit) or 4200000000-4294967294 (32-bit)."
  }
}

variable "auto_accept_shared_attachments" {
  description = "Whether to automatically accept shared attachment requests. Valid values are 'enable' or 'disable'."
  type        = string
  default     = "disable"

  validation {
    condition     = contains(["enable", "disable"], var.auto_accept_shared_attachments)
    error_message = "auto_accept_shared_attachments must be either 'enable' or 'disable'."
  }
}

variable "dns_support" {
  description = "Whether DNS support is enabled. Valid values are 'enable' or 'disable'."
  type        = string
  default     = "enable"

  validation {
    condition     = contains(["enable", "disable"], var.dns_support)
    error_message = "dns_support must be either 'enable' or 'disable'."
  }
}

variable "vpn_ecmp_support" {
  description = "Whether VPN ECMP support is enabled. Valid values are 'enable' or 'disable'."
  type        = string
  default     = "enable"

  validation {
    condition     = contains(["enable", "disable"], var.vpn_ecmp_support)
    error_message = "vpn_ecmp_support must be either 'enable' or 'disable'."
  }
}

variable "transit_gateway_cidr_blocks" {
  description = "One or more IPv4 or IPv6 CIDR blocks for the Transit Gateway."
  type        = list(string)
  default     = []

  validation {
    condition = alltrue([
      for cidr in var.transit_gateway_cidr_blocks : can(cidrhost(cidr, 0))
    ])
    error_message = "Each entry in transit_gateway_cidr_blocks must be a valid IPv4 or IPv6 CIDR block."
  }
}

variable "route_tables" {
  description = "Map of Transit Gateway route tables to create or reference."
  type = map(object({
    create     = bool
    name       = string
    tags       = map(string)
    local_tags = map(string)
  }))
  default = {}
}

variable "shared_principals" {
  description = "Map of principals (AWS account IDs, Organization ARNs, or OU ARNs) to share the Transit Gateway with via RAM."
  type        = map(string)
  default     = {}
}

variable "ram_resource_share_name" {
  description = "Name for the RAM resource share. Defaults to the Transit Gateway name when not set."
  type        = string
  default     = null
}

variable "global_tags" {
  description = "Tags applied to all created resources."
  type        = map(string)
  default     = {}
}

# ------------------------------------------------------------------------------
# LOCALS
# ------------------------------------------------------------------------------

locals {
  tgw_id  = var.create ? aws_ec2_transit_gateway.this[0].id : data.aws_ec2_transit_gateway.this[0].id
  tgw_arn = var.create ? aws_ec2_transit_gateway.this[0].arn : data.aws_ec2_transit_gateway.this[0].arn

  tgw_name = coalesce(
    var.create ? try(aws_ec2_transit_gateway.this[0].tags["Name"], null) : try(data.aws_ec2_transit_gateway.this[0].tags["Name"], null),
    "transit-gateway"
  )

  ram_share_name = coalesce(var.ram_resource_share_name, local.tgw_name)
}

# ------------------------------------------------------------------------------
# TRANSIT GATEWAY
# ------------------------------------------------------------------------------

resource "aws_ec2_transit_gateway" "this" {
  count = var.create ? 1 : 0

  description                     = "Transit Gateway for hub-and-spoke network routing"
  amazon_side_asn                 = var.bgp_asn
  auto_accept_shared_attachments  = var.auto_accept_shared_attachments
  default_route_table_association = "disable"
  default_route_table_propagation = "disable"
  dns_support                     = var.dns_support
  vpn_ecmp_support                = var.vpn_ecmp_support
  transit_gateway_cidr_blocks     = var.transit_gateway_cidr_blocks

  tags = var.global_tags
}

data "aws_ec2_transit_gateway" "this" {
  count = var.create ? 0 : 1

  id = var.id

  dynamic "filter" {
    for_each = (var.id == null || var.id == "") && (var.name != null && var.name != "") ? [1] : []
    content {
      name   = "tag:Name"
      values = [var.name]
    }
  }

  lifecycle {
    precondition {
      condition     = (var.id != null && var.id != "") || (var.name != null && var.name != "")
      error_message = "Either 'id' or 'name' must be provided when 'create' is false."
    }
  }
}

# ------------------------------------------------------------------------------
# ROUTE TABLES
# ------------------------------------------------------------------------------

resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = {
    for name, rt in var.route_tables : name => rt
    if rt.create == true
  }

  transit_gateway_id = local.tgw_id

  tags = merge(
    var.global_tags,
    each.value.tags,
    each.value.local_tags,
    { Name = coalesce(each.value.name, local.tgw_name) }
  )
}

data "aws_ec2_transit_gateway_route_table" "this" {
  for_each = {
    for name, rt in var.route_tables : name => rt
    if rt.create == false
  }

  filter {
    name   = "transit-gateway-id"
    values = [local.tgw_id]
  }

  dynamic "filter" {
    for_each = each.value.name != null && each.value.name != "" ? [1] : []
    content {
      name   = "tag:Name"
      values = [each.value.name]
    }
  }

  lifecycle {
    precondition {
      condition     = each.value.name != null && each.value.name != ""
      error_message = "The 'name' attribute is required when 'create' is false."
    }
  }
}

# ------------------------------------------------------------------------------
# RAM SHARING
# ------------------------------------------------------------------------------

resource "aws_ram_resource_share" "this" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  name                      = local.ram_share_name
  allow_external_principals = true

  tags = var.global_tags
}

resource "aws_ram_resource_association" "this" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  resource_arn       = local.tgw_arn
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

resource "aws_ram_principal_association" "this" {
  for_each = var.shared_principals

  principal          = each.value
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

# ------------------------------------------------------------------------------
# OUTPUTS
# ------------------------------------------------------------------------------

output "transit_gateway_id" {
  description = "ID of the Transit Gateway."
  value       = local.tgw_id
}

output "transit_gateway_arn" {
  description = "ARN of the Transit Gateway."
  value       = local.tgw_arn
}

output "route_table_ids" {
  description = "Map of Transit Gateway route table IDs."
  value = {
    for name, rt in var.route_tables : name => (
      rt.create ? aws_ec2_transit_gateway_route_table.this[name].id : data.aws_ec2_transit_gateway_route_table.this[name].id
    )
  }
}

output "ram_resource_share_arn" {
  description = "ARN of the RAM resource share, or null when no principals are configured."
  value       = length(var.shared_principals) > 0 ? aws_ram_resource_share.this[0].arn : null
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_iam_policy" "backup" {
  name = "AWSBackupServiceRolePolicyForBackup"
}

data "aws_iam_policy" "restores" {
  name = "AWSBackupServiceRolePolicyForRestores"
}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "Allow AWS Backup Service Access"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
    actions = [
      "kms:DescribeKey",
      "kms:CreateGrant",
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:ReEncrypt*",
    ]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_kms_key" "shared" {
  description             = "Shared KMS key for AWS Backup service tiers"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  policy                 = data.aws_iam_policy_document.kms_key_policy.json
}

resource "aws_kms_alias" "shared_backup" {
  name          = "alias/aws-backup-shared-key"
  target_key_id = aws_kms_key.shared.arn
}

resource "aws_iam_role" "bronze_backup_role" {
  name               = "Bronze_Backup_Role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.bronze_backup_role.name
  policy_arn = data.aws_iam_policy.backup.arn
}

resource "aws_iam_role_policy_attachment" "restores" {
  role       = aws_iam_role.bronze_backup_role.name
  policy_arn = data.aws_iam_policy.restores.arn
}

resource "aws_backup_vault" "bronze" {
  name        = "Bronze_Backup_Vault"
  kms_key_arn = aws_kms_key.shared.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "silver" {
  name        = "Silver_Backup_Vault"
  kms_key_arn = aws_kms_key.shared.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "gold" {
  name        = "Gold_Backup_Vault"
  kms_key_arn = aws_kms_key.shared.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "premium" {
  name        = "Premium"
  kms_key_arn = aws_kms_key.shared.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_plan" "bronze" {
  name = "Bronze_Backup"

  rule {
    rule_name         = "Bronze_Backup_Weekly"
    target_vault_name = aws_backup_vault.bronze.name
    schedule          = "cron(0 0 ? * FRI *)"

    lifecycle {
      delete_after = 10
    }
  }
}

resource "aws_backup_plan" "silver" {
  name = "Silver_Backup_Plan"

  rule {
    rule_name         = "Silver_Backup_Daily"
    target_vault_name = aws_backup_vault.silver.name
    schedule          = "cron(0 5 ? * * *)"

    lifecycle {
      delete_after = 7
    }
  }
}

resource "aws_backup_plan" "gold" {
  name = "Gold_Backup"

  rule {
    rule_name         = "Gold_Daily_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 * * ? *)"

    lifecycle {
      delete_after = 31
    }
  }

  rule {
    rule_name         = "Gold_Monthly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 1 1/1 ? *)"

    lifecycle {
      delete_after = 365
    }
  }

  rule {
    rule_name         = "Gold_Yearly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 31 12 ? *)"

    lifecycle {
      delete_after = 2555
    }
  }
}

resource "aws_backup_plan" "premium" {
  name = "Premium"

  rule {
    rule_name         = "Premium_Daily_4Hour_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0/4 ? * * *)"

    lifecycle {
      delete_after = 1
    }
  }

  rule {
    rule_name         = "Premium_Daily_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 * * ? *)"

    lifecycle {
      delete_after = 31
    }
  }

  rule {
    rule_name         = "Premium_Monthly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 1 1/1 ? *)"

    lifecycle {
      cold_storage_after = 15
      delete_after       = 365
    }
  }

  rule {
    rule_name         = "Premium_Yearly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 31 12 ? *)"

    lifecycle {
      cold_storage_after = 15
      delete_after       = 2555
    }
  }
}

resource "aws_backup_selection" "bronze" {
  name         = "Bronze_Resource_Assignment"
  plan_id      = aws_backup_plan.bronze.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "bronze"
  }
}

resource "aws_backup_selection" "silver" {
  name         = "Silver_Backup_resource"
  plan_id      = aws_backup_plan.silver.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "silver"
  }
}

resource "aws_backup_selection" "gold" {
  name         = "Gold_Backup_Select"
  plan_id      = aws_backup_plan.gold.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "gold"
  }
}

resource "aws_backup_selection" "premium" {
  name         = "Premium"
  plan_id      = aws_backup_plan.premium.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "premium"
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region for the deployment"
  type        = string
  default     = "us-east-1"
}

variable "iam_role_name" {
  description = "Name of the IAM role for Prisma Cloud"
  type        = string
  default     = "PrismaCloudReadWriteRole"
}

variable "read_write" {
  description = "Flag to enable remediation (read-write) policy"
  type        = bool
  default     = false
}

resource "random_string" "external_id" {
  length  = 32
  special = false
  upper   = true
  lower   = true
  numeric = true
}

resource "aws_iam_role" "prisma_cloud_role" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::188619942792:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = random_string.external_id.result
          }
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "security_audit" {
  role       = aws_iam_role.prisma_cloud_role.name
  policy_arn = "arn:aws:iam::aws:policy/SecurityAudit"
}

resource "aws_iam_role_policy" "prisma_cloud_read_only" {
  name   = "PrismaCloud-IAM-ReadOnly-Policy"
  role   = aws_iam_role.prisma_cloud_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "apigateway:GET",
          "cognito-identity:ListTagsForResource",
          "cognito-idp:ListTagsForResource",
          "ecr:DescribeImages",
          "ecr:GetLifecyclePolicy",
          "elasticbeanstalk:ListTagsForResource",
          "elasticfilesystem:DescribeTags",
          "glacier:GetVaultLock",
          "glacier:ListTagsForVault",
          "glue:GetSecurityConfigurations",
          "logs:GetLogEvents",
          "mq:listBrokers",
          "mq:describeBroker",
          "ram:GetResourceShares",
          "secretsmanager:DescribeSecret",
          "ssm:GetParameters",
          "ssm:ListTagsForResource",
          "sqs:SendMessage",
          "elasticmapreduce:ListSecurityConfigurations",
          "sns:listSubscriptions",
          "wafv2:ListResourcesForWebACL",
          "wafv2:ListWebACLs"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "prisma_cloud_remediation" {
  count  = var.read_write ? 1 : 0
  name   = "PrismaCloud-IAM-Remediation-Policy"
  role   = aws_iam_role.prisma_cloud_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "iam:UpdateAccountPasswordPolicy",
          "ec2:ModifyImageAttribute",
          "rds:ModifyDBSnapshotAttribute",
          "s3:PutBucketAcl",
          "ec2:RevokeSecurityGroupIngress"
        ]
        Resource = "*"
      }
    ]
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  type        = string
  default     = "10.0.2.0/24"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "development-be-vpc"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "development-be-public-subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "development-be-private-subnet"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "development-be-ig"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "development-be-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "http_access" {
  name        = "http_access"
  description = "Security group allowing SSH from VPC CIDR and HTTP from anywhere, with egress restricted to VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All outbound traffic to VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "development-be-sg"
  }
}

# VPC Flow Logs
resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for CloudWatch log group encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogs"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "development-be-cloudwatch-kms-key"
  }
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/cloudwatch"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

resource "aws_cloudwatch_log_group" "vpc_flow_log" {
  name = "/aws/vpc/flow-log/${aws_vpc.main.id}"
  kms_key_id = aws_kms_alias.cloudwatch.arn

  tags = {
    Name = "development-be-vpc-flow-log-group"
  }
}

resource "aws_iam_role" "vpc_flow_log_role" {
  name = "development-be-vpc-flow-log-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "vpc_flow_log_policy" {
  role = aws_iam_role.vpc_flow_log_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "arn:aws:logs:*:*:log-group:/aws/vpc/flow-log/*"
      },
      {
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = aws_iam_role.vpc_flow_log_role.arn
      }
    ]
  })
}

resource "aws_flow_log" "vpc_flow_log" {
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.vpc_flow_log.arn
  iam_role_arn         = aws_iam_role.vpc_flow_log_role.arn

  tags = {
    Name = "development-be-vpc-flow-log"
  }
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "ID of the public subnet"
  value       = aws_subnet.public.id
}

output "private_subnet_id" {
  description = "ID of the private subnet"
  value       = aws_subnet.private.id
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------

variable "create" {
  description = "Whether to create any resources"
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the SNS topic. If null and use_name_prefix is false, a default name will be used."
  type        = string
  default     = null
}

variable "use_name_prefix" {
  description = "If true, use name as a prefix (name_prefix) instead of the full name."
  type        = bool
  default     = false
}

variable "fifo_topic" {
  description = "Whether to create a FIFO topic."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication (only valid for FIFO topics)."
  type        = bool
  default     = false
}

variable "delivery_policy" {
  description = "JSON delivery policy for the topic."
  type        = string
  default     = null
}

variable "display_name" {
  description = "Display name for the topic."
  type        = string
  default     = null
}

variable "kms_master_key_id" {
  description = "KMS key ID for encryption."
  type        = string
  default     = null
}

variable "signature_version" {
  description = "Signature version (must be null for FIFO topics)."
  type        = string
  default     = null
}

variable "tracing_config" {
  description = "Tracing configuration (e.g., 'Active' or 'Passive')."
  type        = string
  default     = null
}

variable "application_feedback_configuration" {
  description = "Feedback configuration for Application protocol."
  type        = map(string)
  default     = {}
}

variable "firehose_feedback_configuration" {
  description = "Feedback configuration for Firehose protocol."
  type        = map(string)
  default     = {}
}

variable "http_feedback_configuration" {
  description = "Feedback configuration for HTTP protocol."
  type        = map(string)
  default     = {}
}

variable "lambda_feedback_configuration" {
  description = "Feedback configuration for Lambda protocol."
  type        = map(string)
  default     = {}
}

variable "sqs_feedback_configuration" {
  description = "Feedback configuration for SQS protocol."
  type        = map(string)
  default     = {}
}

variable "create_topic_policy" {
  description = "Whether to create a topic policy. If false, use the external topic_policy string."
  type        = bool
  default     = true
}

variable "topic_policy" {
  description = "External topic policy JSON (used when create_topic_policy is false)."
  type        = string
  default     = null
}

variable "enable_default_topic_policy" {
  description = "Whether to include a default policy statement allowing standard SNS actions from the same account."
  type        = bool
  default     = true
}

variable "source_policy_documents" {
  description = "List of JSON policy documents to merge as source."
  type        = list(string)
  default     = []
}

variable "override_policy_documents" {
  description = "List of JSON policy documents to override."
  type        = list(string)
  default     = []
}

variable "statements" {
  description = "List of statement objects for the topic policy."
  type = list(object({
    effect    = string
    actions   = list(string)
    resources = list(string)
    condition = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = []
}

variable "create_subscription" {
  description = "Whether to create subscriptions."
  type        = bool
  default     = true
}

variable "subscriptions" {
  description = "Map of subscription configurations."
  type = map(object({
    protocol                            = string
    endpoint                            = string
    confirmation_timeout_in_minutes     = optional(number)
    delivery_policy                     = optional(string)
    auto_confirm_pending_subscription   = optional(bool)
    filter_policy                       = optional(string)
    filter_policy_scope                 = optional(string)
    raw_message_delivery                = optional(bool)
    redrive_policy                      = optional(string)
    subscription_role_arn               = optional(string)
  }))
  default = {}
}

variable "data_protection_policy" {
  description = "JSON data protection policy (not supported for FIFO topics)."
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags to apply to all resources."
  type        = map(string)
  default     = {}
}

# ------------------------------------------------------------------------------
# VALIDATION
# ------------------------------------------------------------------------------

locals {
  create = var.create
}

# Validate FIFO constraints
check "fifo_content_dedup" {
  assert {
    condition     = var.fifo_topic || !var.content_based_deduplication
    error_message = "content_based_deduplication is only valid when fifo_topic is true."
  }
}

check "fifo_signature_version" {
  assert {
    condition     = !var.fifo_topic || var.signature_version == null
    error_message = "signature_version must be null when fifo_topic is true."
  }
}

# ------------------------------------------------------------------------------
# LOCALS
# ------------------------------------------------------------------------------

locals {
  # Determine base name
  base_name = var.name != null ? var.name : "sns-topic"

  # Ensure .fifo suffix for FIFO topics
  topic_name = var.fifo_topic ? (
    endswith(local.base_name, ".fifo") ? local.base_name : "${local.base_name}.fifo"
  ) : local.base_name

  topic_name_prefix = var.use_name_prefix ? (
    var.fifo_topic ? (
      endswith(var.name, ".fifo") ? var.name : "${var.name}.fifo"
    ) : var.name
  ) : null
}

# ------------------------------------------------------------------------------
# DATA SOURCES
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# SNS TOPIC
# ------------------------------------------------------------------------------

resource "aws_sns_topic" "this" {
  count = local.create ? 1 : 0

  name        = var.use_name_prefix ? null : local.topic_name
  name_prefix = var.use_name_prefix ? local.topic_name_prefix : null

  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.fifo_topic ? var.content_based_deduplication : null
  delivery_policy             = var.delivery_policy
  display_name                = var.display_name
  kms_master_key_id           = var.kms_master_key_id
  signature_version           = var.fifo_topic ? null : var.signature_version
  tracing_config              = var.tracing_config

  application_failure_feedback_role_arn    = try(var.application_feedback_configuration["failure_role_arn"], null)
  application_success_feedback_role_arn    = try(var.application_feedback_configuration["success_role_arn"], null)
  application_success_feedback_sample_rate = try(tonumber(var.application_feedback_configuration["success_sample_rate"]), null)

  firehose_failure_feedback_role_arn    = try(var.firehose_feedback_configuration["failure_role_arn"], null)
  firehose_success_feedback_role_arn    = try(var.firehose_feedback_configuration["success_role_arn"], null)
  firehose_success_feedback_sample_rate = try(tonumber(var.firehose_feedback_configuration["success_sample_rate"]), null)

  http_failure_feedback_role_arn    = try(var.http_feedback_configuration["failure_role_arn"], null)
  http_success_feedback_role_arn    = try(var.http_feedback_configuration["success_role_arn"], null)
  http_success_feedback_sample_rate = try(tonumber(var.http_feedback_configuration["success_sample_rate"]), null)

  lambda_failure_feedback_role_arn    = try(var.lambda_feedback_configuration["failure_role_arn"], null)
  lambda_success_feedback_role_arn    = try(var.lambda_feedback_configuration["success_role_arn"], null)
  lambda_success_feedback_sample_rate = try(tonumber(var.lambda_feedback_configuration["success_sample_rate"]), null)

  sqs_failure_feedback_role_arn    = try(var.sqs_feedback_configuration["failure_role_arn"], null)
  sqs_success_feedback_role_arn    = try(var.sqs_feedback_configuration["success_role_arn"], null)
  sqs_success_feedback_sample_rate = try(tonumber(var.sqs_feedback_configuration["success_sample_rate"]), null)

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# TOPIC POLICY
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "topic_policy" {
  count = local.create && var.create_topic_policy ? 1 : 0

  source_policy_documents   = var.source_policy_documents
  override_policy_documents = var.override_policy_documents

  dynamic "statement" {
    for_each = var.statements
    content {
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = statement.value.resources
      dynamic "condition" {
        for_each = statement.value.condition != null ? statement.value.condition : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }

  dynamic "statement" {
    for_each = var.enable_default_topic_policy ? [1] : []
    content {
      sid       = "DefaultTopicPolicy"
      effect    = "Allow"
      actions   = ["sns:GetTopicAttributes", "sns:Publish", "sns:Subscribe", "sns:Receive"]
      resources = [aws_sns_topic.this[0].arn]
      principals {
        type        = "AWS"
        identifiers = ["*"]
      }
      condition {
        test     = "StringEquals"
        variable = "aws:SourceOwner"
        values   = [data.aws_caller_identity.current.account_id]
      }
    }
  }
}

resource "aws_sns_topic_policy" "this" {
  count = local.create ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = var.create_topic_policy ? data.aws_iam_policy_document.topic_policy[0].json : var.topic_policy
}

# ------------------------------------------------------------------------------
# SUBSCRIPTIONS
# ------------------------------------------------------------------------------

resource "aws_sns_topic_subscription" "this" {
  for_each = local.create && var.create_subscription ? var.subscriptions : {}

  topic_arn = aws_sns_topic.this[0].arn

  protocol                        = each.value.protocol
  endpoint                        = each.value.endpoint
  confirmation_timeout_in_minutes = try(each.value.confirmation_timeout_in_minutes, null)
  delivery_policy                 = try(each.value.delivery_policy, null)
  filter_policy                   = try(each.value.filter_policy, null)
  filter_policy_scope             = try(each.value.filter_policy_scope, null)
  raw_message_delivery            = try(each.value.raw_message_delivery, null)
  redrive_policy                  = try(each.value.redrive_policy, null)
  subscription_role_arn           = try(each.value.subscription_role_arn, null)
}

# ------------------------------------------------------------------------------
# DATA PROTECTION POLICY
# ------------------------------------------------------------------------------

resource "aws_sns_topic_data_protection_policy" "this" {
  count = local.create && var.data_protection_policy != null && !var.fifo_topic ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = var.data_protection_policy
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

variable "bucket_name" {
  type    = string
  default = null
}

variable "prefix" {
  type    = bool
  default = false
}

variable "request_payer" {
  type    = string
  default = "BucketOwner"
}

variable "encryption" {
  type    = bool
  default = true
}

variable "kms_key" {
  type    = string
  default = ""
}

variable "versioning" {
  type    = bool
  default = false
}

variable "mfa_delete" {
  type    = bool
  default = false
}

variable "force_destroy" {
  type    = bool
  default = false
}

variable "acl" {
  type    = string
  default = null
}

variable "object_ownership" {
  type    = string
  default = "BucketOwnerPreferred"
}

variable "policy" {
  type    = string
  default = null
}

variable "grants" {
  type = list(object({
    permission   = string
    type         = string
    uri          = optional(string)
    id           = optional(string)
    display_name = optional(string)
  }))
  default = []
}

variable "tags" {
  type    = map(string)
  default = {}
}

variable "acceleration_status" {
  type    = string
  default = null
}

variable "log_target_bucket" {
  type    = string
  default = null
}

variable "log_prefix" {
  type    = string
  default = null
}

variable "website_index_document" {
  type    = string
  default = null
}

variable "website_error_document" {
  type    = string
  default = null
}

variable "website_redirect_all_requests_to" {
  type    = any
  default = null
}

variable "cors_rules" {
  type    = list(any)
  default = []
}

variable "lifecycle_rules" {
  type    = list(any)
  default = []
}

variable "object_lock_configuration" {
  type = object({
    default_retention = object({
      mode  = string
      days  = optional(number)
      years = optional(number)
    })
  })
  default = null
}

variable "replication_rules" {
  type = list(object({
    id                                 = optional(string)
    status                             = optional(string)
    priority                           = optional(number)
    prefix                             = optional(string)
    filter                             = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    destination_bucket_arn             = optional(string)
    destination_region                 = optional(string)
    destination_storage_class          = optional(string)
    destination_account                = optional(string)
    delete_marker_replication_status   = optional(string)
    existing_object_replication_status = optional(string)
    encryption_configuration           = optional(object({
      replica_kms_key_id = string
    }))
    access_control_translation         = optional(object({
      owner = string
    }))
    source_selection_criteria          = optional(object({
      sse_kms_encrypted_objects = optional(object({
        status = string
      }))
    }))
  }))
  default = []
}

variable "replication_role_arn" {
  type    = string
  default = ""
}

variable "replication_region" {
  type    = string
  default = "us-west-2"
}

locals {
  bucket_name = var.bucket_name != null ? (
    var.prefix ? "${var.bucket_name}-${random_id.prefix_suffix.hex}" : var.bucket_name
  ) : (
    var.prefix ? "corebucket-${random_id.bucket_name.hex}-${random_id.prefix_suffix.hex}" : "corebucket-${random_id.bucket_name.hex}"
  )

  replication_destinations = {
    for idx, rule in var.replication_rules : tostring(idx) => rule
    if rule.destination_bucket_arn == null || rule.destination_bucket_arn == ""
  }
}

data "aws_canonical_user_id" "current" {
  count = length(var.grants) > 0 && var.object_ownership != "BucketOwnerEnforced" ? 1 : 0
}

resource "random_id" "bucket_name" {
  byte_length = 4
}

resource "random_id" "prefix_suffix" {
  byte_length = 4
}

resource "random_id" "logging" {
  byte_length = 4
}

resource "aws_s3_bucket" "this" {
  bucket              = local.bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_configuration != null ? true : false
  tags                = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  count  = var.object_ownership != "BucketOwnerEnforced" ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_acl" "canned" {
  count      = var.acl != null && var.acl != "" && length(var.grants) == 0 && var.object_ownership != "BucketOwnerEnforced" ? 1 : 0
  bucket     = aws_s3_bucket.this.id
  acl        = var.acl
  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_acl" "grants" {
  count      = length(var.grants) > 0 && var.object_ownership != "BucketOwnerEnforced" ? 1 : 0
  bucket     = aws_s3_bucket.this.id
  depends_on = [aws_s3_bucket_ownership_controls.this]

  access_control_policy {
    owner {
      id = data.aws_canonical_user_id.current[0].id
    }

    dynamic "grant" {
      for_each = var.grants
      content {
        permission = grant.value.permission

        grantee {
          type         = grant.value.type
          uri          = try(grant.value.uri, null)
          id           = try(grant.value.id, null)
          display_name = try(grant.value.display_name, null)
        }
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  count  = var.policy != null && var.policy != "" ? 1 : 0
  bucket = aws_s3_bucket.this.id
  policy = var.policy
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = "Enabled"
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
  }
}

resource "aws_s3_bucket_request_payment_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  payer  = var.request_payer
}

resource "aws_kms_key" "this" {
  count                   = var.encryption && var.kms_key == "" ? 1 : 0
  description             = "Customer-managed KMS key for S3 bucket ${local.bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count  = var.encryption ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = var.kms_key != "" ? var.kms_key : aws_kms_key.this[0].arn
    }
  }
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count  = var.acceleration_status != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  status = var.acceleration_status
}

resource "aws_s3_bucket_logging" "this" {
  bucket        = aws_s3_bucket.this.id
  target_bucket = var.log_target_bucket != null && var.log_target_bucket != "" ? var.log_target_bucket : aws_s3_bucket.logging.id
  target_prefix = var.log_prefix != null ? var.log_prefix : ""
}

resource "aws_s3_bucket_website_configuration" "this" {
  count  = (var.website_index_document != null || var.website_error_document != null || var.website_redirect_all_requests_to != null) ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "index_document" {
    for_each = var.website_index_document != null ? [var.website_index_document] : []
    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = var.website_error_document != null ? [var.website_error_document] : []
    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = var.website_redirect_all_requests_to != null ? [var.website_redirect_all_requests_to] : []
    content {
      host_name = try(redirect_all_requests_to.value.host_name, redirect_all_requests_to.value)
      protocol  = try(redirect_all_requests_to.value.protocol, null)
    }
  }
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = try(rule.value.id, null)
      status = try(rule.value.status, "Enabled")

      dynamic "filter" {
        for_each = (
          try(rule.value.prefix, null) != null ||
          try(rule.value.filter.prefix, null) != null ||
          try(rule.value.filter.tags, null) != null ||
          try(rule.value.filter.object_size_greater_than, null) != null ||
          try(rule.value.filter.object_size_less_than, null) != null
        ) ? [true] : []

        content {
          dynamic "and" {
            for_each = (
              try(rule.value.filter.tags, null) != null ||
              try(rule.value.filter.object_size_greater_than, null) != null ||
              try(rule.value.filter.object_size_less_than, null) != null
            ) ? [true] : []

            content {
              prefix                   = try(rule.value.filter.prefix, try(rule.value.prefix, null))
              tags                     = try(rule.value.filter.tags, null)
              object_size_greater_than = try(rule.value.filter.object_size_greater_than, null)
              object_size_less_than    = try(rule.value.filter.object_size_less_than, null)
            }
          }

          prefix = (
            try(rule.value.filter.tags, null) != null ||
            try(rule.value.filter.object_size_greater_than, null) != null ||
            try(rule.value.filter.object_size_less_than, null) != null
          ) ? null : try(rule.value.filter.prefix, try(rule.value.prefix, null))
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value.expiration, null) == null ? [] : [rule.value.expiration]
        content {
          date                         = try(expiration.value.date, null)
          days                         = try(expiration.value.days, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transitions, null) != null ? rule.value.transitions : (
          try(rule.value.transition, null) != null ? try(tolist(rule.value.transition), [rule.value.transition]) : []
        )

        content {
          date          = try(transition.value.date, null)
          days          = try(transition.value.days, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration, null) == null ? [] : [rule.value.noncurrent_version_expiration]
        content {
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
          noncurrent_days           = try(noncurrent_version_expiration.value.noncurrent_days, null)
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value.noncurrent_version_transitions, null) != null ? rule.value.noncurrent_version_transitions : (
          try(rule.value.noncurrent_version_transition, null) != null ? try(tolist(rule.value.noncurrent_version_transition), [rule.value.noncurrent_version_transition]) : []
        )

        content {
          newer_noncurrent_versions = try(noncurrent_version_transition.value.newer_noncurrent_versions, null)
          noncurrent_days           = try(noncurrent_version_transition.value.noncurrent_days, null)
          storage_class             = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload, null) == null ? [] : [rule.value.abort_incomplete_multipart_upload]
        content {
          days_after_initiation = try(abort_incomplete_multipart_upload.value.days_after_initiation, null)
        }
      }
    }
  }
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count      = var.object_lock_configuration != null ? 1 : 0
  bucket     = aws_s3_bucket.this.id
  depends_on = [aws_s3_bucket_versioning.this]

  dynamic "rule" {
    for_each = var.object_lock_configuration != null ? [var.object_lock_configuration.default_retention] : []
    content {
      default_retention {
        mode  = rule.value.mode
        days  = try(rule.value.days, null)
        years = try(rule.value.years, null)
      }
    }
  }
}

resource "random_id" "replication_destination" {
  for_each   = local.replication_destinations
  byte_length = 4
}

resource "aws_s3_bucket" "replication_destination" {
  for_each      = local.replication_destinations
  bucket        = "cores3-replication-dest-${each.key}-${random_id.replication_destination[each.key].hex}"
  force_destroy = false
  tags = merge(var.tags, {
    ReplicationRegion = coalesce(try(each.value.destination_region, null), var.replication_region)
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replication_destination" {
  for_each = local.replication_destinations
  bucket   = aws_s3_bucket.replication_destination[each.key].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replication_destination" {
  for_each                = local.replication_destinations
  bucket                  = aws_s3_bucket.replication_destination[each.key].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replication_destination" {
  for_each = local.replication_destinations
  bucket   = aws_s3_bucket.replication_destination[each.key].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_logging" "replication_destination" {
  for_each = local.replication_destinations
  bucket   = aws_s3_bucket.replication_destination[each.key].id

  target_bucket = var.log_target_bucket != null && var.log_target_bucket != "" ? var.log_target_bucket : aws_s3_bucket.logging.id
  target_prefix = var.log_prefix != null ? var.log_prefix : "replication-destination/${each.key}/"
}

resource "aws_s3_bucket" "logging" {
  bucket        = "cores3-access-logs-${random_id.logging.hex}"
  force_destroy = false
  tags = merge(var.tags, {
    Name = "cores3-access-logs-${random_id.logging.hex}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logging" {
  bucket                  = aws_s3_bucket.logging.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "logging" {
  bucket = aws_s3_bucket.logging.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "logging" {
  bucket     = aws_s3_bucket.logging.id
  acl        = "log-delivery-write"
  depends_on = [aws_s3_bucket_ownership_controls.logging]
}

resource "aws_s3_bucket_versioning" "logging" {
  bucket = aws_s3_bucket.logging.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  bucket = aws_s3_bucket.logging.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_iam_role" "replication" {
  count = length(var.replication_rules) > 0 && var.replication_role_arn == "" ? 1 : 0
  name  = "CoreS3ReplicationRole_${local.bucket_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "replication" {
  count = length(var.replication_rules) > 0 && var.replication_role_arn == "" ? 1 : 0
  name  = "CoreS3ReplicationPolicy_${local.bucket_name}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetReplicationConfiguration",
          "s3:PutReplicationConfiguration"
        ]
        Resource = aws_s3_bucket.this.arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = "${aws_s3_bucket.this.arn}/*"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  count      = length(var.replication_rules) > 0 && var.replication_role_arn == "" ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count  = length(var.replication_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id
  role   = var.replication_role_arn != "" ? var.replication_role_arn : aws_iam_role.replication[0].arn

  depends_on = [
    aws_s3_bucket_versioning.this,
    aws_s3_bucket_versioning.replication_destination,
    aws_iam_role_policy_attachment.replication
  ]

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id       = try(rule.value.id, null)
      status   = try(rule.value.status, "Enabled")
      priority = try(rule.value.priority, null)

      dynamic "filter" {
        for_each = (
          try(rule.value.prefix, null) != null ||
          try(rule.value.filter.prefix, null) != null ||
          try(rule.value.filter.tags, null) != null
        ) ? [true] : []

        content {
          dynamic "and" {
            for_each = try(rule.value.filter.tags, null) != null ? [true] : []
            content {
              prefix = try(rule.value.filter.prefix, try(rule.value.prefix, null))
              tags   = try(rule.value.filter.tags, null)
            }
          }

          prefix = try(rule.value.filter.tags, null) != null ? null : try(rule.value.filter.prefix, try(rule.value.prefix, null))
        }
      }

      dynamic "destination" {
        for_each = [1]
        content {
          bucket        = rule.value.destination_bucket_arn != null && rule.value.destination_bucket_arn != "" ? rule.value.destination_bucket_arn : aws_s3_bucket.replication_destination[tostring(rule.key)].arn
          storage_class = try(rule.value.destination_storage_class, null)
          account       = try(rule.value.destination_account, null)

          dynamic "access_control_translation" {
            for_each = try(rule.value.access_control_translation, null) != null ? [rule.value.access_control_translation] : []
            content {
              owner = access_control_translation.value.owner
            }
          }

          dynamic "encryption_configuration" {
            for_each = try(rule.value.encryption_configuration, null) != null ? [rule.value.encryption_configuration] : []
            content {
              replica_kms_key_id = encryption_configuration.value.replica_kms_key_id
            }
          }
        }
      }

      dynamic "delete_marker_replication" {
        for_each = try(rule.value.delete_marker_replication_status, null) != null ? [rule.value.delete_marker_replication_status] : []
        content {
          status = delete_marker_replication.value
        }
      }

      dynamic "existing_object_replication" {
        for_each = try(rule.value.existing_object_replication_status, null) != null ? [rule.value.existing_object_replication_status] : []
        content {
          status = existing_object_replication.value
        }
      }

      dynamic "source_selection_criteria" {
        for_each = try(rule.value.source_selection_criteria, null) != null ? [rule.value.source_selection_criteria] : []
        content {
          dynamic "sse_kms_encrypted_objects" {
            for_each = try(source_selection_criteria.value.sse_kms_encrypted_objects, null) != null ? [source_selection_criteria.value.sse_kms_encrypted_objects] : []
            content {
              status = sse_kms_encrypted_objects.value.status
            }
          }
        }
      }
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "random_suffix" {
  description = "Whether to append a random suffix to resource names"
  type        = bool
  default     = true
}

variable "create_iam_user" {
  description = "Whether to create the IAM user, access key, and policy"
  type        = bool
  default     = true
}

variable "upload_image" {
  description = "Whether to upload an image file to the S3 bucket"
  type        = bool
  default     = false
}

variable "image_filename" {
  description = "Local filename of the image to upload"
  type        = string
  default     = "my-file.qcow2"
}

variable "s3_folder" {
  description = "Folder prefix for the uploaded image"
  type        = string
  default     = "my-folder"
}

variable "create_folder" {
  description = "Whether to include the folder prefix in the S3 key"
  type        = bool
  default     = true
}

variable "bucket_base_name" {
  description = "Base name for the S3 bucket"
  type        = string
  default     = "zedcloud"
}

variable "iam_username_base" {
  description = "Base name for the IAM user"
  type        = string
  default     = "zedcloud-s3-user"
}

variable "iam_policy_name_base" {
  description = "Base name for the IAM policy"
  type        = string
  default     = "zedcloud-s3-policy"
}

variable "random_suffix_length" {
  description = "Length of the random suffix"
  type        = number
  default     = 4
}

resource "random_string" "suffix" {
  length  = var.random_suffix_length
  special = false
  upper   = false
  lower   = true
  numeric = true
}

locals {
  resolved_bucket_name   = var.random_suffix ? "${var.bucket_base_name}-${random_string.suffix.result}" : var.bucket_base_name
  resolved_iam_username  = var.random_suffix ? "${var.iam_username_base}-${random_string.suffix.result}" : var.iam_username_base
  resolved_iam_policy_name = var.random_suffix ? "${var.iam_policy_name_base}-${random_string.suffix.result}" : var.iam_policy_name_base
  log_bucket_name        = "${local.resolved_bucket_name}-logs"
}

# KMS key for bucket encryption
resource "aws_kms_key" "storage_kms_key" {
  description             = "KMS key for S3 bucket SSE-KMS encryption"
  deletion_window_in_days = 7
  rotation_period_in_days = 365
  enable_key_rotation     = true
}

# Main application images bucket
resource "aws_s3_bucket" "app_images" {
  bucket        = local.resolved_bucket_name
  force_destroy = true
  tags = {
    Name = local.resolved_bucket_name
  }

  logging {
    target_bucket = aws_s3_bucket.log_bucket.id
    target_prefix = "s3-access-logs/"
  }

  versioning {
    enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "app_images_public_access_block" {
  bucket = aws_s3_bucket.app_images.id

  block_public_acls       = true
  ignore_public_acls      = true
  block_public_policy     = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "app_images_sse" {
  bucket = aws_s3_bucket.app_images.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.storage_kms_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# Log bucket for S3 access logs
resource "aws_s3_bucket" "log_bucket" {
  bucket        = local.log_bucket_name
  force_destroy = true
  tags = {
    Name = local.log_bucket_name
  }

  versioning {
    enabled = true
  }
}

resource "aws_s3_bucket_ownership_controls" "log_bucket_ownership" {
  bucket = aws_s3_bucket.log_bucket.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "log_bucket_acl" {
  depends_on = [aws_s3_bucket_ownership_controls.log_bucket_ownership]

  bucket = aws_s3_bucket.log_bucket.id
  acl    = "log-delivery-write"
}

resource "aws_s3_bucket_public_access_block" "log_bucket_public_access_block" {
  bucket = aws_s3_bucket.log_bucket.id

  block_public_acls       = true
  ignore_public_acls      = true
  block_public_policy     = true
  restrict_public_buckets = true
}

# IAM user and group (conditional)
resource "aws_iam_user" "app_images_user" {
  count = var.create_iam_user ? 1 : 0

  name          = local.resolved_iam_username
  force_destroy = true
  path          = "/"
}

resource "aws_iam_access_key" "app_images_user_key" {
  count = var.create_iam_user ? 1 : 0

  user = aws_iam_user.app_images_user[0].name
}

resource "aws_iam_policy" "app_images_policy" {
  count = var.create_iam_user ? 1 : 0

  name        = local.resolved_iam_policy_name
  description = "Read-only access to S3 bucket ${local.resolved_bucket_name}"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "s3:GetObject"
        Resource = "arn:aws:s3:::${local.resolved_bucket_name}/*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Effect   = "Allow"
        Action   = "s3:ListBucket"
        Resource = "arn:aws:s3:::${local.resolved_bucket_name}"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group" "app_images_group" {
  count = var.create_iam_user ? 1 : 0

  name = "${local.resolved_iam_username}-group"
  path = "/"
}

resource "aws_iam_group_policy_attachment" "app_images_group_policy_attachment" {
  count = var.create_iam_user ? 1 : 0

  group      = aws_iam_group.app_images_group[0].name
  policy_arn = aws_iam_policy.app_images_policy[0].arn
}

resource "aws_iam_group_membership" "app_images_group_membership" {
  count = var.create_iam_user ? 1 : 0

  name  = "${local.resolved_iam_username}-membership"
  group = aws_iam_group.app_images_group[0].name
  users = [aws_iam_user.app_images_user[0].name]
}

# Conditional image upload
resource "aws_s3_object" "uploaded_image" {
  count = var.upload_image ? 1 : 0

  bucket = aws_s3_bucket.app_images.id
  key    = var.create_folder ? "${var.s3_folder}/${var.image_filename}" : var.image_filename
  source = var.image_filename
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "default_tags" {
  type = map(string)
  default = {
    Project     = "tf-eks-jofo"
    Owner       = "Jovan Zelincevic"
    Compliance  = "Nothing"
    Environment = "dev"
    Provider    = "Terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = "10.14.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-vpc"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-public-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index + 3)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-private-${count.index}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-igw"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-nat-eip"
  }
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-nat"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_kms_key" "flow_log" {
  description             = "KMS key for VPC flow log CloudWatch log group encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-vpc-flow-log-key"
  }
}

resource "aws_kms_alias" "flow_log" {
  name_prefix   = "alias/${var.default_tags.Project}-${var.default_tags.Environment}-vpc-flow-logs-"
  target_key_id = aws_kms_key.flow_log.id
}

resource "aws_cloudwatch_log_group" "flow_log" {
  name              = "/aws/vpc-flow-logs/${var.default_tags.Project}-${var.default_tags.Environment}"
  retention_in_days = 30
  kms_key_id        = aws_kms_alias.flow_log.arn

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-flow-log-group"
  }
}

resource "aws_iam_role" "flow_log" {
  name_prefix = "${var.default_tags.Project}-${var.default_tags.Environment}-vpc-flow-log-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-vpc-flow-log-role"
  }
}

resource "aws_iam_role_policy" "flow_log" {
  name = "${var.default_tags.Project}-${var.default_tags.Environment}-vpc-flow-log-policy"
  role = aws_iam_role.flow_log.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${aws_cloudwatch_log_group.flow_log.name}:log-stream:*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "logs:DescribeLogGroups"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  iam_role_arn         = aws_iam_role.flow_log.arn
  log_destination      = aws_cloudwatch_log_group.flow_log.arn
  log_destination_type = "cloud-watch-logs"
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.main.id

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-flow-log"
  }
}

# Terraform metadata block
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0, < 6.0"
    }
  }
}

# Variables
variable "create_bucket" {
  description = "Controls whether the S3 bucket is created"
  type        = bool
  default     = true
}

variable "bucket" {
  description = "Name of the bucket. Must be globally unique."
  type        = string
  default     = null
}

variable "bucket_prefix" {
  description = "Prefix for bucket name. Conflicts with bucket."
  type        = string
  default     = null
}

variable "acl" {
  description = "Canned ACL to apply to the bucket"
  type        = string
  default     = "private"
}

variable "force_destroy" {
  description = "Allow deletion of non-empty bucket"
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}

variable "acceleration_status" {
  description = "Transfer Acceleration status (Enabled or Suspended)"
  type        = string
  default     = null
}

variable "request_payer" {
  description = "Request payer configuration (BucketOwner or Requester)"
  type        = string
  default     = null
}

variable "control_object_ownership" {
  description = "Enable object ownership controls"
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership setting (BucketOwnerPreferred, ObjectWriter, or BucketOwnerEnforced)"
  type        = string
  default     = "ObjectWriter"
}

variable "website" {
  description = "Static website hosting configuration"
  type        = any
  default     = null
}

variable "cors_rule" {
  description = "List of CORS rules"
  type        = list(any)
  default     = []
}

variable "versioning" {
  description = "Versioning configuration (map with status, mfa_delete, etc.)"
  type        = map(string)
  default     = {
    status = "Enabled"
  }
}

variable "logging" {
  description = "Logging configuration (target_bucket, target_prefix, target_object_key_format)"
  type        = map(string)
  default     = {}
}

variable "grants" {
  description = "List of ACL grants"
  type        = list(any)
  default     = []
}

variable "lifecycle_rule" {
  description = "List of lifecycle rules"
  type        = list(any)
  default     = []
}

variable "replication_configuration" {
  description = "Cross-region replication configuration"
  type        = any
  default     = null
}

variable "server_side_encryption_configuration" {
  description = "Server-side encryption configuration. If null, a KMS key is created."
  type        = any
  default     = null
}

variable "object_lock_configuration" {
  description = "Object lock configuration"
  type        = any
  default     = null
}

variable "attach_elb_log_delivery_policy" {
  description = "Attach ELB log delivery policy"
  type        = bool
  default     = false
}

variable "attach_lb_log_delivery_policy" {
  description = "Attach ALB/NLB log delivery policy"
  type        = bool
  default     = false
}

variable "attach_deny_insecure_transport_policy" {
  description = "Attach deny insecure transport policy"
  type        = bool
  default     = false
}

variable "attach_policy" {
  description = "Attach custom policy"
  type        = bool
  default     = false
}

variable "policy" {
  description = "Custom policy document JSON string"
  type        = string
  default     = ""
}

variable "attach_public_policy" {
  description = "Attach public access block"
  type        = bool
  default     = true
}

# Locals
locals {
  create_kms_key = var.create_bucket && var.server_side_encryption_configuration == null
  create_log_bucket = var.create_bucket && try(var.logging.target_bucket, null) == null
}

# Data sources
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_elb_service_account" "main" {
  region = data.aws_region.current.name
}
data "aws_canonical_user_id" "current" {}

data "aws_iam_policy_document" "combined_bucket_policy" {
  count = var.create_bucket ? 1 : 0

  source_policy_documents = var.attach_policy ? [var.policy] : []

  # ELB log delivery
  dynamic "statement" {
    for_each = var.attach_elb_log_delivery_policy ? [1] : []
    content {
      sid    = "ELBLogDelivery"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = [data.aws_elb_service_account.main.arn]
      }
      actions = [
        "s3:PutObject"
      ]
      resources = [
        "${aws_s3_bucket.this[0].arn}/*"
      ]
    }
  }

  # ALB/NLB log delivery
  dynamic "statement" {
    for_each = var.attach_lb_log_delivery_policy ? [1] : []
    content {
      sid    = "ALBLogDelivery"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = [data.aws_elb_service_account.main.arn]
      }
      actions = [
        "s3:PutObject"
      ]
      resources = [
        "${aws_s3_bucket.this[0].arn}/*"
      ]
    }
  }

  # ALB/NLB ACL check
  dynamic "statement" {
    for_each = var.attach_lb_log_delivery_policy ? [1] : []
    content {
      sid    = "ALBLogDeliveryAclCheck"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = [data.aws_elb_service_account.main.arn]
      }
      actions = [
        "s3:GetBucketAcl"
      ]
      resources = [
        aws_s3_bucket.this[0].arn
      ]
    }
  }

  # Deny insecure transport
  dynamic "statement" {
    for_each = var.attach_deny_insecure_transport_policy ? [1] : []
    content {
      sid    = "DenyInsecureTransport"
      effect = "Deny"
      principals {
        type        = "*"
        identifiers = ["*"]
      }
      actions = [
        "s3:*"
      ]
      resources = [
        aws_s3_bucket.this[0].arn,
        "${aws_s3_bucket.this[0].arn}/*"
      ]
      condition {
        test     = "Bool"
        variable = "aws:SecureTransport"
        values   = ["false"]
      }
    }
  }
}

# KMS key policy
data "aws_iam_policy_document" "kms_key" {
  count = local.create_kms_key ? 1 : 0
  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }
  statement {
    sid    = "Allow S3 Service to Use Key"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
  }
}

# S3 bucket (main)
resource "aws_s3_bucket" "this" {
  count         = var.create_bucket ? 1 : 0
  bucket        = var.bucket
  bucket_prefix = var.bucket_prefix
  force_destroy = var.force_destroy
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
    precondition {
      condition     = var.create_bucket == false || !(var.bucket != null && var.bucket_prefix != null)
      error_message = "At most one of `bucket` or `bucket_prefix` may be supplied; omitting both lets AWS generate a unique bucket name."
    }
  }
}

# Log bucket (created only when no target_bucket supplied)
resource "aws_s3_bucket" "log_bucket" {
  count         = local.create_log_bucket ? 1 : 0
  bucket        = "${replace(aws_s3_bucket.this[0].id, ".", "-")}-logs"
  force_destroy = var.force_destroy
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "log_bucket" {
  count  = local.create_log_bucket ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id

  rule {
    object_ownership = "ObjectWriter"
  }
}

resource "aws_s3_bucket_acl" "log_bucket" {
  count  = local.create_log_bucket ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id
  acl    = "log-delivery-write"

  depends_on = [aws_s3_bucket_ownership_controls.log_bucket]
}

resource "aws_s3_bucket_public_access_block" "log_bucket" {
  count                   = local.create_log_bucket ? 1 : 0
  bucket                  = aws_s3_bucket.log_bucket[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "log_bucket" {
  count  = local.create_log_bucket ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

# Bucket ACL (main)
resource "aws_s3_bucket_acl" "this" {
  count  = var.create_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  acl    = var.acl

  dynamic "access_control_policy" {
    for_each = length(var.grants) > 0 ? [1] : []
    content {
      owner {
        id = data.aws_canonical_user_id.current.id
      }
      dynamic "grant" {
        for_each = var.grants
        content {
          permission = grant.value.permission
          grantee {
            type          = grant.value.grantee.type
            email_address = try(grant.value.grantee.email_address, null)
            id            = try(grant.value.grantee.id, null)
            uri           = try(grant.value.grantee.uri, null)
          }
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

# Ownership controls (main) — always created when an ACL is applied
resource "aws_s3_bucket_ownership_controls" "this" {
  count  = var.create_bucket && (var.control_object_ownership || var.acl != null || length(var.grants) > 0) ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.object_ownership
  }
}

# Public access block (main)
resource "aws_s3_bucket_public_access_block" "this" {
  count                   = var.create_bucket && var.attach_public_policy ? 1 : 0
  bucket                  = aws_s3_bucket.this[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Versioning (main)
resource "aws_s3_bucket_versioning" "this" {
  count  = var.create_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  versioning_configuration {
    status     = try(var.versioning.status, "Enabled")
    mfa_delete = try(var.versioning.mfa_delete, null)
  }
}

# Server-side encryption
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count  = var.create_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = local.create_kms_key ? aws_kms_key.this[0].arn : try(var.server_side_encryption_configuration.rule[0].apply_server_side_encryption_by_default[0].kms_master_key_id, null)
      sse_algorithm     = local.create_kms_key ? "aws:kms" : try(var.server_side_encryption_configuration.rule[0].apply_server_side_encryption_by_default[0].sse_algorithm, "AES256")
    }
    bucket_key_enabled = try(var.server_side_encryption_configuration.rule[0].bucket_key_enabled, null)
  }
}

# KMS key
resource "aws_kms_key" "this" {
  count                   = local.create_kms_key ? 1 : 0
  description             = "KMS key for S3 bucket ${aws_s3_bucket.this[0].id}"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy                  = data.aws_iam_policy_document.kms_key[0].json
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "this" {
  count         = local.create_kms_key ? 1 : 0
  name          = "alias/s3-${replace(aws_s3_bucket.this[0].id, ".", "-")}"
  target_key_id = aws_kms_key.this[0].key_id
}

# Lifecycle
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = var.create_bucket && length(var.lifecycle_rule) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rule
    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload, null) != null ? [rule.value.abort_incomplete_multipart_upload] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value.expiration, null) != null ? [rule.value.expiration] : []
        content {
          date                         = try(expiration.value.date, null)
          days                         = try(expiration.value.days, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transition, [])
        content {
          date          = try(transition.value.date, null)
          days          = try(transition.value.days, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration, null) != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
          noncurrent_days           = noncurrent_version_expiration.value.noncurrent_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value.noncurrent_version_transition, [])
        content {
          newer_noncurrent_versions = try(noncurrent_version_transition.value.newer_noncurrent_versions, null)
          noncurrent_days           = noncurrent_version_transition.value.noncurrent_days
          storage_class             = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }
}

# CORS
resource "aws_s3_bucket_cors_configuration" "this" {
  count  = var.create_bucket && length(var.cors_rule) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rule
    content {
      allowed_headers = try(cors_rule.value.allowed_headers, [])
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, [])
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

# Website
resource "aws_s3_bucket_website_configuration" "this" {
  count  = var.create_bucket && var.website != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  index_document {
    suffix = try(var.website.index_document.suffix, "index.html")
  }

  dynamic "error_document" {
    for_each = try(var.website.error_document, null) != null ? [var.website.error_document] : []
    content {
      key = error_document.value.key
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = try(var.website.redirect_all_requests_to, null) != null ? [var.website.redirect_all_requests_to] : []
    content {
      host_name = redirect_all_requests_to.value.host_name
      protocol  = try(redirect_all_requests_to.value.protocol, null)
    }
  }

  dynamic "routing_rule" {
    for_each = try(var.website.routing_rules, [])
    content {
      condition {
        http_error_code_returned_equals = try(routing_rule.value.condition.http_error_code_returned_equals, null)
        key_prefix_equals               = try(routing_rule.value.condition.key_prefix_equals, null)
      }
      redirect {
        host_name               = try(routing_rule.value.redirect.host_name, null)
        http_redirect_code      = try(routing_rule.value.redirect.http_redirect_code, null)
        protocol                = try(routing_rule.value.redirect.protocol, null)
        replace_key_prefix_with = try(routing_rule.value.redirect.replace_key_prefix_with, null)
        replace_key_with        = try(routing_rule.value.redirect.replace_key_with, null)
      }
    }
  }
}

# Logging (main bucket) - always enabled when possible
resource "aws_s3_bucket_logging" "this" {
  count  = var.create_bucket && (try(var.logging.target_bucket, null) != null || local.create_log_bucket) ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  target_bucket = try(var.logging.target_bucket, aws_s3_bucket.log_bucket[0].id)
  target_prefix = try(var.logging.target_prefix, "logs/")

  dynamic "target_object_key_format" {
    for_each = try(var.logging.target_object_key_format, null) != null ? [var.logging.target_object_key_format] : []
    content {
      partitioned_prefix {
        partition_date_source = target_object_key_format.value.partitioned_prefix.partition_date_source
      }
    }
  }
}

# Request payer
resource "aws_s3_bucket_request_payment_configuration" "this" {
  count  = var.create_bucket && var.request_payer != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  payer  = var.request_payer
}

# Acceleration
resource "aws_s3_bucket_accelerate_configuration" "this" {
  count  = var.create_bucket && var.acceleration_status != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  status = var.acceleration_status
}

# Object lock
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = var.create_bucket && var.object_lock_configuration != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  object_lock_enabled = try(var.object_lock_configuration.object_lock_enabled, "Enabled")

  dynamic "rule" {
    for_each = try(var.object_lock_configuration.rule, null) != null ? [var.object_lock_configuration.rule] : []
    content {
      default_retention {
        mode  = rule.value.default_retention.mode
        days  = try(rule.value.default_retention.days, null)
        years = try(rule.value.default_retention.years, null)
      }
    }
  }
}

# Replication
resource "aws_s3_bucket_replication_configuration" "this" {
  count  = var.create_bucket && var.replication_configuration != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  role   = var.replication_configuration.role

  dynamic "rule" {
    for_each = var.replication_configuration.rules
    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "filter" {
        for_each = try(rule.value.filter, null) != null ? [rule.value.filter] : []
        content {
          prefix = try(filter.value.prefix, null)
          dynamic "tag" {
            for_each = try(filter.value.tags, [])
            content {
              key   = tag.value.key
              value = tag.value.value
            }
          }
        }
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = try(rule.value.destination.storage_class, null)
        dynamic "encryption_configuration" {
          for_each = try(rule.value.destination.encryption_configuration, null) != null ? [rule.value.destination.encryption_configuration] : []
          content {
            replica_kms_key_id = encryption_configuration.value.replica_kms_key_id
          }
        }
      }

      dynamic "source_selection_criteria" {
        for_each = try(rule.value.source_selection_criteria, null) != null ? [rule.value.source_selection_criteria] : []
        content {
          dynamic "sse_kms_encrypted_objects" {
            for_each = try(source_selection_criteria.value.sse_kms_encrypted_objects, null) != null ? [source_selection_criteria.value.sse_kms_encrypted_objects] : []
            content {
              status = sse_kms_encrypted_objects.value.status
            }
          }
        }
      }

      dynamic "delete_marker_replication" {
        for_each = try(rule.value.delete_marker_replication, null) != null ? [rule.value.delete_marker_replication] : []
        content {
          status = delete_marker_replication.value.status
        }
      }
    }
  }
}

# Bucket policy (combined) - only attach if at least one policy flag is true
resource "aws_s3_bucket_policy" "this" {
  count  = var.create_bucket && (var.attach_elb_log_delivery_policy || var.attach_lb_log_delivery_policy || var.attach_deny_insecure_transport_policy || var.attach_policy) ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.combined_bucket_policy[0].json
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "projectPrefix" {
  description = "Prefix for resource naming and tagging"
  type        = string
  default     = "f5-dcec"
}

variable "resourceOwner" {
  description = "Owner tag value"
  type        = string
  default     = "f5-user"
}

variable "buildSuffix" {
  description = "Suffix for resource naming and tagging"
  type        = string
  default     = "YY"
}

variable "map_public_ip_on_launch" {
  description = "Assign public IP to instances in public subnets"
  type        = bool
  default     = false
}

variable "awsRegion" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "vpcMainCidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.1.0.0/16"
}

variable "vpcMainSubPubACidr" {
  description = "CIDR block for public subnet A"
  type        = string
  default     = "10.1.10.0/24"
}

variable "vpcMainSubPubBCidr" {
  description = "CIDR block for public subnet B"
  type        = string
  default     = "10.1.110.0/24"
}

variable "vpcMainSubMgmtACidr" {
  description = "CIDR block for management subnet A"
  type        = string
  default     = "10.1.1.0/24"
}

variable "vpcMainSubMgmtBCidr" {
  description = "CIDR block for management subnet B"
  type        = string
  default     = "10.1.101.0/24"
}

variable "vpcMainSubPrivACidr" {
  description = "CIDR block for private subnet A"
  type        = string
  default     = "10.1.20.0/24"
}

variable "vpcMainSubPrivBCidr" {
  description = "CIDR block for private subnet B"
  type        = string
  default     = "10.1.120.0/24"
}

variable "awsAz1" {
  description = "First availability zone; defaults to first available AZ"
  type        = string
  default     = null
}

variable "awsAz2" {
  description = "Second availability zone; defaults to awsAz1 if set, else second available AZ"
  type        = string
  default     = null
}

# Data source for available AZs
data "aws_availability_zones" "available" {
  state = "available"
}

# Local AZ resolution
locals {
  az1 = coalesce(var.awsAz1, data.aws_availability_zones.available.names[0])
  az2 = coalesce(var.awsAz2, var.awsAz1, data.aws_availability_zones.available.names[1])
}

# Common tags
locals {
  common_tags = {
    projectPrefix = var.projectPrefix
    resourceOwner = var.resourceOwner
    buildSuffix   = var.buildSuffix
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpcMainCidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-vpc-${var.buildSuffix}"
  })
}

# KMS Key for CloudWatch Logs encryption
resource "aws_kms_key" "main" {
  description             = "KMS key for CloudWatch Logs encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${var.awsRegion}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
          "kms:CreateGrant"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-kms-cloudwatch-${var.buildSuffix}"
  })
}

# KMS Alias
resource "aws_kms_alias" "main" {
  name          = "alias/${var.projectPrefix}-cloudwatch-${var.buildSuffix}"
  target_key_id = aws_kms_key.main.key_id
}

# Data source for current account ID (used in KMS policy)
data "aws_caller_identity" "current" {}

# CloudWatch Log Group for VPC Flow Logs
resource "aws_cloudwatch_log_group" "main" {
  name = "${var.projectPrefix}-vpc-flow-logs-${var.buildSuffix}"
  kms_key_id = aws_kms_alias.main.arn

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-vpc-flow-logs-${var.buildSuffix}"
  })
}

# IAM Role for VPC Flow Logs
resource "aws_iam_role" "flow_logs" {
  name = "${var.projectPrefix}-flow-logs-role-${var.buildSuffix}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-flow-logs-role-${var.buildSuffix}"
  })
}

# IAM Policy for VPC Flow Logs delivery
resource "aws_iam_role_policy" "flow_logs" {
  name = "${var.projectPrefix}-flow-logs-policy-${var.buildSuffix}"
  role = aws_iam_role.flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = aws_cloudwatch_log_group.main.arn
      }
    ]
  })
}

# VPC Flow Logs
resource "aws_flow_log" "main" {
  log_destination      = aws_cloudwatch_log_group.main.arn
  log_destination_type = "cloud-watch-logs"
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.main.id
  iam_role_arn         = aws_iam_role.flow_logs.arn

  depends_on = [aws_iam_role_policy.flow_logs]

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-flow-log-${var.buildSuffix}"
  })
}

# Public subnets
resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-public-a-${var.buildSuffix}"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-public-b-${var.buildSuffix}"
  })
}

# Management subnets
resource "aws_subnet" "mgmt_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubMgmtACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-mgmt-a-${var.buildSuffix}"
  })
}

resource "aws_subnet" "mgmt_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubMgmtBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-mgmt-b-${var.buildSuffix}"
  })
}

# Private subnets
resource "aws_subnet" "priv_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPrivACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-priv-a-${var.buildSuffix}"
  })
}

resource "aws_subnet" "priv_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPrivBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-priv-b-${var.buildSuffix}"
  })
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-igw-${var.buildSuffix}"
  })
}

# Route table
resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-rt-main-${var.buildSuffix}"
  })
}

# Main route table association
resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.main.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Resource name"
  type        = string
  default     = "benchmark"
}

variable "listener_rule_count" {
  description = "Number of listener rules to create"
  type        = number
  default     = 1
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.name
  }
}

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 0)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = var.name
  }
}

resource "aws_subnet" "secondary" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 1)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = var.name
  }
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.name
  }
}

resource "aws_route_table_association" "main" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.main.id
}

resource "aws_route_table_association" "secondary" {
  subnet_id      = aws_subnet.secondary.id
  route_table_id = aws_route_table.main.id
}

resource "aws_security_group" "main" {
  name        = var.name
  description = "Security group for ${var.name} ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow all inbound traffic within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = var.name
  }
}

resource "tls_private_key" "main" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "main" {
  private_key_pem = tls_private_key.main.private_key_pem

  subject {
    common_name = "benchmark.local"
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "main" {
  private_key      = tls_private_key.main.private_key_pem
  certificate_body = tls_self_signed_cert.main.cert_pem
}

resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for ${var.name} CloudWatch log group encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${var.region}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = var.name
  }
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/cloudwatch-${var.name}"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

resource "aws_cloudwatch_log_group" "flow_log" {
  name              = "/aws/vpc-flow-logs/${var.name}"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.cloudwatch.arn

  tags = {
    Name   = var.name
    Region = var.region
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "flow_log" {
  name = var.name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = var.name
  }
}

resource "aws_iam_role_policy" "flow_log" {
  name = var.name
  role = aws_iam_role.flow_log.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  log_group_name = aws_cloudwatch_log_group.flow_log.name
  iam_role_arn   = aws_iam_role.flow_log.arn
  traffic_type   = "ALL"
  vpc_id         = aws_vpc.main.id

  depends_on = [
    aws_iam_role_policy.flow_log
  ]

  tags = {
    Name = var.name
  }
}

resource "aws_lb" "main" {
  name                       = var.name
  internal                   = true
  load_balancer_type         = "application"
  drop_invalid_header_fields = true
  security_groups            = [aws_security_group.main.id]
  subnets                    = [aws_subnet.main.id, aws_subnet.secondary.id]

  tags = {
    Name = var.name
  }
}

resource "aws_lb_target_group" "main" {
  name     = var.name
  port     = 8080
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    enabled             = true
    interval            = 60
    path                = "/health"
    port                = 8081
    protocol            = "HTTP"
    timeout             = 3
    healthy_threshold   = 3
    unhealthy_threshold = 3
    matcher             = "200-299"
  }

  tags = {
    Name = var.name
  }
}

resource "aws_lb_listener" "main" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.main.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

resource "aws_lb_listener_rule" "main" {
  count        = var.listener_rule_count
  listener_arn = aws_lb_listener.main.arn
  priority     = 100 + count.index

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  condition {
    path_pattern {
      values = ["/static-${count.index}/*"]
    }
  }
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

# Variables
variable "trail_name" {
  description = "Name of the CloudTrail trail"
  type        = string
  default     = "management_trail"
}

variable "log_group_name" {
  description = "Name of the CloudWatch Log Group"
  type        = string
  default     = "cloudtrail_logs"
}

variable "enable_organization_trail" {
  description = "Enable organization trail"
  type        = bool
  default     = false
}

variable "enable_kms_encryption" {
  description = "Enable KMS encryption for the trail and S3 bucket"
  type        = bool
  default     = true
}

variable "kms_key_alias" {
  description = "Alias for the KMS key"
  type        = string
  default     = "alias/cloudtrail_key"
}

# Data sources for static metadata
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# Random string for bucket name suffix
resource "random_string" "bucket_suffix" {
  length  = 12
  special = false
  upper   = false
  lower   = false
  numeric = true
}

# KMS key (only if enable_kms_encryption is true)
resource "aws_kms_key" "cloudtrail" {
  count                   = var.enable_kms_encryption ? 1 : 0
  description             = "Customer managed key for CloudTrail log encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAdmin"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudTrailUse"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowS3UseForBucketEncryption"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = "arn:${data.aws_partition.current.partition}:s3:::cloudtrail-bucket-${random_string.bucket_suffix.result}"
          }
        }
      },
      {
        Sid    = "AllowCloudWatchLogsUse"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowAccountDecrypt"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:Decrypt"
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = data.aws_caller_identity.current.account_id
          }
        }
      },
      {
        Sid    = "AllowCallerAdmin"
        Effect = "Allow"
        Principal = {
          AWS = data.aws_caller_identity.current.arn
        }
        Action = [
          "kms:Create*",
          "kms:Describe*",
          "kms:Enable*",
          "kms:List*",
          "kms:Put*",
          "kms:Update*",
          "kms:Revoke*",
          "kms:Disable*",
          "kms:Get*",
          "kms:Delete*",
          "kms:Tag*",
          "kms:Untag*",
          "kms:ScheduleKeyDeletion",
          "kms:CancelKeyDeletion"
        ]
        Resource = "*"
      }
    ]
  })
}

# KMS key alias (only if enable_kms_encryption is true)
resource "aws_kms_alias" "cloudtrail" {
  count         = var.enable_kms_encryption ? 1 : 0
  name          = var.kms_key_alias
  target_key_id = aws_kms_key.cloudtrail[0].key_id
}

import {
  to = aws_kms_alias.cloudtrail[0]
  id = "alias/cloudtrail_key"
}

# S3 bucket for CloudTrail logs
resource "aws_s3_bucket" "cloudtrail" {
  bucket        = "cloudtrail-bucket-${random_string.bucket_suffix.result}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

# Block public access to the bucket
resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Server-side encryption configuration
resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.enable_kms_encryption ? "aws:kms" : "AES256"
      kms_master_key_id = var.enable_kms_encryption ? aws_kms_key.cloudtrail[0].arn : null
    }
  }
}

# Enable versioning on the bucket
resource "aws_s3_bucket_versioning" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  versioning_configuration {
    status = "Enabled"
  }
}

# Bucket policy to allow CloudTrail access
resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AWSCloudTrailAclCheck"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.cloudtrail.arn
      },
      {
        Sid    = "AWSCloudTrailWrite"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.cloudtrail.arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

# S3 bucket for access logs (server access logging)
resource "aws_s3_bucket" "access_logs" {
  bucket        = "cloudtrail-access-logs-${random_string.bucket_suffix.result}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

# Public access block for the access logs bucket
resource "aws_s3_bucket_public_access_block" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Enable versioning on the access logs bucket
resource "aws_s3_bucket_versioning" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

# Bucket policy to allow S3 Log Delivery to write access logs
resource "aws_s3_bucket_policy" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ServerAccessLogWrite"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.access_logs.arn}/*"
      }
    ]
  })
}

# Configure server access logging for the CloudTrail bucket
resource "aws_s3_bucket_logging" "cloudtrail" {
  bucket        = aws_s3_bucket.cloudtrail.id
  target_bucket = aws_s3_bucket.access_logs.id
  target_prefix = "cloudtrail-access-logs/"
}

# CloudWatch Log Group for CloudTrail logs
resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = var.log_group_name
  retention_in_days = 0
  kms_key_id        = var.enable_kms_encryption ? aws_kms_key.cloudtrail[0].arn : null

  lifecycle {
    prevent_destroy = true
  }
}

import {
  to = aws_cloudwatch_log_group.cloudtrail
  id = var.log_group_name
}

# IAM role for CloudTrail to write to CloudWatch Logs
resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name = "CloudTrailRoleForCloudWatchLogs"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudTrailAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

import {
  to = aws_iam_role.cloudtrail_cloudwatch
  id = "CloudTrailRoleForCloudWatchLogs"
}

# Inline policy for CloudWatch Logs access
resource "aws_iam_role_policy" "cloudtrail_cloudwatch" {
  name   = "allow-access-to-cw-logs"
  role   = aws_iam_role.cloudtrail_cloudwatch.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudTrailCreateLogStreamAndPutEvents"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
      }
    ]
  })
}

# CloudTrail trail
resource "aws_cloudtrail" "main" {
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail.id
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  include_global_service_events = true
  is_organization_trail         = var.enable_organization_trail

  cloud_watch_logs_group_arn = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn  = aws_iam_role.cloudtrail_cloudwatch.arn

  kms_key_id = var.enable_kms_encryption ? aws_kms_key.cloudtrail[0].arn : null

  event_selector {
    read_write_type           = "All"
    include_management_events = true
  }

  depends_on = [
    aws_s3_bucket_policy.cloudtrail,
    aws_iam_role_policy.cloudtrail_cloudwatch
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

variable "namespace" {
  type    = string
  default = ""
}

variable "repository_name" {
  type    = string
  default = null
}

variable "image_tag_mutability" {
  type    = string
  default = "IMMUTABLE"
}

variable "scan_on_push" {
  type    = bool
  default = true
}

variable "lifecycle_policy" {
  type    = string
  default = null
}

variable "trusted_accounts" {
  type    = list(string)
  default = []
}

data "aws_caller_identity" "current" {}

resource "random_pet" "this" {
  length    = 2
  separator = "-"
}

locals {
  effective_repository_name = var.repository_name != null && var.repository_name != "" ? var.repository_name : random_pet.this.id
  repo_name_path            = var.namespace != "" ? "${var.namespace}/${local.effective_repository_name}" : local.effective_repository_name
  local_name                = join("", [for c in split("", local.repo_name_path) : can(regex("^[a-zA-Z0-9+=,.@_-]$", c)) ? c : "_"])
}

data "aws_iam_policy_document" "ecr_kms_key_policy" {
  statement {
    sid    = "AllowECRService"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["ecr.amazonaws.com"]
    }

    actions = [
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:CreateGrant",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowRootAdmin"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = ["kms:*"]

    resources = ["*"]
  }
}

resource "aws_kms_key" "ecr" {
  description         = "KMS key for ECR repository image encryption"
  enable_key_rotation = true
  policy              = data.aws_iam_policy_document.ecr_kms_key_policy.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecr_repository" "main" {
  name                 = local.repo_name_path
  image_tag_mutability = var.image_tag_mutability

  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }

  encryption_configuration {
    encryption_type = "KMS"
    kms_key         = aws_kms_key.ecr.arn
  }

  tags = {
    "terraform.io" = "managed"
    "Name"         = local.repo_name_path
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecr_lifecycle_policy" "main" {
  count      = var.lifecycle_policy != null ? 1 : 0
  repository = aws_ecr_repository.main.name
  policy     = var.lifecycle_policy
}

data "aws_iam_policy_document" "ecr_read" {
  statement {
    sid    = "ECRReadAccess"
    effect = "Allow"

    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:GetAuthorizationToken",
      "ecr:GetDownloadUrlForLayer",
      "ecr:ListImages",
    ]

    resources = [
      aws_ecr_repository.main.arn,
    ]
  }
}

data "aws_iam_policy_document" "ecr_write" {
  statement {
    sid    = "ECRWriteAccess"
    effect = "Allow"

    actions = [
      "ecr:PutImage",
      "ecr:UploadLayerPart",
      "ecr:InitiateLayerUpload",
      "ecr:CompleteLayerUpload",
    ]

    resources = [
      aws_ecr_repository.main.arn,
    ]
  }
}

resource "aws_iam_policy" "ecr_read" {
  name   = "${local.local_name}-ecr-read"
  policy = data.aws_iam_policy_document.ecr_read.json
}

resource "aws_iam_policy" "ecr_write" {
  name   = "${local.local_name}-ecr-write"
  policy = data.aws_iam_policy_document.ecr_write.json
}

data "aws_iam_policy_document" "ecr_repository_policy" {
  statement {
    sid    = "AllowCrossAccountAccess"
    effect = "Allow"

    principals {
      type = "AWS"

      identifiers = concat(
        [data.aws_caller_identity.current.account_id],
        var.trusted_accounts,
      )
    }

    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:GetDownloadUrlForLayer",
      "ecr:ListImages",
    ]
  }
}

resource "aws_ecr_repository_policy" "main" {
  repository = aws_ecr_repository.main.name
  policy     = data.aws_iam_policy_document.ecr_repository_policy.json
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "availability_zone_count" {
  description = "Number of availability zones to use"
  type        = number
  default     = 2
}

variable "enable_public_subnets" {
  description = "Enable the public subnet tier"
  type        = bool
  default     = true
}

variable "enable_nat_subnets" {
  description = "Enable the NAT subnet tier"
  type        = bool
  default     = true
}

variable "enable_private_subnets" {
  description = "Enable the private subnet tier"
  type        = bool
  default     = true
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

locals {
  selected_azs              = slice(data.aws_availability_zones.available.names, 0, var.availability_zone_count)
  public_subnet_count       = var.enable_public_subnets ? var.availability_zone_count : 0
  nat_subnet_count          = var.enable_nat_subnets ? var.availability_zone_count : 0
  private_subnet_count      = var.enable_private_subnets ? var.availability_zone_count : 0
  total_active_subnet_count = local.public_subnet_count + local.nat_subnet_count + local.private_subnet_count
  newbits                   = local.total_active_subnet_count > 0 ? ceil(log(local.total_active_subnet_count, 2)) : 0
  name_prefix               = "multi-tier"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.name_prefix
  }
}

resource "aws_subnet" "public" {
  count = var.enable_public_subnets ? var.availability_zone_count : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, local.newbits, count.index)
  availability_zone       = local.selected_azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-public-${count.index + 1}"
  }
}

resource "aws_subnet" "nat" {
  count = var.enable_nat_subnets ? var.availability_zone_count : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, local.newbits, local.public_subnet_count + count.index)
  availability_zone       = local.selected_azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-nat-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = var.enable_private_subnets ? var.availability_zone_count : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, local.newbits, local.public_subnet_count + local.nat_subnet_count + count.index)
  availability_zone       = local.selected_azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-private-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "main" {
  count = var.enable_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

resource "aws_security_group" "public" {
  count = var.enable_public_subnets ? 1 : 0

  name        = "public"
  description = "Security group for public subnets"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow all outbound traffic within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${local.name_prefix}-public-sg"
  }
}

resource "aws_route_table" "public" {
  count = var.enable_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-public-rt"
  }
}

resource "aws_route" "public_internet_access" {
  count = var.enable_public_subnets ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main[0].id
}

resource "aws_route_table_association" "public" {
  count = var.enable_public_subnets ? var.availability_zone_count : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_kms_key" "flow_logs" {
  description             = "KMS key for VPC Flow Logs encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowVPCFlowLogs"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogs"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "${local.name_prefix}-flow-logs-kms"
  }
}

resource "aws_kms_alias" "flow_logs" {
  name          = "alias/vpc-flow-logs"
  target_key_id = aws_kms_key.flow_logs.key_id
}

resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = "/aws/vpc-flow-logs/${local.name_prefix}"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.flow_logs.arn
}

resource "aws_iam_role" "flow_logs" {
  name = "vpc-flow-logs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "flow_logs" {
  name = "vpc-flow-logs-policy"
  role = aws_iam_role.flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = aws_cloudwatch_log_group.flow_logs.arn
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext"
        ]
        Resource = aws_kms_key.flow_logs.arn
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  log_destination = aws_cloudwatch_log_group.flow_logs.arn
  iam_role_arn    = aws_iam_role.flow_logs.arn
  traffic_type    = "ALL"
  vpc_id          = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-flow-log"
  }
}

# Terraform and Provider Configuration
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

# Variables
variable "project" {
  description = "Project name"
  type        = string
  default     = "demo"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "poc"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "demo-dataflow"
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.3.0/24"]
}

variable "bastion_key_name" {
  description = "Name of the EC2 key pair for the bastion host"
  type        = string
  default     = "kplinuxdemo"
}

variable "bastion_instance_type" {
  description = "EC2 instance type for the bastion host"
  type        = string
  default     = "t3.nano"
}

variable "bastion_ebs_optimized" {
  description = "Whether the bastion instance is EBS optimized"
  type        = bool
  default     = false
}

variable "bastion_ssh_cidr" {
  description = "CIDR block allowed to SSH into the bastion host (restrict to trusted IPs)"
  type        = string
  default     = "10.0.0.0/16"  # Restricted default – override with specific IP in production
}

variable "tags" {
  description = "A map of tags to apply to all resources"
  type        = map(string)
  default     = {}
}

# Local values
locals {
  common_tags = merge(
    var.tags,
    {
      Project     = var.project
      Environment = var.environment
    }
  )
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

data "aws_caller_identity" "current" {}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = var.vpc_name
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Internet Gateway
resource "aws_internet_gateway" "demogw" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "demogwInternet"
    }
  )
}

# Public Subnets
resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(["10.0.0.0/24", "10.0.2.0/24"], count.index)
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project}-${var.environment}-public-${count.index + 1}"
      Type = "Public"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Public Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.demogw.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "demoPublicRouteTable"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Public Route Table Associations
resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private Subnets
resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project}-${var.environment}-private-${count.index + 1}"
      Type = "Private"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Private Route Table (local route only – implicit)
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project}-${var.environment}-private-rt"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Private Route Table Associations
resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# SSH Key Pair (uses name_prefix to avoid duplicate collisions)
resource "tls_private_key" "bastion" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "bastion" {
  key_name_prefix = "${var.bastion_key_name}-"
  public_key      = tls_private_key.bastion.public_key_openssh

  tags = merge(
    local.common_tags,
    {
      Name = var.bastion_key_name
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Bastion Security Group
resource "aws_security_group" "bastion" {
  name        = "${var.project}-${var.environment}-bastion-sg"
  description = "Security group for bastion host"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from allowed CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.bastion_ssh_cidr]
  }

  egress {
    description = "Allow outbound traffic to VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project}-${var.environment}-bastion-sg"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Bastion EC2 Instance
resource "aws_instance" "bastion" {
  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = var.bastion_instance_type
  key_name               = aws_key_pair.bastion.key_name
  subnet_id              = aws_subnet.public[0].id
  vpc_security_group_ids = [aws_security_group.bastion.id]
  ebs_optimized          = var.bastion_ebs_optimized

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    encrypted  = true
    kms_key_id = aws_kms_key.ebs.arn
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project}-${var.environment}-bastion"
    }
  )
}

# EBS Encryption KMS Key (no alias – use ARN directly)
resource "aws_kms_key" "ebs" {
  description             = "KMS key for EBS volume encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  is_enabled              = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow EC2 to use the key"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = [
          "kms:DescribeKey",
          "kms:CreateGrant",
          "kms:Decrypt",
          "kms:GenerateDataKey*",
          "kms:ReEncrypt*"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project}-${var.environment}-ebs-key"
    }
  )
}

# VPC Flow Logs – KMS Key for encryption (no alias – use ARN directly)
resource "aws_kms_key" "flow_logs" {
  description             = "KMS key for VPC Flow Logs CloudWatch Logs encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${var.region}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project}-${var.environment}-flow-logs-key"
    }
  )
}

# VPC Flow Logs – CloudWatch Log Group (uses name_prefix)
resource "aws_cloudwatch_log_group" "flow_logs" {
  name_prefix       = "/aws/vpc-flow-logs/${var.project}-${var.environment}-"
  retention_in_days = 7
  kms_key_id        = aws_kms_key.flow_logs.arn

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project}-${var.environment}-flow-logs"
    }
  )
}

# VPC Flow Logs – IAM Role (uses name_prefix)
resource "aws_iam_role" "flow_logs" {
  name_prefix = "${var.project}-${var.environment}-flow-logs-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "flow_logs" {
  name = "${var.project}-${var.environment}-flow-logs-policy"
  role = aws_iam_role.flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:DescribeLogGroups",
          "logs:PutLogEvents",
          "logs:PutRetentionPolicy"
        ]
        Resource = "${aws_cloudwatch_log_group.flow_logs.arn}:*"
      }
    ]
  })
}

# VPC Flow Logs
resource "aws_flow_log" "main" {
  iam_role_arn    = aws_iam_role.flow_logs.arn
  log_destination = aws_cloudwatch_log_group.flow_logs.arn
  traffic_type    = "ALL"
  vpc_id          = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project}-${var.environment}-vpc-flow-log"
    }
  )
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  alias = "primary"
}

provider "aws" {
  alias  = "secondary"
  region = var.secondary_region
}

variable "secondary_region" {
  type        = string
  default     = "us-west-2"
  description = "Secondary AWS region for cross-region backup vault copies."
}

variable "enable_cross_account_copy" {
  type        = bool
  default     = true
  description = "Whether to add a cross-account copy action to each backup plan."
}

variable "cross_account_destination_vault_arn" {
  type        = string
  default     = "arn:aws:backup:us-east-1:433568766270:backup-vault:cross-account-backup-vault"
  description = "ARN of the destination backup vault in the target account for cross-account copies."
}

variable "excluded_rds_arns" {
  type        = list(string)
  default     = []
  description = "List of RDS DB instance ARNs to exclude from backup selections."
}

variable "enable_daily_backup" {
  type        = bool
  default     = true
  description = "Whether to create the daily backup plan."
}

resource "aws_iam_role" "backup" {
  name = "aws-backup-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_kms_key" "primary" {
  description             = "Primary Backup Vault Key"
  key_usage               = "ENCRYPT_DECRYPT"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_key" "secondary" {
  provider                = aws.secondary
  description             = "Secondary Backup Vault Key"
  key_usage               = "ENCRYPT_DECRYPT"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_backup_vault" "primary" {
  name        = "primary-backup-vault"
  kms_key_arn = aws_kms_key.primary.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "secondary" {
  provider    = aws.secondary
  name        = "secondary-backup-vault"
  kms_key_arn = aws_kms_key.secondary.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_plan" "daily" {
  count = var.enable_daily_backup ? 1 : 0
  name  = "daily-backup-plan"

  rule {
    rule_name         = "daily-backup"
    target_vault_name = aws_backup_vault.primary.name
    schedule          = "cron(0 2 * * ? *)"

    lifecycle {
      delete_after = 7
    }

    copy_action {
      destination_vault_arn = aws_backup_vault.secondary.arn
    }

    dynamic "copy_action" {
      for_each = var.enable_cross_account_copy ? [1] : []
      content {
        destination_vault_arn = var.cross_account_destination_vault_arn
      }
    }
  }
}

resource "aws_backup_plan" "weekly" {
  name = "weekly-backup-plan"

  rule {
    rule_name         = "weekly-backup"
    target_vault_name = aws_backup_vault.primary.name
    schedule          = "cron(0 2 ? * SAT *)"

    lifecycle {
      delete_after = 30
    }

    copy_action {
      destination_vault_arn = aws_backup_vault.secondary.arn
    }

    dynamic "copy_action" {
      for_each = var.enable_cross_account_copy ? [1] : []
      content {
        destination_vault_arn = var.cross_account_destination_vault_arn
      }
    }
  }
}

resource "aws_backup_plan" "monthly" {
  name = "monthly-backup-plan"

  rule {
    rule_name         = "monthly-backup"
    target_vault_name = aws_backup_vault.primary.name
    schedule          = "cron(0 3 1 * ? *)"

    lifecycle {
      delete_after = 365
    }

    copy_action {
      destination_vault_arn = aws_backup_vault.secondary.arn
    }

    dynamic "copy_action" {
      for_each = var.enable_cross_account_copy ? [1] : []
      content {
        destination_vault_arn = var.cross_account_destination_vault_arn
      }
    }
  }
}

resource "aws_backup_plan" "yearly" {
  name = "yearly-backup-plan"

  rule {
    rule_name         = "yearly-backup"
    target_vault_name = aws_backup_vault.primary.name
    schedule          = "cron(0 4 1 1 ? *)"

    lifecycle {
      delete_after = 2555
    }

    copy_action {
      destination_vault_arn = aws_backup_vault.secondary.arn
    }

    dynamic "copy_action" {
      for_each = var.enable_cross_account_copy ? [1] : []
      content {
        destination_vault_arn = var.cross_account_destination_vault_arn
      }
    }
  }
}

resource "aws_backup_selection" "daily" {
  count         = var.enable_daily_backup ? 1 : 0
  name          = "daily-backup-selection"
  plan_id       = aws_backup_plan.daily[0].id
  iam_role_arn  = aws_iam_role.backup.arn
  resources     = ["arn:aws:rds:*:*:db:*"]
  not_resources = var.excluded_rds_arns

  depends_on = [aws_iam_role_policy_attachment.backup]
}

resource "aws_backup_selection" "weekly" {
  name          = "weekly-backup-selection"
  plan_id       = aws_backup_plan.weekly.id
  iam_role_arn  = aws_iam_role.backup.arn
  resources     = ["arn:aws:rds:*:*:db:*"]
  not_resources = var.excluded_rds_arns

  depends_on = [aws_iam_role_policy_attachment.backup]
}

resource "aws_backup_selection" "monthly" {
  name          = "monthly-backup-selection"
  plan_id       = aws_backup_plan.monthly.id
  iam_role_arn  = aws_iam_role.backup.arn
  resources     = ["arn:aws:rds:*:*:db:*"]
  not_resources = var.excluded_rds_arns

  depends_on = [aws_iam_role_policy_attachment.backup]
}

resource "aws_backup_selection" "yearly" {
  name          = "yearly-backup-selection"
  plan_id       = aws_backup_plan.yearly.id
  iam_role_arn  = aws_iam_role.backup.arn
  resources     = ["arn:aws:rds:*:*:db:*"]
  not_resources = var.excluded_rds_arns

  depends_on = [aws_iam_role_policy_attachment.backup]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "allow_users_to_change_password" {
  description = "Whether users can change their own password."
  type        = bool
  default     = true
}

variable "hard_expiry" {
  description = "Whether users must change their password after it expires."
  type        = bool
  default     = false
}

variable "max_password_age" {
  description = "Number of days before an IAM user password expires."
  type        = number
  default     = 90
}

variable "minimum_password_length" {
  description = "Minimum number of characters allowed in an IAM user password."
  type        = number
  default     = 14
}

variable "password_reuse_prevention" {
  description = "Number of previous passwords that cannot be reused."
  type        = number
  default     = 24
}

variable "require_lowercase_characters" {
  description = "Whether passwords must contain at least one lowercase character."
  type        = bool
  default     = true
}

variable "require_uppercase_characters" {
  description = "Whether passwords must contain at least one uppercase character."
  type        = bool
  default     = true
}

variable "require_numbers" {
  description = "Whether passwords must contain at least one number."
  type        = bool
  default     = true
}

variable "require_symbols" {
  description = "Whether passwords must contain at least one non-alphanumeric character."
  type        = bool
  default     = true
}

resource "aws_iam_account_password_policy" "this" {
  allow_users_to_change_password = var.allow_users_to_change_password
  hard_expiry                    = var.hard_expiry
  max_password_age               = var.max_password_age
  minimum_password_length        = var.minimum_password_length
  password_reuse_prevention      = var.password_reuse_prevention
  require_lowercase_characters   = var.require_lowercase_characters
  require_uppercase_characters   = var.require_uppercase_characters
  require_numbers                = var.require_numbers
  require_symbols                = var.require_symbols
}

resource "aws_iam_group" "administrators" {
  name = "administrators"
}

resource "aws_iam_group" "developpers" {
  name = "developpers"
}

resource "aws_iam_group" "prod_users" {
  name = "prod_users"
}

data "aws_iam_policy_document" "developpers_policy_doc" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:*",
      "rds:*",
    ]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/env"
      values   = ["dev"]
    }
  }
}

resource "aws_iam_policy" "developpers_policy" {
  name   = "developpers_policy"
  policy = data.aws_iam_policy_document.developpers_policy_doc.json
}

data "aws_iam_policy_document" "prod_users_policy_doc" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:*",
      "rds:*",
    ]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/env"
      values   = ["preprod", "prod"]
    }
  }
}

resource "aws_iam_policy" "prod_users_policy" {
  name   = "prod_users_policy"
  policy = data.aws_iam_policy_document.prod_users_policy_doc.json
}

data "aws_iam_policy_document" "administrators_policy_doc" {
  statement {
    effect = "Allow"
    not_actions = [
      "iam:*",
      "organizations:*",
      "account:*",
    ]
    resources = ["*"]

    condition {
      test     = "StringNotEquals"
      variable = "aws:ResourceTag/security"
      values   = ["high"]
    }
  }

  statement {
    effect = "Allow"
    actions = [
      "iam:CreateServiceLinkedRole",
      "iam:DeleteServiceLinkedRole",
      "iam:ListRoles",
      "organizations:DescribeOrganization",
      "account:ListRegions",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "administrators_policy" {
  name   = "administrators_policy"
  policy = data.aws_iam_policy_document.administrators_policy_doc.json
}

resource "aws_iam_group_policy_attachment" "administrators_policy_attachment" {
  group      = aws_iam_group.administrators.name
  policy_arn = aws_iam_policy.administrators_policy.arn
}

resource "aws_iam_group_policy_attachment" "developpers_policy_attachment" {
  group      = aws_iam_group.developpers.name
  policy_arn = aws_iam_policy.developpers_policy.arn
}

resource "aws_iam_group_policy_attachment" "prod_users_policy_attachment" {
  group      = aws_iam_group.prod_users.name
  policy_arn = aws_iam_policy.prod_users_policy.arn
}

data "aws_iam_policy_document" "mfa_enforcement" {
  statement {
    effect = "Deny"
    actions = [
      "*",
    ]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }
}

resource "aws_iam_group_policy" "mfa_administrators" {
  name   = "mfa_enforcement"
  group  = aws_iam_group.administrators.name
  policy = data.aws_iam_policy_document.mfa_enforcement.json
}

resource "aws_iam_group_policy" "mfa_developpers" {
  name   = "mfa_enforcement"
  group  = aws_iam_group.developpers.name
  policy = data.aws_iam_policy_document.mfa_enforcement.json
}

resource "aws_iam_group_policy" "mfa_prod_users" {
  name   = "mfa_enforcement"
  group  = aws_iam_group.prod_users.name
  policy = data.aws_iam_policy_document.mfa_enforcement.json
}

terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix for resource names"
  type        = string
  default     = "tfm-aws"
}

variable "instance_tenancy" {
  description = "Instance tenancy for VPC"
  type        = string
  default     = "default"
}

variable "vpc_cidr" {
  description = "CIDR block for VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnets" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.2.0/24", "10.0.3.0/24"]
}

variable "public_inbound_acl_rules" {
  description = "Inbound ACL rules"
  type = list(object({
    rule_number = number
    protocol    = string
    from_port   = number
    to_port     = number
    cidr_block  = string
  }))
  default = [
    {
      rule_number = 100
      protocol    = "tcp"
      from_port   = 32768
      to_port     = 65535
      cidr_block  = "0.0.0.0/0"
    }
  ]
}

variable "public_outbound_acl_rules" {
  description = "Outbound ACL rules"
  type = list(object({
    rule_number = number
    protocol    = string
    from_port   = number
    to_port     = number
    cidr_block  = string
  }))
  default = [
    {
      rule_number = 100
      protocol    = "tcp"
      from_port   = 443
      to_port     = 443
      cidr_block  = "0.0.0.0/0"
    }
  ]
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true
  instance_tenancy     = var.instance_tenancy
  tags = {
    Name = "${var.name_prefix}-vpc"
  }
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnets[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name = "${var.name_prefix}-private-subnet-${count.index}"
  }
}

resource "aws_route_table" "private" {
  count  = 2
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${var.name_prefix}-private-rt-${count.index}"
  }
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3_gateway" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id
}

resource "aws_network_acl" "private" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = aws_subnet.private[*].id
  tags = {
    Name = "${var.name_prefix}-private-nacl"
  }
}

resource "aws_network_acl_rule" "inbound" {
  for_each = { for idx, rule in var.public_inbound_acl_rules : idx => rule }
  network_acl_id = aws_network_acl.private.id
  rule_number    = each.value.rule_number
  protocol       = each.value.protocol
  rule_action    = "allow"
  cidr_block     = each.value.cidr_block
  from_port      = each.value.from_port
  to_port        = each.value.to_port
  egress         = false
}

resource "aws_network_acl_rule" "outbound" {
  for_each = { for idx, rule in var.public_outbound_acl_rules : idx => rule }
  network_acl_id = aws_network_acl.private.id
  rule_number    = each.value.rule_number
  protocol       = each.value.protocol
  rule_action    = "allow"
  cidr_block     = each.value.cidr_block
  from_port      = each.value.from_port
  to_port        = each.value.to_port
  egress         = true
}

resource "aws_kms_key" "flow_log" {
  description         = "${var.name_prefix}-vpc-flow-logs-encryption-key"
  enable_key_rotation = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "logs.${var.region}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "flow_log" {
  name          = "alias/${var.name_prefix}-vpc-flow-logs"
  target_key_id = aws_kms_key.flow_log.arn
}

resource "aws_cloudwatch_log_group" "flow_log" {
  name       = "${var.name_prefix}-vpc-flow-logs"
  kms_key_id = aws_kms_alias.flow_log.arn
}

resource "aws_iam_role" "flow_log" {
  name = "${var.name_prefix}-vpc-flow-logs-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "flow_log" {
  name = "${var.name_prefix}-vpc-flow-logs-policy"
  role = aws_iam_role.flow_log.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams",
          "logs:DescribeLogGroups"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_flow_log" "vpc" {
  vpc_id               = aws_vpc.main.id
  traffic_type         = "REJECT"
  iam_role_arn         = aws_iam_role.flow_log.arn
  log_destination      = aws_cloudwatch_log_group.flow_log.arn
  log_destination_type = "cloud-watch-logs"
}

# Terraform configuration
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Variables
variable "namespace" {
  description = "Namespace for the null-label context"
  type        = string
  default     = "default"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "dev"
}

variable "name" {
  description = "Name for the null-label context"
  type        = string
  default     = "vpc"
}

variable "attributes" {
  description = "Additional attributes for the null-label"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags"
  type        = map(string)
  default     = {}
}

variable "ipv4_primary_cidr_block" {
  description = "Primary IPv4 CIDR block for the VPC"
  type        = string
  default     = "11.0.0.0/16"
}

variable "instance_tenancy" {
  description = "Instance tenancy for the VPC"
  type        = string
  default     = "default"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "assign_generated_ipv6_cidr_block" {
  description = "Assign a generated IPv6 CIDR block"
  type        = bool
  default     = true
}

variable "ipv4_ipam_pool_id" {
  description = "IPv4 IPAM pool ID (optional)"
  type        = string
  default     = null
}

variable "ipv4_netmask_length" {
  description = "Netmask length for IPv4 IPAM allocation"
  type        = number
  default     = null
}

variable "ipv6_ipam_pool_id" {
  description = "IPv6 IPAM pool ID (optional)"
  type        = string
  default     = null
}

variable "ipv6_netmask_length" {
  description = "Netmask length for IPv6 IPAM allocation"
  type        = number
  default     = null
}

variable "additional_ipv4_cidr_block_associations" {
  description = "Map of additional IPv4 CIDR block associations"
  type = map(object({
    cidr_block    = optional(string)
    ipam_pool_id  = optional(string)
    netmask_length = optional(number)
    create_timeout = optional(string, "10m")
    delete_timeout = optional(string, "10m")
  }))
  default = {}
}

variable "additional_ipv6_cidr_block_associations" {
  description = "Map of additional IPv6 CIDR block associations"
  type = map(object({
    cidr_block    = optional(string)
    ipam_pool_id  = optional(string)
    netmask_length = optional(number)
    create_timeout = optional(string, "10m")
    delete_timeout = optional(string, "10m")
  }))
  default = {}
}

variable "default_security_group_deny_all" {
  description = "Deny all rules in default security group"
  type        = bool
  default     = true
}

variable "manage_default_route_table" {
  description = "Manage default route table"
  type        = bool
  default     = false
}

variable "manage_default_network_acl" {
  description = "Manage default network ACL"
  type        = bool
  default     = false
}

variable "internet_gateway_enabled" {
  description = "Create an internet gateway"
  type        = bool
  default     = true
}

variable "ipv6_egress_only_internet_gateway_enabled" {
  description = "Create an IPv6 egress-only internet gateway"
  type        = bool
  default     = false
}

variable "vpc_flow_logs_enabled" {
  description = "Enable VPC Flow Logs"
  type        = bool
  default     = true
}

# Null-label module
module "this" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = var.attributes
  tags        = var.tags
}

# Primary VPC
resource "aws_vpc" "this" {
  cidr_block                       = var.ipv4_ipam_pool_id != null ? null : var.ipv4_primary_cidr_block
  ipv4_ipam_pool_id                = var.ipv4_ipam_pool_id
  ipv4_netmask_length              = var.ipv4_ipam_pool_id != null ? var.ipv4_netmask_length : null
  instance_tenancy                 = var.instance_tenancy
  enable_dns_hostnames             = var.enable_dns_hostnames
  enable_dns_support               = var.enable_dns_support
  assign_generated_ipv6_cidr_block = var.ipv6_ipam_pool_id != null ? false : var.assign_generated_ipv6_cidr_block
  ipv6_ipam_pool_id                = var.ipv6_ipam_pool_id
  ipv6_netmask_length              = var.ipv6_ipam_pool_id != null ? var.ipv6_netmask_length : null

  tags = module.this.tags
}

# Additional IPv4 CIDR block associations
resource "aws_vpc_ipv4_cidr_block_association" "this" {
  for_each = var.additional_ipv4_cidr_block_associations

  vpc_id            = aws_vpc.this.id
  cidr_block        = lookup(each.value, "ipam_pool_id", null) != null ? null : each.value.cidr_block
  ipv4_ipam_pool_id = lookup(each.value, "ipam_pool_id", null)
  ipv4_netmask_length = lookup(each.value, "ipam_pool_id", null) != null ? each.value.netmask_length : null

  timeouts {
    create = try(each.value.create_timeout, "10m")
    delete = try(each.value.delete_timeout, "10m")
  }
}

# Additional IPv6 CIDR block associations
resource "aws_vpc_ipv6_cidr_block_association" "this" {
  for_each = var.additional_ipv6_cidr_block_associations

  vpc_id             = aws_vpc.this.id
  ipv6_cidr_block    = lookup(each.value, "ipam_pool_id", null) != null ? null : each.value.cidr_block
  ipv6_ipam_pool_id  = lookup(each.value, "ipam_pool_id", null)
  ipv6_netmask_length = lookup(each.value, "ipam_pool_id", null) != null ? each.value.netmask_length : null

  timeouts {
    create = try(each.value.create_timeout, "10m")
    delete = try(each.value.delete_timeout, "10m")
  }
}

# Default Security Group (deny-all)
resource "aws_default_security_group" "this" {
  count = var.default_security_group_deny_all ? 1 : 0

  vpc_id = aws_vpc.this.id

  revoke_rules_on_delete = true

  tags = module.this.tags
}

# Default Route Table (reset)
resource "aws_default_route_table" "this" {
  count = var.manage_default_route_table ? 1 : 0

  default_route_table_id = aws_vpc.this.default_route_table_id

  tags = module.this.tags
}

# Default Network ACL (deny-all)
resource "aws_default_network_acl" "this" {
  count = var.manage_default_network_acl ? 1 : 0

  default_network_acl_id = aws_vpc.this.default_network_acl_id

  tags = module.this.tags
}

# Internet Gateway (IPv4 + IPv6)
resource "aws_internet_gateway" "this" {
  count = var.internet_gateway_enabled ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = module.this.tags
}

# IPv6 Egress-Only Internet Gateway
resource "aws_egress_only_internet_gateway" "this" {
  count = var.ipv6_egress_only_internet_gateway_enabled ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = module.this.tags
}

# VPC Flow Logs resources
resource "aws_kms_key" "flow_logs" {
  count = var.vpc_flow_logs_enabled ? 1 : 0

  description         = "KMS key for VPC Flow Logs encryption"
  enable_key_rotation = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowFlowLogsRole"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.flow_logs[0].arn
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogs"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = module.this.tags
}

resource "aws_kms_alias" "flow_logs" {
  count = var.vpc_flow_logs_enabled ? 1 : 0

  name          = "alias/vpc-flow-logs-${module.this.id}"
  target_key_id = aws_kms_key.flow_logs[0].key_id
}

resource "aws_cloudwatch_log_group" "flow_logs" {
  count = var.vpc_flow_logs_enabled ? 1 : 0

  name              = "/aws/vpc-flow-logs/${module.this.id}"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.flow_logs[0].arn

  tags = module.this.tags
}

resource "aws_iam_role" "flow_logs" {
  count = var.vpc_flow_logs_enabled ? 1 : 0

  name = module.this.id

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })

  tags = module.this.tags
}

resource "aws_iam_policy" "flow_logs" {
  count = var.vpc_flow_logs_enabled ? 1 : 0

  name        = "${module.this.id}-flow-logs"
  description = "Custom policy for VPC Flow Logs"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      }
    ]
  })

  tags = module.this.tags
}

resource "aws_iam_role_policy_attachment" "flow_logs" {
  count = var.vpc_flow_logs_enabled ? 1 : 0

  role       = aws_iam_role.flow_logs[0].name
  policy_arn = aws_iam_policy.flow_logs[0].arn
}

resource "aws_flow_log" "this" {
  count = var.vpc_flow_logs_enabled ? 1 : 0

  vpc_id               = aws_vpc.this.id
  log_destination      = aws_cloudwatch_log_group.flow_logs[0].arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.flow_logs[0].arn
  traffic_type         = "ALL"

  tags = module.this.tags
}

# Data source for current account ID (static provider metadata)
data "aws_caller_identity" "current" {}

# Outputs
output "vpc_id" {
  value = aws_vpc.this.id
}

output "vpc_arn" {
  value = aws_vpc.this.arn
}

output "vpc_primary_ipv4_cidr_block" {
  value = aws_vpc.this.cidr_block
}

output "vpc_primary_ipv6_cidr_block" {
  value = aws_vpc.this.ipv6_cidr_block
}

output "additional_ipv4_cidr_block_associations" {
  value = values(aws_vpc_ipv4_cidr_block_association.this)[*].cidr_block
}

output "additional_ipv6_cidr_block_associations" {
  value = values(aws_vpc_ipv6_cidr_block_association.this)[*].ipv6_cidr_block
}

output "default_security_group_id" {
  value = try(aws_default_security_group.this[0].id, null)
}

output "default_route_table_id" {
  value = try(aws_default_route_table.this[0].id, null)
}

output "default_network_acl_id" {
  value = try(aws_default_network_acl.this[0].id, null)
}

output "internet_gateway_id" {
  value = try(aws_internet_gateway.this[0].id, null)
}

output "egress_only_internet_gateway_id" {
  value = try(aws_egress_only_internet_gateway.this[0].id, null)
}

output "vpc_flow_log_id" {
  value = try(aws_flow_log.this[0].id, null)
}

output "vpc_flow_log_log_group_name" {
  value = try(aws_cloudwatch_log_group.flow_logs[0].name, null)
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "existing_vpc_id" {
  type    = string
  default = ""
}

variable "environment" {
  type    = string
  default = "DEV"
}

variable "vpc_cidr_block" {
  type    = string
  default = "10.0.0.0/16"
}

variable "create_private_subnet" {
  type    = bool
  default = false
}

variable "nat_eip_private_ip" {
  type    = string
  default = "10.0.0.5"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

locals {
  vpc_id                  = var.existing_vpc_id != "" ? var.existing_vpc_id : aws_vpc.main[0].id
  internet_cidr           = "0.0.0.0/0"
  vpc_flow_log_group_name = "/aws/vpc/flow-logs/${var.environment}"
  vpc_flow_log_group_arn  = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${local.vpc_flow_log_group_name}"
  common_tags = {
    Environment = var.environment
  }
}

data "aws_iam_policy_document" "flow_log_kms" {
  statement {
    sid       = "Enable IAM User Permissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid       = "Allow CloudWatch Logs to use the key"
    effect    = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["logs.amazonaws.com"]
    }

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = [local.vpc_flow_log_group_arn]
    }
  }
}

data "aws_iam_policy_document" "flow_log_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "flow_log_permissions" {
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]
    resources = [
      local.vpc_flow_log_group_arn,
      "${local.vpc_flow_log_group_arn}:log-stream:*",
    ]
  }
}

resource "aws_vpc" "main" {
  count                = var.existing_vpc_id == "" ? 1 : 0
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.environment}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = local.vpc_id

  tags = merge(local.common_tags, {
    Name = "${var.environment}-igw"
  })
}

resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = local.vpc_id
  cidr_block        = cidrsubnet(var.vpc_cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "${var.environment}-public-subnet-${count.index + 1}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = local.vpc_id

  route {
    cidr_block = local.internet_cidr
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_subnet" "private" {
  count             = var.create_private_subnet ? 2 : 0
  vpc_id            = local.vpc_id
  cidr_block        = cidrsubnet(var.vpc_cidr_block, 8, count.index + 10)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "${var.environment}-private-subnet-${count.index + 1}"
  })
}

resource "aws_route_table" "private" {
  count  = var.create_private_subnet ? 1 : 0
  vpc_id = local.vpc_id

  route {
    cidr_block     = local.internet_cidr
    nat_gateway_id = aws_nat_gateway.nat[0].id
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count          = var.create_private_subnet ? 2 : 0
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_eip" "nat" {
  count                     = var.create_private_subnet ? 1 : 0
  domain                    = "vpc"
  associate_with_private_ip = var.nat_eip_private_ip

  tags = merge(local.common_tags, {
    Name = "${var.environment}-nat-eip"
  })
}

resource "aws_nat_gateway" "nat" {
  count         = var.create_private_subnet ? 1 : 0
  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id
  depends_on    = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "${var.environment}-nat"
  })
}

resource "aws_kms_key" "flow_log" {
  count               = var.existing_vpc_id == "" ? 1 : 0
  description         = "KMS key for VPC Flow Log encryption"
  enable_key_rotation = true
  policy              = data.aws_iam_policy_document.flow_log_kms.json

  tags = local.common_tags
}

resource "aws_kms_alias" "flow_log" {
  count         = var.existing_vpc_id == "" ? 1 : 0
  name          = "alias/${var.environment}-vpc-flow-logs"
  target_key_id = aws_kms_key.flow_log[0].key_id
}

resource "aws_cloudwatch_log_group" "flow_log" {
  count             = var.existing_vpc_id == "" ? 1 : 0
  name              = local.vpc_flow_log_group_name
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.flow_log[0].arn
  depends_on        = [aws_kms_key.flow_log]

  tags = local.common_tags
}

resource "aws_iam_role" "flow_log" {
  count              = var.existing_vpc_id == "" ? 1 : 0
  name               = "${var.environment}-vpc-flow-log-role"
  assume_role_policy = data.aws_iam_policy_document.flow_log_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy" "flow_log" {
  count  = var.existing_vpc_id == "" ? 1 : 0
  name   = "${var.environment}-vpc-flow-log-policy"
  role   = aws_iam_role.flow_log[0].id
  policy = data.aws_iam_policy_document.flow_log_permissions.json
}

resource "aws_flow_log" "main" {
  count                = var.existing_vpc_id == "" ? 1 : 0
  vpc_id               = aws_vpc.main[0].id
  log_destination      = aws_cloudwatch_log_group.flow_log[0].arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.flow_log[0].arn
  traffic_type         = "ALL"
  depends_on = [
    aws_cloudwatch_log_group.flow_log,
    aws_iam_role.flow_log,
    aws_iam_role_policy.flow_log,
  ]

  tags = local.common_tags
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# ----------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ----------------------------------------------------------------------------------------------------------------------

variable "create" {
  description = "Whether to create the primary SQS queue and all dependent resources."
  type        = bool
  default     = true
}

variable "name" {
  description = "The name of the SQS queue. If not set, `name_prefix` is used."
  type        = string
  default     = null
}

variable "name_prefix" {
  description = "A prefix to use for the queue name. If not set, a default prefix is used."
  type        = string
  default     = null
}

variable "fifo_queue" {
  description = "Whether the queue is a FIFO queue."
  type        = bool
  default     = false
}

variable "delay_seconds" {
  description = "The time in seconds that the delivery of all messages in the queue will be delayed."
  type        = number
  default     = 0
}

variable "max_message_size" {
  description = "The limit of how many bytes a message can contain before Amazon SQS rejects it."
  type        = number
  default     = 262144
}

variable "message_retention_seconds" {
  description = "The number of seconds Amazon SQS retains a message."
  type        = number
  default     = 345600
}

variable "receive_wait_time_seconds" {
  description = "The time for which a ReceiveMessage call will wait for a message to arrive."
  type        = number
  default     = 0
}

variable "visibility_timeout_seconds" {
  description = "The visibility timeout for the queue."
  type        = number
  default     = 30
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO queues."
  type        = bool
  default     = false
}

variable "deduplication_scope" {
  description = "Specifies whether message deduplication occurs at the message group or queue level. Valid values are `messageGroup` and `queue`."
  type        = string
  default     = "queue"
}

variable "fifo_throughput_limit" {
  description = "Specifies whether the FIFO queue throughput quota applies to the entire queue or per message group. Valid values are `perQueue` and `perMessageGroupId`."
  type        = string
  default     = "perQueue"
}

variable "sqs_managed_sse_enabled" {
  description = "Whether to use SQS managed server-side encryption (SSE). This is used only when `kms_master_key_id` is not set."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "The ID of a customer managed KMS key to use for SSE. If not set, SQS managed SSE is used (controlled by `sqs_managed_sse_enabled`)."
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "The length of time, in seconds, for which Amazon SQS can reuse a data key to encrypt or decrypt messages before calling KMS again."
  type        = number
  default     = 300
}

variable "create_queue_policy" {
  description = "Whether to create a queue policy."
  type        = bool
  default     = false
}

variable "source_policy_documents" {
  description = "List of IAM policy documents (JSON strings) that are merged as source documents for the queue policy."
  type        = list(string)
  default     = []
}

variable "override_policy_documents" {
  description = "List of IAM policy documents (JSON strings) that are merged as override documents for the queue policy."
  type        = list(string)
  default     = []
}

variable "policy_statements" {
  description = "List of statement objects to include in the queue policy. Each object can contain any valid statement attributes. If `resources` is omitted, it defaults to the queue ARN."
  type = list(object({
    sid           = optional(string)
    effect        = optional(string, "Allow")
    actions       = list(string)
    resources     = optional(list(string))
    principals    = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    not_principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    conditions    = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = []
}

variable "create_dlq" {
  description = "Whether to create a dead-letter queue."
  type        = bool
  default     = false
}

variable "dlq_name" {
  description = "The name of the dead-letter queue. If not set, the name is derived from the main queue name or prefix by appending `-dlq`."
  type        = string
  default     = null
}

variable "dlq_name_prefix" {
  description = "A prefix to use for the dead-letter queue name. If not set, the prefix is derived from the main queue name or prefix."
  type        = string
  default     = null
}

variable "max_receive_count" {
  description = "The number of times a message can be received before being sent to the dead-letter queue."
  type        = number
  default     = 5
}

variable "create_dlq_redrive_allow_policy" {
  description = "Whether to attach a redrive allow policy to the dead-letter queue that restricts redrive permissions to the main queue."
  type        = bool
  default     = true
}

variable "tags" {
  description = "A map of tags to assign to all resources."
  type        = map(string)
  default     = {}
}

# ----------------------------------------------------------------------------------------------------------------------
# LOCALS
# ----------------------------------------------------------------------------------------------------------------------

locals {
  # Resolve an effective prefix when the caller does not supply an explicit one.
  effective_name_prefix = var.name_prefix != null ? var.name_prefix : "sqs-queue"

  # Main queue name. Only used when var.name is set, or for FIFO queues without an explicit name.
  main_queue_name = var.name != null ? (
    var.fifo_queue ? (
      endswith(var.name, ".fifo") ? var.name : "${var.name}.fifo"
    ) : var.name
  ) : (
    var.fifo_queue && var.create ? (
      "${local.effective_name_prefix}${random_id.main_queue_name_suffix[0].hex}.fifo"
    ) : null
  )

  # Main queue prefix. Only used for standard queues when no explicit name is set.
  main_queue_name_prefix = var.name == null && !var.fifo_queue ? local.effective_name_prefix : null

  # DLQ naming – purely from input variables, no queue resource references.
  # Precedence: explicit dlq_name > explicit dlq_name_prefix > derived from var.name > derived from effective prefix.

  dlq_name_explicit = var.dlq_name != null ? (
    var.fifo_queue ? (
      endswith(var.dlq_name, ".fifo") ? var.dlq_name : "${var.dlq_name}.fifo"
    ) : var.dlq_name
  ) : null

  dlq_name_prefix_explicit = var.dlq_name_prefix != null ? (
    var.fifo_queue ? (
      var.create && var.create_dlq ? "${var.dlq_name_prefix}${random_id.dlq_name_suffix[0].hex}.fifo" : null
    ) : var.dlq_name_prefix
  ) : null

  dlq_name_from_name = var.name != null ? (
    var.fifo_queue ? (
      endswith(var.name, ".fifo") ? replace(var.name, ".fifo", "-dlq.fifo") : "${var.name}-dlq.fifo"
    ) : "${var.name}-dlq"
  ) : null

  dlq_name_from_prefix = var.name == null && var.create && var.create_dlq ? (
    var.fifo_queue ? "${local.effective_name_prefix}${random_id.main_queue_name_suffix[0].hex}-dlq.fifo" : null
  ) : null

  dlq_name_prefix_from_prefix = var.name == null && var.create && var.create_dlq ? (
    var.fifo_queue ? null : "${local.effective_name_prefix}-dlq"
  ) : null

  dlq_name = var.dlq_name != null ? local.dlq_name_explicit : (
    var.dlq_name_prefix != null && var.fifo_queue ? local.dlq_name_prefix_explicit : (
      var.name != null ? local.dlq_name_from_name : (
        var.fifo_queue ? local.dlq_name_from_prefix : null
      )
    )
  )

  dlq_name_prefix = var.dlq_name != null ? null : (
    var.dlq_name_prefix != null && !var.fifo_queue ? local.dlq_name_prefix_explicit : (
      var.name != null ? null : (
        !var.fifo_queue ? local.dlq_name_prefix_from_prefix : null
      )
    )
  )
}

# ----------------------------------------------------------------------------------------------------------------------
# RANDOM ID FOR NAME_PREFIX (FIFO)
# ----------------------------------------------------------------------------------------------------------------------

resource "random_id" "main_queue_name_suffix" {
  count       = var.create && var.fifo_queue && var.name == null ? 1 : 0
  byte_length = 4
}

resource "random_id" "dlq_name_suffix" {
  count       = var.create && var.create_dlq && var.fifo_queue && var.dlq_name_prefix != null ? 1 : 0
  byte_length = 4
}

# ----------------------------------------------------------------------------------------------------------------------
# MAIN SQS QUEUE
# ----------------------------------------------------------------------------------------------------------------------

resource "aws_sqs_queue" "this" {
  count = var.create ? 1 : 0

  name        = local.main_queue_name
  name_prefix = local.main_queue_name_prefix

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  delay_seconds               = var.delay_seconds
  max_message_size            = var.max_message_size
  message_retention_seconds   = var.message_retention_seconds
  receive_wait_time_seconds   = var.receive_wait_time_seconds
  visibility_timeout_seconds  = var.visibility_timeout_seconds

  sqs_managed_sse_enabled = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : false
  kms_master_key_id       = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_data_key_reuse_period_seconds

  redrive_policy = var.create && var.create_dlq ? jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount     = var.max_receive_count
  }) : null

  tags = var.tags

  lifecycle {
    precondition {
      condition     = var.create ? !(var.name != null && var.name_prefix != null) : true
      error_message = "Only one of `name` or `name_prefix` may be set when `create = true`; both cannot be specified together."
    }
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------------------------------------------------------
# QUEUE POLICY (ATTACHED SEPARATELY)
# ----------------------------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "queue_policy" {
  count = var.create && var.create_queue_policy ? 1 : 0

  source_policy_documents   = var.source_policy_documents
  override_policy_documents = var.override_policy_documents

  dynamic "statement" {
    for_each = var.policy_statements

    content {
      sid       = statement.value.sid
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = try(length(statement.value.resources), 0) > 0 ? statement.value.resources : [aws_sqs_queue.this[0].arn]

      dynamic "principals" {
        for_each = statement.value.principals != null ? statement.value.principals : []
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = statement.value.not_principals != null ? statement.value.not_principals : []
        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.conditions != null ? statement.value.conditions : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.this[0].id
  policy    = data.aws_iam_policy_document.queue_policy[0].json
}

# ----------------------------------------------------------------------------------------------------------------------
# DEAD-LETTER QUEUE
# ----------------------------------------------------------------------------------------------------------------------

resource "aws_sqs_queue" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  name        = local.dlq_name
  name_prefix = local.dlq_name_prefix

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  delay_seconds               = var.delay_seconds
  max_message_size            = var.max_message_size
  message_retention_seconds   = var.message_retention_seconds
  receive_wait_time_seconds   = var.receive_wait_time_seconds
  visibility_timeout_seconds  = var.visibility_timeout_seconds

  sqs_managed_sse_enabled = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : false
  kms_master_key_id       = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_data_key_reuse_period_seconds

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------------------------------------------------------
# DLQ REDRIVE ALLOW POLICY
# ----------------------------------------------------------------------------------------------------------------------

resource "aws_sqs_queue_policy" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "RedriveAllowPolicy"
        Effect    = "Allow"
        Principal = "*"
        Action    = "sqs:Redrive"
        Resource  = aws_sqs_queue.dlq[0].arn
        Condition = {
          ArnEquals = {
            "aws:SourceArn" = aws_sqs_queue.this[0].arn
          }
        }
      }
    ]
  })
}

# ----------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ----------------------------------------------------------------------------------------------------------------------

output "queue_id" {
  description = "The URL of the main SQS queue."
  value       = try(aws_sqs_queue.this[0].id, null)
}

output "queue_arn" {
  description = "The ARN of the main SQS queue."
  value       = try(aws_sqs_queue.this[0].arn, null)
}

output "queue_name" {
  description = "The name of the main SQS queue."
  value       = try(aws_sqs_queue.this[0].name, null)
}

output "queue_url" {
  description = "The URL of the main SQS queue."
  value       = try(aws_sqs_queue.this[0].url, null)
}

output "queue_policy" {
  description = "The rendered JSON policy document attached to the main queue, if any."
  value       = try(data.aws_iam_policy_document.queue_policy[0].json, null)
}

output "dlq_id" {
  description = "The URL of the dead-letter queue."
  value       = try(aws_sqs_queue.dlq[0].id, null)
}

output "dlq_arn" {
  description = "The ARN of the dead-letter queue."
  value       = try(aws_sqs_queue.dlq[0].arn, null)
}

output "dlq_name" {
  description = "The name of the dead-letter queue."
  value       = try(aws_sqs_queue.dlq[0].name, null)
}

output "dlq_url" {
  description = "The URL of the dead-letter queue."
  value       = try(aws_sqs_queue.dlq[0].url, null)
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# IAM Users
# ------------------------------------------------------------------------------
resource "aws_iam_user" "loadbalancer" {
  name          = "loadbalancer"
  path          = "/system/"
  force_destroy = false
}

resource "aws_iam_user" "loadbalancer2" {
  name          = "loadbalancer2"
  path          = "/system/"
  force_destroy = false
}

resource "aws_iam_user" "loadbalancer3" {
  name          = "loadbalancer3"
  path          = "/system/"
  force_destroy = false
}

# ------------------------------------------------------------------------------
# Access Keys (Active)
# ------------------------------------------------------------------------------
resource "aws_iam_access_key" "loadbalancer_key" {
  user   = aws_iam_user.loadbalancer.name
  status = "Active"
}

resource "aws_iam_access_key" "loadbalancer2_key" {
  user   = aws_iam_user.loadbalancer2.name
  status = "Active"
}

resource "aws_iam_access_key" "loadbalancer3_key" {
  user   = aws_iam_user.loadbalancer3.name
  status = "Active"
}

# ------------------------------------------------------------------------------
# IAM Groups
# ------------------------------------------------------------------------------
resource "aws_iam_group" "loadbalancer" {
  name = "loadbalancer"
  path = "/system/"
}

resource "aws_iam_group" "loadbalancer2" {
  name = "loadbalancer2"
  path = "/system/"
}

resource "aws_iam_group" "loadbalancer3" {
  name = "loadbalancer3"
  path = "/system/"
}

# ------------------------------------------------------------------------------
# Policy Documents (reusable statements)
# ------------------------------------------------------------------------------
locals {
  ec2_describe_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "ec2:Describe*"
        Resource = "*"
      }
    ]
  })

  mfa_enforcement_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "ec2:Describe*"
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = ["true"]
          }
        }
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Group Policies for loadbalancer group
# ------------------------------------------------------------------------------
resource "aws_iam_group_policy" "loadbalancer_test" {
  group  = aws_iam_group.loadbalancer.name
  name   = "test"
  policy = local.ec2_describe_policy
}

resource "aws_iam_group_policy" "loadbalancer_test2" {
  group  = aws_iam_group.loadbalancer.name
  name   = "test2"
  policy = local.ec2_describe_policy
}

resource "aws_iam_group_policy" "loadbalancer_test3" {
  group  = aws_iam_group.loadbalancer.name
  name   = "test3"
  policy = local.ec2_describe_policy
}

resource "aws_iam_group_policy" "loadbalancer_test4" {
  group  = aws_iam_group.loadbalancer.name
  name   = "test4"
  policy = local.ec2_describe_policy
}

resource "aws_iam_group_policy" "loadbalancer_mfa" {
  group  = aws_iam_group.loadbalancer.name
  name   = "mfa"
  policy = local.mfa_enforcement_policy
}

# ------------------------------------------------------------------------------
# Group Policies for loadbalancer2 group
# ------------------------------------------------------------------------------
resource "aws_iam_group_policy" "loadbalancer2_test2" {
  group  = aws_iam_group.loadbalancer2.name
  name   = "test2"
  policy = local.ec2_describe_policy
}

resource "aws_iam_group_policy" "loadbalancer2_test22" {
  group  = aws_iam_group.loadbalancer2.name
  name   = "test22"
  policy = local.ec2_describe_policy
}

resource "aws_iam_group_policy" "loadbalancer2_test23" {
  group  = aws_iam_group.loadbalancer2.name
  name   = "test23"
  policy = local.ec2_describe_policy
}

resource "aws_iam_group_policy" "loadbalancer2_test24" {
  group  = aws_iam_group.loadbalancer2.name
  name   = "test24"
  policy = local.ec2_describe_policy
}

resource "aws_iam_group_policy" "loadbalancer2_mfa" {
  group  = aws_iam_group.loadbalancer2.name
  name   = "mfa"
  policy = local.mfa_enforcement_policy
}

# ------------------------------------------------------------------------------
# Group Policies for loadbalancer3 group
# ------------------------------------------------------------------------------
resource "aws_iam_group_policy" "loadbalancer3_test3" {
  group  = aws_iam_group.loadbalancer3.name
  name   = "test3"
  policy = local.ec2_describe_policy
}

resource "aws_iam_group_policy" "loadbalancer3_test32" {
  group  = aws_iam_group.loadbalancer3.name
  name   = "test32"
  policy = local.ec2_describe_policy
}

resource "aws_iam_group_policy" "loadbalancer3_test33" {
  group  = aws_iam_group.loadbalancer3.name
  name   = "test33"
  policy = local.ec2_describe_policy
}

resource "aws_iam_group_policy" "loadbalancer3_test34" {
  group  = aws_iam_group.loadbalancer3.name
  name   = "test34"
  policy = local.ec2_describe_policy
}

resource "aws_iam_group_policy" "loadbalancer3_mfa" {
  group  = aws_iam_group.loadbalancer3.name
  name   = "mfa"
  policy = local.mfa_enforcement_policy
}

# ------------------------------------------------------------------------------
# Group Membership – each user added to its respective group
# ------------------------------------------------------------------------------
resource "aws_iam_group_membership" "loadbalancer_membership" {
  group = aws_iam_group.loadbalancer.name
  users = [aws_iam_user.loadbalancer.name]
  name  = "loadbalancer-membership"
}

resource "aws_iam_group_membership" "loadbalancer2_membership" {
  group = aws_iam_group.loadbalancer2.name
  users = [aws_iam_user.loadbalancer2.name]
  name  = "loadbalancer2-membership"
}

resource "aws_iam_group_membership" "loadbalancer3_membership" {
  group = aws_iam_group.loadbalancer3.name
  users = [aws_iam_user.loadbalancer3.name]
  name  = "loadbalancer3-membership"
}

terraform {
  required_version = ">= 1.7"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

import {
  to = aws_backup_vault.main
  id = var.backup_name
}

locals {
  backup_name = var.backup_name
  partition   = data.aws_partition.current.partition
  dns_suffix  = data.aws_partition.current.dns_suffix
  backup_role = var.account_type == "workload" ? { main = "aws-backup-${var.backup_name}" } : {}
}

data "aws_partition" "current" {}

variable "backup_name" {
  description = "Name used to identify the backup vault, plan, and IAM role"
  type        = string
  default     = "my-backup"
}

variable "account_type" {
  description = "Type of account: 'workload' or 'backup'"
  type        = string
  default     = "workload"

  validation {
    condition     = contains(["workload", "backup"], var.account_type)
    error_message = "account_type must be either 'workload' or 'backup'."
  }
}

variable "kms_key_arn" {
  description = "ARN of KMS key for vault encryption (default: AWS managed key)"
  type        = string
  default     = null
}

variable "vault_policy" {
  description = "JSON policy document for cross-account vault access"
  type        = string
  default     = null
}

variable "min_retention_days" {
  description = "Minimum retention days for vault lock (triggers lock configuration)"
  type        = number
  default     = null
}

variable "max_retention_days" {
  description = "Maximum retention days for vault lock"
  type        = number
  default     = null
}

variable "changeable_for_days" {
  description = "Number of days the lock configuration can be changed"
  type        = number
  default     = null
}

variable "enable_aws_backup_vault_notifications" {
  description = "Enable SNS notifications for backup vault events"
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "ARN of existing SNS topic for vault notifications (if null and notifications enabled, a topic is created)"
  type        = string
  default     = null
}

variable "selection_resources" {
  description = "List of explicit ARNs to include in backup selection (in addition to tag-based)"
  type        = list(string)
  default     = null
}

variable "rule_schedule" {
  description = "Cron expression for backup plan rule schedule"
  type        = string
  default     = "cron(0 5 * * ? *)"
}

variable "destination_vault_arn" {
  description = "ARN of destination vault for cross-region/cross-account copy"
  type        = string
  default     = null
}

resource "aws_backup_vault" "main" {
  name        = local.backup_name
  kms_key_arn = var.kms_key_arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault_policy" "main" {
  count = var.vault_policy != null ? 1 : 0

  backup_vault_name = aws_backup_vault.main.name
  policy            = var.vault_policy
}

resource "aws_backup_vault_lock_configuration" "main" {
  count = var.min_retention_days != null ? 1 : 0

  backup_vault_name   = aws_backup_vault.main.name
  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days
  changeable_for_days = var.changeable_for_days
}

resource "aws_sns_topic" "backup_notifications" {
  count = var.enable_aws_backup_vault_notifications && var.sns_topic_arn == null ? 1 : 0

  name = "backup-vault-notifications-${local.backup_name}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault_notifications" "main" {
  count = var.enable_aws_backup_vault_notifications ? 1 : 0

  backup_vault_name = aws_backup_vault.main.name
  sns_topic_arn     = var.sns_topic_arn != null ? var.sns_topic_arn : aws_sns_topic.backup_notifications[0].arn
  backup_vault_events = [
    "BACKUP_JOB_FAILED",
    "COPY_JOB_FAILED",
  ]
}

import {
  for_each = local.backup_role
  to       = aws_iam_role.backup
  id       = each.value
}

resource "aws_iam_role" "backup" {
  for_each = local.backup_role

  name = each.value

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "backup.${local.dns_suffix}"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

import {
  for_each = local.backup_role
  to       = aws_iam_role_policy_attachment.backup
  id       = "${each.value}/arn:${local.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "backup" {
  for_each = local.backup_role

  role       = aws_iam_role.backup[each.key].name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_backup_plan" "main" {
  count = var.account_type == "workload" ? 1 : 0

  name = "plan-${local.backup_name}-backup"

  rule {
    rule_name         = "${local.backup_name}-rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = var.rule_schedule
    start_window      = 60
    completion_window = 120

    lifecycle {
      cold_storage_after = 30
      delete_after       = 120
    }

    recovery_point_tags = {
      BackupName = local.backup_name
    }

    dynamic "copy_action" {
      for_each = var.destination_vault_arn != null ? [1] : []
      content {
        destination_vault_arn = var.destination_vault_arn
      }
    }
  }
}

resource "aws_backup_selection" "main" {
  count = var.account_type == "workload" ? 1 : 0

  name         = "${local.backup_name}-selection"
  plan_id      = aws_backup_plan.main[0].id
  iam_role_arn = aws_iam_role.backup["main"].arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "true"
  }

  resources = var.selection_resources != null ? var.selection_resources : null
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "config_name" {
  description = "Optional name for AWS Config resources. null defaults to 'config'; empty generates a random pet name."
  type        = string
  default     = null
}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

resource "random_pet" "config_name" {
  length    = 2
  separator = "-"
}

locals {
  config_name_resolved = coalesce(var.config_name, "config")
  config_name_final    = var.config_name == "" ? random_pet.config_name.id : local.config_name_resolved
  evaluation_frequency = "TwentyFour_Hours"
}

resource "aws_iam_role" "config" {
  name_prefix = "${local.config_name_final}-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "config" {
  role       = aws_iam_role.config.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWS_ConfigRole"
}

resource "aws_s3_bucket" "snapshot" {
  bucket_prefix = "${lower(local.config_name_final)}-awsconfig-snapshots-"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "snapshot" {
  bucket                  = aws_s3_bucket.snapshot.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "s3" {
  description         = "Customer managed KMS key for AWS Config snapshot S3 bucket encryption"
  enable_key_rotation = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "ConfigS3KeyPolicy"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "s3" {
  name_prefix   = "alias/awsconfig-s3-"
  target_key_id = aws_kms_key.s3.key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "snapshot" {
  bucket = aws_s3_bucket.snapshot.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "snapshot" {
  bucket = aws_s3_bucket.snapshot.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket" "config_logs" {
  bucket_prefix = "${lower(local.config_name_final)}-awsconfig-logs-"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "config_logs" {
  bucket                  = aws_s3_bucket.config_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "config_logs" {
  bucket = aws_s3_bucket.config_logs.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "config_logs" {
  bucket = aws_s3_bucket.config_logs.id
  acl    = "log-delivery-write"

  depends_on = [aws_s3_bucket_ownership_controls.config_logs]
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config_logs" {
  bucket = aws_s3_bucket.config_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "config_logs" {
  bucket = aws_s3_bucket.config_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "config_logs" {
  bucket = aws_s3_bucket.config_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowS3ServerAccessLogs"
        Effect    = "Allow"
        Principal = {
          Service = ["logging.s3.amazonaws.com"]
        }
        Action   = ["s3:PutObject"]
        Resource = "${aws_s3_bucket.config_logs.arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          ArnLike = {
            "aws:SourceArn" = "arn:${data.aws_partition.current.partition}:s3:::${aws_s3_bucket.snapshot.id}"
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_logging" "snapshot" {
  bucket        = aws_s3_bucket.snapshot.id
  target_bucket = aws_s3_bucket.config_logs.id
  target_prefix = "config-logs/"
}

resource "aws_kms_key" "config" {
  description         = "Customer managed KMS key for AWS Config SNS topic encryption"
  enable_key_rotation = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "ConfigSnsKeyPolicy"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowSnsService"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt",
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "config" {
  name_prefix   = "alias/awsconfig-sns-"
  target_key_id = aws_kms_key.config.key_id
}

resource "aws_sns_topic" "config" {
  name              = local.config_name_final
  kms_master_key_id = aws_kms_key.config.arn
}

resource "aws_iam_role_policy" "config_delivery" {
  name = "config-delivery"
  role = aws_iam_role.config.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ConfigS3Delivery"
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetBucketAcl",
        ]
        Resource = [
          aws_s3_bucket.snapshot.arn,
          "${aws_s3_bucket.snapshot.arn}/*",
        ]
      },
      {
        Sid    = "ConfigSnsPublish"
        Effect = "Allow"
        Action = [
          "sns:Publish",
        ]
        Resource = [
          aws_sns_topic.config.arn,
        ]
      },
      {
        Sid    = "ConfigS3Kms"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
        ]
        Resource = [
          aws_kms_key.s3.arn,
        ]
      }
    ]
  })
}

resource "aws_config_configuration_recorder" "config" {
  name     = local.config_name_final
  role_arn = aws_iam_role.config.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }

  depends_on = [
    aws_iam_role_policy_attachment.config,
    aws_iam_role_policy.config_delivery,
  ]
}

resource "aws_config_delivery_channel" "config" {
  name           = local.config_name_final
  s3_bucket_name = aws_s3_bucket.snapshot.id
  s3_key_prefix  = "awsconfig/records"
  s3_kms_key_arn = aws_kms_key.s3.arn
  sns_topic_arn  = aws_sns_topic.config.arn

  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_configuration_recorder_status" "config" {
  name       = aws_config_configuration_recorder.config.name
  is_enabled = true

  depends_on = [aws_config_delivery_channel.config]
}

resource "aws_config_config_rule" "cloudtrail_enabled" {
  name                        = "cloudtrail-enabled"
  maximum_execution_frequency = local.evaluation_frequency

  source {
    owner             = "AWS"
    source_identifier = "CLOUD_TRAIL_ENABLED"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "iam_pw_policy" {
  name                        = "iam-pw-policy"
  maximum_execution_frequency = local.evaluation_frequency

  source {
    owner             = "AWS"
    source_identifier = "IAM_PASSWORD_POLICY"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "ec2_vpc" {
  name = "ec2-vpc"

  source {
    owner             = "AWS"
    source_identifier = "INSTANCES_IN_VPC"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "root_mfa_enabled" {
  name                        = "root-mfa-enabled"
  maximum_execution_frequency = local.evaluation_frequency

  source {
    owner             = "AWS"
    source_identifier = "ROOT_ACCOUNT_MFA_ENABLED"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "acm_expiration_check" {
  name                        = "acm-expiration-check"
  maximum_execution_frequency = local.evaluation_frequency

  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "ebs_inuse_check" {
  name = "ebs-inuse-check"

  source {
    owner             = "AWS"
    source_identifier = "EC2_VOLUME_INUSE_CHECK"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "ec2_imdsv2_check" {
  name = "ec2-imdsv2-check"

  source {
    owner             = "AWS"
    source_identifier = "EC2_IMDSV2_CHECK"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "rds_encrypted" {
  name = "rds-encrypted"

  source {
    owner             = "AWS"
    source_identifier = "RDS_STORAGE_ENCRYPTED"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "rds_private" {
  name = "rds-private"

  source {
    owner             = "AWS"
    source_identifier = "RDS_INSTANCE_PUBLIC_ACCESS_CHECK"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "rds_private_snapshots" {
  name = "rds-private-snapshots"

  source {
    owner             = "AWS"
    source_identifier = "RDS_SNAPSHOTS_PUBLIC_PROHIBITED"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "required_tags" {
  name = "required-tags"

  input_parameters = jsonencode({
    tag1Key = "terraform.io"
    tag2Key = "environment"
  })

  scope {
    compliance_resource_types = ["AWS::S3::Bucket"]
  }

  source {
    owner             = "AWS"
    source_identifier = "REQUIRED_TAGS"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

locals {
  common_tags = {
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "bjit-vpc"
  })
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = ["10.0.4.0/24", "10.0.6.0/24", "10.0.8.0/24"][count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "bjit-public-subnet-${count.index + 1}"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = ["10.0.10.0/24", "10.0.12.0/24", "10.0.14.0/24"][count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "bjit-private-subnet-${count.index + 1}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "bjit-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "bjit-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "bjit-private-rt-${count.index + 1}"
  })
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"

  route_table_ids = aws_route_table.private[*].id

  tags = merge(local.common_tags, {
    Name = "bjit-s3-vpc-endpoint"
  })
}

resource "aws_security_group" "alb" {
  name        = "bjit-api-server-ALB-SG"
  description = "Security group for ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow HTTP/HTTPS from internet"
    from_port   = 80
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-api-server-ALB-SG"
  })
}

resource "aws_security_group" "mariadb" {
  name        = "bjit-mariaDB-RDS-SG"
  description = "Security group for MariaDB RDS"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow MySQL from VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-mariaDB-RDS-SG"
  })
}

resource "aws_security_group" "redis" {
  name        = "bjit-redis-SG"
  description = "Security group for Redis"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow Redis from VPC"
