    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-redis-SG"
  })
}

resource "aws_security_group" "api_server" {
  name        = "bjit-api-server-SG"
  description = "Security group for API server"
  vpc_id      = aws_vpc.main.id

  ingress {
