resource "aws_security_group" "public_ssh" {
  name        = "bjit-public-ssh-SG"
  description = "Security group for public SSH access"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow SSH from VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-public-ssh-SG"
  })
}

# VPC Flow Logs
resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for CloudWatch log encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogs"
        Effect = "Allow"
        Principal = {
          Service = "logs.us-east-1.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "bjit-vpc-flow-logs-kms-key"
  })
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/bjit-vpc-flow-logs"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

resource "aws_cloudwatch_log_group" "flow_log" {
  name              = "/aws/vpc/flow-logs"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.cloudwatch.arn

  tags = merge(local.common_tags, {
    Name = "bjit-vpc-flow-logs"
  })
}

resource "aws_iam_role" "flow_log" {
  name = "bjit-vpc-flow-logs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "bjit-vpc-flow-logs-role"
  })
}

resource "aws_iam_role_policy" "flow_log" {
  name = "bjit-vpc-flow-logs-policy"
  role = aws_iam_role.flow_log.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.cloudwatch.arn
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  log_destination      = aws_cloudwatch_log_group.flow_log.arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.flow_log.arn
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "bjit-vpc-flow-log"
  })
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "base_name" {
  type    = string
  default = "benchmark"
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "subnet_public_cidrs" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "subnet_private_cidrs" {
  type    = list(string)
  default = null
  validation {
    condition     = var.subnet_private_cidrs == null || length(var.subnet_private_cidrs) == length(var.subnet_public_cidrs)
    error_message = "When provided, subnet_private_cidrs must have the same number of CIDR blocks as subnet_public_cidrs."
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

locals {
  has_private_subnets = var.subnet_private_cidrs != null && length(var.subnet_private_cidrs) > 0
  endpoint_subnet_ids = local.has_private_subnets ? aws_subnet.private[*].id : aws_subnet.public[*].id
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true

  tags = {
    Name = "${var.base_name}-vpc"
  }
}

resource "aws_subnet" "public" {
  count             = length(var.subnet_public_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_public_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index + 1]

  tags = {
    Name = "${var.base_name}-public-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.base_name}-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.base_name}-public-rt"
  }
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "public" {
  count          = length(var.subnet_public_cidrs)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_subnet" "private" {
  count             = local.has_private_subnets ? length(var.subnet_private_cidrs) : 0
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_private_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index + 1]

  tags = {
    Name = "${var.base_name}-private-${count.index + 1}"
  }
}

resource "aws_eip" "nat" {
  count  = local.has_private_subnets ? length(var.subnet_public_cidrs) : 0
  domain = "vpc"

  tags = {
    Name = "${var.base_name}-nat-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "nat" {
  count         = local.has_private_subnets ? length(var.subnet_public_cidrs) : 0
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  depends_on = [aws_internet_gateway.igw]

  tags = {
    Name = "${var.base_name}-nat-${count.index + 1}"
  }
}

resource "aws_route_table" "private" {
  count  = local.has_private_subnets ? length(var.subnet_private_cidrs) : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.base_name}-private-rt-${count.index + 1}"
  }
}

resource "aws_route" "private_nat" {
  count                  = local.has_private_subnets ? length(var.subnet_private_cidrs) : 0
  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.nat[count.index].id
}

resource "aws_route_table_association" "private" {
  count          = local.has_private_subnets ? length(var.subnet_private_cidrs) : 0
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3_public" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.public.id]

  tags = {
    Name = "${var.base_name}-s3-gateway-public"
  }
}

resource "aws_vpc_endpoint" "s3_private" {
  count             = local.has_private_subnets ? 1 : 0
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = {
    Name = "${var.base_name}-s3-gateway-private"
  }
}

resource "aws_security_group" "ecr" {
  name        = "${var.base_name}-ecr"
  description = "Security group for ECR VPC endpoints"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "${var.base_name}-ecr-sg"
  }
}

resource "aws_security_group_rule" "ecr_egress" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [var.vpc_cidr]
  security_group_id = aws_security_group.ecr.id
  description       = "Allow all outbound traffic within VPC CIDR"
}

resource "aws_security_group_rule" "ecr_ingress_public" {
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = var.subnet_public_cidrs
  security_group_id = aws_security_group.ecr.id
  description       = "Allow HTTPS from public subnets"
}

resource "aws_security_group_rule" "ecr_ingress_private" {
  count             = local.has_private_subnets ? 1 : 0
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = local.has_private_subnets ? var.subnet_private_cidrs : []
  security_group_id = aws_security_group.ecr.id
  description       = "Allow HTTPS from private subnets"
}

resource "aws_vpc_endpoint" "ecr" {
  for_each            = toset(["api", "dkr"])
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ecr.${each.value}"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  security_group_ids  = [aws_security_group.ecr.id]
  subnet_ids          = local.endpoint_subnet_ids

  tags = {
    Name = "${var.base_name}-ecr-${each.value}"
  }
}

resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for VPC flow log CloudWatch encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-default-1"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "${var.base_name}-cloudwatch-kms"
  }
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/${var.base_name}-cloudwatch"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

resource "aws_cloudwatch_log_group" "vpc_flow_log" {
  name              = "/aws/vpc/${var.base_name}-flow-logs"
  retention_in_days = 7
  kms_key_id        = aws_kms_key.cloudwatch.arn

  tags = {
    Name = "${var.base_name}-vpc-flow-logs"
  }
}

resource "aws_iam_role" "vpc_flow_log" {
  name = "${var.base_name}-vpc-flow-log-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${var.base_name}-vpc-flow-log-role"
  }
}

resource "aws_iam_role_policy" "vpc_flow_log" {
  name = "${var.base_name}-vpc-flow-log-policy"
  role = aws_iam_role.vpc_flow_log.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = format("%s:*", aws_cloudwatch_log_group.vpc_flow_log.arn)
      }
    ]
  })
}

resource "aws_flow_log" "vpc" {
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.vpc_flow_log.arn
  iam_role_arn         = aws_iam_role.vpc_flow_log.arn
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.main.id

  depends_on = [aws_iam_role_policy.vpc_flow_log]

  tags = {
    Name = "${var.base_name}-vpc-flow-log"
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the project VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "pub_sub_1_cidr" {
  description = "CIDR block for public subnet 1"
  type        = string
  default     = "10.0.1.0/24"
}

variable "pub_sub_2_cidr" {
  description = "CIDR block for public subnet 2"
  type        = string
  default     = "10.0.2.0/24"
}

variable "pvt_sub_1_cidr" {
  description = "CIDR block for private subnet 1"
  type        = string
  default     = "10.0.3.0/24"
}

variable "pvt_sub_2_cidr" {
  description = "CIDR block for private subnet 2"
  type        = string
  default     = "10.0.4.0/24"
}

variable "admin_ssh_cidr" {
  description = "Allowed admin CIDR for SSH access"
  type        = string
  default     = "203.0.113.0/24"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

resource "aws_vpc" "project_vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "project-vpc"
  }
}

resource "aws_subnet" "pub_sub_1" {
  vpc_id                  = aws_vpc.project_vpc.id
  cidr_block              = var.pub_sub_1_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "pub-sub-1"
  }
}

resource "aws_subnet" "pub_sub_2" {
  vpc_id                  = aws_vpc.project_vpc.id
  cidr_block              = var.pub_sub_2_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "pub-sub-2"
  }
}

resource "aws_subnet" "pvt_sub_1" {
  vpc_id                  = aws_vpc.project_vpc.id
  cidr_block              = var.pvt_sub_1_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "pvt-sub-1"
  }
}

resource "aws_subnet" "pvt_sub_2" {
  vpc_id                  = aws_vpc.project_vpc.id
  cidr_block              = var.pvt_sub_2_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "pvt-sub-2"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.project_vpc.id

  tags = {
    Name = "T-igw"
  }
}

resource "aws_route_table" "rt_pub_1" {
  vpc_id = aws_vpc.project_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "RT_PUBRT-1"
  }
}

resource "aws_route_table" "rt_pub_2" {
  vpc_id = aws_vpc.project_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "RT_PUBRT-2"
  }
}

resource "aws_route_table_association" "pub_sub_1" {
  subnet_id      = aws_subnet.pub_sub_1.id
  route_table_id = aws_route_table.rt_pub_1.id
}

resource "aws_route_table_association" "pub_sub_2" {
  subnet_id      = aws_subnet.pub_sub_2.id
  route_table_id = aws_route_table.rt_pub_2.id
}

resource "aws_eip" "eip_nat_1" {
  domain = "vpc"
}

resource "aws_eip" "eip_nat_2" {
  domain = "vpc"
}

resource "aws_nat_gateway" "nat_gw_1" {
  allocation_id = aws_eip.eip_nat_1.id
  subnet_id     = aws_subnet.pub_sub_1.id

  tags = {
    Name = "T-NAT1"
  }
}

resource "aws_nat_gateway" "nat_gw_2" {
  allocation_id = aws_eip.eip_nat_2.id
  subnet_id     = aws_subnet.pub_sub_2.id

  tags = {
    Name = "T-NAT1"
  }
}

resource "aws_route_table" "rt_pvt_1" {
  vpc_id = aws_vpc.project_vpc.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat_gw_1.id
  }

  tags = {
    Name = "RT_PVTRT-1"
  }
}

resource "aws_route_table" "rt_pvt_2" {
  vpc_id = aws_vpc.project_vpc.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat_gw_1.id
  }

  tags = {
    Name = "RT_PVTRT-2"
  }
}

resource "aws_route_table_association" "pvt_sub_1" {
  subnet_id      = aws_subnet.pvt_sub_1.id
  route_table_id = aws_route_table.rt_pvt_1.id
}

resource "aws_route_table_association" "pvt_sub_2" {
  subnet_id      = aws_subnet.pvt_sub_2.id
  route_table_id = aws_route_table.rt_pvt_2.id
}

resource "aws_security_group" "allow_tls" {
  name        = "allow_tls"
  description = "Allow HTTP, HTTPS, and SSH from the admin range"
  vpc_id      = aws_vpc.project_vpc.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "SSH from admin range"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_ssh_cidr]
  }

  egress {
    description = "Outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.project_vpc.cidr_block]
  }

  tags = {
    Name = "allow_tls"
  }
}

resource "aws_security_group" "pvt_seg" {
  name        = "pvt-seg"
  description = "Allow web, SSH, and PostgreSQL traffic from the public security group"
  vpc_id      = aws_vpc.project_vpc.id

  ingress {
    description     = "HTTP from public security group"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    description     = "HTTPS from public security group"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    description     = "SSH from public security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    description     = "PostgreSQL from public security group"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  egress {
    description     = "Outbound to public security group"
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    security_groups = [aws_security_group.allow_tls.id]
  }

  tags = {
    Name = "pvt-seg"
  }
}

resource "aws_kms_key" "cloudwatch" {
  description         = "KMS key for VPC flow log CloudWatch Log Group encryption"
  enable_key_rotation = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "vpc-flow-logs-key-policy"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "cloudwatch-flow-logs"
  }
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/vpc-flow-logs"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

resource "aws_cloudwatch_log_group" "vpc_flow_log" {
  name              = "vpc-flow-logs"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.cloudwatch.arn

  tags = {
    Name = "vpc-flow-logs"
  }
}

resource "aws_iam_role" "vpc_flow_log" {
  name = "vpc-flow-log-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "vpc_flow_log" {
  name = "vpc-flow-log-policy"
  role = aws_iam_role.vpc_flow_log.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Effect   = "Allow"
        Resource = "${aws_cloudwatch_log_group.vpc_flow_log.arn}:*"
      },
      {
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Effect   = "Allow"
        Resource = aws_kms_key.cloudwatch.arn
      }
    ]
  })
}

resource "aws_flow_log" "vpc_flow_log" {
  log_destination      = aws_cloudwatch_log_group.vpc_flow_log.arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.vpc_flow_log.arn
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.project_vpc.id

  tags = {
    Name = "vpc-flow-logs"
  }
}

terraform {
  required_version = "~> 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

import {
  to = aws_dynamodb_table.pets
  id = "Pets"
}

import {
  to = aws_iam_role.api_gateway_dynamodb_role
  id = "apigw-dynamodb-integration-role"
}

import {
  to = aws_iam_role.api_gateway_cloudwatch_role
  id = "apigw-cloudwatch-role"
}

import {
  to = aws_cloudwatch_log_group.api_gw
  id = "/aws/APIGW/terraform-apigw-dynamodb"
}

data "aws_caller_identity" "current" {}

resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for CloudWatch log group encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-policy-cloudwatch"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_key" "dynamodb" {
  description             = "KMS key for DynamoDB table encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-policy-dynamodb"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow DynamoDB to use the key"
        Effect = "Allow"
        Principal = {
          Service = "dynamodb.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_dynamodb_table" "pets" {
  name           = "Pets"
  billing_mode   = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  attribute {
    name = "PetType"
    type = "S"
  }

  global_secondary_index {
    name               = "PetType-index"
    hash_key           = "PetType"
    projection_type    = "INCLUDE"
    non_key_attributes = ["PetName", "PetPrice"]
    read_capacity      = 5
    write_capacity     = 5
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.dynamodb.arn
  }

  point_in_time_recovery {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "api_gateway_dynamodb_role" {
  name = "apigw-dynamodb-integration-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "api_gateway_dynamodb_policy" {
  name = "apigw-dynamodb-integration-policy"
  role = aws_iam_role.api_gateway_dynamodb_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = ["dynamodb:PutItem"]
        Resource = [aws_dynamodb_table.pets.arn]
      },
      {
        Effect = "Allow"
        Action = ["dynamodb:Query"]
        Resource = [
          aws_dynamodb_table.pets.arn,
          "${aws_dynamodb_table.pets.arn}/index/PetType-index"
        ]
      }
    ]
  })
}

resource "aws_api_gateway_rest_api" "demo" {
  name           = "APIGW DynamoDB Serverless Pattern Demo"
  api_key_source = "HEADER"
}

resource "aws_api_gateway_resource" "pets" {
  rest_api_id = aws_api_gateway_rest_api.demo.id
  parent_id   = aws_api_gateway_rest_api.demo.root_resource_id
  path_part   = "pets"
}

resource "aws_api_gateway_resource" "pet_type" {
  rest_api_id = aws_api_gateway_rest_api.demo.id
  parent_id   = aws_api_gateway_resource.pets.id
  path_part   = "{PetType}"
}

resource "aws_api_gateway_method" "post_pets" {
  rest_api_id      = aws_api_gateway_rest_api.demo.id
  resource_id      = aws_api_gateway_resource.pets.id
  http_method      = "POST"
  authorization    = "NONE"
  api_key_required = true
}

resource "aws_api_gateway_integration" "post_pets" {
  rest_api_id             = aws_api_gateway_rest_api.demo.id
  resource_id             = aws_api_gateway_resource.pets.id
  http_method             = aws_api_gateway_method.post_pets.http_method
  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = "arn:aws:apigateway:us-east-1:dynamodb:action/PutItem"
  credentials             = aws_iam_role.api_gateway_dynamodb_role.arn
  passthrough_behavior    = "NEVER"

  request_templates = {
    "application/json" = <<VTL
#set($inputRoot = $input.path('$'))
{
  "TableName": "Pets",
  "Item": {
    "id": { "S": "$context.requestId" },
    "PetType": { "S": "$util.escapeJavaScript($inputRoot.PetType)" },
    "PetName": { "S": "$util.escapeJavaScript($inputRoot.PetName)" },
    "PetPrice": { "N": "$inputRoot.PetPrice" },
    "PetBoolean": { "BOOL": true }
  }
}
VTL
  }
}

resource "aws_api_gateway_method_response" "post_pets_200" {
  rest_api_id = aws_api_gateway_rest_api.demo.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.post_pets.http_method
  status_code = "200"
}

resource "aws_api_gateway_integration_response" "post_pets_200" {
  rest_api_id = aws_api_gateway_rest_api.demo.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.post_pets.http_method
  status_code = aws_api_gateway_method_response.post_pets_200.status_code

  depends_on = [aws_api_gateway_integration.post_pets]

  response_templates = {
    "application/json" = <<VTL
{
  "message": "Pet item created successfully"
}
VTL
  }
}

resource "aws_api_gateway_method" "get_pets_by_type" {
  rest_api_id      = aws_api_gateway_rest_api.demo.id
  resource_id      = aws_api_gateway_resource.pet_type.id
  http_method      = "GET"
  authorization    = "NONE"
  api_key_required = true

  request_parameters = {
    "method.request.path.PetType" = true
  }
}

resource "aws_api_gateway_integration" "get_pets_by_type" {
  rest_api_id             = aws_api_gateway_rest_api.demo.id
  resource_id             = aws_api_gateway_resource.pet_type.id
  http_method             = aws_api_gateway_method.get_pets_by_type.http_method
  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = "arn:aws:apigateway:us-east-1:dynamodb:action/Query"
  credentials             = aws_iam_role.api_gateway_dynamodb_role.arn
  passthrough_behavior    = "NEVER"

  request_templates = {
    "application/json" = <<VTL
{
  "TableName": "Pets",
  "IndexName": "PetType-index",
  "KeyConditionExpression": "PetType = :v1",
  "ExpressionAttributeValues": {
    ":v1": { "S": "$util.escapeJavaScript($util.urlDecode($input.params('path').PetType))" }
  }
}
VTL
  }
}

resource "aws_api_gateway_method_response" "get_pets_by_type_200" {
  rest_api_id = aws_api_gateway_rest_api.demo.id
  resource_id = aws_api_gateway_resource.pet_type.id
  http_method = aws_api_gateway_method.get_pets_by_type.http_method
  status_code = "200"
}

resource "aws_api_gateway_integration_response" "get_pets_by_type_200" {
  rest_api_id = aws_api_gateway_rest_api.demo.id
  resource_id = aws_api_gateway_resource.pet_type.id
  http_method = aws_api_gateway_method.get_pets_by_type.http_method
  status_code = aws_api_gateway_method_response.get_pets_by_type_200.status_code

  depends_on = [aws_api_gateway_integration.get_pets_by_type]

  response_templates = {
    "application/json" = <<VTL
#set($items = [])
#foreach($item in $input.path('$.Items'))
  #set($petItem = {})
  #set($discarded = $petItem.put("id", "$item.id.S"))
  #set($discarded = $petItem.put("PetType", "$item.PetType.S"))
  #set($discarded = $petItem.put("PetName", "$item.PetName.S"))
  #set($discarded = $petItem.put("PetPrice", "$item.PetPrice.N"))
  #set($discarded = $items.add($petItem))
#end
{
  "items": $util.toJson($items)
}
VTL
  }
}

resource "aws_api_gateway_deployment" "demo" {
  rest_api_id = aws_api_gateway_rest_api.demo.id

  depends_on = [
    aws_api_gateway_resource.pets,
    aws_api_gateway_resource.pet_type,
    aws_api_gateway_method.post_pets,
    aws_api_gateway_method.get_pets_by_type,
    aws_api_gateway_integration.post_pets,
    aws_api_gateway_integration.get_pets_by_type,
    aws_api_gateway_method_response.post_pets_200,
    aws_api_gateway_method_response.get_pets_by_type_200,
    aws_api_gateway_integration_response.post_pets_200,
    aws_api_gateway_integration_response.get_pets_by_type_200
  ]

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_api_gateway_stage" "v1" {
  deployment_id         = aws_api_gateway_deployment.demo.id
  rest_api_id           = aws_api_gateway_rest_api.demo.id
  stage_name            = "v1"
  cache_cluster_enabled = true
  cache_cluster_size    = 0.5
  xray_tracing_enabled  = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_gw.arn
    format = jsonencode({
      requestId       = "$context.requestId"
      path            = "$context.path"
      status          = "$context.status"
      httpMethod      = "$context.httpMethod"
      responseLatency = "$context.responseLatency"
      sourceIp        = "$context.identity.sourceIp"
    })
  }

  depends_on = [aws_api_gateway_account.this]
}

resource "aws_api_gateway_method_settings" "v1" {
  rest_api_id = aws_api_gateway_rest_api.demo.id
  stage_name  = aws_api_gateway_stage.v1.stage_name
  method_path = "*/*"

  settings {
    metrics_enabled      = true
    logging_level        = "INFO"
    caching_enabled      = true
    cache_data_encrypted = true
  }
}

resource "aws_iam_role" "api_gateway_cloudwatch_role" {
  name = "apigw-cloudwatch-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "api_gateway_cloudwatch_policy" {
  name = "apigw-cloudwatch-policy"
  role = aws_iam_role.api_gateway_cloudwatch_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:GetLogEvents",
          "logs:FilterLogEvents"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "xray:PutTraceSegments",
          "xray:PutTelemetryRecords"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_cloudwatch_log_group" "api_gw" {
  name              = "/aws/APIGW/terraform-apigw-dynamodb"
  retention_in_days = 7
  kms_key_id        = aws_kms_key.cloudwatch.arn
}

resource "aws_api_gateway_account" "this" {
  cloudwatch_role_arn = aws_iam_role.api_gateway_cloudwatch_role.arn

  depends_on = [aws_iam_role_policy.api_gateway_cloudwatch_policy]
}

resource "aws_cloudwatch_log_resource_policy" "api_gw" {
  policy_name = "apigw-dynamodb-terraform-log-policy"

  policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.api_gw.arn}:*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = "${aws_api_gateway_rest_api.demo.execution_arn}/*"
          }
        }
      }
    ]
  })
}

resource "aws_api_gateway_api_key" "demo" {
  name    = "apigw-dynamodb-terraform-api-key"
  enabled = true
}

resource "aws_api_gateway_usage_plan" "demo" {
  name = "apigw-dynamodb-terraform-usage-plan"

  api_stages {
    api_id = aws_api_gateway_rest_api.demo.id
    stage  = aws_api_gateway_stage.v1.stage_name
  }

  throttle_settings {
    burst_limit = 20
    rate_limit  = 100
  }

  quota_settings {
    limit  = 1000
    period = "MONTH"
  }
}

resource "aws_api_gateway_usage_plan_key" "demo" {
  key_id        = aws_api_gateway_api_key.demo.id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.demo.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "name" {
  type    = string
  default = "sadcloud"
}

variable "no_versioning" {
  type    = bool
  default = false
}

variable "no_default_encryption" {
  type    = bool
  default = false
}

variable "website_enabled" {
  type    = bool
  default = false
}

variable "no_logging" {
  type    = bool
  default = false
}

variable "allow_cleartext" {
  type    = bool
  default = false
}

variable "s3_getobject_only" {
  type    = bool
  default = false
}

variable "s3_public" {
  type    = bool
  default = false
}

variable "bucket_acl" {
  type    = string
  default = "log-delivery-write"
}

resource "aws_s3_bucket" "main" {
  bucket_prefix = var.name
  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "main" {
  bucket = aws_s3_bucket.main.id
  acl    = "private"

  depends_on = [aws_s3_bucket_ownership_controls.main]
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket                  = aws_s3_bucket.main.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "main" {
  count  = var.no_versioning ? 0 : 1
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_kms_key" "main_encryption" {
  count               = var.no_default_encryption ? 0 : 1
  description         = "KMS key for main bucket ${var.name}"
  enable_key_rotation = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  count  = var.no_default_encryption ? 0 : 1
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.main_encryption[count.index].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_website_configuration" "main" {
  count  = var.website_enabled ? 1 : 0
  bucket = aws_s3_bucket.main.id

  index_document {
    suffix = "index.html"
  }
}

resource "aws_s3_bucket" "logging" {
  count        = var.no_logging ? 0 : 1
  bucket       = "${var.name}-logging"
  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "logging" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.logging[count.index].id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "logging" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.logging[count.index].id
  acl    = var.bucket_acl

  depends_on = [aws_s3_bucket_ownership_controls.logging]
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count                   = var.no_logging ? 0 : 1
  bucket                  = aws_s3_bucket.logging[count.index].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "logging" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.logging[count.index].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_kms_key" "logging_encryption" {
  count               = var.no_logging ? 0 : 1
  description         = "KMS key for logging bucket ${var.name}-logging"
  enable_key_rotation = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.logging[count.index].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.logging_encryption[count.index].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_logging" "main" {
  count         = var.no_logging ? 0 : 1
  bucket        = aws_s3_bucket.main.id
  target_bucket = aws_s3_bucket.logging[count.index].id
  target_prefix = "log/"
}

resource "aws_s3_bucket_policy" "cleartext_deny" {
  count  = var.allow_cleartext ? 1 : 0
  bucket = aws_s3_bucket.main.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.main.arn,
          "${aws_s3_bucket.main.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket" "getonly" {
  count        = var.s3_getobject_only ? 1 : 0
  bucket       = "${var.name}-getonly"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "getonly" {
  count                   = var.s3_getobject_only ? 1 : 0
  bucket                  = aws_s3_bucket.getonly[count.index].id
  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_versioning" "getonly" {
  count  = var.s3_getobject_only ? 1 : 0
  bucket = aws_s3_bucket.getonly[count.index].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "getonly" {
  count  = var.s3_getobject_only ? 1 : 0
  bucket = aws_s3_bucket.getonly[count.index].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:GetObject"
        Resource = [
          "${aws_s3_bucket.getonly[count.index].arn}/*"
        ]
      }
    ]
  })
}

resource "aws_s3_bucket" "public" {
  count        = var.s3_public ? 1 : 0
  bucket       = "${var.name}-public"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "public" {
  count                   = var.s3_public ? 1 : 0
  bucket                  = aws_s3_bucket.public[count.index].id
  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_versioning" "public" {
  count  = var.s3_public ? 1 : 0
  bucket = aws_s3_bucket.public[count.index].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "public" {
  count  = var.s3_public ? 1 : 0
  bucket = aws_s3_bucket.public[count.index].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.public[count.index].arn,
          "${aws_s3_bucket.public[count.index].arn}/*"
        ]
      }
    ]
  })
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_iam_policy" "drs_agent_policy" {
  name = "AWSElasticDisasterRecoveryAgentPolicy"
}

data "aws_iam_policy" "drs_failback_policy" {
  name = "AWSElasticDisasterRecoveryFailbackPolicy"
}

data "aws_iam_policy" "drs_conversion_server_policy" {
  name = "AWSElasticDisasterRecoveryConversionServerPolicy"
}

data "aws_iam_policy" "drs_recovery_instance_policy" {
  name = "AWSElasticDisasterRecoveryRecoveryInstancePolicy"
}

data "aws_iam_policy" "drs_replication_server_policy" {
  name = "AWSElasticDisasterRecoveryReplicationServerPolicy"
}

data "aws_iam_policy" "ssm_managed_instance_core" {
  name = "AmazonSSMManagedInstanceCore"
}

resource "aws_iam_role" "drs_agent_role" {
  name               = "AWSElasticDisasterRecoveryAgentRole"
  path               = "/service-role/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "drs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          StringLike = {
            "sts:SourceIdentity" = "s-*"
          }
        }
      }
    ]
  })
}

