}

resource "aws_iam_policy" "initialize_policy" {
  name        = "InitializePolicy"
  path        = "/"
  description = "Policy used to initialize AWS Elastic Disaster Recovery"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "InitializeDRS"
        Effect   = "Allow"
        Action   = "drs:InitializeService"
        Resource = "*"
      },
      {
        Sid    = "CreateDRSInstanceProfiles"
        Effect = "Allow"
        Action = [
          "iam:CreateInstanceProfile",
          "iam:AddRoleToInstanceProfile"
        ]
        Resource = "*"
      },
      {
        Sid      = "PassDRSServiceRoles"
        Effect   = "Allow"
        Action   = "iam:PassRole"
        Resource = [
          aws_iam_role.drs_agent_role.arn,
          aws_iam_role.drs_failback_role.arn,
          aws_iam_role.drs_conversion_server_role.arn,
          aws_iam_role.drs_recovery_instance_role.arn,
          aws_iam_role.drs_replication_server_role.arn,
          aws_iam_role.drs_recovery_instance_launch_actions_role.arn
        ]
        Condition = {
          StringEquals = {
            "iam:PassedToService" = [
              "ec2.amazonaws.com",
              "drs.amazonaws.com"
            ]
          }
        }
      },
      {
        Sid      = "DenyPassRoleOutsideDRSServiceRoles"
        Effect   = "Deny"
        Action   = "iam:PassRole"
        NotResource = [
          aws_iam_role.drs_agent_role.arn,
          aws_iam_role.drs_failback_role.arn,
          aws_iam_role.drs_conversion_server_role.arn,
          aws_iam_role.drs_recovery_instance_role.arn,
          aws_iam_role.drs_replication_server_role.arn,
          aws_iam_role.drs_recovery_instance_launch_actions_role.arn
        ]
      },
      {
        Sid      = "CreateDRSServiceLinkedRole"
        Effect   = "Allow"
        Action   = "iam:CreateServiceLinkedRole"
        Resource = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role/aws-service-role/drs.amazonaws.com/AWSServiceRoleForElasticDisasterRecovery"
      },
      {
        Sid      = "FullEC2Access"
        Effect   = "Allow"
        Action   = "ec2:*"
        Resource = "*"
      },
      {
        Sid      = "AttachDRSManagedPolicies"
        Effect   = "Allow"
        Action   = "iam:AttachRolePolicy"
        Resource = [
          aws_iam_role.drs_agent_role.arn,
          aws_iam_role.drs_failback_role.arn,
          aws_iam_role.drs_conversion_server_role.arn,
          aws_iam_role.drs_recovery_instance_role.arn,
          aws_iam_role.drs_replication_server_role.arn,
          aws_iam_role.drs_recovery_instance_launch_actions_role.arn
        ]
        Condition = {
          StringEquals = {
            "iam:PolicyARN" = [
              data.aws_iam_policy.drs_agent_policy.arn,
              data.aws_iam_policy.drs_failback_policy.arn,
              data.aws_iam_policy.drs_conversion_server_policy.arn,
              data.aws_iam_policy.drs_recovery_instance_policy.arn,
              data.aws_iam_policy.drs_replication_server_policy.arn
            ]
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "initializer_policy_attach" {
  role       = aws_iam_role.drs_initializer_role.name
  policy_arn = aws_iam_policy.initialize_policy.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "instance_count" {
  description = "Number of EC2 instances to launch"
  type        = number
  default     = 3
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  private_subnet_cidrs = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name      = "VPC_from_Terraform"
    Terraform = "true"
  }
}

resource "aws_subnet" "private" {
  count                   = length(local.private_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name      = "private-subnet-${count.index + 1}"
    Terraform = "true"
  }
}

resource "aws_security_group" "allow_ssh_http_https" {
  name        = "allow_ssh_http_https"
  description = "Allow SSH from VPC, HTTP/HTTPS from anywhere, egress to VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All traffic to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name                         = "allow_ssh_http_https"
    Terraform_SG_HTTP_HTTPS_SSH = "true"
  }
}

resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for CloudWatch Log Group encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-cloudwatch-1"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "kms:CancelKeyDeletion",
          "kms:CreateAlias",
          "kms:CreateGrant",
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:DisableKey",
          "kms:DisableKeyRotation",
          "kms:EnableKey",
          "kms:EnableKeyRotation",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:GetKeyPolicy",
          "kms:GetKeyRotationStatus",
          "kms:GetPublicKey",
          "kms:ListAliases",
          "kms:ListGrants",
          "kms:ListKeyPolicies",
          "kms:ListKeys",
          "kms:ListResourceTags",
          "kms:PutKeyPolicy",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo",
          "kms:RevokeGrant",
          "kms:ScheduleKeyDeletion",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:UpdateAlias",
          "kms:UpdateKeyDescription"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/cloudwatch-log-group"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

resource "aws_kms_key" "ebs" {
  description             = "KMS key for EBS root volume encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

resource "aws_cloudwatch_log_group" "vpc_flow_log" {
  name              = "/aws/vpc/flow-logs"
  retention_in_days = 14
  kms_key_id        = aws_kms_alias.cloudwatch.arn
}

resource "aws_iam_role" "vpc_flow_log_role" {
  name = "vpc-flow-log-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "vpc_flow_log_policy" {
  name        = "vpc-flow-log-policy"
  description = "Allows VPC Flow Logs to publish to CloudWatch Logs"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "VpcFlowLogsCloudWatch"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = aws_cloudwatch_log_group.vpc_flow_log.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "vpc_flow_log_attachment" {
  role       = aws_iam_role.vpc_flow_log_role.name
  policy_arn = aws_iam_policy.vpc_flow_log_policy.arn
}

resource "aws_flow_log" "main" {
  log_destination      = aws_cloudwatch_log_group.vpc_flow_log.arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.vpc_flow_log_role.arn
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.main.id

  depends_on = [
    aws_iam_role_policy_attachment.vpc_flow_log_attachment
  ]

  tags = {
    Name = "vpc-flow-log"
  }
}

resource "aws_instance" "terraform_instance" {
  count                  = var.instance_count
  ami                    = data.aws_ami.amazon_linux2.id
  instance_type          = "t2.micro"
  subnet_id              = aws_subnet.private[count.index % length(aws_subnet.private)].id
  vpc_security_group_ids = [aws_security_group.allow_ssh_http_https.id]

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    volume_size = 20
    encrypted   = true
    kms_key_id  = aws_kms_key.ebs.arn

    tags = {
      Name = "Terraform_EBS_Volume1"
    }
  }

  tags = {
    Name      = "Terraform_Instance"
    Terraform = "true"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

