      "elasticloadbalancing:ModifyRule",
      "lambda:InvokeFunction",
      "lambda:GetFunctionConfiguration",
      "cloudwatch:DescribeAlarms",
      "cloudwatch:GetMetricStatistics",
      "cloudwatch:PutMetricAlarm",
      "sns:Publish",
      "s3:GetObject",
      "s3:PutObject"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy" {
  name   = "ecs_codedeploy_role_policy"
  role   = aws_iam_role.ecs_codedeploy_role.id
  policy = data.aws_iam_policy_document.ecs_codedeploy_role_policy.json
}

data "aws_iam_policy_document" "ecs_codedeploy_role_policy_task" {
  statement {
    effect = "Allow"
    actions = ["iam:PassRole"]
    resources = [aws_iam_role.ecsTaskRole.arn]
  }
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task" {
  name   = "ecs_codedeploy_role_policy_task"
  role   = aws_iam_role.ecs_codedeploy_role.id
  policy = data.aws_iam_policy_document.ecs_codedeploy_role_policy_task.json
}

data "aws_iam_policy_document" "ecs_codedeploy_role_policy_task_exec" {
  statement {
    effect = "Allow"
    actions = ["iam:PassRole"]
    resources = [aws_iam_role.ecsExecTaskRole.arn]
  }
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task_exec" {
  name   = "ecs_codedeploy_role_policy_task_exec"
  role   = aws_iam_role.ecs_codedeploy_role.id
  policy = data.aws_iam_policy_document.ecs_codedeploy_role_policy_task_exec.json
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# External VPC
resource "aws_vpc" "external" {
  cidr_block           = "10.41.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name        = "Production External"
    purpose     = "Production External VPC"
    environment = "prod"
  }
}

resource "aws_default_security_group" "external" {
  vpc_id = aws_vpc.external.id
  ingress = []
  egress  = []
  tags = {
    Name = "default"
  }
}

resource "aws_default_network_acl" "external" {
  default_network_acl_id = aws_vpc.external.default_network_acl_id
  ingress {
    rule_no    = 100
    protocol   = "-1"
    from_port  = 0
    to_port    = 0
    cidr_block = "0.0.0.0/0"
    action     = "allow"
  }
  egress {
    rule_no    = 100
    protocol   = "icmp"
    from_port  = 0
    to_port    = 0
    cidr_block = "0.0.0.0/0"
    action     = "allow"
  }
  egress {
    rule_no    = 150
    protocol   = "-1"
    from_port  = 0
    to_port    = 0
    cidr_block = "0.0.0.0/0"
    action     = "allow"
  }
  tags = {
    Name = "default"
  }
}

resource "aws_internet_gateway" "external" {
  vpc_id = aws_vpc.external.id
  tags = {
    Name = "External GW"
  }
}

resource "aws_route_table" "external" {
  vpc_id = aws_vpc.external.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.external.id
  }
  tags = {
    Name = "External Route Table"
  }
}

resource "aws_main_route_table_association" "external" {
  vpc_id         = aws_vpc.external.id
  route_table_id = aws_route_table.external.id
}

resource "aws_subnet" "external" {
  count             = 4
  vpc_id            = aws_vpc.external.id
  cidr_block        = "10.41.${count.index}.0/24"
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = {
    Name = "Subnet${count.index}-1${substr(data.aws_availability_zones.available.names[count.index], length(data.aws_availability_zones.available.names[count.index]) - 1, 1)}"
  }
}

resource "aws_route_table_association" "external" {
  count          = 4
  subnet_id      = aws_subnet.external[count.index].id
  route_table_id = aws_route_table.external.id
}

# Internal VPC
resource "aws_vpc" "internal" {
  cidr_block       = "10.40.0.0/16"
  instance_tenancy = "default"
  tags = {
    Name        = "Production Internal"
    purpose     = "Production Internal VPC"
    environment = "prod"
  }
}

resource "aws_default_security_group" "internal" {
  vpc_id = aws_vpc.internal.id
  ingress = []
  egress  = []
  tags = {
    Name = "default"
  }
}

resource "aws_default_network_acl" "internal" {
  default_network_acl_id = aws_vpc.internal.default_network_acl_id
  ingress {
    rule_no    = 100
    protocol   = "icmp"
    from_port  = 0
    to_port    = 0
    cidr_block = "0.0.0.0/0"
    action     = "allow"
  }
  egress {
    rule_no    = 100
    protocol   = "icmp"
    from_port  = 0
    to_port    = 0
    cidr_block = "0.0.0.0/0"
    action     = "allow"
  }
  egress {
    rule_no    = 150
    protocol   = "-1"
    from_port  = 0
    to_port    = 0
    cidr_block = "0.0.0.0/0"
    action     = "allow"
  }
  tags = {
    Name = "default"
  }
}

resource "aws_subnet" "internal" {
  count             = 4
  vpc_id            = aws_vpc.internal.id
  cidr_block        = "10.40.${count.index}.0/24"
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = {
    Name = "Subnet${count.index}-1${substr(data.aws_availability_zones.available.names[count.index], length(data.aws_availability_zones.available.names[count.index]) - 1, 1)}"
  }
}

# VPC Flow Logs

resource "aws_kms_key" "cloudwatch_flow_logs" {
  description         = "KMS key for CloudWatch flow log groups"
  enable_key_rotation = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.us-east-1.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "cloudwatch_flow_logs" {
  name          = "alias/cloudwatch-flow-logs"
  target_key_id = aws_kms_key.cloudwatch_flow_logs.key_id
}

resource "aws_cloudwatch_log_group" "external_flow_log" {
  name              = "/aws/vpc/flow-logs/external"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.cloudwatch_flow_logs.arn
}

resource "aws_cloudwatch_log_group" "internal_flow_log" {
  name              = "/aws/vpc/flow-logs/internal"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.cloudwatch_flow_logs.arn
}

resource "aws_iam_role" "vpc_flow_log_role" {
  name = "vpc-flow-log-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "vpc_flow_log_policy" {
  name = "vpc-flow-log-policy"
  role = aws_iam_role.vpc_flow_log_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_flow_log" "external" {
  log_destination      = aws_cloudwatch_log_group.external_flow_log.arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.vpc_flow_log_role.arn
  vpc_id               = aws_vpc.external.id
  traffic_type         = "ALL"
}

resource "aws_flow_log" "internal" {
  log_destination      = aws_cloudwatch_log_group.internal_flow_log.arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.vpc_flow_log_role.arn
  vpc_id               = aws_vpc.internal.id
  traffic_type         = "ALL"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Variables
variable "prefix" {
  type    = string
  default = "n8n"
}

variable "certificate_arn" {
  type    = string
  default = null
}

variable "url" {
  type    = string
  default = null
}

variable "desired_count" {
  type    = number
  default = 1
}

variable "container_image" {
  type    = string
  default = "n8nio/n8n:1.4.0"
}

variable "fargate_type" {
  type    = string
  default = "FARGATE_SPOT"
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# Locals
locals {
  vpc_cidr            = "10.0.0.0/16"
  azs                 = slice(data.aws_availability_zones.available.names, 0, 3)
  private_cidrs       = ["10.0.0.0/24", "10.0.1.0/24", "10.0.2.0/24"]
  public_cidrs        = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]
  log_group_name      = "${var.prefix}-logs"
  flow_log_group_name = "${var.prefix}-flow-logs"
  certificate_arn     = var.certificate_arn != null ? var.certificate_arn : (try(aws_acm_certificate.self_signed[0].arn, ""))
}

# Random ID for unique service name
resource "random_id" "service_suffix" {
  keepers = {
    prefix = var.prefix
  }
  byte_length = 4
}

# VPC and Networking
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "${var.prefix}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${var.prefix}-igw"
  }
}

# Public subnets - map_public_ip_on_launch disabled per security fix
resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name = "${var.prefix}-public-${count.index}"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name = "${var.prefix}-private-${count.index}"
  }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = {
    Name = "${var.prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private route table (no default route)
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${var.prefix}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Security Groups with descriptions
# ALB Security Group
resource "aws_security_group" "alb" {
  name        = "${var.prefix}-alb-sg"
  description = "Security group for n8n ALB"
  vpc_id      = aws_vpc.main.id
  tags = {
    Name = "${var.prefix}-alb-sg"
  }
}

resource "aws_security_group_rule" "alb_inbound_http" {
  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.alb.id
  description       = "Allow HTTP from internet"
}

resource "aws_security_group_rule" "alb_inbound_https" {
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.alb.id
  description       = "Allow HTTPS from internet"
}

resource "aws_security_group_rule" "alb_outbound" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [local.vpc_cidr]
  security_group_id = aws_security_group.alb.id
  description       = "Allow outbound to VPC CIDR"
}

# EFS Security Group
resource "aws_security_group" "efs" {
  name        = "${var.prefix}-efs-sg"
  description = "Security group for n8n EFS"
  vpc_id      = aws_vpc.main.id
  tags = {
    Name = "${var.prefix}-efs-sg"
  }
}

resource "aws_security_group_rule" "efs_inbound" {
  type              = "ingress"
  from_port         = 2049
  to_port           = 2049
  protocol          = "tcp"
  cidr_blocks       = [local.vpc_cidr]
  security_group_id = aws_security_group.efs.id
  description       = "Allow NFS from VPC CIDR"
}

resource "aws_security_group_rule" "efs_outbound" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [local.vpc_cidr]
  security_group_id = aws_security_group.efs.id
  description       = "Allow outbound to VPC CIDR"
}

# ECS Task Security Group
resource "aws_security_group" "ecs_tasks" {
  name        = "${var.prefix}-ecs-tasks-sg"
  description = "Security group for n8n ECS tasks"
  vpc_id      = aws_vpc.main.id
  tags = {
    Name = "${var.prefix}-ecs-tasks-sg"
  }
}

resource "aws_security_group_rule" "ecs_tasks_inbound" {
  type                     = "ingress"
  from_port                = 5678
  to_port                  = 5678
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.alb.id
  security_group_id        = aws_security_group.ecs_tasks.id
  description              = "Allow n8n from ALB"
}

resource "aws_security_group_rule" "ecs_tasks_outbound" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [local.vpc_cidr]
  security_group_id = aws_security_group.ecs_tasks.id
  description       = "Allow outbound to VPC CIDR"
}

# Application Load Balancer
resource "aws_lb" "this" {
  name                       = "${var.prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true
  tags = {
    Name = "${var.prefix}-alb"
  }
}

# Target Group
resource "aws_lb_target_group" "this" {
  name                 = "${var.prefix}-tg"
  port                 = 80
  protocol             = "HTTP"
  target_type          = "ip"
  vpc_id               = aws_vpc.main.id
  deregistration_delay = 30
  health_check {
    path                = "/healthz"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    interval            = 30
  }
  tags = {
    Name = "${var.prefix}-tg"
  }
}

# Self-signed certificate (conditional)
resource "tls_private_key" "self_signed" {
  count     = var.certificate_arn == null ? 1 : 0
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  count           = var.certificate_arn == null ? 1 : 0
  private_key_pem = tls_private_key.self_signed[0].private_key_pem
  subject {
    common_name = "${var.prefix}.local"
  }
  validity_period_hours = 8760
  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "self_signed" {
  count             = var.certificate_arn == null ? 1 : 0
  private_key       = tls_private_key.self_signed[0].private_key_pem
  certificate_body  = tls_self_signed_cert.self_signed[0].cert_pem
  certificate_chain = ""
  tags = {
    Name = "${var.prefix}-self-signed"
  }
}

# HTTPS Listener
resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.this.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = local.certificate_arn
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.this.arn
  }
}

# HTTP Listener (redirect to HTTPS)
resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.this.arn
  port              = 80
  protocol          = "HTTP"
  default_action {
    type = "redirect"
    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
      host        = "#{host}"
      path        = "/#{path}"
      query       = "#{query}"
    }
  }
}

# EFS File System (lifecycle prevent_destroy removed per fix objective)
resource "aws_efs_file_system" "this" {
  creation_token = "${var.prefix}-efs"
  encrypted      = true
  tags = {
    Name = "${var.prefix}-efs"
  }
}

# EFS Access Point
resource "aws_efs_access_point" "this" {
  file_system_id = aws_efs_file_system.this.id
  posix_user {
    uid = 1000
    gid = 1000
  }
  root_directory {
    path = "/n8n"
    creation_info {
      owner_uid   = 1000
      owner_gid   = 1000
      permissions = "777"
    }
  }
  tags = {
    Name = "${var.prefix}-efs-ap"
  }
}

# EFS Mount Targets
resource "aws_efs_mount_target" "this" {
  count           = 3
  file_system_id  = aws_efs_file_system.this.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
}

# KMS key for CloudWatch Log Group encryption
resource "aws_kms_key" "logs" {
  description             = "KMS key for n8n CloudWatch log groups"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = {
    Name = "${var.prefix}-logs-kms"
  }
}

# KMS Alias using name_prefix to avoid name collisions
resource "aws_kms_alias" "logs" {
  name_prefix   = "alias/${var.prefix}-logs-"
  target_key_id = aws_kms_key.logs.key_id
}

# CloudWatch Log Groups
resource "aws_cloudwatch_log_group" "this" {
  name              = local.log_group_name
  retention_in_days = 1
  kms_key_id        = aws_kms_alias.logs.arn
  tags = {
    Name = local.log_group_name
  }
}

# VPC Flow Logs resources
resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = local.flow_log_group_name
  retention_in_days = 1
  kms_key_id        = aws_kms_alias.logs.arn
  tags = {
    Name = local.flow_log_group_name
  }
}

# IAM Role for Flow Logs using name_prefix
resource "aws_iam_role" "flow_logs" {
  name_prefix = "${var.prefix}-flow-logs-role-"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })
  tags = {
    Name = "${var.prefix}-flow-logs-role"
  }
}

resource "aws_iam_policy" "flow_logs" {
  name        = "${var.prefix}-flow-logs-policy"
  description = "Inline policy for VPC Flow Logs"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Effect   = "Allow"
        Resource = "${aws_cloudwatch_log_group.flow_logs.arn}:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "flow_logs" {
  role       = aws_iam_role.flow_logs.name
  policy_arn = aws_iam_policy.flow_logs.arn
}

resource "aws_flow_log" "this" {
  log_destination      = aws_cloudwatch_log_group.flow_logs.arn
  iam_role_arn         = aws_iam_role.flow_logs.arn
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
  tags = {
    Name = "${var.prefix}-flow-log"
  }
}

# IAM Roles and Policies for ECS
# Task Execution Role using name_prefix
resource "aws_iam_role" "execution" {
  name_prefix = "${var.prefix}-execution-role-"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })
  tags = {
    Name = "${var.prefix}-execution-role"
  }
}

resource "aws_iam_policy" "execution" {
  name        = "${var.prefix}-execution-policy"
  description = "Inline policy for ECS task execution"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups"
        ]
        Effect   = "Allow"
        Resource = "${aws_cloudwatch_log_group.this.arn}:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "execution" {
  role       = aws_iam_role.execution.name
  policy_arn = aws_iam_policy.execution.arn
}

# Task Role using name_prefix
resource "aws_iam_role" "task" {
  name_prefix = "${var.prefix}-task-role-"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })
  tags = {
    Name = "${var.prefix}-task-role"
  }
}

resource "aws_iam_policy" "task" {
  name        = "${var.prefix}-task-policy"
  description = "Inline policy for ECS task"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups"
        ]
        Effect   = "Allow"
        Resource = "${aws_cloudwatch_log_group.this.arn}:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "task" {
  role       = aws_iam_role.task.name
  policy_arn = aws_iam_policy.task.arn
}

# ECS Cluster with container insights enabled
resource "aws_ecs_cluster" "this" {
  name = "${var.prefix}-cluster"
  setting {
    name  = "containerInsights"
    value = "enabled"
  }
  tags = {
    Name = "${var.prefix}-cluster"
  }
}

# Capacity provider - using managed FARGATE_SPOT / FARGATE
resource "aws_ecs_cluster_capacity_providers" "this" {
  cluster_name       = aws_ecs_cluster.this.name
  capacity_providers = [var.fargate_type]
  default_capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }
}

# Task Definition
resource "aws_ecs_task_definition" "this" {
  family                   = "${var.prefix}-task"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"
  execution_role_arn       = aws_iam_role.execution.arn
  task_role_arn            = aws_iam_role.task.arn

  volume {
    name = "n8n-data"
    efs_volume_configuration {
      file_system_id     = aws_efs_file_system.this.id
      transit_encryption = "ENABLED"
      authorization_config {
        iam = "ENABLED"
      }
      root_directory = "/"
    }
  }

  container_definitions = jsonencode([
    {
      name      = "n8n"
      image     = var.container_image
      essential = true
      portMappings = [
        {
          containerPort = 5678
          hostPort      = 5678
          protocol      = "tcp"
        }
      ]
      environment = [
        {
          name  = "N8N_SKIP_WEBHOOK_DEREGISTRATION_SHUTDOWN"
          value = "true"
        },
        {
          name  = "WEBHOOK_URL"
          value = var.url != null ? var.url : "https://${aws_lb.this.dns_name}"
        }
      ]
      mountPoints = [
        {
          sourceVolume  = "n8n-data"
          containerPath = "/home/node/.n8n"
          readOnly      = false
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = local.log_group_name
          "awslogs-region"        = data.aws_availability_zones.available.id
          "awslogs-stream-prefix" = "ecs"
          "awslogs-create-group"  = "true"
        }
      }
    }
  ])

  tags = {
    Name = "${var.prefix}-task-definition"
  }
}

# ECS Service with unique name using random suffix
resource "aws_ecs_service" "this" {
  name            = "${var.prefix}-service-${random_id.service_suffix.hex}"
  cluster         = aws_ecs_cluster.this.id
  task_definition = aws_ecs_task_definition.this.arn
  desired_count   = var.desired_count

  network_configuration {
    subnets          = aws_subnet.public[*].id
    assign_public_ip = true
    security_groups  = [aws_security_group.ecs_tasks.id]
  }

  capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }

  depends_on = [
    aws_lb_listener.https,
    aws_lb_listener.http
  ]

  tags = {
    Name = "${var.prefix}-service"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
