  egress {
    description = "All traffic to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.32.0.0/20"]
  }

  tags = {
    Name = "lambda-rds-dev-postgres-db"
  }
}

resource "aws_security_group" "lambda_rds_dev_lambda_functions" {
  name        = "lambda-rds-dev-lambda-functions"
  description = "Security group for Lambda functions"
  vpc_id      = aws_vpc.lambda_rds_dev.id

  ingress = []

  egress {
    description = "All traffic to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.32.0.0/20"]
  }

  tags = {
