  source_security_group_id = aws_security_group.lambda_rds_dev_postgres_db.id
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  description              = "PostgreSQL to database security group"
}

resource "aws_kms_key" "flow_logs" {
  description         = "KMS key for VPC Flow Logs encryption"
  enable_key_rotation = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable Root Account Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = {
    Name = "lambda-rds-dev-flow-logs-key"
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

resource "aws_kms_alias" "flow_logs" {
  name          = "alias/lambda-rds-dev-flow-logs"
  target_key_id = aws_kms_key.flow_logs.key_id
}

resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = "lambda-rds-dev-flow-logs"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.flow_logs.arn
  tags = {
    Name = "lambda-rds-dev-flow-logs"
  }
}

resource "aws_iam_role" "flow_logs" {
  name = "lambda-rds-dev-flow-logs-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })
  tags = {
    Name = "lambda-rds-dev-flow-logs-role"
  }
}

resource "aws_iam_role_policy" "flow_logs_policy" {
  name = "lambda-rds-dev-flow-logs-policy"
  role = aws_iam_role.flow_logs.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:lambda-rds-dev-flow-logs:*"
      }
    ]
  })
}

resource "aws_flow_log" "lambda_rds_dev" {
  iam_role_arn         = aws_iam_role.flow_logs.arn
  log_destination      = aws_cloudwatch_log_group.flow_logs.arn
  log_destination_type = "cloud-watch-logs"
  traffic_type         = "REJECT"
  vpc_id               = aws_vpc.lambda_rds_dev.id
  tags = {
    Name = "lambda-rds-dev-flow-log"
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "admin_cidr" {
  description = "CIDR block for admin/SSH access"
  type        = string
  default     = "203.0.113.0/24"
}

variable "environment" {
  description = "Environment tag"
  type        = string
  default     = "production"
}

variable "application" {
  description = "Application tag"
  type        = string
  default     = "dosomething-quasar"
}

variable "stack" {
  description = "Stack tag"
  type        = string
  default     = "data"
}

locals {
  common_tags = {
    Application = var.application
    Environment = var.environment
    Stack       = var.stack
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "quasar" {
  cidr_block           = "10.255.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "Quasar"
  })
}

resource "aws_subnet" "quasar_rds_1a" {
  vpc_id            = aws_vpc.quasar.id
  cidr_block        = "10.255.100.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "Quasar RDS - 1A"
  })
}

resource "aws_subnet" "quasar_rds_1e" {
  vpc_id            = aws_vpc.quasar.id
  cidr_block        = "10.255.101.0/24"
  availability_zone = data.aws_availability_zones.available.names[4]

  tags = merge(local.common_tags, {
    Name = "Quasar RDS - 1E"
  })
}

resource "aws_route_table" "quasar" {
  vpc_id = aws_vpc.quasar.id

  route {
    cidr_block = "10.255.0.0/16"
    gateway_id = "local"
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-RouteTable"
  })
}

resource "aws_route_table_association" "quasar_rds_1a" {
  subnet_id      = aws_subnet.quasar_rds_1a.id
  route_table_id = aws_route_table.quasar.id
}

resource "aws_route_table_association" "quasar_rds_1e" {
  subnet_id      = aws_subnet.quasar_rds_1e.id
  route_table_id = aws_route_table.quasar.id
}

# KMS key for CloudWatch Log Group encryption
resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for CloudWatch Log Group encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable CloudWatch Logs"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
  tags = local.common_tags
}

data "aws_caller_identity" "current" {}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/cloudwatch-quasar"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

# VPC Flow Logs support resources
resource "aws_cloudwatch_log_group" "vpc_flow_log" {
  name              = "/aws/vpc/flow-logs/quasar"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.cloudwatch.arn
  tags              = local.common_tags
}

resource "aws_iam_role" "vpc_flow_log" {
  name = "QuasarVPCFlowLogRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "vpc_flow_log" {
  name = "QuasarVPCFlowLogPolicy"
  role = aws_iam_role.vpc_flow_log.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          aws_cloudwatch_log_group.vpc_flow_log.arn,
          "${aws_cloudwatch_log_group.vpc_flow_log.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_flow_log" "quasar" {
  log_destination      = aws_cloudwatch_log_group.vpc_flow_log.arn
  log_destination_type = "cloud-watch-logs"
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.quasar.id
  iam_role_arn         = aws_iam_role.vpc_flow_log.arn
  tags                 = local.common_tags
}

# Security Groups

resource "aws_security_group" "quasar_bastion" {
  name_prefix = "Quasar-Bastion-"
  vpc_id      = aws_vpc.quasar.id
  description = "Bastion security group"

  tags = merge(local.common_tags, {
    Name = "Quasar-Bastion"
  })
}

resource "aws_security_group_rule" "bastion_ingress_ssh" {
  type              = "ingress"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = [var.admin_cidr]
  security_group_id = aws_security_group.quasar_bastion.id
  description       = "Allow SSH from admin CIDR"
}

resource "aws_security_group_rule" "bastion_egress" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.quasar.cidr_block]
  security_group_id = aws_security_group.quasar_bastion.id
  description       = "Egress to VPC CIDR"
}

resource "aws_security_group" "quasar_ha_proxy" {
  name_prefix = "Quasar-HA-Proxy-"
  vpc_id      = aws_vpc.quasar.id
  description = "HAProxy security group"

  tags = merge(local.common_tags, {
    Name = "Quasar-HA-Proxy"
  })
}

resource "aws_security_group_rule" "haproxy_ingress_http" {
  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.quasar_ha_proxy.id
  description       = "Allow HTTP from anywhere"
}

resource "aws_security_group_rule" "haproxy_ingress_https" {
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.quasar_ha_proxy.id
  description       = "Allow HTTPS from anywhere"
}

resource "aws_security_group_rule" "haproxy_ingress_ssh" {
  type                     = "ingress"
  from_port                = 22
  to_port                  = 22
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.quasar_bastion.id
  security_group_id        = aws_security_group.quasar_ha_proxy.id
  description              = "Allow SSH from Bastion SG"
}

resource "aws_security_group_rule" "haproxy_egress" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.quasar.cidr_block]
  security_group_id = aws_security_group.quasar_ha_proxy.id
  description       = "Egress to VPC CIDR"
}

resource "aws_security_group" "quasar_jenkins" {
  name_prefix = "Quasar-Jenkins-"
  vpc_id      = aws_vpc.quasar.id
  description = "Jenkins security group"

  tags = merge(local.common_tags, {
    Name = "Quasar-Jenkins"
  })
}

resource "aws_security_group_rule" "jenkins_ingress_ssh" {
  type                     = "ingress"
  from_port                = 22
  to_port                  = 22
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.quasar_bastion.id
  security_group_id        = aws_security_group.quasar_jenkins.id
  description              = "Allow SSH from Bastion SG"
}

resource "aws_security_group_rule" "jenkins_ingress_8080" {
  type                     = "ingress"
  from_port                = 8080
  to_port                  = 8080
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.quasar_ha_proxy.id
  security_group_id        = aws_security_group.quasar_jenkins.id
  description              = "Allow port 8080 from HAProxy SG"
}

resource "aws_security_group_rule" "jenkins_egress" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.quasar.cidr_block]
  security_group_id = aws_security_group.quasar_jenkins.id
  description       = "Egress to VPC CIDR"
}

resource "aws_security_group" "quasar_etl" {
  name_prefix = "Quasar-ETL-"
  vpc_id      = aws_vpc.quasar.id
  description = "ETL security group"

  tags = merge(local.common_tags, {
    Name = "Quasar-ETL"
  })
}

resource "aws_security_group_rule" "etl_ingress_ssh_bastion" {
  type                     = "ingress"
  from_port                = 22
  to_port                  = 22
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.quasar_bastion.id
  security_group_id        = aws_security_group.quasar_etl.id
  description              = "Allow SSH from Bastion SG"
}

resource "aws_security_group_rule" "etl_ingress_ssh_jenkins" {
  type                     = "ingress"
  from_port                = 22
  to_port                  = 22
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.quasar_jenkins.id
  security_group_id        = aws_security_group.quasar_etl.id
  description              = "Allow SSH from Jenkins SG"
}

resource "aws_security_group_rule" "etl_egress" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.quasar.cidr_block]
  security_group_id = aws_security_group.quasar_etl.id
  description       = "Egress to VPC CIDR"
}

resource "aws_security_group" "quasar_postgresql" {
  name_prefix = "Quasar-PostgreSQL-"
  vpc_id      = aws_vpc.quasar.id
  description = "PostgreSQL security group"

  tags = merge(local.common_tags, {
    Name = "Quasar-PostgreSQL"
  })
}

resource "aws_security_group_rule" "postgresql_ingress_all" {
  type              = "ingress"
  from_port         = 5432
  to_port           = 5432
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.quasar_postgresql.id
  description       = "Allow PostgreSQL from anywhere"
}

resource "aws_security_group_rule" "postgresql_ingress_etl" {
  type                     = "ingress"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.quasar_etl.id
  security_group_id        = aws_security_group.quasar_postgresql.id
  description              = "Allow PostgreSQL from ETL SG"
}

resource "aws_security_group_rule" "postgresql_egress" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.quasar.cidr_block]
  security_group_id = aws_security_group.quasar_postgresql.id
  description       = "Egress to VPC CIDR"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "create" {
  description = "Whether to create SQS resources"
  type        = bool
  default     = true
}

variable "queue_name" {
  description = "Human-readable queue name (will strip .fifo suffix if present)"
  type        = string
  default     = "my-queue"
}

variable "use_name_prefix" {
  description = "Use queue_name as a prefix instead of the exact name"
  type        = bool
  default     = false
}

variable "fifo_queue" {
  description = "Whether the queue is FIFO"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication (FIFO only)"
  type        = bool
  default     = null
}

variable "deduplication_scope" {
  description = "Deduplication scope for FIFO queues: 'queue' or 'messageGroup'"
  type        = string
  default     = null
}

variable "fifo_throughput_limit" {
  description = "FIFO throughput limit: 'perQueue' or 'perMessageGroupId'"
  type        = string
  default     = null
}

variable "delay_seconds" {
  description = "Delay in seconds for the queue"
  type        = number
  default     = null
}

variable "max_message_size" {
  description = "Maximum message size in bytes (1024-262144)"
  type        = number
  default     = null
}

variable "message_retention_seconds" {
  description = "Message retention period in seconds (60-1209600)"
  type        = number
  default     = null
}

variable "receive_wait_time_seconds" {
  description = "Receive wait time in seconds (0-20)"
  type        = number
  default     = null
}

variable "visibility_timeout_seconds" {
  description = "Visibility timeout in seconds (0-43200)"
  type        = number
  default     = null
}

variable "sqs_managed_sse_enabled" {
  description = "Enable SQS-managed SSE (default true); set to false to use custom KMS key"
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "Custom KMS key ARN for encryption (leave empty to create a new key when sqs_managed_sse_enabled is false)"
  type        = string
  default     = ""
}

variable "kms_data_key_reuse_period_seconds" {
  description = "Data key reuse period in seconds for KMS encryption"
  type        = number
  default     = null
}

variable "create_queue_policy" {
  description = "Whether to create a policy for the main queue"
  type        = bool
  default     = false
}

variable "queue_policy_source_policy_documents" {
  description = "List of IAM policy JSON documents to merge for the main queue policy"
  type        = list(string)
  default     = []
}

variable "queue_policy_statements" {
  description = "List of statement objects for the main queue policy"
  type = list(object({
    sid       = optional(string)
    effect    = string
    actions   = list(string)
    resources = list(string)
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    condition = optional(object({
      test     = string
      variable = string
      values   = list(string)
    }))
  }))
  default = []
}

variable "create_dlq" {
  description = "Whether to create a dead-letter queue"
  type        = bool
  default     = false
}

variable "create_dlq_queue_policy" {
  description = "Whether to create a policy for the DLQ"
  type        = bool
  default     = false
}

variable "create_dlq_redrive_allow_policy" {
  description = "Whether to attach a redrive allow policy to the DLQ"
  type        = bool
  default     = true
}

variable "dlq_sqs_managed_sse_enabled" {
  description = "Override SQS-managed SSE for DLQ (null = inherit from main)"
  type        = bool
  default     = null
}

variable "dlq_kms_master_key_id" {
  description = "Override KMS key ARN for DLQ (empty = inherit from main)"
  type        = string
  default     = ""
}

variable "dlq_kms_data_key_reuse_period_seconds" {
  description = "Override data key reuse period for DLQ"
  type        = number
  default     = null
}

variable "dlq_delay_seconds" {
  description = "Override delay_seconds for DLQ"
  type        = number
  default     = null
}

variable "dlq_max_message_size" {
  description = "Override max_message_size for DLQ"
  type        = number
  default     = null
}

variable "dlq_message_retention_seconds" {
  description = "Override message_retention_seconds for DLQ"
  type        = number
  default     = null
}

variable "dlq_receive_wait_time_seconds" {
  description = "Override receive_wait_time_seconds for DLQ"
  type        = number
  default     = null
}

variable "dlq_visibility_timeout_seconds" {
  description = "Override visibility_timeout_seconds for DLQ"
  type        = number
  default     = null
}

variable "dlq_queue_policy_source_policy_documents" {
  description = "List of IAM policy JSON documents to merge for the DLQ policy"
  type        = list(string)
  default     = []
}

variable "dlq_queue_policy_statements" {
  description = "List of statement objects for the DLQ policy"
  type = list(object({
    sid       = optional(string)
    effect    = string
    actions   = list(string)
    resources = list(string)
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    condition = optional(object({
      test     = string
      variable = string
      values   = list(string)
    }))
  }))
  default = []
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCES (static/well-known only)
# ---------------------------------------------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# ---------------------------------------------------------------------------------------------------------------------
# LOCALS
# ---------------------------------------------------------------------------------------------------------------------

locals {
  # Strip .fifo from the provided name
  base_name = replace(var.queue_name, ".fifo", "")

  # Final name/prefix for the main queue (without .fifo suffix yet)
  main_queue_base = var.use_name_prefix ? local.base_name : local.base_name
  main_queue_name = var.fifo_queue ? "${local.main_queue_base}.fifo" : local.main_queue_base
  main_queue_prefix = var.use_name_prefix ? local.main_queue_base : null

  # DLQ name derived from base_name
  dlq_base_name = "${local.base_name}-dlq"
  dlq_queue_name = var.fifo_queue ? "${local.dlq_base_name}.fifo" : local.dlq_base_name
  dlq_queue_prefix = var.use_name_prefix ? local.dlq_base_name : null

  # Effective encryption settings for DLQ (inherit from main if not overridden)
  dlq_sqs_managed_sse = var.dlq_sqs_managed_sse_enabled != null ? var.dlq_sqs_managed_sse_enabled : var.sqs_managed_sse_enabled
  dlq_kms_key_id      = var.dlq_kms_master_key_id != "" ? var.dlq_kms_master_key_id : var.kms_master_key_id
  dlq_kms_reuse       = var.dlq_kms_data_key_reuse_period_seconds != null ? var.dlq_kms_data_key_reuse_period_seconds : var.kms_data_key_reuse_period_seconds

  # Determine if we need to create a custom KMS key for the main queue
  create_kms_key = var.create && !var.sqs_managed_sse_enabled && var.kms_master_key_id == ""
}

# ---------------------------------------------------------------------------------------------------------------------
# KMS KEY (only when custom encryption requested and no existing key ARN provided)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_kms_key" "sqs" {
  count                    = local.create_kms_key ? 1 : 0
  description             = "SQS encryption key for queue ${var.queue_name}"
  key_usage               = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  enable_key_rotation     = true
  policy = data.aws_iam_policy_document.kms_sqs_policy[0].json
}

resource "aws_kms_alias" "sqs" {
  count         = local.create_kms_key ? 1 : 0
  name          = "alias/${var.queue_name}-sqs-key"
  target_key_id = aws_kms_key.sqs[0].key_id
}

data "aws_iam_policy_document" "kms_sqs_policy" {
  count = local.create_kms_key ? 1 : 0
  statement {
    sid    = "Enable SQS to use the key"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["sqs.${data.aws_partition.current.dns_suffix}"]
    }
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt"
    ]
    resources = ["*"]
  }
  statement {
    sid    = "Allow account to manage key"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# PRIMARY QUEUE
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_sqs_queue" "this" {
  count = var.create ? 1 : 0

  name       = var.use_name_prefix ? null : local.main_queue_name
  name_prefix = var.use_name_prefix ? local.main_queue_prefix : null

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.content_based_deduplication
  deduplication_scope         = var.deduplication_scope
  fifo_throughput_limit       = var.fifo_throughput_limit

  delay_seconds              = var.delay_seconds
  max_message_size           = var.max_message_size
  message_retention_seconds  = var.message_retention_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  sqs_managed_sse_enabled = var.sqs_managed_sse_enabled
  kms_master_key_id       = var.sqs_managed_sse_enabled ? null : (var.kms_master_key_id != "" ? var.kms_master_key_id : try(aws_kms_key.sqs[0].arn, null))
  kms_data_key_reuse_period_seconds = var.kms_data_key_reuse_period_seconds

  redrive_policy = var.create_dlq ? jsonencode({
    deadLetterTargetArn = try(aws_sqs_queue.dlq[0].arn, "")
    maxReceiveCount     = 5
  }) : null

  tags = {
    Name = var.queue_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# MAIN QUEUE POLICY (conditional)
# ---------------------------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "queue_policy" {
  count = var.create && var.create_queue_policy ? 1 : 0

  source_policy_documents = var.queue_policy_source_policy_documents

  dynamic "statement" {
    for_each = var.queue_policy_statements
    content {
      sid       = statement.value.sid
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = statement.value.resources
      dynamic "principals" {
        for_each = statement.value.principals != null ? statement.value.principals : []
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }
      dynamic "condition" {
        for_each = statement.value.condition != null ? [statement.value.condition] : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count     = var.create && var.create_queue_policy ? 1 : 0
  queue_url = aws_sqs_queue.this[0].id
  policy    = data.aws_iam_policy_document.queue_policy[0].json
}

# ---------------------------------------------------------------------------------------------------------------------
# DEAD-LETTER QUEUE (conditional)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_sqs_queue" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  name       = var.use_name_prefix ? null : local.dlq_queue_name
  name_prefix = var.use_name_prefix ? local.dlq_queue_prefix : null

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? (var.content_based_deduplication != null ? var.content_based_deduplication : null) : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  delay_seconds              = var.dlq_delay_seconds
  max_message_size           = var.dlq_max_message_size
  message_retention_seconds  = var.dlq_message_retention_seconds
  receive_wait_time_seconds  = var.dlq_receive_wait_time_seconds
  visibility_timeout_seconds = var.dlq_visibility_timeout_seconds

  sqs_managed_sse_enabled = local.dlq_sqs_managed_sse
  kms_master_key_id       = local.dlq_sqs_managed_sse ? null : (local.dlq_kms_key_id != "" ? local.dlq_kms_key_id : try(aws_kms_key.sqs[0].arn, null))
  kms_data_key_reuse_period_seconds = local.dlq_kms_reuse

  tags = {
    Name = "${var.queue_name}-dlq"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# DLQ REDRIVE ALLOW POLICY (conditional)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_sqs_queue_redrive_allow_policy" "dlq" {
  count     = var.create && var.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0
  queue_url = aws_sqs_queue.dlq[0].id

  redrive_allow_policy = jsonencode({
    redrivePermission = "byQueue",
    sourceQueueArns   = [aws_sqs_queue.this[0].arn]
  })
}

# ---------------------------------------------------------------------------------------------------------------------
# DLQ QUEUE POLICY (conditional)
# ---------------------------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "dlq_queue_policy" {
  count = var.create && var.create_dlq && var.create_dlq_queue_policy ? 1 : 0

  source_policy_documents = var.dlq_queue_policy_source_policy_documents

  dynamic "statement" {
    for_each = var.dlq_queue_policy_statements
    content {
      sid       = statement.value.sid
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = statement.value.resources
      dynamic "principals" {
        for_each = statement.value.principals != null ? statement.value.principals : []
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }
      dynamic "condition" {
        for_each = statement.value.condition != null ? [statement.value.condition] : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "dlq" {
  count     = var.create && var.create_dlq && var.create_dlq_queue_policy ? 1 : 0
  queue_url = aws_sqs_queue.dlq[0].id
  policy    = data.aws_iam_policy_document.dlq_queue_policy[0].json
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "queue_arn" {
  description = "ARN of the main SQS queue"
  value       = var.create ? aws_sqs_queue.this[0].arn : null
}

output "queue_url" {
  description = "URL of the main SQS queue"
  value       = var.create ? aws_sqs_queue.this[0].url : null
}

output "queue_id" {
  description = "ID of the main SQS queue"
  value       = var.create ? aws_sqs_queue.this[0].id : null
}

output "dlq_arn" {
  description = "ARN of the dead-letter queue"
  value       = var.create && var.create_dlq ? aws_sqs_queue.dlq[0].arn : null
}

output "dlq_url" {
  description = "URL of the dead-letter queue"
  value       = var.create && var.create_dlq ? aws_sqs_queue.dlq[0].url : null
}

output "dlq_id" {
  description = "ID of the dead-letter queue"
  value       = var.create && var.create_dlq ? aws_sqs_queue.dlq[0].id : null
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------
variable "create" {
  description = "Global toggle to create all resources"
  type        = bool
  default     = true
}

variable "create_app" {
  description = "Create the CodeDeploy application"
  type        = bool
  default     = false
}

variable "use_existing_app" {
  description = "Use an existing CodeDeploy application instead of creating one"
  type        = bool
  default     = false
}

variable "app_name" {
  description = "Name of the CodeDeploy application"
  type        = string
  default     = "lambda-app"
}

variable "create_deployment_group" {
  description = "Create the deployment group"
  type        = bool
  default     = false
}

variable "use_existing_deployment_group" {
  description = "Use an existing deployment group instead of creating one"
  type        = bool
  default     = false
}

variable "deployment_group_name" {
  description = "Name of the deployment group (used when creating or referencing existing)"
  type        = string
  default     = ""
}

variable "deployment_config_name" {
  description = "Deployment configuration name"
  type        = string
  default     = "CodeDeployDefault.LambdaAllAtOnce"
}

variable "create_codedeploy_role" {
  description = "Create the IAM role for CodeDeploy"
  type        = bool
  default     = true
}

variable "attach_hooks_policy" {
  description = "Attach inline policy for Lambda invoke permissions on lifecycle hooks"
  type        = bool
  default     = true
}

variable "attach_triggers_policy" {
  description = "Attach inline policy for SNS publish permissions on triggers"
  type        = bool
  default     = false
}

variable "create_deployment" {
  description = "Create the deployment (null_resource with local-exec)"
  type        = bool
  default     = false
}

variable "aws_cli_command" {
  description = "AWS CLI command to use (e.g., 'aws' or 'aws2')"
  type        = string
  default     = "aws"
}

variable "get_deployment_sleep_timer" {
  description = "Sleep interval in seconds between deployment status checks"
  type        = number
  default     = 5
}

variable "save_deploy_script" {
  description = "Save the deployment script locally as a file"
  type        = bool
  default     = false
}

variable "run_deployment" {
  description = "Execute the deployment via local-exec provisioner"
  type        = bool
  default     = false
}

variable "function_name" {
  description = "Name of the Lambda function to deploy"
  type        = string
  default     = "my-function"
}

variable "alias_name" {
  description = "Name of the Lambda alias"
  type        = string
  default     = "prod"
}

variable "current_version" {
  description = "Current version of the Lambda function"
  type        = string
  default     = "1"
}

variable "target_version" {
  description = "Target version for the deployment"
  type        = string
  default     = "2"
}

variable "before_allow_traffic_hook_arn" {
  description = "ARN of the Lambda function to run before allowing traffic"
  type        = string
  default     = null
}

variable "after_allow_traffic_hook_arn" {
  description = "ARN of the Lambda function to run after allowing traffic"
  type        = string
  default     = null
}

variable "alarm_names" {
  description = "List of CloudWatch alarm names for automatic rollback"
  type        = list(string)
  default     = []
}

variable "trigger_topic_arn" {
  description = "ARN of the SNS topic for deployment notifications"
  type        = string
  default     = null
}

variable "trigger_events" {
  description = "List of events for the deployment trigger"
  type        = list(string)
  default     = []
}

# ------------------------------------------------------------------------------
# LOCALS
# ------------------------------------------------------------------------------
locals {
  # Derive deployment group name if not provided
  deployment_group_name = var.deployment_group_name != "" ? var.deployment_group_name : "${var.app_name}-deployment-group"

  # Construct AppSpec JSON for Lambda
  # Hooks must be a map of event name to ARN string.
  hooks_map = merge(
    var.before_allow_traffic_hook_arn != null ? { BeforeAllowTraffic = var.before_allow_traffic_hook_arn } : {},
    var.after_allow_traffic_hook_arn != null ? { AfterAllowTraffic = var.after_allow_traffic_hook_arn } : {}
  )

  appspec = jsonencode({
    version = 0.0
    Resources = [
      {
        Type = "AWS::Lambda::Function"
        Properties = {
          Name           = var.function_name
          Alias          = var.alias_name
          CurrentVersion = var.current_version
          TargetVersion  = var.target_version
        }
      }
    ]
    Hooks = local.hooks_map
  })

  # Shell script for deployment and monitoring
  deploy_script = <<-EOT
#!/bin/bash
set -e

APPSPEC='${local.appspec}'

DEPLOYMENT_ID=$(${var.aws_cli_command} deploy create-deployment \
  --application-name "${var.app_name}" \
  --deployment-group-name "${local.deployment_group_name}" \
  --revision revisionType=AppSpecContent,appSpecContent="{content=${local.appspec}}" \
  --query 'deploymentId' \
  --output text)

echo "Deployment ID: $DEPLOYMENT_ID"

STATUS=""
while [ "$STATUS" != "Succeeded" ] && [ "$STATUS" != "Failed" ] && [ "$STATUS" != "Stopped" ]; do
  sleep ${var.get_deployment_sleep_timer}
  STATUS=$(${var.aws_cli_command} deploy get-deployment --deployment-id "$DEPLOYMENT_ID" --query 'deploymentInfo.status' --output text)
  echo "Deployment status: $STATUS"
done

if [ "$STATUS" == "Succeeded" ]; then
  echo "Deployment succeeded."
else
  echo "Deployment finished with status: $STATUS"
  exit 1
fi
EOT
}

# ------------------------------------------------------------------------------
# RANDOM UUID FOR DEPLOYMENT TRIGGER
# ------------------------------------------------------------------------------
resource "random_uuid" "deploy_trigger" {
  count = var.create && var.run_deployment ? 1 : 0
}

# ------------------------------------------------------------------------------
# IAM ROLE FOR CODEPLOY
# ------------------------------------------------------------------------------
resource "aws_iam_role" "codedeploy_lambda" {
  count = var.create && var.create_codedeploy_role ? 1 : 0
  name  = "${var.app_name}-codedeploy-lambda-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codedeploy.amazonaws.com"
        }
      }
    ]
  })
}

# Attach the correct managed policy for Lambda deployments
resource "aws_iam_role_policy_attachment" "codedeploy_lambda_managed" {
  count      = var.create && var.create_codedeploy_role ? 1 : 0
  role       = aws_iam_role.codedeploy_lambda[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeDeployRoleForLambda"
}

# Inline policy for hooks (Lambda invoke) – only when at least one hook ARN is provided
resource "aws_iam_role_policy" "codedeploy_hooks" {
  count = var.create && var.create_codedeploy_role && var.attach_hooks_policy && (var.before_allow_traffic_hook_arn != null || var.after_allow_traffic_hook_arn != null) ? 1 : 0
  name  = "${var.app_name}-codedeploy-hooks-policy"
  role  = aws_iam_role.codedeploy_lambda[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "lambda:InvokeFunction"
        Resource = [for arn in [var.before_allow_traffic_hook_arn, var.after_allow_traffic_hook_arn] : arn if arn != null]
      }
    ]
  })
}

# Inline policy for triggers (SNS publish) – only when trigger_topic_arn is provided
resource "aws_iam_role_policy" "codedeploy_triggers" {
  count = var.create && var.create_codedeploy_role && var.attach_triggers_policy && var.trigger_topic_arn != null ? 1 : 0
  name  = "${var.app_name}-codedeploy-triggers-policy"
  role  = aws_iam_role.codedeploy_lambda[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sns:Publish"
        Resource = var.trigger_topic_arn
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# CODEPLOY APPLICATION
# ------------------------------------------------------------------------------
resource "aws_codedeploy_app" "lambda_app" {
  count            = var.create && var.create_app && !var.use_existing_app ? 1 : 0
  compute_platform = "Lambda"
  name             = var.app_name
}

# ------------------------------------------------------------------------------
# CODEPLOY DEPLOYMENT GROUP
# ------------------------------------------------------------------------------
resource "aws_codedeploy_deployment_group" "lambda_deployment_group" {
  count                  = var.create && var.create_deployment_group && !var.use_existing_deployment_group ? 1 : 0
  app_name               = var.create_app && !var.use_existing_app ? aws_codedeploy_app.lambda_app[0].name : var.app_name
  deployment_group_name  = local.deployment_group_name
  service_role_arn       = var.create_codedeploy_role ? aws_iam_role.codedeploy_lambda[0].arn : null
  deployment_config_name = var.deployment_config_name

  deployment_style {
    deployment_option = "WITH_TRAFFIC_CONTROL"
    deployment_type   = "BLUE_GREEN"
  }

  auto_rollback_configuration {
    enabled = true
    events  = ["DEPLOYMENT_STOP_ON_ALARM"]
  }

  dynamic "alarm_configuration" {
    for_each = length(var.alarm_names) > 0 ? [1] : []
    content {
      alarms  = var.alarm_names
      enabled = true
    }
  }

  dynamic "trigger_configuration" {
    for_each = var.trigger_topic_arn != null ? [1] : []
    content {
      trigger_events     = var.trigger_events
      trigger_name       = "${var.app_name}-trigger"
      trigger_target_arn = var.trigger_topic_arn
    }
  }
}

# ------------------------------------------------------------------------------
# SCRIPT FILE (OPTIONAL)
# ------------------------------------------------------------------------------
resource "local_file" "deploy_script" {
  count    = var.create && var.save_deploy_script ? 1 : 0
  content  = local.deploy_script
  filename = "${path.module}/deploy_lambda.sh"
}

# ------------------------------------------------------------------------------
# NULL RESOURCE FOR DEPLOYMENT EXECUTION
# ------------------------------------------------------------------------------
resource "null_resource" "deploy_lambda" {
  count = var.create && var.create_deployment && var.run_deployment ? 1 : 0

  triggers = {
    function_name      = var.function_name
    alias_name         = var.alias_name
    current_version    = var.current_version
    target_version     = var.target_version
    before_hook_arn    = var.before_allow_traffic_hook_arn
    after_hook_arn     = var.after_allow_traffic_hook_arn
    deployment_config  = var.deployment_config_name
    uuid               = random_uuid.deploy_trigger[0].id
  }

  provisioner "local-exec" {
    interpreter = ["/bin/bash", "-c"]
    command     = local.deploy_script
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Variables
variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.16.0.0/16"
}

variable "vpc_name_prefix" {
  description = "Prefix for the VPC name tag"
  type        = string
  default     = "tf-project"
}

variable "web_subnet_cidrs" {
  description = "List of CIDR blocks for web subnets"
  type        = list(string)
  default     = []
}

variable "app_subnet_cidrs" {
  description = "List of CIDR blocks for application subnets"
  type        = list(string)
  default     = []
}

variable "db_subnet_cidrs" {
  description = "List of CIDR blocks for database subnets"
  type        = list(string)
  default     = []
}

variable "reserved_subnet_cidrs" {
  description = "List of CIDR blocks for reserved subnets"
  type        = list(string)
  default     = []
}

variable "max_subnet_count" {
  description = "Maximum number of subnets to create per tier (limits AZ usage)"
  type        = number
  default     = 3
}

variable "create_igw" {
  description = "Whether to create an Internet Gateway (automatically created if web subnets are provided)"
  type        = bool
  default     = false
}

variable "vpc_interface_endpoints" {
  description = "Map of interface VPC endpoints. Key is a label, value is an object with service_name and optional subnet_ids."
  type = map(object({
    service_name = string
    subnet_ids   = optional(list(string))
  }))
  default = {}
}

variable "vpc_gateway_endpoint_service" {
  description = "Service name for a gateway VPC endpoint (e.g., 's3' or 'dynamodb'). Set to null to skip."
  type        = string
  default     = null
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

# Random resources
resource "random_integer" "vpc_suffix" {
  min = 1
  max = 100
}

resource "random_shuffle" "az" {
  input        = data.aws_availability_zones.available.names
  result_count = length(data.aws_availability_zones.available.names)
}

# Locals
locals {
  max_az = min(var.max_subnet_count, length(data.aws_availability_zones.available.names))
  shuffled_azs = random_shuffle.az.result

  web_count = min(length(var.web_subnet_cidrs), local.max_az)
  app_start = local.web_count
  app_count = (local.app_start < local.max_az) ? min(length(var.app_subnet_cidrs), local.max_az - local.app_start) : 0
  db_start = local.app_start + local.app_count
  db_count = (local.db_start < local.max_az) ? min(length(var.db_subnet_cidrs), local.max_az - local.db_start) : 0
  reserved_start = local.db_start + local.db_count
  reserved_count = (local.reserved_start < local.max_az) ? min(length(var.reserved_subnet_cidrs), local.max_az - local.reserved_start) : 0

  private_subnet_count = local.app_count + local.db_count + local.reserved_count
  private_subnet_ids = concat(
    aws_subnet.app[*].id,
    aws_subnet.db[*].id,
    aws_subnet.reserved[*].id
  )
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.vpc_name_prefix}-${random_integer.vpc_suffix.result}"
  }
}

# Web Subnets
resource "aws_subnet" "web" {
  count = local.web_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.web_subnet_cidrs, count.index)
  availability_zone       = element(local.shuffled_azs, count.index)
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.vpc_name_prefix}-web-${count.index + 1}"
  }
}

# Application Subnets
resource "aws_subnet" "app" {
  count = local.app_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.app_subnet_cidrs, count.index)
  availability_zone = element(local.shuffled_azs, local.app_start + count.index)

  tags = {
    Name = "${var.vpc_name_prefix}-app-${count.index + 1}"
  }
}

# Database Subnets
resource "aws_subnet" "db" {
  count = local.db_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.db_subnet_cidrs, count.index)
  availability_zone = element(local.shuffled_azs, local.db_start + count.index)

  tags = {
    Name = "${var.vpc_name_prefix}-db-${count.index + 1}"
  }
}

# Reserved Subnets
resource "aws_subnet" "reserved" {
  count = local.reserved_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.reserved_subnet_cidrs, count.index)
  availability_zone = element(local.shuffled_azs, local.reserved_start + count.index)

  tags = {
    Name = "${var.vpc_name_prefix}-reserved-${count.index + 1}"
  }
}

# Internet Gateway (conditionally created if web subnets exist or explicitly requested)
resource "aws_internet_gateway" "igw" {
  count = var.create_igw || length(var.web_subnet_cidrs) > 0 ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name_prefix}-igw"
  }
}

# Public Route Table (only if web subnets exist)
resource "aws_route_table" "public" {
  count = length(aws_subnet.web) > 0 ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name_prefix}-public"
  }
}

# Default route in public route table (only if IGW exists)
resource "aws_route" "public_default" {
  count = length(aws_internet_gateway.igw) > 0 ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw[0].id
}

# Public route table associations
resource "aws_route_table_association" "public" {
  count = length(aws_subnet.web)

  subnet_id      = aws_subnet.web[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# Private Route Table (only if at least one private subnet exists)
resource "aws_route_table" "private" {
  count = local.private_subnet_count > 0 ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name_prefix}-private"
  }
}

# Private route table associations
resource "aws_route_table_association" "private" {
  count = local.private_subnet_count

  subnet_id      = element(local.private_subnet_ids, count.index)
  route_table_id = aws_route_table.private[0].id
}

# Interface VPC Endpoints
resource "aws_vpc_endpoint" "interface" {
  for_each = var.vpc_interface_endpoints

  vpc_id              = aws_vpc.main.id
  service_name        = each.value.service_name
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = try(each.value.subnet_ids, local.private_subnet_ids)

  tags = {
    Name = "${var.vpc_name_prefix}-vpce-${each.key}"
  }
}

# Gateway VPC Endpoint (optional)
resource "aws_vpc_endpoint" "gateway" {
  count = var.vpc_gateway_endpoint_service != null ? 1 : 0

  vpc_id            = aws_vpc.main.id
  service_name      = var.vpc_gateway_endpoint_service
  vpc_endpoint_type = "Gateway"

  tags = {
    Name = "${var.vpc_name_prefix}-vpce-gateway"
  }
}

# Route table association for gateway endpoint (only if private route table exists)
resource "aws_vpc_endpoint_route_table_association" "gateway" {
  count = var.vpc_gateway_endpoint_service != null && local.private_subnet_count > 0 ? 1 : 0

  vpc_endpoint_id = aws_vpc_endpoint.gateway[0].id
  route_table_id  = aws_route_table.private[0].id
}

# KMS Key for CloudWatch Logs encryption
resource "aws_kms_key" "vpc_flow_logs" {
  description             = "KMS key for VPC Flow Logs CloudWatch Logs encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogs"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "${var.vpc_name_prefix}-vpc-flow-logs-key"
  }
}

resource "aws_kms_alias" "vpc_flow_logs" {
  name          = "alias/${var.vpc_name_prefix}-cloudwatch-logs"
  target_key_id = aws_kms_key.vpc_flow_logs.key_id
}

# VPC Flow Logs
resource "aws_cloudwatch_log_group" "vpc_flow_logs" {
  name              = "/aws/vpc/flow-logs"
  retention_in_days = 14
  kms_key_id        = aws_kms_alias.vpc_flow_logs.arn

  tags = {
    Name = "${var.vpc_name_prefix}-vpc-flow-logs"
  }
}

resource "aws_iam_role" "vpc_flow_logs" {
  name = "${var.vpc_name_prefix}-vpc-flow-logs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "${var.vpc_name_prefix}-vpc-flow-logs-role"
  }
}

resource "aws_iam_role_policy" "vpc_flow_logs" {
  name = "${var.vpc_name_prefix}-vpc-flow-logs-policy"
  role = aws_iam_role.vpc_flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "${aws_cloudwatch_log_group.vpc_flow_logs.arn}:*"
      }
    ]
  })
}

resource "aws_flow_log" "vpc" {
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.vpc_flow_logs.arn
  iam_role_arn         = aws_iam_role.vpc_flow_logs.arn
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"

  tags = {
    Name = "${var.vpc_name_prefix}-vpc-flow-log"
  }
}

# Additional data sources required for KMS key policy
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "admin_cidrs" {
  type        = list(string)
  default     = ["203.0.113.0/24"]
  description = "List of CIDR blocks allowed SSH access to the Home SSH security group"
}

variable "dhcp_domain_name" {
  type        = string
  default     = "internal"
  description = "Internal domain name for DHCP options and private Route 53 zone"
}

