resource "aws_security_group" "home_ssh" {
  name        = "home_ssh"
  description = "Allow SSH from admin CIDRs and self, outbound to VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from admin CIDRs"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.admin_cidrs
  }

  ingress {
    description = "SSH from self"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "All traffic to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "home_ssh"
  }
}

resource "aws_security_group" "packer_ssh" {
  name        = "packer_ssh"
  description = "Allow SSH from VPC CIDR and self, outbound to VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "SSH from self"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "All traffic to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "packer_ssh"
  }
}

# --- KMS Key for CloudWatch Logs encryption (AWS-0017) ---
resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for CloudWatch Log Groups"
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAdminPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogsService"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "cloudwatch" {
  name_prefix   = "alias/cloudwatch-"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

# --- VPC Flow Logs (AWS-0178) ---
resource "aws_cloudwatch_log_group" "vpc_flow_logs" {
  name_prefix = "/aws/vpc/flow-logs-"
  kms_key_id  = aws_kms_alias.cloudwatch.arn

  tags = {
    Name = "vpc-flow-logs"
  }
}

resource "aws_iam_role" "vpc_flow_logs" {
  name_prefix = "vpc-flow-logs-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "vpc_flow_logs" {
  name_prefix = "vpc-flow-logs-policy-"
  role        = aws_iam_role.vpc_flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups"
        ]
        Resource = [
          aws_cloudwatch_log_group.vpc_flow_logs.arn,
          "${aws_cloudwatch_log_group.vpc_flow_logs.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  iam_role_arn    = aws_iam_role.vpc_flow_logs.arn
  log_destination = aws_cloudwatch_log_group.vpc_flow_logs.arn
  traffic_type    = "ALL"
  vpc_id          = aws_vpc.main.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  name_prefix = var.env != "" ? "${var.env}-" : ""
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

variable "env" {
  type    = string
  default = ""
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "private_app_subnet_cidrs" {
  type    = list(string)
  default = ["10.0.10.0/24", "10.0.20.0/24", "10.0.30.0/24"]
}

variable "private_db_subnet_cidrs" {
  type    = list(string)
  default = ["10.0.100.0/24", "10.0.110.0/24", "10.0.120.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}main-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}main-igw"
  }
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private_app" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_app_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.name_prefix}private-app-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private_db" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_db_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.name_prefix}private-db-subnet-${count.index + 1}"
  }
}

resource "aws_eip" "nat" {
  count  = 3
  domain = "vpc"

  tags = {
    Name = "${local.name_prefix}nat-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "main" {
  count         = 3
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${local.name_prefix}nat-gw-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}public-rt"
  }
}

resource "aws_route_table" "private_app" {
  count  = 3
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = {
    Name = "${local.name_prefix}private-app-rt-${data.aws_availability_zones.available.names[count.index]}"
  }
}

resource "aws_route_table" "database" {
  vpc_id = aws_vpc.main.id

  # No explicit routes: the default local route is created automatically by AWS.
  tags = {
    Name = "${local.name_prefix}private-db-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private_app" {
  count          = 3
  subnet_id      = aws_subnet.private_app[count.index].id
  route_table_id = aws_route_table.private_app[count.index].id
}

resource "aws_route_table_association" "private_db" {
  count          = 3
  subnet_id      = aws_subnet.private_db[count.index].id
  route_table_id = aws_route_table.database.id
}

# KMS key for CloudWatch Logs encryption
resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for CloudWatch Logs encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

data "aws_caller_identity" "current" {}

resource "aws_kms_alias" "cloudwatch" {
  name_prefix   = "alias/${local.name_prefix}cloudwatch-logs-"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

# VPC Flow Logs resources
resource "aws_cloudwatch_log_group" "vpc_flow_log" {
  name_prefix       = "/aws/vpc-flow-logs/${local.name_prefix}main-"
  retention_in_days = 14
  kms_key_id        = aws_kms_alias.cloudwatch.arn
}

resource "aws_iam_role" "vpc_flow_log" {
  name = "${local.name_prefix}vpc-flow-log-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "vpc-flow-logs.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy" "vpc_flow_log" {
  name = "${local.name_prefix}vpc-flow-log-policy"
  role = aws_iam_role.vpc_flow_log.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Effect   = "Allow"
        Resource = aws_kms_key.cloudwatch.arn
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  log_destination      = aws_cloudwatch_log_group.vpc_flow_log.arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.vpc_flow_log.arn
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.main.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "bucket_name" {
  description = "Base name for the S3 bucket"
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "use_account_alias_prefix" {
  description = "Whether to prepend the AWS IAM account alias to the bucket name"
  type        = bool
  default     = false
}

variable "use_random_suffix" {
  description = "Whether to append a random suffix to the bucket name (default true to ensure uniqueness)"
  type        = bool
  default     = true
}

variable "force_destroy" {
  description = "Allow bucket to be destroyed even if it contains objects"
  type        = bool
  default     = false
}

variable "enable_s3_public_access_block" {
  description = "Enable S3 public access block settings"
  type        = bool
  default     = true
}

variable "versioning_status" {
  description = "Versioning status: Enabled or Suspended"
  type        = string
  default     = "Enabled"
}

variable "kms_master_key_id" {
  description = "KMS key ARN for encryption (if not provided, AES256 is used)"
  type        = string
  default     = null
}

variable "bucket_key_enabled" {
  description = "Enable bucket key for SSE-KMS"
  type        = bool
  default     = false
}

variable "enable_analytics" {
  description = "Enable storage class analytics"
  type        = bool
  default     = true
}

variable "enable_bucket_inventory" {
  description = "Enable bucket inventory reports"
  type        = bool
  default     = false
}

variable "logging_bucket" {
  description = "Target S3 bucket for access logs. If not provided, a dedicated log bucket will be created automatically with a random suffix."
  type        = string
  default     = null
}

variable "transfer_acceleration" {
  description = "Enable or suspend transfer acceleration (true/false/null)"
  type        = bool
  default     = null
}

variable "s3_bucket_acl" {
  description = "Canned ACL to apply to the bucket"
  type        = string
  default     = null
}

variable "cors_rules" {
  description = "List of CORS rules"
  type = list(object({
    allowed_headers = list(string)
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = list(string)
    max_age_seconds = number
  }))
  default = []
}

variable "custom_bucket_policy" {
  description = "Custom JSON bucket policy to merge with mandatory statements"
  type        = string
  default     = null
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------
locals {
  account_alias = var.use_account_alias_prefix ? "${data.aws_iam_account_alias.current[0].account_alias}-" : ""
  random_suffix = var.use_random_suffix ? random_id.suffix[0].hex : ""
  bucket_name   = "${local.account_alias}${var.bucket_name}${local.random_suffix}"
}

# ------------------------------------------------------------------------------
# Data sources
# ------------------------------------------------------------------------------
data "aws_iam_account_alias" "current" {
  count = var.use_account_alias_prefix ? 1 : 0
}

# ------------------------------------------------------------------------------
# Random suffix for main bucket (conditional)
# ------------------------------------------------------------------------------
resource "random_id" "suffix" {
  count      = var.use_random_suffix ? 1 : 0
  byte_length = 4
}

# ------------------------------------------------------------------------------
# Random suffix for logging bucket (always generated when logging bucket is created)
# ------------------------------------------------------------------------------
resource "random_id" "logging_suffix" {
  count       = var.logging_bucket == null ? 1 : 0
  byte_length = 4
}

# ------------------------------------------------------------------------------
# Main S3 Bucket
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "main" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy

  versioning {
    enabled = var.versioning_status == "Enabled"
  }

  logging {
    target_bucket = var.logging_bucket != null ? var.logging_bucket : aws_s3_bucket.logging[0].id
    target_prefix = "s3/${local.bucket_name}/"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Public Access Block for Main Bucket (conditional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_public_access_block" "main" {
  count = var.enable_s3_public_access_block ? 1 : 0

  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# Ownership Controls for Main Bucket
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# ------------------------------------------------------------------------------
# Server-Side Encryption for Main Bucket
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_master_key_id != null ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_master_key_id
    }
    bucket_key_enabled = var.kms_master_key_id != null ? var.bucket_key_enabled : null
  }
}

# ------------------------------------------------------------------------------
# Lifecycle Configuration for Main Bucket
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  transition_default_minimum_object_size = "all_storage_classes_128K"

  # Rule 1: Abort incomplete multipart uploads after 14 days
  rule {
    id = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    abort_incomplete_multipart_upload {
      days_after_initiation = 14
    }

    filter {
      prefix = ""
    }
  }

  # Rule 2: Noncurrent version transitions and expiration
  rule {
    id = "noncurrent-version-management"
    status = "Enabled"

    filter {
      prefix = ""
    }

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "STANDARD_IA"
    }

    noncurrent_version_expiration {
      noncurrent_days = 365
    }
  }

  # Rule 3: Expire analytics export data after 30 days (if analytics enabled)
  dynamic "rule" {
    for_each = var.enable_analytics ? [1] : []

    content {
      id     = "analytics-export-expiration"
      status = "Enabled"

      expiration {
        days = 30
      }

      filter {
        prefix = "_AWSBucketAnalytics/"
      }
    }
  }

  # Rule 4: Expire inventory reports after 14 days (if inventory enabled)
  dynamic "rule" {
    for_each = var.enable_bucket_inventory ? [1] : []

    content {
      id     = "inventory-report-expiration"
      status = "Enabled"

      expiration {
        days = 14
      }

      filter {
        prefix = "_AWSBucketInventory/"
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Analytics Configuration for Main Bucket (conditional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_analytics_configuration" "main" {
  count = var.enable_analytics ? 1 : 0

  bucket = aws_s3_bucket.main.id
  name   = "DefaultAnalytics"

  filter {
    prefix = "_AWSBucketAnalytics/"
  }

  storage_class_analysis {
    data_export {
      output_schema_version = "V_1"

      destination {
        s3_bucket_destination {
          bucket_arn = aws_s3_bucket.main.arn
          prefix     = "_AWSBucketAnalytics/"
          format     = "CSV"
        }
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Inventory Configuration for Main Bucket (conditional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_inventory" "main" {
  count = var.enable_bucket_inventory ? 1 : 0

  bucket   = aws_s3_bucket.main.id
  name     = "DefaultInventory"
  enabled  = true

  included_object_versions = "Current"

  optional_fields = [
    "Size",
    "LastModifiedDate",
    "StorageClass",
    "ETag",
    "IsMultipartUploaded",
    "ReplicationStatus",
    "EncryptionStatus",
    "ObjectLockRetainUntilDate",
    "ObjectLockMode",
    "ObjectLockLegalHoldStatus",
    "IntelligentTieringAccessTier",
    "BucketKeyStatus",
  ]

  schedule {
    frequency = "Weekly"
  }

  destination {
    bucket {
      bucket_arn = aws_s3_bucket.main.arn
      prefix     = "_AWSBucketInventory/"
      format     = "ORC"
    }
  }
}

# ------------------------------------------------------------------------------
# Transfer Acceleration for Main Bucket (conditional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_accelerate_configuration" "main" {
  count = var.transfer_acceleration != null ? 1 : 0

  bucket = aws_s3_bucket.main.id
  status = var.transfer_acceleration ? "Enabled" : "Suspended"
}

# ------------------------------------------------------------------------------
# Bucket ACL for Main Bucket (conditional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_acl" "main" {
  count = var.s3_bucket_acl != null ? 1 : 0

  bucket = aws_s3_bucket.main.id
  acl    = var.s3_bucket_acl

  depends_on = [aws_s3_bucket_ownership_controls.main]
}

# ------------------------------------------------------------------------------
# CORS Configuration for Main Bucket (conditional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_cors_configuration" "main" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# ------------------------------------------------------------------------------
# Bucket Policy for Main Bucket (merged with mandatory statements)
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "combined" {
  source_policy_documents = var.custom_bucket_policy != null ? [var.custom_bucket_policy] : []

  # Deny non-TLS requests
  statement {
    sid    = "DenyNonSecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions   = ["s3:*"]
    resources = ["${aws_s3_bucket.main.arn}/*"]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  # Allow S3 service to write inventory and analytics with bucket-owner-full-control
  statement {
    sid    = "AllowS3ServiceWriteInventoryAndAnalytics"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "s3:PutObject"
    ]

    resources = [
      "${aws_s3_bucket.main.arn}/_AWSBucketAnalytics/*",
      "${aws_s3_bucket.main.arn}/_AWSBucketInventory/*",
    ]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "main" {
  bucket = aws_s3_bucket.main.id
  policy = data.aws_iam_policy_document.combined.json
}

# ------------------------------------------------------------------------------
# Dedicated Log Bucket (created only when no external target is provided)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "logging" {
  count = var.logging_bucket == null ? 1 : 0

  bucket        = "${local.bucket_name}-logs-${random_id.logging_suffix[0].hex}"
  force_destroy = true

  versioning {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count = var.logging_bucket == null ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "logging" {
  count = var.logging_bucket == null ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "logging" {
  count = var.logging_bucket == null ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id
  acl    = "log-delivery-write"

  depends_on = [aws_s3_bucket_ownership_controls.logging]
}

# Terraform configuration
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Data sources
data "aws_caller_identity" "current" {}

# Random suffix for unique bucket name
resource "random_id" "bucket_suffix" {
  byte_length = 4
  keepers = {
    bucket_name = var.bucket_name
  }
}

# Locals for tag merging and final bucket name
locals {
  merged_tags = merge(
    {
      Environment     = var.environment
      ServiceProvider = "Rackspace"
    },
    var.tags
  )
  bucket_name_final = "${var.bucket_name}-${random_id.bucket_suffix.hex}"
}

# Variables
variable "bucket_name" {
  description = "Name of the S3 bucket"
  type        = string
  default     = "benchmark-access-logs-bkt"
}

variable "environment" {
  description = "Environment tag value"
  type        = string
  default     = "Development"
}

variable "tags" {
  description = "Additional tags for the bucket"
  type        = map(string)
  default     = {}
}

variable "sse_algorithm" {
  description = "Server-side encryption algorithm: AES256, aws:kms, or none"
  type        = string
  default     = "AES256"
  validation {
    condition     = contains(["AES256", "aws:kms", "none"], var.sse_algorithm)
    error_message = "sse_algorithm must be one of AES256, aws:kms, or none."
  }
}

variable "kms_master_key_id" {
  description = "KMS key ID for aws:kms encryption"
  type        = string
  default     = null
}

variable "bucket_key_enabled" {
  description = "Enable S3 bucket key for aws:kms encryption"
  type        = bool
  default     = false
}

variable "public_access_block_enabled" {
  description = "Enable public access block settings"
  type        = bool
  default     = true
}

variable "block_public_acls" {
  description = "Block public ACLs"
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public bucket policies"
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs"
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict public buckets"
  type        = bool
  default     = true
}

variable "control_object_ownership" {
  description = "Enable bucket ownership controls"
  type        = bool
  default     = true
  validation {
    condition     = var.control_object_ownership || (var.canned_acl == null && length(var.grants) == 0)
    error_message = "ACLs require control_object_ownership to be true. Set control_object_ownership = true or remove canned_acl/grants."
  }
}

variable "object_ownership" {
  description = "Object ownership value: ObjectWriter or BucketOwnerPreferred"
  type        = string
  default     = "ObjectWriter"
  validation {
    condition     = contains(["ObjectWriter", "BucketOwnerPreferred"], var.object_ownership)
    error_message = "object_ownership must be ObjectWriter or BucketOwnerPreferred."
  }
}

variable "canned_acl" {
  description = "Canned ACL to apply to the bucket"
  type        = string
  default     = "log-delivery-write"
}

variable "grants" {
  description = "List of grant objects (type, permission, URI, id)"
  type = list(object({
    type       = string
    permission = string
    uri        = optional(string)
    id         = optional(string)
  }))
  default = []
}

variable "versioning_status" {
  description = "Versioning status: Enabled or Disabled"
  type        = string
  default     = "Enabled"
  validation {
    condition     = contains(["Enabled", "Disabled"], var.versioning_status)
    error_message = "versioning_status must be Enabled or Disabled."
  }
}

variable "mfa_delete" {
  description = "Enable MFA delete"
  type        = bool
  default     = false
}

variable "mfa_token" {
  description = "MFA token required for MFA delete operations"
  type        = string
  default     = null
  sensitive   = true
}

variable "bucket_logging" {
  description = "Enable bucket logging"
  type        = bool
  default     = false
}

variable "log_bucket" {
  description = "Target bucket for logs"
  type        = string
  default     = null
}

variable "log_prefix" {
  description = "Prefix for log objects"
  type        = string
  default     = null
}

variable "object_lock_enabled" {
  description = "Enable S3 Object Lock"
  type        = bool
  default     = false
}

variable "default_retention_mode" {
  description = "Default retention mode for Object Lock"
  type        = string
  default     = "GOVERNANCE"
  validation {
    condition     = contains(["GOVERNANCE", "COMPLIANCE"], var.default_retention_mode)
    error_message = "default_retention_mode must be GOVERNANCE or COMPLIANCE."
  }
}

variable "default_retention_days" {
  description = "Number of days for default retention"
  type        = number
  default     = null
}

variable "default_retention_years" {
  description = "Number of years for default retention"
  type        = number
  default     = null
}

variable "website" {
  description = "Website configuration map (index_document, error_document, redirect_all_requests_to, routing_rules)"
  type        = any
  default     = {}
}

variable "intelligent_tiering" {
  description = "List of intelligent tiering configurations"
  type = list(object({
    name   = string
    status = string
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    tiering = list(object({
      access_tier = string
      days        = number
    }))
  }))
  default = []
}

variable "metrics" {
  description = "List of metric configurations (name and optional filter_prefix)"
  type = list(object({
    name          = string
    filter_prefix = optional(string)
  }))
  default = []
}

variable "cors_rules" {
  description = "List of CORS rules"
  type = list(object({
    allowed_headers = list(string)
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules"
  type = list(object({
    id     = string
    status = string
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    expiration = optional(object({
      days                         = optional(number)
      date                         = optional(string)
      expired_object_delete_marker = optional(bool)
    }))
    transition = optional(list(object({
      days          = number
      storage_class = string
    })))
    noncurrent_version_expiration = optional(object({
      noncurrent_days = number
    }))
    noncurrent_version_transition = optional(list(object({
      noncurrent_days = number
      storage_class   = string
    })))
    abort_incomplete_multipart_upload = optional(object({
      days_after_initiation = number
    }))
  }))
  default = []
}

# Main S3 bucket
resource "aws_s3_bucket" "this" {
  bucket = local.bucket_name_final
  tags   = local.merged_tags

  object_lock_enabled = var.object_lock_enabled ? "Enabled" : null

  lifecycle {
    prevent_destroy = true
  }
}

# Server-side encryption configuration
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count  = var.sse_algorithm != "none" ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.sse_algorithm
      kms_master_key_id = var.sse_algorithm == "aws:kms" ? var.kms_master_key_id : null
    }
    bucket_key_enabled = var.sse_algorithm == "aws:kms" ? var.bucket_key_enabled : null
  }
}

# Public access block
resource "aws_s3_bucket_public_access_block" "this" {
  count = var.public_access_block_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

# Ownership controls
resource "aws_s3_bucket_ownership_controls" "this" {
  count = var.control_object_ownership ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

# ACL (canned or grants)
resource "aws_s3_bucket_acl" "this" {
  count = (var.canned_acl != null || length(var.grants) > 0) ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.canned_acl

  depends_on = [
    aws_s3_bucket_ownership_controls.this,
    aws_s3_bucket_public_access_block.this,
  ]

  dynamic "access_control_policy" {
    for_each = length(var.grants) > 0 ? [1] : []
    content {
      owner {
        id = data.aws_caller_identity.current.canonical_user_id
      }
      dynamic "grant" {
        for_each = var.grants
        content {
          grantee {
            type   = grant.value.type
            uri    = grant.value.uri
            id     = grant.value.id
          }
          permission = grant.value.permission
        }
      }
    }
  }
}

# Versioning
resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status    = var.versioning_status
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
  }

  mfa = var.mfa_delete ? var.mfa_token : null
}

# Bucket logging
resource "aws_s3_bucket_logging" "this" {
  count = var.bucket_logging ? 1 : 0

  bucket = aws_s3_bucket.this.id

  target_bucket = var.log_bucket
  target_prefix = var.log_prefix
}

# Object Lock configuration
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.default_retention_mode
      days  = var.default_retention_days
      years = var.default_retention_years
    }
  }
}

# Website configuration
resource "aws_s3_bucket_website_configuration" "this" {
  count = length(var.website) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  index_document {
    suffix = try(var.website.index_document, null)
  }

  error_document {
    key = try(var.website.error_document, null)
  }

  dynamic "redirect_all_requests_to" {
    for_each = try(var.website.redirect_all_requests_to, null) != null ? [1] : []
    content {
      host_name = var.website.redirect_all_requests_to.host_name
      protocol  = try(var.website.redirect_all_requests_to.protocol, null)
    }
  }

  dynamic "routing_rule" {
    for_each = try(var.website.routing_rules, [])
    content {
      condition {
        http_error_code_returned_equals = try(routing_rule.value.condition.http_error_code_returned_equals, null)
        key_prefix_equals               = try(routing_rule.value.condition.key_prefix_equals, null)
      }
      redirect {
        host_name               = try(routing_rule.value.redirect.host_name, null)
        http_redirect_code      = try(routing_rule.value.redirect.http_redirect_code, null)
        protocol                = try(routing_rule.value.redirect.protocol, null)
        replace_key_prefix_with = try(routing_rule.value.redirect.replace_key_prefix_with, null)
        replace_key_with        = try(routing_rule.value.redirect.replace_key_with, null)
      }
    }
  }
}

# Intelligent Tiering
resource "aws_s3_bucket_intelligent_tiering_configuration" "this" {
  for_each = { for idx, config in var.intelligent_tiering : config.name => config }

  bucket = aws_s3_bucket.this.id
  name   = each.value.name
  status = each.value.status

  dynamic "filter" {
    for_each = each.value.filter != null ? [each.value.filter] : []
    content {
      prefix = filter.value.prefix
      tags   = filter.value.tags
    }
  }

  dynamic "tiering" {
    for_each = each.value.tiering
    content {
      access_tier = tiering.value.access_tier
      days        = tiering.value.days
    }
  }
}

# Metrics
resource "aws_s3_bucket_metric" "this" {
  for_each = { for idx, m in var.metrics : m.name => m }

  bucket = aws_s3_bucket.this.id
  name   = each.value.name

  dynamic "filter" {
    for_each = each.value.filter_prefix != null ? [each.value.filter_prefix] : []
    content {
      prefix = filter.value
    }
  }
}

# CORS configuration
resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

# Lifecycle configuration
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = { for idx, rule in var.lifecycle_rules : rule.id => rule }
    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "filter" {
        for_each = rule.value.filter != null ? [1] : []
        content {
          # Use 'and' block when tags are present, otherwise just set prefix directly
          dynamic "and" {
            for_each = (rule.value.filter.prefix != null || length(try(rule.value.filter.tags, {})) > 0) ? [1] : []
            content {
              prefix = rule.value.filter.prefix
              tags   = rule.value.filter.tags
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          days                         = expiration.value.days
          date                         = expiration.value.date
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "transition" {
        for_each = rule.value.transition != null ? rule.value.transition : []
        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value.noncurrent_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transition != null ? rule.value.noncurrent_version_transition : []
        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload != null ? [rule.value.abort_incomplete_multipart_upload] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "bucket" {
  description = "Name of the S3 bucket (must be globally unique). Max 63 characters."
  type        = string
  default     = ""
  validation {
    condition     = length(var.bucket) <= 63
    error_message = "Bucket name must be 63 characters or fewer."
  }
}

variable "bucket_prefix" {
  description = "Prefix for the S3 bucket name. Max 37 characters."
  type        = string
  default     = ""
  validation {
    condition     = length(var.bucket_prefix) <= 37
    error_message = "Bucket prefix must be 37 characters or fewer."
  }
}

variable "force_destroy" {
  description = "Allow bucket to be destroyed even if not empty."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership setting: BucketOwnerEnforced, BucketOwnerPreferred, or ObjectWriter."
  type        = string
  default     = "BucketOwnerEnforced"
  validation {
    condition     = contains(["BucketOwnerEnforced", "BucketOwnerPreferred", "ObjectWriter"], var.object_ownership)
    error_message = "Object ownership must be one of: BucketOwnerEnforced, BucketOwnerPreferred, ObjectWriter."
  }
}

variable "block_public_acls" {
  description = "Block public ACLs."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public bucket policies."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict public buckets."
  type        = bool
  default     = true
}

variable "kms_key_arn" {
  description = "ARN of an existing KMS key for SSE-KMS. If empty, a new key is created."
  type        = string
  default     = ""
}

variable "enable_versioning" {
  description = "Enable bucket versioning."
  type        = bool
  default     = true
}

variable "enable_logging" {
  description = "Enable server access logging for the main bucket."
  type        = bool
  default     = true
}

variable "custom_bucket_policy" {
  description = "Additional JSON bucket policy to merge with the enforced policies."
  type        = string
  default     = ""
}

variable "enable_eventbridge" {
  description = "Enable Amazon EventBridge notifications for the bucket."
  type        = bool
  default     = false
}

variable "object_lock_enabled" {
  description = "Enable object lock on the bucket."
  type        = bool
  default     = false
}

variable "object_lock_mode" {
  description = "Default retention mode: GOVERNANCE or COMPLIANCE."
  type        = string
  default     = "GOVERNANCE"
  validation {
    condition     = contains(["GOVERNANCE", "COMPLIANCE"], var.object_lock_mode)
    error_message = "Object lock mode must be GOVERNANCE or COMPLIANCE."
  }
}

variable "object_lock_days" {
  description = "Number of days for default retention (mutually exclusive with years)."
  type        = number
  default     = null
}

variable "object_lock_years" {
  description = "Number of years for default retention (mutually exclusive with days)."
  type        = number
  default     = null
}

variable "replication_rules" {
  description = "List of replication rule configurations."
  type = list(object({
    priority                   = number
    filter_prefix              = optional(string)
    filter_tags                = optional(map(string))
    destination_bucket_name    = string
    destination_region         = string
    source_selection_criteria  = optional(object({
      sse_kms_encrypted_objects = optional(bool, false)
    }))
  }))
  default = []
}

variable "replication_role_name" {
  description = "Name of the IAM role for replication."
  type        = string
  default     = "s3-replication-role"
}

variable "inventory_configurations" {
  description = "List of inventory configurations."
  type = list(object({
    schedule              = string                # "Daily" or "Weekly"
    destination_bucket    = string
    destination_prefix    = optional(string)
    included_object_versions = string             # "All" or "Current"
    optional_fields       = optional(list(string))
    format                = string                # "Parquet" or "ORC"
    encryption            = string                # "SSE_S3" or "SSE_KMS"
    kms_key_arn           = optional(string)      # required if encryption = "SSE_KMS"
  }))
  default = []
}

variable "cors_rules" {
  description = "List of CORS rules."
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rule configurations."
  type = list(object({
    id                                     = string
    status                                 = optional(string, "Enabled")
    prefix                                 = optional(string)
    tags                                   = optional(map(string))
    expiration                             = optional(object({
      days                         = optional(number)
      date                         = optional(string)
      expired_object_delete_marker = optional(bool)
    }))
    transition                             = optional(list(object({
      days          = number
      storage_class = string
    })))
    noncurrent_version_expiration          = optional(object({
      newer_noncurrent_versions = optional(number)
      days                      = number
    }))
    noncurrent_version_transition          = optional(list(object({
      newer_noncurrent_versions = optional(number)
      days                      = number
      storage_class             = string
    })))
    abort_incomplete_multipart_upload      = optional(object({
      days_after_initiation = number
    }))
  }))
  default = []
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------
locals {
  bucket_name = var.bucket != "" ? var.bucket : null
  bucket_prefix = var.bucket == "" && var.bucket_prefix != "" ? var.bucket_prefix : null

  # SSE algorithm: always use aws:kms (with CMK)
  use_kms       = true
  sse_algorithm = "aws:kms"
  kms_key_id    = var.kms_key_arn != "" ? var.kms_key_arn : try(aws_kms_key.main[0].arn, null)

  # Versioning status
  versioning_status = var.enable_versioning ? "Enabled" : "Suspended"

  # Object lock retention days/years
  object_lock_retention_days  = var.object_lock_days != null ? var.object_lock_days : null
  object_lock_retention_years = var.object_lock_years != null ? var.object_lock_years : null

  # SSL deny policy for main bucket
  ssl_deny_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureConnections"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          "arn:aws:s3:::${aws_s3_bucket.main.id}",
          "arn:aws:s3:::${aws_s3_bucket.main.id}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  # Combine policies: custom + ssl deny
  combined_policy = jsonencode(merge(
    jsondecode(local.ssl_deny_policy),
    var.custom_bucket_policy != "" ? jsondecode(var.custom_bucket_policy) : {}
  ))
}

# ------------------------------------------------------------------------------
# KMS Key (created only if no ARN provided)
# ------------------------------------------------------------------------------
resource "aws_kms_key" "main" {
  count = var.kms_key_arn == "" ? 1 : 0
  description             = "S3 bucket encryption key"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_alias" "main" {
  count = var.kms_key_arn == "" ? 1 : 0
  name          = "alias/s3-bucket-key"
  target_key_id = aws_kms_key.main[0].key_id
}

# ------------------------------------------------------------------------------
# Main S3 Bucket (inline SSE and logging)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "main" {
  bucket        = local.bucket_name
  bucket_prefix = local.bucket_prefix
  force_destroy = var.force_destroy

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = local.sse_algorithm
        kms_master_key_id = local.kms_key_id
      }
      bucket_key_enabled = local.use_kms
    }
  }

  logging {
    target_bucket = aws_s3_bucket.log_destination[0].id
    target_prefix = "logs/"
  }

  lifecycle {
    precondition {
      condition     = !var.object_lock_enabled
      error_message = "Cannot enable server access logging when object lock is enabled."
    }
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# ACL (conditional: only when object_ownership = "ObjectWriter")
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_acl" "main" {
  count  = var.object_ownership == "ObjectWriter" ? 1 : 0
  bucket = aws_s3_bucket.main.id
  acl    = "private"
}

# ------------------------------------------------------------------------------
# Public Access Block
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

# ------------------------------------------------------------------------------
# Versioning
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id
  versioning_configuration {
    status = local.versioning_status
  }
}

# ------------------------------------------------------------------------------
# Bucket Policy (SSL deny + custom)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_policy" "main" {
  bucket = aws_s3_bucket.main.id
  policy = local.combined_policy
}

# ------------------------------------------------------------------------------
# EventBridge Notification
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_notification" "main" {
  count  = var.enable_eventbridge ? 1 : 0
  bucket = aws_s3_bucket.main.id
  eventbridge = true
}

# ------------------------------------------------------------------------------
# Log destination bucket (inline ACL, ownership controls)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "log_destination" {
  count = var.enable_logging && !var.object_lock_enabled ? 1 : 0

  bucket_prefix = "logs-"
  force_destroy = false

  acl = "log-delivery-write"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "log_destination" {
  count = var.enable_logging && !var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.log_destination[0].id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "log_destination" {
  count = var.enable_logging && !var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.log_destination[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log_destination" {
  count = var.enable_logging && !var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.log_destination[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "log_destination" {
  count = var.enable_logging && !var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.log_destination[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------------------
# Object Lock (conditional, with precondition)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_object_lock_configuration" "main" {
  count  = var.object_lock_enabled ? 1 : 0
  bucket = aws_s3_bucket.main.id

  rule {
    default_retention {
      mode = var.object_lock_mode
      days  = local.object_lock_retention_days
      years = local.object_lock_retention_years
    }
  }

  lifecycle {
    precondition {
      condition     = !var.enable_logging
      error_message = "Object lock cannot be enabled when server access logging is configured."
    }
  }
}

# ------------------------------------------------------------------------------
# Replication Configuration (conditional)
# ------------------------------------------------------------------------------
# Provider alias for replication destination region (guarded against empty list)
provider "aws" {
  alias  = "replication"
  region = length(var.replication_rules) > 0 ? var.replication_rules[0].destination_region : "us-east-1"
}

# IAM role for replication
resource "aws_iam_role" "replication" {
  count = length(var.replication_rules) > 0 ? 1 : 0
  name  = var.replication_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "replication" {
  count = length(var.replication_rules) > 0 ? 1 : 0
  name  = "${var.replication_role_name}-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersion",
          "s3:GetObjectVersionTagging",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.main.arn,
          "${aws_s3_bucket.main.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:GetObjectVersionTagging"
        ]
        Resource = [for rule in var.replication_rules : "arn:aws:s3:::${rule.destination_bucket_name}/*"]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = length(var.replication_rules) > 0 ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

# Destination buckets (one per rule, in the target region)
resource "aws_s3_bucket" "replication_destination" {
  for_each = { for idx, rule in var.replication_rules : idx => rule }

  provider = aws.replication

  bucket        = each.value.destination_bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replication_destination" {
  for_each = { for idx, rule in var.replication_rules : idx => rule }

  provider = aws.replication

  bucket = aws_s3_bucket.replication_destination[each.key].id
  versioning_configuration {
    status = "Enabled"
  }
}

# Replication configuration on the source bucket
resource "aws_s3_bucket_replication_configuration" "main" {
  count  = length(var.replication_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.main.id
  role   = aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id       = "rule-${rule.value.priority}"
      priority = rule.value.priority
      status   = "Enabled"

      filter {
        prefix = rule.value.filter_prefix
        dynamic "and" {
          for_each = length(keys(rule.value.filter_tags)) > 0 ? [1] : []
          content {
            prefix = rule.value.filter_prefix
            tags   = rule.value.filter_tags
          }
        }
      }

      destination {
        bucket        = aws_s3_bucket.replication_destination[rule.key].arn
        storage_class = "STANDARD"
      }

      dynamic "source_selection_criteria" {
        for_each = rule.value.source_selection_criteria != null ? [rule.value.source_selection_criteria] : []
        content {
          sse_kms_encrypted_objects {
            status = source_selection_criteria.value.sse_kms_encrypted_objects ? "Enabled" : "Disabled"
          }
        }
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.replication_destination,
    aws_iam_role_policy_attachment.replication
  ]
}

# ------------------------------------------------------------------------------
# Inventory Configurations
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "inventory_destination" {
  for_each = { for idx, cfg in var.inventory_configurations : idx => cfg }

  bucket        = each.value.destination_bucket
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "inventory_destination" {
  for_each = { for idx, cfg in var.inventory_configurations : idx => cfg }

  bucket = aws_s3_bucket.inventory_destination[each.key].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = each.value.encryption == "SSE_KMS" ? "aws:kms" : "AES256"
      kms_master_key_id = each.value.encryption == "SSE_KMS" ? each.value.kms_key_arn : null
    }
  }
}

resource "aws_s3_bucket_inventory" "main" {
  for_each = { for idx, cfg in var.inventory_configurations : idx => cfg }

  bucket = aws_s3_bucket.main.id
  name   = "inventory-${each.key}"
  included_object_versions = each.value.included_object_versions
  optional_fields          = each.value.optional_fields
  schedule {
    frequency = each.value.schedule
  }
  destination {
    bucket {
      format     = each.value.format
      bucket_arn = aws_s3_bucket.inventory_destination[each.key].arn
      prefix     = each.value.destination_prefix
      encryption {
        dynamic "sse_s3" {
          for_each = each.value.encryption == "SSE_S3" ? [1] : []
          content {}
        }
        dynamic "sse_kms" {
          for_each = each.value.encryption == "SSE_KMS" ? [1] : []
          content {
            key_id = each.value.kms_key_arn
          }
        }
      }
    }
  }
}

# ------------------------------------------------------------------------------
# CORS Configuration
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_cors_configuration" "main" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.main.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# ------------------------------------------------------------------------------
# Lifecycle Configuration
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "main" {
  count  = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.main.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status

      filter {
        prefix = rule.value.prefix
        dynamic "and" {
          for_each = length(keys(rule.value.tags)) > 0 ? [1] : []
          content {
            prefix = rule.value.prefix
            tags   = rule.value.tags
          }
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          days                         = expiration.value.days
          date                         = expiration.value.date
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "transition" {
        for_each = rule.value.transition != null ? rule.value.transition : []
        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          newer_noncurrent_versions = noncurrent_version_expiration.value.newer_noncurrent_versions
          noncurrent_days            = noncurrent_version_expiration.value.days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transition != null ? rule.value.noncurrent_version_transition : []
        content {
          newer_noncurrent_versions = noncurrent_version_transition.value.newer_noncurrent_versions
          noncurrent_days            = noncurrent_version_transition.value.days
          storage_class             = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload != null ? [rule.value.abort_incomplete_multipart_upload] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }
    }
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "group_name_prefix" {
  type    = string
  default = "app"
}

variable "designated_region" {
  type    = string
  default = "us-east-1"
}

data "aws_caller_identity" "current" {}

locals {
  remote_state_bucket = "terraform-remote-state-${data.aws_caller_identity.current.account_id}"
  developer_group_name = "${var.group_name_prefix}_developer"
  admin_group_name     = "${var.group_name_prefix}_admin"
}

resource "aws_iam_account_password_policy" "this" {
  minimum_password_length        = 14
  require_uppercase_characters   = true
  require_lowercase_characters   = true
  require_numbers                = true
  require_symbols                = true
  allow_users_to_change_password = true
  max_password_age               = 90
  password_reuse_prevention      = 5
}

resource "aws_s3_account_public_access_block" "this" {
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_iam_group" "developer" {
  name = local.developer_group_name
}

resource "aws_iam_group" "admin" {
  name = local.admin_group_name
}

# AWS managed policies for developer group
resource "aws_iam_group_policy_attachment" "developer_readonly" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "developer_change_password" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserChangePassword"
}

resource "aws_iam_group_policy_attachment" "developer_ssh_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserSSHKeys"
}

# Custom policy: developer-personal-keys
data "aws_iam_policy_document" "developer_personal_keys" {
  statement {
    effect = "Allow"
    actions = [
      "iam:CreateAccessKey",
      "iam:UpdateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys",
      "iam:GetAccessKeyLastUsed"
    ]
    resources = ["arn:aws:iam::*:user/$${aws:username}"]
  }
}

resource "aws_iam_policy" "developer_personal_keys" {
  name        = "${var.group_name_prefix}_developer_personal_keys"
  description = "Allow users to manage their own access keys"
  policy      = data.aws_iam_policy_document.developer_personal_keys.json
}

resource "aws_iam_group_policy_attachment" "developer_personal_keys_attach" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_personal_keys.arn
}

# Custom policy: developer-mfa-devices
data "aws_iam_policy_document" "developer_mfa_devices" {
  statement {
    sid    = "AllowManageOwnVirtualMFADevices"
    effect = "Allow"
    actions = [
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
      "iam:ListVirtualMFADevices"
    ]
    resources = ["arn:aws:iam::*:mfa/$${aws:username}"]
  }
  statement {
    sid    = "AllowDeactivateOwnVirtualMFADeviceWithMFA"
    effect = "Allow"
    actions = ["iam:DeactivateMFADevice"]
    resources = ["arn:aws:iam::*:mfa/$${aws:username}"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "developer_mfa_devices" {
  name        = "${var.group_name_prefix}_developer_mfa_devices"
  description = "Allow users to manage their own virtual MFA devices, requiring MFA to deactivate"
  policy      = data.aws_iam_policy_document.developer_mfa_devices.json
}

resource "aws_iam_group_policy_attachment" "developer_mfa_devices_attach" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_mfa_devices.arn
}

# Custom policy: developer-mfa-s3
data "aws_iam_policy_document" "developer_mfa_s3" {
  statement {
    sid    = "DenyCreateBucketOutsideDesignatedRegion"
    effect = "Deny"
    actions = ["s3:CreateBucket"]
    resources = ["*"]
    condition {
      test     = "StringNotEquals"
      variable = "aws:RequestedRegion"
      values   = [var.designated_region]
    }
  }
  statement {
    sid    = "DenyAllS3OnRemoteStateBucket"
    effect = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.remote_state.arn,
      "${aws_s3_bucket.remote_state.arn}/*"
    ]
  }
}

resource "aws_iam_policy" "developer_mfa_s3" {
  name        = "${var.group_name_prefix}_developer_mfa_s3"
  description = "Deny S3 CreateBucket outside designated region and deny all S3 access to remote state bucket"
  policy      = data.aws_iam_policy_document.developer_mfa_s3.json
}

resource "aws_iam_group_policy_attachment" "developer_mfa_s3_attach" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_mfa_s3.arn
}

# Custom policy: developer-mfa-ec2-elb-cw-asg (updated with Deny PassRole without MFA)
data "aws_iam_policy_document" "developer_mfa_ec2_elb_cw_asg" {
  statement {
    sid    = "AllowEC2ELBCWASGWithMFA"
    effect = "Allow"
    actions = [
      "ec2:*",
      "elasticloadbalancing:*",
      "cloudwatch:*",
      "autoscaling:*"
    ]
    resources = ["*"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
  statement {
    sid    = "AllowPassRoleToServiceLinkedRoles"
    effect = "Allow"
    actions = ["iam:PassRole"]
    resources = [
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling",
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/aws-service-role/ec2.amazonaws.com/AWSServiceRoleForEC2"
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
  statement {
    sid    = "DenyPassRoleWithoutMFA"
    effect = "Deny"
    actions = ["iam:PassRole"]
    resources = ["*"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }
}

resource "aws_iam_policy" "developer_mfa_ec2_elb_cw_asg" {
  name        = "${var.group_name_prefix}_developer_mfa_ec2_elb_cw_asg"
  description = "Allow EC2, ELB, CloudWatch, AutoScaling actions and PassRole to service-linked roles only with MFA"
  policy      = data.aws_iam_policy_document.developer_mfa_ec2_elb_cw_asg.json
}

resource "aws_iam_group_policy_attachment" "developer_mfa_ec2_elb_cw_asg_attach" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_mfa_ec2_elb_cw_asg.arn
}

# Remote state S3 bucket
resource "aws_s3_bucket" "remote_state" {
  bucket = local.remote_state_bucket
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id
  versioning_configuration {
    status = "Enabled"
  }
}

# KMS key for SSE-KMS encryption on remote state bucket
resource "aws_kms_key" "remote_state" {
  description             = "CMK for remote state bucket"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

resource "aws_s3_bucket_server_side_encryption_configuration" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.remote_state.arn
    }
  }
}

# Logging bucket for remote state bucket
resource "aws_s3_bucket" "logging" {
  bucket = "${local.remote_state_bucket}-logs"
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logging" {
  bucket = aws_s3_bucket.logging.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "logging" {
  bucket = aws_s3_bucket.logging.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Bucket policy for logging bucket – allow S3 Log Delivery to write logs
data "aws_iam_policy_document" "logging_bucket_policy" {
  statement {
    sid       = "S3ServerAccessLogsWrite"
    effect    = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.logging.arn}/*"]
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_s3_bucket_policy" "logging" {
  bucket = aws_s3_bucket.logging.id
  policy = data.aws_iam_policy_document.logging_bucket_policy.json
}

resource "aws_s3_bucket_logging" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id
  target_bucket = aws_s3_bucket.logging.id
  target_prefix = "logs/"
}

# Group-level MFA enforcement for developer group
data "aws_iam_policy_document" "developer_mfa_enforce" {
  statement {
    sid    = "DenyAllWithoutMFA"
    effect = "Deny"
    actions = ["*"]
    resources = ["*"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }
}

resource "aws_iam_group_policy" "developer_mfa_enforce" {
  group  = aws_iam_group.developer.name
  name   = "${var.group_name_prefix}_developer_mfa_enforce"
  policy = data.aws_iam_policy_document.developer_mfa_enforce.json
}

# Group-level MFA enforcement for admin group
data "aws_iam_policy_document" "admin_mfa_enforce" {
  statement {
    sid    = "DenyAllWithoutMFA"
    effect = "Deny"
    actions = ["*"]
    resources = ["*"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }
}

resource "aws_iam_group_policy" "admin_mfa_enforce" {
  group  = aws_iam_group.admin.name
  name   = "${var.group_name_prefix}_admin_mfa_enforce"
  policy = data.aws_iam_policy_document.admin_mfa_enforce.json
}

# Admin role
data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions = ["sts:AssumeRole"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name               = "admin"
  assume_role_policy = data.aws_iam_policy_document.admin_assume_role.json
}

# Admin full access MFA policy
data "aws_iam_policy_document" "admin_full_access_mfa" {
  statement {
    effect = "Allow"
    actions = ["*"]
    resources = ["*"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "admin_full_access_mfa" {
  name        = "admin-full-access-mfa"
  description = "Full administrative access conditioned on MFA"
  policy      = data.aws_iam_policy_document.admin_full_access_mfa.json
}

resource "aws_iam_role_policy_attachment" "admin_full_access_mfa_attach" {
  role       = aws_iam_role.admin.name
  policy_arn = aws_iam_policy.admin_full_access_mfa.arn
}

# Admin group assume role policy
data "aws_iam_policy_document" "admin_group_assume_role" {
  statement {
    effect = "Allow"
    actions = ["sts:AssumeRole"]
    resources = [aws_iam_role.admin.arn]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "admin_group_assume_role" {
  name        = "${var.group_name_prefix}_admin_assume_role"
  description = "Allow members of admin group to assume the admin role with MFA"
  policy      = data.aws_iam_policy_document.admin_group_assume_role.json
}

resource "aws_iam_group_policy_attachment" "admin_group_assume_role_attach" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_group_assume_role.arn
}

# Import existing resources into Terraform state
import {
  to = aws_iam_group.developer
  id = "${var.group_name_prefix}_developer"
}

import {
  to = aws_iam_group.admin
  id = "${var.group_name_prefix}_admin"
}

import {
  to = aws_iam_policy.developer_mfa_s3
  id = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:policy/${var.group_name_prefix}_developer_mfa_s3"
}

import {
  to = aws_iam_policy.admin_group_assume_role
  id = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:policy/${var.group_name_prefix}_admin_assume_role"
}

import {
  to = aws_iam_policy.developer_personal_keys
  id = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:policy/${var.group_name_prefix}_developer_personal_keys"
}

import {
  to = aws_iam_policy.developer_mfa_devices
  id = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:policy/${var.group_name_prefix}_developer_mfa_devices"
}

import {
  to = aws_iam_policy.developer_mfa_ec2_elb_cw_asg
  id = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:policy/${var.group_name_prefix}_developer_mfa_ec2_elb_cw_asg"
}

import {
  to = aws_s3_bucket.remote_state
  id = local.remote_state_bucket
}

import {
  to = aws_s3_bucket.logging
  id = "${local.remote_state_bucket}-logs"
}

import {
  to = aws_iam_role.admin
  id = "admin"
}

import {
  to = aws_iam_policy.admin_full_access_mfa
  id = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:policy/admin-full-access-mfa"
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_configs" {
  description = "List of subnet configurations with CIDR, AZ, and name"
  type = list(object({
    cidr_block        = string
    availability_zone = string
    name              = string
  }))
  default = [
    { cidr_block = "10.0.0.0/24", availability_zone = "us-east-1a", name = "subnet-0" },
    { cidr_block = "10.0.1.0/24", availability_zone = "us-east-1b", name = "subnet-1" },
    { cidr_block = "10.0.2.0/24", availability_zone = "us-east-1c", name = "subnet-2" },
    { cidr_block = "10.0.3.0/24", availability_zone = "us-east-1a", name = "subnet-3" },
    { cidr_block = "10.0.4.0/24", availability_zone = "us-east-1b", name = "subnet-4" },
    { cidr_block = "10.0.5.0/24", availability_zone = "us-east-1c", name = "subnet-5" },
    { cidr_block = "10.0.6.0/24", availability_zone = "us-east-1a", name = "subnet-6" },
    { cidr_block = "10.0.7.0/24", availability_zone = "us-east-1b", name = "subnet-7" },
    { cidr_block = "10.0.8.0/24", availability_zone = "us-east-1c", name = "subnet-8" },
    { cidr_block = "10.0.9.0/24", availability_zone = "us-east-1a", name = "subnet-9" },
    { cidr_block = "10.0.10.0/24", availability_zone = "us-east-1b", name = "subnet-10" },
    { cidr_block = "10.0.11.0/24", availability_zone = "us-east-1c", name = "subnet-11" },
    { cidr_block = "10.0.12.0/24", availability_zone = "us-east-1a", name = "subnet-12" },
    { cidr_block = "10.0.13.0/24", availability_zone = "us-east-1b", name = "subnet-13" },
    { cidr_block = "10.0.14.0/24", availability_zone = "us-east-1c", name = "subnet-14" },
    { cidr_block = "10.0.15.0/24", availability_zone = "us-east-1a", name = "subnet-15" },
  ]
}

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  instance_tenancy                 = "default"
  assign_generated_ipv6_cidr_block = true
  enable_dns_support               = true
  enable_dns_hostnames             = true

  tags = {
    Name = "my-deploy-me-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "igw-deploy-me"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "deployme-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.private[0].id
  depends_on    = [aws_internet_gateway.main]

  tags = {
    Name = "deployme-natgw"
  }
}

# Private subnets (first 8 in subnet_configs: indices 0-7)
resource "aws_subnet" "private" {
  count = 8

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_configs[count.index].cidr_block
  availability_zone       = var.subnet_configs[count.index].availability_zone
  map_public_ip_on_launch = false

  tags = {
    Name = var.subnet_configs[count.index].name
  }
}

# Public subnets (next 4: indices 8-11)
resource "aws_subnet" "public" {
  count = 4

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_configs[count.index + 8].cidr_block
  availability_zone       = var.subnet_configs[count.index + 8].availability_zone
  map_public_ip_on_launch = false

  tags = {
    Name = var.subnet_configs[count.index + 8].name
  }
}

# Spare subnets (last 4: indices 12-15)
resource "aws_subnet" "spare" {
  count = 4

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_configs[count.index + 12].cidr_block
  availability_zone       = var.subnet_configs[count.index + 12].availability_zone
  map_public_ip_on_launch = false

  tags = {
    Name = var.subnet_configs[count.index + 12].name
  }
}

# Private route table (main)
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "rt-private-deploy-me"
  }
}

# Set private route table as main
resource "aws_main_route_table_association" "set_main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.private.id
}

# Associate private subnets with private route table
resource "aws_route_table_association" "private" {
  count = 8

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.main.id
  }

  tags = {
    Name = "rt-public-deploy-me"
  }
}

# Associate public subnets with public route table
resource "aws_route_table_association" "public" {
  count = 4

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Spare route table
resource "aws_route_table" "spare" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.main.id
  }

  tags = {
    Name = "rt-spare-deploy-me"
  }
}

# Associate spare subnets with spare route table
resource "aws_route_table_association" "spare" {
  count = 4

  subnet_id      = aws_subnet.spare[count.index].id
  route_table_id = aws_route_table.spare.id
}

# Security group for web traffic
resource "aws_security_group" "allow_web_traffic" {
  name        = "allow_web_traffic"
  description = "Allow HTTP, HTTPS, and SSH inbound; outbound to VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "SSH from VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Egress to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "allow_web_traffic"
  }
}

# KMS key for CloudWatch log group encryption with policy allowing CloudWatch Logs
resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for CloudWatch Logs encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudWatchLogs"
        Effect = "Allow"
        Principal = {
          Service = "logs.us-east-1.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "EnableRootAdmin"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "cloudwatch-kms-key"
  }
}

resource "aws_kms_alias" "cloudwatch" {
  name_prefix   = "alias/cloudwatch-"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

# CloudWatch Log Group for VPC Flow Logs (encrypted with CMK, using name_prefix to avoid collisions)
resource "aws_cloudwatch_log_group" "vpc_flow_logs" {
  name_prefix       = "/aws/vpc/flow-logs-"
  retention_in_days = 30
  kms_key_id        = aws_kms_alias.cloudwatch.arn

  tags = {
    Name = "vpc-flow-logs"
  }
}

# IAM Role for VPC Flow Logs
resource "aws_iam_role" "vpc_flow_logs" {
  name_prefix = "vpc-flow-logs-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "vpc-flow-logs-role"
  }
}

# Custom IAM policy for VPC Flow Logs to write to CloudWatch Logs
resource "aws_iam_policy" "vpc_flow_logs" {
  name_prefix = "vpc-flow-logs-policy-"
  description = "Policy for VPC Flow Logs to write to CloudWatch Logs"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.vpc_flow_logs.arn,
          "${aws_cloudwatch_log_group.vpc_flow_logs.arn}:*"
        ]
      }
    ]
  })

  tags = {
    Name = "vpc-flow-logs-policy"
  }
}

# Attach the custom policy to the IAM role
resource "aws_iam_role_policy_attachment" "vpc_flow_logs_custom" {
  role       = aws_iam_role.vpc_flow_logs.name
  policy_arn = aws_iam_policy.vpc_flow_logs.arn
}

# VPC Flow Logs resource
resource "aws_flow_log" "main" {
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.vpc_flow_logs.arn
  iam_role_arn         = aws_iam_role.vpc_flow_logs.arn

  tags = {
    Name = "vpc-flow-log"
  }
}

output "server_public_ip" {
  description = "Public IP of the NAT Gateway Elastic IP"
  value       = aws_eip.nat.public_ip
}

# ------------------------------------------------------------------------------
# TERRAFORM & PROVIDER CONFIGURATION
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

# ------------------------------------------------------------------------------
# DATA SOURCES (static provider metadata)
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------
variable "name" {
  description = "Name for the security group and prefix list"
  type        = string
  default     = "default-sg"
}

variable "environment" {
  description = "Environment (e.g. dev, prod)"
  type        = string
  default     = "default"
}

variable "managedby" {
  description = "Managed by tag value"
  type        = string
  default     = "opsstation"
}

variable "label_order" {
  description = "Order of labels for naming"
  type        = list(string)
  default     = ["name", "environment"]
}

variable "repository" {
  description = "Repository URL for the module"
  type        = string
  default     = "https://github.com/opsstation/terraform-aws-security_group"
}

variable "enable" {
  description = "Enable the creation of all resources"
  type        = bool
  default     = true
}

variable "new_sg" {
  description = "Create a new security group when true"
  type        = bool
  default     = true
}

variable "vpc_id" {
  description = "VPC ID for the security group (required when new_sg = true and vpc_cidr is empty)"
  type        = string
  default     = ""
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC to create when vpc_id is empty"
  type        = string
  default     = "10.0.0.0/16"
}

variable "existing_sg_id" {
  description = "Existing security group ID to apply rules to (used when new_sg = false)"
  type        = string
  default     = ""
}

variable "prefix_list_enabled" {
  description = "Enable creation of a managed prefix list"
  type        = bool
  default     = false
}

variable "prefix_list_ids" {
  description = "List of existing prefix list IDs to use instead of creating one"
  type        = list(string)
  default     = []
}

variable "prefix_list_address_family" {
  description = "Address family for the prefix list (IPv4 or IPv6)"
  type        = string
  default     = "IPv4"
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries in the prefix list"
  type        = number
  default     = 5
}

variable "prefix_list_entries" {
  description = "List of entries for the prefix list"
  type = list(object({
    cidr        = string
    description = optional(string)
  }))
  default = []
}

variable "ingress_rules" {
  description = "List of ingress rules to apply to the security group"
  type = list(object({
    description              = optional(string)
    protocol                 = string
    from_port                = number
    to_port                  = number
    cidr_blocks              = optional(list(string), [])
    ipv6_cidr_blocks         = optional(list(string), [])
    self                     = optional(bool, false)
    source_security_group_id = optional(string, "")
    prefix_list_ids          = optional(list(string), [])
  }))
  default = []
}

variable "egress_rules" {
  description = "List of egress rules to apply to the security group"
  type = list(object({
    description              = optional(string)
    protocol                 = string
    from_port                = number
    to_port                  = number
    cidr_blocks              = optional(list(string), [])
    ipv6_cidr_blocks         = optional(list(string), [])
    self                     = optional(bool, false)
    source_security_group_id = optional(string, "")
    prefix_list_ids          = optional(list(string), [])
  }))
  default = []
}

# ------------------------------------------------------------------------------
# LOCALS
# ------------------------------------------------------------------------------
locals {
  # Determine the effective VPC ID: user-provided or from auto-created VPC
  effective_vpc_id = var.vpc_id != "" ? var.vpc_id : try(aws_vpc.this[0].id, null)

  # Determine the security group ID to use (new or existing)
  sg_id = var.enable ? (
    var.new_sg ? try(aws_security_group.this[0].id, null) : var.existing_sg_id
  ) : null

  # Determine the prefix list ID(s) to use in rules
  created_prefix_list_id = var.enable && var.prefix_list_enabled && length(var.prefix_list_ids) == 0 ? (
    try(aws_ec2_managed_prefix_list.this[0].id, null)
  ) : null

  # Plan-time-known flag: should we create rules? Depends only on variables, not resource IDs.
  # When new_sg is true, rules are created if vpc_id is provided or if vpc_cidr is non-empty (which triggers VPC creation).
  create_rules = var.enable && (
    var.new_sg ? (var.vpc_id != "" || var.vpc_cidr != "") : var.existing_sg_id != ""
  )

  # Process ingress rules: for each rule, if prefix_list_ids is empty and we have a created one, inject it.
  ingress_rules_processed = [
    for rule in var.ingress_rules : merge(rule, {
      prefix_list_ids = length(rule.prefix_list_ids) > 0 ? rule.prefix_list_ids : (local.created_prefix_list_id != null ? [local.created_prefix_list_id] : [])
    })
  ]

  # Process egress rules similarly
  egress_rules_processed = [
    for rule in var.egress_rules : merge(rule, {
      prefix_list_ids = length(rule.prefix_list_ids) > 0 ? rule.prefix_list_ids : (local.created_prefix_list_id != null ? [local.created_prefix_list_id] : [])
    })
  ]
}

# ------------------------------------------------------------------------------
# REMOTE LABELS MODULE (via HTTPS)
# ------------------------------------------------------------------------------
module "labels" {
  source     = "git::https://github.com/opsstation/terraform-aws-labels.git?ref=v1.0.0"
  name       = var.name
  environment = var.environment
  managedby  = var.managedby
  label_order = var.label_order
  repository = var.repository
}

# ------------------------------------------------------------------------------
# VPC (conditional – created only when new_sg and no vpc_id provided)
# ------------------------------------------------------------------------------
resource "aws_vpc" "this" {
  count      = var.enable && var.new_sg && var.vpc_id == "" ? 1 : 0
  cidr_block = var.vpc_cidr
  tags       = module.labels.tags
}

# ------------------------------------------------------------------------------
# KMS KEY AND ALIAS FOR VPC FLOW LOG ENCRYPTION (conditional – only when VPC is auto-created)
# ------------------------------------------------------------------------------
resource "aws_kms_key" "vpc_flow_log" {
  count               = var.enable && var.new_sg && var.vpc_id == "" ? 1 : 0
  description         = "KMS key for VPC Flow Log encryption"
  enable_key_rotation = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow VPC Flow Log Role to use the key"
        Effect = "Allow"
        Principal = {
          AWS = try(aws_iam_role.vpc_flow_log[0].arn, null)
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = module.labels.tags
}

resource "aws_kms_alias" "vpc_flow_log" {
  count         = var.enable && var.new_sg && var.vpc_id == "" ? 1 : 0
  name          = "alias/${module.labels.id}-vpc-flow-log"
  target_key_id = aws_kms_key.vpc_flow_log[0].key_id
}

# ------------------------------------------------------------------------------
# VPC FLOW LOGS (conditional – only when VPC is auto-created)
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "vpc_flow_log" {
  count      = var.enable && var.new_sg && var.vpc_id == "" ? 1 : 0
  name       = "/aws/vpc/flow-logs/${module.labels.id}"
  kms_key_id = try(aws_kms_key.vpc_flow_log[0].arn, null)
  tags       = module.labels.tags
}

resource "aws_iam_role" "vpc_flow_log" {
  count = var.enable && var.new_sg && var.vpc_id == "" ? 1 : 0
  name  = "${module.labels.id}-vpc-flow-log-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "vpc-flow-logs.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
  tags = module.labels.tags
}

# Inline policy for VPC Flow Logs to write to CloudWatch Logs
resource "aws_iam_role_policy" "vpc_flow_log" {
  count = var.enable && var.new_sg && var.vpc_id == "" ? 1 : 0
  name  = "${module.labels.id}-vpc-flow-log-policy"
  role  = aws_iam_role.vpc_flow_log[0].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      }
    ]
  })
}

# Inline policy for KMS permissions (needed for flow log encryption)
resource "aws_iam_role_policy" "vpc_flow_log_kms" {
  count = var.enable && var.new_sg && var.vpc_id == "" ? 1 : 0
  name  = "${module.labels.id}-vpc-flow-log-kms"
  role  = aws_iam_role.vpc_flow_log[0].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = try(aws_kms_key.vpc_flow_log[0].arn, null)
      }
    ]
  })
}

resource "aws_flow_log" "this" {
  count                = var.enable && var.new_sg && var.vpc_id == "" ? 1 : 0
  log_destination      = aws_cloudwatch_log_group.vpc_flow_log[0].arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.vpc_flow_log[0].arn
  vpc_id               = aws_vpc.this[0].id
  traffic_type         = "ALL"
  tags                 = module.labels.tags
}

# ------------------------------------------------------------------------------
# SECURITY GROUP (conditional)
# ------------------------------------------------------------------------------
resource "aws_security_group" "this" {
  count       = var.enable && var.new_sg ? 1 : 0
  name        = "${module.labels.id}-sg"
  description = "Security group created by Terraform module"
  vpc_id      = local.effective_vpc_id
  tags        = module.labels.tags

  lifecycle {
    create_before_destroy = true
  }
}

# ------------------------------------------------------------------------------
# MANAGED PREFIX LIST (conditional)
# ------------------------------------------------------------------------------
resource "aws_ec2_managed_prefix_list" "this" {
  count          = var.enable && var.prefix_list_enabled && length(var.prefix_list_ids) == 0 ? 1 : 0
  name           = "${module.labels.id}-prefix-list"
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = lookup(entry.value, "description", null)
    }
  }

  tags = module.labels.tags
}

# ------------------------------------------------------------------------------
# INGRESS RULES (dynamic)
# ------------------------------------------------------------------------------
resource "aws_security_group_rule" "ingress" {
  for_each = local.create_rules ? {
    for idx, rule in local.ingress_rules_processed : idx => rule
  } : {}

  security_group_id = local.sg_id
  type              = "ingress"
  description       = lookup(each.value, "description", null)
  protocol          = each.value.protocol
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  cidr_blocks       = length(each.value.cidr_blocks) > 0 ? each.value.cidr_blocks : null
  ipv6_cidr_blocks  = length(each.value.ipv6_cidr_blocks) > 0 ? each.value.ipv6_cidr_blocks : null
  self              = each.value.self ? true : null
  source_security_group_id = each.value.source_security_group_id != "" ? each.value.source_security_group_id : null
  prefix_list_ids   = length(each.value.prefix_list_ids) > 0 ? each.value.prefix_list_ids : null
}

# ------------------------------------------------------------------------------
# EGRESS RULES (dynamic)
# ------------------------------------------------------------------------------
resource "aws_security_group_rule" "egress" {
  for_each = local.create_rules ? {
    for idx, rule in local.egress_rules_processed : idx => rule
  } : {}

  security_group_id = local.sg_id
  type              = "egress"
  description       = lookup(each.value, "description", null)
  protocol          = each.value.protocol
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  cidr_blocks       = length(each.value.cidr_blocks) > 0 ? each.value.cidr_blocks : null
  ipv6_cidr_blocks  = length(each.value.ipv6_cidr_blocks) > 0 ? each.value.ipv6_cidr_blocks : null
  self              = each.value.self ? true : null
  source_security_group_id = each.value.source_security_group_id != "" ? each.value.source_security_group_id : null
  prefix_list_ids   = length(each.value.prefix_list_ids) > 0 ? each.value.prefix_list_ids : null
}

# ------------------------------------------------------------------------------
# OUTPUTS
# ------------------------------------------------------------------------------
output "security_group_id" {
  description = "ID of the security group (new or existing)"
  value       = local.sg_id
}

output "prefix_list_id" {
  description = "ID of the created prefix list, if any"
  value       = var.enable && var.prefix_list_enabled && length(var.prefix_list_ids) == 0 ? (
    try(aws_ec2_managed_prefix_list.this[0].id, null)
  ) : null
}

output "label_id" {
  description = "ID generated by the labels module"
  value       = module.labels.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Environment name used for naming roles"
  type        = string
  default     = "dev"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# IAM Account Password Policy
resource "aws_iam_account_password_policy" "strict" {
  minimum_password_length      = 14
  require_lowercase_characters = true
  require_uppercase_characters = true
  require_numbers              = true
  require_symbols              = true
  allow_users_to_change_password = true
  max_password_age             = 90
  password_reuse_prevention    = 5
}

