# Developers Policy (Limited MFA)
resource "aws_iam_policy" "developers_policy" {
  name        = "developers-policy-limited-mfa"
  description = "Developer policy with MFA enforcement for sensitive actions"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3Access"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowSecretsManagerReadOnlyWithMFA"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret",
          "secretsmanager:ListSecrets"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "AllowCloudWatchReadOnlyWithMFA"
        Effect = "Allow"
        Action = [
          "cloudwatch:Describe*",
          "cloudwatch:Get*",
          "cloudwatch:List*"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "AllowECSReadOnlyWithMFA"
        Effect = "Allow"
        Action = [
          "ecs:Describe*",
          "ecs:List*"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "AllowSelfServiceIAM"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:CreateAccessKey",
          "iam:ListAccessKeys",
          "iam:DeleteAccessKey",
          "iam:UpdateAccessKey",
          "iam:UploadSSHPublicKey",
          "iam:ListSSHPublicKeys",
          "iam:GetSSHPublicKey",
          "iam:DeleteSSHPublicKey"
        ]
        Resource = "arn:aws:iam::*:user/$${aws:username}"
      },
      {
        Sid    = "DenyAllIfNoMFA"
        Effect = "Deny"
        NotAction = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket",
          "iam:ChangePassword",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:CreateAccessKey",
          "iam:ListAccessKeys",
          "iam:DeleteAccessKey",
          "iam:UpdateAccessKey",
          "iam:UploadSSHPublicKey",
          "iam:ListSSHPublicKeys",
          "iam:GetSSHPublicKey",
          "iam:DeleteSSHPublicKey"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

# Billing Policy (Limited MFA)
resource "aws_iam_policy" "billing_policy" {
  name        = "billing-policy-limited-mfa"
  description = "Billing policy with MFA enforcement"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowBillingWithMFA"
        Effect = "Allow"
        Action = [
          "aws-portal:*",
          "budgets:*",
          "ce:*",
          "payments:*",
          "tax:*"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "AllowSelfServiceIAM"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:CreateAccessKey",
          "iam:ListAccessKeys",
          "iam:DeleteAccessKey",
          "iam:UpdateAccessKey",
          "iam:UploadSSHPublicKey",
          "iam:ListSSHPublicKeys",
          "iam:GetSSHPublicKey",
          "iam:DeleteSSHPublicKey"
        ]
        Resource = "arn:aws:iam::*:user/$${aws:username}"
      },
      {
        Sid    = "DenyAllIfNoMFA"
        Effect = "Deny"
        NotAction = [
          "iam:ChangePassword",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:CreateAccessKey",
          "iam:ListAccessKeys",
          "iam:DeleteAccessKey",
          "iam:UpdateAccessKey",
          "iam:UploadSSHPublicKey",
          "iam:ListSSHPublicKeys",
          "iam:GetSSHPublicKey",
          "iam:DeleteSSHPublicKey"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Terraform required blocks
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 6.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "config" {
  description = "Path to YAML configuration file defining pipelines"
  type        = string
  default     = "pipeline_config.yaml"
}

# ------------------------------------------------------------------------------
# Data sources
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

# ------------------------------------------------------------------------------
# Locals – parse YAML configuration
# ------------------------------------------------------------------------------
locals {
  # Fallback to empty object if config file not found
  raw_config = try(yamldecode(file(var.config)), yamldecode(file("${path.module}/${var.config}")), {})
  pipelines  = try(local.raw_config.pipelines, [])
  create_default_role = try(local.raw_config.create_default_pipeline_role, true)

  # Build a map for easy lookup of pipeline by name
  pipeline_map = { for p in local.pipelines : p.name => p }

  # Extract providers that require CodeStar connections
  codestar_providers = toset(["Bitbucket", "GitHub", "GitHubEnterpriseServer"])
}

# ------------------------------------------------------------------------------
# S3 buckets – artifact store and cache per pipeline
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "artifact_store" {
  for_each = local.pipeline_map
  bucket   = "${each.key}-artifacts"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "cache" {
  for_each = local.pipeline_map
  bucket   = "${each.key}-cache"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "artifact_store" {
  for_each = local.pipeline_map
  bucket   = aws_s3_bucket.artifact_store[each.key].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "cache" {
  for_each = local.pipeline_map
  bucket   = aws_s3_bucket.cache[each.key].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact_store" {
  for_each = local.pipeline_map
  bucket   = aws_s3_bucket.artifact_store[each.key].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cache" {
  for_each = local.pipeline_map
  bucket   = aws_s3_bucket.cache[each.key].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "artifact_store" {
  for_each = local.pipeline_map
  bucket   = aws_s3_bucket.artifact_store[each.key].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "cache" {
  for_each = local.pipeline_map
  bucket   = aws_s3_bucket.cache[each.key].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# Default CodePipeline IAM role (path /terraforest/)
# ------------------------------------------------------------------------------
resource "aws_iam_role" "codepipeline_default" {
  count = local.create_default_role ? 1 : 0
  name  = "terraform-forest-codepipeline-role"
  path  = "/terraforest/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codepipeline.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "codepipeline_default" {
  count = local.create_default_role ? 1 : 0
  name  = "terraform-forest-codepipeline-policy"
  role  = aws_iam_role.codepipeline_default[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "codecommit:*",
          "codebuild:*",
          "ecr:*"
        ]
        Resource = "*"
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# CodeStar Connections (for Bitbucket, GitHub, GitHubEnterpriseServer)
# ------------------------------------------------------------------------------
resource "aws_codestarconnections_connection" "this" {
  for_each = {
    for p in local.pipelines : p.name => p
    if contains(local.codestar_providers, try(p.source.provider, ""))
  }
  name          = "${each.key}-connection"
  provider_type = each.value.source.provider
}

# ------------------------------------------------------------------------------
# CodePipeline resources
# ------------------------------------------------------------------------------
resource "aws_codepipeline" "this" {
  for_each = local.pipeline_map

  name     = each.key
  role_arn = local.create_default_role ? aws_iam_role.codepipeline_default[0].arn : aws_iam_role.codepipeline_default[0].arn # fallback – always create default

  artifact_store {
    location = aws_s3_bucket.artifact_store[each.key].bucket
    type     = "S3"
  }

  # Source stage
  stage {
    name = "Source"
    action {
      name    = "Source"
      owner   = "AWS"
      version = "1"
      category = "Source"

      provider = try(each.value.source.provider, "CodeCommit")
      configuration = merge(
        {
          # Common source fields
          BranchName = try(each.value.source.branch, "main")
        },
        try(each.value.source.provider, null) == "CodeCommit" ? {
          RepositoryName = each.value.source.repository_name
        } : {},
        try(each.value.source.provider, null) == "S3" ? {
          S3Bucket = each.value.source.bucket
          S3ObjectKey = each.value.source.object_key
        } : {},
        try(each.value.source.provider, null) == "ECR" ? {
          RepositoryName = each.value.source.repository_name
          ImageTag       = try(each.value.source.image_tag, "latest")
        } : {},
        contains(local.codestar_providers, try(each.value.source.provider, "")) ? {
          ConnectionArn = aws_codestarconnections_connection.this[each.key].arn
          FullRepositoryId = try(each.value.source.owner, "") != "" ? "${each.value.source.owner}/${each.value.source.repo}" : each.value.source.repo
        } : {}
      )
      output_artifacts = ["SourceArtifact"]
    }
  }

  # Dynamic stages from configuration
  dynamic "stage" {
    for_each = try(each.value.stages, [])
    content {
      name = stage.value.name

      dynamic "action" {
        for_each = try(stage.value.actions, [])
        content {
          name    = action.value.name
          owner   = "AWS"
          version = "1"
          category = try(action.value.category, null) == null ? (
            action.value.provider == "Manual" ? "Approval" : (
              action.value.provider == "Lambda" ? "Invoke" : "Build"
            )
          ) : action.value.category

          provider = action.value.provider
          configuration = merge(
            {
              ProjectName = try(action.value.project_name, null)
              FunctionName = try(action.value.function_name, null)
              CustomData   = try(action.value.configuration.CustomData, null)
            },
            try(action.value.configuration, {})
          )
          input_artifacts  = try(action.value.input_artifacts, [])
          output_artifacts = try(action.value.output_artifacts, [])
          run_order       = try(action.value.run_order, null)
        }
      }
    }
  }
}

# ------------------------------------------------------------------------------
# EventBridge IAM roles (terrabits-<pipeline_name>)
# ------------------------------------------------------------------------------
resource "aws_iam_role" "eventbridge" {
  for_each = local.pipeline_map
  name     = "terrabits-${each.key}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "eventbridge" {
  for_each = local.pipeline_map
  name     = "terrabits-${each.key}-policy"
  role     = aws_iam_role.eventbridge[each.key].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "codepipeline:StartPipelineExecution"
        Resource = aws_codepipeline.this[each.key].arn
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# CloudWatch Event Rules per pipeline trigger
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_event_rule" "pipeline_triggers" {
  for_each = {
    for tuple in flatten([
      for p in local.pipelines : [
        for idx, trigger in try(p.triggers, []) : {
          key  = "${p.name}-${idx}"
          pipeline_name = p.name
          trigger = trigger
        }
      ]
    ]) : tuple.key => tuple
  }

  name        = "${each.value.pipeline_name}-trigger-${each.value.trigger.type}"
  description = "Trigger for pipeline ${each.value.pipeline_name}"

  # Merge schedule_expression and event_pattern into a single conditional
  schedule_expression = try(each.value.trigger.cron_expression, null)

  event_pattern = try(each.value.trigger.event_pattern, null) != null ? jsonencode(each.value.trigger.event_pattern) : (
    each.value.trigger.type == "CodeCommitBranchChange" ? jsonencode({
      source      = ["aws.codecommit"]
      detail-type = ["CodeCommit Repository State Change"]
      resources   = ["arn:${data.aws_partition.current.partition}:codecommit:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:${each.value.trigger.repository_name}"]
      detail = {
        event         = ["referenceCreated", "referenceUpdated"]
        referenceType = ["branch"]
        referenceName = [each.value.trigger.branch_name]
      }
    }) : each.value.trigger.type == "CodeCommitTagChange" ? jsonencode({
      source      = ["aws.codecommit"]
      detail-type = ["CodeCommit Repository State Change"]
      resources   = ["arn:${data.aws_partition.current.partition}:codecommit:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:${each.value.trigger.repository_name}"]
      detail = {
        event         = ["referenceCreated", "referenceUpdated"]
        referenceType = ["tag"]
        referenceName = [each.value.trigger.tag_name]
      }
    }) : null
  )
}

resource "aws_cloudwatch_event_target" "pipeline_triggers" {
  for_each = aws_cloudwatch_event_rule.pipeline_triggers

  rule     = each.value.name
  arn      = aws_codepipeline.this[split("-", each.key)[0]].arn
  role_arn = aws_iam_role.eventbridge[split("-", each.key)[0]].arn
}

# ------------------------------------------------------------------------------
# Terraform configuration
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "server_name" {
  description = "Base name used for Transfer Family server, IAM roles, and security groups"
  type        = string
  default     = "sftp-server"
}

variable "vpc_id" {
  description = "ID of an existing VPC. If empty, a new VPC will be created."
  type        = string
  default     = ""
}

variable "subnet_ids" {
  description = "List of subnet IDs for mount targets. If empty and vpc_id is also empty, new subnets are created."
  type        = list(string)
  default     = []
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC. Required only if vpc_id is provided; otherwise ignored."
  type        = string
  default     = ""

  validation {
    condition     = var.vpc_id == "" || var.vpc_cidr != ""
    error_message = "vpc_cidr must be provided when vpc_id is set."
  }
}

variable "performance_mode" {
  description = "EFS performance mode: 'generalPurpose' or 'maxIO'."
  type        = string
  default     = "generalPurpose"
  validation {
    condition     = contains(["generalPurpose", "maxIO"], var.performance_mode)
    error_message = "performance_mode must be 'generalPurpose' or 'maxIO'."
  }
}

variable "is_public" {
  description = "If true and no VPC is provided, allocate Elastic IPs for a public endpoint."
  type        = bool
  default     = false
}

variable "logging_enabled" {
  description = "If true, create CloudWatch log group and IAM logging role for the Transfer server."
  type        = bool
  default     = false
}

variable "kms_key_arn" {
  description = "ARN of an existing KMS key for EFS encryption. If empty, a new key is created."
  type        = string
  default     = ""
}

variable "allowed_cidr" {
  description = "CIDR block allowed to connect to the SFTP server on port 22."
  type        = string
  default     = "10.0.0.0/16"
}

variable "sftp_users" {
  description = "Map of SFTP users. Each key is the user name."
  type = map(object({
    posix_uid      = number
    posix_gid      = number
    ssh_public_key = string
    home_directory = optional(string)
    restricted     = optional(bool, false)
    iam_role_arn   = optional(string)
  }))
  default = {}
}

variable "additional_access_points" {
  description = "Map of additional EFS access points for general storage paths."
  type = map(object({
    root_directory = string
    posix_uid      = number
    posix_gid      = number
    tags           = optional(map(string), {})
  }))
  default = {}
}

variable "tags" {
  description = "Tags to apply to all resources."
  type        = map(string)
  default     = {}
}

# ------------------------------------------------------------------------------
# Data sources
# ------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------
locals {
  # VPC ID: use provided, or the created one
  vpc_id = var.vpc_id != "" ? var.vpc_id : (
    length(aws_vpc.main) > 0 ? aws_vpc.main[0].id : ""
  )

  # Subnet IDs: use provided, or the created ones (public + private)
  subnet_ids = length(var.subnet_ids) > 0 ? var.subnet_ids : (
    var.vpc_id == "" ? concat(
      aws_subnet.public[*].id,
      aws_subnet.private[*].id
    ) : []
  )

  # VPC CIDR: use provided, or from created VPC, or fallback
  vpc_cidr = var.vpc_cidr != "" ? var.vpc_cidr : (
    var.vpc_id == "" ? aws_vpc.main[0].cidr_block : "10.0.0.0/16"
  )

  # KMS key ARN: use provided, or the created one
  kms_key_arn = var.kms_key_arn != "" ? var.kms_key_arn : (
    length(aws_kms_key.efs) > 0 ? aws_kms_key.efs[0].arn : ""
  )

  # Endpoint type
  endpoint_type = local.vpc_id != "" ? "VPC" : "PUBLIC"

  # Elastic IP allocation IDs (only when public and no VPC)
  address_allocation_ids = var.is_public && local.endpoint_type == "PUBLIC" ? aws_eip.main[*].id : []
}

# ------------------------------------------------------------------------------
# VPC and networking (only when vpc_id is empty)
# ------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  count      = var.vpc_id == "" ? 1 : 0
  cidr_block = "10.0.0.0/16"
  tags       = merge(var.tags, { Name = "${var.server_name}-vpc" })
}

resource "aws_internet_gateway" "main" {
  count  = var.vpc_id == "" ? 1 : 0
  vpc_id = aws_vpc.main[0].id
  tags   = merge(var.tags, { Name = "${var.server_name}-igw" })
}

# Two subnets: public (AZ 0) and private (AZ 1)
resource "aws_subnet" "public" {
  count             = var.vpc_id == "" ? 1 : 0
  vpc_id            = aws_vpc.main[0].id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]
  tags              = merge(var.tags, { Name = "${var.server_name}-public-subnet" })
}

resource "aws_subnet" "private" {
  count             = var.vpc_id == "" ? 1 : 0
  vpc_id            = aws_vpc.main[0].id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]
  tags              = merge(var.tags, { Name = "${var.server_name}-private-subnet" })
}

resource "aws_route_table" "public" {
  count  = var.vpc_id == "" ? 1 : 0
  vpc_id = aws_vpc.main[0].id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = merge(var.tags, { Name = "${var.server_name}-public-rt" })
}

resource "aws_route_table_association" "public" {
  count          = var.vpc_id == "" ? 1 : 0
  subnet_id      = aws_subnet.public[0].id
  route_table_id = aws_route_table.public[0].id
}

# ------------------------------------------------------------------------------
# Security groups
# ------------------------------------------------------------------------------
resource "aws_security_group" "sftp" {
  count       = 1
  name        = "${var.server_name}-sftp-sg"
  description = "Security group for Transfer Family SFTP server"
  vpc_id      = local.vpc_id

  ingress {
    description = "SSH from allowed CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.allowed_cidr]
  }

  egress {
    description = "Egress to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(var.tags, { Name = "${var.server_name}-sftp-sg" })
}

resource "aws_security_group" "efs" {
  count       = length(local.subnet_ids) > 0 ? 1 : 0
  name        = "${var.server_name}-efs-sg"
  description = "Security group for EFS mount targets"
  vpc_id      = local.vpc_id

  ingress {
    description = "NFS from VPC CIDR"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Egress to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(var.tags, { Name = "${var.server_name}-efs-sg" })
}

# ------------------------------------------------------------------------------
# Elastic IPs (only for public endpoint without VPC)
# ------------------------------------------------------------------------------
resource "aws_eip" "main" {
  count  = var.is_public && local.endpoint_type == "PUBLIC" ? 1 : 0
  domain = "vpc"
  tags   = merge(var.tags, { Name = "${var.server_name}-eip" })
}

# ------------------------------------------------------------------------------
# KMS key for EFS (if not provided)
# ------------------------------------------------------------------------------
resource "aws_kms_key" "efs" {
  count                   = var.kms_key_arn == "" ? 1 : 0
  description             = "EFS CMK for ${var.server_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = var.tags
}

resource "aws_kms_alias" "efs" {
  count         = var.kms_key_arn == "" ? 1 : 0
  name          = "alias/${var.server_name}-efs-key"
  target_key_id = aws_kms_key.efs[0].key_id
}

# ------------------------------------------------------------------------------
# KMS key for CloudWatch logs (only when needed)
# ------------------------------------------------------------------------------
resource "aws_kms_key" "cloudwatch" {
  count                   = (var.logging_enabled || var.vpc_id == "") ? 1 : 0
  description             = "CMK for CloudWatch logs of ${var.server_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
      }
    ]
  })
  tags = var.tags
}

data "aws_caller_identity" "current" {}

resource "aws_kms_alias" "cloudwatch" {
  count         = (var.logging_enabled || var.vpc_id == "") ? 1 : 0
  name          = "alias/${var.server_name}-cloudwatch-key"
  target_key_id = aws_kms_key.cloudwatch[0].key_id
}

# ------------------------------------------------------------------------------
# EFS File System
# ------------------------------------------------------------------------------
resource "aws_efs_file_system" "main" {
  creation_token   = "${var.server_name}-efs"
  performance_mode = var.performance_mode
  throughput_mode  = "bursting"
  encrypted        = true
  kms_key_id       = local.kms_key_arn

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(var.tags, { Name = "${var.server_name}-efs" })
}

# ------------------------------------------------------------------------------
# EFS Mount Targets (only when subnet_ids is non-empty)
# ------------------------------------------------------------------------------
resource "aws_efs_mount_target" "main" {
  count          = length(local.subnet_ids) > 0 ? length(local.subnet_ids) : 0
  file_system_id = aws_efs_file_system.main.id
  subnet_id      = local.subnet_ids[count.index]
  security_groups = length(aws_security_group.efs) > 0 ? [aws_security_group.efs[0].id] : []
}

# ------------------------------------------------------------------------------
# Transfer Family SFTP Server
# ------------------------------------------------------------------------------
resource "aws_transfer_server" "main" {
  domain                 = "EFS"
  identity_provider_type = "SERVICE_MANAGED"
  security_policy_name   = "TransferSecurityPolicy-2023-05"
  endpoint_type          = local.endpoint_type

  # VPC endpoint details
  endpoint_details {
    vpc_id             = local.vpc_id != "" ? local.vpc_id : null
    subnet_ids         = local.endpoint_type == "VPC" ? local.subnet_ids : null
    security_group_ids = local.endpoint_type == "VPC" ? [aws_security_group.sftp[0].id] : null
    address_allocation_ids = length(local.address_allocation_ids) > 0 ? local.address_allocation_ids : null
  }

  # Logging role
  logging_role = var.logging_enabled ? aws_iam_role.logging[0].arn : null

  tags = merge(var.tags, { Name = var.server_name })
}

# ------------------------------------------------------------------------------
# CloudWatch Logging (optional)
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "transfer" {
  count             = var.logging_enabled ? 1 : 0
  name              = "/aws/transfer/${var.server_name}"
  retention_in_days = 30
  kms_key_id        = aws_kms_alias.cloudwatch[0].arn
  lifecycle {
    prevent_destroy = true
  }
  tags = var.tags
}

resource "aws_iam_role" "logging" {
  count = var.logging_enabled ? 1 : 0
  name  = "${var.server_name}-logging-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy" "logging" {
  count = var.logging_enabled ? 1 : 0
  name  = "${var.server_name}-logging-policy"
  role  = aws_iam_role.logging[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = aws_cloudwatch_log_group.transfer[0].arn
      },
      {
        Effect = "Allow"
        Action = "kms:Decrypt"
        Resource = aws_kms_key.cloudwatch[0].arn
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# VPC Flow Logs (only when VPC is created)
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "flow_log" {
  count             = var.vpc_id == "" ? 1 : 0
  name              = "/aws/vpc-flow-logs/${var.server_name}"
  retention_in_days = 30
  kms_key_id        = aws_kms_alias.cloudwatch[0].arn
  lifecycle {
    prevent_destroy = true
  }
  tags = var.tags
}

resource "aws_iam_role" "flow_log" {
  count = var.vpc_id == "" ? 1 : 0
  name  = "${var.server_name}-flow-log-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy" "flow_log" {
  count = var.vpc_id == "" ? 1 : 0
  name  = "${var.server_name}-flow-log-policy"
  role  = aws_iam_role.flow_log[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "kms:Decrypt"
        Resource = aws_kms_key.cloudwatch[0].arn
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  count                = var.vpc_id == "" ? 1 : 0
  log_destination      = aws_cloudwatch_log_group.flow_log[0].arn
  log_destination_type = "cloud-watch-logs"
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.main[0].id
  iam_role_arn         = aws_iam_role.flow_log[0].arn
  tags                 = merge(var.tags, { Name = "${var.server_name}-flow-log" })
}

# ------------------------------------------------------------------------------
# SFTP Users
# ------------------------------------------------------------------------------
resource "aws_transfer_user" "users" {
  for_each            = var.sftp_users
  server_id           = aws_transfer_server.main.id
  user_name           = each.key
  role                = try(each.value.iam_role_arn, "") != "" ? each.value.iam_role_arn : aws_iam_role.user[each.key].arn
  home_directory_type = each.value.restricted ? "PATH" : "LOGICAL"
  home_directory      = each.value.restricted ? each.value.home_directory : null

  posix_profile {
    uid = each.value.posix_uid
    gid = each.value.posix_gid
  }

  tags = merge(var.tags, { Name = "${var.server_name}-user-${each.key}" })
}

resource "aws_transfer_ssh_key" "users" {
  for_each  = var.sftp_users
  server_id = aws_transfer_server.main.id
  user_name = aws_transfer_user.users[each.key].user_name
  body      = each.value.ssh_public_key
}

# IAM roles for users without provided iam_role_arn
resource "aws_iam_role" "user" {
  for_each = {
    for k, v in var.sftp_users : k => v
    if try(v.iam_role_arn, "") == ""
  }
  name = "${var.server_name}-${each.key}-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = merge(var.tags, { Name = "${var.server_name}-${each.key}-role" })
}

resource "aws_iam_role_policy" "user" {
  for_each = aws_iam_role.user
  name     = "${var.server_name}-${each.key}-efs-policy"
  role     = each.value.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
          "elasticfilesystem:ClientRootAccess"
        ]
        Resource = aws_efs_file_system.main.arn
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# EFS Access Points for Users
# ------------------------------------------------------------------------------
resource "aws_efs_access_point" "user" {
  for_each       = var.sftp_users
  file_system_id = aws_efs_file_system.main.id

  posix_user {
    uid = each.value.posix_uid
    gid = each.value.posix_gid
  }

  root_directory {
    path = try(each.value.home_directory, "/${each.key}")
    creation_info {
      owner_uid   = each.value.posix_uid
      owner_gid   = each.value.posix_gid
      permissions = "0755"
    }
  }

  tags = merge(var.tags, { Name = "${var.server_name}-ap-${each.key}" })
}

# ------------------------------------------------------------------------------
# Additional EFS Access Points
# ------------------------------------------------------------------------------
resource "aws_efs_access_point" "additional" {
  for_each       = var.additional_access_points
  file_system_id = aws_efs_file_system.main.id

  posix_user {
    uid = each.value.posix_uid
    gid = each.value.posix_gid
  }

  root_directory {
    path = each.value.root_directory
    creation_info {
      owner_uid   = each.value.posix_uid
      owner_gid   = each.value.posix_gid
      permissions = "0755"
    }
  }

  tags = merge(var.tags, each.value.tags, { Name = "${var.server_name}-ap-${each.key}" })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Provider configuration is injected externally; do not include a provider block.

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "create_bucket" {
  description = "Whether to create the S3 bucket."
  type        = bool
  default     = true
}

variable "create_kms_key" {
  description = "Whether to create a customer-managed KMS key for SSE-KMS."
  type        = bool
  default     = true
}

variable "bucket_name" {
  description = "Explicit bucket name. If empty, a name will be generated using bucket_prefix or a default prefix."
  type        = string
  default     = ""
}

variable "bucket_prefix" {
  description = "Prefix for the generated bucket name. Ignored if bucket_name is set."
  type        = string
  default     = ""
}

variable "force_destroy" {
  description = "Allow force destroy of bucket even if it contains objects."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags to apply to the bucket and KMS key."
  type        = map(string)
  default     = {}
}

variable "object_lock_configuration" {
  description = "Object lock configuration for the bucket. Provide an object with default_retention block."
  type = any
  default = null
}

variable "acl" {
  description = "Canned ACL to apply to the bucket (e.g., 'private', 'public-read')."
  type        = string
  default     = null
}

variable "grant" {
  description = "List of ACL grant blocks (see aws_s3_bucket grant)."
  type = any
  default = null
}

variable "website" {
  description = "Static website hosting configuration."
  type = any
  default = null
}

variable "cors_rule" {
  description = "List of CORS rules."
  type = any
  default = null
}

variable "versioning" {
  description = "Versioning configuration (enable, mfa_delete)."
  type = any
  default = { enabled = true }
}

variable "logging" {
  description = "Access logging configuration (target_bucket, target_prefix). If null, a default logging bucket is created."
  type = any
  default = null
}

variable "acceleration_status" {
  description = "Transfer acceleration status ('Enabled' or 'Suspended')."
  type        = string
  default     = null
}

variable "request_payer" {
  description = "Requester pays configuration ('BucketOwner' or 'Requester')."
  type        = string
  default     = null
}

variable "lifecycle_rule" {
  description = "List of lifecycle rule configurations."
  type = any
  default = null
}

variable "replication_configuration" {
  description = "Cross-region replication configuration."
  type = any
  default = null
}

variable "intelligent_tiering" {
  description = "Intelligent-Tiering configuration."
  type = any
  default = null
}

variable "object_ownership" {
  description = "Object ownership controls. Set to 'BucketOwnerPreferred', 'ObjectWriter', or 'BucketOwnerEnforced'."
  type        = string
  default     = null
}

variable "server_side_encryption_configuration" {
  description = "Custom server-side encryption configuration (overrides default KMS)."
  type = any
  default = null
}

# Bucket policy toggles
variable "attach_elb_log_delivery_policy" {
  description = "Whether to attach a policy granting ELB access log delivery."
  type        = bool
  default     = false
}

variable "deny_insecure_transport" {
  description = "Whether to deny requests that do not use HTTPS."
  type        = bool
  default     = false
}

variable "deny_tls_versions_older_than_1_2" {
  description = "Whether to deny requests using TLS versions older than 1.2."
  type        = bool
  default     = false
}

variable "attach_user_supplied_policy" {
  description = "Whether to attach a user-supplied JSON policy."
  type        = bool
  default     = false
}

variable "user_supplied_policy" {
  description = "JSON policy document to attach when attach_user_supplied_policy is true."
  type        = string
  default     = null
}

variable "create_default_logging_bucket" {
  description = "Whether to create a default logging bucket when logging is not explicitly configured."
  type        = bool
  default     = true
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  # Bucket name logic
  bucket_name_final   = var.bucket_name != "" ? var.bucket_name : null
  bucket_prefix_final = var.bucket_name != "" ? null : (var.bucket_prefix != "" ? var.bucket_prefix : "tf-s3-")

  # KMS key creation flag
  create_kms = var.create_kms_key

  # Encryption configuration: use custom if provided, else KMS if created, else SSE-S3
  sse_config = var.server_side_encryption_configuration != null ? var.server_side_encryption_configuration : (
    local.create_kms ? [
      {
        rule = {
          apply_server_side_encryption_by_default = {
            sse_algorithm     = "aws:kms"
            kms_master_key_id = aws_kms_key.this[0].arn
          }
        }
      }
    ] : [
      {
        rule = {
          apply_server_side_encryption_by_default = {
            sse_algorithm = "AES256"
          }
        }
      }
    ]
  )

  # Whether any policy toggle is enabled
  enable_bucket_policy = var.attach_elb_log_delivery_policy || var.deny_insecure_transport || var.deny_tls_versions_older_than_1_2 || var.attach_user_supplied_policy

  # Bucket ARN for use in policy
  bucket_arn = var.create_bucket ? aws_s3_bucket.this[0].arn : ""

  # Default logging bucket creation flag (used in count)
  create_default_logging = var.create_default_logging_bucket && var.logging == null

  # Effective logging configuration
  logging_effective = var.logging != null ? var.logging : (
    local.create_default_logging ? {
      target_bucket = aws_s3_bucket.log_bucket[0].id
      target_prefix = "s3-access-logs/"
    } : null
  )
}

# ------------------------------------------------------------------------------
# KMS Key
# ------------------------------------------------------------------------------

resource "aws_kms_key" "this" {
  count                   = local.create_kms ? 1 : 0
  description             = "S3 bucket encryption key"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  tags                    = var.tags
}

resource "aws_kms_alias" "this" {
  count         = local.create_kms ? 1 : 0
  name          = "alias/s3-bucket-key"
  target_key_id = aws_kms_key.this[0].key_id
}

# ------------------------------------------------------------------------------
# Default Logging Bucket
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "log_bucket" {
  count         = local.create_default_logging ? 1 : 0
  bucket_prefix = "tf-s3-logs-"
  force_destroy = false
  tags          = var.tags
}

resource "aws_s3_bucket_versioning" "log_bucket" {
  count  = local.create_default_logging ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log_bucket" {
  count  = local.create_default_logging ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "log_bucket" {
  count  = local.create_default_logging ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "log_bucket" {
  count  = local.create_default_logging ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "log_bucket" {
  count  = local.create_default_logging ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id
  acl    = "log-delivery-write"

  depends_on = [aws_s3_bucket_ownership_controls.log_bucket]
}

# ------------------------------------------------------------------------------
# S3 Bucket (Main)
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "this" {
  count         = var.create_bucket ? 1 : 0
  bucket        = local.bucket_name_final
  bucket_prefix = local.bucket_prefix_final
  force_destroy = var.force_destroy
  tags          = var.tags
}

# Object lock
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = var.create_bucket && var.object_lock_configuration != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.object_lock_configuration["rule"] != null ? [var.object_lock_configuration["rule"]] : []
    content {
      default_retention {
        mode  = rule.value.default_retention.mode
        days  = rule.value.default_retention.days
        years = rule.value.default_retention.years
      }
    }
  }
}

# ACL
resource "aws_s3_bucket_acl" "this" {
  count  = var.create_bucket && var.acl != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  acl    = var.acl
}

resource "aws_s3_bucket_acl" "grant" {
  count  = var.create_bucket && var.grant != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "access_control_policy" {
    for_each = var.grant != null ? [var.grant] : []
    content {
      dynamic "grant" {
        for_each = var.grant
        content {
          grantee {
            type  = grant.value.grantee.type
            id    = grant.value.grantee.id
            # email is not a valid argument; removed
          }
          permission = grant.value.permission
        }
      }
      owner {
        id = data.aws_caller_identity.current.account_id
      }
    }
  }
}

# Versioning
resource "aws_s3_bucket_versioning" "this" {
  count  = var.create_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  versioning_configuration {
    status     = try(var.versioning.enabled, false) ? "Enabled" : "Suspended"
    mfa_delete = try(var.versioning.mfa_delete, false) ? "Enabled" : "Disabled"
  }
}

# Logging
resource "aws_s3_bucket_logging" "this" {
  count  = var.create_bucket && local.logging_effective != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  target_bucket = local.logging_effective.target_bucket
  target_prefix = try(local.logging_effective.target_prefix, "")
}

# Website
resource "aws_s3_bucket_website_configuration" "this" {
  count  = var.create_bucket && var.website != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "index_document" {
    for_each = var.website["index_document"] != null ? [var.website["index_document"]] : []
    content {
      suffix = index_document.value.suffix
    }
  }

  dynamic "error_document" {
    for_each = var.website["error_document"] != null ? [var.website["error_document"]] : []
    content {
      key = error_document.value.key
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = var.website["redirect_all_requests_to"] != null ? [var.website["redirect_all_requests_to"]] : []
    content {
      host_name = redirect_all_requests_to.value.host_name
      protocol  = try(redirect_all_requests_to.value.protocol, null)
    }
  }

  dynamic "routing_rule" {
    for_each = try(var.website["routing_rules"], [])
    content {
      dynamic "redirect" {
        for_each = routing_rule.value.redirect != null ? [routing_rule.value.redirect] : []
        content {
          host_name       = try(redirect.value.host_name, null)
          http_redirect_code = try(redirect.value.http_redirect_code, null)
          protocol        = try(redirect.value.protocol, null)
          replace_key_prefix_with = try(redirect.value.replace_key_prefix_with, null)
          replace_key_with        = try(redirect.value.replace_key_with, null)
        }
      }
      dynamic "condition" {
        for_each = routing_rule.value.condition != null ? [routing_rule.value.condition] : []
        content {
          http_error_code_returned_equals = try(condition.value.http_error_code_returned_equals, null)
          key_prefix_equals               = try(condition.value.key_prefix_equals, null)
        }
      }
    }
  }
}

# CORS
resource "aws_s3_bucket_cors_configuration" "this" {
  count  = var.create_bucket && var.cors_rule != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rule
    content {
      allowed_headers = try(cors_rule.value.allowed_headers, [])
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, [])
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

# Transfer acceleration
resource "aws_s3_bucket_accelerate_configuration" "this" {
  count  = var.create_bucket && var.acceleration_status != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  status = var.acceleration_status
}

# Requester pays
resource "aws_s3_bucket_request_payment_configuration" "this" {
  count  = var.create_bucket && var.request_payer != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  payer  = var.request_payer
}

# Lifecycle rules
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = var.create_bucket && var.lifecycle_rule != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rule
    content {
      id     = try(rule.value.id, null)
      status = rule.value.status

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload, null) != null ? [rule.value.abort_incomplete_multipart_upload] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value.expiration, null) != null ? [rule.value.expiration] : []
        content {
          date                         = try(expiration.value.date, null)
          days                         = try(expiration.value.days, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transitions, [])
        content {
          date          = try(transition.value.date, null)
          days          = try(transition.value.days, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration, null) != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
          noncurrent_days           = noncurrent_version_expiration.value.noncurrent_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value.noncurrent_version_transitions, [])
        content {
          newer_noncurrent_versions = try(noncurrent_version_transition.value.newer_noncurrent_versions, null)
          noncurrent_days           = noncurrent_version_transition.value.noncurrent_days
          storage_class             = noncurrent_version_transition.value.storage_class
        }
      }

      filter {
        dynamic "and" {
          for_each = try(rule.value.filter.and, null) != null ? [rule.value.filter.and] : []
          content {
            prefix                   = try(and.value.prefix, null)
            tags                     = try(and.value.tags, null)
            object_size_greater_than = try(and.value.object_size_greater_than, null)
            object_size_less_than    = try(and.value.object_size_less_than, null)
          }
        }
        dynamic "tag" {
          for_each = try(rule.value.filter.tag, null) != null ? [rule.value.filter.tag] : []
          content {
            key   = tag.value.key
            value = tag.value.value
          }
        }
        prefix                    = try(rule.value.filter.prefix, null)
        object_size_greater_than = try(rule.value.filter.object_size_greater_than, null)
        object_size_less_than    = try(rule.value.filter.object_size_less_than, null)
      }
    }
  }
}

# Replication
resource "aws_s3_bucket_replication_configuration" "this" {
  count  = var.create_bucket && var.replication_configuration != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  role   = var.replication_configuration["role"]

  dynamic "rule" {
    for_each = var.replication_configuration["rules"]
    content {
      id       = try(rule.value.id, null)
      status   = rule.value.status
      priority = try(rule.value.priority, null)

      dynamic "delete_marker_replication" {
        for_each = try(rule.value.delete_marker_replication, null) != null ? [rule.value.delete_marker_replication] : []
        content {
          status = delete_marker_replication.value.status
        }
      }

      dynamic "destination" {
        for_each = [rule.value.destination]
        content {
          bucket        = destination.value.bucket
          storage_class = try(destination.value.storage_class, null)
          dynamic "encryption_configuration" {
            for_each = try(destination.value.encryption_configuration, null) != null ? [destination.value.encryption_configuration] : []
            content {
              replica_kms_key_id = encryption_configuration.value.replica_kms_key_id
            }
          }
          dynamic "access_control_translation" {
            for_each = try(destination.value.access_control_translation, null) != null ? [destination.value.access_control_translation] : []
            content {
              owner = access_control_translation.value.owner
            }
          }
          account = try(destination.value.account, null)
          metrics {
            status  = try(destination.value.metrics.status, "Enabled")
            event_threshold {
              minutes = try(destination.value.metrics.event_threshold.minutes, 15)
            }
          }
          replication_time {
            status = try(destination.value.replication_time.status, "Enabled")
            time {
              minutes = try(destination.value.replication_time.time.minutes, 15)
            }
          }
        }
      }

      dynamic "source_selection_criteria" {
        for_each = try(rule.value.source_selection_criteria, null) != null ? [rule.value.source_selection_criteria] : []
        content {
          dynamic "sse_kms_encrypted_objects" {
            for_each = try(source_selection_criteria.value.sse_kms_encrypted_objects, null) != null ? [source_selection_criteria.value.sse_kms_encrypted_objects] : []
            content {
              status = sse_kms_encrypted_objects.value.status
            }
          }
        }
      }

      dynamic "filter" {
        for_each = try(rule.value.filter, null) != null ? [rule.value.filter] : []
        content {
          prefix = try(filter.value.prefix, null)
          dynamic "tag" {
            for_each = try(filter.value.tag, null) != null ? [filter.value.tag] : []
            content {
              key   = tag.value.key
              value = tag.value.value
            }
          }
          dynamic "and" {
            for_each = try(filter.value.and, null) != null ? [filter.value.and] : []
            content {
              prefix = try(and.value.prefix, null)
              tags   = try(and.value.tags, null)
            }
          }
        }
      }
    }
  }
}

# Intelligent Tiering
resource "aws_s3_bucket_intelligent_tiering_configuration" "this" {
  count  = var.create_bucket && var.intelligent_tiering != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  name   = var.intelligent_tiering["name"]

  dynamic "tiering" {
    for_each = var.intelligent_tiering["tierings"]
    content {
      access_tier = tiering.value.access_tier
      days        = tiering.value.days
    }
  }

  filter {
    prefix = try(var.intelligent_tiering["filter"]["prefix"], null)
    tags   = try(var.intelligent_tiering["filter"]["tags"], null)
  }

  status = try(var.intelligent_tiering["status"], "Enabled")
}

# ------------------------------------------------------------------------------
# Bucket Policy (combined)
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "combined" {
  count = var.create_bucket && local.enable_bucket_policy ? 1 : 0

  # ELB access log delivery
  dynamic "statement" {
    for_each = var.attach_elb_log_delivery_policy ? [1] : []
    content {
      sid    = "ELBAccessLogDelivery"
      effect = "Allow"
      principals {
        type        = "Service"
        identifiers = ["delivery.logs.amazonaws.com", "logdelivery.elasticloadbalancing.amazonaws.com"]
      }
      actions = ["s3:PutObject"]
      resources = [
        "${local.bucket_arn}/*",
      ]
      condition {
        test     = "StringEquals"
        variable = "s3:x-amz-acl"
        values   = ["bucket-owner-full-control"]
      }
    }
  }

  # Deny insecure transport
  dynamic "statement" {
    for_each = var.deny_insecure_transport ? [1] : []
    content {
      sid    = "DenyInsecureTransport"
      effect = "Deny"
      principals {
        type        = "*"
        identifiers = ["*"]
      }
      actions = ["s3:*"]
      resources = [
        local.bucket_arn,
        "${local.bucket_arn}/*",
      ]
      condition {
        test     = "Bool"
        variable = "aws:SecureTransport"
        values   = ["false"]
      }
    }
  }

  # Deny TLS versions older than 1.2
  dynamic "statement" {
    for_each = var.deny_tls_versions_older_than_1_2 ? [1] : []
    content {
      sid    = "DenyTLSVersionsOlderThan1_2"
      effect = "Deny"
      principals {
        type        = "*"
        identifiers = ["*"]
      }
      actions = ["s3:*"]
      resources = [
        local.bucket_arn,
        "${local.bucket_arn}/*",
      ]
      condition {
        test     = "NumericLessThan"
        variable = "s3:TlsVersion"
        values   = ["1.2"]
      }
    }
  }

  # User-supplied policy – set directly as an argument, not a block
  source_policy_documents = var.attach_user_supplied_policy && var.user_supplied_policy != null ? [var.user_supplied_policy] : []
}

resource "aws_s3_bucket_policy" "this" {
  count  = var.create_bucket && local.enable_bucket_policy ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.combined[0].json
}

# ------------------------------------------------------------------------------
# Public Access Block (applied after bucket policy to avoid conflicts)
# ------------------------------------------------------------------------------

resource "aws_s3_bucket_public_access_block" "this" {
  count  = var.create_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true

  depends_on = [aws_s3_bucket_policy.this]
}

# ------------------------------------------------------------------------------
# Ownership Controls (applied after bucket policy)
# ------------------------------------------------------------------------------

resource "aws_s3_bucket_ownership_controls" "this" {
  count  = var.create_bucket && var.object_ownership != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.object_ownership
  }

  depends_on = [aws_s3_bucket_policy.this]
}

# ------------------------------------------------------------------------------
# Server-side Encryption
# ------------------------------------------------------------------------------

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count  = var.create_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = local.sse_config
    content {
      apply_server_side_encryption_by_default {
        sse_algorithm     = rule.value.rule.apply_server_side_encryption_by_default.sse_algorithm
        kms_master_key_id = try(rule.value.rule.apply_server_side_encryption_by_default.kms_master_key_id, null)
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Data Source for caller identity
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "bucket_id" {
  description = "ID of the S3 bucket."
  value       = var.create_bucket ? aws_s3_bucket.this[0].id : ""
}

output "bucket_arn" {
  description = "ARN of the S3 bucket."
  value       = var.create_bucket ? aws_s3_bucket.this[0].arn : ""
}

output "bucket_domain_name" {
  description = "Domain name of the S3 bucket."
  value       = var.create_bucket ? aws_s3_bucket.this[0].bucket_domain_name : ""
}

output "kms_key_arn" {
  description = "ARN of the KMS key (if created)."
  value       = local.create_kms ? aws_kms_key.this[0].arn : ""
}

output "logging_bucket_id" {
  description = "ID of the default logging bucket (if created)."
  value       = local.create_default_logging ? aws_s3_bucket.log_bucket[0].id : ""
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Input variables
variable "target_stack" {
  description = "Target stack name"
  type        = string
  default     = "benchmark"
}

variable "stack_githash" {
  description = "Short git hash of the stack"
  type        = string
  default     = "benchmark0000"
}

variable "stack_githash_long" {
  description = "Long git hash placeholder"
  type        = string
  default     = "benchmark0000000000000000000000000"
}

variable "stack_s3_bucket" {
  description = "S3 bucket for stack artifacts and datasets"
  type        = string
  default     = "benchmark-stack-bucket"
}

variable "dataset_s3_object_key" {
  description = "Object key for dataset CSV"
  type        = string
  default     = "dataset.csv"
}

variable "destigmatized_dataset_s3_object_key" {
  description = "Object key for destigmatized dataset CSV"
  type        = string
  default     = "destigmatized_dataset.csv"
}

variable "genomic_dataset_s3_object_key" {
  description = "Object key for genomic dataset CSV"
  type        = string
  default     = "genomic_dataset.csv"
}

# Locals for role names and prefixes
locals {
  role_prefixes = [
    "wildfly-deployment-s3",
    "httpd-deployment-s3",
    "auth-hpds-deployment-s3",
    "open-hpds-deployment-s3",
    "dictionary-deployment-s3"
  ]

  role_names = {
    for prefix in local.role_prefixes :
    prefix => "${prefix}-${var.target_stack}-${var.stack_githash}"
  }

  # Map each role to a short prefix for S3 paths (e.g., "wildfly", "httpd", etc.)
  s3_path_prefixes = {
    wildfly-deployment-s3    = "wildfly"
    httpd-deployment-s3      = "httpd"
    auth-hpds-deployment-s3  = "auth-hpds"
    open-hpds-deployment-s3  = "open-hpds"
    dictionary-deployment-s3 = "dictionary"
  }

  # S3 ARN for the bucket
  s3_bucket_arn = "arn:aws:s3:::${var.stack_s3_bucket}"

  # Dataset object keys list
  dataset_keys = [
    var.dataset_s3_object_key,
    var.destigmatized_dataset_s3_object_key,
    var.genomic_dataset_s3_object_key
  ]
}

# IAM role for each prefix
resource "aws_iam_role" "this" {
  for_each = local.role_names

  name = each.value

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name        = each.value
    Stack       = var.target_stack
    Githash     = var.stack_githash
    GithashLong = var.stack_githash_long
  }
}

# Attach CloudWatchAgentServerPolicy
resource "aws_iam_role_policy_attachment" "cloudwatch" {
  for_each = aws_iam_role.this

  role       = each.value.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy"
}

# Attach AmazonSSMManagedInstanceCore
resource "aws_iam_role_policy_attachment" "ssm" {
  for_each = aws_iam_role.this

  role       = each.value.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

# Inline policy for each role
resource "aws_iam_role_policy" "inline" {
  for_each = aws_iam_role.this

  name   = "${each.value.name}-inline"
  role   = each.value.name
  policy = data.aws_iam_policy_document.inline[each.key].json
}

# Policy document for inline policy
data "aws_iam_policy_document" "inline" {
  for_each = aws_iam_role.this

  # Statement 1: EC2 CreateTags on instance resources
  statement {
    sid    = "EC2CreateTags"
    effect = "Allow"
    actions = [
      "ec2:CreateTags"
    ]
    resources = [
      "arn:aws:ec2:*:*:instance/*"
    ]
  }

  # Statement 2: CloudWatch PutMetricData globally
  statement {
    sid    = "CloudWatchPutMetricData"
    effect = "Allow"
    actions = [
      "cloudwatch:PutMetricData"
    ]
    resources = ["*"]
  }

  # Statement 3: S3 ListBucket on the deployment bucket
  statement {
    sid    = "S3ListBucket"
    effect = "Allow"
    actions = [
      "s3:ListBucket"
    ]
    resources = [local.s3_bucket_arn]
  }

  # Statement 4: S3 GetObject on artifacts, config, SSL, datasets, and security tools
  statement {
    sid    = "S3GetObject"
    effect = "Allow"
    actions = [
      "s3:GetObject"
    ]
    resources = concat(
      # Artifacts for this role's tier
      ["${local.s3_bucket_arn}/artifacts/${local.s3_path_prefixes[each.key]}/*"],
      # Configurations for this role's tier
      ["${local.s3_bucket_arn}/config/${local.s3_path_prefixes[each.key]}/*"],
      # SSL certificates for this role's tier
      ["${local.s3_bucket_arn}/ssl/${local.s3_path_prefixes[each.key]}/*"],
      # Common security tools (shared across all roles)
      ["${local.s3_bucket_arn}/security-tools/*"],
      # Datasets: all roles get access to the specific dataset object keys
      [for key in local.dataset_keys : "${local.s3_bucket_arn}/${key}"]
    )
  }
}

# Instance profiles
resource "aws_iam_instance_profile" "this" {
  for_each = aws_iam_role.this

  name = each.value.name
  role = each.value.name

  tags = {
    Name        = each.value.name
    Stack       = var.target_stack
    Githash     = var.stack_githash
    GithashLong = var.stack_githash_long
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

data "aws_caller_identity" "current" {}

variable "create_module" {
  description = "Whether to create any resources."
  type        = bool
  default     = true
}

variable "create_security_group" {
  description = "Whether to create a new security group or use an existing one."
  type        = bool
  default     = true
}

variable "vpc_id" {
  description = "ID of the VPC in which to create the new security group. Leave empty to have the module create a VPC."
  type        = string
  default     = ""
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC created by this module when vpc_id is not supplied."
  type        = string
  default     = "10.0.0.0/16"
}

variable "existing_security_group_id" {
  description = "ID of the existing security group to which rules are added when create_security_group is false."
  type        = string
  default     = ""
}

variable "ingress_rules" {
  description = "Ingress rules for the newly created security group."
  type = list(object({
    protocol                 = string
    from_port                = number
    to_port                  = number
    ipv4_cidr                = optional(string)
    ipv6_cidr                = optional(string)
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
    description              = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.ingress_rules :
      length([
        for source in [
          rule.ipv4_cidr,
          rule.ipv6_cidr,
          rule.source_security_group_id,
          rule.prefix_list_id
        ] : source if source != null && source != ""
      ]) == 1
    ])
    error_message = "Each ingress rule must specify exactly one of ipv4_cidr, ipv6_cidr, source_security_group_id, or prefix_list_id."
  }

  validation {
    condition = alltrue([
      for rule in var.ingress_rules : rule.from_port <= rule.to_port
    ])
    error_message = "In each ingress rule, from_port must be less than or equal to to_port."
  }
}

variable "egress_rules" {
  description = "Egress rules for the newly created security group."
  type = list(object({
    protocol                 = string
    from_port                = number
    to_port                  = number
    ipv4_cidr                = optional(string)
    ipv6_cidr                = optional(string)
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
    description              = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.egress_rules :
      length([
        for source in [
          rule.ipv4_cidr,
          rule.ipv6_cidr,
          rule.source_security_group_id,
          rule.prefix_list_id
        ] : source if source != null && source != ""
      ]) == 1
    ])
    error_message = "Each egress rule must specify exactly one of ipv4_cidr, ipv6_cidr, source_security_group_id, or prefix_list_id."
  }

  validation {
    condition = alltrue([
      for rule in var.egress_rules : rule.from_port <= rule.to_port
    ])
    error_message = "In each egress rule, from_port must be less than or equal to to_port."
  }
}

variable "existing_ingress_rules" {
  description = "Ingress rules to add to the existing security group."
  type = list(object({
    protocol                 = string
    from_port                = number
    to_port                  = number
    ipv4_cidr                = optional(string)
    ipv6_cidr                = optional(string)
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
    description              = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.existing_ingress_rules :
      length([
        for source in [
          rule.ipv4_cidr,
          rule.ipv6_cidr,
          rule.source_security_group_id,
          rule.prefix_list_id
        ] : source if source != null && source != ""
      ]) == 1
    ])
    error_message = "Each existing ingress rule must specify exactly one of ipv4_cidr, ipv6_cidr, source_security_group_id, or prefix_list_id."
  }

  validation {
    condition = alltrue([
      for rule in var.existing_ingress_rules : rule.from_port <= rule.to_port
    ])
    error_message = "In each existing ingress rule, from_port must be less than or equal to to_port."
  }
}

variable "existing_egress_rules" {
  description = "Egress rules to add to the existing security group."
  type = list(object({
    protocol                 = string
    from_port                = number
    to_port                  = number
    ipv4_cidr                = optional(string)
    ipv6_cidr                = optional(string)
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
    description              = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.existing_egress_rules :
      length([
        for source in [
          rule.ipv4_cidr,
          rule.ipv6_cidr,
          rule.source_security_group_id,
          rule.prefix_list_id
        ] : source if source != null && source != ""
      ]) == 1
    ])
    error_message = "Each existing egress rule must specify exactly one of ipv4_cidr, ipv6_cidr, source_security_group_id, or prefix_list_id."
  }

  validation {
    condition = alltrue([
      for rule in var.existing_egress_rules : rule.from_port <= rule.to_port
    ])
    error_message = "In each existing egress rule, from_port must be less than or equal to to_port."
  }
}

variable "default_egress_cidr_blocks" {
  description = "CIDR blocks for the default egress rule applied when no egress_rules are provided for a new security group."
  type        = list(string)
  default     = ["10.0.0.0/8"]

  validation {
    condition = length(var.default_egress_cidr_blocks) > 0 && alltrue([
      for cidr in var.default_egress_cidr_blocks :
      cidr != null && cidr != "" && cidr != "0.0.0.0/0" && cidr != "::/0"
    ])
    error_message = "default_egress_cidr_blocks must be a non-empty list of non-wildcard CIDR blocks."
  }
}

variable "default_egress_description" {
  description = "Description applied to the default egress rule."
  type        = string
  default     = "Default outbound rule restricted to private IPv4 ranges"
}

variable "create_prefix_list" {
  description = "Whether to create a customer-managed prefix list."
  type        = bool
  default     = false
}

variable "existing_prefix_list_ids" {
  description = "IDs of existing prefix lists to reference in security group rules. When non-empty, no new prefix list is created."
  type        = list(string)
  default     = []

  validation {
    condition     = alltrue([for id in var.existing_prefix_list_ids : id != null && id != ""])
    error_message = "All existing_prefix_list_ids values must be non-empty strings."
  }
}

variable "prefix_list_name" {
  description = "Name of the customer-managed prefix list."
  type        = string
  default     = "terraform-managed-prefix-list"
}

variable "address_family" {
  description = "Address family of the prefix list."
  type        = string
  default     = "IPv4"

  validation {
    condition     = contains(["IPv4", "IPv6"], var.address_family)
    error_message = "address_family must be either 'IPv4' or 'IPv6'."
  }
}

variable "max_entries" {
  description = "Maximum number of entries for the prefix list."
  type        = number
  default     = 10

  validation {
    condition     = var.max_entries != null && var.max_entries > 0
    error_message = "max_entries must be greater than zero."
  }
}

variable "prefix_list_entries" {
  description = "CIDR entries for the prefix list."
  type = list(object({
    cidr        = string
    description = optional(string, "")
  }))
  default = []

  validation {
    condition     = alltrue([for entry in var.prefix_list_entries : entry.cidr != null && entry.cidr != ""])
    error_message = "Each prefix list entry must specify a non-empty cidr."
  }
}

variable "flow_logs_log_group_name" {
  description = "Name of the CloudWatch Log Group used for VPC Flow Logs."
  type        = string
  default     = "terraform-vpc-flow-logs"
}

locals {
  effective_vpc_id  = var.vpc_id != "" ? var.vpc_id : try(aws_vpc.this[0].id, "")
  security_group_id = try(aws_security_group.this[0].id, var.existing_security_group_id)
}

resource "aws_vpc" "this" {
  count = var.create_module && var.create_security_group && var.vpc_id == "" ? 1 : 0

  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "terraform-vpc"
  }
}

resource "aws_kms_key" "flow_logs" {
  count = var.create_module && var.create_security_group && var.vpc_id == "" ? 1 : 0

  description             = "Customer managed key for VPC Flow Logs CloudWatch Log Group encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountManagement"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogsForFlowLogs"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

data "aws_partition" "current" {}

data "aws_region" "current" {}

resource "aws_kms_alias" "flow_logs" {
  count = var.create_module && var.create_security_group && var.vpc_id == "" ? 1 : 0

  name_prefix   = "alias/terraform-vpc-flow-logs-"
  target_key_id = aws_kms_key.flow_logs[0].key_id
}

resource "aws_cloudwatch_log_group" "flow_logs" {
  count = var.create_module && var.create_security_group && var.vpc_id == "" ? 1 : 0

  name              = var.flow_logs_log_group_name
  kms_key_id        = aws_kms_key.flow_logs[0].arn
  retention_in_days = 30

  tags = {
    Name = var.flow_logs_log_group_name
  }
}

resource "aws_iam_role" "flow_logs" {
  count = var.create_module && var.create_security_group && var.vpc_id == "" ? 1 : 0

  name_prefix = "terraform-vpc-flow-logs-"
  description = "IAM role used by VPC Flow Logs to deliver logs to CloudWatch Logs."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "flow_logs" {
  count = var.create_module && var.create_security_group && var.vpc_id == "" ? 1 : 0

  name_prefix = "flow-logs-"
  role        = aws_iam_role.flow_logs[0].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          aws_cloudwatch_log_group.flow_logs[0].arn,
          "${aws_cloudwatch_log_group.flow_logs[0].arn}:*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = [aws_kms_key.flow_logs[0].arn]
      }
    ]
  })
}

resource "aws_flow_log" "this" {
  count = var.create_module && var.create_security_group && var.vpc_id == "" ? 1 : 0

  vpc_id               = aws_vpc.this[0].id
  log_destination      = aws_cloudwatch_log_group.flow_logs[0].arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.flow_logs[0].arn
  traffic_type         = "ALL"

  tags = {
    Name = "terraform-vpc-flow-logs"
  }
}

resource "aws_security_group" "this" {
  count = var.create_module && var.create_security_group ? 1 : 0

  name_prefix            = "terraform-sg-"
  description            = "Security group created by Terraform configuration"
  vpc_id                 = local.effective_vpc_id
  revoke_rules_on_delete = true

  lifecycle {
    create_before_destroy = true

    precondition {
      condition     = local.effective_vpc_id != null && local.effective_vpc_id != ""
      error_message = "vpc_id must be provided or a VPC must be created when create_module and create_security_group are true."
    }
  }
}

resource "aws_security_group_rule" "default_egress" {
  count = var.create_module && var.create_security_group && length(var.egress_rules) == 0 ? 1 : 0

  type              = "egress"
  security_group_id = local.security_group_id
  protocol          = "-1"
  from_port         = 0
  to_port           = 0
  cidr_blocks       = var.default_egress_cidr_blocks
  description       = var.default_egress_description
}

resource "aws_security_group_rule" "ingress" {
  for_each = var.create_module && var.create_security_group ? { for idx, rule in var.ingress_rules : tostring(idx) => rule } : {}

  type                     = "ingress"
  security_group_id        = local.security_group_id
  protocol                 = each.value.protocol
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  cidr_blocks              = each.value.ipv4_cidr != null ? [each.value.ipv4_cidr] : null
  ipv6_cidr_blocks         = each.value.ipv6_cidr != null ? [each.value.ipv6_cidr] : null
  source_security_group_id = each.value.source_security_group_id != null ? each.value.source_security_group_id : null
  prefix_list_ids          = each.value.prefix_list_id != null ? [each.value.prefix_list_id] : null
  description              = each.value.description != null && each.value.description != "" ? each.value.description : "${each.value.protocol} ${each.value.from_port}-${each.value.to_port}"
}

resource "aws_security_group_rule" "egress" {
  for_each = var.create_module && var.create_security_group ? { for idx, rule in var.egress_rules : tostring(idx) => rule } : {}

  type                     = "egress"
  security_group_id        = local.security_group_id
  protocol                 = each.value.protocol
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  cidr_blocks              = each.value.ipv4_cidr != null ? [each.value.ipv4_cidr] : null
  ipv6_cidr_blocks         = each.value.ipv6_cidr != null ? [each.value.ipv6_cidr] : null
  source_security_group_id = each.value.source_security_group_id != null ? each.value.source_security_group_id : null
  prefix_list_ids          = each.value.prefix_list_id != null ? [each.value.prefix_list_id] : null
  description              = each.value.description != null && each.value.description != "" ? each.value.description : "${each.value.protocol} ${each.value.from_port}-${each.value.to_port}"
}

resource "aws_security_group_rule" "existing_ingress" {
  for_each = var.create_module && !var.create_security_group ? { for idx, rule in var.existing_ingress_rules : tostring(idx) => rule } : {}

  type                     = "ingress"
  security_group_id        = local.security_group_id
  protocol                 = each.value.protocol
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  cidr_blocks              = each.value.ipv4_cidr != null ? [each.value.ipv4_cidr] : null
  ipv6_cidr_blocks         = each.value.ipv6_cidr != null ? [each.value.ipv6_cidr] : null
  source_security_group_id = each.value.source_security_group_id != null ? each.value.source_security_group_id : null
  prefix_list_ids          = each.value.prefix_list_id != null ? [each.value.prefix_list_id] : null
  description              = each.value.description != null && each.value.description != "" ? each.value.description : "${each.value.protocol} ${each.value.from_port}-${each.value.to_port}"

  lifecycle {
    precondition {
      condition     = var.existing_security_group_id != null && var.existing_security_group_id != ""
      error_message = "existing_security_group_id must be provided when adding rules to an existing security group."
    }
  }
}

resource "aws_security_group_rule" "existing_egress" {
  for_each = var.create_module && !var.create_security_group ? { for idx, rule in var.existing_egress_rules : tostring(idx) => rule } : {}

  type                     = "egress"
  security_group_id        = local.security_group_id
  protocol                 = each.value.protocol
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  cidr_blocks              = each.value.ipv4_cidr != null ? [each.value.ipv4_cidr] : null
  ipv6_cidr_blocks         = each.value.ipv6_cidr != null ? [each.value.ipv6_cidr] : null
  source_security_group_id = each.value.source_security_group_id != null ? each.value.source_security_group_id : null
  prefix_list_ids          = each.value.prefix_list_id != null ? [each.value.prefix_list_id] : null
  description              = each.value.description != null && each.value.description != "" ? each.value.description : "${each.value.protocol} ${each.value.from_port}-${each.value.to_port}"

  lifecycle {
    precondition {
      condition     = var.existing_security_group_id != null && var.existing_security_group_id != ""
      error_message = "existing_security_group_id must be provided when adding rules to an existing security group."
    }
  }
}

resource "aws_ec2_managed_prefix_list" "this" {
  count = var.create_module && var.create_prefix_list && length(var.existing_prefix_list_ids) == 0 ? 1 : 0

  name           = var.prefix_list_name
  address_family = var.address_family
  max_entries    = var.max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = entry.value.description == null ? "" : entry.value.description
    }
  }

  lifecycle {
    precondition {
      condition     = length(var.prefix_list_entries) > 0
      error_message = "prefix_list_entries must be provided when creating a new prefix list and no existing_prefix_list_ids are supplied."
    }

    precondition {
      condition     = var.max_entries >= length(var.prefix_list_entries)
      error_message = "max_entries must be greater than or equal to the number of prefix_list_entries."
    }
  }
}

output "security_group_id" {
  description = "ID of the security group created or referenced by this configuration."
  value       = local.security_group_id
}

output "prefix_list_id" {
  description = "ID of the customer-managed prefix list, if one was created."
  value       = try(aws_ec2_managed_prefix_list.this[0].id, null)
}

terraform {
  required_version = "~> 1.6"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "project" {
  description = "Project name used as a prefix for resources"
  type        = string
  default     = "Cv-React-App"
}

data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# KMS Customer Managed Key for S3 encryption
# ------------------------------------------------------------------------------
resource "aws_kms_key" "s3_cmk" {
  description             = "CMK for S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# S3 bucket for CodePipeline artifacts (lowercase name)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "codepipeline_artifacts" {
  bucket = lower("${var.project}-codepipeline-artifacts-bucket")
}

resource "aws_s3_bucket_public_access_block" "codepipeline_artifacts" {
  bucket                  = aws_s3_bucket.codepipeline_artifacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "codepipeline_artifacts" {
  bucket = aws_s3_bucket.codepipeline_artifacts.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_cmk.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "codepipeline_artifacts" {
  bucket = aws_s3_bucket.codepipeline_artifacts.id
  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------------------
# S3 bucket for access logs (lowercase name)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "access_logs" {
  bucket = lower("${var.project}-access-logs-bucket")
}

resource "aws_s3_bucket_public_access_block" "access_logs" {
  bucket                  = aws_s3_bucket.access_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------------------
# Enable logging on artifacts bucket
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_logging" "codepipeline_artifacts" {
  bucket        = aws_s3_bucket.codepipeline_artifacts.id
  target_bucket = aws_s3_bucket.access_logs.id
  target_prefix = "codepipeline/"
}

# ------------------------------------------------------------------------------
# Bucket policy for access logs (replaces ACL, grants write to log delivery)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_policy" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ServerAccessLogsPolicy"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.access_logs.arn}/*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.codepipeline_artifacts.arn
          }
        }
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Custom IAM policy replacing AmazonS3FullAccess (no s3:* action)
# ------------------------------------------------------------------------------
resource "aws_iam_policy" "s3_full_access_custom" {
  name        = "${var.project}-s3-full-access-custom"
  description = "Custom policy granting full S3 access using individual actions instead of s3:*"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3FullAccess"
        Effect = "Allow"
        Action = [
          "s3:AbortMultipartUpload",
          "s3:CreateBucket",
          "s3:DeleteBucket",
          "s3:DeleteBucketPolicy",
          "s3:DeleteBucketWebsite",
          "s3:DeleteObject",
          "s3:DeleteObjectTagging",
          "s3:DeleteObjectVersion",
          "s3:DeleteObjectVersionTagging",
          "s3:GetAccelerateConfiguration",
          "s3:GetBucketAcl",
          "s3:GetBucketCORS",
          "s3:GetBucketLocation",
          "s3:GetBucketLogging",
          "s3:GetBucketNotification",
          "s3:GetBucketObjectLockConfiguration",
          "s3:GetBucketPolicy",
          "s3:GetBucketRequestPayment",
          "s3:GetBucketTagging",
          "s3:GetBucketVersioning",
          "s3:GetBucketWebsite",
          "s3:GetLifecycleConfiguration",
          "s3:GetObject",
          "s3:GetObjectAcl",
          "s3:GetObjectLegalHold",
          "s3:GetObjectRetention",
          "s3:GetObjectTagging",
          "s3:GetObjectTorrent",
          "s3:GetObjectVersion",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionLegalHold",
          "s3:GetObjectVersionRetention",
          "s3:GetObjectVersionTagging",
          "s3:GetObjectVersionTorrent",
          "s3:GetReplicationConfiguration",
          "s3:ListAllMyBuckets",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:ListBucketVersions",
          "s3:ListMultipartUploadParts",
          "s3:PutAccelerateConfiguration",
          "s3:PutBucketAcl",
          "s3:PutBucketCORS",
          "s3:PutBucketLogging",
          "s3:PutBucketNotification",
          "s3:PutBucketObjectLockConfiguration",
          "s3:PutBucketPolicy",
          "s3:PutBucketRequestPayment",
          "s3:PutBucketTagging",
          "s3:PutBucketVersioning",
          "s3:PutBucketWebsite",
          "s3:PutLifecycleConfiguration",
          "s3:PutObject",
          "s3:PutObjectAcl",
          "s3:PutObjectLegalHold",
          "s3:PutObjectRetention",
          "s3:PutObjectTagging",
          "s3:PutObjectVersionAcl",
          "s3:PutObjectVersionLegalHold",
          "s3:PutObjectVersionRetention",
          "s3:PutObjectVersionTagging",
          "s3:PutReplicationConfiguration",
          "s3:RestoreObject"
        ]
        Resource = "*"
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# IAM: EC2 CodeDeploy role
# ------------------------------------------------------------------------------
resource "aws_iam_role" "ec2_codedeploy" {
  name = "${var.project}_ec2_codedeploy_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_AmazonEC2RoleforAWSCodeDeploy" {
  role       = aws_iam_role.ec2_codedeploy.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2RoleforAWSCodeDeploy"
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_AmazonEC2FullAccess" {
  role       = aws_iam_role.ec2_codedeploy.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2FullAccess"
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_s3_full_access_custom" {
  role       = aws_iam_role.ec2_codedeploy.name
  policy_arn = aws_iam_policy.s3_full_access_custom.arn
}

resource "aws_iam_instance_profile" "ec2_codedeploy" {
  name = "${var.project}_ec2_codedeploy_profile"
  role = aws_iam_role.ec2_codedeploy.name
}

# ------------------------------------------------------------------------------
# IAM: CodeDeploy service role
# ------------------------------------------------------------------------------
resource "aws_iam_role" "codedeploy_service" {
  name = "${var.project}_codedeploy_service_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codedeploy.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codedeploy_service_AWSCodeDeployRole" {
  role       = aws_iam_role.codedeploy_service.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeDeployRole"
}

resource "aws_iam_role_policy_attachment" "codedeploy_service_s3_full_access_custom" {
  role       = aws_iam_role.codedeploy_service.name
  policy_arn = aws_iam_policy.s3_full_access_custom.arn
}

# ------------------------------------------------------------------------------
# IAM: EC2 CloudWatch Agent role
# ------------------------------------------------------------------------------
resource "aws_iam_role" "cloudwatch_agent" {
  name = "${var.project}_cloudwatch_agent_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "cloudwatch_agent_CloudWatchAgentServerPolicy" {
  role       = aws_iam_role.cloudwatch_agent.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_role_policy_attachment" "cloudwatch_agent_s3_full_access_custom" {
  role       = aws_iam_role.cloudwatch_agent.name
  policy_arn = aws_iam_policy.s3_full_access_custom.arn
}

resource "aws_iam_instance_profile" "cloudwatch_agent" {
  name = "${var.project}_cloudwatch_agent_profile"
  role = aws_iam_role.cloudwatch_agent.name
}

# ------------------------------------------------------------------------------
# IAM: CodeBuild role
# ------------------------------------------------------------------------------
resource "aws_iam_role" "codebuild" {
  name = "CodeBuildRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_s3_full_access_custom" {
  role       = aws_iam_role.codebuild.name
  policy_arn = aws_iam_policy.s3_full_access_custom.arn
}

resource "aws_iam_role_policy" "codebuild_inline" {
  name = "CodeBuildInlinePolicy"
  role = aws_iam_role.codebuild.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid = "LoggingPermissions"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      },
      {
        Sid = "S3ArtifactAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.codepipeline_artifacts.arn,
          "${aws_s3_bucket.codepipeline_artifacts.arn}/*"
        ]
      },
      {
        Sid = "CodeBuildReportCreation"
        Effect = "Allow"
        Action = [
          "codebuild:CreateReportGroup",
          "codebuild:CreateReport",
          "codebuild:BatchPutTestCases",
          "codebuild:BatchPutCodeCoverages"
        ]
        Resource = "*"
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# IAM: CodePipeline role
# ------------------------------------------------------------------------------
resource "aws_iam_role" "codepipeline" {
  name = "CodePipelineRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codepipeline.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "codepipeline_inline" {
  name = "CodePipelineInlinePolicy"
  role = aws_iam_role.codepipeline.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeStarConnections"
        Effect = "Allow"
        Action = ["codestar-connections:*"]
        Resource = "*"
      },
      {
        Sid    = "S3"
        Effect = "Allow"
        Action = [
          "s3:AbortMultipartUpload",
          "s3:CreateBucket",
          "s3:DeleteBucket",
          "s3:DeleteBucketPolicy",
          "s3:DeleteBucketWebsite",
          "s3:DeleteObject",
          "s3:DeleteObjectTagging",
          "s3:DeleteObjectVersion",
          "s3:DeleteObjectVersionTagging",
          "s3:GetAccelerateConfiguration",
          "s3:GetBucketAcl",
          "s3:GetBucketCORS",
          "s3:GetBucketLocation",
          "s3:GetBucketLogging",
          "s3:GetBucketNotification",
          "s3:GetBucketObjectLockConfiguration",
          "s3:GetBucketPolicy",
          "s3:GetBucketRequestPayment",
          "s3:GetBucketTagging",
          "s3:GetBucketVersioning",
          "s3:GetBucketWebsite",
          "s3:GetLifecycleConfiguration",
          "s3:GetObject",
          "s3:GetObjectAcl",
          "s3:GetObjectLegalHold",
          "s3:GetObjectRetention",
          "s3:GetObjectTagging",
          "s3:GetObjectTorrent",
          "s3:GetObjectVersion",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionLegalHold",
          "s3:GetObjectVersionRetention",
          "s3:GetObjectVersionTagging",
          "s3:GetObjectVersionTorrent",
          "s3:GetReplicationConfiguration",
          "s3:ListAllMyBuckets",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:ListBucketVersions",
          "s3:ListMultipartUploadParts",
          "s3:PutAccelerateConfiguration",
          "s3:PutBucketAcl",
          "s3:PutBucketCORS",
          "s3:PutBucketLogging",
          "s3:PutBucketNotification",
          "s3:PutBucketObjectLockConfiguration",
          "s3:PutBucketPolicy",
          "s3:PutBucketRequestPayment",
          "s3:PutBucketTagging",
          "s3:PutBucketVersioning",
          "s3:PutBucketWebsite",
          "s3:PutLifecycleConfiguration",
          "s3:PutObject",
          "s3:PutObjectAcl",
          "s3:PutObjectLegalHold",
          "s3:PutObjectRetention",
          "s3:PutObjectTagging",
          "s3:PutObjectVersionAcl",
          "s3:PutObjectVersionLegalHold",
          "s3:PutObjectVersionRetention",
          "s3:PutObjectVersionTagging",
          "s3:PutReplicationConfiguration",
          "s3:RestoreObject"
        ]
        Resource = [
          aws_s3_bucket.codepipeline_artifacts.arn,
          "${aws_s3_bucket.codepipeline_artifacts.arn}/*"
        ]
      },
      {
        Sid    = "CodeCommit"
        Effect = "Allow"
        Action = ["codecommit:*"]
        Resource = "*"
      },
      {
        Sid    = "CodeDeploy"
        Effect = "Allow"
        Action = ["codedeploy:*"]
        Resource = "*"
      },
      {
        Sid    = "Lambda"
        Effect = "Allow"
        Action = ["lambda:*"]
        Resource = "*"
      },
      {
        Sid    = "CodeBuild"
        Effect = "Allow"
        Action = ["codebuild:*"]
        Resource = "*"
      },
      {
        Sid    = "CloudFormation"
        Effect = "Allow"
        Action = ["cloudformation:*"]
        Resource = "*"
      },
      {
        Sid    = "IAM"
        Effect = "Allow"
        Action = ["iam:*"]
        Resource = "*"
      },
      {
        Sid    = "EC2"
        Effect = "Allow"
        Action = ["ec2:*"]
        Resource = "*"
      },
      {
        Sid    = "SNS"
        Effect = "Allow"
        Action = ["sns:*"]
        Resource = "*"
      },
      {
        Sid    = "SQS"
        Effect = "Allow"
        Action = ["sqs:*"]
        Resource = "*"
      },
      {
        Sid    = "CloudWatch"
        Effect = "Allow"
        Action = ["cloudwatch:*", "logs:*", "events:*"]
        Resource = "*"
      }
    ]
  })
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Environment name for tagging resources"
  type        = string
  default     = "dev"
}

locals {
  base_tags = {
    Environment = var.environment
  }
}

# KMS key for DynamoDB encryption
resource "aws_kms_key" "dynamo_db_kms" {
  description         = "Customer-managed KMS key for DynamoDB tables"
  enable_key_rotation = true
  tags = merge(local.base_tags, { Name = "dynamodb-cmk" })
}

# ──────────────────────────────────────────────
# DynamoDB Tables
# ──────────────────────────────────────────────

resource "aws_dynamodb_table" "near_app_actions_mapping" {
  name         = "near-app-actions-mapping"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "appId"

  attribute {
    name = "appId"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.dynamo_db_kms.arn
  }

  tags = merge(local.base_tags, { Name = "near-app-actions-mapping" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_app_actions_master" {
  name         = "near-app-actions-master"
  billing_mode = "PAY_PER_REQUEST"
