terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

variable "admin_cidr_block" {
  description = "CIDR block allowed for SSH access"
  type        = string
  default     = "10.0.0.0/8"
}

variable "environment" {
  description = "Environment tag"
  type        = string
  default     = "chaos"
}

variable "project" {
  description = "Project tag"
  type        = string
  default     = "fis-chaos"
}

locals {
  name_prefix = "${var.project}-${var.environment}"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "ecs_optimized" {
  most_recent = true
  owners      = ["amazon"]
  filter {
    name   = "name"
    values = ["amzn2-ami-ecs-hvm-*-x86_64-ebs"]
  }
  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

data "aws_caller_identity" "current" {}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "random_id" "delivery_suffix" {
  byte_length = 4
}

resource "tls_private_key" "admin" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name        = "${local.name_prefix}-vpc"
    Environment = var.environment
    Project     = var.project
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false
  tags = {
    Name        = "${local.name_prefix}-subnet"
    Environment = var.environment
    Project     = var.project
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name        = "${local.name_prefix}-igw"
    Environment = var.environment
    Project     = var.project
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = {
    Name        = "${local.name_prefix}-rt-public"
    Environment = var.environment
    Project     = var.project
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "ssh" {
  name        = "${local.name_prefix}-ssh"
  description = "Allow SSH inbound and VPC internal traffic"
  vpc_id      = aws_vpc.main.id
  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr_block]
    description = "SSH from admin CIDR"
  }
  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
    description = "Allow all traffic from VPC CIDR (for VPC endpoints)"
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
    description = "Allow all outbound traffic (required for EC2 health checks)"
  }
  tags = {
    Name        = "${local.name_prefix}-sg-ssh"
    Environment = var.environment
    Project     = var.project
  }
}

resource "aws_key_pair" "admin" {
  key_name_prefix = "${local.name_prefix}-key-"
  public_key      = tls_private_key.admin.public_key_openssh
  tags = {
    Name        = "${local.name_prefix}-key"
    Environment = var.environment
    Project     = var.project
  }
}

resource "aws_launch_template" "fis" {
  name_prefix   = "${local.name_prefix}-lt-"
  image_id      = data.aws_ami.ecs_optimized.id
  instance_type = "t3.micro"
  key_name      = aws_key_pair.admin.key_name
  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }
  network_interfaces {
    associate_public_ip_address = true
    delete_on_termination       = true
    security_groups             = [aws_security_group.ssh.id]
  }
  iam_instance_profile {
    name = aws_iam_instance_profile.ec2_profile.name
  }
  tag_specifications {
    resource_type = "instance"
    tags = {
      Name        = "fis-target"
      Environment = var.environment
      Project     = var.project
    }
  }
  tags = {
    Name        = "${local.name_prefix}-lt"
    Environment = var.environment
    Project     = var.project
  }
}

resource "aws_autoscaling_group" "fis" {
  name_prefix               = "${local.name_prefix}-asg-"
  desired_capacity          = 1
  max_size                  = 1
  min_size                  = 1
  vpc_zone_identifier       = [aws_subnet.public.id]
  health_check_type         = "EC2"
  health_check_grace_period = 300
  launch_template {
    id      = aws_launch_template.fis.id
    version = "$Latest"
  }
  tag {
    key                 = "Name"
    value               = "fis-target"
    propagate_at_launch = true
  }
  tag {
    key                 = "Environment"
    value               = var.environment
    propagate_at_launch = true
  }
  tag {
    key                 = "Project"
    value               = var.project
    propagate_at_launch = true
  }
  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_kms_key" "fis_log_key" {
  description             = "KMS key for FIS log bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow FIS Service to use key for log delivery"
        Effect = "Allow"
        Principal = {
          Service = "fis.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow FIS Role to use key"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.fis_role.arn
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
      }
    ]
  })
  tags = {
    Name        = "${local.name_prefix}-kms-fis-log"
    Environment = var.environment
    Project     = var.project
  }
  lifecycle {
    prevent_destroy = true
  }
}

data "aws_region" "current" {}

resource "aws_s3_bucket" "fis_log_bucket" {
  bucket = "${local.name_prefix}-fis-logs-${random_id.bucket_suffix.hex}"
  tags = {
    Name        = "${local.name_prefix}-fis-logs"
    Environment = var.environment
    Project     = var.project
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "fis_log_bucket" {
  bucket                  = aws_s3_bucket.fis_log_bucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "fis_log_bucket" {
  bucket = aws_s3_bucket.fis_log_bucket.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.fis_log_key.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "fis_log_bucket" {
  bucket = aws_s3_bucket.fis_log_bucket.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket" "fis_log_delivery" {
  bucket        = "${local.name_prefix}-fis-logs-delivery-${random_id.delivery_suffix.hex}"
  force_destroy = true
  tags = {
    Name        = "${local.name_prefix}-fis-logs-delivery"
    Environment = var.environment
    Project     = var.project
  }
}

resource "aws_s3_bucket_public_access_block" "fis_log_delivery" {
  bucket                  = aws_s3_bucket.fis_log_delivery.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "fis_log_delivery" {
  bucket = aws_s3_bucket.fis_log_delivery.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "fis_log_delivery" {
  bucket = aws_s3_bucket.fis_log_delivery.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_policy" "fis_log_delivery" {
  bucket = aws_s3_bucket.fis_log_delivery.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLogDelivery"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.fis_log_delivery.arn}/*"
      }
    ]
  })
}

resource "aws_s3_bucket_logging" "fis_log_bucket" {
  bucket        = aws_s3_bucket.fis_log_bucket.id
  target_bucket = aws_s3_bucket.fis_log_delivery.id
  target_prefix = "log/"
}

resource "aws_s3_bucket_policy" "fis_log_bucket" {
  bucket = aws_s3_bucket.fis_log_bucket.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowFISLogDelivery"
        Effect = "Allow"
        Principal = {
          Service = "fis.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.fis_log_bucket.arn}/*"
      }
    ]
  })
}

resource "aws_iam_role" "ec2_role" {
  name_prefix = "${local.name_prefix}-ec2-role-"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = {
    Name        = "${local.name_prefix}-ec2-role"
    Environment = var.environment
    Project     = var.project
  }
}

resource "aws_iam_role_policy_attachment" "ecs" {
  role       = aws_iam_role.ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

resource "aws_iam_role_policy_attachment" "ssm" {
  role       = aws_iam_role.ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ec2_profile" {
  name_prefix = "${local.name_prefix}-ec2-profile-"
  role        = aws_iam_role.ec2_role.name
}

resource "aws_iam_role" "fis_role" {
  name_prefix = "${local.name_prefix}-fis-role-"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "fis.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = {
    Name        = "${local.name_prefix}-fis-role"
    Environment = var.environment
    Project     = var.project
  }
}

resource "aws_iam_policy" "fis_policy" {
  name_prefix = "${local.name_prefix}-fis-policy-"
  description = "Permissions for FIS experiment execution"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "FISEC2Actions"
        Effect = "Allow"
        Action = [
          "ec2:DescribeImages",
          "ec2:DescribeVolumes",
          "ec2:DescribeInstances",
          "ec2:DescribeSubnets",
          "ec2:TerminateInstances",
          "ec2:ModifyVolume",
          "ec2:ModifySubnetAttribute",
          "ec2:DescribeVolumeStatus",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeNetworkInterfaces",
          "ec2:StopInstances"
        ]
        Resource = "*"
      },
      {
        Sid    = "FISSSMActions"
        Effect = "Allow"
        Action = [
          "ssm:SendCommand",
          "ssm:ListCommands",
          "ssm:DescribeInstanceInformation"
        ]
        Resource = "*"
      },
      {
        Sid    = "FISKMSPermissions"
        Effect = "Allow"
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = aws_kms_key.fis_log_key.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "fis_policy_attach" {
  role       = aws_iam_role.fis_role.name
  policy_arn = aws_iam_policy.fis_policy.arn
}

# VPC Flow Logs
resource "aws_cloudwatch_log_group" "fis_vpc_flow" {
  name_prefix       = "${local.name_prefix}-vpc-flow-logs-"
  retention_in_days = 7
  kms_key_id        = aws_kms_key.fis_log_key.arn
  tags = {
    Name        = "${local.name_prefix}-vpc-flow-logs"
    Environment = var.environment
    Project     = var.project
  }
}

resource "aws_iam_role" "flow_logs" {
  name_prefix = "${local.name_prefix}-flow-logs-role-"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = {
    Name        = "${local.name_prefix}-flow-logs-role"
    Environment = var.environment
    Project     = var.project
  }
}

resource "aws_iam_role_policy" "flow_logs" {
  name = "${local.name_prefix}-flow-logs-policy"
  role = aws_iam_role.flow_logs.id
  policy = jsonencode({
    Version = "2012-10-17"
