# FIS Experiment Templates

resource "aws_fis_experiment_template" "internal_error" {
  description = "EC2 Instance Stop (placeholder for API error fault)"
  role_arn    = aws_iam_role.fis_role.arn
  stop_condition {
    source = "none"
  }
  action {
    name      = "fault"
    action_id = "aws:ec2:stop-instances"
    target {
      key   = "Instances"
      value = "target-ec2-instances"
    }
  }
  target {
    name           = "target-ec2-instances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"
    resource_tag {
      key   = "Name"
      value = "fis-target"
    }
  }
  log_configuration {
    log_schema_version = 1
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_log_bucket.bucket
    }
  }
  tags = {
    Name        = "${local.name_prefix}-fis-internal-error"
    Environment = var.environment
    Project     = var.project
  }
}

resource "aws_fis_experiment_template" "ebs_pause_io" {
  description = "EBS Volume I/O Pause (placeholder using instance stop)"
  role_arn    = aws_iam_role.fis_role.arn
  stop_condition {
    source = "none"
  }
  action {
    name      = "fault"
    action_id = "aws:ec2:stop-instances"
    target {
      key   = "Instances"
      value = "target-ec2-instances"
    }
  }
  target {
    name           = "target-ec2-instances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"
    resource_tag {
      key   = "Name"
      value = "fis-target"
    }
  }
  log_configuration {
    log_schema_version = 1
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_log_bucket.bucket
    }
  }
  tags = {
    Name        = "${local.name_prefix}-fis-ebs-pause"
    Environment = var.environment
    Project     = var.project
  }
}

resource "aws_fis_experiment_template" "cpu_stress" {
  description = "EC2 CPU Stress"
  role_arn    = aws_iam_role.fis_role.arn
  stop_condition {
    source = "none"
  }
  action {
    name      = "fault"
    action_id = "aws:ssm:send-command"
    parameter {
      key   = "documentArn"
      value = "arn:aws:ssm:us-east-1::document/AWSFIS-Run-CPU-Stress"
    }
    parameter {
      key   = "documentParameters"
      value = "{\"DurationSeconds\":\"60\",\"NumberOfProcessors\":\"1\"}"
    }
    parameter {
      key   = "duration"
      value = "PT1M"
    }
    target {
      key   = "Instances"
      value = "target-ec2-instances"
    }
  }
  target {
    name           = "target-ec2-instances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"
    resource_tag {
      key   = "Name"
      value = "fis-target"
    }
  }
  log_configuration {
    log_schema_version = 1
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_log_bucket.bucket
    }
  }
  tags = {
    Name        = "${local.name_prefix}-fis-cpu-stress"
    Environment = var.environment
    Project     = var.project
  }
}

resource "aws_fis_experiment_template" "terminate_instances" {
  description = "EC2 Instance Termination"
  role_arn    = aws_iam_role.fis_role.arn
  stop_condition {
    source = "none"
  }
  action {
    name      = "fault"
    action_id = "aws:ec2:terminate-instances"
    target {
      key   = "Instances"
      value = "target-ec2-instances"
    }
  }
  target {
    name           = "target-ec2-instances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"
    resource_tag {
      key   = "Name"
      value = "fis-target"
    }
  }
  log_configuration {
    log_schema_version = 1
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_log_bucket.bucket
    }
  }
  tags = {
    Name        = "${local.name_prefix}-fis-terminate"
    Environment = var.environment
    Project     = var.project
  }
}

resource "aws_fis_experiment_template" "network_disrupt" {
  description = "Subnet Network Connectivity Disruption (placeholder using instance stop)"
  role_arn    = aws_iam_role.fis_role.arn
  stop_condition {
    source = "none"
  }
  action {
    name      = "fault"
    action_id = "aws:ec2:stop-instances"
    target {
      key   = "Instances"
      value = "target-ec2-instances"
    }
  }
  target {
    name           = "target-ec2-instances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"
    resource_tag {
      key   = "Name"
      value = "fis-target"
    }
  }
  log_configuration {
    log_schema_version = 1
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_log_bucket.bucket
    }
  }
  tags = {
    Name        = "${local.name_prefix}-fis-network-disrupt"
    Environment = var.environment
    Project     = var.project
  }
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------
variable "create_vpc" {
  description = "Controls whether to create the VPC"
  type        = bool
  default     = true
}

variable "vpc_cidr" {
  description = "IPv4 CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "ipv4_ipam_pool_id" {
  description = "IPAM pool ID to allocate the VPC CIDR from"
  type        = string
  default     = null
}

variable "ipv4_netmask_length" {
  description = "Netmask length for VPC CIDR when using IPAM"
  type        = number
  default     = null
}

variable "secondary_cidr_blocks" {
  description = "List of secondary IPv4 CIDR blocks to associate with the VPC"
  type        = list(string)
  default     = []
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "public_subnets" {
  description = "Map of public subnet definitions. Each key is a subnet name, value is an object with cidr, az (optional), ipv6_cidr_block (optional)"
  type = map(object({
    cidr            = string
    az              = optional(string)
    ipv6_cidr_block = optional(string)
  }))
  default = {}
}

variable "private_subnets" {
  description = "Map of private subnet definitions. Same structure as public_subnets."
  type = map(object({
    cidr            = string
    az              = optional(string)
    ipv6_cidr_block = optional(string)
  }))
  default = {}
}

variable "create_igw" {
  description = "Controls whether to create an Internet Gateway"
  type        = bool
  default     = true
}

variable "nat_gateway_config" {
  description = "Map of AZ names to boolean indicating whether to create a NAT Gateway in that AZ. The public subnet in the same AZ will be used."
  type        = map(bool)
  default     = {}
}

variable "create_egress_only_igw" {
  description = "Controls whether to create an Egress-Only Internet Gateway"
  type        = bool
  default     = false
}

variable "dhcp_options_config" {
  description = "Configuration for DHCP options. Set to null to skip."
  type = object({
    domain_name          = optional(string)
    domain_name_servers  = optional(list(string))
    ntp_servers          = optional(list(string))
    netbios_name_servers = optional(list(string))
    netbios_node_type    = optional(string)
  })
  default = null
}

variable "flow_log_config" {
  description = "Configuration for VPC Flow Logs. Set to null to disable. Allowed destination_type values: \"cloud-watch-logs\", \"s3\", \"kinesis-data-firehose\"."
  type = object({
    destination_type   = string # "cloud-watch-logs" or "s3" or "kinesis-data-firehose"
    traffic_interval   = optional(number, 600)
    log_format         = optional(string)
    s3_bucket_name     = optional(string) # only if destination_type = "s3"
    log_group_name     = optional(string) # only if destination_type = "cloud-watch-logs"
  })
  default = {
    destination_type = "cloud-watch-logs"
  }
}

variable "manage_default_security_group" {
  description = "Whether to manage the default security group of the VPC"
  type        = bool
  default     = false
}

variable "manage_default_network_acl" {
  description = "Whether to manage the default network ACL of the VPC"
  type        = bool
  default     = false
}

variable "manage_default_route_table" {
  description = "Whether to manage the default route table of the VPC"
  type        = bool
  default     = false
}

variable "tags" {
  description = "A map of tags to add to all resources"
  type        = map(string)
  default     = {}
}

# ------------------------------------------------------------------------------
# LOCALS
# ------------------------------------------------------------------------------
locals {
  vpc_tags   = merge(var.tags, { Name = var.vpc_cidr })
  subnet_tags = merge(var.tags, {})

  azs = data.aws_availability_zones.available.names

  public_subnet_az = {
    for k, v in var.public_subnets : k => (
      v.az != null ? v.az : local.azs[0]
    )
  }

  private_subnet_az = {
    for k, v in var.private_subnets : k => (
      v.az != null ? v.az : local.azs[0]
    )
  }

  nat_azs = { for az, enabled in var.nat_gateway_config : az => az if enabled }

  az_to_public_subnet_id = {
    for az in distinct(values(local.public_subnet_az)) : az => [
      for name, sub in aws_subnet.public : sub.id
      if local.public_subnet_az[name] == az
    ][0]
  }

  # Flow log configuration
  flow_log_enabled = var.flow_log_config != null
  flow_log_dest_type = var.flow_log_config != null ? var.flow_log_config.destination_type : ""
  flow_log_s3_bucket_name = var.flow_log_config != null ? coalesce(var.flow_log_config.s3_bucket_name, "vpc-flow-logs-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}") : ""
  flow_log_log_group_name = var.flow_log_config != null ? coalesce(var.flow_log_config.log_group_name, "/aws/vpc/flow-logs") : ""
}

# ------------------------------------------------------------------------------
# DATA SOURCES
# ------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# ------------------------------------------------------------------------------
# VPC
# ------------------------------------------------------------------------------
resource "aws_vpc" "this" {
  count = var.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr
  ipv4_ipam_pool_id    = var.ipv4_ipam_pool_id
  ipv4_netmask_length  = var.ipv4_netmask_length
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = merge(local.vpc_tags, { Name = var.vpc_cidr })
}

# Secondary CIDR associations
resource "aws_vpc_ipv4_cidr_block_association" "this" {
  for_each = toset(var.secondary_cidr_blocks)

  vpc_id     = aws_vpc.this[0].id
  cidr_block = each.value
}

# ------------------------------------------------------------------------------
# SUBNETS
# ------------------------------------------------------------------------------
resource "aws_subnet" "public" {
  for_each = var.public_subnets

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = each.value.cidr
  availability_zone = local.public_subnet_az[each.key]
  ipv6_cidr_block   = each.value.ipv6_cidr_block

  tags = merge(local.subnet_tags, { Name = "public-${each.key}", Type = "public" })
}

resource "aws_subnet" "private" {
  for_each = var.private_subnets

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = each.value.cidr
  availability_zone = local.private_subnet_az[each.key]
  ipv6_cidr_block   = each.value.ipv6_cidr_block

  tags = merge(local.subnet_tags, { Name = "private-${each.key}", Type = "private" })
}

# ------------------------------------------------------------------------------
# INTERNET GATEWAY
# ------------------------------------------------------------------------------
resource "aws_internet_gateway" "this" {
  count = var.create_igw && var.create_vpc ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, { Name = "igw-${var.vpc_cidr}" })
}

# ------------------------------------------------------------------------------
# PUBLIC ROUTE TABLE
# ------------------------------------------------------------------------------
resource "aws_route_table" "public" {
  count = var.create_vpc ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, { Name = "public-rtb" })
}

resource "aws_route" "public_igw" {
  count = var.create_igw && var.create_vpc ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  for_each = var.public_subnets

  subnet_id      = aws_subnet.public[each.key].id
  route_table_id = aws_route_table.public[0].id
}

# ------------------------------------------------------------------------------
# NAT GATEWAYS (one per AZ)
# ------------------------------------------------------------------------------
resource "aws_eip" "nat" {
  for_each = local.nat_azs

  domain = "vpc"

  tags = merge(var.tags, { Name = "nat-eip-${each.value}" })
}

resource "aws_nat_gateway" "this" {
  for_each = local.nat_azs

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = local.az_to_public_subnet_id[each.key]

  tags = merge(var.tags, { Name = "nat-${each.key}" })
}

# ------------------------------------------------------------------------------
# PRIVATE ROUTE TABLES (one per AZ)
# ------------------------------------------------------------------------------
resource "aws_route_table" "private" {
  for_each = local.nat_azs

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, { Name = "private-rtb-${each.key}" })
}

resource "aws_route" "private_nat" {
  for_each = local.nat_azs

  route_table_id         = aws_route_table.private[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[each.key].id
}

# Associate private subnets to the route table of their AZ
locals {
  private_subnet_to_rt = {
    for name, subnet in aws_subnet.private : name => aws_route_table.private[local.private_subnet_az[name]].id
  }
}

resource "aws_route_table_association" "private" {
  for_each = var.private_subnets

  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = local.private_subnet_to_rt[each.key]
}

# ------------------------------------------------------------------------------
# EGRESS-ONLY INTERNET GATEWAY (IPv6)
# ------------------------------------------------------------------------------
resource "aws_egress_only_internet_gateway" "this" {
  count = var.create_egress_only_igw && var.create_vpc ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, { Name = "eigw-${var.vpc_cidr}" })
}

# Add IPv6 routes if egress-only IGW is created
resource "aws_route" "private_egress_only_ipv6" {
  for_each = var.create_egress_only_igw ? local.nat_azs : {}

  route_table_id              = aws_route_table.private[each.key].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.this[0].id
}

resource "aws_route" "public_egress_only_ipv6" {
  count = var.create_egress_only_igw && var.create_igw && var.create_vpc ? 1 : 0

  route_table_id              = aws_route_table.public[0].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.this[0].id
}

# ------------------------------------------------------------------------------
# NETWORK ACLs
# ------------------------------------------------------------------------------
# Public subnet NACL (default allow all for demo, can be customized)
resource "aws_network_acl" "public" {
  count = length(var.public_subnets) > 0 && var.create_vpc ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = merge(var.tags, { Name = "public-nacl" })
}

resource "aws_network_acl_association" "public" {
  for_each = var.public_subnets

  network_acl_id = aws_network_acl.public[0].id
  subnet_id      = aws_subnet.public[each.key].id
}

# Private subnet NACLs (one per AZ for simplicity, allow all)
resource "aws_network_acl" "private" {
  for_each = local.nat_azs

  vpc_id = aws_vpc.this[0].id

  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol        = "-1"
    rule_no         = 101
    action          = "allow"
    ipv6_cidr_block = "::/0"
    from_port       = 0
    to_port         = 0
  }

  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  ingress {
    protocol        = "-1"
    rule_no         = 101
    action          = "allow"
    ipv6_cidr_block = "::/0"
    from_port       = 0
    to_port         = 0
  }

  tags = merge(var.tags, { Name = "private-nacl-${each.key}" })
}

resource "aws_network_acl_association" "private" {
  for_each = var.private_subnets

  network_acl_id = aws_network_acl.private[local.private_subnet_az[each.key]].id
  subnet_id      = aws_subnet.private[each.key].id
}

# ------------------------------------------------------------------------------
# DHCP OPTIONS
# ------------------------------------------------------------------------------
resource "aws_vpc_dhcp_options" "this" {
  count = var.dhcp_options_config != null && var.create_vpc ? 1 : 0

  domain_name          = var.dhcp_options_config.domain_name
  domain_name_servers  = var.dhcp_options_config.domain_name_servers
  ntp_servers          = var.dhcp_options_config.ntp_servers
  netbios_name_servers = var.dhcp_options_config.netbios_name_servers
  netbios_node_type    = var.dhcp_options_config.netbios_node_type

  tags = merge(var.tags, { Name = "dhcp-options" })
}

resource "aws_vpc_dhcp_options_association" "this" {
  count = var.dhcp_options_config != null && var.create_vpc ? 1 : 0

  vpc_id          = aws_vpc.this[0].id
  dhcp_options_id = aws_vpc_dhcp_options.this[0].id
}

# ------------------------------------------------------------------------------
# VPC FLOW LOGS
# ------------------------------------------------------------------------------
# IAM Role for CloudWatch logs destination
resource "aws_iam_role" "flow_logs" {
  count = local.flow_log_enabled && local.flow_log_dest_type == "cloud-watch-logs" ? 1 : 0

  name_prefix = "vpc-flow-logs-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(var.tags, { Name = "vpc-flow-logs-role" })
}

resource "aws_iam_role_policy" "flow_logs" {
  count = local.flow_log_enabled && local.flow_log_dest_type == "cloud-watch-logs" ? 1 : 0

  name_prefix = "vpc-flow-logs-policy-"
  role = aws_iam_role.flow_logs[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      }
    ]
  })
}

# KMS key for CloudWatch Logs encryption
resource "aws_kms_key" "flow_logs" {
  count = local.flow_log_enabled && local.flow_log_dest_type == "cloud-watch-logs" ? 1 : 0

  description             = "KMS key for VPC flow log CloudWatch Logs group encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(var.tags, { Name = "vpc-flow-logs-kms-key" })
}

resource "aws_kms_alias" "flow_logs" {
  count = local.flow_log_enabled && local.flow_log_dest_type == "cloud-watch-logs" ? 1 : 0

  name_prefix = "alias/vpc-flow-logs-"
  target_key_id = aws_kms_key.flow_logs[0].key_id
}

# S3 bucket for flow logs
resource "aws_s3_bucket" "flow_logs" {
  count = local.flow_log_enabled && local.flow_log_dest_type == "s3" ? 1 : 0

  bucket = local.flow_log_s3_bucket_name

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(var.tags, { Name = "vpc-flow-logs" })
}

resource "aws_s3_bucket_public_access_block" "flow_logs" {
  count = local.flow_log_enabled && local.flow_log_dest_type == "s3" ? 1 : 0

  bucket = aws_s3_bucket.flow_logs[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "flow_logs" {
  count = local.flow_log_enabled && local.flow_log_dest_type == "s3" ? 1 : 0

  bucket = aws_s3_bucket.flow_logs[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# CloudWatch Log Group for flow logs
resource "aws_cloudwatch_log_group" "flow_logs" {
  count = local.flow_log_enabled && local.flow_log_dest_type == "cloud-watch-logs" ? 1 : 0

  name = local.flow_log_log_group_name

  kms_key_id = aws_kms_alias.flow_logs[0].arn

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(var.tags, { Name = "vpc-flow-logs" })
}

# Flow Log resource
resource "aws_flow_log" "this" {
  count = local.flow_log_enabled && var.create_vpc ? 1 : 0

  log_destination_type = local.flow_log_dest_type
  log_destination      = local.flow_log_dest_type == "s3" ? aws_s3_bucket.flow_logs[0].arn : aws_cloudwatch_log_group.flow_logs[0].arn
  iam_role_arn         = local.flow_log_dest_type == "cloud-watch-logs" ? aws_iam_role.flow_logs[0].arn : null

  vpc_id                  = aws_vpc.this[0].id
  max_aggregation_interval = var.flow_log_config.traffic_interval
  traffic_type            = "ALL"
  log_format              = var.flow_log_config.log_format

  tags = merge(var.tags, { Name = "vpc-flow-log" })
}

# ------------------------------------------------------------------------------
# DEFAULT SECURITY GROUP MANAGEMENT
# ------------------------------------------------------------------------------
resource "aws_default_security_group" "this" {
  count = var.manage_default_security_group && var.create_vpc ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  ingress {
    protocol  = "-1"
    self      = true
    from_port = 0
    to_port   = 0
  }

  egress {
    protocol  = "-1"
    self      = true
    from_port = 0
    to_port   = 0
  }

  tags = merge(var.tags, { Name = "default-sg" })
}

# ------------------------------------------------------------------------------
# DEFAULT NETWORK ACL MANAGEMENT
# ------------------------------------------------------------------------------
resource "aws_default_network_acl" "this" {
  count = var.manage_default_network_acl && var.create_vpc ? 1 : 0

  default_network_acl_id = aws_vpc.this[0].default_network_acl_id

  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol        = "-1"
    rule_no         = 101
    action          = "allow"
    ipv6_cidr_block = "::/0"
    from_port       = 0
    to_port         = 0
  }

  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  ingress {
    protocol        = "-1"
    rule_no         = 101
    action          = "allow"
    ipv6_cidr_block = "::/0"
    from_port       = 0
    to_port         = 0
  }

  tags = merge(var.tags, { Name = "default-nacl" })
}

# ------------------------------------------------------------------------------
# DEFAULT ROUTE TABLE MANAGEMENT
# ------------------------------------------------------------------------------
resource "aws_default_route_table" "this" {
  count = var.manage_default_route_table && var.create_vpc ? 1 : 0

  default_route_table_id = aws_vpc.this[0].default_route_table_id

  # No routes – enforce that no traffic uses the default route table
  tags = merge(var.tags, { Name = "default-rtb" })
}

# ------------------------------------------------------------------------------
# OUTPUTS
# ------------------------------------------------------------------------------
output "vpc_id" {
  value = try(aws_vpc.this[0].id, null)
}

output "public_subnet_ids" {
  value = { for k, s in aws_subnet.public : k => s.id }
}

output "private_subnet_ids" {
  value = { for k, s in aws_subnet.private : k => s.id }
}

output "nat_gateway_ids" {
  value = { for k, g in aws_nat_gateway.this : k => g.id }
}

output "internet_gateway_id" {
  value = try(aws_internet_gateway.this[0].id, null)
}

output "flow_log_id" {
  value = try(aws_flow_log.this[0].id, null)
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# ----------------------------------------------------------------------
# Variables
# ----------------------------------------------------------------------
variable "server_name" {
  type        = string
  default     = ""
  description = "Explicit name for the Transfer server; if empty a random pet name is generated."
}

variable "logging_role_arn" {
  type        = string
  default     = ""
  description = "ARN of an existing IAM role for Transfer logging; if empty a new role is created."
}

variable "api_gateway_auth_enabled" {
  type        = bool
  default     = false
  description = "Enable API Gateway authentication for the Transfer server."
}

variable "endpoint_type" {
  type        = string
  default     = "PUBLIC"
  description = "Transfer server endpoint type: PUBLIC, VPC, or VPC_ENDPOINT."
  validation {
    condition     = contains(["PUBLIC", "VPC", "VPC_ENDPOINT"], var.endpoint_type)
    error_message = "Allowed values are PUBLIC, VPC, or VPC_ENDPOINT."
  }
}

variable "storage_type" {
  type        = string
  default     = "S3"
  description = "Storage type for the Transfer server (S3 or EFS)."
}

variable "protocols" {
  type        = list(string)
  default     = ["SFTP"]
  description = "List of protocols (SFTP, FTPS, AS2)."
  validation {
    condition = alltrue([
      for p in var.protocols : contains(["SFTP", "FTPS", "AS2"], p)
    ])
    error_message = "Allowed protocols: SFTP, FTPS, AS2."
  }
}

variable "certificate_arn" {
  type        = string
  default     = ""
  description = "ARN of ACM certificate for FTPS."
}

variable "login_banner" {
  type        = string
  default     = ""
  description = "Custom login banner message."
}

variable "security_policy_name" {
  type        = string
  default     = "TransferSecurityPolicy-2023-05"
  description = "Security policy name for the Transfer server."
}

variable "host_key" {
  type        = string
  default     = null
  sensitive   = true
  description = "Private host key for the server."
}

variable "structured_log_destinations" {
  type        = list(string)
  default     = []
  description = "List of CloudWatch log group ARNs for structured logs."
}

variable "as2_transport" {
  type        = bool
  default     = false
  description = "Enable AS2 transport."
}

variable "passive_ip" {
  type        = string
  default     = ""
  description = "Passive IP for FTPS."
}

variable "set_stat_option" {
  type        = string
  default     = ""
  description = "Set stat option for AS2 (DEFAULT or ENABLE_NO_OP)."
}

variable "vpc_id" {
  type        = string
  default     = ""
  description = "VPC ID for VPC/VPC_ENDPOINT endpoint types."
}

variable "subnet_ids" {
  type        = list(string)
  default     = []
  description = "List of subnet IDs for VPC endpoint type."
}

variable "vpc_endpoint_id" {
  type        = string
  default     = ""
  description = "VPC endpoint ID for VPC_ENDPOINT endpoint type."
}

variable "route53_zone_id" {
  type        = string
  default     = ""
  description = "Route53 hosted zone ID for CNAME record."
}

variable "route53_subdomain" {
  type        = string
  default     = "sftp"
  description = "Subdomain for the Route53 CNAME record."
}

variable "sftp_users" {
  type = map(object({
    home_directory = string   # e.g., "/bucket-name/prefix"
    s3_bucket_arn  = string   # ARN of the S3 bucket for the home directory
  }))
  default     = {}
  description = "Map of SFTP users with home directory and bucket ARN."
}

variable "ssh_public_keys" {
  type        = map(string)
  default     = {}
  description = "Map of username to SSH public key material."
}

# ----------------------------------------------------------------------
# Locals
# ----------------------------------------------------------------------
locals {
  common_tags = {
    Environment = "production"
    ManagedBy   = "terraform"
  }

  # Final server name: use var.server_name if not empty, else random pet.
  server_name = var.server_name != "" ? var.server_name : (
    length(random_pet.server_name) > 0 ? random_pet.server_name[0].id : ""
  )

  # Security group name for VPC hosted server
  sg_name = "transfer-server-sg-${local.server_name}"

  # API Gateway invoke URL (if enabled)
  api_gateway_url = var.api_gateway_auth_enabled ? (
    "https://${aws_api_gateway_rest_api.auth[0].id}.execute-api.${data.aws_region.current.name}.amazonaws.com/${aws_api_gateway_stage.auth[0].stage_name}${aws_api_gateway_resource.auth[0].path}"
  ) : ""
}

# ----------------------------------------------------------------------
# Data sources
# ----------------------------------------------------------------------
data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_route53_zone" "selected" {
  count = var.route53_zone_id != "" ? 1 : 0
  zone_id = var.route53_zone_id
}

# ----------------------------------------------------------------------
# Random Pet (fallback server name)
# ----------------------------------------------------------------------
resource "random_pet" "server_name" {
  count = var.server_name == "" ? 1 : 0
  length = 2
  separator = "-"
}

# ----------------------------------------------------------------------
# IAM Role for Transfer Logging
# ----------------------------------------------------------------------
data "aws_iam_policy_document" "transfer_logging_assume_role" {
  count = var.logging_role_arn == "" ? 1 : 0
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "transfer_logging" {
  count = var.logging_role_arn == "" ? 1 : 0
  name               = "transfer-logging-role"
  assume_role_policy = data.aws_iam_policy_document.transfer_logging_assume_role[0].json
  tags               = local.common_tags
}

resource "aws_iam_role_policy_attachment" "transfer_logging" {
  count = var.logging_role_arn == "" ? 1 : 0
  role       = aws_iam_role.transfer_logging[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSTransferLoggingAccess"
}

# ----------------------------------------------------------------------
# IAM Role for API Gateway Authorization
# ----------------------------------------------------------------------
data "aws_iam_policy_document" "api_gateway_auth_assume_role" {
  count = var.api_gateway_auth_enabled ? 1 : 0
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "api_gateway_auth" {
  count = var.api_gateway_auth_enabled ? 1 : 0
  statement {
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = ["arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:API-Gateway-Execution-Logs*"]
  }
}

resource "aws_iam_role" "api_gateway_auth" {
  count = var.api_gateway_auth_enabled ? 1 : 0
  name               = "transfer-api-gateway-auth-role"
  assume_role_policy = data.aws_iam_policy_document.api_gateway_auth_assume_role[0].json
  tags               = local.common_tags
}

resource "aws_iam_policy" "api_gateway_auth" {
  count = var.api_gateway_auth_enabled ? 1 : 0
  name        = "transfer-api-gateway-auth-policy"
  description = "Policy for API Gateway to write CloudWatch logs"
  policy      = data.aws_iam_policy_document.api_gateway_auth[0].json
}

resource "aws_iam_role_policy_attachment" "api_gateway_auth" {
  count = var.api_gateway_auth_enabled ? 1 : 0
  role       = aws_iam_role.api_gateway_auth[0].name
  policy_arn = aws_iam_policy.api_gateway_auth[0].arn
}

# ----------------------------------------------------------------------
# API Gateway Resources (if API Gateway auth enabled)
# ----------------------------------------------------------------------
resource "aws_api_gateway_rest_api" "auth" {
  count = var.api_gateway_auth_enabled ? 1 : 0
  name        = "sftp-auth"
  description = "API Gateway for Transfer Server authentication"
  endpoint_configuration {
    types = ["REGIONAL"]
  }
  tags = local.common_tags
}

resource "aws_api_gateway_resource" "auth" {
  count = var.api_gateway_auth_enabled ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.auth[0].id
  parent_id   = aws_api_gateway_rest_api.auth[0].root_resource_id
  path_part   = "auth"
}

resource "aws_api_gateway_method" "auth" {
  count = var.api_gateway_auth_enabled ? 1 : 0
  rest_api_id   = aws_api_gateway_rest_api.auth[0].id
  resource_id   = aws_api_gateway_resource.auth[0].id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "auth" {
  count = var.api_gateway_auth_enabled ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.auth[0].id
  resource_id = aws_api_gateway_resource.auth[0].id
  http_method = aws_api_gateway_method.auth[0].http_method
  type        = "MOCK"
  request_templates = {
    "application/json" = jsonencode({ statusCode = 200 })
  }
}

resource "aws_api_gateway_method_response" "auth" {
  count = var.api_gateway_auth_enabled ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.auth[0].id
  resource_id = aws_api_gateway_resource.auth[0].id
  http_method = aws_api_gateway_method.auth[0].http_method
  status_code = "200"
}

resource "aws_api_gateway_integration_response" "auth" {
  count = var.api_gateway_auth_enabled ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.auth[0].id
  resource_id = aws_api_gateway_resource.auth[0].id
  http_method = aws_api_gateway_method.auth[0].http_method
  status_code = aws_api_gateway_method_response.auth[0].status_code
}

resource "aws_api_gateway_deployment" "auth" {
  count = var.api_gateway_auth_enabled ? 1 : 0
  depends_on = [aws_api_gateway_integration.auth, aws_api_gateway_method_response.auth, aws_api_gateway_integration_response.auth]
  rest_api_id = aws_api_gateway_rest_api.auth[0].id
  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.auth[0].id,
      aws_api_gateway_method.auth[0].id,
      aws_api_gateway_integration.auth[0].id
    ]))
  }
  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_api_gateway_stage" "auth" {
  count = var.api_gateway_auth_enabled ? 1 : 0
  stage_name    = "prod"
  rest_api_id   = aws_api_gateway_rest_api.auth[0].id
  deployment_id = aws_api_gateway_deployment.auth[0].id
  tags          = local.common_tags
}

# Resource policy to allow Transfer service to invoke the API
data "aws_iam_policy_document" "api_gateway_resource_policy" {
  count = var.api_gateway_auth_enabled ? 1 : 0
  statement {
    actions = ["execute-api:Invoke"]
    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }
    resources = ["${aws_api_gateway_rest_api.auth[0].arn}/*/*/auth"]
  }
}

resource "aws_api_gateway_rest_api_policy" "auth" {
  count = var.api_gateway_auth_enabled ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.auth[0].id
  policy      = data.aws_iam_policy_document.api_gateway_resource_policy[0].json
}

# ----------------------------------------------------------------------
# Security Group (for VPC or VPC_ENDPOINT)
# ----------------------------------------------------------------------
resource "aws_security_group" "transfer" {
  count = (var.endpoint_type == "VPC" || var.endpoint_type == "VPC_ENDPOINT") && var.vpc_id != "" ? 1 : 0
  name        = local.sg_name
  description = "Security group for Transfer server"
  vpc_id      = var.vpc_id
  ingress {
    description = "SSH from anywhere"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = merge(local.common_tags, { Name = local.sg_name })
}

# ----------------------------------------------------------------------
# Elastic IPs (for VPC endpoint type)
# ----------------------------------------------------------------------
resource "aws_eip" "transfer" {
  for_each = var.endpoint_type == "VPC" && var.vpc_id != "" ? toset(var.subnet_ids) : toset([])
  domain   = "vpc"
  tags     = merge(local.common_tags, { Name = "transfer-eip-${each.key}" })
}

# ----------------------------------------------------------------------
# Transfer Server
# ----------------------------------------------------------------------
resource "aws_transfer_server" "main" {
  identity_provider_type = var.api_gateway_auth_enabled ? "API_GATEWAY" : "SERVICE_MANAGED"
  logging_role           = var.logging_role_arn != "" ? var.logging_role_arn : try(aws_iam_role.transfer_logging[0].arn, "")
  endpoint_type          = var.endpoint_type
  domain                 = var.storage_type
  protocols              = var.protocols
  certificate            = var.certificate_arn != "" ? var.certificate_arn : null
  security_policy_name   = var.security_policy_name
  host_key               = var.host_key
  structured_log_destinations = length(var.structured_log_destinations) > 0 ? var.structured_log_destinations : null

  # Identity provider settings as top-level arguments
  invocation_role = var.api_gateway_auth_enabled ? aws_iam_role.api_gateway_auth[0].arn : null
  url             = var.api_gateway_auth_enabled ? local.api_gateway_url : null

  dynamic "endpoint_details" {
    for_each = var.endpoint_type == "VPC" || var.endpoint_type == "VPC_ENDPOINT" && var.vpc_id != "" ? [1] : []
    content {
      vpc_id             = var.vpc_id
      subnet_ids         = var.endpoint_type == "VPC" ? var.subnet_ids : null
      security_group_ids = [aws_security_group.transfer[0].id]
      address_allocation_ids = var.endpoint_type == "VPC" ? [
        for s in var.subnet_ids : aws_eip.transfer[s].id
      ] : null
      vpc_endpoint_id = var.endpoint_type == "VPC_ENDPOINT" ? var.vpc_endpoint_id : null
    }
  }

  dynamic "protocol_details" {
    for_each = var.as2_transport || var.passive_ip != "" || var.set_stat_option != "" ? [1] : []
    content {
      as2_transports = var.as2_transport ? ["ENABLED"] : null
      passive_ip     = var.passive_ip != "" ? var.passive_ip : null
      set_stat_option = var.set_stat_option != "" ? var.set_stat_option : null
    }
  }

  # Login banner
  pre_authentication_login_banner = var.login_banner != "" ? var.login_banner : null

  tags = merge(local.common_tags, { Name = local.server_name })

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# Route53 CNAME Record
# ----------------------------------------------------------------------
resource "aws_route53_record" "sftp" {
  count = var.route53_zone_id != "" ? 1 : 0
  zone_id = var.route53_zone_id
  name    = "${var.route53_subdomain}.${data.aws_route53_zone.selected[0].name}"
  type    = "CNAME"
  ttl     = "300"
  records = [aws_transfer_server.main.endpoint]
}

# ----------------------------------------------------------------------
# SFTP Users
# ----------------------------------------------------------------------
# IAM role for each user
data "aws_iam_policy_document" "transfer_user_assume_role" {
  for_each = var.sftp_users
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "sftp_user" {
  for_each = var.sftp_users
  name               = "transfer-user-${each.key}"
  assume_role_policy = data.aws_iam_policy_document.transfer_user_assume_role[each.key].json
  tags               = local.common_tags
}

# IAM policy for each user (least privilege)
data "aws_iam_policy_document" "sftp_user" {
  for_each = var.sftp_users
  statement {
    actions   = ["s3:ListBucket"]
    resources = [each.value.s3_bucket_arn]
    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values   = ["${each.value.home_directory}/*"]
    }
  }
  statement {
    actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
    resources = ["${each.value.s3_bucket_arn}${each.value.home_directory}/*"]
  }
}

resource "aws_iam_policy" "sftp_user" {
  for_each = var.sftp_users
  name        = "transfer-user-policy-${each.key}"
  description = "S3 access policy for SFTP user ${each.key}"
  policy      = data.aws_iam_policy_document.sftp_user[each.key].json
}

resource "aws_iam_role_policy_attachment" "sftp_user" {
  for_each = var.sftp_users
  role       = aws_iam_role.sftp_user[each.key].name
  policy_arn = aws_iam_policy.sftp_user[each.key].arn
}

# Transfer user
resource "aws_transfer_user" "user" {
  for_each = var.sftp_users
  server_id = aws_transfer_server.main.id
  user_name = each.key
  role      = aws_iam_role.sftp_user[each.key].arn
  home_directory_type = "PATH"
  home_directory = each.value.home_directory
  tags = local.common_tags
}

# SSH public keys
resource "aws_transfer_ssh_key" "user" {
  for_each = {
    for k, v in var.ssh_public_keys : k => v
    if contains(keys(var.sftp_users), k)
  }
  server_id = aws_transfer_server.main.id
  user_name = each.key
  body      = each.value
}

# ----------------------------------------------------------------------
# Outputs
# ----------------------------------------------------------------------
output "transfer_server_endpoint" {
  value = aws_transfer_server.main.endpoint
}

output "logging_role_arn" {
  value = var.logging_role_arn != "" ? var.logging_role_arn : (
    length(aws_iam_role.transfer_logging) > 0 ? aws_iam_role.transfer_logging[0].arn : null
  )
}

output "api_gateway_role_arn" {
  value = var.api_gateway_auth_enabled ? aws_iam_role.api_gateway_auth[0].arn : null
}

output "route53_record_fqdn" {
  value = var.route53_zone_id != "" ? aws_route53_record.sftp[0].fqdn : null
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

locals {
  common_tags = {
    Project = "md-k8s"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "192.168.0.0/16"
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "md-k8s-vpc"
  })
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = ["192.168.0.0/19", "192.168.32.0/19", "192.168.64.0/19"][count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name                     = "md-k8s-public-${count.index}"
    "kubernetes.io/role/elb" = "1"
  })
}

resource "aws_subnet" "private" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = ["192.168.96.0/19", "192.168.128.0/19", "192.168.160.0/19"][count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name                           = "md-k8s-private-${count.index}"
    "kubernetes.io/role/internal-elb" = "1"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "md-k8s-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "md-k8s-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "md-k8s-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "md-k8s-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "md-k8s-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_db_subnet_group" "main" {
  name       = "md-k8s-private-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "md-k8s-private-subnet-group"
  })
}

resource "aws_iam_role" "eks_cluster" {
  name_prefix = "eks-cluster-role-md-k8s-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster.name
}

resource "aws_iam_role_policy_attachment" "vpc_resource_controller" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
  role       = aws_iam_role.eks_cluster.name
}

resource "aws_iam_role_policy" "describe_ec2" {
  name = "eks-describe-ec2"
  role = aws_iam_role.eks_cluster.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "ec2:Describe*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudwatch_metrics" {
  name = "eks-cloudwatch-metrics"
  role = aws_iam_role.eks_cluster.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "cloudwatch:PutMetricData"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_key" "eks" {
  description             = "EKS secrets encryption key"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow EKS cluster role to use key"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.eks_cluster.arn
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "cloudwatch" {
  description             = "CloudWatch Logs encryption key"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs service"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/cloudwatch-md-k8s"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

data "aws_caller_identity" "current" {}

resource "aws_security_group" "eks_cluster_sg" {
  name        = "md-k8s-cluster-sg"
  description = "Security group for EKS cluster control plane"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow outbound traffic to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "md-k8s-cluster-sg"
  })
}

resource "aws_security_group" "eks_node_sg" {
  name        = "md-k8s-node-sg"
  description = "Security group for EKS worker nodes"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow all traffic between nodes"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  ingress {
    description = "Allow API traffic from cluster control plane"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    security_groups = [aws_security_group.eks_cluster_sg.id]
  }

  ingress {
    description = "Allow kubelet traffic from cluster control plane"
    from_port   = 10250
    to_port     = 10250
    protocol    = "tcp"
    security_groups = [aws_security_group.eks_cluster_sg.id]
  }

  egress {
    description = "Allow outbound traffic to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "md-k8s-node-sg"
  })
}

resource "aws_security_group_rule" "cluster_ingress_from_node" {
  description       = "Allow inbound from node SG on API port"
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  source_security_group_id = aws_security_group.eks_node_sg.id
  security_group_id = aws_security_group.eks_cluster_sg.id
}

resource "aws_security_group_rule" "cluster_ingress_from_node_kubelet" {
  description       = "Allow inbound from node SG on kubelet port"
  type              = "ingress"
  from_port         = 10250
  to_port           = 10250
  protocol          = "tcp"
  source_security_group_id = aws_security_group.eks_node_sg.id
  security_group_id = aws_security_group.eks_cluster_sg.id
}

resource "aws_cloudwatch_log_group" "vpc_flow_logs" {
  name              = "/aws/vpc-flow-logs/md-k8s-vpc"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.cloudwatch.arn

  tags = local.common_tags
}

resource "aws_iam_role" "vpc_flow_logs" {
  name_prefix = "md-k8s-vpc-flow-logs-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "vpc_flow_logs_policy" {
  name = "md-k8s-vpc-flow-logs-policy"
  role = aws_iam_role.vpc_flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups"
        ]
        Resource = aws_cloudwatch_log_group.vpc_flow_logs.arn
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.vpc_flow_logs.arn
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.main.id
  iam_role_arn         = aws_iam_role.vpc_flow_logs.arn

  tags = merge(local.common_tags, {
    Name = "md-k8s-vpc-flow-log"
  })
}

resource "aws_eks_cluster" "main" {
  name     = "md-k8s"
  role_arn = aws_iam_role.eks_cluster.arn
  version  = "1.30"

  vpc_config {
    subnet_ids              = concat(aws_subnet.public[*].id, aws_subnet.private[*].id)
    endpoint_private_access = true
    endpoint_public_access  = false
    security_group_ids      = [aws_security_group.eks_cluster_sg.id]
  }

  encryption_config {
    provider {
      key_arn = aws_kms_key.eks.arn
    }
    resources = ["secrets"]
  }

  enabled_cluster_log_types = ["api", "audit", "authenticator", "controllerManager", "scheduler"]

  tags = local.common_tags

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.vpc_resource_controller,
    aws_iam_role_policy.describe_ec2,
    aws_iam_role_policy.cloudwatch_metrics
  ]

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "tags" {
  description = "Additional tags (e.g. map('BusinessUnit','XYZ'))"
  type        = map(string)
  default     = {}
}

variable "force_destroy" {
  description = "Allow deletion of bucket with objects"
  type        = bool
  default     = false
}

variable "sse_algorithm" {
  description = "Server-side encryption algorithm: 'aws:kms' or 'AES256'"
  type        = string
  default     = "aws:kms"

  validation {
    condition     = contains(["aws:kms", "AES256"], var.sse_algorithm)
    error_message = "sse_algorithm must be either 'aws:kms' or 'AES256'."
  }
}

variable "kms_key_id" {
  description = "ID of an existing KMS key to use for SSE-KMS. If empty and sse_algorithm is 'aws:kms', a new key will be created."
  type        = string
  default     = ""
}

variable "deletion_window_in_days" {
  description = "Waiting period for scheduled KMS key deletion (7-30 days)"
  type        = number
  default     = 30
}

variable "enable_lifecycle" {
  description = "Enable lifecycle configuration"
  type        = bool
  default     = false
}

variable "lifecycle_rules" {
  description = <<-EOT
List of lifecycle rules. Each rule is an object with:
  - id (string)
  - status (string: "Enabled" or "Disabled")
  - prefix (optional string)
  - filter (optional map with key "prefix")
  - transitions (list of objects: days, storage_class)
  - expiration (optional object: days, date, expired_object_delete_marker)
  - noncurrent_version_expiration (optional object: days)
  - noncurrent_version_transitions (list of objects: days, storage_class)
  - abort_incomplete_multipart_upload (optional object: days_after_initiation)
EOT
  type = list(object({
    id                                     = string
    status                                 = string
    prefix                                 = optional(string)
    filter                                 = optional(map(string))
    transitions                            = optional(list(object({
      days          = number
      storage_class = string
    })))
    expiration                             = optional(object({
      days                         = optional(number)
      date                         = optional(string)
      expired_object_delete_marker = optional(bool)
    }))
    noncurrent_version_expiration          = optional(object({
      days = number
    }))
    noncurrent_version_transitions         = optional(list(object({
      days          = number
      storage_class = string
    })))
    abort_incomplete_multipart_upload      = optional(object({
      days_after_initiation = number
    }))
  }))
  default = []
}

variable "logging_bucket" {
  description = "Name of the S3 bucket to store access logs. If empty, an automatic log bucket will be created."
  type        = string
  default     = ""
}

variable "logging_prefix" {
  description = "Prefix for log objects in the logging bucket"
  type        = string
  default     = ""
}

variable "enable_website" {
  description = "Enable static website hosting"
  type        = bool
  default     = false
}

variable "website_index_document" {
  description = "Index document for website hosting"
  type        = string
  default     = "index.html"
}

variable "website_error_document" {
  description = "Error document for website hosting"
  type        = string
  default     = "error.html"
}

variable "website_routing_rules" {
  description = "Routing rules for website hosting (list of objects)"
  type = list(object({
    condition = object({
      http_error_code_returned_equals = optional(string)
      key_prefix_equals               = optional(string)
    })
    redirect = object({
      host_name               = optional(string)
      http_redirect_code      = optional(string)
      protocol                = optional(string)
      replace_key_prefix_with = optional(string)
      replace_key_with        = optional(string)
    })
  }))
  default = []
}

variable "cors_rules" {
  description = "List of CORS rules. Each rule is an object with allowed_headers, allowed_methods, allowed_origins, expose_headers, max_age_seconds."
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "enable_object_lock" {
  description = "Enable S3 Object Lock (versioning must be enabled)"
  type        = bool
  default     = false
}

variable "object_lock_mode" {
  description = "Default retention mode: 'GOVERNANCE' or 'COMPLIANCE'"
  type        = string
  default     = "GOVERNANCE"

  validation {
    condition     = contains(["GOVERNANCE", "COMPLIANCE"], var.object_lock_mode)
    error_message = "object_lock_mode must be either 'GOVERNANCE' or 'COMPLIANCE'."
  }
}

variable "object_lock_days" {
  description = "Number of days for default retention"
  type        = number
  default     = 0
}

variable "bucket_policy_json" {
  description = "Raw JSON bucket policy. If set, this takes precedence over structured bucket_policy_statements."
  type        = string
  default     = ""
}

variable "bucket_policy_statements" {
  description = "Structured list of IAM policy statements for the bucket policy. Used only if bucket_policy_json is empty."
  type = list(object({
    sid       = optional(string)
    effect    = string
    actions   = list(string)
    principals = list(object({
      type        = string
      identifiers = list(string)
    }))
    resources = optional(list(string))
    condition = optional(object({
      test     = string
      variable = string
      values   = list(string)
    }))
  }))
  default = []
}

variable "enable_acceleration" {
  description = "Enable S3 Transfer Acceleration"
  type        = bool
  default     = false
}

variable "enable_requester_pays" {
  description = "Enable Requester Pays"
  type        = bool
  default     = false
}

variable "acl" {
  description = "Canned ACL to apply to the bucket (e.g. 'private', 'public-read'). If set, grant must be empty."
  type        = string
  default     = null
}

variable "grant" {
  description = "List of ACL grants. Each grant is an object with type, permission, uri (for Group) or id (for CanonicalUser)."
  type = list(object({
    type       = string
    permission = string
    uri        = optional(string)
    id         = optional(string)
  }))
  default = []
}

# ---------------------------------------------------------------------------------------------------------------------
# LOCAL VALUES
# ---------------------------------------------------------------------------------------------------------------------

locals {
  # Determine if we need to create a KMS key
  create_kms_key = var.sse_algorithm == "aws:kms" && var.kms_key_id == "" ? true : false
  # KMS key ARN to use for SSE
  kms_key_arn = var.sse_algorithm == "aws:kms" ? (
    local.create_kms_key ? aws_kms_key.this[0].arn : var.kms_key_id
  ) : null
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCES
# ---------------------------------------------------------------------------------------------------------------------

data "aws_partition" "current" {}
data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------------------------------------------------
# KMS KEY (if needed)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_kms_key" "this" {
  count = local.create_kms_key ? 1 : 0

  description             = "KMS key for S3 bucket org-dev-s3-bucket"
  deletion_window_in_days = var.deletion_window_in_days
  enable_key_rotation     = true
  key_usage               = "ENCRYPT_DECRYPT"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
    ]
  })
  tags = merge(var.tags, { Name = "org-dev-s3-bucket" })
}

# ---------------------------------------------------------------------------------------------------------------------
# AUTOMATIC LOG BUCKET (when no external logging bucket is provided)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_s3_bucket" "log" {
  count = var.logging_bucket == "" ? 1 : 0

  bucket        = "org-dev-s3-bucket-logs"
  force_destroy = true

  tags = merge(var.tags, { Name = "org-dev-s3-bucket-logs" })
}

resource "aws_s3_bucket_acl" "log" {
  count = var.logging_bucket == "" ? 1 : 0

  bucket = aws_s3_bucket.log[0].id
  acl    = "log-delivery-write"
}

# ---------------------------------------------------------------------------------------------------------------------
# MAIN S3 BUCKET (without inline versioning)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_s3_bucket" "this" {
  bucket        = "org-dev-s3-bucket"
  force_destroy = var.force_destroy

  tags = merge(var.tags, { Name = "org-dev-s3-bucket" })
}

# ---------------------------------------------------------------------------------------------------------------------
# PUBLIC ACCESS BLOCK FOR MAIN BUCKET (literal bucket name)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = "org-dev-s3-bucket"

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------------------------------------------------
# VERSIONING FOR MAIN BUCKET (literal bucket name)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_s3_bucket_versioning" "this" {
  bucket = "org-dev-s3-bucket"
  versioning_configuration {
    status = "Enabled"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# VERSIONING FOR LOG BUCKET (when auto-created)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_s3_bucket_versioning" "log" {
  count = var.logging_bucket == "" ? 1 : 0

  bucket = aws_s3_bucket.log[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# SERVER-SIDE ENCRYPTION
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.sse_algorithm
      kms_master_key_id = local.kms_key_arn
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# LIFECYCLE CONFIGURATION
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = var.enable_lifecycle ? 1 : 0

  bucket = aws_s3_bucket.this.id

  depends_on = [aws_s3_bucket_versioning.this]

  dynamic "rule" {
    for_each = var.lifecycle_rules

    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []

        content {
          prefix = lookup(filter.value, "prefix", null)
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions != null ? rule.value.transitions : []

        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []

        content {
          days                         = lookup(expiration.value, "days", null)
          date                         = lookup(expiration.value, "date", null)
          expired_object_delete_marker = lookup(expiration.value, "expired_object_delete_marker", null)
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []

        content {
          noncurrent_days = noncurrent_version_expiration.value.days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions != null ? rule.value.noncurrent_version_transitions : []

        content {
          noncurrent_days = noncurrent_version_transition.value.days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload != null ? [rule.value.abort_incomplete_multipart_upload] : []

        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# LOGGING (always enabled – to user‑supplied bucket or auto‑created log bucket)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_s3_bucket_logging" "this" {
  bucket = aws_s3_bucket.this.id

  target_bucket = var.logging_bucket != "" ? var.logging_bucket : aws_s3_bucket.log[0].id
  target_prefix = var.logging_prefix
}

# ---------------------------------------------------------------------------------------------------------------------
# STATIC WEBSITE HOSTING
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_s3_bucket_website_configuration" "this" {
  count = var.enable_website ? 1 : 0

  bucket = aws_s3_bucket.this.id

  index_document {
    suffix = var.website_index_document
  }

  error_document {
    key = var.website_error_document
  }

  dynamic "routing_rule" {
    for_each = var.website_routing_rules

    content {
      condition {
        http_error_code_returned_equals = lookup(routing_rule.value.condition, "http_error_code_returned_equals", null)
        key_prefix_equals               = lookup(routing_rule.value.condition, "key_prefix_equals", null)
      }
      redirect {
        host_name               = lookup(routing_rule.value.redirect, "host_name", null)
        http_redirect_code      = lookup(routing_rule.value.redirect, "http_redirect_code", null)
        protocol                = lookup(routing_rule.value.redirect, "protocol", null)
        replace_key_prefix_with = lookup(routing_rule.value.redirect, "replace_key_prefix_with", null)
        replace_key_with        = lookup(routing_rule.value.redirect, "replace_key_with", null)
      }
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# CORS CONFIGURATION
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# OBJECT LOCK CONFIGURATION
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.enable_object_lock ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode = var.object_lock_mode
      days = var.object_lock_days
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# BUCKET POLICY
# ---------------------------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "bucket_policy" {
  count = var.bucket_policy_json == "" && length(var.bucket_policy_statements) > 0 ? 1 : 0

  dynamic "statement" {
    for_each = var.bucket_policy_statements

    content {
      sid       = statement.value.sid
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = coalescelist(statement.value.resources, ["arn:${data.aws_partition.current.partition}:s3:::${aws_s3_bucket.this.id}/*", "arn:${data.aws_partition.current.partition}:s3:::${aws_s3_bucket.this.id}"])

      dynamic "principals" {
        for_each = statement.value.principals
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.condition != null ? [statement.value.condition] : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  count = var.bucket_policy_json != "" || length(var.bucket_policy_statements) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id
  policy = var.bucket_policy_json != "" ? var.bucket_policy_json : data.aws_iam_policy_document.bucket_policy[0].json
}

# ---------------------------------------------------------------------------------------------------------------------
# ACCELERATION
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.enable_acceleration ? 1 : 0

  bucket = aws_s3_bucket.this.id
  status = "Enabled"
}

# ---------------------------------------------------------------------------------------------------------------------
# REQUESTER PAYS
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_s3_bucket_request_payment_configuration" "this" {
  count = var.enable_requester_pays ? 1 : 0

  bucket = aws_s3_bucket.this.id
  payer  = "Requester"
}

# ---------------------------------------------------------------------------------------------------------------------
# ACL (deprecated but included per request)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_s3_bucket_acl" "this" {
  count = var.acl != null || length(var.grant) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.acl

  dynamic "access_control_policy" {
    for_each = length(var.grant) > 0 ? [1] : []
    content {
      dynamic "grant" {
        for_each = var.grant
        content {
          grantee {
            type       = grant.value.type
            uri        = grant.value.uri
            id         = grant.value.id
          }
          permission = grant.value.permission
        }
      }
      owner {
        id = data.aws_caller_identity.current.account_id
      }
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "bucket_id" {
  description = "The name of the bucket"
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The ARN of the bucket"
  value       = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  description = "The bucket domain name"
  value       = aws_s3_bucket.this.bucket_domain_name
}

output "tags" {
  description = "The tags applied to the bucket"
  value       = merge(var.tags, { Name = "org-dev-s3-bucket" })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Provider block is managed externally; not included.

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "create_public_subnets" {
  description = "Toggle creation of public subnets, Internet Gateway, and public route table"
  type        = bool
  default     = true
}

variable "create_private_subnets" {
  description = "Toggle creation of private subnets and private route table"
  type        = bool
  default     = true
}

variable "create_nat_gateway" {
  description = "Toggle creation of NAT Gateway and Elastic IP (requires create_public_subnets = true)"
  type        = bool
  default     = true
}

variable "availability_zone_count" {
  description = "Number of Availability Zones to use; defaults to all available AZs when null"
  type        = number
  default     = null
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

locals {
  azs = var.availability_zone_count != null ? slice(data.aws_availability_zones.available.names, 0, var.availability_zone_count) : data.aws_availability_zones.available.names
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/18"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  count  = var.create_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

# Public Subnets
resource "aws_subnet" "public" {
  count             = var.create_public_subnets ? length(local.azs) : 0
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index)
  availability_zone = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.vpc_name}-public-${local.azs[count.index]}"
  }
}

# Private Subnets
resource "aws_subnet" "private" {
  count             = var.create_private_subnets ? length(local.azs) : 0
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index + length(local.azs))
  availability_zone = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.vpc_name}-private-${local.azs[count.index]}"
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  count = var.create_public_subnets && var.create_nat_gateway ? 1 : 0
  domain = "vpc"

  tags = {
    Name = "${var.vpc_name}-nat-eip"
  }
}

# NAT Gateway
resource "aws_nat_gateway" "main" {
  count         = var.create_public_subnets && var.create_nat_gateway ? 1 : 0
  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${var.vpc_name}-nat-gw"
  }

  depends_on = [aws_internet_gateway.main]
}

# Public Route Table
resource "aws_route_table" "public" {
  count  = var.create_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = {
    Name = "${var.vpc_name}-public-rt"
  }
}

# Public Route Table Associations
resource "aws_route_table_association" "public" {
  count          = var.create_public_subnets ? length(local.azs) : 0
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# Private Route Table
resource "aws_route_table" "private" {
  count  = var.create_private_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  dynamic "route" {
    for_each = var.create_nat_gateway && var.create_public_subnets ? [1] : []
    content {
      cidr_block     = "0.0.0.0/0"
      nat_gateway_id = aws_nat_gateway.main[0].id
    }
  }

  tags = {
    Name = "${var.vpc_name}-private-rt"
  }
}

# Private Route Table Associations
resource "aws_route_table_association" "private" {
  count          = var.create_private_subnets ? length(local.azs) : 0
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

# Public Network ACL
resource "aws_network_acl" "public" {
  count  = var.create_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  ingress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 80
    to_port    = 80
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 110
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 443
    to_port    = 443
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 120
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 22
    to_port    = 22
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 130
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 1024
    to_port    = 65535
  }

  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name = "${var.vpc_name}-public-nacl"
  }
}

# Private Network ACL
resource "aws_network_acl" "private" {
  count  = var.create_private_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = aws_vpc.main.cidr_block
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name = "${var.vpc_name}-private-nacl"
  }
}

# Network ACL Associations for Public Subnets
resource "aws_network_acl_association" "public" {
  count          = var.create_public_subnets ? length(local.azs) : 0
  subnet_id      = aws_subnet.public[count.index].id
  network_acl_id = aws_network_acl.public[0].id
}

# Network ACL Associations for Private Subnets
resource "aws_network_acl_association" "private" {
  count          = var.create_private_subnets ? length(local.azs) : 0
  subnet_id      = aws_subnet.private[count.index].id
  network_acl_id = aws_network_acl.private[0].id
}

# KMS Key for CloudWatch Logs encryption (Trivy AWS-0017)
resource "aws_kms_key" "cloudwatch_logs" {
  description             = "KMS key for CloudWatch Logs encryption (${var.vpc_name})"
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogs"
        Effect = "Allow"
        Principal = {
          Service = "logs.${var.aws_region}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "cloudwatch_logs" {
  name          = "alias/cloudwatch-logs-${var.vpc_name}"
  target_key_id = aws_kms_key.cloudwatch_logs.key_id
}

# VPC Flow Logs
resource "aws_cloudwatch_log_group" "vpc_flow" {
  name       = "/aws/vpc/flow-logs/${var.vpc_name}"
  kms_key_id = aws_kms_alias.cloudwatch_logs.arn
}

resource "aws_iam_role" "vpc_flow" {
  name = "${var.vpc_name}-vpc-flow-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "vpc-flow-logs.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy" "vpc_flow" {
  name = "${var.vpc_name}-vpc-flow-policy"
  role = aws_iam_role.vpc_flow.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:PutLogEvents",
        "logs:DescribeLogGroups"
      ]
      Resource = "*"
    }]
  })
}

resource "aws_flow_log" "vpc" {
  log_destination      = aws_cloudwatch_log_group.vpc_flow.arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.vpc_flow.arn
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "is_ipv6_enabled" {
  type    = bool
  default = true
}

variable "sn_details" {
  type = list(map(string))
  default = [
    { name = "web-az1", az = "us-east-1a", type = "public" },
    { name = "web-az2", az = "us-east-1b", type = "public" },
    { name = "web-az3", az = "us-east-1c", type = "public" },
    { name = "app-az1", az = "us-east-1a", type = "private" },
    { name = "app-az2", az = "us-east-1b", type = "private" },
    { name = "app-az3", az = "us-east-1c", type = "private" },
    { name = "db-az1",  az = "us-east-1a", type = "private" },
    { name = "db-az2",  az = "us-east-1b", type = "private" },
    { name = "db-az3",  az = "us-east-1c", type = "private" },
    { name = "reserved-az1", az = "us-east-1a", type = "private" },
    { name = "reserved-az2", az = "us-east-1b", type = "private" },
    { name = "reserved-az3", az = "us-east-1c", type = "private" },
  ]
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

locals {
  subnet_map = {
    for i, sn in var.sn_details : sn.name => {
      name            = sn.name
      az              = sn.az
      type            = sn.type
      ipv4_cidr_block = cidrsubnet(aws_vpc.main.cidr_block, 4, i)
      ipv6_cidr_block = var.is_ipv6_enabled ? cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, i) : null
    }
  }
}

resource "aws_vpc" "main" {
  cidr_block                       = "10.16.0.0/16"
  instance_tenancy                 = "default"
  enable_dns_hostnames             = true
  enable_dns_support               = true
  assign_generated_ipv6_cidr_block = var.is_ipv6_enabled

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "this" {
  for_each = local.subnet_map

  vpc_id            = aws_vpc.main.id
  cidr_block        = each.value.ipv4_cidr_block
  availability_zone = each.value.az
  ipv6_cidr_block   = try(each.value.ipv6_cidr_block, null)

  tags = {
    Name = each.value.name
    Tier = each.value.type == "public" ? "web" : (
      each.value.type == "private" ? (
        can(regex("^app", each.value.name)) ? "app" : (
          can(regex("^db", each.value.name)) ? "db" : "reserved"
        )
      ) : "unknown"
    )
  }
}

resource "aws_internet_gateway" "main_igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw-vpc-${aws_vpc.main.id}"
  }
}

resource "aws_route_table" "public_rt" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "public-rt-web"
  }
}

resource "aws_route" "public_ipv4" {
  route_table_id         = aws_route_table.public_rt.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main_igw.id
}

resource "aws_route" "public_ipv6" {
  route_table_id            = aws_route_table.public_rt.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                = aws_internet_gateway.main_igw.id
}

resource "aws_route_table_association" "public" {
  for_each = {
    for k, v in local.subnet_map : k => v if v.type == "public"
  }

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.public_rt.id
}

resource "aws_security_group" "web_sg" {
  name        = "web_sg"
  description = "Security group for web tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "web_sg"
  }
}

resource "aws_security_group_rule" "web_ingress_443" {
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  description       = "Allow HTTPS from internet"
  security_group_id = aws_security_group.web_sg.id
}

resource "aws_security_group_rule" "web_ingress_22" {
  type              = "ingress"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  description       = "Allow SSH from VPC CIDR"
  security_group_id = aws_security_group.web_sg.id
}

resource "aws_security_group_rule" "web_egress_443_to_app" {
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.app_sg.id
  description              = "Allow HTTPS egress to app_sg"
  security_group_id        = aws_security_group.web_sg.id
}

resource "aws_security_group" "app_sg" {
  name        = "app_sg"
  description = "Security group for app tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "app_sg"
  }
}

resource "aws_security_group_rule" "app_ingress_443_from_web" {
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.web_sg.id
  description              = "Allow HTTPS ingress from web_sg"
  security_group_id        = aws_security_group.app_sg.id
}

resource "aws_security_group_rule" "app_egress_443_to_db" {
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.db_sg.id
  description              = "Allow HTTPS egress to db_sg"
  security_group_id        = aws_security_group.app_sg.id
}

resource "aws_security_group" "db_sg" {
  name        = "db_sg"
  description = "Security group for database tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "db_sg"
  }
}

resource "aws_security_group_rule" "db_ingress_443_from_app" {
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.app_sg.id
  description              = "Allow HTTPS ingress from app_sg"
  security_group_id        = aws_security_group.db_sg.id
}

resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for VPC Flow Logs CloudWatch Log Group encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-default-1"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "cloudwatch" {
  name_prefix   = "alias/vpc-flow-logs-"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

resource "aws_cloudwatch_log_group" "flow_log" {
  name              = "/aws/vpc-flow-logs/main-vpc"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.cloudwatch.arn
}

resource "aws_iam_role" "flow_log" {
  name = "vpc-flow-log-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "flow_log" {
  name = "vpc-flow-log-policy"
  role = aws_iam_role.flow_log.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups"
        ]
        Resource = "${aws_cloudwatch_log_group.flow_log.arn}:*"
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.flow_log.arn
  iam_role_arn         = aws_iam_role.flow_log.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
  }
}

# Variables
variable "kms_enable" {
  description = "Toggle to use custom KMS key for SNS topic and CloudWatch Log Group"
  type        = bool
  default     = true
}

variable "bucket_versioning" {
  description = "Enable versioning on the S3 bucket"
  type        = bool
  default     = true
}

variable "email_endpoint" {
  description = "Email endpoint for SNS subscription"
  type        = string
  default     = "nobody@example.com"
}

variable "success_percent_alarm" {
  description = "Enable success percent alarm (OK actions to SNS)"
  type        = bool
  default     = false
}

variable "canary_configs" {
  description = "Map of canary configurations"
  type = map(object({
    name               = string
    schedule_expression = string
    subnet_ids         = list(string)
    security_group_ids = list(string)
    source_type        = string
    source_location    = string
    handler            = string
  }))
  default = {}
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# Random suffix for unique naming
resource "random_id" "bucket_suffix" {
  byte_length = 4
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "benchmark-canary-vpc"
  }
}

# VPC Flow Logs
resource "aws_cloudwatch_log_group" "flow_log" {
  name              = "/aws/vpc/flow-logs/benchmark-canary-${random_id.bucket_suffix.hex}"
  retention_in_days = 7
  kms_key_id        = var.kms_enable ? aws_kms_key.custom.arn : null
  tags = {
    Name = "benchmark-canary-flow-log-group"
  }
}

resource "aws_flow_log" "main" {
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.flow_log.arn
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.main.id
  iam_role_arn         = aws_iam_role.flow_log.arn
  tags = {
    Name = "benchmark-canary-flow-log"
  }
}

resource "aws_iam_role" "flow_log" {
  name = "${random_pet.iam_prefix.id}-flow-log-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "flow_log" {
  name = "${random_pet.iam_prefix.id}-flow-log-policy"
  role = aws_iam_role.flow_log.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "FlowLogsToCloudWatch"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      }
    ]
  })
}

# Public subnets (no auto-assign public IP)
resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name = "benchmark-canary-public-${count.index}"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 2)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = {
    Name = "benchmark-canary-private-${count.index}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "benchmark-canary-igw"
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"
  tags = {
    Name = "benchmark-canary-nat-eip"
  }
}

# NAT Gateway
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id
  tags = {
    Name = "benchmark-canary-nat"
  }
}

# Route tables
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = {
    Name = "benchmark-canary-public-rt"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }
  tags = {
    Name = "benchmark-canary-private-rt"
  }
}

# Route table associations
resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Security group for canary VPC execution
resource "aws_security_group" "canary" {
  name        = "benchmark-canary-sg"
  description = "Security group for CloudWatch Synthetics canary VPC execution"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
    description = "Outbound HTTPS traffic for canary health checks"
  }

  egress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
    description = "Outbound HTTP traffic for canary health checks"
  }

  tags = {
    Name = "benchmark-canary-sg"
  }
}

# Random pet for IAM role name
resource "random_pet" "iam_prefix" {
  length = 2
}

# IAM role for canary execution
resource "aws_iam_role" "canary_execution" {
  name = "${random_pet.iam_prefix.id}-canary-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = [
            "lambda.amazonaws.com",
            "synthetics.amazonaws.com"
          ]
        }
      }
    ]
  })
}

# Custom IAM policy for canary
resource "aws_iam_policy" "canary_policy" {
  name   = "${random_pet.iam_prefix.id}-canary-policy"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3Permissions"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.canary_bucket.arn,
          "${aws_s3_bucket.canary_bucket.arn}/*"
        ]
      },
      {
        Sid    = "CloudWatchMetrics"
        Effect = "Allow"
        Action = "cloudwatch:PutMetricData"
        Resource = "*"
      },
      {
        Sid    = "CloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      },
      {
        Sid    = "EC2ENI"
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "canary_policy_attachment" {
  role       = aws_iam_role.canary_execution.name
  policy_arn = aws_iam_policy.canary_policy.arn
}

# S3 bucket for canary artifacts
resource "aws_s3_bucket" "canary_bucket" {
  bucket        = "benchmark-canary-bucket-tf5x-${random_id.bucket_suffix.hex}"
  force_destroy = true
}

resource "aws_s3_bucket_versioning" "canary_bucket" {
  bucket = aws_s3_bucket.canary_bucket.id
  versioning_configuration {
    status = var.bucket_versioning ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_public_access_block" "canary_bucket" {
  bucket                  = aws_s3_bucket.canary_bucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_cors_configuration" "canary_bucket" {
  bucket = aws_s3_bucket.canary_bucket.id

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET", "PUT", "POST", "DELETE", "HEAD"]
    allowed_origins = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3600
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "canary_bucket" {
  bucket = aws_s3_bucket.canary_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.custom.arn
    }
  }
}

# S3 bucket logging - log bucket
resource "aws_s3_bucket" "log_bucket" {
  bucket        = "benchmark-canary-logs-tf5x-${random_id.bucket_suffix.hex}"
  force_destroy = true
}

resource "aws_s3_bucket_versioning" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "log_bucket" {
  bucket                  = aws_s3_bucket.log_bucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.custom.arn
    }
  }
}

resource "aws_s3_bucket_policy" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3ServerAccessLogs"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.log_bucket.arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

# Enable access logging on log bucket (target: canary bucket)
resource "aws_s3_bucket_logging" "log_bucket_logging" {
  bucket = aws_s3_bucket.log_bucket.id

  target_bucket = aws_s3_bucket.canary_bucket.id
  target_prefix = "log-bucket-access-logs/"
}

# Enable access logging on canary bucket (target: log bucket)
resource "aws_s3_bucket_logging" "canary_bucket_logging" {
  bucket = aws_s3_bucket.canary_bucket.id

  target_bucket = aws_s3_bucket.log_bucket.id
  target_prefix = "canary-access-logs/"
}

# Bucket policy on canary bucket to allow S3 logging service to write
resource "aws_s3_bucket_policy" "canary_bucket_logging_policy" {
  bucket = aws_s3_bucket.canary_bucket.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3ServerAccessLogs"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.canary_bucket.arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

# KMS key for encryption (always created)
resource "aws_kms_key" "custom" {
  description             = "KMS key for benchmark canary encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Service"
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs Service"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "custom" {
  name_prefix   = "alias/benchmark-canary-key-"
  target_key_id = aws_kms_key.custom.key_id
}

# SNS topic for alerts
resource "aws_sns_topic" "canary_alerts" {
  name = "benchmark-canary-topic"

  kms_master_key_id = var.kms_enable ? aws_kms_key.custom.arn : null

  lifecycle {
    prevent_destroy = true
  }
}

# SNS topic policy
resource "aws_sns_topic_policy" "canary_alerts" {
  arn = aws_sns_topic.canary_alerts.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudWatchAlarms"
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action   = "SNS:Publish"
        Resource = aws_sns_topic.canary_alerts.arn
      }
    ]
  })
}

# SNS email subscription
resource "aws_sns_topic_subscription" "email" {
  topic_arn = aws_sns_topic.canary_alerts.arn
  protocol  = "email"
  endpoint  = var.email_endpoint
}

# Local default canary configuration (S3 source)
locals {
  default_canary_configs = {
    "default-canary" = {
      name               = "default-canary"
      schedule_expression = "rate(5 minutes)"
      subnet_ids         = aws_subnet.public[*].id
      security_group_ids = [aws_security_group.canary.id]
      source_type        = "s3"
      source_location    = aws_s3_object.canary_script.key
      handler            = "index.handler"
    }
  }

  canary_configs = length(var.canary_configs) > 0 ? var.canary_configs : local.default_canary_configs
}

# Archive file for canary script
resource "local_file" "canary_script" {
  filename = "${path.module}/canary_script.js"
  content  = <<-EOT
    exports.handler = async (event, context) => {
      return {
        statusCode: 200,
        body: JSON.stringify('Health check passed')
      };
    };
  EOT
}

data "archive_file" "canary_script" {
  type        = "zip"
  source_file = local_file.canary_script.filename
  output_path = "${path.module}/canary_script.zip"
}

# Upload canary script to S3
resource "aws_s3_object" "canary_script" {
  bucket = aws_s3_bucket.canary_bucket.id
  key    = "canary_script.zip"
  source = data.archive_file.canary_script.output_path
  etag   = data.archive_file.canary_script.output_md5
}

# CloudWatch Synthetics Canaries
resource "aws_synthetics_canary" "canary" {
  for_each = local.canary_configs

  name                 = each.value.name
  runtime_version      = "syn-nodejs-2.2"
  execution_role_arn   = aws_iam_role.canary_execution.arn
  artifact_s3_location = "s3://${aws_s3_bucket.canary_bucket.id}/artifacts"
  handler              = each.value.handler

  schedule {
    expression = each.value.schedule_expression
  }

  run_config {
    timeout_in_seconds = 120
  }

  vpc_config {
    subnet_ids         = each.value.subnet_ids
    security_group_ids = each.value.security_group_ids
  }

  # Conditional source configuration
  zip_file   = each.value.source_type == "inline" ? each.value.source_location : null
  s3_bucket  = each.value.source_type == "s3" ? aws_s3_bucket.canary_bucket.id : null
  s3_key     = each.value.source_type == "s3" ? each.value.source_location : null
  s3_version = null
}

# CloudWatch alarm for Failed metric
resource "aws_cloudwatch_metric_alarm" "canary_failure" {
  for_each = local.canary_configs

  alarm_name          = "${each.value.name}-failure-alarm"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = "Failed"
  namespace           = "CloudWatchSynthetics"
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  treat_missing_data  = "notBreaching"
  alarm_actions       = [aws_sns_topic.canary_alerts.arn]
  dimensions = {
    CanaryName = each.value.name
  }
}

# Optional success percent alarm
resource "aws_cloudwatch_metric_alarm" "canary_success_percent" {
  for_each = var.success_percent_alarm ? local.canary_configs : {}

  alarm_name          = "${each.value.name}-success-percent-alarm"
  comparison_operator = "LessThanThreshold"
  evaluation_periods  = 1
  metric_name         = "SuccessPercent"
  namespace           = "CloudWatchSynthetics"
  period              = 60
  statistic           = "Average"
  threshold           = 90
  treat_missing_data  = "notBreaching"
  ok_actions          = [aws_sns_topic.canary_alerts.arn]
  dimensions = {
    CanaryName = each.value.name
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "create_vpc" {
  description = "Toggle to create all VPC resources"
  type        = bool
  default     = true
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "public_subnet_cidrs" {
  description = "List of CIDR blocks for public subnets"
  type        = list(string)
  default     = []
}

variable "private_subnet_cidrs" {
  description = "List of CIDR blocks for private subnets"
  type        = list(string)
  default     = []
}

variable "intra_subnet_cidrs" {
  description = "List of CIDR blocks for intra (isolated) subnets"
  type        = list(string)
  default     = []
}

variable "public_subnet_names" {
  description = "Explicit list of names for public subnets (overrides auto-generation)"
  type        = list(string)
  default     = []
}

variable "private_subnet_names" {
  description = "Explicit list of names for private subnets"
  type        = list(string)
  default     = []
}

variable "intra_subnet_names" {
  description = "Explicit list of names for intra subnets"
  type        = list(string)
  default     = []
}

variable "public_subnet_suffix" {
  description = "Suffix used for auto‑generated public subnet names"
  type        = string
  default     = "public"
}

variable "private_subnet_suffix" {
  description = "Suffix used for auto‑generated private subnet names"
  type        = string
  default     = "private"
}

variable "intra_subnet_suffix" {
  description = "Suffix used for auto‑generated intra subnet names"
  type        = string
  default     = "intra"
}

variable "map_public_ip_on_launch" {
  description = "Assign a public IP to instances launched in public subnets"
  type        = bool
  default     = false
}

variable "create_igw" {
  description = "Toggle to create an Internet Gateway and associated public route"
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "Toggle to create NAT Gateways for private subnets (requires public subnets)"
  type        = bool
  default     = false
}

variable "enable_flow_log" {
  description = "Toggle to enable VPC Flow Logs to CloudWatch"
  type        = bool
  default     = true
}

variable "common_tags" {
  description = "A map of tags to add to all resources"
  type        = map(string)
  default     = {}
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------
locals {
  azs = data.aws_availability_zones.available.names

  # Auto‑generate subnet names if explicit lists are empty
  public_subnet_names = length(var.public_subnet_names) > 0 ? var.public_subnet_names : [
    for i in range(length(var.public_subnet_cidrs)) :
    format("%s-%s", var.public_subnet_suffix, element(local.azs, i))
  ]
  private_subnet_names = length(var.private_subnet_names) > 0 ? var.private_subnet_names : [
    for i in range(length(var.private_subnet_cidrs)) :
    format("%s-%s", var.private_subnet_suffix, element(local.azs, i))
  ]
  intra_subnet_names = length(var.intra_subnet_names) > 0 ? var.intra_subnet_names : [
    for i in range(length(var.intra_subnet_cidrs)) :
    format("%s-%s", var.intra_subnet_suffix, element(local.azs, i))
  ]
}

# ------------------------------------------------------------------------------
# VPC
# ------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  count = var.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = merge(var.common_tags, {
    Name = "main"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Public Subnets
# ------------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count = var.create_vpc ? length(var.public_subnet_cidrs) : 0

  vpc_id                  = aws_vpc.main[0].id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = element(local.azs, count.index)
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(var.common_tags, {
    Name = local.public_subnet_names[count.index]
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Private Subnets
# ------------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count = var.create_vpc ? length(var.private_subnet_cidrs) : 0

  vpc_id            = aws_vpc.main[0].id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = element(local.azs, count.index)

  tags = merge(var.common_tags, {
    Name = local.private_subnet_names[count.index]
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Intra (Isolated) Subnets
# ------------------------------------------------------------------------------
resource "aws_subnet" "intra" {
  count = var.create_vpc ? length(var.intra_subnet_cidrs) : 0

  vpc_id            = aws_vpc.main[0].id
  cidr_block        = var.intra_subnet_cidrs[count.index]
  availability_zone = element(local.azs, count.index)

  tags = merge(var.common_tags, {
    Name = local.intra_subnet_names[count.index]
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Internet Gateway
# ------------------------------------------------------------------------------
resource "aws_internet_gateway" "this" {
  count = var.create_vpc && var.create_igw ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(var.common_tags, {
    Name = "main"
  })
}

# ------------------------------------------------------------------------------
# Public Route Table and Routes
# ------------------------------------------------------------------------------
resource "aws_route_table" "public" {
  count = var.create_vpc ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(var.common_tags, {
    Name = "public"
  })
}

resource "aws_route" "public_internet" {
  count = var.create_vpc && var.create_igw ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  count = var.create_vpc ? length(var.public_subnet_cidrs) : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# ------------------------------------------------------------------------------
# NAT Gateways (Elastic IPs + NAT Gateways)
# ------------------------------------------------------------------------------
locals {
  nat_count = var.create_vpc && var.enable_nat_gateway && length(var.public_subnet_cidrs) > 0 && length(var.private_subnet_cidrs) > 0 ? min(length(var.public_subnet_cidrs), length(var.private_subnet_cidrs)) : 0
}

resource "aws_eip" "nat" {
  count = local.nat_count

  domain = "vpc"

  tags = merge(var.common_tags, {
    Name = "nat-${count.index}"
  })
}

resource "aws_nat_gateway" "this" {
  count = local.nat_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(var.common_tags, {
    Name = "nat-${count.index}"
  })
}

# ------------------------------------------------------------------------------
# Private Route Tables and Routes (one per private subnet)
# ------------------------------------------------------------------------------
resource "aws_route_table" "private" {
  count = var.create_vpc ? length(var.private_subnet_cidrs) : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(var.common_tags, {
    Name = "private-${count.index}"
  })
}

resource "aws_route" "private_nat" {
  count = local.nat_count > 0 ? length(var.private_subnet_cidrs) : 0

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[count.index % local.nat_count].id
}

resource "aws_route_table_association" "private" {
  count = var.create_vpc ? length(var.private_subnet_cidrs) : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ------------------------------------------------------------------------------
# Intra (Isolated) Route Tables and Associations (no internet route)
# ------------------------------------------------------------------------------
resource "aws_route_table" "intra" {
  count = var.create_vpc ? length(var.intra_subnet_cidrs) : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(var.common_tags, {
    Name = "intra-${count.index}"
  })
}

resource "aws_route_table_association" "intra" {
  count = var.create_vpc ? length(var.intra_subnet_cidrs) : 0

  subnet_id      = aws_subnet.intra[count.index].id
  route_table_id = aws_route_table.intra[count.index].id
}

# ------------------------------------------------------------------------------
# VPC Flow Logs – KMS key, CloudWatch Log Group, IAM Role and Custom Policy
# ------------------------------------------------------------------------------
resource "aws_kms_key" "flow_log" {
  count = var.create_vpc && var.enable_flow_log ? 1 : 0

  description         = "KMS key for VPC Flow Log encryption"
  enable_key_rotation = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable Root User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(var.common_tags, {
    Name = "vpc-flow-logs-key"
  })
}

resource "aws_kms_alias" "flow_log" {
  count = var.create_vpc && var.enable_flow_log ? 1 : 0

  name_prefix   = "alias/vpc-flow-logs-"
  target_key_id = aws_kms_key.flow_log[0].key_id
}

resource "aws_cloudwatch_log_group" "flow_log" {
  count = var.create_vpc && var.enable_flow_log ? 1 : 0

  name_prefix       = "/aws/vpc-flow-logs/main-"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.flow_log[0].arn

  tags = merge(var.common_tags, {
    Name = "vpc-flow-logs"
  })
}

resource "aws_iam_role" "flow_log" {
  count = var.create_vpc && var.enable_flow_log ? 1 : 0

  name_prefix = "vpc-flow-logs-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(var.common_tags, {
    Name = "vpc-flow-logs-role"
  })
}

resource "aws_iam_policy" "flow_log" {
  count = var.create_vpc && var.enable_flow_log ? 1 : 0

  name_prefix = "vpc-flow-logs-policy-"
  description = "Custom policy for VPC Flow Logs to CloudWatch"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = "${aws_cloudwatch_log_group.flow_log[0].arn}:*"
      }
    ]
  })

  tags = merge(var.common_tags, {
    Name = "vpc-flow-logs-policy"
  })
}

resource "aws_iam_role_policy_attachment" "flow_log" {
  count = var.create_vpc && var.enable_flow_log ? 1 : 0

  role       = aws_iam_role.flow_log[0].name
  policy_arn = aws_iam_policy.flow_log[0].arn
}

resource "aws_flow_log" "main" {
  count = var.create_vpc && var.enable_flow_log ? 1 : 0

  log_destination      = aws_cloudwatch_log_group.flow_log[0].arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.flow_log[0].arn
  vpc_id               = aws_vpc.main[0].id
  traffic_type         = "ALL"

  tags = merge(var.common_tags, {
    Name = "main"
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = ">= 2.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "api_type" {
  description = "Type of API Gateway: 'http' for HTTP API (v2) or 'rest' for REST API (v1)"
  type        = string
  default     = "http"
  validation {
    condition     = contains(["http", "rest"], var.api_type)
    error_message = "api_type must be 'http' or 'rest'."
  }
}

variable "api_name" {
  description = "Name of the API Gateway"
  type        = string
  default     = "benchmark-api"
}

variable "environment" {
  description = "Environment name used for stage naming"
  type        = string
  default     = "dev"
}

variable "vpc_id" {
  description = "VPC ID for VPC links and NLB"
  type        = string
  default     = null
}

variable "private_subnet_ids" {
  description = "List of private subnet IDs for VPC links and NLB"
  type        = list(string)
  default     = []
}

variable "domain_name" {
  description = "Custom domain name for API Gateway (optional)"
  type        = string
  default     = null
}

variable "hosted_zone_id" {
  description = "Route53 hosted zone ID for custom domain alias records (optional)"
  type        = string
  default     = null
}

variable "certificate_domain_name" {
  description = "Domain name for the ACM certificate (if different from domain_name)"
  type        = string
  default     = null
}

variable "alb_private_ip" {
  description = "Private IP address of the ALB to be used as target for the NLB (required when REST VPC link is enabled)"
  type        = string
  default     = null
}

variable "tcp_port" {
  description = "TCP port for the NLB target group (default 443)"
  type        = number
  default     = 443
}

variable "http_routes" {
  description = "List of HTTP API routes (v2). Each object: { route_key, integration_type, integration_uri }"
  type = list(object({
    route_key        = string
    integration_type = string
    integration_uri  = string
  }))
  default = []
}

variable "rest_resources" {
  description = "List of REST API resources and methods. Each object: { path, method, path_parameter_override, authorization }"
  type = list(object({
    path                   = string
    method                 = string
    path_parameter_override = optional(string)
    authorization          = optional(string, "NONE")
  }))
  default = []
}

variable "allowed_ip_cidr" {
  description = "CIDR block allowed to invoke the REST API (optional IP restriction)"
  type        = string
  default     = null
}

variable "api_key_name" {
  description = "Name for the REST API key (optional)"
  type        = string
  default     = null
}

variable "authorizer_name" {
  description = "Name for the Lambda authorizer (optional, REST only)"
  type        = string
  default     = null
}

# ------------------------------------------------------------------------------
# Data sources (static / well-known only)
# ------------------------------------------------------------------------------
data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------
locals {
  stage_name = "${var.environment}-stage"
  # Use certificate domain name if provided, else domain_name
  cert_domain = var.certificate_domain_name != null ? var.certificate_domain_name : (var.domain_name != null ? var.domain_name : "")
  # Enable features based on api_type
  is_http   = var.api_type == "http"
  is_rest   = var.api_type == "rest"
  # For REST VPC link, we need an internal NLB
  enable_rest_vpc_link = local.is_rest && length(var.private_subnet_ids) > 0 && var.alb_private_ip != null
  # Common tags
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ------------------------------------------------------------------------------
# KMS Key for CloudWatch Logs encryption
# ------------------------------------------------------------------------------
resource "aws_kms_key" "cloudwatch" {
  count = local.is_http || local.is_rest ? 1 : 0

  description             = "KMS key for CloudWatch Logs encryption (API Gateway access logs)"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.region}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_kms_alias" "cloudwatch" {
  count = local.is_http || local.is_rest ? 1 : 0

  name          = "alias/cloudwatch"
  target_key_id = aws_kms_key.cloudwatch[0].key_id
}

# ------------------------------------------------------------------------------
# CloudWatch Log Group for API Gateway access logging
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "api_gw" {
  count = local.is_http || local.is_rest ? 1 : 0

  name              = "/aws/api-gateway/${var.api_name}"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.cloudwatch[0].arn
  tags              = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# IAM Role for REST API CloudWatch logging (optional but recommended)
# ------------------------------------------------------------------------------
resource "aws_iam_role" "api_gateway_cloudwatch" {
  count = local.is_rest ? 1 : 0

  name               = "${var.api_name}-api-gateway-cloudwatch"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "apigateway.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
  tags = local.common_tags
}

resource "aws_iam_role_policy" "api_gateway_cloudwatch" {
  count = local.is_rest ? 1 : 0

  name = "${var.api_name}-api-gateway-cloudwatch-policy"
  role = aws_iam_role.api_gateway_cloudwatch[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ]
      Resource = "${aws_cloudwatch_log_group.api_gw[0].arn}:*"
    }]
  })
}

resource "aws_api_gateway_account" "rest" {
  count = local.is_rest ? 1 : 0

  cloudwatch_role_arn = aws_iam_role.api_gateway_cloudwatch[0].arn
}

# ------------------------------------------------------------------------------
# HTTP API (v2) Resources
# ------------------------------------------------------------------------------
resource "aws_apigatewayv2_api" "http" {
  count = local.is_http ? 1 : 0

  name          = var.api_name
  protocol_type = "HTTP"
  tags          = local.common_tags
}

resource "aws_apigatewayv2_stage" "http" {
  count = local.is_http ? 1 : 0

  api_id = aws_apigatewayv2_api.http[0].id
  name   = local.stage_name
  auto_deploy = true
  tags        = local.common_tags

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_gw[0].arn
    format = jsonencode({
      requestId          = "$context.requestId"
      sourceIp           = "$context.identity.sourceIp"
      caller             = "$context.identity.caller"
      requestTime        = "$context.requestTime"
      httpMethod         = "$context.httpMethod"
      routeKey           = "$context.routeKey"
      status             = "$context.status"
      responseLength     = "$context.responseLength"
      integrationError   = "$context.integrationErrorMessage"
    })
  }
}

resource "aws_apigatewayv2_integration" "http" {
  count = local.is_http ? length(var.http_routes) : 0

  api_id           = aws_apigatewayv2_api.http[0].id
  integration_type = var.http_routes[count.index].integration_type
  integration_uri  = var.http_routes[count.index].integration_uri
}

resource "aws_apigatewayv2_route" "http" {
  count = local.is_http ? length(var.http_routes) : 0

  api_id    = aws_apigatewayv2_api.http[0].id
  route_key = var.http_routes[count.index].route_key
  target    = "integrations/${aws_apigatewayv2_integration.http[count.index].id}"
}

# VPC Link for HTTP API (when private subnets provided)
resource "aws_apigatewayv2_vpc_link" "http" {
  count = local.is_http && length(var.private_subnet_ids) > 0 ? 1 : 0

  name               = "${var.api_name}-vpc-link"
  security_group_ids = [] # VPC link does not require SG
  subnet_ids         = var.private_subnet_ids
  tags               = local.common_tags
}

# Custom domain for HTTP API (optional)
resource "aws_acm_certificate" "http" {
  count = local.is_http && local.cert_domain != "" ? 1 : 0

  domain_name       = local.cert_domain
  validation_method = "DNS"
  tags              = local.common_tags
  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_apigatewayv2_domain_name" "http" {
  count = local.is_http && local.cert_domain != "" ? 1 : 0

  domain_name = local.cert_domain
  domain_name_configuration {
    certificate_arn = aws_acm_certificate.http[0].arn
    endpoint_type   = "REGIONAL"
    security_policy = "TLS_1_2"
  }
  tags = local.common_tags
}

resource "aws_apigatewayv2_api_mapping" "http" {
  count = local.is_http && local.cert_domain != "" ? 1 : 0

  api_id      = aws_apigatewayv2_api.http[0].id
  domain_name = aws_apigatewayv2_domain_name.http[0].id
  stage       = local.stage_name
}

# Route53 alias record for HTTP custom domain (optional)
resource "aws_route53_record" "http" {
  count = local.is_http && local.cert_domain != "" && var.hosted_zone_id != null ? 1 : 0

  zone_id = var.hosted_zone_id
  name    = local.cert_domain
  type    = "A"

  alias {
    name                   = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].target_domain_name
    zone_id                = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].hosted_zone_id
    evaluate_target_health = false
  }
}

# ------------------------------------------------------------------------------
# REST API (v1) Resources
# ------------------------------------------------------------------------------
# IAM roles and policies for Lambda authorizer (common to REST)
resource "aws_iam_role" "lambda_execution" {
  count = local.is_rest ? 1 : 0

  name               = "${var.api_name}-lambda-execution"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "lambda_execution_basic" {
  count = local.is_rest ? 1 : 0

  role       = aws_iam_role.lambda_execution[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role" "api_gateway_invocation" {
  count = local.is_rest ? 1 : 0

  name               = "${var.api_name}-api-gateway-invocation"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "apigateway.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
  tags = local.common_tags
}

resource "aws_iam_role_policy" "api_gateway_invoke_lambda" {
  count = local.is_rest ? 1 : 0

  name = "${var.api_name}-invoke-lambda"
  role = aws_iam_role.api_gateway_invocation[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = "lambda:InvokeFunction"
      Resource = aws_lambda_function.authorizer[0].arn
    }]
  })
}

# Lambda authorizer function (Node.js 16.x)
data "archive_file" "lambda_authorizer" {
  count = local.is_rest ? 1 : 0

  type        = "zip"
  output_path = "${path.module}/lambda_authorizer.zip"
  source {
    content = <<EOF
exports.handler = async (event) => {
  // Simple authorizer returning a policy document
  const policy = {
    principalId: 'user',
    policyDocument: {
      Version: '2012-10-17',
      Statement: [{
        Effect: 'Allow',
        Action: 'execute-api:Invoke',
        Resource: event.methodArn
      }]
    }
  };
  return policy;
};
EOF
    filename = "index.js"
  }
}

resource "aws_lambda_function" "authorizer" {
  count = local.is_rest ? 1 : 0

  filename         = data.archive_file.lambda_authorizer[0].output_path
  function_name    = "${var.api_name}-authorizer"
  role             = aws_iam_role.lambda_execution[0].arn
  handler          = "index.handler"
  runtime          = "nodejs16.x"
  source_code_hash = data.archive_file.lambda_authorizer[0].output_base64sha256
  tags             = local.common_tags
  lifecycle {
    create_before_destroy = true
  }
}

# REST API
resource "aws_api_gateway_rest_api" "rest" {
  count = local.is_rest ? 1 : 0

  name        = var.api_name
  description = "REST API created by Terraform"
  tags        = local.common_tags

  # Optional IP source restriction resource policy
  policy = var.allowed_ip_cidr != null ? jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = "*"
      Action = "execute-api:Invoke"
      Resource = "arn:${data.aws_partition.current.partition}:execute-api:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:*"
      Condition = {
        IpAddress = {
          "aws:SourceIp" = var.allowed_ip_cidr
        }
      }
    }]
  }) : null
}

# Dynamic resource path mapping
resource "aws_api_gateway_resource" "rest" {
  count = local.is_rest ? length(var.rest_resources) : 0

  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  parent_id   = aws_api_gateway_rest_api.rest[0].root_resource_id
  path_part   = var.rest_resources[count.index].path
}

# Methods for each resource
resource "aws_api_gateway_method" "rest" {
  count = local.is_rest ? length(var.rest_resources) : 0

  rest_api_id   = aws_api_gateway_rest_api.rest[0].id
  resource_id   = aws_api_gateway_resource.rest[count.index].id
  http_method   = var.rest_resources[count.index].method
  authorization = var.rest_resources[count.index].authorization
  # If authorizer is set, reference it
  authorizer_id = var.rest_resources[count.index].authorization == "CUSTOM" && var.authorizer_name != null ? aws_api_gateway_authorizer.rest[0].id : null
  # Path parameter override (if any) - we assume the method request may use path parameters
  request_parameters = var.rest_resources[count.index].path_parameter_override != null ? {
    "method.request.path.${var.rest_resources[count.index].path_parameter_override}" = true
  } : {}
}

# Integration (mock for simplicity; can be overridden)
resource "aws_api_gateway_integration" "rest" {
  count = local.is_rest ? length(var.rest_resources) : 0

  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  resource_id = aws_api_gateway_resource.rest[count.index].id
  http_method = aws_api_gateway_method.rest[count.index].http_method
  type        = "MOCK"
  request_templates = {
    "application/json" = jsonencode({ statusCode = 200 })
  }
}

# Deployment with auto-redeploy trigger
locals {
  rest_deployment_trigger = local.is_rest ? {
    redeployment = sha1(jsonencode([
      aws_api_gateway_rest_api.rest[0].body,
      [for r in aws_api_gateway_resource.rest : r.id],
      [for m in aws_api_gateway_method.rest : m.http_method],
      [for i in aws_api_gateway_integration.rest : i.type],
    ]))
  } : {}
}

resource "aws_api_gateway_deployment" "rest" {
  count = local.is_rest ? 1 : 0

  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  triggers    = local.rest_deployment_trigger
  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_api_gateway_stage" "rest" {
  count = local.is_rest ? 1 : 0

  stage_name    = local.stage_name
  rest_api_id   = aws_api_gateway_rest_api.rest[0].id
  deployment_id = aws_api_gateway_deployment.rest[0].id
  tags          = local.common_tags

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_gw[0].arn
    format = jsonencode({
      requestId        = "$context.requestId"
      sourceIp         = "$context.identity.sourceIp"
      caller           = "$context.identity.caller"
      requestTime      = "$context.requestTime"
      httpMethod       = "$context.httpMethod"
      resourcePath     = "$context.resourcePath"
      status           = "$context.status"
      responseLength   = "$context.responseLength"
      integrationError = "$context.integrationErrorMessage"
    })
  }
}

# Usage plan and API key
resource "aws_api_gateway_usage_plan" "rest" {
  count = local.is_rest && var.api_key_name != null ? 1 : 0

  name         = "${var.api_name}-usage-plan"
  description  = "Usage plan for ${var.api_name}"
  product_code = "Terraform"
  api_stages {
    api_id = aws_api_gateway_rest_api.rest[0].id
    stage  = local.stage_name
  }
  tags = local.common_tags
}

resource "aws_api_gateway_api_key" "rest" {
  count = local.is_rest && var.api_key_name != null ? 1 : 0

  name        = var.api_key_name
  description = "API key for ${var.api_name}"
  enabled     = true
  tags        = local.common_tags
}

resource "aws_api_gateway_usage_plan_key" "rest" {
  count = local.is_rest && var.api_key_name != null ? 1 : 0

  key_id        = aws_api_gateway_api_key.rest[0].id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.rest[0].id
}

# Store API key as SecureString in SSM Parameter Store
resource "aws_ssm_parameter" "api_key" {
  count = local.is_rest && var.api_key_name != null ? 1 : 0

  name        = "/api-gateway/${var.api_name}/${var.api_key_name}"
  description = "API key for ${var.api_name}"
  type        = "SecureString"
  value       = aws_api_gateway_api_key.rest[0].value
  tags        = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

# Authorizer for REST API
resource "aws_api_gateway_authorizer" "rest" {
  count = local.is_rest && var.authorizer_name != null ? 1 : 0

  name                   = var.authorizer_name
  rest_api_id            = aws_api_gateway_rest_api.rest[0].id
  authorizer_uri         = aws_lambda_function.authorizer[0].invoke_arn
  authorizer_credentials = aws_iam_role.api_gateway_invocation[0].arn
  type                   = "TOKEN"
  identity_source        = "method.request.header.Authorization"
}

# REST API VPC link support (when enabled)
resource "aws_lb" "nlb" {
  count = local.enable_rest_vpc_link ? 1 : 0

  name               = "${var.api_name}-nlb"
  internal           = true
  load_balancer_type = "network"
  subnets            = var.private_subnet_ids
  tags               = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lb_target_group" "nlb" {
  count = local.enable_rest_vpc_link ? 1 : 0

  name        = "${var.api_name}-nlb-tg"
  port        = var.tcp_port
  protocol    = "TCP"
  vpc_id      = var.vpc_id
  target_type = "ip"
  health_check {
    protocol = "HTTPS"
    port     = var.tcp_port
    path     = "/"
  }
  tags = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lb_target_group_attachment" "nlb" {
  count = local.enable_rest_vpc_link ? 1 : 0

  target_group_arn = aws_lb_target_group.nlb[0].arn
  target_id        = var.alb_private_ip
  port             = var.tcp_port
}

resource "aws_lb_listener" "nlb" {
  count = local.enable_rest_vpc_link ? 1 : 0

  load_balancer_arn = aws_lb.nlb[0].arn
  port              = var.tcp_port
  protocol          = "TCP"
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.nlb[0].arn
  }
}

resource "aws_api_gateway_vpc_link" "rest" {
  count = local.enable_rest_vpc_link ? 1 : 0

  name        = "${var.api_name}-vpc-link"
  target_arns = [aws_lb.nlb[0].arn]
  description = "VPC Link for ${var.api_name}"
  tags        = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "trail_name" {
  description = "Name of the CloudTrail trail"
  type        = string
  default     = "cloudtrail-trail"
}

variable "bucket_name" {
  description = "Name of the S3 bucket for CloudTrail logs. If null, a name is generated dynamically."
  type        = string
  default     = null
}

variable "force_destroy" {
  description = "Allow the S3 bucket to be destroyed even if it contains objects"
  type        = bool
  default     = true
}

variable "enable_versioning" {
  description = "Enable versioning on the S3 bucket"
  type        = bool
  default     = true
}

variable "kms_alias_prefix" {
  description = "Prefix for the KMS key alias"
  type        = string
  default     = "cloudtrail-"
}

variable "log_group_name_prefix" {
  description = "Prefix for the CloudWatch Log Group name"
  type        = string
  default     = "/aws/cloudtrail/"
}

variable "log_group_retention_days" {
  description = "Retention days for CloudWatch Log Group"
  type        = number
  default     = 90
}

variable "enable_log_file_validation" {
  description = "Enable log file validation on CloudTrail"
  type        = bool
  default     = true
}

variable "include_global_service_events" {
  description = "Include global service events in the trail"
  type        = bool
  default     = true
}

variable "is_multi_region_trail" {
  description = "Create a multi-region trail"
  type        = bool
  default     = true
}

variable "enable_logging" {
  description = "Enable logging on the trail"
  type        = bool
  default     = true
}

variable "is_organization_trail" {
  description = "Create an organization trail"
  type        = bool
  default     = false
}

variable "event_selector" {
  description = "List of event selectors for the trail"
  type = list(object({
    read_write_type           = string
    include_management_events = bool
    data_resource = optional(list(object({
      type   = string
      values = list(string)
    })), [])
  }))
  default = [
    {
      read_write_type           = "All"
      include_management_events = true
      data_resource             = []
    }
  ]
}

variable "insight_selector" {
  description = "List of insight selectors for the trail"
  type = list(object({
    insight_type = string
  }))
  default = []
}

variable "create_sns_topic" {
  description = "Create an SNS topic for CloudTrail alerts"
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "ARN of an externally managed SNS topic for CloudTrail alerts (used when create_sns_topic is false)"
  type        = string
  default     = ""
}

variable "tags" {
  description = "Tags to apply to resources"
  type        = map(string)
  default     = {}
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

resource "random_id" "suffix" {
  byte_length = 4
}

locals {
  bucket_name = var.bucket_name != null ? var.bucket_name : "${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}-${random_id.suffix.hex}"
  log_group_name = "${var.log_group_name_prefix}${var.trail_name}"
  partition      = data.aws_partition.current.partition
  account_id     = data.aws_caller_identity.current.account_id
  region         = data.aws_region.current.name
  trail_arn      = "arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/${var.trail_name}"
  kms_key_arn    = aws_kms_key.cloudtrail.arn
  sns_topic_name = var.create_sns_topic ? try(aws_sns_topic.cloudtrail[0].name, "") : (var.sns_topic_arn != "" ? element(split(":", var.sns_topic_arn), length(split(":", var.sns_topic_arn)) - 1) : "")
}

# Main S3 Bucket for CloudTrail logs
resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy
  tags          = merge(var.tags, { Name = local.bucket_name })
}

# Logging bucket for server access logs
resource "aws_s3_bucket" "logging" {
  bucket        = "${local.bucket_name}-logs"
  force_destroy = var.force_destroy
  tags          = merge(var.tags, { Name = "${local.bucket_name}-logs" })
}

# S3 Bucket Public Access Block for main bucket
resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# S3 Bucket Public Access Block for logging bucket
resource "aws_s3_bucket_public_access_block" "logging" {
  bucket                  = aws_s3_bucket.logging.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Bucket policy for logging bucket to allow S3 server access log delivery
resource "aws_s3_bucket_policy" "logging" {
  bucket = aws_s3_bucket.logging.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ServerAccessLogsDelivery"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.logging.arn}/*"
      }
    ]
  })
}

# S3 Bucket Encryption for main bucket
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = local.kms_key_arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# S3 Bucket Encryption for logging bucket (use AES256 to avoid circular dependency)
resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  bucket = aws_s3_bucket.logging.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# S3 Bucket Versioning for main bucket
resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration {
    status = var.enable_versioning ? "Enabled" : "Suspended"
  }
}

# S3 Bucket Versioning for logging bucket
resource "aws_s3_bucket_versioning" "logging" {
  bucket = aws_s3_bucket.logging.id
  versioning_configuration {
    status = var.enable_versioning ? "Enabled" : "Suspended"
  }
}

# S3 Bucket Policy for main bucket
resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudTrailAclCheck"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.this.arn
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          ArnLike = {
            "aws:SourceArn" = local.trail_arn
          }
        }
      },
      {
        Sid    = "CloudTrailWrite"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.this.arn}/AWSLogs/${local.account_id}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl"      = "bucket-owner-full-control"
            "aws:SourceAccount" = local.account_id
          }
          ArnLike = {
            "aws:SourceArn" = local.trail_arn
          }
        }
      }
    ]
  })
}

# S3 Bucket Logging configuration for main bucket
resource "aws_s3_bucket_logging" "this" {
  bucket = aws_s3_bucket.this.id
  target_bucket = aws_s3_bucket.logging.id
  target_prefix = "s3-access-logs/"
}

# KMS Key
resource "aws_kms_key" "cloudtrail" {
  description             = "KMS key for CloudTrail log encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudTrailToEncrypt"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:EncryptionContext:aws:cloudtrail:arn" = local.trail_arn
          }
        }
      },
      {
        Sid    = "AllowCloudWatchLogsToEncrypt"
        Effect = "Allow"
        Principal = {
          Service = "logs.${local.region}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*"
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:${local.log_group_name}"
          }
        }
      },
      {
        Sid    = "AllowS3ToEncrypt"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:EncryptionContext:aws:s3:arn" = aws_s3_bucket.this.arn
          }
        }
      }
    ]
  })
  tags = merge(var.tags, { Name = "${var.kms_alias_prefix}key" })
}

# KMS Key Alias
resource "aws_kms_alias" "cloudtrail" {
  name          = "alias/${var.kms_alias_prefix}${var.trail_name}"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = local.log_group_name
  retention_in_days = var.log_group_retention_days
  kms_key_id        = local.kms_key_arn
  tags              = merge(var.tags, { Name = local.log_group_name })
}

# IAM Role for CloudTrail to write to CloudWatch Logs
resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name               = "${var.trail_name}-cloudwatch-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          ArnLike = {
            "aws:SourceArn" = local.trail_arn
          }
        }
      }
    ]
  })
  tags = merge(var.tags, { Name = "${var.trail_name}-cloudwatch-role" })
}

# IAM Policy for CloudWatch Logs
resource "aws_iam_policy" "cloudtrail_cloudwatch" {
  name        = "${var.trail_name}-cloudwatch-policy"
  description = "Policy allowing CloudTrail to write logs to CloudWatch"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
      }
    ]
  })
}

# Attach Policy to Role
resource "aws_iam_role_policy_attachment" "cloudtrail_cloudwatch" {
  role       = aws_iam_role.cloudtrail_cloudwatch.name
  policy_arn = aws_iam_policy.cloudtrail_cloudwatch.arn
}

# SNS Topic (optional)
resource "aws_sns_topic" "cloudtrail" {
  count = var.create_sns_topic ? 1 : 0
  name  = "${var.trail_name}-alerts"
  tags  = merge(var.tags, { Name = "${var.trail_name}-alerts" })
}

# SNS Topic Policy
resource "aws_sns_topic_policy" "cloudtrail" {
  count = var.create_sns_topic ? 1 : 0
  arn   = aws_sns_topic.cloudtrail[0].arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudTrailPublish"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.cloudtrail[0].arn
        Condition = {
          ArnLike = {
            "aws:SourceArn" = local.trail_arn
          }
        }
      }
    ]
  })
}

# CloudTrail Trail
resource "aws_cloudtrail" "main" {
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.this.id
  s3_key_prefix                 = ""
  include_global_service_events = var.include_global_service_events
  is_multi_region_trail         = var.is_multi_region_trail
  enable_log_file_validation    = var.enable_log_file_validation
  enable_logging                = var.enable_logging
  is_organization_trail         = var.is_organization_trail
  kms_key_id                    = local.kms_key_arn
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch.arn
  sns_topic_name                = local.sns_topic_name

  dynamic "event_selector" {
    for_each = var.event_selector
    content {
      read_write_type           = event_selector.value.read_write_type
      include_management_events = event_selector.value.include_management_events

      dynamic "data_resource" {
        for_each = event_selector.value.data_resource
        content {
          type   = data_resource.value.type
          values = data_resource.value.values
        }
      }
    }
  }

  dynamic "insight_selector" {
    for_each = var.insight_selector
    content {
      insight_type = insight_selector.value.insight_type
    }
  }

  tags = merge(var.tags, { Name = var.trail_name })
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "enabled" {
  description = "Global master switch for account-level EBS security settings."
  type        = bool
  default     = true
}

variable "target_region" {
  description = "Optional AWS region override. When empty, the provider's current/default region (us-east-1) is used."
  type        = string
  default     = ""
}

variable "ebs_default_encryption_enabled" {
  description = "Whether to enable default EBS encryption for the region."
  type        = bool
  default     = true
}

variable "block_public_snapshots" {
  description = "Whether to block public access to EBS snapshots."
  type        = bool
  default     = true
}

variable "snapshot_block_public_access_state" {
  description = "State for EBS snapshot public access blocking."
  type        = string
  default     = "block-all-sharing"
}

resource "aws_ebs_encryption_by_default" "this" {
  count   = var.enabled ? 1 : 0
  enabled = var.ebs_default_encryption_enabled
}

resource "aws_ebs_snapshot_block_public_access" "this" {
  count = var.enabled && var.block_public_snapshots ? 1 : 0
  state = var.snapshot_block_public_access_state
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "user_name" {
  type        = string
  default     = "DeploymentUser"
  validation {
    condition     = length(var.user_name) > 0
    error_message = "User name must be non-empty."
  }
}

variable "tags" {
  type    = map(string)
  default = {}
}

variable "s3_bucket_arns" {
  type    = list(string)
  default = []
}

variable "s3_subpaths" {
  type    = map(list(string))
  default = {}
}

variable "lambda_function_arns" {
  type    = list(string)
  default = []
}

resource "aws_iam_user" "deployment" {
  name          = var.user_name
  force_destroy = true
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_policy" "s3_bucket" {
  for_each = toset(var.s3_bucket_arns)

  name        = "deployment-${replace(replace(each.key, ":", "-"), "/", "-")}"
  path        = "/"
  description = "S3 bucket policy for ${each.key}"
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = concat(
      [
        {
          Effect   = "Allow"
          Action   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:PutObjectAcl", "s3:GetObjectAcl"]
          Resource = [for sub in lookup(var.s3_subpaths, each.key, ["*"]) : "${each.key}/${sub}"]
        }
      ],
      [
        {
          Effect   = "Allow"
          Action   = ["s3:ListBucket"]
          Resource = [each.key]
        }
      ]
    )
  })
  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_policy" "lambda_function" {
  for_each = toset(var.lambda_function_arns)

  name        = "deployment-${replace(replace(each.key, ":", "-"), "/", "-")}"
  path        = "/"
  description = "Lambda function policy for ${each.key}"
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["lambda:UpdateFunctionCode"]
        Resource = [each.key]
      }
    ]
  })
  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_user_policy_attachment" "s3" {
  for_each = toset(var.s3_bucket_arns)

  user       = aws_iam_user.deployment.name
  policy_arn = aws_iam_policy.s3_bucket[each.key].arn
}

resource "aws_iam_user_policy_attachment" "lambda" {
  for_each = toset(var.lambda_function_arns)

  user       = aws_iam_user.deployment.name
  policy_arn = aws_iam_policy.lambda_function[each.key].arn
}

resource "aws_iam_access_key" "deployment" {
  user = aws_iam_user.deployment.name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "deployment_credentials" {
  description         = "KMS key for deployment credentials secret"
  enable_key_rotation = true
  tags                = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret" "deployment_credentials" {
  name        = "deployment-credentials-${var.user_name}"
  kms_key_id  = aws_kms_key.deployment_credentials.arn
  tags        = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "deployment_credentials" {
  secret_id = aws_secretsmanager_secret.deployment_credentials.id
  secret_string = jsonencode({
    access_key_id     = aws_iam_access_key.deployment.id
    secret_access_key = aws_iam_access_key.deployment.secret
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

# Variables
variable "custom_bucket_name" {
  description = "Custom name for the S3 bucket. If empty, falls back to domain_name or a generated name."
  type        = string
  default     = ""
}

variable "domain_name" {
  description = "Domain name for the website. If provided, ACM certificate and Route 53 records are created."
  type        = string
  default     = ""
}

variable "enable_versioning" {
  description = "Enable versioning on the S3 bucket."
  type        = bool
  default     = true
}

variable "include_www" {
  description = "If true, create www and wildcard subject alternative names in the ACM certificate and Route 53 records."
  type        = bool
  default     = false
}

variable "route53_zone_id" {
  description = "Route 53 hosted zone ID (required if domain_name is set)."
  type        = string
  default     = ""
  validation {
    condition     = var.domain_name == "" ? true : var.route53_zone_id != ""
    error_message = "route53_zone_id must be provided when domain_name is set."
  }
}

variable "tags" {
  description = "Tags to apply to resources."
  type        = map(string)
  default     = {}
}

# Data sources (only permitted ones)
data "aws_caller_identity" "current" {}

# Random suffix for bucket name fallback
resource "random_id" "bucket_suffix" {
  byte_length = 8
}

# S3 bucket
locals {
  bucket_name = coalesce(
    var.custom_bucket_name,
    var.domain_name,
    "webapp-template-${random_id.bucket_suffix.hex}"
  )
  domains = var.domain_name != "" ? toset(concat([var.domain_name], var.include_www ? ["www.${var.domain_name}"] : [])) : toset([])
}

resource "aws_s3_bucket" "website" {
  bucket        = local.bucket_name
  force_destroy = true
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "website" {
  bucket = aws_s3_bucket.website.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# KMS key for SSE-KMS encryption
data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "EnableRootAdmin"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "Enable CloudFront Decrypt"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }
    actions = ["kms:Decrypt"]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:aws:cloudfront::${data.aws_caller_identity.current.account_id}:distribution/*"]
    }
  }
}

resource "aws_kms_key" "sse_kms" {
  description             = "KMS key for S3 bucket SSE-KMS encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "sse_kms" {
  name          = "alias/s3-website-kms-key-${random_id.bucket_suffix.hex}"
  target_key_id = aws_kms_key.sse_kms.key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "website" {
  bucket = aws_s3_bucket.website.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.sse_kms.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "website" {
  bucket = aws_s3_bucket.website.id

  versioning_configuration {
    status = var.enable_versioning ? "Enabled" : "Suspended"
  }
}

# Logs bucket
resource "aws_s3_bucket" "logs" {
  bucket        = "logs-${random_id.bucket_suffix.hex}"
  force_destroy = true
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket = aws_s3_bucket.logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_versioning" "logs" {
  bucket = aws_s3_bucket.logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_acl" "logs" {
  bucket = aws_s3_bucket.logs.id
  acl    = "log-delivery-write"

  depends_on = [aws_s3_bucket_ownership_controls.logs]
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

data "aws_iam_policy_document" "logs_bucket_policy" {
  statement {
    sid    = "AllowLogDeliveryForS3"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.logs.arn}/*"]
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }

  statement {
    sid    = "AllowCloudFrontLogDelivery"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.logs.arn}/*"]
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_cloudfront_distribution.main.arn]
    }
  }
}

resource "aws_s3_bucket_policy" "logs" {
  bucket = aws_s3_bucket.logs.id
  policy = data.aws_iam_policy_document.logs_bucket_policy.json
}

resource "aws_s3_bucket_logging" "website" {
  bucket = aws_s3_bucket.website.id

  target_bucket = aws_s3_bucket.logs.id
  target_prefix = "s3-access-logs/"
}

# Origin Access Control for CloudFront
resource "aws_cloudfront_origin_access_control" "oac" {
  name                              = "s3-oac-${random_id.bucket_suffix.hex}"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
  origin_access_control_origin_type = "s3"
}

# S3 bucket policy allowing CloudFront access
data "aws_iam_policy_document" "s3_bucket_policy" {
  statement {
    sid    = "AllowCloudFrontGetObject"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.website.arn}/*"]
    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [aws_cloudfront_distribution.main.arn]
    }
  }
}

resource "aws_s3_bucket_policy" "website" {
  bucket = aws_s3_bucket.website.id
  policy = data.aws_iam_policy_document.s3_bucket_policy.json
}

# WAFv2 Web ACL for CloudFront
resource "aws_wafv2_web_acl" "cloudfront" {
  name        = "cloudfront-waf-acl-${random_id.bucket_suffix.hex}"
  description = "Web ACL for CloudFront distribution"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "cloudfrontWafAcl"
    sampled_requests_enabled   = true
  }

  tags = var.tags
}

# CloudFront distribution
resource "aws_cloudfront_distribution" "main" {
  enabled             = true
  is_ipv6_enabled     = true
  price_class         = "PriceClass_100"
  default_root_object = "index.html"
  web_acl_id          = aws_wafv2_web_acl.cloudfront.arn
  tags                = var.tags

  logging_config {
    bucket         = aws_s3_bucket.logs.bucket_domain_name
    prefix         = "cloudfront-logs/"
    include_cookies = false
  }

  origin {
    domain_name              = aws_s3_bucket.website.bucket_regional_domain_name
    origin_id                = "s3-origin"
    origin_access_control_id = aws_cloudfront_origin_access_control.oac.id
  }

  default_cache_behavior {
    target_origin_id       = "s3-origin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["DELETE", "GET", "HEAD", "OPTIONS", "PATCH", "POST", "PUT"]
    cached_methods         = ["GET", "HEAD"]
    cache_policy_id        = "658327ea-f89d-4fab-a63d-7e88639e58f6" # Managed-CachingOptimized
    compress               = true
  }

  ordered_cache_behavior {
    path_pattern           = "/index.html"
    target_origin_id       = "s3-origin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]
    cache_policy_id        = "4135ea2d-6df8-44a3-9df3-4b5a84be39ad" # Managed-CachingDisabled
    compress               = true
  }

  custom_error_response {
    error_caching_min_ttl = 10
    error_code            = 403
    response_code         = 404
    response_page_path    = "/index.html"
  }

  custom_error_response {
    error_caching_min_ttl = 10
    error_code            = 404
    response_code         = 404
    response_page_path    = "/index.html"
  }

  # Viewer certificate – conditional on domain_name
  dynamic "viewer_certificate" {
    for_each = var.domain_name != "" ? [true] : []
    content {
      acm_certificate_arn      = aws_acm_certificate_validation.main[0].certificate_arn
      ssl_support_method       = "sni-only"
      minimum_protocol_version = "TLSv1.2_2021"
    }
  }

  # Fallback viewer certificate (no domain)
  dynamic "viewer_certificate" {
    for_each = var.domain_name == "" ? [true] : []
    content {
      cloudfront_default_certificate = true
    }
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  retain_on_delete = false
}

# ACM certificate (only if domain_name is set)
resource "aws_acm_certificate" "main" {
  count = var.domain_name != "" ? 1 : 0

  domain_name       = var.domain_name
  validation_method = "DNS"
  subject_alternative_names = var.include_www ? [
    "www.${var.domain_name}",
    "*.${var.domain_name}"
  ] : []

  tags = var.tags

  lifecycle {
    create_before_destroy = true
  }
}

# Route 53 hosted zone (must exist)
data "aws_route53_zone" "selected" {
  count = var.domain_name != "" ? 1 : 0

  zone_id = var.route53_zone_id
}

# DNS validation records
resource "aws_route53_record" "validation" {
  for_each = var.domain_name != "" ? {
    for dvo in aws_acm_certificate.main[0].domain_validation_options : dvo.domain_name => {
      name   = dvo.resource_record_name
      record = dvo.resource_record_value
      type   = dvo.resource_record_type
    }
  } : {}

  zone_id = data.aws_route53_zone.selected[0].zone_id
  name    = each.value.name
  type    = each.value.type
  records = [each.value.record]
  ttl     = 60
}

# Certificate validation
resource "aws_acm_certificate_validation" "main" {
  count = var.domain_name != "" ? 1 : 0

  certificate_arn         = aws_acm_certificate.main[0].arn
  validation_record_fqdns = [for record in aws_route53_record.validation : record.fqdn]
}

# Route 53 alias A records
resource "aws_route53_record" "alias" {
  for_each = local.domains

  zone_id = data.aws_route53_zone.selected[0].zone_id
  name    = each.key
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.main.domain_name
    zone_id                = aws_cloudfront_distribution.main.hosted_zone_id
    evaluate_target_health = false
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "availability_zone_names" {
  description = "List of availability zone names for subnet placement"
  type        = list(string)
  default     = ["us-east-1a", "us-east-1b", "us-east-1c"]
}

variable "enable_s3_vpc_endpoint" {
  description = "Enable S3 Gateway VPC Endpoint"
  type        = bool
  default     = true
}

variable "tags" {
  description = "Additional tags for all resources"
  type        = map(string)
  default     = {}
}

locals {
  common_tags = merge(var.tags, {
    Author      = "Fairwinds"
    "Managed By" = "Terraform"
  })
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.20.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "vpc"
  })
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "vpc"
  })
}

# Admin Subnets (per AZ)
resource "aws_subnet" "admin" {
  for_each          = toset(var.availability_zone_names)
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 5, index(var.availability_zone_names, each.value))
  availability_zone = each.value

  tags = merge(local.common_tags, {
    Name = "admin-az${index(var.availability_zone_names, each.value) + 1}"
  })
}

# Public Subnets (per AZ)
resource "aws_subnet" "public" {
  for_each          = toset(var.availability_zone_names)
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 5, index(var.availability_zone_names, each.value) + 4)
  availability_zone = each.value

  tags = merge(local.common_tags, {
    Name = "public-az${index(var.availability_zone_names, each.value) + 1}"
  })
}

# Private Production Subnets (per AZ)
resource "aws_subnet" "private_prod" {
  for_each          = toset(var.availability_zone_names)
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 5, index(var.availability_zone_names, each.value) + 8)
  availability_zone = each.value

  tags = merge(local.common_tags, {
    Name = "private-prod-az${index(var.availability_zone_names, each.value) + 1}"
  })
}

# Private Working Subnets (per AZ)
resource "aws_subnet" "private_work" {
  for_each          = toset(var.availability_zone_names)
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 5, index(var.availability_zone_names, each.value) + 12)
  availability_zone = each.value

  tags = merge(local.common_tags, {
    Name = "private-work-az${index(var.availability_zone_names, each.value) + 1}"
  })
}

# Public Route Table (single)
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "public"
  })
}

# Associate Public Subnets to Public Route Table
resource "aws_route_table_association" "public" {
  for_each       = aws_subnet.public
  subnet_id      = each.value.id
  route_table_id = aws_route_table.public.id
}

# Private Route Tables (one per AZ)
resource "aws_route_table" "private" {
  for_each = toset(var.availability_zone_names)
  vpc_id   = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "private_az${index(var.availability_zone_names, each.value) + 1}"
  })
}

# Elastic IPs (per AZ)
resource "aws_eip" "nat" {
  for_each = toset(var.availability_zone_names)
  domain   = "vpc"

  tags = merge(local.common_tags, {
    Name = "nat-az${index(var.availability_zone_names, each.value) + 1}"
  })
}

# NAT Gateways (per AZ, placed in public subnet)
resource "aws_nat_gateway" "main" {
  for_each      = toset(var.availability_zone_names)
  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.public[each.key].id

  tags = merge(local.common_tags, {
    Name = "nat-az${index(var.availability_zone_names, each.value) + 1}"
  })

  depends_on = [aws_internet_gateway.main]
}

# Route to NAT Gateway in each private route table
resource "aws_route" "private_nat" {
  for_each       = toset(var.availability_zone_names)
  route_table_id = aws_route_table.private[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id = aws_nat_gateway.main[each.key].id
}

# Associate Admin Subnets to Private Route Tables
resource "aws_route_table_association" "admin" {
  for_each       = aws_subnet.admin
  subnet_id      = each.value.id
  route_table_id = aws_route_table.private[each.key].id
}

# Associate Private Production Subnets to Private Route Tables
resource "aws_route_table_association" "private_prod" {
  for_each       = aws_subnet.private_prod
  subnet_id      = each.value.id
  route_table_id = aws_route_table.private[each.key].id
}

# Associate Private Working Subnets to Private Route Tables
resource "aws_route_table_association" "private_work" {
  for_each       = aws_subnet.private_work
  subnet_id      = each.value.id
  route_table_id = aws_route_table.private[each.key].id
}

# S3 Gateway VPC Endpoint (conditional)
resource "aws_vpc_endpoint" "s3" {
  count           = var.enable_s3_vpc_endpoint ? 1 : 0
  vpc_id          = aws_vpc.main.id
  service_name    = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = "*"
        Action    = "*"
        Resource  = "*"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "s3-endpoint"
  })
}

# Associate S3 Endpoint with all private route tables
resource "aws_vpc_endpoint_route_table_association" "private_s3" {
  for_each         = var.enable_s3_vpc_endpoint ? toset(var.availability_zone_names) : toset([])
  route_table_id   = aws_route_table.private[each.key].id
  vpc_endpoint_id  = aws_vpc_endpoint.s3[0].id
}

# IAM policy document for CloudWatch Logs KMS key permissions
data "aws_iam_policy_document" "cloudwatch_kms" {
  statement {
    sid    = "Enable CloudWatch Logs to use the key"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logs.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "Allow full access to key administrators"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions = ["kms:*"]
    resources = ["*"]
  }
}

data "aws_caller_identity" "current" {}

# KMS Key for CloudWatch Logs encryption
resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for CloudWatch Logs encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.cloudwatch_kms.json

  tags = local.common_tags
}

# KMS Alias for the CloudWatch Logs key
resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/cloudwatch"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

# VPC Flow Logs - CloudWatch Log Group (encrypted with CMK)
resource "aws_cloudwatch_log_group" "vpc_flow_log" {
  name              = "/aws/vpc/flow-logs"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.cloudwatch.arn

  tags = local.common_tags
}

# IAM role for VPC Flow Logs delivery to CloudWatch Logs
resource "aws_iam_role" "flow_logs" {
  name = "vpc-flow-logs-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "delivery.logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

# IAM policy for VPC Flow Logs to write to CloudWatch Logs
resource "aws_iam_role_policy" "flow_logs" {
  name = "vpc-flow-logs-policy"
  role = aws_iam_role.flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          aws_cloudwatch_log_group.vpc_flow_log.arn,
          "${aws_cloudwatch_log_group.vpc_flow_log.arn}:*"
        ]
      }
    ]
  })
}

# VPC Flow Logs - Flow Log resource (using log_destination and iam_role_arn)
resource "aws_flow_log" "main" {
  log_destination      = aws_cloudwatch_log_group.vpc_flow_log.arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.flow_logs.arn
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.main.id

  tags = local.common_tags
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "tls" {
  # Default configuration – will be used for certificate generation
}

variable "github_org" {
  description = "GitHub organization or account name for OIDC role trust policy"
  type        = string
  default     = "your-org"
}

variable "health_check_path" {
  description = "Health check path for ALB target group"
  type        = string
  default     = "/"
}

variable "app_port" {
  description = "Application container port"
  type        = number
  default     = 80
}

variable "db_name" {
  description = "RDS database name"
  type        = string
  default     = "mydb"
}

variable "db_username" {
  description = "RDS master username"
  type        = string
  default     = "postgres"
}

variable "db_password" {
  description = "RDS master password (plaintext – will be stored in Secrets Manager)"
  type        = string
  default     = "postgres"
  sensitive   = true
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az_count = 2
  az_names = slice(data.aws_availability_zones.available.names, 0, local.az_count)
}

# Random suffix for unique ECR repository name
resource "random_pet" "suffix" {
  length    = 2
  separator = "-"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

# Public subnets
resource "aws_subnet" "public" {
  count             = local.az_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index)
  availability_zone = local.az_names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count             = local.az_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index + local.az_count)
  availability_zone = local.az_names[count.index]

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private route table (no default route)
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = local.az_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Security group for ALB
resource "aws_security_group" "alb" {
  name        = "alb-sg"
  description = "Security group for internal ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTP from VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "alb-sg"
  }
}

# Security group for ECS tasks
resource "aws_security_group" "ecs_task" {
  name        = "ecs-task-sg"
  description = "Security group for ECS Fargate tasks"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Application port from ALB"
    from_port       = var.app_port
    to_port         = var.app_port
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Outbound to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "ecs-task-sg"
  }
}

# Security group for RDS
resource "aws_security_group" "rds" {
  name        = "rds-sg"
  description = "Security group for RDS PostgreSQL"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from ECS tasks"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs_task.id]
  }

  egress {
    description = "Outbound to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "rds-sg"
  }
}

# TLS certificate generation
resource "tls_private_key" "self_signed" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  private_key_pem = tls_private_key.self_signed.private_key_pem

  subject {
    common_name = "alb.internal"
  }

  validity_period_hours = 87600

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

# ACM certificate import
resource "aws_acm_certificate" "self_signed" {
  private_key      = tls_private_key.self_signed.private_key_pem
  certificate_body = tls_self_signed_cert.self_signed.cert_pem

  lifecycle {
    create_before_destroy = true
  }
}

# Application Load Balancer (internal)
resource "aws_lb" "internal" {
  name                       = "app-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.private[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = "app-alb"
  }
}

# HTTP listener (redirect to HTTPS)
resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.internal.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

# HTTPS listener (forward to target group)
resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.internal.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.self_signed.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

# Target group (name_prefix exactly 6 characters)
resource "aws_lb_target_group" "main" {
  name_prefix = "ecs-tg"
  port        = var.app_port
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "ip"

  health_check {
    enabled             = true
    path                = var.health_check_path
    port                = "traffic-port"
    protocol            = "HTTP"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 5
    interval            = 30
  }

  tags = {
    Name = "ecs-tg"
  }
}

# KMS key for CloudWatch Logs
data "aws_iam_policy_document" "cloudwatch_kms" {
  statement {
    sid    = "AllowCloudWatchLogs"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:aws:logs:${data.aws_region.current.name}:*:log-group:*"]
    }
  }

  statement {
    sid    = "EnableIAMUserPermissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }
}

resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for CloudWatch Logs encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy                  = data.aws_iam_policy_document.cloudwatch_kms.json

  tags = {
    Name = "cloudwatch-logs-key"
  }
}

resource "aws_kms_alias" "cloudwatch" {
  name_prefix  = "alias/cloudwatch-logs-"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

# CloudWatch log group for ECS task logs
resource "aws_cloudwatch_log_group" "ecs" {
  name              = "/ecs/main-cluster"
  retention_in_days = 30
  kms_key_id        = aws_kms_alias.cloudwatch.arn
}

# KMS key for ECR
resource "aws_kms_key" "ecr" {
  description             = "KMS key for ECR encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = {
    Name = "ecr-key"
  }
}

resource "aws_kms_alias" "ecr" {
  name_prefix  = "alias/ecr-"
  target_key_id = aws_kms_key.ecr.key_id
}

# ECR Repository (fixed name with random suffix)
resource "aws_ecr_repository" "app" {
  name                 = "app-repo-${random_pet.suffix.id}"
  image_tag_mutability = "IMMUTABLE"
  force_delete         = false

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "KMS"
    kms_key        = aws_kms_key.ecr.key_id
  }

  lifecycle {
    create_before_destroy = true
  }
}

# ECR lifecycle policy (expire untagged images after 14 days)
resource "aws_ecr_lifecycle_policy" "untagged" {
  repository = aws_ecr_repository.app.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images after 14 days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

# RDS subnet group
resource "aws_db_subnet_group" "main" {
  name       = "rds-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "rds-subnet-group"
  }
}

# KMS key for Secrets Manager
resource "aws_kms_key" "secrets" {
  description             = "KMS key for Secrets Manager encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = {
    Name = "secrets-manager-key"
  }
}

resource "aws_kms_alias" "secrets" {
  name_prefix  = "alias/secrets-manager-"
  target_key_id = aws_kms_key.secrets.key_id
}

# Secrets Manager secret for RDS password
resource "aws_secretsmanager_secret" "db_password" {
  name_prefix = "rds-master-password-"
  kms_key_id  = aws_kms_key.secrets.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db_password" {
  secret_id     = aws_secretsmanager_secret.db_password.id
  secret_string = var.db_password
}

# RDS instance
resource "aws_db_instance" "postgres" {
  identifier              = "mydb"
  engine                  = "postgres"
  engine_version          = "16.3"
  instance_class          = "db.t3.micro"
  allocated_storage       = 20
  storage_encrypted       = true
  db_name                 = var.db_name
  username                = var.db_username
  password                = aws_secretsmanager_secret_version.db_password.secret_string
  db_subnet_group_name    = aws_db_subnet_group.main.name
  vpc_security_group_ids  = [aws_security_group.rds.id]
  skip_final_snapshot     = false
  final_snapshot_identifier = "mydb-final-snapshot"
  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:00-sun:05:00"
  multi_az                = false
  publicly_accessible     = false
  iam_database_authentication_enabled = true
  performance_insights_enabled = true
  performance_insights_retention_period = 7
  performance_insights_kms_key_id = aws_kms_key.secrets.arn
  deletion_protection = true

  lifecycle {
    prevent_destroy = true
  }
}

# ECS cluster
resource "aws_ecs_cluster" "main" {
  name = "main-cluster"

  setting {
    name  = "containerInsights"
    value = "enabled"
  }
}

# IAM execution role
data "aws_iam_policy_document" "ecs_execution_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_execution" {
  name_prefix          = "ecs-execution-role-"
  assume_role_policy   = data.aws_iam_policy_document.ecs_execution_assume.json
}

resource "aws_iam_role_policy_attachment" "ecs_execution_managed" {
  role       = aws_iam_role.ecs_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

# IAM task role (empty policy)
data "aws_iam_policy_document" "ecs_task_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_task" {
  name_prefix          = "ecs-task-role-"
  assume_role_policy   = data.aws_iam_policy_document.ecs_task_assume.json
}

# ECS task definition
resource "aws_ecs_task_definition" "app" {
  family                   = "app-task"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"
  execution_role_arn       = aws_iam_role.ecs_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name  = "app"
      image = "nginx:latest"
      portMappings = [
        {
          containerPort = var.app_port
          hostPort      = var.app_port
          protocol      = "tcp"
        }
      ]
      environment = [
        { name = "DB_HOST", value = aws_db_instance.postgres.address },
        { name = "DB_PORT", value = "5432" },
        { name = "DB_NAME", value = var.db_name },
        { name = "DB_USER", value = var.db_username }
      ]
      secrets = [
        {
          name      = "DB_PASSWORD"
          valueFrom = aws_secretsmanager_secret.db_password.arn
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.ecs.name
          "awslogs-region"        = data.aws_region.current.name
          "awslogs-stream-prefix" = "ecs"
        }
      }
    }
  ])

  lifecycle {
    create_before_destroy = true
  }
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

# ECS service
resource "aws_ecs_service" "main" {
  name            = "app-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.app.arn
  desired_count   = 2
  platform_version = "LATEST"

  capacity_provider_strategy {
    capacity_provider = "FARGATE"
    weight            = 20
    base             = 0
  }

  capacity_provider_strategy {
    capacity_provider = "FARGATE_SPOT"
    weight            = 80
    base             = 0
  }

  network_configuration {
    subnets         = aws_subnet.private[*].id
    security_groups = [aws_security_group.ecs_task.id]
    assign_public_ip = false
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.main.arn
    container_name   = "app"
    container_port   = var.app_port
  }

  deployment_circuit_breaker {
    enable   = true
    rollback = true
  }

  depends_on = [aws_lb_listener.https]
}

# Application Auto Scaling target
resource "aws_appautoscaling_target" "ecs" {
  max_capacity       = 4
  min_capacity       = 2
  resource_id        = "service/${aws_ecs_cluster.main.name}/${aws_ecs_service.main.name}"
  scalable_dimension = "ecs:service:DesiredCount"
  service_namespace  = "ecs"
}

# Target tracking scaling policies
resource "aws_appautoscaling_policy" "cpu" {
  name               = "cpu-target-tracking"
  policy_type        = "TargetTrackingScaling"
  resource_id        = aws_appautoscaling_target.ecs.resource_id
  scalable_dimension = aws_appautoscaling_target.ecs.scalable_dimension
  service_namespace  = aws_appautoscaling_target.ecs.service_namespace

  target_tracking_scaling_policy_configuration {
    target_value = 70
    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageCPUUtilization"
    }
  }
}

resource "aws_appautoscaling_policy" "memory" {
  name               = "memory-target-tracking"
  policy_type        = "TargetTrackingScaling"
  resource_id        = aws_appautoscaling_target.ecs.resource_id
  scalable_dimension = aws_appautoscaling_target.ecs.scalable_dimension
  service_namespace  = aws_appautoscaling_target.ecs.service_namespace

  target_tracking_scaling_policy_configuration {
    target_value = 70
    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageMemoryUtilization"
    }
  }
}

# IAM OIDC provider for GitHub Actions
resource "aws_iam_openid_connect_provider" "github" {
  url = "https://token.actions.githubusercontent.com"
  client_id_list = ["sts.amazonaws.com"]
  thumbprint_list = ["6938fd4d98bab03faadb97b34396831e3780aea1"]
}

# IAM role for GitHub Actions
data "aws_iam_policy_document" "github_assume" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]
    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }
    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }
    condition {
      test     = "StringLike"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:${var.github_org}/*"]
    }
  }
}

resource "aws_iam_role" "github_actions" {
  name               = "github-actions-role"
  assume_role_policy = data.aws_iam_policy_document.github_assume.json
}

resource "aws_iam_policy" "github_actions" {
  name_prefix = "github-actions-policy-"
  description = "Policy for GitHub Actions CI/CD"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:PutImage",
          "ecr:InitiateLayerUpload",
          "ecr:UploadLayerPart",
          "ecr:CompleteLayerUpload"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ecs:RegisterTaskDefinition",
          "ecs:PassRole"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ecs:UpdateService",
          "ecs:ListTaskDefinitions",
          "ecs:DescribeTaskDefinition",
          "ecs:DeregisterTaskDefinition"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "github_actions" {
  role       = aws_iam_role.github_actions.name
  policy_arn = aws_iam_policy.github_actions.arn
}

# Custom IAM policy for VPC Flow Logs to publish to CloudWatch
resource "aws_iam_policy" "vpc_flow_logs" {
  name_prefix = "vpc-flow-logs-policy-"
  description = "Allows VPC Flow Logs to publish to CloudWatch Logs"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      }
    ]
  })
}

# VPC Flow Logs
resource "aws_cloudwatch_log_group" "vpc_flow" {
  name              = "/aws/vpc-flow-logs"
  retention_in_days = 30
  kms_key_id        = aws_kms_alias.cloudwatch.arn
}

data "aws_iam_policy_document" "vpc_flow_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "vpc_flow" {
  name_prefix = "vpc-flow-logs-role-"
  assume_role_policy = data.aws_iam_policy_document.vpc_flow_assume.json
}

resource "aws_iam_role_policy_attachment" "vpc_flow" {
  role       = aws_iam_role.vpc_flow.name
  policy_arn = aws_iam_policy.vpc_flow_logs.arn
}

resource "aws_flow_log" "main" {
  log_destination      = aws_cloudwatch_log_group.vpc_flow.arn
  iam_role_arn         = aws_iam_role.vpc_flow.arn
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
  max_aggregation_interval = 60

  tags = {
    Name = "main-vpc-flow-logs"
  }
}

# Import blocks to adopt existing resources
import {
  to = aws_iam_openid_connect_provider.github
  id = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:oidc-provider/token.actions.githubusercontent.com"
}

import {
  to = aws_cloudwatch_log_group.ecs
  id = "/ecs/main-cluster"
}

import {
  to = aws_cloudwatch_log_group.vpc_flow
  id = "/aws/vpc-flow-logs"
}

import {
  to = aws_iam_role.github_actions
  id = "github-actions-role"
}

import {
  to = aws_ecs_service.main
  id = "main-cluster/app-service"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "cluster_tag" {
  type    = string
  default = "default"
}

variable "enable_key_rotation" {
  type    = bool
  default = true
}

variable "machine_roles" {
  type    = map(set(string))
  default = {}
}

# ---------------------------------------------------------------------------
# KMS Key for Vault Unsealing
# ---------------------------------------------------------------------------
resource "aws_kms_key" "vault_seal" {
  description         = "resinstack:vault:seal:${var.cluster_tag}"
  enable_key_rotation = var.enable_key_rotation
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# KMS Key for Secrets Manager Secrets
# ---------------------------------------------------------------------------
resource "aws_kms_key" "secrets" {
  description         = "resinstack:secrets:${var.cluster_tag}"
  enable_key_rotation = true
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Secrets Manager Secrets and Random Passwords
# ---------------------------------------------------------------------------
locals {
  secret_ids = {
    consul_agent_token       = "consul-agent-token"
    consul_gossip_key        = "consul-gossip-key"
    nomad_client_consul_token = "nomad-client-consul-token"
    nomad_gossip_key         = "nomad-gossip-key"
    nomad_server_consul_token = "nomad-server-consul-token"
    nomad_vault_token        = "nomad-vault-token"
    vault_consul_token       = "vault-consul-token"
  }
}

resource "aws_secretsmanager_secret" "hashi_stack" {
  for_each               = local.secret_ids
  name_prefix            = "resinstack-${each.value}-${var.cluster_tag}-"
  kms_key_id             = aws_kms_key.secrets.arn
  recovery_window_in_days = 0
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "random_password" "secret_value" {
  for_each = local.secret_ids
  length   = 64
  special  = true
}

resource "aws_secretsmanager_secret_version" "secret_value" {
  for_each      = local.secret_ids
  secret_id     = aws_secretsmanager_secret.hashi_stack[each.key].id
  secret_string = random_password.secret_value[each.key].result
}

# ---------------------------------------------------------------------------
# IAM Policies
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "vault_kms" {
  name_prefix = "ResinStackVaultKMS-"
  description = "Allows Vault to encrypt/decrypt/describe the KMS key for unsealing"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["kms:Encrypt", "kms:Decrypt", "kms:DescribeKey"]
        Resource = aws_kms_key.vault_seal.arn
      }
    ]
  })
}

resource "aws_iam_policy" "read_tags" {
  name_prefix = "ResinStackReadTags-"
  description = "Allows reading EC2 instance tags"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["ec2:DescribeInstances"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "client_keys" {
  name_prefix = "ResinStackClientKeys-"
  description = "Allows clients to retrieve required secret values"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = [
          aws_secretsmanager_secret.hashi_stack["consul_agent_token"].arn,
          aws_secretsmanager_secret.hashi_stack["consul_gossip_key"].arn,
          aws_secretsmanager_secret.hashi_stack["nomad_client_consul_token"].arn,
        ]
      }
    ]
  })
}

resource "aws_iam_policy" "nomad_keys" {
  name_prefix = "ResinStackNomadKeys-"
  description = "Allows Nomad servers to retrieve required secret values"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = [
          aws_secretsmanager_secret.hashi_stack["consul_agent_token"].arn,
          aws_secretsmanager_secret.hashi_stack["consul_gossip_key"].arn,
          aws_secretsmanager_secret.hashi_stack["nomad_gossip_key"].arn,
          aws_secretsmanager_secret.hashi_stack["nomad_server_consul_token"].arn,
          aws_secretsmanager_secret.hashi_stack["nomad_vault_token"].arn,
        ]
      }
    ]
  })
}

resource "aws_iam_policy" "consul_keys" {
  name_prefix = "ResinStackConsulKeys-"
  description = "Allows Consul servers to retrieve required secret values"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = [
          aws_secretsmanager_secret.hashi_stack["consul_gossip_key"].arn,
        ]
      }
    ]
  })
}

resource "aws_iam_policy" "vault_keys" {
  name_prefix = "ResinStackVaultKeys-"
  description = "Allows Vault servers to retrieve required secret values"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = [
          aws_secretsmanager_secret.hashi_stack["consul_gossip_key"].arn,
          aws_secretsmanager_secret.hashi_stack["vault_consul_token"].arn,
        ]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# IAM Roles and Instance Profiles
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "role" {
  for_each           = var.machine_roles
  name               = "resinstack-${each.key}-${var.cluster_tag}"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  max_session_duration = 43200
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

resource "aws_iam_instance_profile" "profile" {
  for_each = var.machine_roles
  name     = "resinstack-${each.key}-${var.cluster_tag}"
  role     = aws_iam_role.role[each.key].name
}

# ---------------------------------------------------------------------------
# Dynamic Policy Attachments
# ---------------------------------------------------------------------------
locals {
  policy_map = {
    vault-kms   = aws_iam_policy.vault_kms.arn
    read-tags   = aws_iam_policy.read_tags.arn
    client-keys = aws_iam_policy.client_keys.arn
    nomad-keys  = aws_iam_policy.nomad_keys.arn
    consul-keys = aws_iam_policy.consul_keys.arn
    vault-keys  = aws_iam_policy.vault_keys.arn
  }

  role_attachments = flatten([
    for role_name, policies in var.machine_roles : [
      for policy_id in policies : {
        role_name  = role_name
        policy_id  = policy_id
        policy_arn = try(local.policy_map[policy_id], null)
      } if try(local.policy_map[policy_id], null) != null
    ]
  ])
}

resource "aws_iam_role_policy_attachment" "attach" {
  for_each = {
    for att in local.role_attachments : "${att.role_name}-${att.policy_id}" => att
  }
  role       = aws_iam_role.role[each.value.role_name].name
  policy_arn = each.value.policy_arn
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "vault_kms_key_id" {
  value = aws_kms_key.vault_seal.key_id
}

output "secret_names" {
  value = {
    for id, secret in aws_secretsmanager_secret.hashi_stack : id => secret.name
  }
}

output "machine_role_names" {
  value = {
    for role_name, role in aws_iam_role.role : role_name => role.name
  }
}

output "instance_profile_names" {
  value = {
    for role_name, profile in aws_iam_instance_profile.profile : role_name => profile.name
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment_prefix" {
  description = "Prefix for resource naming and tagging"
  type        = string
  default     = "elluis_codes_limited_network"
}

variable "az_subnet_offsets" {
  description = "Map of Availability Zone names to subnet CIDR offsets"
  type        = map(number)
  default = {
    "us-east-1a" = 11
    "us-east-1b" = 22
    "us-east-1c" = 33
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "64.0.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.environment_prefix
  }
}

# Data sources for account ID and region (used in KMS key policy)
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# KMS key for CloudWatch Log Group encryption
resource "aws_kms_key" "flow_logs" {
  description             = "KMS key for VPC Flow Logs CloudWatch Log Group"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Principal = {
          AWS = "*"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = data.aws_caller_identity.current.account_id
          }
        }
      },
      {
        Sid    = "Allow CloudWatch Logs Service"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "${var.environment_prefix}-flow-logs-key"
  }
}

# KMS key alias
resource "aws_kms_alias" "flow_logs" {
  name          = "alias/${var.environment_prefix}-flow-logs"
  target_key_id = aws_kms_key.flow_logs.key_id
}

# CloudWatch Log Group for VPC Flow Logs (encrypted with CMK)
resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = "${var.environment_prefix}-flow-logs"
  retention_in_days = 30
  kms_key_id        = aws_kms_alias.flow_logs.arn

  tags = {
    Name = "${var.environment_prefix}-flow-logs"
  }
}

# IAM Role for VPC Flow Logs
resource "aws_iam_role" "flow_logs" {
  name = "${var.environment_prefix}-flow-logs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${var.environment_prefix}-flow-logs-role"
  }
}

# IAM Policy for VPC Flow Logs to publish to CloudWatch
resource "aws_iam_role_policy" "flow_logs" {
  name = "${var.environment_prefix}-flow-logs-policy"
  role = aws_iam_role.flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      }
    ]
  })
}

# VPC Flow Logs
resource "aws_flow_log" "main" {
  iam_role_arn    = aws_iam_role.flow_logs.arn
  log_destination = aws_cloudwatch_log_group.flow_logs.arn
  traffic_type    = "ALL"
  vpc_id          = aws_vpc.main.id

  tags = {
    Name = "${var.environment_prefix}-flow-logs"
  }
}

# Public subnets (one per AZ)
resource "aws_subnet" "public" {
  for_each = var.az_subnet_offsets

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, each.value)
  availability_zone       = each.key
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.environment_prefix}-public-${each.key}"
  }
}

# Private subnets (one per AZ)
resource "aws_subnet" "private" {
  for_each = var.az_subnet_offsets

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, each.value + 100) # Use offset+100 to avoid overlap
  availability_zone       = each.key
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.environment_prefix}-private-${each.key}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.environment_prefix}-igw"
  }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.environment_prefix}-public-rt"
  }

  lifecycle {
    ignore_changes = [route]
  }
}

# Associate each public subnet with the public route table
resource "aws_route_table_association" "public" {
  for_each = var.az_subnet_offsets

  subnet_id      = aws_subnet.public[each.key].id
  route_table_id = aws_route_table.public.id
}

# Elastic IPs for NAT Gateways (one per AZ)
resource "aws_eip" "nat" {
  for_each = var.az_subnet_offsets

  domain = "vpc"

  tags = {
    Name = "${var.environment_prefix}-nat-eip-${each.key}"
  }
}

# NAT Gateways (one per AZ, placed in corresponding public subnet)
resource "aws_nat_gateway" "main" {
  for_each = var.az_subnet_offsets

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.public[each.key].id

  tags = {
    Name = "${var.environment_prefix}-nat-${each.key}"
  }

  lifecycle {
    ignore_changes = [subnet_id]
  }
}

# Private route tables (one per AZ)
resource "aws_route_table" "private" {
  for_each = var.az_subnet_offsets

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[each.key].id
  }

  tags = {
    Name = "${var.environment_prefix}-private-rt-${each.key}"
  }

  lifecycle {
    ignore_changes = [route]
  }
}

# Associate each private subnet with its AZ-specific private route table
resource "aws_route_table_association" "private" {
  for_each = var.az_subnet_offsets

  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[each.key].id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "creation_token" {
  description = "Unique creation token for the EFS file system"
  type        = string
  default     = "test-efs"
}

variable "performance_mode" {
  description = "Performance mode for the EFS file system"
  type        = string
  default     = "generalPurpose"
}

variable "throughput_mode" {
  description = "Throughput mode for the EFS file system"
  type        = string
  default     = "bursting"
}

variable "lifecycle_policy_transition_days" {
  description = "Number of days after which files transition to IA storage class"
  type        = number
  default     = 30
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

resource "random_id" "this" {
  byte_length = 8
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "efs-vpc"
  }
}

resource "aws_subnet" "efs" {
  count = length(data.aws_availability_zones.available.names)

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "efs-subnet-${count.index}"
  }
}

resource "aws_security_group" "efs" {
  name_prefix = "efs-mount-target-"
  description = "Security group for EFS mount targets"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS from VPC"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "efs-security-group"
  }
}

resource "aws_kms_key" "this" {
  description             = "KMS key for EFS encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  rotation_period_in_days = 365

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Allow root account full access"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_file_system" "this" {
  creation_token   = "${var.creation_token}-${random_id.this.hex}"
  performance_mode = var.performance_mode
  throughput_mode  = var.throughput_mode
  encrypted        = true
  kms_key_id       = aws_kms_key.this.arn

  lifecycle_policy {
    transition_to_ia = "AFTER_${var.lifecycle_policy_transition_days}_DAYS"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_mount_target" "this" {
  count = length(aws_subnet.efs)

  file_system_id  = aws_efs_file_system.this.id
  subnet_id       = aws_subnet.efs[count.index].id
  security_groups = [aws_security_group.efs.id]
}

resource "aws_cloudwatch_log_group" "efs_flow_log" {
  name              = "/aws/vpc/flow-logs/efs-vpc-${random_id.this.hex}"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.this.arn

  tags = {
    Name = "efs-flow-log-group"
  }
}

resource "aws_iam_role" "efs_flow_log" {
  name_prefix = "efs-flow-log-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "efs_flow_log" {
  name = "efs-flow-log-policy"
  role = aws_iam_role.efs_flow_log.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_flow_log" "this" {
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.efs_flow_log.arn
  iam_role_arn         = aws_iam_role.efs_flow_log.arn
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "iam_user_name" {
  type    = string
  default = "cert-manager"
}

variable "hosted_zone_id" {
  type    = string
  default = "*"
}

resource "aws_iam_user" "cert_manager" {
  name = var.iam_user_name
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_access_key" "cert_manager" {
  user = aws_iam_user.cert_manager.name
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ssm_parameter" "access_key" {
  name  = "/cert-manager/access-key"
  type  = "SecureString"
  value = aws_iam_access_key.cert_manager.id
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ssm_parameter" "secret_key" {
  name  = "/cert-manager/secret-key"
  type  = "SecureString"
  value = aws_iam_access_key.cert_manager.secret
  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "cert_manager_route53" {
  statement {
    actions   = ["route53:GetChange"]
    resources = ["arn:aws:route53:::change/*"]
  }
  statement {
    actions   = ["route53:ChangeResourceRecordSets", "route53:ListResourceRecordSets"]
    resources = ["arn:aws:route53:::hostedzone/${var.hosted_zone_id}"]
  }
  statement {
    actions   = ["route53:ListHostedZonesByName"]
    resources = ["*"]
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

resource "random_id" "suffix" {
  byte_length = 4
}

variable "replica_region" {
  description = "Region for the replica S3 bucket"
  type        = string
  default     = "us-west-2"
}

variable "snapshot_retention" {
  description = "Toggle for EBS snapshot preservation mode"
  type        = bool
  default     = false
}

variable "ip_sets" {
  description = "Map of IP set definitions (name, format, local file path)"
  type = map(object({
    name   = string
    format = string
    file   = string
  }))
  default = {}
}

variable "threat_intel_sets" {
  description = "Map of threat intel set definitions (name, format, local file path)"
  type = map(object({
    name   = string
    format = string
    file   = string
  }))
  default = {}
}

variable "custom_filters" {
  description = "Map of custom GuardDuty filters"
  type = map(object({
    name   = string
    action = string
    rank   = number
    finding_criteria = map(object({
      field                = string
      equals               = optional(list(string))
      not_equals           = optional(list(string))
      greater_than         = optional(string)
      greater_than_or_equal = optional(string)
      less_than            = optional(string)
      less_than_or_equal   = optional(string)
    }))
  }))
  default = {}
}

variable "enable_publishing_destination" {
  description = "Enable GuardDuty publishing destination to S3"
  type        = bool
  default     = false
}

# GuardDuty Detector (adopt existing)
data "aws_guardduty_detector" "this" {}

# Null resource to update EBS snapshot preservation
resource "null_resource" "ebs_snapshot_preservation" {
  triggers = {
    detector_id = data.aws_guardduty_detector.this.id
    retention   = var.snapshot_retention
  }

  provisioner "local-exec" {
    command = <<EOT
      aws guardduty update-detector \
        --region us-east-1 \
        --cli-input-json '${jsonencode({
          DetectorId              = data.aws_guardduty_detector.this.id
          EbsSnapshotPreservation = var.snapshot_retention ? "RETENTION_WITH_FINDING" : "NO_RETENTION"
        })}'
    EOT
  }
}

# Primary KMS key (multi-region)
resource "aws_kms_key" "primary" {
  description             = "Multi-region key for GuardDuty artifacts"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  multi_region            = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "primary" {
  name_prefix   = "alias/guardduty-primary-"
  target_key_id = aws_kms_key.primary.key_id
}

# Primary S3 bucket for GuardDuty artifacts (with inline logging)
resource "aws_s3_bucket" "primary" {
  bucket = "guardduty-primary-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}-${random_id.suffix.hex}"

  logging {
    target_bucket = aws_s3_bucket.access_logs.id
    target_prefix = "access-logs/"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Dedicated S3 bucket for access logs (primary region)
resource "aws_s3_bucket" "access_logs" {
  bucket = "guardduty-access-logs-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}-${random_id.suffix.hex}"

  logging {
    target_bucket = aws_s3_bucket.log_archive.id
    target_prefix = "access-logs/"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Log archive bucket (terminal bucket for access logs)
resource "aws_s3_bucket" "log_archive" {
  bucket = "guardduty-log-archive-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}-${random_id.suffix.hex}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "log_archive" {
  bucket = aws_s3_bucket.log_archive.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log_archive" {
  bucket = aws_s3_bucket.log_archive.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "log_archive" {
  bucket = aws_s3_bucket.log_archive.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Bucket policy for log_archive to allow S3 log delivery service
resource "aws_s3_bucket_policy" "log_archive" {
  bucket = aws_s3_bucket.log_archive.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.log_archive.arn}/*"
      }
    ]
  })
}

# IAM role for S3 replication (with name_prefix)
resource "aws_iam_role" "replication" {
  name_prefix = "guardduty-s3-replication-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "replication" {
  name_prefix = "guardduty-s3-replication-policy-"
  description = "Policy for S3 replication between GuardDuty buckets"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/*"
        ]
      },
      {
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:GetObjectVersion"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.replica.arn,
          "${aws_s3_bucket.replica.arn}/*"
        ]
      },
      {
        Action = [
          "kms:Decrypt"
        ]
        Effect = "Allow"
        Resource = aws_kms_key.primary.arn
        Condition = {
          "StringLike" = {
            "kms:ViaService" = "s3.${data.aws_region.current.name}.amazonaws.com"
          }
        }
      },
      {
        Action = [
          "kms:Encrypt"
        ]
        Effect = "Allow"
        Resource = aws_kms_replica_key.replica.arn
        Condition = {
          "StringLike" = {
            "kms:ViaService" = "s3.${var.replica_region}.amazonaws.com"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

# Replica KMS key in replica region
resource "aws_kms_replica_key" "replica" {
  provider = aws.replica

  description             = "Replica key for GuardDuty replica bucket"
  primary_key_arn         = aws_kms_key.primary.arn
  deletion_window_in_days = 7

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "replica" {
  provider = aws.replica

  name_prefix   = "alias/guardduty-replica-"
  target_key_id = aws_kms_replica_key.replica.key_id
}

# Replica S3 bucket in replica region with local access logging
resource "aws_s3_bucket" "replica" {
  provider = aws.replica

  bucket = "guardduty-replica-${data.aws_caller_identity.current.account_id}-${var.replica_region}-${random_id.suffix.hex}"

  logging {
    target_bucket = aws_s3_bucket.replica_access_logs.id
    target_prefix = "replica-access-logs/"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_replica_key.replica.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Local access logs bucket for replica region
resource "aws_s3_bucket" "replica_access_logs" {
  provider = aws.replica

  bucket = "guardduty-replica-logs-${data.aws_caller_identity.current.account_id}-${var.replica_region}-${random_id.suffix.hex}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica_access_logs" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica_access_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica_access_logs" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica_access_logs.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_replica_key.replica.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "replica_access_logs" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica_access_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Bucket policy for replica_access_logs to allow S3 log delivery service
resource "aws_s3_bucket_policy" "replica_access_logs" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_access_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.replica_access_logs.arn}/*"
      }
    ]
  })
}

# S3 replication configuration on primary bucket
resource "aws_s3_bucket_replication_configuration" "primary" {
  depends_on = [aws_iam_role_policy_attachment.replication]

  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replication-rule"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.replica.arn
      storage_class = "STANDARD"

      replication_time {
        status = "Enabled"
        time {
          minutes = 15
        }
      }

      metrics {
        status = "Enabled"
        event_threshold {
          minutes = 15
        }
      }
    }
  }
}

# Data sources for account and region
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# Upload IP sets to S3 and create GuardDuty IP sets
resource "aws_s3_object" "ip_set" {
  for_each = var.ip_sets

  bucket = aws_s3_bucket.primary.id
  key    = "ip-sets/${each.key}.txt"
  source = each.value.file
  etag   = filemd5(each.value.file)
}

resource "aws_guardduty_ipset" "this" {
  for_each = var.ip_sets

  activate    = true
  detector_id = data.aws_guardduty_detector.this.id
  name        = each.value.name
  format      = each.value.format
  location    = "https://s3.${data.aws_region.current.name}.amazonaws.com/${aws_s3_bucket.primary.id}/${aws_s3_object.ip_set[each.key].key}"
}

# Upload threat intel sets to S3 and create GuardDuty threat intel sets
resource "aws_s3_object" "threat_intel_set" {
  for_each = var.threat_intel_sets

  bucket = aws_s3_bucket.primary.id
  key    = "threat-intel-sets/${each.key}.txt"
  source = each.value.file
  etag   = filemd5(each.value.file)
}

resource "aws_guardduty_threatintelset" "this" {
  for_each = var.threat_intel_sets

  activate    = true
  detector_id = data.aws_guardduty_detector.this.id
  name        = each.value.name
  format      = each.value.format
  location    = "https://s3.${data.aws_region.current.name}.amazonaws.com/${aws_s3_bucket.primary.id}/${aws_s3_object.threat_intel_set[each.key].key}"
}

# Custom GuardDuty filters
resource "aws_guardduty_filter" "this" {
  for_each = var.custom_filters

  detector_id = data.aws_guardduty_detector.this.id
  name        = each.value.name
  action      = each.value.action
  rank        = each.value.rank

  dynamic "finding_criteria" {
    for_each = length(var.custom_filters) > 0 ? [true] : []
    content {
      dynamic "criterion" {
        for_each = each.value.finding_criteria
        content {
          field                 = criterion.value.field
          equals                = criterion.value.equals
          not_equals            = criterion.value.not_equals
          greater_than          = criterion.value.greater_than
          greater_than_or_equal = criterion.value.greater_than_or_equal
          less_than             = criterion.value.less_than
          less_than_or_equal    = criterion.value.less_than_or_equal
        }
      }
    }
  }
}

# GuardDuty publishing destination
resource "aws_guardduty_publishing_destination" "this" {
  count = var.enable_publishing_destination ? 1 : 0

  detector_id     = data.aws_guardduty_detector.this.id
  destination_arn = aws_s3_bucket.primary.arn
  kms_key_arn     = aws_kms_key.primary.arn

  destination_type = "S3"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "name_prefix" {
  description = "Prefix applied to all IAM resource names"
  type        = string
  default     = "imputation-example"
}

variable "tags" {
  description = "Tags applied to all supported resources"
  type        = map(string)
  default     = {}
}

resource "aws_iam_role" "emr_service" {
  name = "${var.name_prefix}-emr-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "elasticmapreduce.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "emr_service" {
  role       = aws_iam_role.emr_service.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonElasticMapReduceRole"
}

resource "aws_iam_role" "emr_ec2" {
  name = "${var.name_prefix}-emr-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "emr_ec2_cloudwatch" {
  role       = aws_iam_role.emr_ec2.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_role_policy_attachment" "emr_ec2_ssm" {
  role       = aws_iam_role.emr_ec2.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_role" "emr_autoscaling" {
  name = "${var.name_prefix}-emr-autoscaling-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "application-autoscaling.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "emr_autoscaling" {
  role       = aws_iam_role.emr_autoscaling.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonElasticMapReduceforAutoScalingRole"
}

resource "aws_iam_instance_profile" "emr_ec2" {
  name = "${var.name_prefix}-emr-instance-profile"
  role = aws_iam_role.emr_ec2.name
  tags = var.tags
}

output "emr_service_role_arn" {
  value = aws_iam_role.emr_service.arn
}

output "emr_service_role_name" {
  value = aws_iam_role.emr_service.name
}

output "emr_service_role_unique_id" {
  value = aws_iam_role.emr_service.unique_id
}

output "emr_ec2_role_arn" {
  value = aws_iam_role.emr_ec2.arn
}

output "emr_ec2_role_name" {
  value = aws_iam_role.emr_ec2.name
}

output "emr_ec2_role_unique_id" {
  value = aws_iam_role.emr_ec2.unique_id
}

output "emr_autoscaling_role_arn" {
  value = aws_iam_role.emr_autoscaling.arn
}

output "emr_autoscaling_role_name" {
  value = aws_iam_role.emr_autoscaling.name
}

output "emr_autoscaling_role_unique_id" {
  value = aws_iam_role.emr_autoscaling.unique_id
}

output "emr_ec2_instance_profile_id" {
  value = aws_iam_instance_profile.emr_ec2.id
}

output "emr_ec2_instance_profile_arn" {
  value = aws_iam_instance_profile.emr_ec2.arn
}

output "emr_ec2_instance_profile_name" {
  value = aws_iam_instance_profile.emr_ec2.name
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "iam_user_name" {
  description = "Name for the IAM user"
  type        = string
  default     = "postman-user"
}

variable "cognito_user_pool_arn" {
  description = "ARN of a Cognito User Pool to grant AdminInitiateAuth (optional)"
  type        = string
  default     = ""
}

data "aws_iam_policy_document" "base" {
  statement {
    effect = "Allow"
    actions = [
      "apigateway:GET",
      "cloudwatch:GetMetricData",
      "cloudwatch:ListMetrics"
    ]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "cognito" {
  count = var.cognito_user_pool_arn != "" ? 1 : 0

  statement {
    effect = "Allow"
    actions = [
      "cognito-idp:AdminInitiateAuth"
    ]
    resources = [var.cognito_user_pool_arn]
  }
}

resource "aws_iam_user" "this" {
  name = var.iam_user_name
  path = "/"
}

resource "aws_iam_access_key" "this" {
  user = aws_iam_user.this.name
}

resource "aws_iam_group" "this" {
  name = "${var.iam_user_name}-group"
  path = "/"
}

resource "aws_iam_group_membership" "this" {
  name  = "${var.iam_user_name}-membership"
  group = aws_iam_group.this.name
  users = [aws_iam_user.this.name]
}

resource "aws_iam_group_policy" "base" {
  name   = "${var.iam_user_name}-base-policy"
  group  = aws_iam_group.this.name
  policy = data.aws_iam_policy_document.base.json
}

resource "aws_iam_group_policy" "cognito" {
  count  = var.cognito_user_pool_arn != "" ? 1 : 0
  name   = "${var.iam_user_name}-cognito-policy"
  group  = aws_iam_group.this.name
  policy = data.aws_iam_policy_document.cognito[0].json
}

module "enforce_mfa" {
  source  = "terraform-module/enforce-mfa/aws"
  version = "~> 1.0"
  groups  = [aws_iam_group.this.name]
}

output "iam_user_name" {
  description = "The name of the created IAM user"
  value       = aws_iam_user.this.name
}

output "access_key_id" {
  description = "The access key ID for the IAM user"
  value       = aws_iam_access_key.this.id
}

output "secret_access_key" {
  description = "The secret access key for the IAM user"
  value       = aws_iam_access_key.this.secret
  sensitive   = true
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "cluster_name" {
  description = "Name of the EKS cluster"
  type        = string
  default     = "legion"
}

# ------------------------------------------------------------------------------
# EKS Control Plane (Master) IAM Role
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "master_trust" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "master" {
  name               = "tf-${var.cluster_name}"
  assume_role_policy = data.aws_iam_policy_document.master_trust.json
}

resource "aws_iam_role_policy_attachment" "master_eks_cluster" {
  role       = aws_iam_role.master.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "master_eks_service" {
  role       = aws_iam_role.master.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
}

# ------------------------------------------------------------------------------
# Worker Node IAM Role
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "worker_trust" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "worker" {
  name               = "tf-${var.cluster_name}-node"
  assume_role_policy = data.aws_iam_policy_document.worker_trust.json
}

resource "aws_iam_role_policy_attachment" "worker_eks_worker" {
  role       = aws_iam_role.worker.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "worker_eks_cni" {
  role       = aws_iam_role.worker.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "worker_ecr_readonly" {
  role       = aws_iam_role.worker.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_instance_profile" "worker" {
  name = "tf-${var.cluster_name}-node"
  role = aws_iam_role.worker.name
}

# ------------------------------------------------------------------------------
# Custom Cluster Autoscaler Policy for Worker Nodes
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "autoscaling" {
  # Global describe actions – unrestricted
  statement {
    effect = "Allow"
    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeAutoScalingInstances",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeTags",
      "ec2:DescribeLaunchTemplateVersions"
    ]
    resources = ["*"]
  }

  # Capacity modification actions – restricted to tagged Auto Scaling groups
  statement {
    effect = "Allow"
    actions = [
      "autoscaling:SetDesiredCapacity",
      "autoscaling:TerminateInstanceInAutoScalingGroup",
      "autoscaling:UpdateAutoScalingGroup"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/kubernetes.io/cluster/${var.cluster_name}"
      values   = ["owned"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/k8s.io/cluster-autoscaler/enabled"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "autoscaling" {
  name   = "eks-worker-autoscaling-${var.cluster_name}"
  policy = data.aws_iam_policy_document.autoscaling.json
}

resource "aws_iam_role_policy_attachment" "worker_autoscaling" {
  role       = aws_iam_role.worker.name
  policy_arn = aws_iam_policy.autoscaling.arn
}

terraform {
  required_version = "~> 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_cidr" {
  type    = string
  default = "172.69.0.0/16"
}

variable "public_subnet_cidr" {
  type    = string
  default = "172.69.1.0/24"
}

variable "private_subnet_cidr" {
  type    = string
  default = "172.69.2.0/24"
}

variable "vpc_name" {
  type    = string
  default = "vpc_name"
}

variable "public_subnet" {
  type    = string
  default = "public_subnet"
}

variable "private_subnet" {
  type    = string
  default = "private_subnet"
}

variable "igw_tag" {
  type    = string
  default = "igw_tag"
}

variable "rtb_tag" {
  type    = string
  default = "rtb_tag"
}

variable "web_server_security_group" {
  type    = string
  default = "web-server_security_group"
}

variable "database_security_group" {
  type    = string
  default = "database_security_group"
}

variable "web_server_ingress_rules" {
  type = list(object({
    port        = number
    protocol    = string
    cidr_blocks = list(string)
  }))

  default = [
    {
      port        = 80
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    },
    {
      port        = 22
      protocol    = "tcp"
      cidr_blocks = ["172.69.0.0/16"]
    },
  ]
}

locals {
  vpc_cidr = aws_vpc.main.cidr_block
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = var.public_subnet
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = var.private_subnet
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.igw_tag
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = var.rtb_tag
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "web_server" {
  name        = "webserver-sg_${aws_vpc.main.id}"
  description = "Security group for web server workloads"
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.web_server_ingress_rules

    content {
      description = "Ingress for port ${ingress.value.port}"
      from_port   = ingress.value.port
      to_port     = ingress.value.port
      protocol    = ingress.value.protocol
      cidr_blocks = ingress.value.port == 22 ? [local.vpc_cidr] : ingress.value.cidr_blocks
    }
  }

  egress {
    description = "Outbound traffic within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = var.web_server_security_group
  }
}

resource "aws_security_group" "database" {
  name        = "database-sg_${aws_vpc.main.id}"
  description = "Security group for database workloads"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "MySQL access from web servers"
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.web_server.id]
  }

  egress {
    description = "Outbound traffic within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = var.database_security_group
  }
}

resource "aws_cloudwatch_log_group" "flow_log" {
  name       = "/aws/vpc-flow-logs/${aws_vpc.main.id}"
  kms_key_id = aws_kms_key.flow_log.arn
}

resource "aws_kms_key" "flow_log" {
  description             = "KMS key for VPC flow log CloudWatch Logs encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-policy-flow-log"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/vpc-flow-logs/*"
          }
        }
      }
    ]
  })

  tags = {
    Name = "vpc-flow-log-key"
  }
}

resource "aws_kms_alias" "flow_log" {
  name_prefix   = "alias/vpc-flow-logs-"
  target_key_id = aws_kms_key.flow_log.id
}

resource "aws_iam_role" "flow_log" {
  name = "vpc-flow-logs-role-${aws_vpc.main.id}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "flow_log" {
  name = "vpc-flow-logs-policy-${aws_vpc.main.id}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [aws_cloudwatch_log_group.flow_log.arn]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "flow_log" {
  role       = aws_iam_role.flow_log.name
  policy_arn = aws_iam_policy.flow_log.arn
}

resource "aws_flow_log" "main" {
  iam_role_arn    = aws_iam_role.flow_log.arn
  log_destination = aws_cloudwatch_log_group.flow_log.arn
  traffic_type    = "ALL"
  vpc_id          = aws_vpc.main.id

  depends_on = [
    aws_iam_role_policy_attachment.flow_log
  ]
}

