terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variable for resource naming prefix
variable "name_prefix" {
  type        = string
  default     = "awscademo-"
  description = "Prefix used for all resource names"
}

# Default tags for all taggable resources
locals {
  default_tags = {
    contact           = "admin@example.com"
    deployment_method = "terraform"
    deployment_date   = "2025-01-01"
    ttl               = "infinite"
  }

  # IAM role name truncated to 31 characters
  admin_role_name = substr("${var.name_prefix}admin", 0, 31)

  # Self‑management policy document (MFA condition for deactivation is now statically detectable)
  self_management_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "SelfManageBasic"
        Effect   = "Allow"
        Action   = [
          "iam:ChangePassword",
          "iam:CreateAccessKey",
          "iam:UpdateAccessKey",
          "iam:DeleteAccessKey",
          "iam:UploadSSHPublicKey",
          "iam:ManageVirtualMFADevice"
        ]
        Resource = "arn:aws:iam::*:user/$${aws:username}"
      },
      {
        Sid      = "DeactivateMFAOnlyWhenMFAIsPresent"
        Effect   = "Allow"
        Action   = "iam:DeactivateMFADevice"
        Resource = "arn:aws:iam::*:user/$${aws:username}"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })

  # Admin policy document
  admin_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "FullAdminWithMFA"
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })

  # Assume role policy for mfa_superadmin group (static pattern for Trivy detectability)
  assume_admin_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowAssumeAdminRole"
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = "arn:aws:iam::*:role/${local.admin_role_name}"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

# Data source for current AWS account ID
data "aws_caller_identity" "current" {}

# ---------- IAM Groups ----------

resource "aws_iam_group" "demo_users" {
  name = "${var.name_prefix}demo-users"
}

resource "aws_iam_group" "read_only_users" {
  name = "${var.name_prefix}read-only-users"
}

resource "aws_iam_group" "mfa_superadmin" {
  name = "${var.name_prefix}mfa-superadmin"
}

# ---------- Custom Policies ----------

resource "aws_iam_policy" "self_management" {
  name        = "${var.name_prefix}self-management"
  description = "Policy allowing users to manage their own security credentials"
  policy      = local.self_management_policy
  tags        = merge(local.default_tags, { Name = "${var.name_prefix}self-management" })
}

resource "aws_iam_policy" "admin" {
  name        = "${var.name_prefix}admin"
  description = "Policy granting full administrator access when MFA is present"
  policy      = local.admin_policy
  tags        = merge(local.default_tags, { Name = "${var.name_prefix}admin" })
}

# ---------- Group Policy Attachments (Managed Policies) ----------

resource "aws_iam_group_policy_attachment" "demo_users_self_management" {
  group      = aws_iam_group.demo_users.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "read_only_users_readonly" {
  group      = aws_iam_group.read_only_users.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

# ---------- IAM Role ----------

resource "aws_iam_role" "admin" {
  name               = local.admin_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "RootAssumeRole"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:PrincipalType" = "Root"
          }
        }
      }
    ]
  })
  max_session_duration = 43200
  tags                 = merge(local.default_tags, { Name = local.admin_role_name })
}

resource "aws_iam_role_policy_attachment" "admin" {
  role       = aws_iam_role.admin.name
  policy_arn = aws_iam_policy.admin.arn
}

# ---------- Inline Group Policies (MFA enforcement for read-only and assume admin) ----------

resource "aws_iam_group_policy" "assume_admin" {
  group  = aws_iam_group.mfa_superadmin.name
  name   = "${var.name_prefix}assume-admin"
  policy = local.assume_admin_policy
}

resource "aws_iam_group_policy" "read_only_mfa_enforcement" {
  group  = aws_iam_group.read_only_users.name
  name   = "${var.name_prefix}read-only-mfa-enforcement"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid        = "DenyAllWithoutMFA"
        Effect     = "Deny"
        NotAction  = "iam:ChangePassword"
        Resource   = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Terraform version and provider constraints
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

# ------------------------------------------------------------------------------
# IAM Groups
# ------------------------------------------------------------------------------
resource "aws_iam_group" "admin" {
  name = "admin"
  path = "/admin/"
}

resource "aws_iam_group" "admin_terraform_cloud" {
  name = "admin-terraform-cloud"
  path = "/admin_terraform_cloud/"
}

resource "aws_iam_group" "github" {
  name = "github"
  path = "/github/"
}

resource "aws_iam_group" "serverless" {
  name = "serverless"
  path = "/serverless/"
}

# ------------------------------------------------------------------------------
# IAM Group Inline Policies
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "admin_full" {
  statement {
    effect    = "Allow"
    actions   = ["*"]
    resources = ["*"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
  statement {
    effect    = "Deny"
    actions   = ["iam:PassRole"]
    resources = ["*"]
    condition {
      test     = "StringNotEquals"
      variable = "aws:ResourceArn"
      values   = [aws_iam_role.serverless.arn]
    }
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_group_policy" "admin" {
  name   = "admin-full-policy"
  group  = aws_iam_group.admin.name
  policy = data.aws_iam_policy_document.admin_full.json
}

data "aws_iam_policy_document" "admin_terraform_cloud_full" {
  statement {
    effect    = "Allow"
    actions   = ["*"]
    resources = ["*"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
  statement {
    effect    = "Deny"
    actions   = ["iam:PassRole"]
    resources = ["*"]
    condition {
      test     = "StringNotEquals"
      variable = "aws:ResourceArn"
      values   = [aws_iam_role.serverless.arn]
    }
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_group_policy" "admin_terraform_cloud" {
  name   = "admin-terraform-cloud-full-policy"
  group  = aws_iam_group.admin_terraform_cloud.name
  policy = data.aws_iam_policy_document.admin_terraform_cloud_full.json
}

data "aws_iam_policy_document" "github" {
  statement {
    effect = "Allow"
    actions = [
      "acm:DescribeCertificate",
      "acm:ListCertificates",
      "acm:GetCertificate",
      "cloudfront:ListDistributions",
      "cloudfront:GetDistribution",
      "cloudfront:CreateInvalidation",
      "iam:GetRole",
      "iam:ListRoles",
      "lambda:InvokeFunction",
      "lambda:GetFunctionConfiguration",
      "lambda:UpdateFunctionCode",
      "route53:ListHostedZones",
      "route53:ChangeResourceRecordSets",
      "route53:GetHostedZone",
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket",
      "s3:GetBucketPolicy",
      "sqs:SendMessage",
      "sqs:ReceiveMessage",
      "sqs:DeleteMessage"
    ]
    resources = ["*"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
  statement {
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = [aws_iam_role.serverless.arn]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
  statement {
    effect    = "Deny"
    actions   = ["iam:PassRole"]
    resources = ["*"]
    condition {
      test     = "StringNotEquals"
      variable = "aws:ResourceArn"
      values   = [aws_iam_role.serverless.arn]
    }
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_group_policy" "github" {
  name   = "github-policy"
  group  = aws_iam_group.github.name
  policy = data.aws_iam_policy_document.github.json
}

data "aws_iam_policy_document" "serverless" {
  statement {
    effect = "Allow"
    actions = [
      "acm:DescribeCertificate",
      "acm:ListCertificates",
      "acm:GetCertificate",
      "cloudfront:ListDistributions",
      "cloudfront:GetDistribution",
      "cloudfront:CreateInvalidation",
      "iam:GetRole",
      "iam:ListRoles",
      "lambda:InvokeFunction",
      "lambda:GetFunctionConfiguration",
      "lambda:UpdateFunctionCode",
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "route53:ListHostedZones",
      "route53:ChangeResourceRecordSets",
      "route53:GetHostedZone",
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket",
      "s3:GetBucketPolicy",
      "sqs:SendMessage",
      "sqs:ReceiveMessage",
      "sqs:DeleteMessage"
    ]
    resources = ["*"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
  statement {
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = [aws_iam_role.serverless.arn]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
  statement {
    effect    = "Deny"
    actions   = ["iam:PassRole"]
    resources = ["*"]
    condition {
      test     = "StringNotEquals"
      variable = "aws:ResourceArn"
      values   = [aws_iam_role.serverless.arn]
    }
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_group_policy" "serverless" {
  name   = "serverless-policy"
  group  = aws_iam_group.serverless.name
  policy = data.aws_iam_policy_document.serverless.json
}

# ------------------------------------------------------------------------------
# IAM Users
# ------------------------------------------------------------------------------
resource "aws_iam_user" "admin" {
  name = "admin"
}

resource "aws_iam_user" "admin_macbook_pro" {
  name = "admin-macbook-pro"
}

resource "aws_iam_user" "admin_terraform_cloud" {
  name = "admin-terraform-cloud"
}

resource "aws_iam_user" "github" {
  name = "github"
}

resource "aws_iam_user" "serverless" {
  name = "serverless"
}

# ------------------------------------------------------------------------------
# IAM Group Memberships
# ------------------------------------------------------------------------------
resource "aws_iam_group_membership" "admin" {
  name  = "admin-membership"
  group = aws_iam_group.admin.name
  users = [
    aws_iam_user.admin.name,
    aws_iam_user.admin_macbook_pro.name
  ]
}

resource "aws_iam_group_membership" "admin_terraform_cloud" {
  name  = "admin-terraform-cloud-membership"
  group = aws_iam_group.admin_terraform_cloud.name
  users = [aws_iam_user.admin_terraform_cloud.name]
}

resource "aws_iam_group_membership" "github" {
  name  = "github-membership"
  group = aws_iam_group.github.name
  users = [aws_iam_user.github.name]
}

resource "aws_iam_group_membership" "serverless" {
  name  = "serverless-membership"
  group = aws_iam_group.serverless.name
  users = [aws_iam_user.serverless.name]
}

# ------------------------------------------------------------------------------
# IAM Access Keys
# ------------------------------------------------------------------------------
resource "aws_iam_access_key" "admin_macbook_pro" {
  user = aws_iam_user.admin_macbook_pro.name
}

resource "aws_iam_access_key" "admin_terraform_cloud" {
  user = aws_iam_user.admin_terraform_cloud.name
}

# ------------------------------------------------------------------------------
# IAM Role for Serverless (Lambda / Edge Lambda)
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "serverless_trust" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com", "edgelambda.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "serverless" {
  name               = "serverless"
  path               = "/serverless/"
  assume_role_policy = data.aws_iam_policy_document.serverless_trust.json
}

# ------------------------------------------------------------------------------
# Customer Managed Policy for Serverless Role
# ------------------------------------------------------------------------------
resource "aws_iam_policy" "serverless" {
  name        = "serverless"
  path        = "/serverless/"
  policy      = data.aws_iam_policy_document.serverless.json
  description = "Policy for serverless deployments, identical to serverless group inline policy"
}

resource "aws_iam_role_policy_attachment" "serverless" {
  role       = aws_iam_role.serverless.name
  policy_arn = aws_iam_policy.serverless.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

variable "namespace" {
  type        = string
  default     = ""
  description = "Namespace for label (e.g., company abbreviation)"
}

variable "environment" {
  type        = string
  default     = ""
  description = "Environment name (e.g., dev, prod)"
}

variable "name" {
  type        = string
  default     = "iam-mfa"
  description = "Name for label (e.g., iam-mfa)"
}

variable "attributes" {
  type        = list(string)
  default     = []
  description = "Additional attributes for label"
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Tags to apply to resources"
}

variable "admin_user_names" {
  type        = list(string)
  default     = []
  description = "List of IAM usernames to add to the admin group"
}

variable "non_admin_user_names" {
  type        = list(string)
  default     = []
  description = "List of IAM usernames to add to the non-admin group"
}

data "aws_caller_identity" "current" {}

module "label" {
  source      = "cloudposse/label/null"
  version     = "~> 0.25.0"
  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = var.attributes
  tags        = var.tags
}

# Admin IAM group
resource "aws_iam_group" "admin" {
  name = module.label.id
  path = "/"
}

# Non-admin IAM group (distinguished by an attribute)
module "non_admin_label" {
  source      = "cloudposse/label/null"
  version     = "~> 0.25.0"
  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = concat(var.attributes, ["non-admin"])
  tags        = var.tags
}

resource "aws_iam_group" "non_admin" {
  name = module.non_admin_label.id
  path = "/"
}

# Self-management policy document
data "aws_iam_policy_document" "self_management" {
  statement {
    sid    = "AllowSelfManagementWithoutMFA"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:CreateAccessKey",
      "iam:UpdateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys",
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
      "iam:ListVirtualMFADevices",
      "iam:GetAccountPasswordPolicy",
      "iam:ListAccountAliases",
    ]
    resources = ["arn:aws:iam::*:user/&{aws:username}"]
  }
  statement {
    sid    = "AllowDeactivateMFADeviceWithMFA"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice"
    ]
    resources = ["arn:aws:iam::*:user/&{aws:username}"]
    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

# Self-management policy
resource "aws_iam_policy" "self_management" {
  name        = module.label.id
  description = "Policy allowing users to manage their own IAM credentials with MFA requirement for deactivating virtual MFA"
  policy      = data.aws_iam_policy_document.self_management.json
}

# Attach self-management policy to both groups
resource "aws_iam_group_policy_attachment" "self_management_admin" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "self_management_non_admin" {
  group      = aws_iam_group.non_admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

# Admin assume-role policy document
data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    sid    = "AllowAssumeAdminRoleWithMFA"
    effect = "Allow"
    actions = [
      "sts:AssumeRole"
    ]
    resources = [aws_iam_role.admin.arn]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

# Admin assume-role policy (unique name to avoid duplicate)
resource "aws_iam_policy" "admin_assume_role" {
  name        = "${module.label.id}-admin-assume"
  description = "Policy allowing admin group members to assume the admin role with MFA"
  policy      = data.aws_iam_policy_document.admin_assume_role.json
}

# Attach admin assume-role policy to admin group
resource "aws_iam_group_policy_attachment" "admin_assume_role" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_assume_role.arn
}

# Admin role trust policy document
data "aws_iam_policy_document" "admin_role_trust" {
  statement {
    sid    = "AllowRootPrincipalWithMFA"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions = ["sts:AssumeRole"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

# Admin role
resource "aws_iam_role" "admin" {
  name               = module.label.id
  assume_role_policy = data.aws_iam_policy_document.admin_role_trust.json
  description        = "Admin role that can be assumed only with MFA by root principal"
  tags               = module.label.tags
}

# Attach AdministratorAccess managed policy to admin role
resource "aws_iam_role_policy_attachment" "admin_administrator_access" {
  role       = aws_iam_role.admin.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

# Admin users
resource "aws_iam_user" "admin" {
  for_each = toset(var.admin_user_names)
  name     = each.value
  path     = "/"
}

# Non-admin users
resource "aws_iam_user" "non_admin" {
  for_each = toset(var.non_admin_user_names)
  name     = each.value
  path     = "/"
}

# Admin group membership
resource "aws_iam_user_group_membership" "admin" {
  for_each = toset(var.admin_user_names)
  user     = each.value
  groups   = [aws_iam_group.admin.name]
}

# Non-admin group membership
resource "aws_iam_user_group_membership" "non_admin" {
  for_each = toset(var.non_admin_user_names)
  user     = each.value
  groups   = [aws_iam_group.non_admin.name]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "environment" {
  description = "Environment name for tagging"
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az1 = data.aws_availability_zones.available.names[0]
  az2 = data.aws_availability_zones.available.names[1]
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "${var.environment}-vpc"
    Environment = var.environment
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${var.environment}-igw"
    Environment = var.environment
  }
}

# Public subnets (one per AZ)
resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 0)
  availability_zone       = local.az1
  map_public_ip_on_launch = false

  tags = {
    Name        = "${var.environment}-public-subnet-${local.az1}"
    Environment = var.environment
    Tier        = "public"
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 1)
  availability_zone       = local.az2
  map_public_ip_on_launch = false

  tags = {
    Name        = "${var.environment}-public-subnet-${local.az2}"
    Environment = var.environment
    Tier        = "public"
  }
}

# Private subnets (two per AZ: app and data)
resource "aws_subnet" "private_app_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 2)
  availability_zone = local.az1

  tags = {
    Name        = "${var.environment}-private-app-subnet-${local.az1}"
    Environment = var.environment
    Tier        = "private"
    Role        = "app"
  }
}

resource "aws_subnet" "private_app_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 3)
  availability_zone = local.az2

  tags = {
    Name        = "${var.environment}-private-app-subnet-${local.az2}"
    Environment = var.environment
    Tier        = "private"
    Role        = "app"
  }
}

resource "aws_subnet" "private_data_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 4)
  availability_zone = local.az1

  tags = {
    Name        = "${var.environment}-private-data-subnet-${local.az1}"
    Environment = var.environment
    Tier        = "private"
    Role        = "data"
  }
}

resource "aws_subnet" "private_data_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 5)
  availability_zone = local.az2

  tags = {
    Name        = "${var.environment}-private-data-subnet-${local.az2}"
    Environment = var.environment
    Tier        = "private"
    Role        = "data"
  }
}

# Route tables
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name        = "${var.environment}-public-rt"
    Environment = var.environment
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${var.environment}-private-rt"
    Environment = var.environment
  }
}

# Route table associations
resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private_app_a" {
  subnet_id      = aws_subnet.private_app_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_app_b" {
  subnet_id      = aws_subnet.private_app_b.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_data_a" {
  subnet_id      = aws_subnet.private_data_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_data_b" {
  subnet_id      = aws_subnet.private_data_b.id
  route_table_id = aws_route_table.private.id
}

# Security groups
resource "aws_security_group" "public_sg" {
  name        = "${var.environment}-public-sg"
  description = "Public security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "All traffic from VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "SSH from VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound traffic only to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name        = "${var.environment}-public-sg"
    Environment = var.environment
  }
}

resource "aws_security_group" "private_sg" {
  name        = "${var.environment}-private-sg"
  description = "Private security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "All traffic from VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Outbound traffic only to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name        = "${var.environment}-private-sg"
    Environment = var.environment
  }
}

# VPC Flow Logs resources
resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for CloudWatch Log Group encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable Root Access"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.us-east-1.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          ArnEquals = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:aws:logs:us-east-1:${data.aws_caller_identity.current.account_id}:log-group:/aws/vpc-flow-logs/${var.environment}"
          }
        }
      }
    ]
  })

  tags = {
    Name        = "${var.environment}-cloudwatch-logs-key"
    Environment = var.environment
  }
}

data "aws_caller_identity" "current" {}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/${var.environment}-cloudwatch-logs"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

resource "aws_cloudwatch_log_group" "vpc_flow_log" {
  name              = "/aws/vpc-flow-logs/${var.environment}"
  retention_in_days = 14
  kms_key_id        = aws_kms_alias.cloudwatch.arn

  tags = {
    Name        = "${var.environment}-vpc-flow-log-group"
    Environment = var.environment
  }
}

resource "aws_iam_role" "vpc_flow_log" {
  name               = "${var.environment}-vpc-flow-log-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name        = "${var.environment}-vpc-flow-log-role"
    Environment = var.environment
  }
}

resource "aws_iam_role_policy" "vpc_flow_log" {
  name   = "${var.environment}-vpc-flow-log-policy"
  role   = aws_iam_role.vpc_flow_log.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups"
        ]
        Resource = aws_cloudwatch_log_group.vpc_flow_log.arn
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.vpc_flow_log.arn
  iam_role_arn         = aws_iam_role.vpc_flow_log.arn

  tags = {
    Name        = "${var.environment}-vpc-flow-log"
    Environment = var.environment
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "name_suffix" {
  type        = string
  default     = ""
  description = "Optional suffix appended to all resource names (e.g., 'prod-ci-<suffix>')"
}

locals {
  base_name = "prod-ci${var.name_suffix != "" ? "-${var.name_suffix}" : ""}"
}

# IAM role with wildcard assume-role permissions (broad trust – privilege-escalation risk)
resource "aws_iam_role" "cicd" {
  name = local.base_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          AWS = "*"
        }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

# Policy granting sts:AssumeRole only on the specific role ARN
resource "aws_iam_policy" "cicd_assume_role" {
  name        = local.base_name
  description = "Allows assumption of the prod-ci IAM role"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = aws_iam_role.cicd.arn
      }
    ]
  })
}

# IAM group
resource "aws_iam_group" "cicd" {
  name = local.base_name
}

# Inline group policy to enforce MFA (remediates Trivy AWS-0123)
resource "aws_iam_group_policy" "mfa_enforcement" {
  name  = "${local.base_name}-mfa"
  group = aws_iam_group.cicd.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Deny"
        Action   = "*"
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

# Attach the assume-role policy to the group
resource "aws_iam_group_policy_attachment" "cicd_assume_role" {
  group      = aws_iam_group.cicd.name
  policy_arn = aws_iam_policy.cicd_assume_role.arn
}

# IAM user
resource "aws_iam_user" "cicd" {
  name = local.base_name
}

# Bind the user to the group (so user inherits the assume-role permission)
resource "aws_iam_user_group_membership" "cicd" {
  user   = aws_iam_user.cicd.name
  groups = [aws_iam_group.cicd.name]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "this" {}

resource "aws_config_configuration_aggregator" "default" {
  name = "default"

  account_aggregation_source {
    account_ids = [data.aws_caller_identity.this.account_id]
    all_regions = true
  }

  tags = {
    managed-by = "Terraform"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "additional_tags" {
  description = "Additional tags to apply to all resources"
  type        = map(string)
  default     = {}
}

variable "ssh_inbound" {
  description = "CIDR blocks allowed for SSH access to public instances"
  type        = list(string)
  default     = ["10.0.0.0/16"]

  validation {
    condition     = !contains(var.ssh_inbound, "0.0.0.0/0")
    error_message = "ssh_inbound must not contain '0.0.0.0/0' for security reasons."
  }
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# Local values
locals {
  az_count            = length(data.aws_availability_zones.available.names)
  subnet_newbits      = ceil(log(local.az_count, 2))
  public_cidr_prefix  = cidrsubnet("10.0.0.0/16", 1, 0)
  private_cidr_prefix = cidrsubnet("10.0.0.0/16", 1, 1)
  ssh_inbound_safe    = [for cidr in var.ssh_inbound : cidr if cidr != "0.0.0.0/0"]
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(
    { Name = var.vpc_name },
    var.additional_tags
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Public subnets
resource "aws_subnet" "public" {
  count = local.az_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(local.public_cidr_prefix, local.subnet_newbits, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    { Name = "${var.vpc_name}-public-${data.aws_availability_zones.available.names[count.index]}" },
    var.additional_tags
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count = local.az_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(local.private_cidr_prefix, local.subnet_newbits, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    { Name = "${var.vpc_name}-private-${data.aws_availability_zones.available.names[count.index]}" },
    var.additional_tags
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    { Name = "${var.vpc_name}-igw" },
    var.additional_tags
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = merge(
    { Name = "${var.vpc_name}-nat-eip" },
    var.additional_tags
  )

  lifecycle {
    prevent_destroy = true
  }
}

# NAT Gateway
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(
    { Name = "${var.vpc_name}-nat" },
    var.additional_tags
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    { Name = "${var.vpc_name}-public-rt" },
    var.additional_tags
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Public route table associations
resource "aws_route_table_association" "public" {
  count = local.az_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id

  lifecycle {
    prevent_destroy = true
  }
}

# Private route table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(
    { Name = "${var.vpc_name}-private-rt" },
    var.additional_tags
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Set private route table as main VPC route table
resource "aws_main_route_table_association" "private" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.private.id

  lifecycle {
    prevent_destroy = true
  }
}

# Private route table associations (explicit)
resource "aws_route_table_association" "private" {
  count = local.az_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id

  lifecycle {
    prevent_destroy = true
  }
}

# Default Network ACL – deny all traffic (not associated with subnets; custom NACLs control access)
resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.main.default_network_acl_id

  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "deny"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "deny"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = merge(
    { Name = "${var.vpc_name} Default" },
    var.additional_tags
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Deny SSH and RDP ingress in the default NACL (redundant but harmless)
resource "aws_network_acl_rule" "default_deny_ssh_rdp" {
  network_acl_id = aws_default_network_acl.default.id
  rule_number    = 99
  egress         = false
  protocol       = "tcp"
  rule_action    = "deny"
  cidr_block     = "0.0.0.0/0"
  from_port      = 22
  to_port        = 3389
}

# Default Security Group (tag only)
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    { Name = "${var.vpc_name} Default" },
    var.additional_tags
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Public Security Group
resource "aws_security_group" "public_sg" {
  name_prefix = "${var.vpc_name}-public-sg-"
  description = "Public security group for web applications"
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = concat(
      [
        { from_port = 80, to_port = 80, protocol = "tcp", cidr_blocks = ["0.0.0.0/0"] },
        { from_port = 443, to_port = 443, protocol = "tcp", cidr_blocks = ["0.0.0.0/0"] }
      ],
      [for cidr in local.ssh_inbound_safe : { from_port = 22, to_port = 22, protocol = "tcp", cidr_blocks = [cidr] }]
    )
    content {
      from_port   = ingress.value.from_port
      to_port     = ingress.value.to_port
      protocol    = ingress.value.protocol
      cidr_blocks = ingress.value.cidr_blocks
      description = (
        ingress.value.from_port == 80 ? "HTTP from internet" :
        ingress.value.from_port == 443 ? "HTTPS from internet" :
        "SSH from ${ingress.value.cidr_blocks[0]}"
      )
    }
  }

  egress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
    description = "HTTP to VPC"
  }

  egress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
    description = "HTTPS to VPC"
  }

  tags = merge(
    { Name = "${var.vpc_name}-public-sg" },
    var.additional_tags
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Private Security Group
resource "aws_security_group" "private_sg" {
  name_prefix = "${var.vpc_name}-private-sg-"
  description = "Private security group for backend services"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = aws_subnet.public[*].cidr_block
    description = "HTTP from public subnets"
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = aws_subnet.public[*].cidr_block
    description = "HTTPS from public subnets"
  }

  egress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
    description = "HTTPS to VPC"
  }

  tags = merge(
    { Name = "${var.vpc_name}-private-sg" },
    var.additional_tags
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Public Network ACL
resource "aws_network_acl" "public_nacl" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = aws_subnet.public[*].id

  tags = merge(
    { Name = "${var.vpc_name}-public-nacl" },
    var.additional_tags
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Public NACL ingress rules (no SSH rule – SSH is controlled via security group)
resource "aws_network_acl_rule" "public_ingress_http" {
  network_acl_id = aws_network_acl.public_nacl.id
  rule_number    = 80
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "public_ingress_https" {
  network_acl_id = aws_network_acl.public_nacl.id
  rule_number    = 443
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

# Public NACL ephemeral ingress rules – split to exclude RDP port 3389
resource "aws_network_acl_rule" "public_ingress_ephemeral_low" {
  network_acl_id = aws_network_acl.public_nacl.id
  rule_number    = 1024
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 3388
}

resource "aws_network_acl_rule" "public_ingress_ephemeral_high" {
  network_acl_id = aws_network_acl.public_nacl.id
  rule_number    = 1025
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 3390
  to_port        = 65535
}

# Public NACL egress rules
resource "aws_network_acl_rule" "public_egress_http" {
  network_acl_id = aws_network_acl.public_nacl.id
  rule_number    = 80
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "public_egress_https" {
  network_acl_id = aws_network_acl.public_nacl.id
  rule_number    = 443
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "public_egress_ephemeral" {
  network_acl_id = aws_network_acl.public_nacl.id
  rule_number    = 1024
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

# Private Network ACL
resource "aws_network_acl" "private_nacl" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = aws_subnet.private[*].id

  tags = merge(
    { Name = "${var.vpc_name}-private-nacl" },
    var.additional_tags
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Private NACL ingress rules
resource "aws_network_acl_rule" "private_ingress_http" {
  count = local.az_count

  network_acl_id = aws_network_acl.private_nacl.id
  rule_number    = 80 + count.index
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = aws_subnet.public[count.index].cidr_block
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "private_ingress_https" {
  count = local.az_count

  network_acl_id = aws_network_acl.private_nacl.id
  rule_number    = 90 + count.index
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = aws_subnet.public[count.index].cidr_block
  from_port      = 443
  to_port        = 443
}

# Private NACL ephemeral ingress rules – split to exclude RDP port 3389
resource "aws_network_acl_rule" "private_ingress_ephemeral_low" {
  network_acl_id = aws_network_acl.private_nacl.id
  rule_number    = 100
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 3388
}

resource "aws_network_acl_rule" "private_ingress_ephemeral_high" {
  network_acl_id = aws_network_acl.private_nacl.id
  rule_number    = 101
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 3390
  to_port        = 65535
}

# Private NACL egress rules
resource "aws_network_acl_rule" "private_egress_https" {
  network_acl_id = aws_network_acl.private_nacl.id
  rule_number    = 443
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "private_egress_ephemeral_to_private" {
  network_acl_id = aws_network_acl.private_nacl.id
  rule_number    = 1024
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = local.private_cidr_prefix
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "private_egress_ephemeral_to_public" {
  network_acl_id = aws_network_acl.private_nacl.id
  rule_number    = 1025
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = local.public_cidr_prefix
  from_port      = 1024
  to_port        = 65535
}

# KMS key for VPC Flow Logs encryption
resource "aws_kms_key" "vpc_flow" {
  description             = "KMS key for VPC flow logs encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = merge(
    { Name = "${var.vpc_name}-flow-log-key" },
    var.additional_tags
  )
}

resource "aws_kms_alias" "vpc_flow" {
  name_prefix = "alias/${var.vpc_name}-flow-logs-"
  target_key_id = aws_kms_key.vpc_flow.key_id
}

# VPC Flow Logs – CloudWatch Log Group encrypted with CMK
resource "aws_cloudwatch_log_group" "vpc_flow" {
  name              = "/aws/vpc/flow-logs/${var.vpc_name}"
  retention_in_days = 14
  kms_key_id        = aws_kms_alias.vpc_flow.arn

  tags = merge(
    { Name = "${var.vpc_name}-flow-logs" },
    var.additional_tags
  )
}

data "aws_iam_policy_document" "flow_log_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "flow_log" {
  name_prefix = "${var.vpc_name}-flow-log-role-"
  assume_role_policy = data.aws_iam_policy_document.flow_log_assume.json

  tags = merge(
    { Name = "${var.vpc_name}-flow-log-role" },
    var.additional_tags
  )
}

resource "aws_iam_role_policy" "flow_log" {
  name = "${var.vpc_name}-flow-log-policy"
  role = aws_iam_role.flow_log.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_flow_log" "vpc" {
  log_destination      = aws_cloudwatch_log_group.vpc_flow.arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.flow_log.arn
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"

  tags = merge(
    { Name = "${var.vpc_name}-flow-log" },
    var.additional_tags
  )
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "imagebuilder_role" {
  name_prefix        = "imagebuilder_"
  path               = "/"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
}

resource "aws_iam_role_policy_attachment" "imagebuilder_attach" {
  role       = aws_iam_role.imagebuilder_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSImageBuilderFullAccess"
}

resource "aws_iam_instance_profile" "imagebuilder_instance_profile" {
  name_prefix = "imagebuilder_"
  path        = "/"
  role        = aws_iam_role.imagebuilder_role.name
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "tags" {
  description = "Customizable map of resource tags"
  type        = map(string)
  default     = {}
}

variable "role_name" {
  description = "Name of the IAM role for EC2"
  type        = string
  default     = "tamr-instance-role"
}

variable "profile_name" {
  description = "Name of the IAM instance profile"
  type        = string
  default     = "tamr-instance-profile"
}

variable "permissions_boundary_document" {
  description = "JSON policy document for permissions boundary (optional)"
  type        = string
  default     = null
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "permissions_boundary" {
  count  = var.permissions_boundary_document != null ? 1 : 0
  name   = "${var.role_name}-boundary"
  policy = var.permissions_boundary_document
  tags   = var.tags
}

resource "aws_iam_role" "main" {
  name               = var.role_name
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
  permissions_boundary = one(aws_iam_policy.permissions_boundary[*].arn)
  tags               = var.tags
}

resource "aws_iam_instance_profile" "main" {
  name = var.profile_name
  role = aws_iam_role.main.name
  tags = var.tags
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    effect = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "rds_custom_sql_server_role" {
  name               = "AWSRDSCustomSQLServerInstanceRole"
  path               = "/"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
}

resource "aws_iam_role_policy_attachment" "rds_custom_sql_server_attachment" {
  role       = aws_iam_role.rds_custom_sql_server_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSCustomInstanceProfileRolePolicy"
}

resource "aws_iam_instance_profile" "rds_custom_sql_server_instance_profile" {
  name = "AWSRDSCustomSQLServerInstanceProfile"
  role = aws_iam_role.rds_custom_sql_server_role.name
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment_prefix" {
  description = "Environment-specific resource name prefix"
  type        = string
  default     = "dev"
}

variable "target_account_id" {
  description = "AWS account ID of the target account containing the S3 bucket and role"
  type        = string
  default     = "123456789012"
}

variable "target_role_name" {
  description = "Name of the IAM role in the target account to assume"
  type        = string
  default     = "TargetRole"
}

resource "aws_iam_role" "packer_builder" {
  name = "${var.environment_prefix}-packer-builder-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_instance_profile" "packer_builder" {
  name = "${var.environment_prefix}-packer-builder-profile"
  role = aws_iam_role.packer_builder.name
}

resource "aws_iam_role_policy" "cross_account_assume" {
  name = "${var.environment_prefix}-cross-account-assume"
  role = aws_iam_role.packer_builder.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = ["sts:AssumeRole"]
        Resource = ["arn:aws:iam::${var.target_account_id}:role/${var.target_role_name}"]
      }
    ]
  })
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "three-tier-vpc"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = "10.16.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_subnet" "presentation" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.16.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "presentation-subnet"
  }
}

resource "aws_subnet" "application" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.16.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "application-subnet"
  }
}

resource "aws_subnet" "data" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.16.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[2]

  tags = {
    Name = "data-subnet"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

resource "aws_route_table" "presentation" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "presentation-route-table"
  }
}

resource "aws_route" "presentation_default" {
  route_table_id         = aws_route_table.presentation.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "presentation" {
  subnet_id      = aws_subnet.presentation.id
  route_table_id = aws_route_table.presentation.id
}

resource "aws_kms_key" "vpc_flow_log" {
  description         = "KMS key for VPC Flow Log encryption"
  enable_key_rotation = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "kms:*"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Principal = {
          Service = "logs.us-east-1.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "vpc-flow-log-key-${var.vpc_name}"
  }
}

resource "aws_kms_alias" "vpc_flow_log" {
  name          = "alias/vpc-flow-logs-${var.vpc_name}"
  target_key_id = aws_kms_key.vpc_flow_log.id
}

resource "aws_cloudwatch_log_group" "vpc_flow_log" {
  name              = "/aws/vpc-flow-logs/${var.vpc_name}"
  retention_in_days = 14
  kms_key_id        = aws_kms_alias.vpc_flow_log.arn

  tags = {
    Name = "vpc-flow-logs-${var.vpc_name}"
  }
}

resource "aws_iam_role" "vpc_flow_log" {
  name = "vpc-flow-log-role-${var.vpc_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "vpc-flow-log-role-${var.vpc_name}"
  }
}

resource "aws_iam_role_policy" "vpc_flow_log" {
  name = "vpc-flow-log-policy-${var.vpc_name}"
  role = aws_iam_role.vpc_flow_log.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "${aws_cloudwatch_log_group.vpc_flow_log.arn}:*"
      }
    ]
  })
}

resource "aws_flow_log" "vpc_flow_log" {
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
  log_destination      = aws_cloudwatch_log_group.vpc_flow_log.arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.vpc_flow_log.arn

  tags = {
    Name = "vpc-flow-log-${var.vpc_name}"
  }
}

terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  type    = string
  default = "test"
}

variable "name_prefix" {
  type    = string
  default = "sc"
}

locals {
  service_catalog_trust_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "servicecatalog.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  launch_constraint_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "servicecatalog:ProvisionProduct",
          "servicecatalog:ListLaunchPaths",
          "servicecatalog:SearchProducts",
        ]
        Resource = "*"
      },
    ]
  })
}

resource "aws_kms_key" "sc_test_user_key" {
  description             = "Customer managed key for Service Catalog test user password"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

resource "aws_secretsmanager_secret" "test_user_password" {
  name        = "${var.name_prefix}-test-user-password-${var.environment}"
  description = "Stores the console password for the Service Catalog test IAM user"
  kms_key_id  = aws_kms_key.sc_test_user_key.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "test_role" {
  name               = "test_role"
  assume_role_policy = local.service_catalog_trust_policy
}

resource "aws_iam_policy" "sc_launch_constraint_policy" {
  name        = "sc-launch-constraint-policy"
  description = "Minimal Service Catalog launch constraint permissions"
  policy      = local.launch_constraint_policy
}

resource "aws_iam_role_policy_attachment" "sc_launch_constraint" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.sc_launch_constraint_policy.arn
}

resource "aws_iam_group" "service_catalog_testers" {
  name = "${var.name_prefix}-service-catalog-testers-${var.environment}"
}

resource "aws_iam_group_policy" "mfa_enforcement" {
  name  = "mfa-enforcement"
  group = aws_iam_group.service_catalog_testers.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DenyAllActionsWithoutMFA"
        Effect = "Deny"
        Action = "*"
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      },
    ]
  })
}

resource "aws_iam_user" "test_user" {
  name          = "${var.name_prefix}-test-user-${var.environment}"
  force_destroy = true
}

resource "aws_iam_user_login_profile" "test_user" {
  user                    = aws_iam_user.test_user.name
  password_length         = 32
  password_reset_required = false
}

resource "aws_secretsmanager_secret_version" "test_user_password" {
  secret_id     = aws_secretsmanager_secret.test_user_password.id
  secret_string = aws_iam_user_login_profile.test_user.password
}

resource "aws_iam_user_group_membership" "test_user_membership" {
  user   = aws_iam_user.test_user.name
  groups = [aws_iam_group.service_catalog_testers.name]
}

output "iam_role_arn" {
  value = aws_iam_role.test_role.arn
}

output "iam_group_name" {
  value = aws_iam_group.service_catalog_testers.name
}

output "iam_user_name" {
  value = aws_iam_user.test_user.name
}

output "secret_arn" {
  value = aws_secretsmanager_secret.test_user_password.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

locals {
  common_tags = {
    Datadog               = "true"
    DatadogAgentlessScanner = "true"
  }
}

variable "enable_ssm_endpoints" {
  type    = bool
  default = false
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(
    {
      Name = "DatatogAgentlessScanner"
    },
    local.common_tags
  )
}

resource "aws_subnet" "public" {
  count = min(3, length(data.aws_availability_zones.available.names))

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = merge(
    {
      Name = "public-${count.index}"
    },
    local.common_tags
  )
}

resource "aws_subnet" "private" {
  count = min(3, length(data.aws_availability_zones.available.names))

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 100)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = merge(
    {
      Name = "private-${count.index}"
    },
    local.common_tags
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = local.common_tags
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = local.common_tags
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = local.common_tags
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = local.common_tags
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = local.common_tags
}

resource "aws_route" "private_nat" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_vpc_endpoint" "s3_gateway" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.region}.s3"
  vpc_endpoint_type = "Gateway"

  route_table_ids = [
    aws_route_table.public.id,
    aws_route_table.private.id
  ]

  tags = local.common_tags
}

resource "aws_security_group" "vpc_endpoint" {
  name_prefix = "vpc-endpoint-"
  description = "Security group for VPC endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = local.common_tags
}

resource "aws_vpc_endpoint" "lambda" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.lambda"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  private_dns_enabled = true
  security_group_ids  = [aws_security_group.vpc_endpoint.id]

  tags = local.common_tags
}

resource "aws_vpc_endpoint" "ebs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ebs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  private_dns_enabled = true
  security_group_ids  = [aws_security_group.vpc_endpoint.id]

  tags = local.common_tags
}

resource "aws_vpc_endpoint" "ec2messages" {
  count = var.enable_ssm_endpoints ? 1 : 0

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ec2messages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  private_dns_enabled = true
  security_group_ids  = [aws_security_group.vpc_endpoint.id]

  tags = local.common_tags
}

resource "aws_vpc_endpoint" "ssmmessages" {
  count = var.enable_ssm_endpoints ? 1 : 0

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ssmmessages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  private_dns_enabled = true
  security_group_ids  = [aws_security_group.vpc_endpoint.id]

  tags = local.common_tags
}

resource "aws_vpc_endpoint" "ssm" {
  count = var.enable_ssm_endpoints ? 1 : 0

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ssm"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  private_dns_enabled = true
  security_group_ids  = [aws_security_group.vpc_endpoint.id]

  tags = local.common_tags
}

# KMS key for CloudWatch log group encryption
resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for CloudWatch log group encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogsUseKey"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.region}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/cloudwatch-flow-logs"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

# VPC Flow Logs
resource "aws_cloudwatch_log_group" "flow_log" {
  name              = "/aws/vpc/flow-logs"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.cloudwatch.arn
  tags              = local.common_tags
}

resource "aws_iam_role" "flow_log" {
  name = "vpc-flow-logs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "flow_log" {
  name = "vpc-flow-logs-policy"
  role = aws_iam_role.flow_log.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = aws_cloudwatch_log_group.flow_log.arn
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.cloudwatch.arn
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.flow_log.arn
  iam_role_arn         = aws_iam_role.flow_log.arn
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.main.id
  tags                 = local.common_tags
}

# --------------------------------------------------
# Terraform and Provider Configuration
# --------------------------------------------------
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# --------------------------------------------------
# Data Sources
# --------------------------------------------------
data "aws_caller_identity" "current" {}

# --------------------------------------------------
# Variables
# --------------------------------------------------
variable "enabled" {
  description = "Master toggle for all resources (security groups and prefix lists)"
  type        = bool
  default     = true
}

variable "create_security_group" {
  description = "Toggle to create a new security group (true) or attach rules to an existing one (false)"
  type        = bool
  default     = true
}

variable "existing_security_group_id" {
  description = "ID of an existing security group when create_security_group = false"
  type        = string
  default     = ""
}

variable "vpc_id" {
  description = "VPC ID for the new security group. If empty and create_security_group = true, a fallback VPC is created."
  type        = string
  default     = ""
}

variable "create_prefix_list" {
  description = "Toggle to create a managed prefix list"
  type        = bool
  default     = false
}

variable "ingress_rules" {
  description = "List of ingress rule objects. Each object must contain from_port, to_port, protocol, and optionally cidr_blocks, self, source_security_group_id, prefix_list_id."
  type = list(object({
    from_port                = number
    to_port                  = number
    protocol                 = string
    cidr_blocks              = optional(list(string), [])
    self                     = optional(bool, false)
    source_security_group_id = optional(string, "")
    prefix_list_id           = optional(string, "")
  }))
  default = []
}

variable "egress_rules" {
  description = "List of egress rule objects. Each object must contain from_port, to_port, protocol, and optionally cidr_blocks, self, source_security_group_id, prefix_list_id."
  type = list(object({
    from_port                = number
    to_port                  = number
    protocol                 = string
    cidr_blocks              = optional(list(string), [])
    self                     = optional(bool, false)
    source_security_group_id = optional(string, "")
    prefix_list_id           = optional(string, "")
  }))
  default = []
}

# Label variables – used for local naming logic
variable "namespace" {
  description = "Namespace for the label (e.g., 'org' or 'project')"
  type        = string
  default     = ""
}

variable "environment" {
  description = "Environment name (e.g., 'dev', 'prod')"
  type        = string
  default     = ""
}

variable "name" {
  description = "Name for the resource (e.g., 'web')"
  type        = string
  default     = "default"
}

variable "attributes" {
  description = "Additional attributes for the label"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags to apply"
  type        = map(string)
  default     = {}
}

variable "delimiter" {
  description = "Delimiter between label components"
  type        = string
  default     = "-"
}

variable "regex_replace_chars" {
  description = "Regex to replace characters in label values"
  type        = string
  default     = "/[^a-zA-Z0-9-]/"
}

# --------------------------------------------------
# Locals
# --------------------------------------------------
locals {
  # Generate id using the same logic as the external label module
  id = replace(
    join(var.delimiter, compact([var.namespace, var.environment, var.name, join(var.delimiter, var.attributes)])),
    var.regex_replace_chars,
    ""
  )

  # Tags with Name set to local.id
  tags = merge(var.tags, { Name = local.id })

  # Security group ID to use for rules (conditional on enabled and create_security_group)
  security_group_id = var.enabled ? (
    var.create_security_group ? aws_security_group.this[0].id : var.existing_security_group_id
  ) : null

  # Default prefix list ID (empty if not created)
  default_prefix_list_id = try(aws_ec2_managed_prefix_list.this[0].id, "")
}

# --------------------------------------------------
# Fallback VPC (if needed)
# --------------------------------------------------
resource "aws_vpc" "fallback" {
  count = var.enabled && var.create_security_group && var.vpc_id == "" ? 1 : 0

  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = format("%s-vpc", local.id)
  })

  lifecycle {
    prevent_destroy = true
  }
}

# --------------------------------------------------
# VPC Flow Logs (for fallback VPC)
# --------------------------------------------------
resource "aws_iam_role" "flow_logs" {
  count = var.enabled && var.create_security_group && var.vpc_id == "" ? 1 : 0

  name_prefix = format("%s-flow-logs-role-", local.id)

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.tags, {
    Name = format("%s-flow-logs-role", local.id)
  })
}

# Inline policy for VPC Flow Logs
resource "aws_iam_role_policy" "flow_logs" {
  count = var.enabled && var.create_security_group && var.vpc_id == "" ? 1 : 0

  name_prefix = format("%s-flow-logs-policy-", local.id)
  role        = aws_iam_role.flow_logs[0].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      }
    ]
  })
}

# KMS key for encrypting the CloudWatch log group
resource "aws_kms_key" "flow_logs" {
  count = var.enabled && var.create_security_group && var.vpc_id == "" ? 1 : 0

  description             = "KMS key for VPC Flow Logs CloudWatch log group encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable CloudWatch Logs"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Enable Root Account Administration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = merge(local.tags, {
    Name = format("%s-flow-logs-key", local.id)
  })
}

resource "aws_kms_alias" "flow_logs" {
  count = var.enabled && var.create_security_group && var.vpc_id == "" ? 1 : 0

  name_prefix   = format("alias/%s-flow-logs-", local.id)
  target_key_id = aws_kms_key.flow_logs[0].key_id
}

resource "aws_cloudwatch_log_group" "flow_logs" {
  count = var.enabled && var.create_security_group && var.vpc_id == "" ? 1 : 0

  name_prefix = format("/aws/vpc/flow-logs/%s-", local.id)

  retention_in_days = 7
  kms_key_id        = aws_kms_alias.flow_logs[0].arn

  tags = merge(local.tags, {
    Name = format("/aws/vpc/flow-logs/%s", local.id)
  })
}

resource "aws_flow_log" "this" {
  count = var.enabled && var.create_security_group && var.vpc_id == "" ? 1 : 0

  log_destination       = aws_cloudwatch_log_group.flow_logs[0].arn
  log_destination_type  = "cloud-watch-logs"
  iam_role_arn          = aws_iam_role.flow_logs[0].arn
  traffic_type          = "ALL"
  vpc_id                = aws_vpc.fallback[0].id

  tags = merge(local.tags, {
    Name = format("%s-flow-log", local.id)
  })
}

# --------------------------------------------------
# Security Group (new)
# --------------------------------------------------
resource "aws_security_group" "this" {
  count = var.enabled && var.create_security_group ? 1 : 0

  name        = format("%s-sg", local.id)
  description = "Security group managed by Terraform"
  vpc_id      = coalesce(var.vpc_id, aws_vpc.fallback[0].id)

  tags = merge(local.tags, {
    Name = format("%s-sg", local.id)
  })
}

# --------------------------------------------------
# Managed Prefix List
# --------------------------------------------------
resource "aws_ec2_managed_prefix_list" "this" {
  count = var.enabled && var.create_prefix_list ? 1 : 0

  name           = format("%s-prefix-list", local.id)
  address_family = "IPv4"
  max_entries    = 5

  tags = merge(local.tags, {
    Name = format("%s-prefix-list", local.id)
  })

  lifecycle {
    prevent_destroy = true
  }
}

# --------------------------------------------------
# Ingress Rules
# --------------------------------------------------
resource "aws_security_group_rule" "ingress" {
  for_each = var.enabled ? { for idx, rule in var.ingress_rules : idx => rule } : {}

  security_group_id = local.security_group_id
  type              = "ingress"

  cidr_blocks              = try(each.value.cidr_blocks, [])
  self                     = try(each.value.self, false)
  source_security_group_id = try(each.value.source_security_group_id, null)
  prefix_list_ids          = each.value.prefix_list_id != "" ? [each.value.prefix_list_id] : (local.default_prefix_list_id != "" ? [local.default_prefix_list_id] : [])

  from_port = each.value.from_port
  to_port   = each.value.to_port
  protocol  = each.value.protocol
}

# --------------------------------------------------
# Egress Rules
# --------------------------------------------------
resource "aws_security_group_rule" "egress" {
  for_each = var.enabled ? { for idx, rule in var.egress_rules : idx => rule } : {}

  security_group_id = local.security_group_id
  type              = "egress"

  cidr_blocks              = try(each.value.cidr_blocks, [])
  self                     = try(each.value.self, false)
  source_security_group_id = try(each.value.source_security_group_id, null)
  prefix_list_ids          = each.value.prefix_list_id != "" ? [each.value.prefix_list_id] : (local.default_prefix_list_id != "" ? [local.default_prefix_list_id] : [])

  from_port = each.value.from_port
  to_port   = each.value.to_port
  protocol  = each.value.protocol
}

# --------------------------------------------------
# Outputs
# --------------------------------------------------
output "security_group_id" {
  description = "ID of the security group (either created or existing)"
  value       = local.security_group_id
}

output "prefix_list_id" {
  description = "ID of the managed prefix list (if created)"
  value       = try(aws_ec2_managed_prefix_list.this[0].id, null)
}

variable "role_name" {
  type        = string
  default     = "CloudForecast-ZeroWaste"
  description = "Name of the IAM role for CloudForecast integration"
}

variable "external_id" {
  type        = string
  default     = "benchmark-external-id"
  description = "External ID required in the trust policy for cross-account access"
}

resource "aws_iam_role" "cloudforecast_role" {
  name = var.role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::656227328603:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = var.external_id
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudwatch_metrics" {
  name   = "cloudwatch_metrics"
  role   = aws_iam_role.cloudforecast_role.id
  policy = jsonencode({
    Version = "2012-10-17"
