terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_partition" "current" {}
data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

variable "environment" {
  description = "Environment suffix for user names"
  type        = string
  default     = "dev"
}

variable "create_db_dr_user" {
  description = "Toggle creation of the database disaster recovery user"
  type        = bool
  default     = false
}

variable "create_data_exports_user" {
  description = "Toggle creation of the data exports user"
  type        = bool
  default     = false
}

variable "create_packer_image_builder_user" {
  description = "Toggle creation of the Packer image builder user"
  type        = bool
  default     = false
}

variable "s3_export_bucket_arn" {
  description = "ARN of the S3 export bucket for data exports user"
  type        = string
  default     = "arn:aws:s3:::placeholder-export-bucket"
}

locals {
  env_suffix = var.environment
  partition  = data.aws_partition.current.partition
}

# Cost Reporting User and Group (always created)
resource "aws_iam_user" "cost_report" {
  name = "mattermost-cost-report-${local.env_suffix}"
}

resource "aws_iam_group" "cost_report" {
  name = "mattermost-cost-report-group-${local.env_suffix}"
}

resource "aws_iam_group_policy" "cost_report_policy" {
  name  = "cost-report-policy"
  group = aws_iam_group.cost_report.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "ce:*"
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = ["true"]
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_membership" "cost_report" {
  name  = "cost-report-group-membership"
  group = aws_iam_group.cost_report.name
  users = [aws_iam_user.cost_report.name]
}

# Database Disaster Recovery User and Group (conditional)
resource "aws_iam_user" "db_dr" {
  count = var.create_db_dr_user ? 1 : 0
  name  = "mattermost-db-dr-${local.env_suffix}"
}

resource "aws_iam_group" "db_dr" {
  count = var.create_db_dr_user ? 1 : 0
  name  = "mattermost-db-dr-group-${local.env_suffix}"
}

resource "aws_iam_group_policy" "db_dr_policy" {
  count = var.create_db_dr_user ? 1 : 0
  name  = "db-dr-policy"
  group = aws_iam_group.db_dr[0].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["rds:*", "kms:*"]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = ["true"]
          }
        }
      },
      {
        Effect   = "Allow"
        Action   = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:PutSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Resource = "arn:${local.partition}:secretsmanager:*:*:secret:rds-cluster-multitenant-*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = ["true"]
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_membership" "db_dr" {
  count = var.create_db_dr_user ? 1 : 0
  name  = "db-dr-group-membership"
  group = aws_iam_group.db_dr[0].name
  users = [aws_iam_user.db_dr[0].name]
}

# Data Exports User and Group (conditional)
resource "aws_iam_user" "data_exports" {
  count = var.create_data_exports_user ? 1 : 0
  name  = "mattermost-data-exports-${local.env_suffix}"
}

resource "aws_iam_group" "data_exports" {
  count = var.create_data_exports_user ? 1 : 0
  name  = "mattermost-data-exports-group-${local.env_suffix}"
}

resource "aws_iam_group_policy" "data_exports_policy" {
  count = var.create_data_exports_user ? 1 : 0
  name  = "data-exports-policy"
  group = aws_iam_group.data_exports[0].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "s3:ListBucket"
        Resource = var.s3_export_bucket_arn
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = ["true"]
          }
        }
      },
      {
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:PutObject"]
        Resource = "${var.s3_export_bucket_arn}/*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = ["true"]
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_membership" "data_exports" {
  count = var.create_data_exports_user ? 1 : 0
  name  = "data-exports-group-membership"
  group = aws_iam_group.data_exports[0].name
  users = [aws_iam_user.data_exports[0].name]
}

# Packer Image Builder Role (always created for pass-role authority)
resource "aws_iam_role" "packer_server_role" {
  name = "mattermost-packer-server-role-${local.env_suffix}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Packer Image Builder User and Group (conditional)
resource "aws_iam_user" "packer_image_builder" {
  count = var.create_packer_image_builder_user ? 1 : 0
  name  = "mattermost-packer-image-builder-${local.env_suffix}"
}

resource "aws_iam_group" "packer_image_builder" {
  count = var.create_packer_image_builder_user ? 1 : 0
  name  = "mattermost-packer-image-builder-group-${local.env_suffix}"
}

resource "aws_iam_group_policy" "packer_image_builder_policy" {
  count = var.create_packer_image_builder_user ? 1 : 0
  name  = "packer-image-builder-policy"
  group = aws_iam_group.packer_image_builder[0].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:*",
          "autoscaling:*",
          "events:*",
          "ssm:GetParameter",
          "ssm:GetParameters",
          "ssm:PutParameter",
          "iam:GetInstanceProfile",
          "iam:ListInstanceProfiles",
          "iam:PassRole",
          "iam:GetRole",
          "iam:ListRoles"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = ["true"]
          }
        }
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = [
          "arn:${local.partition}:s3:::mattermost-packer-state-${local.env_suffix}",
          "arn:${local.partition}:s3:::mattermost-packer-state-${local.env_suffix}/*"
        ]
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = ["true"]
          }
        }
      },
      {
        Effect = "Allow"
        Action = "lambda:GetFunctionConfiguration"
        Resource = "arn:${local.partition}:lambda:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:function:bind-server-network-attachment"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = ["true"]
          }
        }
      },
      {
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = aws_iam_role.packer_server_role.arn
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = ["true"]
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_membership" "packer_image_builder" {
  count = var.create_packer_image_builder_user ? 1 : 0
  name  = "packer-image-builder-group-membership"
  group = aws_iam_group.packer_image_builder[0].name
  users = [aws_iam_user.packer_image_builder[0].name]
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "ecr_repository_names" {
  description = "List of ECR repository names to create"
  type        = list(string)
  default     = []
}

variable "external_account_ids" {
  description = "List of external AWS account IDs to grant cross-account ECR pull access"
  type        = list(string)
  default     = []
}

variable "additional_bucket_arns" {
  description = "List of additional S3 bucket ARNs to grant read-only access"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  output_bucket_name = "tf-benchmark-omics-output-bucket"
  log_bucket_name    = "tf-benchmark-omics-log-bucket"
  output_bucket_arn  = "arn:${local.partition}:s3:::${local.output_bucket_name}"
  kms_key_arn        = aws_kms_key.this.arn
  role_arn           = aws_iam_role.health_omics.arn
}

# Import existing resources into Terraform state
import {
  to = aws_s3_bucket.log
  id = local.log_bucket_name
}

import {
  to = aws_s3_bucket.output
  id = local.output_bucket_name
}

import {
  to = aws_iam_role.health_omics
  id = "HealthOmicsRole"
}

import {
  to = aws_iam_group.health_omics
  id = "HealthOmicsGroup"
}

import {
  to = aws_iam_user.workbench_health_omics
  id = "workbench-health-omics"
}

import {
  to = aws_kms_alias.this
  id = "alias/health-omics-output-key"
}

import {
  to = aws_s3_bucket_ownership_controls.log
  id = local.log_bucket_name
}

import {
  to = aws_iam_policy.service_policy
  id = "arn:${local.partition}:iam::${local.account_id}:policy/HealthOmicsServicePolicy"
}

import {
  to = aws_iam_policy.user_policy
  id = "arn:${local.partition}:iam::${local.account_id}:policy/HealthOmicsUserPolicy"
}

# KMS key for S3 SSE-KMS
resource "aws_kms_key" "this" {
  description             = "Customer-managed key for HealthOmics output bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAdmin"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowServiceRoleAndUserUse"
        Effect = "Allow"
        Principal = {
          AWS = [
            aws_iam_role.health_omics.arn,
            aws_iam_user.workbench_health_omics.arn
          ]
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = var.tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "this" {
  name          = "alias/health-omics-output-key"
  target_key_id = aws_kms_key.this.key_id
}

# S3 log bucket for access logs
resource "aws_s3_bucket" "log" {
  bucket = local.log_bucket_name
  tags   = var.tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "log" {
  bucket = aws_s3_bucket.log.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log" {
  bucket = aws_s3_bucket.log.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "log" {
  bucket = aws_s3_bucket.log.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "log" {
  bucket = aws_s3_bucket.log.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "log" {
  bucket = aws_s3_bucket.log.id
  acl    = "log-delivery-write"
  depends_on = [aws_s3_bucket_ownership_controls.log]
}

# S3 output bucket
resource "aws_s3_bucket" "output" {
  bucket = local.output_bucket_name
  tags   = var.tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "output" {
  bucket = aws_s3_bucket.output.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "output" {
  bucket = aws_s3_bucket.output.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.this.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "output" {
  bucket = aws_s3_bucket.output.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "output" {
  bucket = aws_s3_bucket.output.id

  target_bucket = aws_s3_bucket.log.id
  target_prefix = "s3-access-logs/"
}

# IAM role for HealthOmics service
resource "aws_iam_role" "health_omics" {
  name = "HealthOmicsRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "omics.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = var.tags
}

# Service policy for the role
resource "aws_iam_policy" "service_policy" {
  name        = "HealthOmicsServicePolicy"
  description = "Policy for HealthOmics service role"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Effect = "Allow"
          Action = [
            "s3:PutObject",
            "s3:GetObject",
            "s3:ListBucket"
          ]
          Resource = [
            local.output_bucket_arn,
            "${local.output_bucket_arn}/*"
          ]
        },
        {
          Effect = "Allow"
          Action = [
            "kms:Decrypt",
            "kms:GenerateDataKey"
          ]
          Resource = local.kms_key_arn
        }
      ],
      length(var.additional_bucket_arns) > 0 ? [
        {
          Effect = "Allow"
          Action = [
            "s3:GetObject",
            "s3:ListBucket"
          ]
          Resource = flatten([
            var.additional_bucket_arns,
            [for arn in var.additional_bucket_arns : "${arn}/*"]
          ])
        }
      ] : []
    )
  })
}

resource "aws_iam_role_policy_attachment" "service_policy_attachment" {
  role       = aws_iam_role.health_omics.name
  policy_arn = aws_iam_policy.service_policy.arn
}

# IAM group for user policy
resource "aws_iam_group" "health_omics" {
  name = "HealthOmicsGroup"
}

resource "aws_iam_group_policy_attachment" "user_policy_attachment" {
  group      = aws_iam_group.health_omics.name
  policy_arn = aws_iam_policy.user_policy.arn
}

resource "aws_iam_group_membership" "health_omics" {
  name  = "health-omics-membership"
  users = [aws_iam_user.workbench_health_omics.name]
  group = aws_iam_group.health_omics.name
}

# MFA enforcement policy for the group
resource "aws_iam_group_policy" "mfa_enforcement" {
  group = aws_iam_group.health_omics.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "iam:GetAccountPasswordPolicy"
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

# IAM user for programmatic access
resource "aws_iam_user" "workbench_health_omics" {
  name = "workbench-health-omics"
  tags = var.tags
}

# User policy
resource "aws_iam_policy" "user_policy" {
  name        = "HealthOmicsUserPolicy"
  description = "Policy for HealthOmics user"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Effect = "Allow"
          Action = "iam:PassRole"
          Resource = local.role_arn
        },
        {
          Effect = "Allow"
          Action = "omics:*"
          Resource = "*"
        },
        {
          Effect = "Allow"
          Action = [
            "s3:GetObject",
            "s3:ListBucket"
          ]
          Resource = [
            local.output_bucket_arn,
            "${local.output_bucket_arn}/*"
          ]
        },
        {
          Effect = "Allow"
          Action = "kms:Decrypt"
          Resource = local.kms_key_arn
        }
      ],
      length(var.additional_bucket_arns) > 0 ? [
        {
          Effect = "Allow"
          Action = [
            "s3:GetObject",
            "s3:ListBucket"
          ]
          Resource = flatten([
            var.additional_bucket_arns,
            [for arn in var.additional_bucket_arns : "${arn}/*"]
          ])
        }
      ] : []
    )
  })
}

# ECR repositories
resource "aws_ecr_repository" "this" {
  for_each = toset(var.ecr_repository_names)
  name     = each.key
  tags     = var.tags
}

resource "aws_ecr_repository_policy" "this" {
  for_each   = aws_ecr_repository.this
  repository = each.value.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Sid    = "OmicsPull"
          Effect = "Allow"
          Principal = {
            Service = "omics.amazonaws.com"
          }
          Action = [
            "ecr:GetDownloadUrlForLayer",
            "ecr:BatchGetImage",
            "ecr:BatchCheckLayerAvailability"
          ]
        }
      ],
      length(var.external_account_ids) > 0 ? [
        {
          Sid    = "CrossAccountPull"
          Effect = "Allow"
          Principal = {
            AWS = [for account_id in var.external_account_ids : "arn:${local.partition}:iam::${account_id}:root"]
          }
          Action = [
            "ecr:GetDownloadUrlForLayer",
            "ecr:BatchGetImage",
            "ecr:BatchCheckLayerAvailability"
          ]
        }
      ] : []
    )
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "cluster_name" {
  type    = string
  default = "benchmark"
}

variable "vpc_cidr_network_octets" {
  type    = string
  default = "10.0"
}

variable "default_tags" {
  type    = map(string)
  default = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  default_tags = var.default_tags
  az_names     = slice(data.aws_availability_zones.available.names, 0, 3)
  public_cidrs = [
    "${var.vpc_cidr_network_octets}.12.0/22",
    "${var.vpc_cidr_network_octets}.16.0/22",
    "${var.vpc_cidr_network_octets}.20.0/22",
  ]
  private_cidrs = [
    "${var.vpc_cidr_network_octets}.0.0/22",
    "${var.vpc_cidr_network_octets}.4.0/22",
    "${var.vpc_cidr_network_octets}.8.0/22",
  ]
}

resource "aws_ecs_cluster" "main" {
  name = "dit-paas-${var.cluster_name}-cluster"

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = merge(local.default_tags, {
    Name = "dit-paas-${var.cluster_name}-cluster"
  })
}

resource "aws_vpc" "main" {
  cidr_block           = "${var.vpc_cidr_network_octets}.0.0/16"
  enable_dns_hostnames = false

  tags = merge(local.default_tags, {
    Name = "${var.cluster_name}-vpc"
  })
}

resource "aws_subnet" "public" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_cidrs[count.index]
  availability_zone = local.az_names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.default_tags, {
    Name = "${var.cluster_name}-public-subnet-${count.index}"
  })
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_cidrs[count.index]
  availability_zone = local.az_names[count.index]

  tags = merge(local.default_tags, {
    Name = "${var.cluster_name}-private-subnet-${count.index}"
  })
}

resource "aws_internet_gateway" "ig" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.default_tags, {
    Name = "${var.cluster_name}-ig"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = merge(local.default_tags, {
    Name = "${var.cluster_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count  = 3
  domain = "vpc"

  tags = merge(local.default_tags, {
    Name = "${var.cluster_name}-nat-eip-${count.index}"
  })
}

resource "aws_nat_gateway" "main" {
  count             = 3
  allocation_id     = aws_eip.nat[count.index].id
  subnet_id         = aws_subnet.public[count.index].id
  connectivity_type = "public"

  tags = merge(local.default_tags, {
    Name = "${var.cluster_name}-nat-gw-${count.index}"
  })
}

resource "aws_route_table" "private" {
  count  = 3
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = merge(local.default_tags, {
    Name = "${var.cluster_name}-private-rt-${count.index}"
  })
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# KMS key with policy allowing CloudWatch Logs
data "aws_iam_policy_document" "flow_log_key_policy" {
  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "Allow CloudWatch Logs to use the key"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logs.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]
    condition {
      test     = "ArnEquals"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/vpc/flow-logs/${var.cluster_name}"]
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

resource "aws_kms_key" "flow_log" {
  description             = "KMS key for VPC Flow Logs"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.flow_log_key_policy.json

  tags = merge(local.default_tags, {
    Name = "${var.cluster_name}-flow-log-key"
  })
}

resource "aws_kms_alias" "flow_log" {
  name          = "alias/${var.cluster_name}-flow-log-key"
  target_key_id = aws_kms_key.flow_log.key_id
}

resource "aws_cloudwatch_log_group" "flow_log" {
  name              = "/aws/vpc/flow-logs/${var.cluster_name}"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.flow_log.arn

  tags = merge(local.default_tags, {
    Name = "${var.cluster_name}-flow-log-group"
  })
}

resource "aws_iam_role" "flow_log" {
  name = "${var.cluster_name}-flow-log-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(local.default_tags, {
    Name = "${var.cluster_name}-flow-log-role"
  })
}

resource "aws_iam_role_policy_attachment" "flow_log" {
  role       = aws_iam_role.flow_log.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonAPIGatewayPushToCloudWatchLogs"
}

resource "aws_flow_log" "main" {
  log_destination      = aws_cloudwatch_log_group.flow_log.arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.flow_log.arn
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"

  tags = merge(local.default_tags, {
    Name = "${var.cluster_name}-flow-log"
  })
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
  required_version = ">= 1.0"
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "Primary IPv4 CIDR block for the VPC"
  type        = string
  default     = "172.16.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  # Allocate /20 subnets for each AZ within the VPC CIDR
  public_subnet_cidrs  = [for i, az in local.azs : cidrsubnet(var.vpc_cidr, 4, i)]
  private_subnet_cidrs = [for i, az in local.azs : cidrsubnet(var.vpc_cidr, 4, i + 3)]
}

# Official AWS VPC module
module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = var.vpc_name
  cidr = var.vpc_cidr

  azs              = local.azs
  public_subnets   = local.public_subnet_cidrs
  private_subnets  = local.private_subnet_cidrs

  enable_dns_hostnames = true
  enable_nat_gateway   = true
  single_nat_gateway   = true

  # Deny-all default security group
  manage_default_security_group = true
  default_security_group_ingress = []
  default_security_group_egress  = []

  # VPC Flow Logs
  enable_flow_log                      = true
  flow_log_traffic_type                = "ALL"
  create_flow_log_cloudwatch_log_group = true
  create_flow_log_cloudwatch_iam_role  = true

  tags = {
    Name = var.vpc_name
  }
}

# Security group for VPC endpoints
resource "aws_security_group" "vpc_endpoint_sg" {
  name        = "vpc_endpoint_sg"
  description = "Security group for VPC Interface Endpoints"
  vpc_id      = module.vpc.vpc_id

  ingress {
    description = "Self-referencing HTTPS ingress"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Self-referencing HTTPS egress"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    self        = true
  }

  tags = {
    Name = "vpc_endpoint_sg"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# S3 Gateway Endpoint
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = module.vpc.vpc_id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"

  route_table_ids = concat(
    module.vpc.public_route_table_ids,
    module.vpc.private_route_table_ids,
    [module.vpc.default_route_table_id]
  )

  tags = {
    Name = "s3-gateway-endpoint"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Interface VPC Endpoints
locals {
  interface_services = {
    ecr_docker = "com.amazonaws.us-east-1.ecr.dkr"
    ecr_api    = "com.amazonaws.us-east-1.ecr.api"
    logs       = "com.amazonaws.us-east-1.logs"
    ssm        = "com.amazonaws.us-east-1.ssm"
    kms        = "com.amazonaws.us-east-1.kms"
  }
}

resource "aws_vpc_endpoint" "interface" {
  for_each = local.interface_services

  vpc_id              = module.vpc.vpc_id
  service_name        = each.value
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = module.vpc.private_subnets
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]

  tags = {
    Name = "${each.key}-endpoint"
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "vpc_name" {
  description = "Name of the VPC and prefix for dependent resources"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "Primary CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "instance_tenancy" {
  description = "Instance tenancy for the VPC"
  type        = string
  default     = "default"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "endpoint_services" {
  description = "Set of standard AWS interface endpoint service names (e.g., logs, ec2, ssm)"
  type        = set(string)
  default     = ["logs"]
}

variable "custom_endpoint_services" {
  description = "Map of custom endpoint services with service_name, port, and source_sg_id"
  type = map(object({
    service_name = string
    port         = number
    source_sg_id = string
  }))
  default = {}
}

variable "flow_logs_retention_days" {
  description = "Retention period in days for VPC Flow Logs CloudWatch Log Group"
  type        = number
  default     = 180
}

variable "endpoint_security_group_source_ids" {
  description = "List of source security group IDs to allow HTTPS (443) to/from VPC endpoints security group"
  type        = list(string)
  default     = []
}

# ------------------------------------------------------------------------------
# Data Sources
# ------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

# Adopt the existing CloudWatch Log Group instead of creating it
data "aws_cloudwatch_log_group" "vpc_flow_logs" {
  name = local.log_group_name
}

# ------------------------------------------------------------------------------
# Local values
# ------------------------------------------------------------------------------
locals {
  subnet_cidr = cidrsubnet(var.vpc_cidr, 8, 0)
  flow_logs_role_name = "vpc_flow_logs_${var.vpc_name}"
  ssm_role_name       = "ssm_${var.vpc_name}"
  ssm_profile_name    = "ssm_${var.vpc_name}"
  log_group_name = "/aws/vpc-flow-logs/${var.vpc_name}"
  vpc_endpoints_sg_name   = "vpc-endpoints-${var.vpc_name}"
  custom_endpoints_sg_name = "custom-endpoints-${var.vpc_name}"
  ssm_enabled = contains(var.endpoint_services, "ssm") ? true : false
}

# ------------------------------------------------------------------------------
# VPC
# ------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = var.enable_dns_hostnames

  tags = {
    Name = var.vpc_name
  }
}

# ------------------------------------------------------------------------------
# Subnet (required for interface endpoints)
# ------------------------------------------------------------------------------
resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.vpc_name}-subnet"
  }
}

# ------------------------------------------------------------------------------
# VPC Flow Logs
# ------------------------------------------------------------------------------
resource "aws_iam_role" "vpc_flow_logs" {
  name = local.flow_logs_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "vpc_flow_logs" {
  name = "${local.flow_logs_role_name}-policy"
  role = aws_iam_role.vpc_flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${data.aws_cloudwatch_log_group.vpc_flow_logs.arn}:*"
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  iam_role_arn    = aws_iam_role.vpc_flow_logs.arn
  log_destination = data.aws_cloudwatch_log_group.vpc_flow_logs.arn
  traffic_type    = "ALL"
  vpc_id          = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-flow-log"
  }
}

# ------------------------------------------------------------------------------
# Security Groups
# ------------------------------------------------------------------------------
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-default-sg"
  }
}

resource "aws_security_group" "vpc_endpoints" {
  name        = local.vpc_endpoints_sg_name
  description = "Security group for VPC interface endpoints (standard AWS services)"
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.endpoint_security_group_source_ids
    content {
      from_port       = 443
      to_port         = 443
      protocol        = "tcp"
      security_groups = [ingress.value]
    }
  }

  dynamic "egress" {
    for_each = var.endpoint_security_group_source_ids
    content {
      from_port       = 443
      to_port         = 443
      protocol        = "tcp"
      security_groups = [egress.value]
    }
  }

  tags = {
    Name = local.vpc_endpoints_sg_name
  }
}

resource "aws_security_group" "custom_endpoints" {
  name        = local.custom_endpoints_sg_name
  description = "Security group for custom VPC interface endpoints"
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.custom_endpoint_services
    content {
      from_port       = ingress.value.port
      to_port         = ingress.value.port
      protocol        = "tcp"
      security_groups = [ingress.value.source_sg_id]
    }
  }

  dynamic "egress" {
    for_each = var.custom_endpoint_services
    content {
      from_port       = egress.value.port
      to_port         = egress.value.port
      protocol        = "tcp"
      security_groups = [egress.value.source_sg_id]
    }
  }

  tags = {
    Name = local.custom_endpoints_sg_name
  }
}

# ------------------------------------------------------------------------------
# Route Table (for Gateway endpoints)
# ------------------------------------------------------------------------------
resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-route-table"
  }
}

# ------------------------------------------------------------------------------
# VPC Endpoints
# ------------------------------------------------------------------------------
resource "aws_vpc_endpoint" "gateway_dynamodb" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.dynamodb"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.main.id]

  tags = {
    Name = "${var.vpc_name}-dynamodb-endpoint"
  }
}

resource "aws_vpc_endpoint" "gateway_s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.main.id]

  tags = {
    Name = "${var.vpc_name}-s3-endpoint"
  }
}

resource "aws_vpc_endpoint" "interface_endpoints" {
  for_each = var.endpoint_services

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.${each.value}"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  subnet_ids          = [aws_subnet.main.id]

  tags = {
    Name = "${var.vpc_name}-${each.value}-endpoint"
  }
}

resource "aws_vpc_endpoint" "custom_endpoints" {
  for_each = var.custom_endpoint_services

  vpc_id              = aws_vpc.main.id
  service_name        = each.value.service_name
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = false
  security_group_ids  = [aws_security_group.custom_endpoints.id]
  subnet_ids          = [aws_subnet.main.id]

  tags = {
    Name = "${var.vpc_name}-${each.key}-endpoint"
  }
}

# ------------------------------------------------------------------------------
# SSM IAM Role and Instance Profile (conditional on "ssm" in endpoint_services)
# ------------------------------------------------------------------------------
resource "aws_iam_role" "ssm" {
  count = local.ssm_enabled ? 1 : 0

  name = local.ssm_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = local.ssm_role_name
  }
}

resource "aws_iam_role_policy_attachment" "ssm_managed" {
  count = local.ssm_enabled ? 1 : 0

  role       = aws_iam_role.ssm[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ssm" {
  count = local.ssm_enabled ? 1 : 0

  name = local.ssm_profile_name
  role = aws_iam_role.ssm[0].name

  tags = {
    Name = local.ssm_profile_name
  }
}

# Variables
variable "project_name" {
  description = "Project name used for KMS key aliases and resource naming"
  type        = string
  default     = "myproject"
}

variable "kms_key_rotation_period_days" {
  description = "Number of days between automatic key rotations"
  type        = number
  default     = 90
}

variable "hop_limit" {
  description = "Hop limit for EC2 instance metadata (IMDSv2)"
  type        = number
  default     = 1
}

variable "enable_imdsv2" {
  description = "Enable enforcement of IMDSv2 (required HTTP tokens) at account level"
  type        = bool
  default     = true
}

variable "disable_serial_console" {
  description = "Disable EC2 Serial Console access at account level"
  type        = bool
  default     = true
}

variable "enable_emr_block_public_access" {
  description = "Enable EMR block public access configuration to restrict public security groups"
  type        = bool
  default     = true
}

variable "external_ebs_kms_key_arn" {
  description = "Optional external KMS key ARN for account-level default EBS encryption; if left blank, the compute KMS key ARN is used"
  type        = string
  default     = ""
}

# Data sources for current account and region
data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# Account-level default EBS encryption
resource "aws_ebs_encryption_by_default" "default" {
  enabled = true
}

# Account-level default EBS KMS key
resource "aws_ebs_default_kms_key" "default" {
  key_arn = coalesce(var.external_ebs_kms_key_arn, aws_kms_key.compute.arn)
}

# Compute KMS key and alias
resource "aws_kms_key" "compute" {
  description             = "KMS key for compute layer (EBS, EC2, Auto Scaling)"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  rotation_period_in_days = var.kms_key_rotation_period_days
  policy                  = data.aws_iam_policy_document.compute_key_policy.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "compute" {
  name          = "alias/${var.project_name}-compute"
  target_key_id = aws_kms_key.compute.id
}

# Observability KMS key and alias
resource "aws_kms_key" "observability" {
  description             = "KMS key for observability layer (CloudWatch Logs, CloudTrail, SNS, SQS, EventBridge)"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  rotation_period_in_days = var.kms_key_rotation_period_days
  policy                  = data.aws_iam_policy_document.observability_key_policy.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "observability" {
  name          = "alias/${var.project_name}-observability"
  target_key_id = aws_kms_key.observability.id
}

# Storage KMS key and alias
resource "aws_kms_key" "storage" {
  description             = "KMS key for storage layer (S3, AWS Config, CloudTrail)"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  rotation_period_in_days = var.kms_key_rotation_period_days
  policy                  = data.aws_iam_policy_document.storage_key_policy.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "storage" {
  name          = "alias/${var.project_name}-storage"
  target_key_id = aws_kms_key.storage.id
}

# Compute KMS key policy
data "aws_iam_policy_document" "compute_key_policy" {
  statement {
    sid    = "EnableRootAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowEC2Service"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:DescribeKey"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowAutoScalingGrant"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["autoscaling.amazonaws.com"]
    }
    actions   = ["kms:CreateGrant"]
    resources = ["*"]
    condition {
      test     = "Bool"
      variable = "kms:GrantIsForAWSResource"
      values   = ["true"]
    }
  }
}

# Observability KMS key policy
data "aws_iam_policy_document" "observability_key_policy" {
  statement {
    sid    = "EnableRootAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogs"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logs.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext"
    ]
    resources = ["*"]
    condition {
      test     = "StringLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:*"]
    }
  }

  statement {
    sid    = "AllowCloudTrail"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchAlarms"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowSNS"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowSQS"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["sqs.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowEventBridge"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext"
    ]
    resources = ["*"]
  }
}

# Storage KMS key policy
data "aws_iam_policy_document" "storage_key_policy" {
  statement {
    sid    = "EnableRootAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowConfig"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudTrail"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext"
    ]
    resources = ["*"]
  }
}

# EC2 image block public access
resource "aws_ec2_image_block_public_access" "main" {
  state = "block-new-sharing"
}

# EBS snapshot block public access
resource "aws_ebs_snapshot_block_public_access" "main" {
  state = "block-all-sharing"
}

# Conditional: EC2 instance metadata defaults (IMDSv2)
resource "aws_ec2_instance_metadata_defaults" "main" {
  count = var.enable_imdsv2 ? 1 : 0

  http_tokens                 = "required"
  http_put_response_hop_limit = var.hop_limit
}

# Conditional: Disable EC2 Serial Console
resource "aws_ec2_serial_console_access" "main" {
  count   = var.disable_serial_console ? 1 : 0
  enabled = false
}

# Conditional: EMR block public access
resource "aws_emr_block_public_access_configuration" "main" {
  count = var.enable_emr_block_public_access ? 1 : 0

  block_public_security_group_rules = true
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
  required_version = ">= 1.0"
}

locals {
  cluster_prefix = var.cluster_prefix
  common_tags = {
    Project = local.cluster_prefix
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "cluster_prefix" {
  description = "Prefix for naming resources (5-8 characters)"
  type        = string
  default     = "bench"

  validation {
    condition     = can(regex("^[a-zA-Z][a-zA-Z0-9]{4,7}$", var.cluster_prefix))
    error_message = "cluster_prefix must be 5-8 alphanumeric characters starting with a letter."
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "172.16.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "List of CIDR blocks for public subnets"
  type        = list(string)
  default     = []
}

variable "private_subnet_cidrs" {
  description = "List of CIDR blocks for private subnets"
  type        = list(string)
  default     = []
}

variable "additional_ingress_cidrs" {
  description = "List of CIDR blocks allowed ingress to the default security group"
  type        = list(string)
  default     = []
}

variable "inventory_nodes" {
  description = "List of EC2 instance configurations"
  type = list(object({
    instance_type      = string
    subnet_index       = number
    root_volume_size   = number
    root_volume_type   = string
    eip_enabled        = bool
    secondary_volumes = list(object({
      device_name = string
      size        = number
      type        = string
      mount_point = string
    }))
  }))
  default = []
}

# ------------------------------------------------------------------------------
# Data Sources
# ------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# ------------------------------------------------------------------------------
# TLS Private Key
# ------------------------------------------------------------------------------
resource "tls_private_key" "main" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

# ------------------------------------------------------------------------------
# Key Pair
# ------------------------------------------------------------------------------
resource "aws_key_pair" "main" {
  key_name   = "${local.cluster_prefix}-keypair"
  public_key = tls_private_key.main.public_key_openssh
  tags       = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# VPC and Internet Gateway
# ------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = merge(local.common_tags, {
    Name = "${local.cluster_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags   = local.common_tags
}

# ------------------------------------------------------------------------------
# Subnets (public & private)
# ------------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index % length(data.aws_availability_zones.available.names)]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.cluster_prefix}-public-${count.index}"
  })
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index % length(data.aws_availability_zones.available.names)]

  tags = merge(local.common_tags, {
    Name = "${local.cluster_prefix}-private-${count.index}"
  })
}

# ------------------------------------------------------------------------------
# Elastic IPs & NAT Gateways (one per public subnet)
# ------------------------------------------------------------------------------
resource "aws_eip" "nat" {
  count = length(var.public_subnet_cidrs)
  domain = "vpc"
  tags = merge(local.common_tags, {
    Name = "${local.cluster_prefix}-nat-eip-${count.index}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_nat_gateway" "main" {
  count = length(var.public_subnet_cidrs)

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(local.common_tags, {
    Name = "${local.cluster_prefix}-nat-${count.index}"
  })
}

# ------------------------------------------------------------------------------
# Route Tables
# ------------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags = merge(local.common_tags, {
    Name = "${local.cluster_prefix}-public-rt"
  })
}

resource "aws_route" "public_default" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = length(var.public_subnet_cidrs)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id = aws_vpc.main.id
  tags = merge(local.common_tags, {
    Name = "${local.cluster_prefix}-private-rt-${count.index}"
  })
}

resource "aws_route" "private_default" {
  count = length(var.private_subnet_cidrs)

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index % length(aws_nat_gateway.main)].id
}

resource "aws_route_table_association" "private" {
  count = length(var.private_subnet_cidrs)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ------------------------------------------------------------------------------
# Default Security Group
# ------------------------------------------------------------------------------
resource "aws_security_group" "default" {
  name_prefix = "${local.cluster_prefix}-sg-"
  description = "Default security group for VPC"
  vpc_id      = aws_vpc.main.id
  tags        = local.common_tags

  # Self-referencing full ingress
  ingress {
    description = "Self-referencing intra-group ingress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  # Custom ingress CIDRs
  dynamic "ingress" {
    for_each = var.additional_ingress_cidrs
    content {
      description = "Custom ingress CIDR: ${ingress.value}"
      from_port   = 0
      to_port     = 0
      protocol    = "-1"
      cidr_blocks = [ingress.value]
    }
  }

  # Outbound only within VPC CIDR
  egress {
    description = "Outbound within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }
}

# ------------------------------------------------------------------------------
# KMS Key for CloudWatch Logs Encryption
# ------------------------------------------------------------------------------
resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for ${local.cluster_prefix} CloudWatch log group encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow VPC Flow Logs Role to use the key"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.vpc_flow.arn
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/${local.cluster_prefix}-cloudwatch-logs"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

# ------------------------------------------------------------------------------
# VPC Flow Logs
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "vpc_flow" {
  name              = "/aws/vpc/flow-logs/${local.cluster_prefix}"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.cloudwatch.arn
  tags              = local.common_tags
}

data "aws_iam_policy_document" "vpc_flow_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "vpc_flow" {
  name               = "${local.cluster_prefix}-vpc-flow-logs-role"
  assume_role_policy = data.aws_iam_policy_document.vpc_flow_assume_role.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "vpc_flow_permissions" {
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams"
    ]
    resources = [
      aws_cloudwatch_log_group.vpc_flow.arn,
      "${aws_cloudwatch_log_group.vpc_flow.arn}:*"
    ]
  }
}

resource "aws_iam_policy" "vpc_flow" {
  name   = "${local.cluster_prefix}-vpc-flow-logs-policy"
  policy = data.aws_iam_policy_document.vpc_flow_permissions.json
  tags   = local.common_tags
}

resource "aws_iam_role_policy_attachment" "vpc_flow" {
  role       = aws_iam_role.vpc_flow.name
  policy_arn = aws_iam_policy.vpc_flow.arn
}

resource "aws_flow_log" "main" {
  log_destination      = aws_cloudwatch_log_group.vpc_flow.arn
  iam_role_arn         = aws_iam_role.vpc_flow.arn
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
  max_aggregation_interval = 60
  tags                 = local.common_tags
}

# ------------------------------------------------------------------------------
# EC2 Instances (inventory nodes)
# ------------------------------------------------------------------------------
resource "aws_instance" "node" {
  for_each = { for idx, node in var.inventory_nodes : idx => node }

  ami                    = data.aws_ami.amazon_linux2.id
  instance_type          = each.value.instance_type
  key_name               = aws_key_pair.main.key_name
  subnet_id              = aws_subnet.public[each.value.subnet_index].id
  vpc_security_group_ids = [aws_security_group.default.id]
  ebs_optimized          = true

  root_block_device {
    volume_size = each.value.root_volume_size
    volume_type = each.value.root_volume_type
    delete_on_termination = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.cluster_prefix}-node-${each.key}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Optional Elastic IP for nodes
resource "aws_eip" "node" {
  for_each = { for idx, node in var.inventory_nodes : idx => node if node.eip_enabled }

  instance = aws_instance.node[each.key].id
  domain   = "vpc"
  tags = merge(local.common_tags, {
    Name = "${local.cluster_prefix}-node-eip-${each.key}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Secondary EBS Volumes and Attachments
# ------------------------------------------------------------------------------
resource "aws_ebs_volume" "secondary" {
  for_each = {
    for flat in flatten([
      for idx, node in var.inventory_nodes : [
        for vol_idx, vol in node.secondary_volumes : {
          key        = "${idx}-${vol_idx}"
          node_index = idx
          volume     = vol
        }
      ]
    ]) : flat.key => flat
  }

  availability_zone = aws_instance.node[each.value.node_index].availability_zone
  size              = each.value.volume.size
  type              = each.value.volume.type
  tags = merge(local.common_tags, {
    Name       = "${local.cluster_prefix}-vol-${each.value.node_index}-${each.value.volume.mount_point}"
    MountPoint = each.value.volume.mount_point
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_volume_attachment" "secondary" {
  for_each = aws_ebs_volume.secondary

  device_name = each.value.tags["MountPoint"] != null ? "/dev/sd${replace(each.value.tags["MountPoint"], "/dev/", "")}" : "/dev/xvd${replace(split("/", each.key)[1], "/", "")}"
  volume_id   = each.value.id
  instance_id = aws_instance.node[split("-", each.key)[0]].id
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------
output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "default_security_group_id" {
  value = aws_security_group.default.id
}

output "key_pair_name" {
  value = aws_key_pair.main.key_name
}

output "node_eips" {
  value = {
    for idx, eip in aws_eip.node : idx => eip.public_ip
  }
}

# ----------------------------------------------------------------------
# Terraform Block
# ----------------------------------------------------------------------
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.0"
    }
  }
}

# ----------------------------------------------------------------------
# Variables
# ----------------------------------------------------------------------
variable "subnet_cidrs" {
  description = "CIDR blocks for subnets (up to 4)"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24", "10.0.4.0/24"]

  validation {
    condition     = length(var.subnet_cidrs) == 4
    error_message = "subnet_cidrs must contain exactly 4 CIDR blocks."
  }
}

variable "enable_private_subnets" {
  description = "Toggle to create two public and two private subnets (true) or four public subnets (false)"
  type        = bool
  default     = true
}

variable "enable_nat_gateways" {
  description = "Deploy redundant NAT Gateways in each public subnet"
  type        = bool
  default     = false
}

variable "enable_nat_instances" {
  description = "Deploy redundant NAT EC2 instances (m1.small) in each public subnet"
  type        = bool
  default     = false
}

variable "enable_egress_only_igw" {
  description = "Create an Egress-Only Internet Gateway with IPv6 egress routes"
  type        = bool
  default     = false
}

variable "environment" {
  description = "Environment tag value"
  type        = string
  default     = "dev"
}

# ----------------------------------------------------------------------
# Locals
# ----------------------------------------------------------------------
locals {
  common_tags = {
    Environment = var.environment
    Project     = "benchmark-vpc"
  }
  # Determine number of public and private subnets based on toggle
  public_subnet_count  = var.enable_private_subnets ? 2 : 4
  private_subnet_count = var.enable_private_subnets ? 2 : 0
  # AZ indices to use
  public_az_indices  = var.enable_private_subnets ? [0, 1] : [0, 1, 2, 3]
  private_az_indices = var.enable_private_subnets ? [0, 1] : []
  # Validate mutual exclusivity of egress strategies
  egress_strategy_count = (
    (var.enable_nat_gateways ? 1 : 0) +
    (var.enable_nat_instances ? 1 : 0) +
    (var.enable_egress_only_igw ? 1 : 0)
  )
}

# ----------------------------------------------------------------------
# Data sources
# ----------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "nat_instance" {
  count       = var.enable_nat_instances ? 1 : 0
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn-ami-vpc-nat-*"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

# ----------------------------------------------------------------------
# VPC
# ----------------------------------------------------------------------
resource "aws_vpc" "benchmark" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "benchmark-vpc" })

  # Conditionally assign IPv6 CIDR if egress-only IGW is enabled
  assign_generated_ipv6_cidr_block = var.enable_egress_only_igw
}

# ----------------------------------------------------------------------
# Subnets
# ----------------------------------------------------------------------
resource "aws_subnet" "public" {
  count = local.public_subnet_count

  vpc_id            = aws_vpc.benchmark.id
  cidr_block        = var.subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[local.public_az_indices[count.index]]

  # Conditionally assign IPv6 CIDR if egress-only IGW is enabled
  ipv6_cidr_block = var.enable_egress_only_igw ? cidrsubnet(aws_vpc.benchmark.ipv6_cidr_block, 8, count.index) : null

  # Do not assign public IP automatically – instances must request explicitly
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "benchmark-vpc-public-${count.index}" })
}

resource "aws_subnet" "private" {
  count = local.private_subnet_count

  vpc_id            = aws_vpc.benchmark.id
  cidr_block        = var.subnet_cidrs[count.index + 2] # Use third and fourth CIDR blocks
  availability_zone = data.aws_availability_zones.available.names[local.private_az_indices[count.index]]

  # Conditionally assign IPv6 CIDR if egress-only IGW is enabled
  ipv6_cidr_block = var.enable_egress_only_igw ? cidrsubnet(aws_vpc.benchmark.ipv6_cidr_block, 8, count.index + 2) : null

  tags = merge(local.common_tags, { Name = "benchmark-vpc-private-${count.index}" })
}

# ----------------------------------------------------------------------
# Internet Gateway
# ----------------------------------------------------------------------
resource "aws_internet_gateway" "benchmark" {
  vpc_id = aws_vpc.benchmark.id

  tags = merge(local.common_tags, { Name = "benchmark-vpc-igw" })
}

# ----------------------------------------------------------------------
# Default Security Group (self-referencing, egress restricted to VPC CIDR)
# ----------------------------------------------------------------------
resource "aws_security_group" "default" {
  name        = "benchmark-vpc-default-sg"
  description = "Default security group for benchmark VPC"
  vpc_id      = aws_vpc.benchmark.id

  # Self-referencing ingress
  ingress {
    description = "Allow all internal traffic from self"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  # Egress restricted to VPC CIDR only
  egress {
    description = "Allow all outbound traffic to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.benchmark.cidr_block]
  }

  tags = merge(local.common_tags, { Name = "benchmark-vpc-default-sg" })
}

# ----------------------------------------------------------------------
# TLS Inbound Security Group
# ----------------------------------------------------------------------
resource "aws_security_group" "tls_inbound" {
  name        = "benchmark-vpc-tls-inbound-sg"
  description = "Allows inbound HTTPS (443) from anywhere"
  vpc_id      = aws_vpc.benchmark.id

  ingress {
    description = "Allow HTTPS inbound from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.benchmark.cidr_block]
  }

  tags = merge(local.common_tags, { Name = "benchmark-vpc-tls-inbound-sg" })
}

# ----------------------------------------------------------------------
# Public Route Table
# ----------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.benchmark.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.benchmark.id
  }

  tags = merge(local.common_tags, { Name = "benchmark-vpc-public-rt" })
}

resource "aws_route_table_association" "public" {
  count = local.public_subnet_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ----------------------------------------------------------------------
# NAT Gateways (if enabled)
# ----------------------------------------------------------------------
resource "aws_eip" "nat_gateway" {
  count = var.enable_nat_gateways && var.enable_private_subnets ? local.public_subnet_count : 0

  domain = "vpc"

  tags = merge(local.common_tags, { Name = "benchmark-vpc-nat-gw-eip-${count.index}" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_nat_gateway" "benchmark" {
  count = var.enable_nat_gateways && var.enable_private_subnets ? local.public_subnet_count : 0

  allocation_id = aws_eip.nat_gateway[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(local.common_tags, { Name = "benchmark-vpc-nat-gw-${count.index}" })
}

# Private route tables for NAT Gateways (one per private subnet)
resource "aws_route_table" "private_nat_gw" {
  count = var.enable_nat_gateways && var.enable_private_subnets ? local.private_subnet_count : 0

  vpc_id = aws_vpc.benchmark.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.benchmark[count.index].id
  }

  tags = merge(local.common_tags, { Name = "benchmark-vpc-private-nat-gw-rt-${count.index}" })
}

resource "aws_route_table_association" "private_nat_gw" {
  count = var.enable_nat_gateways && var.enable_private_subnets ? local.private_subnet_count : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private_nat_gw[count.index].id
}

# ----------------------------------------------------------------------
# NAT Instances (if enabled)
# ----------------------------------------------------------------------
# Security group for NAT instances
resource "aws_security_group" "nat_instance" {
  count = var.enable_nat_instances ? 1 : 0

  name        = "benchmark-vpc-nat-instance-sg"
  description = "Security group for NAT instances"
  vpc_id      = aws_vpc.benchmark.id

  # Allow all traffic from private subnets
  ingress {
    description = "Allow all traffic from private subnets"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [
      for i in range(local.private_subnet_count) : var.subnet_cidrs[i + 2]
    ]
  }

  # Egress restricted to VPC CIDR
  egress {
    description = "Allow all outbound traffic to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.benchmark.cidr_block]
  }

  tags = merge(local.common_tags, { Name = "benchmark-vpc-nat-instance-sg" })
}

# Elastic IPs for NAT instances
resource "aws_eip" "nat_instance" {
  count = var.enable_nat_instances && var.enable_private_subnets ? local.public_subnet_count : 0

  domain = "vpc"

  tags = merge(local.common_tags, { Name = "benchmark-vpc-nat-instance-eip-${count.index}" })

  lifecycle {
    prevent_destroy = true
  }
}

# NAT Instances
resource "aws_instance" "nat_instance" {
  count = var.enable_nat_instances && var.enable_private_subnets ? local.public_subnet_count : 0

  ami                    = data.aws_ami.nat_instance[0].id
  instance_type          = "m1.small"
  subnet_id              = aws_subnet.public[count.index].id
  vpc_security_group_ids = [aws_security_group.nat_instance[0].id]
  source_dest_check      = false

  # Associate public IP explicitly (since subnets do not auto-assign)
  associate_public_ip_address = true

  tags = merge(local.common_tags, { Name = "benchmark-vpc-nat-instance-${count.index}" })
}

# Associate EIP after instance creation
resource "aws_eip_association" "nat_instance" {
  count = var.enable_nat_instances && var.enable_private_subnets ? local.public_subnet_count : 0

  allocation_id = aws_eip.nat_instance[count.index].id
  instance_id   = aws_instance.nat_instance[count.index].id
}

# Private route tables for NAT Instances
resource "aws_route_table" "private_nat_instance" {
  count = var.enable_nat_instances && var.enable_private_subnets ? local.private_subnet_count : 0

  vpc_id = aws_vpc.benchmark.id

  route {
    cidr_block           = "0.0.0.0/0"
    network_interface_id = aws_instance.nat_instance[count.index].primary_network_interface_id
  }

  tags = merge(local.common_tags, { Name = "benchmark-vpc-private-nat-instance-rt-${count.index}" })
}

resource "aws_route_table_association" "private_nat_instance" {
  count = var.enable_nat_instances && var.enable_private_subnets ? local.private_subnet_count : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private_nat_instance[count.index].id
}

# ----------------------------------------------------------------------
# Egress-Only Internet Gateway (if enabled)
# ----------------------------------------------------------------------
resource "aws_egress_only_internet_gateway" "benchmark" {
  count = var.enable_egress_only_igw ? 1 : 0

  vpc_id = aws_vpc.benchmark.id

  tags = merge(local.common_tags, { Name = "benchmark-vpc-eigw" })
}

# Private route table for egress-only IGW (single for all private subnets)
resource "aws_route_table" "private_eigw" {
  count = var.enable_egress_only_igw && var.enable_private_subnets ? 1 : 0

  vpc_id = aws_vpc.benchmark.id

  route {
    ipv6_cidr_block        = "::/0"
    egress_only_gateway_id = aws_egress_only_internet_gateway.benchmark[0].id
  }

  tags = merge(local.common_tags, { Name = "benchmark-vpc-private-eigw-rt" })
}

resource "aws_route_table_association" "private_eigw" {
  count = var.enable_egress_only_igw && var.enable_private_subnets ? local.private_subnet_count : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private_eigw[0].id
}

# ----------------------------------------------------------------------
# Mutual exclusivity validation
# ----------------------------------------------------------------------
resource "null_resource" "validate_egress_strategies" {
  lifecycle {
    precondition {
      condition     = local.egress_strategy_count <= 1
      error_message = "Only one of enable_nat_gateways, enable_nat_instances, or enable_egress_only_igw can be true at a time."
    }
  }
}

# ----------------------------------------------------------------------
# KMS Key for CloudWatch Logs encryption
# ----------------------------------------------------------------------
resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for VPC Flow Logs CloudWatch log group encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow VPC Flow Logs Role to use the key"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.vpc_flow_log.arn
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "benchmark-vpc-flow-log-kms-key" })
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/benchmark-vpc-flow-log"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

# ----------------------------------------------------------------------
# VPC Flow Logs
# ----------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "vpc_flow_log" {
  name              = "/aws/vpc/benchmark-vpc"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.cloudwatch.arn

  tags = merge(local.common_tags, { Name = "benchmark-vpc-flow-log-group" })
}

resource "aws_flow_log" "benchmark" {
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.vpc_flow_log.arn
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.benchmark.id

  iam_role_arn = aws_iam_role.vpc_flow_log.arn

  tags = merge(local.common_tags, { Name = "benchmark-vpc-flow-log" })
}

# IAM role for VPC Flow Logs
resource "aws_iam_role" "vpc_flow_log" {
  name = "benchmark-vpc-flow-log-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "vpc_flow_log" {
  name = "benchmark-vpc-flow-log-policy"
  role = aws_iam_role.vpc_flow_log.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.cloudwatch.arn
      }
    ]
  })
}

# ----------------------------------------------------------------------
# Data source for account ID (used in KMS key policy)
# ----------------------------------------------------------------------
data "aws_caller_identity" "current" {}

# Variables
variable "environment_name" {
  description = "Environment name used for resource naming"
  type        = string
  default     = "benchmark"
}

variable "glacier_transition_days" {
  description = "Number of days after object creation to transition to GLACIER"
  type        = number
  default     = 7
}

variable "glacier_expiration_days" {
  description = "Number of days after object creation to expire objects"
  type        = number
  default     = 30
}

variable "secondary_region" {
  description = "AWS region for disaster recovery replication"
  type        = string
  default     = "us-west-2"
}

# Terraform configuration
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Provider configurations (injected by harness, but needed for secondary alias)
provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "secondary"
  region = var.secondary_region
}

# Data sources
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# Local values
locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

# Random suffix for globally unique bucket names
resource "random_id" "suffix" {
  byte_length = 4
}

# Primary KMS key for state bucket
resource "aws_kms_key" "state_key" {
  description             = "KMS key for encrypting Terraform state bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "state_key_alias" {
  name_prefix   = "alias/${var.environment_name}-tfstate-key-"
  target_key_id = aws_kms_key.state_key.id
}

# Primary state bucket
resource "aws_s3_bucket" "tfstate" {
  bucket = "${var.environment_name}-tfstate-${random_id.suffix.hex}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "tfstate_versioning" {
  bucket = aws_s3_bucket.tfstate.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "tfstate_encryption" {
  bucket = aws_s3_bucket.tfstate.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "tfstate_public_access" {
  bucket = aws_s3_bucket.tfstate.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Primary access logs bucket
resource "aws_s3_bucket" "access_logs" {
  bucket = "${var.environment_name}-access-logs-${random_id.suffix.hex}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "access_logs_versioning" {
  bucket = aws_s3_bucket.access_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "access_logs_lifecycle" {
  bucket = aws_s3_bucket.access_logs.id

  rule {
    id     = "glacier-transition"
    status = "Enabled"

    filter {
      prefix = ""
    }

    transition {
      days          = var.glacier_transition_days
      storage_class = "GLACIER"
    }

    expiration {
      days = var.glacier_expiration_days
    }
  }
}

# Enable ACLs on access logs bucket
resource "aws_s3_bucket_ownership_controls" "access_logs_ownership" {
  bucket = aws_s3_bucket.access_logs.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "access_logs_acl" {
  depends_on = [aws_s3_bucket_ownership_controls.access_logs_ownership]
  bucket     = aws_s3_bucket.access_logs.id
  acl        = "log-delivery-write"
}

resource "aws_s3_bucket_public_access_block" "access_logs_public_access" {
  bucket = aws_s3_bucket.access_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Logging configuration for state bucket
resource "aws_s3_bucket_logging" "tfstate_logging" {
  bucket = aws_s3_bucket.tfstate.id

  target_bucket = aws_s3_bucket.access_logs.id
  target_prefix = "state-logs/"
}

# Bucket policy for state bucket (allows management operations, denies external without ACL)
resource "aws_s3_bucket_policy" "tfstate_policy" {
  bucket = aws_s3_bucket.tfstate.id
  depends_on = [
    aws_s3_bucket_versioning.tfstate_versioning,
    aws_s3_bucket_server_side_encryption_configuration.tfstate_encryption,
    aws_s3_bucket_public_access_block.tfstate_public_access,
    aws_s3_bucket_logging.tfstate_logging
  ]
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSameAccountManagement"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "s3:*"
        Resource = [
          aws_s3_bucket.tfstate.arn,
          "${aws_s3_bucket.tfstate.arn}/*"
        ]
      },
      {
        Sid    = "DenyExternalWithoutACL"
        Effect = "Deny"
        Principal = "*"
        Action   = "s3:*"
        Resource = [
          aws_s3_bucket.tfstate.arn,
          "${aws_s3_bucket.tfstate.arn}/*"
        ]
        Condition = {
          StringNotEquals = {
            "s3:x-amz-acl"        = "bucket-owner-full-control"
            "aws:PrincipalAccount" = local.account_id
          }
        }
      }
    ]
  })
}

# Secondary region KMS keys
resource "aws_kms_key" "replica_state_key" {
  provider                = aws.secondary
  description             = "KMS key for encrypting replica state bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "replica_state_key_alias" {
  provider      = aws.secondary
  name_prefix   = "alias/${var.environment_name}-replica-tfstate-key-"
  target_key_id = aws_kms_key.replica_state_key.id
}

resource "aws_kms_key" "replica_access_logs_key" {
  provider                = aws.secondary
  description             = "KMS key for encrypting replica access logs bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "replica_access_logs_key_alias" {
  provider      = aws.secondary
  name_prefix   = "alias/${var.environment_name}-replica-access-logs-key-"
  target_key_id = aws_kms_key.replica_access_logs_key.id
}

# Replica state bucket in secondary region
resource "aws_s3_bucket" "replica_tfstate" {
  provider = aws.secondary
  bucket   = "${var.environment_name}-replica-tfstate-${random_id.suffix.hex}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica_tfstate_versioning" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.replica_tfstate.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica_tfstate_encryption" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.replica_tfstate.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica_state_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "replica_tfstate_public_access" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.replica_tfstate.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Bucket policy for replica state bucket (allows management operations, denies external without ACL)
resource "aws_s3_bucket_policy" "replica_tfstate_policy" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.replica_tfstate.id
  depends_on = [
    aws_s3_bucket_versioning.replica_tfstate_versioning,
    aws_s3_bucket_server_side_encryption_configuration.replica_tfstate_encryption,
    aws_s3_bucket_public_access_block.replica_tfstate_public_access
  ]
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSameAccountManagement"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "s3:*"
        Resource = [
          aws_s3_bucket.replica_tfstate.arn,
          "${aws_s3_bucket.replica_tfstate.arn}/*"
        ]
      },
      {
        Sid    = "DenyExternalWithoutACL"
        Effect = "Deny"
        Principal = "*"
        Action   = "s3:*"
        Resource = [
          aws_s3_bucket.replica_tfstate.arn,
          "${aws_s3_bucket.replica_tfstate.arn}/*"
        ]
        Condition = {
          StringNotEquals = {
            "s3:x-amz-acl"        = "bucket-owner-full-control"
            "aws:PrincipalAccount" = local.account_id
          }
        }
      }
    ]
  })
}

# Dedicated logging bucket in secondary region for replica buckets
resource "aws_s3_bucket" "replica_logging" {
  provider = aws.secondary
  bucket   = "${var.environment_name}-replica-logs-${random_id.suffix.hex}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica_logging_versioning" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.replica_logging.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "replica_logging_ownership" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.replica_logging.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "replica_logging_acl" {
  provider   = aws.secondary
  depends_on = [aws_s3_bucket_ownership_controls.replica_logging_ownership]
  bucket     = aws_s3_bucket.replica_logging.id
  acl        = "log-delivery-write"
}

resource "aws_s3_bucket_public_access_block" "replica_logging_public_access" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.replica_logging.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Logging for replica state bucket (deliver logs to same-region logging bucket)
resource "aws_s3_bucket_logging" "replica_tfstate_logging" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.replica_tfstate.id

  target_bucket = aws_s3_bucket.replica_logging.id
  target_prefix = "replica-tfstate-logs/"
}

# Replica access logs bucket in secondary region
resource "aws_s3_bucket" "replica_access_logs" {
  provider = aws.secondary
  bucket   = "${var.environment_name}-replica-access-logs-${random_id.suffix.hex}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica_access_logs_versioning" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.replica_access_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "replica_access_logs_lifecycle" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.replica_access_logs.id

  rule {
    id     = "glacier-transition"
    status = "Enabled"

    filter {
      prefix = ""
    }

    transition {
      days          = var.glacier_transition_days
      storage_class = "GLACIER"
    }

    expiration {
      days = var.glacier_expiration_days
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica_access_logs_encryption" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.replica_access_logs.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica_access_logs_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "replica_access_logs_public_access" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.replica_access_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Logging for replica access logs bucket (deliver logs to same-region logging bucket)
resource "aws_s3_bucket_logging" "replica_access_logs_logging" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.replica_access_logs.id

  target_bucket = aws_s3_bucket.replica_logging.id
  target_prefix = "replica-access-logs-logs/"
}

# IAM Role and Policy for replication
resource "aws_iam_role" "replication_role" {
  name_prefix = "${var.environment_name}-s3-replication-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3Service"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "replication_policy" {
  name_prefix = "${var.environment_name}-s3-replication-policy-"
  description = "Policy for S3 cross-region replication"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3ReplicationSource"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersion",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.tfstate.arn,
          "${aws_s3_bucket.tfstate.arn}/*",
          aws_s3_bucket.access_logs.arn,
          "${aws_s3_bucket.access_logs.arn}/*"
        ]
      },
      {
        Sid    = "AllowS3ReplicationDestination"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = [
          aws_s3_bucket.replica_tfstate.arn,
          "${aws_s3_bucket.replica_tfstate.arn}/*",
          aws_s3_bucket.replica_access_logs.arn,
          "${aws_s3_bucket.replica_access_logs.arn}/*"
        ]
      },
      {
        Sid    = "AllowKMSDecryptSource"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = [
          aws_kms_key.state_key.arn
        ]
      },
      {
        Sid    = "AllowKMSEncryptDestination"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey"
        ]
        Resource = [
          aws_kms_key.replica_state_key.arn,
          aws_kms_key.replica_access_logs_key.arn
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication_policy_attachment" {
  role       = aws_iam_role.replication_role.name
  policy_arn = aws_iam_policy.replication_policy.arn
}

# Replication configuration for state bucket
resource "aws_s3_bucket_replication_configuration" "tfstate_replication" {
  bucket = aws_s3_bucket.tfstate.id
  role   = aws_iam_role.replication_role.arn

  rule {
    id     = "state-replication"
    status = "Enabled"

    delete_marker_replication {
      status = "Enabled"
    }

    filter {
      prefix = ""
    }

    destination {
      bucket        = aws_s3_bucket.replica_tfstate.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica_state_key.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.replication_policy_attachment
  ]
}

# Replication configuration for access logs bucket
resource "aws_s3_bucket_replication_configuration" "access_logs_replication" {
  bucket = aws_s3_bucket.access_logs.id
  role   = aws_iam_role.replication_role.arn

  rule {
    id     = "access-logs-replication"
    status = "Enabled"

    delete_marker_replication {
      status = "Enabled"
    }

    filter {
      prefix = ""
    }

    destination {
      bucket        = aws_s3_bucket.replica_access_logs.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica_access_logs_key.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.replication_policy_attachment
  ]
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Variables
variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "existing_vpc_id" {
  description = "ID of an existing VPC. If provided, no new VPC will be created."
  type        = string
  default     = ""
}

variable "existing_subnet_ids" {
  description = "Map of subnet type to list of subnet IDs. If non-empty, subnet creation is skipped."
  type        = map(list(string))
  default     = {}
}

variable "existing_nat_id" {
  description = "ID of an existing NAT Gateway. If provided, no new NAT Gateway will be created."
  type        = string
  default     = ""
}

variable "existing_endpoint_sg_id" {
  description = "ID of an existing security group for VPC endpoints. If provided, no new SG is created."
  type        = string
  default     = ""
}

variable "endpoint_services" {
  description = "List of AWS services for which to create interface VPC endpoints (S3 is handled separately via a Gateway endpoint)."
  type        = list(string)
  default = [
    "ec2",
    "ecr.api",
    "ecr.dkr",
    "logs",
    "sts",
    "elasticloadbalancing",
    "autoscaling"
  ]
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_vpc" "existing" {
  count = var.existing_vpc_id != "" ? 1 : 0
  id    = var.existing_vpc_id
}

# Locals
locals {
  vpc_id = var.existing_vpc_id != "" ? data.aws_vpc.existing[0].id : aws_vpc.main[0].id

  public_subnet_ids   = length(var.existing_subnet_ids) > 0 ? lookup(var.existing_subnet_ids, "public", []) : aws_subnet.public[*].id
  private_subnet_ids  = length(var.existing_subnet_ids) > 0 ? lookup(var.existing_subnet_ids, "private", []) : aws_subnet.private[*].id
  database_subnet_ids = length(var.existing_subnet_ids) > 0 ? lookup(var.existing_subnet_ids, "database", []) : aws_subnet.database[*].id

  default_public_cidrs   = ["10.0.1.0/24", "10.0.2.0/24"]
  default_private_cidrs  = ["10.0.11.0/24", "10.0.12.0/24"]
  default_database_cidrs = ["10.0.21.0/24", "10.0.22.0/24"]
}

# VPC
resource "aws_vpc" "main" {
  count = var.existing_vpc_id == "" ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = var.vpc_name
  }
}

# Subnets (only if no existing subnet IDs)
resource "aws_subnet" "public" {
  count = length(var.existing_subnet_ids) == 0 ? 2 : 0

  vpc_id                  = local.vpc_id
  cidr_block              = local.default_public_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.vpc_name}-public-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.existing_subnet_ids) == 0 ? 2 : 0

  vpc_id            = local.vpc_id
  cidr_block        = local.default_private_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.vpc_name}-private-${count.index + 1}"
  }
}

resource "aws_subnet" "database" {
  count = length(var.existing_subnet_ids) == 0 ? 2 : 0

  vpc_id            = local.vpc_id
  cidr_block        = local.default_database_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.vpc_name}-database-${count.index + 1}"
  }
}

# Internet Gateway (only if creating new VPC)
resource "aws_internet_gateway" "main" {
  count = var.existing_vpc_id == "" ? 1 : 0

  vpc_id = local.vpc_id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

# Elastic IP for NAT (only if no existing NAT)
resource "aws_eip" "nat" {
  count = var.existing_nat_id == "" ? 1 : 0

  domain = "vpc"

  tags = {
    Name = "${var.vpc_name}-nat-eip"
  }
}

# NAT Gateway (only if no existing NAT)
resource "aws_nat_gateway" "main" {
  count = var.existing_nat_id == "" ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = local.public_subnet_ids[0]

  tags = {
    Name = "${var.vpc_name}-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

# Route Tables (only if subnets were created)
resource "aws_route_table" "public" {
  count = length(var.existing_subnet_ids) == 0 ? 1 : 0

  vpc_id = local.vpc_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = {
    Name = "${var.vpc_name}-public-rt"
  }
}

resource "aws_route_table" "private" {
  count = length(var.existing_subnet_ids) == 0 ? 1 : 0

  vpc_id = local.vpc_id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = var.existing_nat_id != "" ? var.existing_nat_id : aws_nat_gateway.main[0].id
  }

  tags = {
    Name = "${var.vpc_name}-private-rt"
  }
}

# Route Table Associations (only if subnets were created)
resource "aws_route_table_association" "public" {
  count = length(var.existing_subnet_ids) == 0 ? 2 : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table_association" "private" {
  count = length(var.existing_subnet_ids) == 0 ? 2 : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

# DB Subnet Group (always created)
resource "aws_db_subnet_group" "rds" {
  name       = lower(var.vpc_name)
  subnet_ids = local.database_subnet_ids

  tags = {
    Name = "${var.vpc_name}-rds-subnet-group"
  }
}

# Endpoint Security Group (only if no existing SG)
resource "aws_security_group" "vpc_endpoints" {
  count = var.existing_endpoint_sg_id == "" ? 1 : 0

  name        = "${var.vpc_name}-vpc-endpoints"
  description = "Security group for VPC endpoints"
  vpc_id      = local.vpc_id

  ingress {
    description = "Allow HTTPS from VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow all outbound traffic within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${var.vpc_name}-vpc-endpoints"
  }
}

# Interface VPC Endpoints (excluding S3)
resource "aws_vpc_endpoint" "interface" {
  for_each = toset(var.endpoint_services)

  vpc_id              = local.vpc_id
  service_name        = "com.amazonaws.us-east-1.${each.key}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = local.private_subnet_ids
  security_group_ids  = var.existing_endpoint_sg_id != "" ? [var.existing_endpoint_sg_id] : [aws_security_group.vpc_endpoints[0].id]
  private_dns_enabled = true

  tags = {
    Name = "${var.vpc_name}-${each.key}"
  }
}

# Gateway VPC Endpoint for S3 (with route table associations)
resource "aws_vpc_endpoint" "s3_gateway" {
  vpc_id            = local.vpc_id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [for rt in aws_route_table.private[*].id : rt]

  tags = {
    Name = "${var.vpc_name}-s3-gateway"
  }
}

# KMS key policy document allowing CloudWatch Logs service
data "aws_iam_policy_document" "kms_cloudwatch_policy" {
  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "Allow CloudWatch Logs to use the key"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
  }
}

# KMS key for CloudWatch Log Group encryption
resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for CloudWatch Log Group encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy                  = data.aws_iam_policy_document.kms_cloudwatch_policy.json

  tags = {
    Name = "${var.vpc_name}-cloudwatch-kms-key"
  }
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/cloudwatch-${var.vpc_name}"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

# VPC Flow Logs – CloudWatch Log Group (encrypted with CMK)
resource "aws_cloudwatch_log_group" "vpc_flow_log" {
  name              = "/aws/vpc/flow-logs/${var.vpc_name}"
  retention_in_days = 7
  kms_key_id        = aws_kms_key.cloudwatch.arn

  tags = {
    Name = "${var.vpc_name}-flow-log-group"
  }
}

# IAM role for VPC Flow Logs
data "aws_iam_policy_document" "flow_log_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "vpc_flow_log" {
  name               = "${var.vpc_name}-flow-log-role"
  assume_role_policy = data.aws_iam_policy_document.flow_log_assume_role.json

  tags = {
    Name = "${var.vpc_name}-flow-log-role"
  }
}

# Custom policy for flow log permissions (including KMS)
data "aws_iam_policy_document" "flow_log_policy" {
  statement {
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams"
    ]
    resources = [aws_cloudwatch_log_group.vpc_flow_log.arn]
  }

  statement {
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = [aws_kms_key.cloudwatch.arn]
  }
}

resource "aws_iam_policy" "vpc_flow_log" {
  name   = "${var.vpc_name}-flow-log-policy"
  policy = data.aws_iam_policy_document.flow_log_policy.json

  tags = {
    Name = "${var.vpc_name}-flow-log-policy"
  }
}

resource "aws_iam_role_policy_attachment" "vpc_flow_log" {
  role       = aws_iam_role.vpc_flow_log.name
  policy_arn = aws_iam_policy.vpc_flow_log.arn
}

# VPC Flow Log resource
resource "aws_flow_log" "main" {
  log_destination      = aws_cloudwatch_log_group.vpc_flow_log.arn
  log_destination_type = "cloud-watch-logs"
  traffic_type         = "ALL"
  vpc_id               = local.vpc_id
  iam_role_arn         = aws_iam_role.vpc_flow_log.arn

  tags = {
    Name = "${var.vpc_name}-flow-log"
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "app_shortcode" {
  description = "Shortcode used as prefix for IAM role and instance profile names"
  type        = string
  default     = "bmk"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_ami" "amazon_linux2" {
  most_recent = true
  owners      = ["amazon"]
  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-2.0.*-x86_64-ebs"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.8.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "testing-vpc"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.8.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]
  tags = {
    Name = "private-subnet"
  }
}

resource "aws_security_group" "vpc_endpoints" {
  name        = "vpc-endpoints-sg"
  description = "Security group for VPC endpoints"
  vpc_id      = aws_vpc.main.id
  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
  # No egress rules
  tags = {
    Name = "vpc-endpoints-sg"
  }
}

resource "aws_vpc_endpoint" "ssm" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ssm"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  private_dns_enabled = true
  auto_accept         = true
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  tags = {
    Name = "ssm-endpoint"
  }
}

resource "aws_vpc_endpoint" "ec2messages" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ec2messages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  private_dns_enabled = true
  auto_accept         = true
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  tags = {
    Name = "ec2messages-endpoint"
  }
}

resource "aws_vpc_endpoint" "ssmmessages" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ssmmessages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  private_dns_enabled = true
  auto_accept         = true
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  tags = {
    Name = "ssmmessages-endpoint"
  }
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  private_dns_enabled = true
  auto_accept         = true
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  tags = {
    Name = "logs-endpoint"
  }
}

resource "aws_kms_key" "ebs" {
  description             = "KMS key for EBS root volume encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow EC2 Instance Role to Use Key"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.instance_role.arn
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })
  tags = {
    Name = "ebs-encryption-key"
  }
}

resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for CloudWatch Logs encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          ArnEquals = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/vpc/flow-logs"
          }
        }
      }
    ]
  })
  tags = {
    Name = "${var.app_shortcode}-cloudwatch-key"
  }
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/${var.app_shortcode}/cloudwatch-logs"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

resource "aws_iam_role" "instance_role" {
  name = "${var.app_shortcode}-ssm-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = {
    Name = "${var.app_shortcode}-ssm-role"
  }
}

resource "aws_iam_policy" "ssm_and_logs" {
  name        = "${var.app_shortcode}-ssm-logs-policy"
  description = "Policy for SSM, logs, KMS, and S3 permissions"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "ssm:*",
          "ssmmessages:*",
          "ec2messages:*"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = aws_kms_key.ebs.arn
      },
      {
        Effect   = "Allow"
        Action   = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach" {
  role       = aws_iam_role.instance_role.name
  policy_arn = aws_iam_policy.ssm_and_logs.arn
}

resource "aws_iam_instance_profile" "instance_profile" {
  name = "${var.app_shortcode}-instance-profile"
  role = aws_iam_role.instance_role.name
}

resource "aws_security_group" "instance" {
  name        = "instance-sg"
  description = "Security group for test EC2 instance"
  vpc_id      = aws_vpc.main.id
  egress {
    description = "HTTPS to VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
  tags = {
    Name = "instance-sg"
  }
}

resource "aws_instance" "test" {
  ami                    = data.aws_ami.amazon_linux2.id
  instance_type          = "t3.small"
  subnet_id              = aws_subnet.private.id
  vpc_security_group_ids = [aws_security_group.instance.id]
  iam_instance_profile   = aws_iam_instance_profile.instance_profile.name
  associate_public_ip_address = false
  source_dest_check      = false

  root_block_device {
    volume_size = 8
    volume_type = "gp3"
    encrypted   = true
    kms_key_id  = aws_kms_key.ebs.arn
  }

  metadata_options {
    http_tokens   = "required"
    http_endpoint = "enabled"
  }

  tags = {
    Name = "test-instance"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# --- VPC Flow Logs resources ---
resource "aws_cloudwatch_log_group" "vpc_flow" {
  name              = "/aws/vpc/flow-logs"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.cloudwatch.arn
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "flow_log" {
  name = "${var.app_shortcode}-vpc-flow-log-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = {
    Name = "${var.app_shortcode}-vpc-flow-log-role"
  }
}

resource "aws_iam_role_policy" "flow_log" {
  name = "${var.app_shortcode}-vpc-flow-log-policy"
  role = aws_iam_role.flow_log.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups"
        ]
        Resource = aws_cloudwatch_log_group.vpc_flow.arn
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt"
        ]
        Resource = aws_kms_key.cloudwatch.arn
      }
    ]
  })
}

resource "aws_flow_log" "vpc" {
  log_group_name = aws_cloudwatch_log_group.vpc_flow.name
  traffic_type   = "REJECT"
  vpc_id         = aws_vpc.main.id
  iam_role_arn   = aws_iam_role.flow_log.arn
  tags = {
    Name = "vpc-flow-log"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

import {
  to = aws_ecr_repository.main
  id = "nginx-fargate-repo"
}

import {
  to = aws_iam_role.ecs_execution
  id = "ecs-execution-role"
}

import {
  to = aws_iam_role.ecs_task
  id = "ecs-task-role"
}

import {
  to = aws_iam_role.jumphost
  id = "jumphost-role"
}

import {
  to = aws_iam_role.flow_logs
  id = "vpc-flow-logs-role"
}

import {
  to = aws_cloudwatch_log_group.ecs
  id = "/ecs/nginx-fargate"
}

import {
  to = aws_cloudwatch_log_group.flow_logs
  id = "/vpc/flow-logs"
}

import {
  to = aws_iam_instance_profile.jumphost
  id = "jumphost-instance-profile"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
  owners = ["amazon"]
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  tags = {
    Name = "fargate-crowdnews-vpc"
  }
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet("10.0.0.0/16", 4, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet("10.0.0.0/16", 4, count.index + 8)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "fargate-crowdnews-igw"
  }
}

resource "aws_eip" "nat" {
  count  = 3
  domain = "vpc"
  tags = {
    Name = "nat-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "main" {
  count         = 3
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id
  tags = {
    Name = "nat-gw-${count.index + 1}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = {
    Name = "public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count  = 3
  vpc_id = aws_vpc.main.id
  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }
  tags = {
    Name = "private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

