resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for CloudWatch log group and EBS encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable CloudWatch Logs"
        Effect = "Allow"
        Principal = {
          Service = "logs.us-east-1.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          ArnEquals = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:aws:logs:us-east-1:${data.aws_caller_identity.current.account_id}:log-group:*"
          }
        }
      },
      {
        Sid    = "Enable EC2 EBS"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "kms:Create*",
          "kms:Describe*",
          "kms:Enable*",
          "kms:List*",
          "kms:Put*",
          "kms:Update*",
          "kms:Revoke*",
          "kms:Disable*",
          "kms:Get*",
          "kms:Delete*",
          "kms:Tag*",
          "kms:Untag*",
          "kms:ScheduleKeyDeletion",
          "kms:CancelKeyDeletion",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

data "aws_caller_identity" "current" {}

resource "aws_cloudwatch_log_group" "ecs" {
  name              = "/ecs/nginx-fargate"
  kms_key_id        = aws_kms_key.cloudwatch.arn
}

resource "aws_kms_key" "ecr" {
  description             = "KMS key for ECR repository encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable ECR"
        Effect = "Allow"
        Principal = {
          Service = "ecr.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "kms:Create*",
          "kms:Describe*",
          "kms:Enable*",
          "kms:List*",
          "kms:Put*",
          "kms:Update*",
          "kms:Revoke*",
          "kms:Disable*",
          "kms:Get*",
          "kms:Delete*",
          "kms:Tag*",
          "kms:Untag*",
          "kms:ScheduleKeyDeletion",
          "kms:CancelKeyDeletion",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_ecr_repository" "main" {
  name                 = "nginx-fargate-repo"
  image_tag_mutability = "IMMUTABLE"
  image_scanning_configuration {
    scan_on_push = true
  }
  encryption_configuration {
    encryption_type = "KMS"
    kms_key         = aws_kms_key.ecr.key_id
  }
}

resource "aws_ecs_cluster" "main" {
  name = "nginx-fargate-cluster"
  setting {
    name  = "containerInsights"
    value = "enabled"
  }
}

resource "aws_iam_role" "ecs_execution" {
  name = "ecs-execution-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_execution" {
  name = "ecs-execution-policy"
  role = aws_iam_role.ecs_execution.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecr:BatchCheckLayerAvailability"
        ]
        Resource = aws_ecr_repository.main.arn
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role" "ecs_task" {
  name = "ecs-task-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_task" {
  name = "ecs-task-policy"
  role = aws_iam_role.ecs_task.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ssm:GetParameter",
          "ssm:GetParameters"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "servicediscovery:DiscoverInstances",
          "servicediscovery:GetInstance",
          "servicediscovery:ListInstances"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_ecs_task_definition" "nginx" {
  family                   = "nginx-fargate"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = 512
  memory                   = 1024
  execution_role_arn       = aws_iam_role.ecs_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn
  container_definitions = jsonencode([
    {
      name  = "nginx"
      image = "nginx:latest"
      essential = true
      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
          protocol      = "tcp"
        }
      ]
      environment = [
        {
          name  = "SERVICE_DISCOVERY_NAMESPACE_ID"
          value = aws_service_discovery_private_dns_namespace.main.id
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.ecs.name
          "awslogs-region"        = "us-east-1"
          "awslogs-stream-prefix" = "nginx"
        }
      }
    }
  ])
}

resource "aws_security_group" "ecs_tasks" {
  name_prefix = "ecs-tasks-sg-"
  description = "Security group for ECS tasks"
  vpc_id      = aws_vpc.main.id
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
    description = "HTTP from VPC"
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
    description = "Outbound to VPC"
  }
  tags = {
    Name = "ecs-tasks-sg"
  }
}

resource "aws_service_discovery_service" "main" {
  name = "nginx-fargate-service"
  dns_config {
    namespace_id = aws_service_discovery_private_dns_namespace.main.id
    dns_records {
      type = "A"
      ttl  = 10
    }
    dns_records {
      type = "SRV"
      ttl  = 10
    }
    routing_policy = "MULTIVALUE"
  }
  health_check_custom_config {
    failure_threshold = 1
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecs_service" "main" {
  name            = "nginx-fargate-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.nginx.arn
  desired_count   = 1
  launch_type     = "FARGATE"
  network_configuration {
    subnets         = aws_subnet.private[*].id
    security_groups = [aws_security_group.ecs_tasks.id]
    assign_public_ip = false
  }
  service_registries {
    registry_arn   = aws_service_discovery_service.main.arn
    container_name = "nginx"
    container_port = 80
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "jumphost" {
  name = "jumphost-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "jumphost_ssm" {
  role       = aws_iam_role.jumphost.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "jumphost" {
  name = "jumphost-instance-profile"
  role = aws_iam_role.jumphost.name
}

resource "aws_security_group" "jumphost" {
  name_prefix = "jumphost-sg-"
  description = "Security group for jumphost EC2"
  vpc_id      = aws_vpc.main.id
  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
    description = "All traffic from VPC"
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
    description = "Outbound to VPC"
  }
  tags = {
    Name = "jumphost-sg"
  }
}

resource "aws_network_interface" "jumphost" {
  subnet_id       = aws_subnet.public[0].id
  private_ips     = ["10.0.0.10"]
  security_groups = [aws_security_group.jumphost.id]
  tags = {
    Name = "jumphost-eni"
  }
}

resource "aws_instance" "jumphost" {
  ami           = data.aws_ami.amazon_linux_2.id
  instance_type = "t3.micro"
  iam_instance_profile = aws_iam_instance_profile.jumphost.name
  metadata_options {
    http_tokens = "required"
  }
  root_block_device {
    encrypted  = true
    kms_key_id = aws_kms_key.cloudwatch.arn
  }
  network_interface {
    device_index         = 0
    network_interface_id = aws_network_interface.jumphost.id
  }
  tags = {
    Name = "jumphost"
  }
}

resource "aws_iam_role" "flow_logs" {
  name = "vpc-flow-logs-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "flow_logs" {
  name = "vpc-flow-logs-policy"
  role = aws_iam_role.flow_logs.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = aws_cloudwatch_log_group.flow_logs.arn
      }
    ]
  })
}

resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = "/vpc/flow-logs"
  kms_key_id        = aws_kms_key.cloudwatch.arn
}

resource "aws_flow_log" "main" {
  iam_role_arn         = aws_iam_role.flow_logs.arn
  log_destination      = aws_cloudwatch_log_group.flow_logs.arn
  log_destination_type = "cloud-watch-logs"
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.main.id
}

output "curl_command" {
  value = "curl http://${aws_service_discovery_service.main.name}.${aws_service_discovery_private_dns_namespace.main.name}"
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

# Variables
variable "project" {
  description = "Project name for naming and tagging"
  type        = string
  default     = "benchmark"
}

variable "application" {
  description = "Application name for naming and tagging"
  type        = string
  default     = "app"
}

variable "environment" {
  description = "Environment name (e.g., dev, test, prod)"
  type        = string
  default     = "dev"
}

variable "availability_zone" {
  description = "Availability zone for subnet placement"
  type        = string
  default     = null
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "10.0.1.0/24"
}

variable "create_ssh_key_pair" {
  description = "Whether to generate and attach an SSH key pair"
  type        = bool
  default     = false
}

variable "allocate_eip" {
  description = "Whether to allocate and associate an Elastic IP"
  type        = bool
  default     = false
}

variable "attach_managed_ssm_policy" {
  description = "Whether to attach the AWS managed AmazonSSMManagedInstanceCore policy"
  type        = bool
  default     = false
}

variable "custom_routes" {
  description = "List of custom routes to add to the route table. Each entry requires 'cidr_block' and optionally 'gateway_id'."
  type = list(object({
    cidr_block = string
    gateway_id = optional(string)
  }))
  default = []
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-2.0.*-x86_64-gp2"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

# Static provider metadata
data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

# Locals
locals {
  az_name   = var.availability_zone != null ? var.availability_zone : data.aws_availability_zones.available.names[0]
  az_short  = element(split("-", local.az_name), length(split("-", local.az_name)) - 1)
  name_prefix = "${var.project}-${var.application}-${var.environment}-${local.az_short}"

  common_tags = {
    Project     = var.project
    Application = var.application
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# VPC
resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

# Internet Gateway
resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

# Subnet
resource "aws_subnet" "this" {
  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.subnet_cidr
  availability_zone       = local.az_name
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet"
  })
}

# Route Table
resource "aws_route_table" "this" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  dynamic "route" {
    for_each = var.custom_routes
    content {
      cidr_block = route.value.cidr_block
      gateway_id = route.value.gateway_id
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rt"
  })
}

resource "aws_route_table_association" "this" {
  subnet_id      = aws_subnet.this.id
  route_table_id = aws_route_table.this.id
}

# Security Group
resource "aws_security_group" "this" {
  name        = "${local.name_prefix}-sg"
  description = "Security group for EC2 instance"
  vpc_id      = aws_vpc.this.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.this.cidr_block]
    description = "Outbound traffic to VPC CIDR"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sg"
  })
}

# IAM Role for EC2/SSM
resource "aws_iam_role" "this" {
  name = "${local.name_prefix}-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "ec2.amazonaws.com",
            "ssm.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-role"
  })
}

# Dedicated SSM Session Manager Policy
data "aws_iam_policy_document" "ssm_session_manager" {
  statement {
    effect = "Allow"
    actions = [
      "ssm:StartSession",
      "ssm:TerminateSession",
      "ssmmessages:CreateControlChannel",
      "ssmmessages:CreateDataChannel",
      "ssmmessages:OpenControlChannel",
      "ssmmessages:OpenDataChannel",
      "ec2messages:*"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "ssm_session_manager" {
  name        = "${local.name_prefix}-ssm-session-manager"
  description = "Policy granting SSM Session Manager permissions"
  policy      = data.aws_iam_policy_document.ssm_session_manager.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ssm-policy"
  })
}

resource "aws_iam_role_policy_attachment" "ssm_session_manager" {
  role       = aws_iam_role.this.name
  policy_arn = aws_iam_policy.ssm_session_manager.arn
}

# Conditionally attach the AWS managed SSM policy using a static ARN
resource "aws_iam_role_policy_attachment" "amazon_ssm_managed_instance_core" {
  count = var.attach_managed_ssm_policy ? 1 : 0
  role  = aws_iam_role.this.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

# Instance Profile
resource "aws_iam_instance_profile" "this" {
  name = "${local.name_prefix}-instance-profile"
  role = aws_iam_role.this.name

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-profile"
  })
}

# Network Interface
resource "aws_network_interface" "this" {
  subnet_id       = aws_subnet.this.id
  security_groups = [aws_security_group.this.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-eni"
  })
}

# Optional SSH Key Pair
resource "tls_private_key" "this" {
  count     = var.create_ssh_key_pair ? 1 : 0
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "this" {
  count      = var.create_ssh_key_pair ? 1 : 0
  key_name   = "${local.name_prefix}-key"
  public_key = tls_private_key.this[0].public_key_openssh

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-key"
  })
}

# EC2 Instance
resource "aws_instance" "this" {
  ami           = data.aws_ami.amazon_linux_2.id
  instance_type = "t3.micro"
  key_name      = var.create_ssh_key_pair ? aws_key_pair.this[0].key_name : null

  network_interface {
    network_interface_id = aws_network_interface.this.id
    device_index         = 0
  }

  metadata_options {
    http_tokens     = "required"
    http_endpoint   = "enabled"
    http_put_response_hop_limit = 1
  }

  root_block_device {
    volume_size = 20
    encrypted   = true
    kms_key_id  = aws_kms_key.flow_logs.arn
  }

  iam_instance_profile = aws_iam_instance_profile.this.name

  instance_initiated_shutdown_behavior = "stop"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ec2"
  })
}

# Optional Elastic IP
resource "aws_eip" "this" {
  count = var.allocate_eip ? 1 : 0
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-eip"
  })
}

resource "aws_eip_association" "this" {
  count         = var.allocate_eip ? 1 : 0
  allocation_id = aws_eip.this[0].id
  network_interface_id = aws_network_interface.this.id
}

# VPC Flow Logs - KMS Key
resource "aws_kms_key" "flow_logs" {
  description             = "${local.name_prefix}-flow-logs-key"
  enable_key_rotation     = true
  is_enabled              = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAdmin"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogs"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          ArnEquals = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${local.name_prefix}-vpc-flow-logs"
          }
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-flow-logs-key"
  })
}

resource "aws_kms_alias" "flow_logs" {
  name          = "alias/${local.name_prefix}-flow-logs"
  target_key_id = aws_kms_key.flow_logs.key_id
}

# VPC Flow Logs - CloudWatch Log Group
resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = "${local.name_prefix}-vpc-flow-logs"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.flow_logs.arn

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-flow-logs-lg"
  })
}

# IAM Role for Flow Logs
data "aws_iam_policy_document" "flow_logs_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "flow_logs" {
  name               = "${local.name_prefix}-flow-logs-role"
  assume_role_policy = data.aws_iam_policy_document.flow_logs_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-flow-logs-role"
  })
}

data "aws_iam_policy_document" "flow_logs" {
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams"
    ]
    resources = ["arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${aws_cloudwatch_log_group.flow_logs.name}:*"]
  }
}

resource "aws_iam_policy" "flow_logs" {
  name   = "${local.name_prefix}-flow-logs-policy"
  policy = data.aws_iam_policy_document.flow_logs.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-flow-logs-policy"
  })
}

resource "aws_iam_role_policy_attachment" "flow_logs" {
  role       = aws_iam_role.flow_logs.name
  policy_arn = aws_iam_policy.flow_logs.arn
}

resource "aws_flow_log" "this" {
  iam_role_arn    = aws_iam_role.flow_logs.arn
  log_destination = aws_cloudwatch_log_group.flow_logs.arn
  traffic_type    = "REJECT"
  vpc_id          = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc-flow-log"
  })
}

# Outputs
output "ec2_instance_id" {
  description = "ID of the EC2 instance"
  value       = aws_instance.this.id
}

output "ec2_instance_arn" {
  description = "ARN of the EC2 instance"
  value       = aws_instance.this.arn
}

output "iam_role_arn" {
  description = "ARN of the IAM role"
  value       = aws_iam_role.this.arn
}

output "iam_instance_profile_arn" {
  description = "ARN of the IAM instance profile"
  value       = aws_iam_instance_profile.this.arn
}

output "route_table_id" {
  description = "ID of the route table"
  value       = aws_route_table.this.id
}

output "subnet_id" {
  description = "ID of the subnet"
  value       = aws_subnet.this.id
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.9"
    }
  }
}

# Data sources for static metadata
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# Retrieve the latest Amazon EKS-optimized AMI for Amazon Linux 2
data "aws_ami" "eks_ami" {
  most_recent = true
  owners      = ["602401143452"]  # Official Amazon EKS AMI owner

  filter {
    name   = "name"
    values = ["amazon-eks-node-*"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = { Name = "demo-eks-vpc" }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags   = { Name = "demo-eks-igw" }
}

# Public subnet (map_public_ip_on_launch = false per security fix)
resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.0.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false
  tags = { Name = "demo-eks-public" }
}

# Private subnets (one per AZ)
resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet("10.0.0.0/16", 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = { Name = "demo-eks-private-${data.aws_availability_zones.available.names[count.index]}" }
}

# NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"
  tags   = { Name = "demo-eks-nat-eip" }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id
  tags          = { Name = "demo-eks-nat" }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = { Name = "demo-eks-public-rt" }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Private route table (one for all private subnets)
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }
  tags = { Name = "demo-eks-private-rt" }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# KMS Key for EKS secrets encryption
resource "aws_kms_key" "eks" {
  description             = "EKS secret encryption key"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow EKS Cluster Role to use KMS"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/eksClusterRole"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = { Name = "demo-eks-kms" }
}

resource "aws_kms_alias" "eks" {
  name          = "alias/eks-demo"
  target_key_id = aws_kms_key.eks.key_id
}

# EKS Cluster IAM Role
resource "aws_iam_role" "eks_cluster" {
  name = "eksClusterRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = { Name = "eksClusterRole" }
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "vpc_resource_controller" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
}

# EKS Cluster with all control plane logging enabled (no explicit version - uses latest supported)
resource "aws_eks_cluster" "demo" {
  name     = "demo-eks"
  role_arn = aws_iam_role.eks_cluster.arn

  enabled_cluster_log_types = [
    "api",
    "audit",
    "authenticator",
    "controllerManager",
    "scheduler"
  ]

  vpc_config {
    subnet_ids              = aws_subnet.private[*].id
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  encryption_config {
    provider {
      key_arn = aws_kms_key.eks.arn
    }
    resources = ["secrets"]
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.vpc_resource_controller
  ]

  tags = { Name = "demo-eks" }
}

# TLS private key and key pair
resource "tls_private_key" "eks" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "local_file" "eks_private_key" {
  content         = tls_private_key.eks.private_key_pem
  filename        = pathexpand("~/.ssh/eks-aws.pem")
  file_permission = "0600"
}

resource "aws_key_pair" "eks" {
  key_name   = "eks_kp"
  public_key = tls_private_key.eks.public_key_openssh
}

# Node security group
resource "aws_security_group" "node" {
  name        = "demo-eks-node-sg"
  description = "Security group for EKS worker nodes"
  vpc_id      = aws_vpc.main.id

  tags = { Name = "demo-eks-node-sg" }
}

# Security group rules with descriptions
resource "aws_security_group_rule" "node_self" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.node.id
  security_group_id        = aws_security_group.node.id
  description              = "Allow all traffic between nodes"
}

resource "aws_security_group_rule" "node_egress_vpc" {
  type             = "egress"
  from_port        = 0
  to_port          = 0
  protocol         = "-1"
  cidr_blocks      = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.node.id
  description      = "Outbound to VPC CIDR"
}

resource "aws_security_group_rule" "node_ingress_eks" {
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.demo.vpc_config[0].cluster_security_group_id
  security_group_id        = aws_security_group.node.id
  description              = "Ingress from EKS cluster on port 443"
}

resource "aws_security_group_rule" "node_ingress_eks_wide" {
  type                     = "ingress"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.demo.vpc_config[0].cluster_security_group_id
  security_group_id        = aws_security_group.node.id
  description              = "Ingress from EKS cluster on ports 1025-65535"
}

resource "aws_security_group_rule" "node_egress_eks" {
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.demo.vpc_config[0].cluster_security_group_id
  security_group_id        = aws_security_group.node.id
  description              = "Egress to EKS cluster on port 443"
}

resource "aws_security_group_rule" "node_egress_eks_wide" {
  type                     = "egress"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.demo.vpc_config[0].cluster_security_group_id
  security_group_id        = aws_security_group.node.id
  description              = "Egress to EKS cluster on ports 1025-65535"
}

# Node IAM role
resource "aws_iam_role" "node" {
  name = "eks-demo-node"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = { Name = "eks-demo-node" }
}

resource "aws_iam_role_policy_attachment" "node_worker" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "node_cni" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "node_ecr" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_role_policy_attachment" "node_ssm" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "node" {
  name = "eks-demo-node-profile"
  role = aws_iam_role.node.name
}

# Launch template
resource "aws_launch_template" "node" {
  name_prefix   = "demo-eks-node-"
  image_id      = data.aws_ami.eks_ami.id
  instance_type = "t3.medium"
  key_name      = aws_key_pair.eks.key_name

  block_device_mappings {
    device_name = "/dev/xvda"
    ebs {
      volume_size = 30
      volume_type = "gp2"
    }
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  user_data = base64encode(<<-EOF
#!/bin/bash
set -x

# Run bootstrap and capture exit code for logging
/etc/eks/bootstrap.sh 'demo-eks' \
  --apiserver-endpoint '${aws_eks_cluster.demo.endpoint}' \
  --b64-cluster-ca '${aws_eks_cluster.demo.certificate_authority[0].data}' \
  --use-max-pods true

# Log exit code (no CloudFormation signaling)
echo "Bootstrap completed with exit code: $?"
EOF
  )

  tag_specifications {
    resource_type = "instance"
    tags = {
      Name = "demo-eks-node"
    }
  }

  depends_on = [
    aws_eks_cluster.demo
  ]
}

# 30-second delay after launch template creation
resource "time_sleep" "launch_template" {
  depends_on = [aws_launch_template.node]
  create_duration = "30s"
}

# VPC Flow Logs (fix AVD-AWS-0178)
resource "aws_iam_role" "flow_logs" {
  name = "demo-eks-flow-logs-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = { Name = "demo-eks-flow-logs-role" }
}

# Custom policy for flow logs (replacing non-existent managed policy)
resource "aws_iam_policy" "flow_logs" {
  name        = "demo-eks-flow-logs-policy"
  description = "Policy for VPC Flow Logs to publish to CloudWatch Logs"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      }
    ]
  })
  tags = { Name = "demo-eks-flow-logs-policy" }
}

resource "aws_iam_role_policy_attachment" "flow_logs_custom" {
  role       = aws_iam_role.flow_logs.name
  policy_arn = aws_iam_policy.flow_logs.arn
}

# Dedicated KMS key for CloudWatch Logs (fix AWS-0017)
resource "aws_kms_key" "cloudwatch" {
  description             = "KMS key for CloudWatch Logs encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogs"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = { Name = "demo-eks-cloudwatch-kms" }
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/cloudwatch-logs"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = "/aws/vpc-flow-logs/demo-eks"
  retention_in_days = 7
  kms_key_id        = aws_kms_key.cloudwatch.arn
  tags              = { Name = "demo-eks-flow-logs" }
}

resource "aws_flow_log" "main" {
  iam_role_arn    = aws_iam_role.flow_logs.arn
  log_destination = aws_cloudwatch_log_group.flow_logs.arn
  traffic_type    = "ALL"
  vpc_id          = aws_vpc.main.id
  tags            = { Name = "demo-eks-flow-logs" }
}

# CloudFormation stack for Auto Scaling Group
locals {
  cf_template = <<-TEMPLATE
AWSTemplateFormatVersion: '2010-09-09'
Resources:
  AutoScalingGroup:
    Type: AWS::AutoScaling::AutoScalingGroup
    Properties:
      AutoScalingGroupName: demo-eks-asg
      LaunchTemplate:
        LaunchTemplateId: ${aws_launch_template.node.id}
        Version: ${aws_launch_template.node.latest_version}
      VPCZoneIdentifier:
${join("\n", [for subnet in aws_subnet.private[*].id : format("        - \"%s\"", subnet)])}
      MinSize: '1'
      DesiredCapacity: '3'
      MaxSize: '4'
      Tags:
        - Key: Name
          Value: demo-eks-node
          PropagateAtLaunch: true
        - Key: kubernetes.io/cluster/demo-eks
          Value: owned
          PropagateAtLaunch: true
    UpdatePolicy:
      AutoScalingRollingUpdate:
        MaxBatchSize: '1'
        MinInstancesInService: '3'
        PauseTime: 'PT5M'
Outputs:
  AutoScalingGroupID:
    Description: Auto Scaling Group ID
    Value: !Ref AutoScalingGroup
TEMPLATE
}

resource "aws_cloudformation_stack" "eks_nodes" {
  name = "eks-cluster-stack"
  template_body = local.cf_template
  parameters = {}
  capabilities = ["CAPABILITY_IAM"]

  depends_on = [
    time_sleep.launch_template,
    aws_security_group.node,
    aws_iam_instance_profile.node,
    aws_flow_log.main
  ]
}

# Outputs
output "node_instance_role_arn" {
  value = aws_iam_role.node.arn
}

output "node_security_group_id" {
  value = aws_security_group.node.id
}

output "auto_scaling_group_id" {
  value = aws_cloudformation_stack.eks_nodes.outputs["AutoScalingGroupID"]
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.0"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 2.0"
    }
  }
}

# Import existing resources into Terraform state
import {
  to = aws_kms_alias.primary
  id = "alias/tf-state-primary"
}

import {
  to = aws_kms_alias.replica
  id = "alias/tf-state-replica"
}

import {
  to = aws_s3_bucket.primary
  id = local.primary_bucket_name
}

import {
  to = aws_s3_bucket.replica
  id = local.replica_bucket_name
}

import {
  to = aws_s3_bucket.access_logs
  id = local.access_logs_bucket_name
}

import {
  to = aws_iam_role.s3_replication
  id = "s3-cross-region-replication-role"
}

import {
  to = aws_s3_bucket.access_logs_replica
  id = "${local.access_logs_bucket_name}-replica"
}

import {
  to = aws_iam_policy.s3_replication
  id = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:policy/s3-cross-region-replication-policy"
}

# Data source for AWS account ID
data "aws_caller_identity" "current" {}

# Local values
locals {
  common_tags = {
    Terraform   = "true"
    Environment = "state-management"
    Purpose     = "eks-state-locking"
  }
  primary_bucket_name     = "tf-state-${data.aws_caller_identity.current.account_id}-primary"
  replica_bucket_name     = "tf-state-${data.aws_caller_identity.current.account_id}-replica"
  access_logs_bucket_name = "tf-state-${data.aws_caller_identity.current.account_id}-access-logs"
}

# Variables
variable "replica_region" {
  description = "AWS region for the replica S3 bucket"
  type        = string
  default     = "us-west-2"
}

variable "eks_stacks" {
  description = "Map of EKS stack names to their target regions"
  type        = map(string)
  default     = {}
}

# Provider for replica region
provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

# Primary KMS Key
resource "aws_kms_key" "primary" {
  description             = "KMS key for primary state bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 service to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_kms_alias" "primary" {
  name          = "alias/tf-state-primary"
  target_key_id = aws_kms_key.primary.key_id
}

# Replica KMS Key
resource "aws_kms_key" "replica" {
  provider                = aws.replica
  description             = "KMS key for replica state bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 service to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_kms_alias" "replica" {
  provider      = aws.replica
  name          = "alias/tf-state-replica"
  target_key_id = aws_kms_key.replica.key_id
}

# Primary S3 Bucket
resource "aws_s3_bucket" "primary" {
  bucket = local.primary_bucket_name
  tags   = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "primary_bucket_policy" {
  statement {
    sid    = "DenyNonSSL"
    effect = "Deny"
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.primary.arn,
      "${aws_s3_bucket.primary.arn}/*"
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "primary" {
  bucket = aws_s3_bucket.primary.id
  policy = data.aws_iam_policy_document.primary_bucket_policy.json
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.primary.arn
    }
  }
}

# Replica S3 Bucket
resource "aws_s3_bucket" "replica" {
  provider = aws.replica
  bucket   = local.replica_bucket_name
  tags     = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "replica_bucket_policy" {
  provider = aws.replica
  statement {
    sid    = "DenyNonSSL"
    effect = "Deny"
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.replica.arn,
      "${aws_s3_bucket.replica.arn}/*"
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  policy   = data.aws_iam_policy_document.replica_bucket_policy.json
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replica.arn
    }
  }
}

# Access Logs S3 Bucket (primary region)
resource "aws_s3_bucket" "access_logs" {
  bucket = local.access_logs_bucket_name
  tags   = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "access_logs_bucket_policy" {
  statement {
    sid    = "AllowLogDelivery"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.access_logs.arn}/*"]
  }
}

resource "aws_s3_bucket_policy" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id
  policy = data.aws_iam_policy_document.access_logs_bucket_policy.json
}

resource "aws_s3_bucket_server_side_encryption_configuration" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# Access Logs S3 Bucket (replica region)
resource "aws_s3_bucket" "access_logs_replica" {
  provider = aws.replica
  bucket   = "${local.access_logs_bucket_name}-replica"
  tags     = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "access_logs_replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.access_logs_replica.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "access_logs_replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.access_logs_replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "access_logs_replica_bucket_policy" {
  provider = aws.replica
  statement {
    sid    = "AllowLogDelivery"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.access_logs_replica.arn}/*"]
  }
}

resource "aws_s3_bucket_policy" "access_logs_replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.access_logs_replica.id
  policy   = data.aws_iam_policy_document.access_logs_replica_bucket_policy.json
}

resource "aws_s3_bucket_server_side_encryption_configuration" "access_logs_replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.access_logs_replica.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# S3 Bucket Logging (primary)
resource "aws_s3_bucket_logging" "primary" {
  bucket        = aws_s3_bucket.primary.id
  target_bucket = aws_s3_bucket.access_logs.id
  target_prefix = "logs/primary/"
}

# S3 Bucket Logging (replica)
resource "aws_s3_bucket_logging" "replica" {
  provider      = aws.replica
  bucket        = aws_s3_bucket.replica.id
  target_bucket = aws_s3_bucket.access_logs_replica.id
  target_prefix = "logs/replica/"
}

# IAM Role for S3 Replication
resource "aws_iam_role" "s3_replication" {
  name = "s3-cross-region-replication-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.common_tags
}

data "aws_iam_policy_document" "s3_replication" {
  statement {
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.primary.arn,
      "${aws_s3_bucket.primary.arn}/*"
    ]
  }
  statement {
    effect = "Allow"
    actions = [
      "kms:Decrypt"
    ]
    resources = [aws_kms_key.primary.arn]
  }
  statement {
    effect = "Allow"
    actions = [
      "kms:Encrypt"
    ]
    resources = [aws_kms_key.replica.arn]
  }
}

resource "aws_iam_policy" "s3_replication" {
  name   = "s3-cross-region-replication-policy"
  policy = data.aws_iam_policy_document.s3_replication.json
  tags   = local.common_tags
}

resource "aws_iam_role_policy_attachment" "s3_replication" {
  role       = aws_iam_role.s3_replication.name
  policy_arn = aws_iam_policy.s3_replication.arn
}

# S3 Replication Configuration
resource "aws_s3_bucket_replication_configuration" "primary" {
  depends_on = [aws_s3_bucket_versioning.primary]
  bucket     = aws_s3_bucket.primary.id
  role       = aws_iam_role.s3_replication.arn

  rule {
    id     = "CrossRegionReplication"
    status = "Enabled"
    filter {
      prefix = ""
    }
    destination {
      bucket        = aws_s3_bucket.replica.arn
      storage_class = "STANDARD"
      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica.arn
      }
    }
    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
    delete_marker_replication {
      status = "Disabled"
    }
  }
}

# DynamoDB Tables and Stack-specific IAM Policies
resource "aws_dynamodb_table" "state_lock" {
  for_each = var.eks_stacks
  name     = "tf-lock-${each.key}"
  hash_key = "LockID"
  attribute {
    name = "LockID"
    type = "S"
  }
  billing_mode     = "PAY_PER_REQUEST"
  server_side_encryption {
    enabled = true
  }
  tags = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_policy" "stack_access" {
  for_each = var.eks_stacks
  name     = "tf-state-access-${each.key}"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem",
          "dynamodb:DescribeTable"
        ]
        Resource = aws_dynamodb_table.state_lock[each.key].arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/env:/${each.key}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.primary.arn
      }
    ]
  })
  tags = local.common_tags
}

# Create directories for backend files
resource "null_resource" "create_backend_dirs" {
  for_each = var.eks_stacks
  provisioner "local-exec" {
    command = "mkdir -p ./eks-stacks/${each.key}"
  }
  triggers = {
    always_run = timestamp()
  }
}

# Local backend files
resource "local_file" "backend" {
  for_each = var.eks_stacks
  depends_on = [null_resource.create_backend_dirs]
  filename   = "./eks-stacks/${each.key}/backend.tf"
  content    = <<-EOT
terraform {
  backend "s3" {
    bucket         = "${local.primary_bucket_name}"
    key            = "env:/${each.key}/terraform.tfstate"
    region         = "us-east-1"
    encrypt        = true
    kms_key_id     = "${aws_kms_key.primary.arn}"
    dynamodb_table = "${aws_dynamodb_table.state_lock[each.key].name}"
  }
}
EOT
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

resource "aws_cognito_user_pool" "box_things" {
  name                     = "box_things"
  alias_attributes         = ["email"]
  auto_verified_attributes = ["email"]
  mfa_configuration        = "OFF"

  password_policy {
    minimum_length    = 8
    require_lowercase = true
    require_uppercase = true
    require_numbers   = true
    require_symbols   = true
  }

  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  verification_message_template {
    default_email_option = "CONFIRM_WITH_LINK"
    email_subject_by_link = "Confirm your email for box_things"
    email_message_by_link = "Please click the link below to verify your email address: {##Click Here##}"
    email_subject         = "Your verification code for box_things"
    email_message         = "Your verification code is {####}. Username: {username}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cognito_user_pool_client" "box_things_client" {
  name         = "box_things_client"
  user_pool_id = aws_cognito_user_pool.box_things.id

  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH",
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]

  access_token_validity = 60
  id_token_validity     = 60

  token_validity_units {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }

  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["openid", "email", "profile"]
  callback_urls                        = ["https://example.com/callback"]
  logout_urls                          = ["https://example.com/logout"]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "users" {
  type = map(object({
    owner = string
  }))
  default = {
    dev1  = { owner = "Devel" }
    dev2  = { owner = "Devel" }
    guest = { owner = "Guest" }
  }
}

resource "aws_iam_group" "devel" {
  name = "Ersia_Devel_Group"
}

resource "aws_iam_group" "guest" {
  name = "Ersia_Guest_Group"
}

resource "aws_iam_group_policy_attachment" "devel_read_only" {
  group      = aws_iam_group.devel.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "guest_iam_read_only" {
  group      = aws_iam_group.guest.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_group_policy" "mfa_devel" {
  name   = "MFAEnforcement"
  group  = aws_iam_group.devel.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyAllWithoutMFA"
        Effect    = "Deny"
        Action    = "*"
        Resource  = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy" "mfa_guest" {
  name   = "MFAEnforcement"
  group  = aws_iam_group.guest.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyAllWithoutMFA"
        Effect    = "Deny"
        Action    = "*"
        Resource  = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_iam_user" "user" {
  for_each = var.users
  name     = each.key
  tags = {
    Owner = each.value.owner
  }
}

resource "aws_iam_user_group_membership" "membership" {
  for_each = var.users
  user     = each.key
  groups   = [each.value.owner == "Devel" ? aws_iam_group.devel.name : aws_iam_group.guest.name]
}

terraform {
  required_version = "~> 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

resource "random_pet" "name" {
  length = 2
}

# KMS key for SQS encryption
resource "aws_kms_key" "sqs_encryption" {
  description             = "KMS key for SQS queue encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

resource "aws_kms_alias" "sqs_encryption" {
  name          = "alias/${random_pet.name.id}-sqs-key"
  target_key_id = aws_kms_key.sqs_encryption.key_id
}

# Dedicated KMS key for CloudWatch Logs encryption with proper key policy
resource "aws_kms_key" "cloudwatch_logs" {
  description             = "KMS key for CloudWatch Logs encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
          "kms:CreateGrant"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "cloudwatch_logs" {
  name          = "alias/${random_pet.name.id}-logs-key"
  target_key_id = aws_kms_key.cloudwatch_logs.key_id
}

# SQS queue
resource "aws_sqs_queue" "main" {
  name                      = "${random_pet.name.id}-queue"
  kms_master_key_id         = aws_kms_key.sqs_encryption.arn
  kms_data_key_reuse_period_seconds = 300

  lifecycle {
    prevent_destroy = true
  }
}

# IAM role for API Gateway
resource "aws_iam_role" "api_gateway_execution" {
  name = "${random_pet.name.id}-api-gw-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# IAM policy for API Gateway execution role
resource "aws_iam_role_policy" "api_gateway_execution" {
  name = "${random_pet.name.id}-api-gw-execution-policy"
  role = aws_iam_role.api_gateway_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sqs:SendMessage"
        Resource = aws_sqs_queue.main.arn
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.api_gateway.arn}:*"
      }
    ]
  })
}

# CloudWatch log group for API Gateway access logs (encrypted with CMK)
resource "aws_cloudwatch_log_group" "api_gateway" {
  name              = "/aws/apigateway/${random_pet.name.id}-ws-api"
  retention_in_days = 1
  kms_key_id        = aws_kms_key.cloudwatch_logs.arn
}

# WebSocket API with valid route selection expression
resource "aws_apigatewayv2_api" "ws" {
  name                       = random_pet.name.id
  protocol_type              = "WEBSOCKET"
  route_selection_expression = "$request.body.action"
}

# --- $connect route (mock integration) ---
resource "aws_apigatewayv2_integration" "connect_mock" {
  api_id           = aws_apigatewayv2_api.ws.id
  integration_type = "MOCK"
  integration_uri  = null
}

resource "aws_apigatewayv2_integration_response" "connect" {
  api_id                   = aws_apigatewayv2_api.ws.id
  integration_id           = aws_apigatewayv2_integration.connect_mock.id
  integration_response_key = "/200/"
  response_templates = {
    "application/json" = jsonencode({ statusCode = 200 })
  }
}

resource "aws_apigatewayv2_route" "connect" {
  api_id    = aws_apigatewayv2_api.ws.id
  route_key = "$connect"
  target    = "integrations/${aws_apigatewayv2_integration.connect_mock.id}"
}

resource "aws_apigatewayv2_route_response" "connect" {
  api_id             = aws_apigatewayv2_api.ws.id
  route_id           = aws_apigatewayv2_route.connect.id
  route_response_key = "$default"
}

# --- $default route (SQS SendMessage) ---
resource "aws_apigatewayv2_integration" "default_sqs" {
  api_id           = aws_apigatewayv2_api.ws.id
  integration_type = "AWS"
  integration_uri  = "arn:aws:apigateway:${data.aws_region.current.name}:sqs:path/${data.aws_caller_identity.current.account_id}/${aws_sqs_queue.main.name}"
  integration_method = "POST"
  credentials_arn  = aws_iam_role.api_gateway_execution.arn

  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }

  request_templates = {
    "application/json" = "Action=SendMessage&MessageBody=$input.body"
  }

  passthrough_behavior = "WHEN_NO_MATCH"
}

resource "aws_apigatewayv2_integration_response" "default" {
  api_id                   = aws_apigatewayv2_api.ws.id
  integration_id           = aws_apigatewayv2_integration.default_sqs.id
  integration_response_key = "/200/"
  response_templates = {
    "application/json" = ""
  }
}

resource "aws_apigatewayv2_route" "default" {
  api_id    = aws_apigatewayv2_api.ws.id
  route_key = "$default"
  target    = "integrations/${aws_apigatewayv2_integration.default_sqs.id}"
}

resource "aws_apigatewayv2_route_response" "default" {
  api_id             = aws_apigatewayv2_api.ws.id
  route_id           = aws_apigatewayv2_route.default.id
  route_response_key = "$default"
}

# --- $disconnect route (SQS SendMessage with fixed message) ---
resource "aws_apigatewayv2_integration" "disconnect_sqs" {
  api_id           = aws_apigatewayv2_api.ws.id
  integration_type = "AWS"
  integration_uri  = "arn:aws:apigateway:${data.aws_region.current.name}:sqs:path/${data.aws_caller_identity.current.account_id}/${aws_sqs_queue.main.name}"
  integration_method = "POST"
  credentials_arn  = aws_iam_role.api_gateway_execution.arn

  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }

  request_templates = {
    "application/json" = "Action=SendMessage&MessageBody=Client disconnected"
  }

  passthrough_behavior = "WHEN_NO_MATCH"
}

resource "aws_apigatewayv2_integration_response" "disconnect" {
  api_id                   = aws_apigatewayv2_api.ws.id
  integration_id           = aws_apigatewayv2_integration.disconnect_sqs.id
  integration_response_key = "/200/"
  response_templates = {
    "application/json" = ""
  }
}

resource "aws_apigatewayv2_route" "disconnect" {
  api_id    = aws_apigatewayv2_api.ws.id
  route_key = "$disconnect"
  target    = "integrations/${aws_apigatewayv2_integration.disconnect_sqs.id}"
}

resource "aws_apigatewayv2_route_response" "disconnect" {
  api_id             = aws_apigatewayv2_api.ws.id
  route_id           = aws_apigatewayv2_route.disconnect.id
  route_response_key = "$default"
}

# Stage with auto-deploy and access logging
resource "aws_apigatewayv2_stage" "dev" {
  api_id      = aws_apigatewayv2_api.ws.id
  name        = "dev"
  auto_deploy = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_gateway.arn
    format = jsonencode({
      requestId               = "$context.requestId"
      ip                      = "$context.identity.sourceIp"
      caller                  = "$context.identity.caller"
      user                    = "$context.identity.user"
      requestTime             = "$context.requestTime"
      httpMethod              = "$context.httpMethod"
      resourcePath            = "$context.resourcePath"
      status                  = "$context.status"
      protocol                = "$context.protocol"
      responseLength          = "$context.responseLength"
      integrationErrorMessage = "$context.integrationErrorMessage"
    })
  }
}

output "websocket_endpoint_url" {
  value = aws_apigatewayv2_stage.dev.invoke_url
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

variable "vpc_config" {
  type = map(any)
  default = {
    vpc1 = {
      cidr_block           = "10.0.0.0/16"
      enable_dns_support   = true
      enable_dns_hostnames = false
      tags = {
        Name = "XXXX-vpc-test"
      }
      instance_tenancy = "default"
    }
    vpc2 = {
      cidr_block           = "172.31.0.0/16"
      enable_dns_support   = true
      enable_dns_hostnames = true
      tags = {
        Name = "Default"
      }
      instance_tenancy = "default"
    }
    vpc3 = {
      cidr_block           = "192.168.0.0/16"
      enable_dns_support   = true
      enable_dns_hostnames = true
      tags = {
        Name                  = "eksctl-eks-cluster-px-cluster/VPC"
        "eksctl:cluster-name" = "eks-cluster-px"
        "eksctl:version"      = "0.94.0"
      }
      instance_tenancy = "default"
    }
    vpc4 = {
      cidr_block           = "10.0.0.0/24"
      enable_dns_support   = true
      enable_dns_hostnames = false
      tags                 = {}
      instance_tenancy     = "default"
    }
    vpc5 = {
      cidr_block           = "10.0.0.0/16"
      enable_dns_support   = true
      enable_dns_hostnames = false
      tags = {
        Name = ""
      }
      instance_tenancy = "default"
    }
  }
}

resource "aws_vpc" "this" {
  for_each = var.vpc_config

  cidr_block           = each.value.cidr_block
  enable_dns_support   = each.value.enable_dns_support
  enable_dns_hostnames = each.value.enable_dns_hostnames
  tags                 = each.value.tags
  instance_tenancy     = each.value.instance_tenancy

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cloudwatch_log_group" "flow_log" {
  for_each = var.vpc_config

  name_prefix       = "vpc-flow-logs-"
  retention_in_days = 0
  kms_key_id        = aws_kms_alias.flow_log.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "vpc_flow_logs" {
  name_prefix = "vpc-flow-logs-"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy" "vpc_flow_logs" {
  name = "vpc-flow-logs-policy"
  role = aws_iam_role.vpc_flow_logs.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "flow_log" {
  description             = "KMS key for VPC flow log encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid = "RootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = ["kms:*"]
        Resource = "*"
      },
      {
        Sid = "CloudWatchLogsAccess"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "flow_log" {
  name_prefix   = "alias/vpc-flow-logs-"
  target_key_id = aws_kms_key.flow_log.id

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_flow_log" "this" {
  for_each = var.vpc_config

  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.flow_log[each.key].arn
  iam_role_arn         = aws_iam_role.vpc_flow_logs.arn
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.this[each.key].id

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "tags" {
  description = "Tags to apply to all resources, merged with provider default tags"
  type        = map(string)
  default     = {}
}

data "aws_iam_policy_document" "ecs_policy" {
  statement {
    actions   = ["ecs:RunTask"]
    resources = ["*"]
  }

  statement {
    actions   = ["iam:PassRole"]
    resources = [aws_iam_role.ecs_tasks_role.arn]
    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = ["ecs-tasks.amazonaws.com"]
    }
  }

  statement {
    effect       = "Deny"
    actions      = ["iam:PassRole"]
    not_resources = [aws_iam_role.ecs_tasks_role.arn]
  }
}

resource "aws_iam_policy" "ecs_policy" {
  name        = "ecs-policy"
  description = "Policy allowing ECS RunTask and PassRole for the task execution role"
  policy      = data.aws_iam_policy_document.ecs_policy.json
  tags        = var.tags
}

resource "aws_iam_role" "ecs_role" {
  name                 = "ecs-role"
  path                 = "/"
  force_detach_policies = true
  assume_role_policy   = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action    = "sts:AssumeRole"
      Effect    = "Allow"
      Principal = {
        Service = "ecs.amazonaws.com"
      }
    }]
  })
  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "ecs_role_policy" {
  role       = aws_iam_role.ecs_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"
}

resource "aws_iam_role" "ecs_tasks_role" {
  name                 = "ecs-tasks-role"
  path                 = "/"
  force_detach_policies = true
  assume_role_policy   = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action    = "sts:AssumeRole"
      Effect    = "Allow"
      Principal = {
        Service = "ecs-tasks.amazonaws.com"
      }
    }]
  })
  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "ecs_tasks_role_policy" {
  role       = aws_iam_role.ecs_tasks_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role" "events_role" {
  name                 = "events-role"
  path                 = "/"
  force_detach_policies = true
  assume_role_policy   = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action    = "sts:AssumeRole"
      Effect    = "Allow"
      Principal = {
        Service = "events.amazonaws.com"
      }
    }]
  })
  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "events_role_ecs_policy" {
  role       = aws_iam_role.events_role.name
  policy_arn = aws_iam_policy.ecs_policy.arn
}

resource "aws_iam_role_policy_attachment" "events_role_logs_policy" {
  role       = aws_iam_role.events_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchLogsFullAccess"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Provider for secondary region – the default provider (us-east-1) is injected
provider "aws" {
  alias  = "secondary"
  region = var.secondary_region
}

variable "bucket1_name" {
  description = "Name for the primary S3 bucket (without account suffix)"
  type        = string
  default     = "example1"
}

variable "bucket2_name" {
  description = "Name for the secondary S3 bucket (without account suffix)"
  type        = string
  default     = "example2"
}

variable "mrap_name" {
  description = "Name for the Multi-Region Access Point"
  type        = string
  default     = "example-mrap"
}

variable "secondary_region" {
  description = "Region for the secondary bucket and MRAP control plane"
  type        = string
  default     = "us-west-2"
}

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  bucket1    = "${var.bucket1_name}-${local.account_id}"
  bucket2    = "${var.bucket2_name}-${local.account_id}"
}

resource "random_id" "mrap_suffix" {
  byte_length = 4
}

# ---------------------------------------------------------------------------
# KMS Keys (one per region)
# ---------------------------------------------------------------------------
resource "aws_kms_key" "primary" {
  description             = "KMS key for primary S3 bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 service to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:Encrypt"
        ]
        Resource = "*"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "secondary" {
  provider = aws.secondary
  description             = "KMS key for secondary S3 bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 service to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:Encrypt"
        ]
        Resource = "*"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Primary S3 Bucket (us-east-1)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "primary" {
  bucket = local.bucket1
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  bucket = aws_s3_bucket.primary.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# Logging bucket for primary
resource "aws_s3_bucket" "log_primary" {
  bucket = "${var.bucket1_name}-logs-${local.account_id}"
}

resource "aws_s3_bucket_ownership_controls" "log_primary" {
  bucket = aws_s3_bucket.log_primary.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "log_primary_acl" {
  bucket     = aws_s3_bucket.log_primary.id
  acl        = "log-delivery-write"
  depends_on = [aws_s3_bucket_ownership_controls.log_primary]
}

resource "aws_s3_bucket_public_access_block" "log_primary" {
  bucket = aws_s3_bucket.log_primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "log_primary" {
  bucket = aws_s3_bucket.log_primary.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "primary" {
  bucket        = aws_s3_bucket.primary.id
  target_bucket = aws_s3_bucket.log_primary.id
  target_prefix = "log/"
}

# ---------------------------------------------------------------------------
# Secondary S3 Bucket (secondary region)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "secondary" {
  provider = aws.secondary
  bucket   = local.bucket2
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.secondary.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# Logging bucket for secondary
resource "aws_s3_bucket" "log_secondary" {
  provider = aws.secondary
  bucket   = "${var.bucket2_name}-logs-${local.account_id}"
}

resource "aws_s3_bucket_ownership_controls" "log_secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.log_secondary.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "log_secondary_acl" {
  provider   = aws.secondary
  bucket     = aws_s3_bucket.log_secondary.id
  acl        = "log-delivery-write"
  depends_on = [aws_s3_bucket_ownership_controls.log_secondary]
}

resource "aws_s3_bucket_public_access_block" "log_secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.log_secondary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "log_secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.log_secondary.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "secondary" {
  provider      = aws.secondary
  bucket        = aws_s3_bucket.secondary.id
  target_bucket = aws_s3_bucket.log_secondary.id
  target_prefix = "log/"
}

# ---------------------------------------------------------------------------
# IAM Role for Replication
# ---------------------------------------------------------------------------
resource "aws_iam_role" "replication" {
  name_prefix = "s3-replication-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "replication" {
  name_prefix = "s3-replication-policy-"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersion",
          "s3:GetObjectVersionForReplication",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = [
          aws_s3_bucket.secondary.arn,
          "${aws_s3_bucket.secondary.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = "kms:Decrypt"
        Resource = aws_kms_key.primary.arn
      },
      {
        Effect = "Allow"
        Action = "kms:Encrypt"
        Resource = aws_kms_key.secondary.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

# ---------------------------------------------------------------------------
# Replication Configuration on Primary Bucket
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_replication_configuration" "primary" {
  depends_on = [aws_s3_bucket_versioning.primary, aws_s3_bucket_versioning.secondary]
  bucket     = aws_s3_bucket.primary.id
  role       = aws_iam_role.replication.arn

  rule {
    id     = "replication-rule"
    status = "Enabled"

    delete_marker_replication {
      status = "Disabled"
    }

    filter {}

    destination {
      bucket        = aws_s3_bucket.secondary.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }
}

# ---------------------------------------------------------------------------
# Multi-Region Access Point (managed from secondary region)
# ---------------------------------------------------------------------------
resource "aws_s3control_multi_region_access_point" "mrap" {
  provider = aws.secondary

  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.secondary,
    aws_s3_bucket_server_side_encryption_configuration.primary,
    aws_s3_bucket_server_side_encryption_configuration.secondary
  ]

  timeouts {
    create = "30m"
  }

  details {
    name = "${var.mrap_name}-${random_id.mrap_suffix.hex}"

    region {
      bucket = aws_s3_bucket.primary.id
    }

    region {
      bucket = aws_s3_bucket.secondary.id
    }
  }
}

resource "aws_s3control_multi_region_access_point_policy" "mrap" {
  provider   = aws.secondary
  depends_on = [aws_s3control_multi_region_access_point.mrap]

  details {
    name   = aws_s3control_multi_region_access_point.mrap.details[0].name
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect = "Allow"
          Principal = {
            AWS = "arn:aws:iam::${local.account_id}:root"
          }
          Action = [
            "s3:GetObject",
            "s3:PutObject"
          ]
          Resource = "arn:aws:s3::${local.account_id}:accesspoint/${aws_s3control_multi_region_access_point.mrap.details[0].name}"
        }
      ]
    })
  }
}

# ---------------------------------------------------------------------------
# Import existing resources into state
# ---------------------------------------------------------------------------
import {
  to = aws_s3_bucket.primary
  id = local.bucket1
}

import {
  to = aws_s3_bucket.log_primary
  id = "${var.bucket1_name}-logs-${local.account_id}"
}

import {
  to = aws_s3_bucket.secondary
  id = local.bucket2
}

import {
  to = aws_s3_bucket.log_secondary
  id = "${var.bucket2_name}-logs-${local.account_id}"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "namespace" {
  description = "Namespace (e.g., org or account name)"
  type        = string
  default     = "acme"
}

variable "stage" {
  description = "Stage (e.g., prod, dev)"
  type        = string
  default     = "prod"
}

variable "name" {
  description = "Application name or solution name"
  type        = string
  default     = "patch"
}

variable "attributes" {
  description = "Additional attributes (e.g., [\"logs\"])"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags (e.g., map('Environment','prod'))"
  type        = map(string)
  default     = {}
}

variable "enable_sns_notifications" {
  description = "Enable SNS notifications for patch tasks"
  type        = bool
  default     = false
}

variable "enable_cloudwatch_logs" {
  description = "Enable CloudWatch Logs output for patch tasks"
  type        = bool
  default     = false
}

variable "scan_window_schedule" {
  description = "Cron expression for the scan maintenance window"
  type        = string
  default     = "cron(0 0 18 ? * WED *)"
}

variable "install_window_schedule" {
  description = "Cron expression for the install maintenance window"
  type        = string
  default     = "cron(0 0 21 ? * WED *)"
}

variable "scan_window_duration" {
  description = "Duration of scan window in hours"
  type        = number
  default     = 3
}

variable "install_window_duration" {
  description = "Duration of install window in hours"
  type        = number
  default     = 3
}

variable "scan_window_cutoff" {
  description = "Cutoff time in hours for scan window"
  type        = number
  default     = 1
}

variable "install_window_cutoff" {
  description = "Cutoff time in hours for install window"
  type        = number
  default     = 1
}

variable "patch_group_scan_key" {
  description = "Tag key for scan patch group"
  type        = string
  default     = "Patch Group"
}

variable "patch_group_scan_value" {
  description = "Tag value for scan patch group"
  type        = string
  default     = "TOSCAN"
}

variable "patch_group_install_key" {
  description = "Tag key for install patch group"
  type        = string
  default     = "Patch Group"
}

variable "patch_group_install_value" {
  description = "Tag value for install patch group"
  type        = string
  default     = "TOPATCH"
}

variable "max_concurrency" {
  description = "Maximum number of instances that can run the task concurrently"
  type        = string
  default     = "20"
}

variable "max_errors" {
  description = "Maximum number of errors allowed before the task stops"
  type        = string
  default     = "50"
}

variable "install_reboot_option" {
  description = "Reboot option for install tasks"
  type        = string
  default     = "RebootIfNeeded"
}

variable "log_bucket_prefix" {
  description = "Prefix for log output in S3 bucket"
  type        = string
  default     = "scanning"
}

# ------------------------------------------------------------------------------
# Data Sources
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# Cloud Posse null-label module
# ------------------------------------------------------------------------------
module "this" {
  source     = "cloudposse/label/null"
  version    = "~> 0.25"
  namespace  = var.namespace
  stage      = var.stage
  name       = var.name
  attributes = var.attributes
  tags       = var.tags
}

locals {
  prefix      = module.this.id
  common_tags = module.this.tags
}

# ------------------------------------------------------------------------------
# KMS Customer Managed Key for S3 encryption
# ------------------------------------------------------------------------------
resource "aws_kms_key" "this" {
  description             = "CMK for S3 log bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = local.common_tags
}

resource "aws_kms_alias" "this" {
  name_prefix   = "alias/${local.prefix}-s3-logs-"
  target_key_id = aws_kms_key.this.key_id
}

# ------------------------------------------------------------------------------
# IAM Role for Maintenance Windows
# ------------------------------------------------------------------------------
resource "aws_iam_role" "maintenance_window" {
  name_prefix          = "${local.prefix}-mw-role-"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ssm.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "maintenance_window" {
  role       = aws_iam_role.maintenance_window.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonSSMMaintenanceWindowRole"
}

# ------------------------------------------------------------------------------
# S3 Log Bucket (primary)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "log" {
  bucket_prefix = "${local.prefix}-patch-logs-"
  tags          = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "log" {
  bucket = aws_s3_bucket.log.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log" {
  bucket = aws_s3_bucket.log.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "log" {
  bucket                  = aws_s3_bucket.log.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "log" {
  bucket = aws_s3_bucket.log.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowAccountReadWrite"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.log.arn,
          "${aws_s3_bucket.log.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_s3_bucket_lifecycle_configuration" "log" {
  bucket = aws_s3_bucket.log.id
  rule {
    id     = "prevent-destroy"
    status = "Enabled"
    expiration {
      days = 3650
    }
    filter {}
  }
}

# ------------------------------------------------------------------------------
# S3 Access Log Bucket (for server access logging)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "access_log" {
  bucket_prefix = "${local.prefix}-access-logs-"
  tags          = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "access_log" {
  bucket = aws_s3_bucket.access_log.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "access_log" {
  bucket = aws_s3_bucket.access_log.id
  acl    = "log-delivery-write"

  depends_on = [aws_s3_bucket_ownership_controls.access_log]
}

resource "aws_s3_bucket_versioning" "access_log" {
  bucket = aws_s3_bucket.access_log.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "access_log" {
  bucket = aws_s3_bucket.access_log.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "access_log" {
  bucket                  = aws_s3_bucket.access_log.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# S3 Bucket Logging (separate resource, replaces deprecated inline logging)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_logging" "log" {
  bucket        = aws_s3_bucket.log.id
  target_bucket = aws_s3_bucket.access_log.id
  target_prefix = "access-logs/"
}

# ------------------------------------------------------------------------------
# Optional SNS Topic
# ------------------------------------------------------------------------------
resource "aws_sns_topic" "patch" {
  count = var.enable_sns_notifications ? 1 : 0
  name  = "${local.prefix}-patch-notifications"
  tags  = local.common_tags
}

# ------------------------------------------------------------------------------
# Optional CloudWatch Log Group
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "patch" {
  count = var.enable_cloudwatch_logs ? 1 : 0
  name  = "/aws/ssm/patch/${local.prefix}"
  tags  = local.common_tags
}

# ------------------------------------------------------------------------------
# Patch Baseline for Amazon Linux 2
# ------------------------------------------------------------------------------
resource "aws_ssm_patch_baseline" "amazon_linux_2" {
  name             = "${local.prefix}-amazon-linux-2"
  description      = "Patch baseline for Amazon Linux 2 with HIGH compliance"
  operating_system = "AMAZON_LINUX_2"
  approved_patches_compliance_level = "HIGH"

  approval_rule {
    approve_after_days = 7
    patch_filter {
      key   = "CLASSIFICATION"
      values = ["Security", "Bugfix", "Recommended"]
    }
    patch_filter {
      key   = "SEVERITY"
      values = ["Critical", "Important", "Medium"]
    }
  }

  tags = local.common_tags
}

# ------------------------------------------------------------------------------
# Maintenance Windows
# ------------------------------------------------------------------------------
resource "aws_ssm_maintenance_window" "scan" {
  name                        = "${local.prefix}-scan"
  schedule                    = var.scan_window_schedule
  duration                    = var.scan_window_duration
  cutoff                      = var.scan_window_cutoff
  allow_unassociated_targets  = false
  tags                        = local.common_tags
}

resource "aws_ssm_maintenance_window" "install" {
  name                        = "${local.prefix}-install"
  schedule                    = var.install_window_schedule
  duration                    = var.install_window_duration
  cutoff                      = var.install_window_cutoff
  allow_unassociated_targets  = false
  tags                        = local.common_tags
}

# ------------------------------------------------------------------------------
# Maintenance Window Targets
# ------------------------------------------------------------------------------
resource "aws_ssm_maintenance_window_target" "scan" {
  window_id     = aws_ssm_maintenance_window.scan.id
  name          = "${local.prefix}-scan-target"
  resource_type = "INSTANCE"
  targets {
    key    = "tag:${var.patch_group_scan_key}"
    values = [var.patch_group_scan_value]
  }
}

resource "aws_ssm_maintenance_window_target" "install" {
  window_id     = aws_ssm_maintenance_window.install.id
  name          = "${local.prefix}-install-target"
  resource_type = "INSTANCE"
  targets {
    key    = "tag:${var.patch_group_install_key}"
    values = [var.patch_group_install_value]
  }
}

# ------------------------------------------------------------------------------
# Maintenance Window Tasks
# ------------------------------------------------------------------------------
resource "aws_ssm_maintenance_window_task" "scan" {
  window_id        = aws_ssm_maintenance_window.scan.id
  task_type        = "RUN_COMMAND"
  task_arn         = "AWS-RunPatchBaseline"
  service_role_arn = aws_iam_role.maintenance_window.arn
  max_concurrency  = var.max_concurrency
  max_errors       = var.max_errors
  name             = "${local.prefix}-scan-task"

  targets {
    key    = "WindowTargetIds"
    values = [aws_ssm_maintenance_window_target.scan.id]
  }

  task_invocation_parameters {
    run_command_parameters {
      comment = "Patch scan task"

      dynamic "notification_config" {
        for_each = var.enable_sns_notifications ? [1] : []
        content {
          notification_arn = aws_sns_topic.patch[0].arn
          notification_events = ["All"]
          notification_type   = "Command"
        }
      }

      dynamic "cloudwatch_config" {
        for_each = var.enable_cloudwatch_logs ? [1] : []
        content {
          cloudwatch_output_enabled = true
          cloudwatch_log_group_name = aws_cloudwatch_log_group.patch[0].name
        }
      }

      output_s3_bucket     = aws_s3_bucket.log.id
      output_s3_key_prefix = var.log_bucket_prefix

      parameter {
        name   = "Operation"
        values = ["Scan"]
      }

      parameter {
        name   = "RebootOption"
        values = ["NoReboot"]
      }
    }
  }
}

resource "aws_ssm_maintenance_window_task" "install" {
  window_id        = aws_ssm_maintenance_window.install.id
  task_type        = "RUN_COMMAND"
  task_arn         = "AWS-RunPatchBaseline"
  service_role_arn = aws_iam_role.maintenance_window.arn
  max_concurrency  = var.max_concurrency
  max_errors       = var.max_errors
  name             = "${local.prefix}-install-task"

  targets {
    key    = "WindowTargetIds"
    values = [aws_ssm_maintenance_window_target.install.id]
  }

  task_invocation_parameters {
    run_command_parameters {
      comment = "Patch install task"

      dynamic "notification_config" {
        for_each = var.enable_sns_notifications ? [1] : []
        content {
          notification_arn = aws_sns_topic.patch[0].arn
          notification_events = ["All"]
          notification_type   = "Command"
        }
      }

      dynamic "cloudwatch_config" {
        for_each = var.enable_cloudwatch_logs ? [1] : []
        content {
          cloudwatch_output_enabled = true
          cloudwatch_log_group_name = aws_cloudwatch_log_group.patch[0].name
        }
      }

      output_s3_bucket     = aws_s3_bucket.log.id
      output_s3_key_prefix = var.log_bucket_prefix

      parameter {
        name   = "Operation"
        values = ["Install"]
      }

      parameter {
        name   = "RebootOption"
        values = [var.install_reboot_option]
      }
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

locals {
  account_id      = data.aws_caller_identity.current.account_id
  trail_name      = "monitor_account_activities"
  trail_arn       = "arn:aws:cloudtrail:us-east-1:${local.account_id}:trail/${local.trail_name}"
  log_group_name  = "cloudtrail_to_cloudwatch_logs"
  bucket_name     = "cloudtrail-monitor-management-event-logs-${local.account_id}"
  sns_topic_name  = "management-updates"

  # Metric filter definitions
  metric_filters = {
    SecurityGroupChanges = {
      pattern = "{ ($.eventName = \"AuthorizeSecurityGroupIngress\") || ($.eventName = \"AuthorizeSecurityGroupEgress\") || ($.eventName = \"RevokeSecurityGroupIngress\") || ($.eventName = \"RevokeSecurityGroupEgress\") || ($.eventName = \"CreateSecurityGroup\") || ($.eventName = \"DeleteSecurityGroup\") }"
      metric_name = "SecurityGroupChanges"
    }
    IAMUserCreationOrDeletion = {
      pattern = "{ ($.eventName = \"CreateUser\") || ($.eventName = \"DeleteUser\") }"
      metric_name = "IAMUserCreationOrDeletion"
    }
    FailedConsoleLogins = {
      pattern = "{ ($.eventName = \"ConsoleLogin\") && ($.responseElements.ConsoleLogin = \"Failure\") }"
      metric_name = "FailedConsoleLogins"
    }
    IAMGroupRoleUserPolicyChanges = {
      pattern = "{ ($.eventName = \"AttachGroupPolicy\") || ($.eventName = \"DetachGroupPolicy\") || ($.eventName = \"AttachRolePolicy\") || ($.eventName = \"DetachRolePolicy\") || ($.eventName = \"AttachUserPolicy\") || ($.eventName = \"DetachUserPolicy\") || ($.eventName = \"PutUserPolicy\") || ($.eventName = \"DeleteUserPolicy\") || ($.eventName = \"PutGroupPolicy\") || ($.eventName = \"DeleteGroupPolicy\") || ($.eventName = \"PutRolePolicy\") || ($.eventName = \"DeleteRolePolicy\") }"
      metric_name = "IAMGroupRoleUserPolicyChanges"
    }
    IAMPolicyChanges = {
      pattern = "{ ($.eventName = \"CreatePolicy\") || ($.eventName = \"DeletePolicy\") || ($.eventName = \"CreatePolicyVersion\") || ($.eventName = \"DeletePolicyVersion\") || ($.eventName = \"SetDefaultPolicyVersion\") }"
      metric_name = "IAMPolicyChanges"
    }
    UsersAddedToGroup = {
      pattern = "{ ($.eventName = \"AddUserToGroup\") }"
      metric_name = "UsersAddedToGroup"
    }
    IAMRoleCreationOrDeletion = {
      pattern = "{ ($.eventName = \"CreateRole\") || ($.eventName = \"DeleteRole\") }"
      metric_name = "IAMRoleCreationOrDeletion"
    }
  }
}

# Import blocks to bring existing resources into Terraform management
import {
  to = aws_s3_bucket.cloudtrail_logs
  id = local.bucket_name
}

import {
  to = aws_s3_bucket.cloudtrail_logs_logging
  id = "cloudtrail-logging-bucket-${local.account_id}"
}

import {
  to = aws_cloudwatch_log_group.cloudtrail
  id = local.log_group_name
}

import {
  to = aws_iam_role.cloudtrail_cloudwatch
  id = "cloudtrail-to-cloudwatch-role"
}

# KMS key for CloudTrail encryption
resource "aws_kms_key" "cloudtrail_key" {
  description             = "KMS key for CloudTrail encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudTrail to use the key"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey",
          "kms:Encrypt",
          "kms:ReEncrypt"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow S3 to use the key for SSE-KMS"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

# KMS key for CloudWatch Logs encryption
resource "aws_kms_key" "cloudwatch_logs_key" {
  description             = "KMS key for CloudWatch Logs encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

# S3 bucket for CloudTrail logs
resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket = local.bucket_name
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cloudtrail_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Allow CloudTrail to write logs"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "s3:PutObject",
          "s3:GetBucketAcl"
        ]
        Resource = [
          aws_s3_bucket.cloudtrail_logs.arn,
          "${aws_s3_bucket.cloudtrail_logs.arn}/*"
        ]
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = local.trail_arn
          }
        }
      }
    ]
  })
}

# Logging bucket for CloudTrail access logs
resource "aws_s3_bucket" "cloudtrail_logs_logging" {
  bucket = "cloudtrail-logging-bucket-${local.account_id}"
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs_logging" {
  bucket = aws_s3_bucket.cloudtrail_logs_logging.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Enable ACLs on the logging bucket (ownership controls)
resource "aws_s3_bucket_ownership_controls" "cloudtrail_logs_logging" {
  bucket = aws_s3_bucket.cloudtrail_logs_logging.id
  rule {
    object_ownership = "ObjectWriter"
  }
}

resource "aws_s3_bucket_acl" "cloudtrail_logs_logging_acl" {
  bucket = aws_s3_bucket.cloudtrail_logs_logging.id
  acl    = "log-delivery-write"
  depends_on = [
    aws_s3_bucket_ownership_controls.cloudtrail_logs_logging
  ]
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs_logging" {
  bucket = aws_s3_bucket.cloudtrail_logs_logging.id
  block_public_acls   = true
  block_public_policy = true
  ignore_public_acls  = true
  restrict_public_buckets = true
}

# Replace deprecated logging block with standalone resource
resource "aws_s3_bucket_logging" "cloudtrail_logs" {
  bucket        = aws_s3_bucket.cloudtrail_logs.id
  target_bucket = aws_s3_bucket.cloudtrail_logs_logging.id
  target_prefix = "log/"
}

# CloudWatch Logs group (encrypted with CMK)
resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = local.log_group_name
  retention_in_days = 365
  kms_key_id        = aws_kms_key.cloudwatch_logs_key.arn
  lifecycle {
    prevent_destroy = true
  }
}

# IAM role for CloudTrail to CloudWatch
resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name = "cloudtrail-to-cloudwatch-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudTrailToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# New policy with unique name prefix and correct resource ARN (includes log stream wildcard)
resource "aws_iam_policy" "cloudtrail_cloudwatch" {
  name_prefix = "cloudtrail-to-cloudwatch-policy-"
  description = "Allows CloudTrail to create log streams, put log events, and describe log groups"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudTrailToWriteLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups"
        ]
        Resource = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "cloudtrail_cloudwatch" {
  role       = aws_iam_role.cloudtrail_cloudwatch.name
  policy_arn = aws_iam_policy.cloudtrail_cloudwatch.arn
}

# CloudTrail trail (multi-region)
resource "aws_cloudtrail" "main" {
  name                          = local.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail_logs.id
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  kms_key_id                    = aws_kms_key.cloudtrail_key.arn
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch.arn

  event_selector {
    read_write_type           = "All"
    include_management_events = true
    exclude_management_event_sources = [
      "kms.amazonaws.com",
      "rdsdata.amazonaws.com"
    ]
  }

  depends_on = [
    aws_s3_bucket_policy.cloudtrail_logs,
    aws_iam_role_policy_attachment.cloudtrail_cloudwatch
  ]
}

# KMS key for SNS topic
resource "aws_kms_key" "sns_key" {
  description             = "KMS key for SNS topic encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Alarms to use the key"
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

# SNS topic
resource "aws_sns_topic" "management_updates" {
  name              = local.sns_topic_name
  kms_master_key_id = aws_kms_key.sns_key.arn
}

variable "sns_email_subscribers" {
  type    = list(string)
  default = ["placeholder@example.com"]
}

resource "aws_sns_topic_subscription" "email" {
  for_each  = toset(var.sns_email_subscribers)
  topic_arn = aws_sns_topic.management_updates.arn
  protocol  = "email"
  endpoint  = each.key
}

# CloudWatch Logs metric filters and alarms
resource "aws_cloudwatch_log_metric_filter" "this" {
  for_each       = local.metric_filters
  name           = each.key
  pattern        = each.value.pattern
  log_group_name = aws_cloudwatch_log_group.cloudtrail.name

  metric_transformation {
    name      = each.value.metric_name
    namespace = "management_activities"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "this" {
  for_each                   = local.metric_filters
  alarm_name                 = "${each.key}Alarm"
  comparison_operator        = "GreaterThanOrEqualToThreshold"
  evaluation_periods         = 1
  metric_name                = each.value.metric_name
  namespace                  = "management_activities"
  period                     = 60
  statistic                  = "Sum"
  threshold                  = 1
  alarm_description          = "Alarm for ${each.key}"
  insufficient_data_actions  = []
  alarm_actions              = [aws_sns_topic.management_updates.arn]
  treat_missing_data         = "notBreaching"

  depends_on = [
    aws_cloudwatch_log_metric_filter.this
  ]
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "config_rule_name_prefix" {
  description = "Prefix for the config rule name"
  type        = string
  default     = ""
}

variable "days_to_expiration" {
  description = "Number of days before expiration to trigger the rule"
  type        = number
  default     = 30
}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
  upper   = false
}

resource "random_string" "log_bucket_suffix" {
  length  = 8
  special = false
  upper   = false
}

resource "aws_kms_key" "config_key" {
  description             = "KMS key for AWS Config S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow Config Service to use the key"
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_s3_bucket" "config_bucket" {
  bucket = "aws-config-logs-${random_string.bucket_suffix.result}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "config_log_bucket" {
  bucket = "aws-config-log-archive-${random_string.log_bucket_suffix.result}"
}

resource "aws_s3_bucket_versioning" "config_bucket" {
  bucket = aws_s3_bucket.config_bucket.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "config_log_bucket" {
  bucket = aws_s3_bucket.config_log_bucket.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config_bucket" {
  bucket = aws_s3_bucket.config_bucket.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.config_key.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "config_bucket" {
  bucket = aws_s3_bucket.config_bucket.id

  block_public_acls         = true
  block_public_policy       = true
  ignore_public_acls        = true
  restrict_public_buckets   = true
}

resource "aws_s3_bucket_public_access_block" "config_log_bucket" {
  bucket = aws_s3_bucket.config_log_bucket.id

  block_public_acls         = true
  block_public_policy       = true
  ignore_public_acls        = true
  restrict_public_buckets   = true
}

resource "aws_s3_bucket_policy" "config_bucket" {
  bucket = aws_s3_bucket.config_bucket.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = [
          "s3:PutObject",
          "s3:GetBucketAcl",
          "s3:GetBucketLocation"
        ]
        Resource = [
          aws_s3_bucket.config_bucket.arn,
          "${aws_s3_bucket.config_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_s3_bucket_policy" "config_log_bucket" {
  bucket = aws_s3_bucket.config_log_bucket.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.config_log_bucket.arn}/*"
      }
    ]
  })
}

resource "aws_s3_bucket_logging" "config_bucket" {
  bucket        = aws_s3_bucket.config_bucket.id
  target_bucket = aws_s3_bucket.config_log_bucket.id
  target_prefix = "config-logs/"
}

resource "aws_iam_role" "aws_config_role" {
  name_prefix = "aws_config_role-"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "aws_config_role" {
  role       = aws_iam_role.aws_config_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWS_ConfigRole"
}

resource "aws_config_configuration_recorder" "main" {
  role_arn = aws_iam_role.aws_config_role.arn
  recording_group {
    all_supported              = true
    include_global_resource_types = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_config_delivery_channel" "main" {
  name           = "default"
  s3_bucket_name = aws_s3_bucket.config_bucket.bucket
  s3_kms_key_arn = aws_kms_key.config_key.arn
}

resource "aws_config_config_rule" "acm_expiration" {
  name = var.config_rule_name_prefix != "" ? "${var.config_rule_name_prefix}-acm-expiration" : "acm-expiration"
  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }
  input_parameters = jsonencode({ daysToExpiration = tostring(var.days_to_expiration) })
}

resource "aws_cognito_user_pool" "fiap_hackathon_cognito_pool" {
  name                     = "fiap-hackathon-cognito-pool"
  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]
  mfa_configuration        = "OFF"

  password_policy {
    minimum_length = 8
  }

  schema {
    name                = "name"
    attribute_data_type = "String"
    required            = true
    mutable             = true
  }
}

resource "aws_cognito_user_pool_client" "cognito_pool_client" {
  name         = "cognito-pool-client"
  user_pool_id = aws_cognito_user_pool.fiap_hackathon_cognito_pool.id

  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]
}

variable "azure_tenant_id" {
  description = "Azure AD tenant ID"
  type        = string
  default     = "221ca1d3-b3f2-4346-8abc-88f802495c7d"
}

variable "azure_client_id" {
  description = "Azure AD application (client) ID for OIDC"
  type        = string
  default     = "c8b9cf86-e2b4-4428-b356-14313412a4d1"
}

data "tls_certificate" "azure_oidc" {
  url = "https://sts.windows.net/${var.azure_tenant_id}/"
}

resource "aws_iam_openid_connect_provider" "azure_ad" {
  url             = "https://sts.windows.net/${var.azure_tenant_id}/"
  client_id_list  = [var.azure_client_id]
  thumbprint_list = data.tls_certificate.azure_oidc.certificates[*].sha1_fingerprint
}

data "aws_iam_policy_document" "sentinel_oidc_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]
    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.azure_ad.arn]
    }
    condition {
      test     = "StringEquals"
      variable = "sts.windows.net/${var.azure_tenant_id}/:aud"
      values   = [var.azure_client_id]
    }
  }
}

resource "aws_iam_role" "sentinel_oidc_orgs_readonly" {
  name               = "Sentinel-OIDC-Organizations-ReadOnly"
  assume_role_policy = data.aws_iam_policy_document.sentinel_oidc_trust.json
}

resource "aws_iam_role_policy_attachment" "orgs_readonly" {
  role       = aws_iam_role.sentinel_oidc_orgs_readonly.name
  policy_arn = "arn:aws:iam::aws:policy/AWSOrganizationsReadOnlyAccess"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "allow_add_role_to_db_cluster" {
  statement {
    actions   = ["rds:AddRoleToDBCluster"]
    resources = ["arn:aws:rds:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:cluster:foo_cluster"]
    effect    = "Allow"
  }
}

data "aws_iam_policy_document" "allow_add_star" {
  statement {
    actions   = ["rds:Add*"]
    resources = ["arn:aws:rds:*:*:cluster:*"]
    effect    = "Allow"
  }
}

data "aws_iam_policy_document" "deny_add_star" {
  statement {
    actions   = ["rds:Add*"]
    resources = ["arn:aws:rds:*:*:cluster:*"]
    effect    = "Deny"
  }
}

resource "aws_iam_role" "ec2_test_role" {
  name               = "ec2_test_role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
}

resource "aws_iam_role_policy" "allow_add_role_to_db_cluster" {
  name   = "allow_add_role_to_db_cluster"
  role   = aws_iam_role.ec2_test_role.name
  policy = data.aws_iam_policy_document.allow_add_role_to_db_cluster.json
}

resource "aws_iam_role_policy" "allow_add_star" {
  name   = "allow_add_star"
  role   = aws_iam_role.ec2_test_role.name
  policy = data.aws_iam_policy_document.allow_add_star.json
}

resource "aws_iam_role_policy" "deny_add_star" {
  name   = "deny_add_star"
  role   = aws_iam_role.ec2_test_role.name
  policy = data.aws_iam_policy_document.deny_add_star.json
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "environment_name" {
  description = "Environment name for the state bucket naming"
  type        = string
  default     = "dev"
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# -----------------------------------------------------------------------
# KMS key for frontend S3 bucket
# -----------------------------------------------------------------------
resource "aws_kms_key" "frontend" {
  description             = "KMS key for frontend S3 bucket encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowS3ServiceToUseKey"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "frontend" {
  name          = "alias/s3-frontend-nft-maker-v2-key"
  target_key_id = aws_kms_key.frontend.key_id
}

# -----------------------------------------------------------------------
# Frontend S3 bucket
# -----------------------------------------------------------------------
resource "aws_s3_bucket" "frontend" {
  bucket = "s3-frontend-nft-maker-v2-${local.account_id}"
  force_destroy = false

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        kms_master_key_id = aws_kms_key.frontend.arn
        sse_algorithm     = "aws:kms"
      }
      bucket_key_enabled = true
    }
  }

  logging {
    target_bucket = aws_s3_bucket.s3_access_logs.id
    target_prefix = "log/frontend/"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "frontend" {
  bucket                  = aws_s3_bucket.frontend.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_website_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id
  index_document {
    suffix = "index.html"
  }
  error_document {
    key = "index.html"
  }
}

resource "aws_s3_bucket_cors_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id
  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET", "PUT", "POST", "DELETE"]
    allowed_origins = ["*"]
    expose_headers  = []
    max_age_seconds = 3600
  }
}

# -----------------------------------------------------------------------
# CloudFront Origin Access Identity
# -----------------------------------------------------------------------
resource "aws_cloudfront_origin_access_identity" "frontend" {
  comment = "OAI for frontend S3 bucket"
}

# -----------------------------------------------------------------------
# Bucket policy granting OAI read/list access
# -----------------------------------------------------------------------
resource "aws_s3_bucket_policy" "frontend" {
  bucket = aws_s3_bucket.frontend.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudFrontOAIReadList"
        Effect = "Allow"
        Principal = {
          AWS = aws_cloudfront_origin_access_identity.frontend.iam_arn
        }
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.frontend.arn,
          "${aws_s3_bucket.frontend.arn}/*"
        ]
      }
    ]
  })
}

# -----------------------------------------------------------------------
# WAFv2 Web ACL (CloudFront scope)
# -----------------------------------------------------------------------
resource "aws_wafv2_web_acl" "frontend" {
  name        = "frontend-waf-acl"
  description = "Web ACL for CloudFront distribution"
  scope       = "CLOUDFRONT"
  default_action {
    allow {}
  }
  rule {
    name     = "AWSManagedRulesCommonRuleSet"
    priority = 0
    override_action {
      none {}
    }
    statement {
      managed_rule_group_statement {
        vendor_name = "AWS"
        name        = "AWSManagedRulesCommonRuleSet"
      }
    }
    visibility_config {
      cloudwatch_metrics_enabled = false
      metric_name                = "AWSManagedRulesCommonRuleSet"
      sampled_requests_enabled   = false
    }
  }
  visibility_config {
    cloudwatch_metrics_enabled = false
    metric_name                = "frontend-waf-acl"
    sampled_requests_enabled   = false
  }
}

# -----------------------------------------------------------------------
# S3 bucket for CloudFront access logs
# -----------------------------------------------------------------------
resource "aws_s3_bucket" "cloudfront_logs" {
  bucket = "cloudfront-logs-${local.account_id}"
  force_destroy = false

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudfront_logs" {
  bucket                  = aws_s3_bucket.cloudfront_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Grant CloudFront logs and S3 server logs delivery permission via bucket policy
resource "aws_s3_bucket_policy" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudFrontLogDelivery"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.cloudfront_logs.arn}/*"
      },
      {
        Sid    = "AllowS3ServerLogDelivery"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.cloudfront_logs.arn}/*"
      }
    ]
  })
}

# -----------------------------------------------------------------------
# CloudFront distribution
# -----------------------------------------------------------------------
resource "aws_cloudfront_distribution" "frontend" {
  enabled         = true
  is_ipv6_enabled = true
  price_class     = "PriceClass_200"
  default_root_object = "index.html"
  web_acl_id      = aws_wafv2_web_acl.frontend.arn

  logging_config {
    bucket          = aws_s3_bucket.cloudfront_logs.bucket_domain_name
    prefix          = "cloudfront/"
    include_cookies = false
  }

  origin {
    domain_name = aws_s3_bucket.frontend.bucket_regional_domain_name
    origin_id   = "S3-${aws_s3_bucket.frontend.id}"
    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.frontend.cloudfront_access_identity_path
    }
  }

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD", "OPTIONS"]
    target_origin_id = "S3-${aws_s3_bucket.frontend.id}"

    compress               = true
    viewer_protocol_policy = "redirect-to-https"

    min_ttl     = 0
    default_ttl = 3600
    max_ttl     = 86400

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }
  }

  # /content/immutable/* - longer cache, compressed
  ordered_cache_behavior {
    path_pattern     = "/content/immutable/*"
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD", "OPTIONS"]
    target_origin_id = "S3-${aws_s3_bucket.frontend.id}"

    compress               = true
    viewer_protocol_policy = "redirect-to-https"

    min_ttl     = 0
    default_ttl = 86400
    max_ttl     = 31536000

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }
  }

  # /content/* - medium cache, compressed
  ordered_cache_behavior {
    path_pattern     = "/content/*"
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD", "OPTIONS"]
    target_origin_id = "S3-${aws_s3_bucket.frontend.id}"

    compress               = true
    viewer_protocol_policy = "redirect-to-https"

    min_ttl     = 0
    default_ttl = 86400
    max_ttl     = 2592000

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  retain_on_delete = false
}

# -----------------------------------------------------------------------
# S3 bucket for server access logs
# -----------------------------------------------------------------------
resource "aws_s3_bucket" "s3_access_logs" {
  bucket = "s3-access-logs-${local.account_id}"
  force_destroy = false

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "s3_access_logs" {
  bucket                  = aws_s3_bucket.s3_access_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Grant S3 server log delivery permission via bucket policy
resource "aws_s3_bucket_policy" "s3_access_logs" {
  bucket = aws_s3_bucket.s3_access_logs.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3ServerLogDelivery"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.s3_access_logs.arn}/*"
      }
    ]
  })
}

# -----------------------------------------------------------------------
# KMS key for DynamoDB table
# -----------------------------------------------------------------------
resource "aws_kms_key" "dynamodb" {
  description             = "KMS key for DynamoDB table encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowDynamoDBServiceToUseKey"
        Effect = "Allow"
        Principal = {
          Service = "dynamodb.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "dynamodb" {
  name          = "alias/near-frontend-dynamodb-key"
  target_key_id = aws_kms_key.dynamodb.key_id
}

# -----------------------------------------------------------------------
# KMS key for Terraform state S3 bucket
# -----------------------------------------------------------------------
resource "aws_kms_key" "state" {
  description             = "KMS key for Terraform state bucket encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowS3ServiceToUseKey"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "state" {
  name          = "alias/near-frontend-terraform-state-key"
  target_key_id = aws_kms_key.state.key_id
}

# -----------------------------------------------------------------------
# Terraform state S3 bucket
# -----------------------------------------------------------------------
resource "aws_s3_bucket" "state" {
  bucket = "near-frontend-${var.environment_name}-terraform-state-${local.account_id}"
  force_destroy = false

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        kms_master_key_id = aws_kms_key.state.arn
        sse_algorithm     = "aws:kms"
      }
      bucket_key_enabled = true
    }
  }

  logging {
    target_bucket = aws_s3_bucket.s3_access_logs.id
    target_prefix = "log/state/"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket                  = aws_s3_bucket.state.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------
# DynamoDB table for state locking
# -----------------------------------------------------------------------
resource "aws_dynamodb_table" "terraform_state_lock" {
  name           = "near-frontend-terraform-state"
  billing_mode   = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.dynamodb.arn
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  base_name = "stackx-network"

  # Availability zones (3 AZs)
  az_names = data.aws_availability_zones.available.names

  # CIDR blocks for subnets
  private_cidrs  = ["10.1.0.0/18", "10.1.64.0/18", "10.1.128.0/18"]
  public_cidrs   = ["10.1.192.0/22", "10.1.196.0/22", "10.1.200.0/22"]
  database_cidrs = ["10.1.204.0/22", "10.1.208.0/22", "10.1.212.0/22"]
  cache_cidrs    = ["10.1.216.0/22", "10.1.220.0/22", "10.1.224.0/22"]
  internal_cidrs = ["10.1.228.0/22", "10.1.232.0/22", "10.1.236.0/22"]

  # Common tags for all resources
  common_tags = {
    "kubernetes.io/cluster/stackx" = "shared"
  }
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

# VPC
resource "aws_vpc" "stackx_network" {
  cidr_block                       = "10.1.0.0/16"
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = merge(local.common_tags, {
    Name = local.base_name
  })
}

# Internet Gateway
resource "aws_internet_gateway" "stackx_network" {
  vpc_id = aws_vpc.stackx_network.id

  tags = merge(local.common_tags, {
    Name = "${local.base_name}-igw"
  })
}

# Egress-only Internet Gateway
resource "aws_egress_only_internet_gateway" "stackx_network" {
  vpc_id = aws_vpc.stackx_network.id

  tags = merge(local.common_tags, {
    Name = "${local.base_name}-eigw"
  })
}

# Public Subnets
resource "aws_subnet" "stackx_network_public" {
  count             = 3
  vpc_id            = aws_vpc.stackx_network.id
  cidr_block        = local.public_cidrs[count.index]
  availability_zone = local.az_names[count.index]
  ipv6_cidr_block   = cidrsubnet(aws_vpc.stackx_network.ipv6_cidr_block, 8, count.index)

  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name                       = "${local.base_name}-public-${count.index + 1}"
    "kubernetes.io/role/elb"   = "1"
  })
}

# Private Subnets
resource "aws_subnet" "stackx_network_private" {
  count             = 3
  vpc_id            = aws_vpc.stackx_network.id
  cidr_block        = local.private_cidrs[count.index]
  availability_zone = local.az_names[count.index]
  ipv6_cidr_block   = cidrsubnet(aws_vpc.stackx_network.ipv6_cidr_block, 8, count.index + 3)

  tags = merge(local.common_tags, {
    Name                           = "${local.base_name}-private-${count.index + 1}"
    "kubernetes.io/role/internal-elb" = "1"
    "karpenter.sh/discovery"       = "stackx"
  })
}

# Elastic IPs for NAT Gateways
resource "aws_eip" "stackx_network" {
  count  = 3
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.base_name}-nat-eip-${count.index + 1}"
  })
}

# NAT Gateways (one per AZ in public subnet)
resource "aws_nat_gateway" "stackx_network" {
  count         = 3
  allocation_id = aws_eip.stackx_network[count.index].id
  subnet_id     = aws_subnet.stackx_network_public[count.index].id

  tags = merge(local.common_tags, {
    Name = "${local.base_name}-nat-${count.index + 1}"
  })

  depends_on = [aws_internet_gateway.stackx_network]
}

# Public Route Table
resource "aws_route_table" "stackx_network_public" {
  vpc_id = aws_vpc.stackx_network.id

  route {
    cidr_block      = "0.0.0.0/0"
    gateway_id      = aws_internet_gateway.stackx_network.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.stackx_network.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.base_name}-public-rt"
  })
}

# Public Route Table Associations
resource "aws_route_table_association" "stackx_network_public" {
  count          = 3
  subnet_id      = aws_subnet.stackx_network_public[count.index].id
  route_table_id = aws_route_table.stackx_network_public.id
}

# Private Route Tables (one per AZ)
resource "aws_route_table" "stackx_network_private" {
  count  = 3
  vpc_id = aws_vpc.stackx_network.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.stackx_network[count.index].id
  }

  route {
    ipv6_cidr_block                = "::/0"
    egress_only_gateway_id         = aws_egress_only_internet_gateway.stackx_network.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.base_name}-private-rt-${count.index + 1}"
  })
}

# Private Route Table Associations
resource "aws_route_table_association" "stackx_network_private" {
  count          = 3
  subnet_id      = aws_subnet.stackx_network_private[count.index].id
  route_table_id = aws_route_table.stackx_network_private[count.index].id
}

# S3 VPC Endpoint (Gateway)
resource "aws_vpc_endpoint" "stackx_network_s3" {
  vpc_id       = aws_vpc.stackx_network.id
  service_name = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"

  route_table_ids = aws_route_table.stackx_network_private[*].id

  tags = merge(local.common_tags, {
    Name = "${local.base_name}-s3-endpoint"
  })
}

# ---------------------------------------------------------------------------
# Optional Database Subnets
# ---------------------------------------------------------------------------
variable "enable_database_subnets" {
  description = "Enable creation of database subnets, route table, and RDS subnet group"
  type        = bool
  default     = false
}

resource "aws_subnet" "stackx_network_database" {
  count             = var.enable_database_subnets ? 3 : 0
  vpc_id            = aws_vpc.stackx_network.id
  cidr_block        = local.database_cidrs[count.index]
  availability_zone = local.az_names[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.base_name}-database-${count.index + 1}"
  })
}

resource "aws_route_table" "stackx_network_database" {
  count  = var.enable_database_subnets ? 1 : 0
  vpc_id = aws_vpc.stackx_network.id

  # No routes – isolated

  tags = merge(local.common_tags, {
    Name = "${local.base_name}-database-rt"
  })
}

resource "aws_route_table_association" "stackx_network_database" {
  count          = var.enable_database_subnets ? 3 : 0
  subnet_id      = aws_subnet.stackx_network_database[count.index].id
  route_table_id = aws_route_table.stackx_network_database[0].id
}

resource "aws_db_subnet_group" "stackx_network" {
  count      = var.enable_database_subnets ? 1 : 0
  name       = "${local.base_name}-db-subnet-group"
  subnet_ids = aws_subnet.stackx_network_database[*].id

  tags = merge(local.common_tags, {
    Name = "${local.base_name}-db-subnet-group"
  })
}

# ---------------------------------------------------------------------------
# Optional Cache Subnets
# ---------------------------------------------------------------------------
variable "enable_cache_subnets" {
  description = "Enable creation of cache subnets, route table, and ElastiCache subnet group"
  type        = bool
  default     = false
}

resource "aws_subnet" "stackx_network_cache" {
  count             = var.enable_cache_subnets ? 3 : 0
  vpc_id            = aws_vpc.stackx_network.id
  cidr_block        = local.cache_cidrs[count.index]
  availability_zone = local.az_names[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.base_name}-cache-${count.index + 1}"
  })
}

resource "aws_route_table" "stackx_network_cache" {
  count  = var.enable_cache_subnets ? 1 : 0
  vpc_id = aws_vpc.stackx_network.id

  # No routes – isolated

  tags = merge(local.common_tags, {
    Name = "${local.base_name}-cache-rt"
  })
}

resource "aws_route_table_association" "stackx_network_cache" {
  count          = var.enable_cache_subnets ? 3 : 0
  subnet_id      = aws_subnet.stackx_network_cache[count.index].id
  route_table_id = aws_route_table.stackx_network_cache[0].id
}

resource "aws_elasticache_subnet_group" "stackx_network" {
  count      = var.enable_cache_subnets ? 1 : 0
  name       = "${local.base_name}-cache-subnet-group"
  subnet_ids = aws_subnet.stackx_network_cache[*].id

  tags = merge(local.common_tags, {
    Name = "${local.base_name}-cache-subnet-group"
  })
}

# ---------------------------------------------------------------------------
# Optional Internal Subnets
# ---------------------------------------------------------------------------
variable "enable_internal_subnets" {
  description = "Enable creation of internal subnets and route table (no internet access)"
  type        = bool
  default     = false
}

resource "aws_subnet" "stackx_network_internal" {
  count             = var.enable_internal_subnets ? 3 : 0
  vpc_id            = aws_vpc.stackx_network.id
  cidr_block        = local.internal_cidrs[count.index]
  availability_zone = local.az_names[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.base_name}-internal-${count.index + 1}"
  })
}

resource "aws_route_table" "stackx_network_internal" {
  count  = var.enable_internal_subnets ? 1 : 0
  vpc_id = aws_vpc.stackx_network.id

  # No routes – isolated

  tags = merge(local.common_tags, {
    Name = "${local.base_name}-internal-rt"
  })
}

resource "aws_route_table_association" "stackx_network_internal" {
  count          = var.enable_internal_subnets ? 3 : 0
  subnet_id      = aws_subnet.stackx_network_internal[count.index].id
  route_table_id = aws_route_table.stackx_network_internal[0].id
}

# ---------------------------------------------------------------------------
# VPC Flow Logs (Added to resolve Trivy AWS-0178)
# ---------------------------------------------------------------------------
resource "aws_kms_key" "stackx_network_flow_log" {
  description             = "KMS key for CloudWatch log group encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.base_name}-flow-log-key"
  })
}

resource "aws_kms_alias" "stackx_network_flow_log" {
  name          = "alias/${local.base_name}-flow-log-key"
  target_key_id = aws_kms_key.stackx_network_flow_log.key_id
}

resource "aws_cloudwatch_log_group" "stackx_network_flow_log" {
  name              = "/aws/vpc/flow-logs/stackx-network"
  retention_in_days = 30
  kms_key_id        = aws_kms_alias.stackx_network_flow_log.arn

  tags = merge(local.common_tags, {
    Name = "${local.base_name}-flow-log-group"
  })
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "stackx_network_flow_log_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "stackx_network_flow_log" {
  name               = "${local.base_name}-flow-log-role"
  assume_role_policy = data.aws_iam_policy_document.stackx_network_flow_log_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.base_name}-flow-log-role"
  })
}

data "aws_iam_policy_document" "stackx_network_flow_log_permissions" {
  statement {
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams"
    ]
    resources = [
      "${aws_cloudwatch_log_group.stackx_network_flow_log.arn}:*",
      aws_cloudwatch_log_group.stackx_network_flow_log.arn
    ]
  }
}

resource "aws_iam_policy" "stackx_network_flow_log" {
  name        = "${local.base_name}-flow-log-policy"
  description = "Policy for VPC Flow Logs to publish to CloudWatch"
  policy      = data.aws_iam_policy_document.stackx_network_flow_log_permissions.json

  tags = merge(local.common_tags, {
    Name = "${local.base_name}-flow-log-policy"
  })
}

resource "aws_iam_role_policy_attachment" "stackx_network_flow_log" {
  role       = aws_iam_role.stackx_network_flow_log.name
  policy_arn = aws_iam_policy.stackx_network_flow_log.arn
}

resource "aws_flow_log" "stackx_network" {
  log_group_name = aws_cloudwatch_log_group.stackx_network_flow_log.name
  iam_role_arn   = aws_iam_role.stackx_network_flow_log.arn
  vpc_id         = aws_vpc.stackx_network.id
  traffic_type   = "ALL"

  tags = merge(local.common_tags, {
    Name = "${local.base_name}-flow-log"
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 2.0"
    }
  }
}

# Data source for account ID
data "aws_caller_identity" "current" {}

# KMS key and alias
resource "aws_kms_key" "main" {
  description             = "Shared CMK for data lake encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

resource "aws_kms_alias" "main" {
  name          = "alias/benchmark-datalake-key"
  target_key_id = aws_kms_key.main.key_id
}

# Local values for bucket names
locals {
  account_id  = data.aws_caller_identity.current.account_id
  bucket_suffix = "-${local.account_id}"

  artefact_bucket = "benchmark-glue-artefacts${local.bucket_suffix}"
  staging_bucket  = "benchmark-datalake-staging${local.bucket_suffix}"
  bronze_bucket   = "benchmark-datalake-bronze${local.bucket_suffix}"
  silver_bucket   = "benchmark-datalake-silver${local.bucket_suffix}"
  gold_bucket     = "benchmark-datalake-gold${local.bucket_suffix}"
  logs_bucket     = "benchmark-datalake-logs${local.bucket_suffix}"

  all_bucket_names = [
    local.artefact_bucket,
    local.staging_bucket,
    local.bronze_bucket,
    local.silver_bucket,
    local.gold_bucket,
    local.logs_bucket
  ]

  all_bucket_arns = [for b in local.all_bucket_names : "arn:aws:s3:::${b}"]
  all_bucket_object_arns = [for b in local.all_bucket_names : "arn:aws:s3:::${b}/*"]
}

# Placeholder local files to guarantee source existence
