# IAM role for Glue
resource "aws_iam_role" "glue_role" {
  name = "glue-weather-datalake-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "glue.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "glue_policy" {
  name = "glue-weather-datalake-policy"
  role = aws_iam_role.glue_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "glue:StartJobRun",
          "glue:GetJobRun",
          "glue:GetJobRuns",
          "glue:BatchStopJobRun",
          "glue:GetJob",
          "glue:GetJobs"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "secretsmanager:GetSecretValue"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Resource = concat(local.all_bucket_arns, local.all_bucket_object_arns)
      }
    ]
  })
}

# Glue job - extraiDados
resource "aws_glue_job" "extrai_dados" {
  name     = "glue-job-extrai-dados"
  role_arn = aws_iam_role.glue_role.arn
  glue_version = "4.0"

  command {
    script_location = "s3://${aws_s3_bucket.artefacts.id}/extraiDados.py"
    python_version  = "3"
  }

  worker_type = "G.1X"
  number_of_workers = 20
  max_retries = 0
  timeout = 2880

  execution_property {
    max_concurrent_runs = 2
  }

  default_arguments = {
    "--city"          = "Sao Paulo"
    "--staging_bucket" = local.staging_bucket
    "--api_key"       = "placeholder_api_key"
  }

  lifecycle {
    create_before_destroy = true
  }
}

# Glue job - transformaDados
resource "aws_glue_job" "transforma_dados" {
  name     = "glue-job-transforma-dados"
  role_arn = aws_iam_role.glue_role.arn
  glue_version = "4.0"

  command {
    script_location = "s3://${aws_s3_bucket.artefacts.id}/transformaDados.py"
    python_version  = "3"
  }

  worker_type = "G.1X"
  number_of_workers = 20
  max_retries = 0
  timeout = 2880

  execution_property {
    max_concurrent_runs = 2
  }

  default_arguments = {
    "--extra-py-files"   = "s3://${aws_s3_bucket.artefacts.id}/lib.zip"
    "--datalake-formats" = "iceberg"
    "--staging_bucket"   = local.staging_bucket
    "--bronze_bucket"    = local.bronze_bucket
    "--silver_bucket"    = local.silver_bucket
    "--translation_key"  = "placeholder_translation_key"
  }

  lifecycle {
    create_before_destroy = true
  }
}

# IAM role for Step Functions
resource "aws_iam_role" "step_functions_role" {
  name = "step-functions-weather-datalake-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "states.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "step_functions_policy" {
  name = "step-functions-weather-datalake-policy"
  role = aws_iam_role.step_functions_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "glue:StartJobRun",
          "glue:GetJobRun",
          "glue:StopJobRun",
          "glue:BatchStopJobRun"
        ]
        Resource = [
          aws_glue_job.extrai_dados.arn,
          aws_glue_job.transforma_dados.arn
        ]
      }
    ]
  })
}

# Step Functions state machine
resource "aws_sfn_state_machine" "weather_data_lake_pipeline" {
  name     = "weather-data-lake-pipeline"
  role_arn = aws_iam_role.step_functions_role.arn

  definition = jsonencode({
    Comment = "Weather data lake pipeline"
    StartAt = "ExtractData"
    States = {
      ExtractData = {
        Type = "Task"
        Resource = "arn:aws:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = aws_glue_job.extrai_dados.name
          Arguments = {
            "--city"          = "Sao Paulo"
            "--staging_bucket" = local.staging_bucket
            "--api_key"       = "placeholder_api_key"
          }
        }
        Next = "TransformData"
      }
      TransformData = {
        Type = "Task"
        Resource = "arn:aws:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = aws_glue_job.transforma_dados.name
          Arguments = {
            "--staging_bucket"  = local.staging_bucket
            "--bronze_bucket"   = local.bronze_bucket
            "--silver_bucket"   = local.silver_bucket
            "--translation_key" = "placeholder_translation_key"
          }
        }
        End = true
      }
    }
  })
}

# IAM role for EventBridge
resource "aws_iam_role" "eventbridge_role" {
  name = "eventbridge-weather-datalake-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "eventbridge_policy" {
  name = "eventbridge-weather-datalake-policy"
  role = aws_iam_role.eventbridge_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "states:StartExecution"
        Resource = aws_sfn_state_machine.weather_data_lake_pipeline.arn
      }
    ]
  })
}

# EventBridge rule and target
resource "aws_cloudwatch_event_rule" "hourly_trigger" {
  name                = "hourly-weather-pipeline-trigger"
  schedule_expression = "rate(1 hour)"
}

resource "aws_cloudwatch_event_target" "state_machine_target" {
  rule      = aws_cloudwatch_event_rule.hourly_trigger.name
  target_id = "StepFunctionsTarget"
  arn       = aws_sfn_state_machine.weather_data_lake_pipeline.arn
  role_arn  = aws_iam_role.eventbridge_role.arn
}

# Import blocks to adopt existing resources
import {
  to = aws_s3_bucket.silver
  id = local.silver_bucket
}

import {
  to = aws_athena_database.silver
  id = "silver"
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name

  target_bucket_name      = "benchmark-cicd-target-${local.account_id}"
  target_logs_bucket_name = "benchmark-cicd-target-logs-${local.account_id}"
  artifact_bucket_name    = "benchmark-cicd-artifacts-${local.account_id}"
  artifact_logs_bucket_name = "benchmark-cicd-artifacts-logs-${local.account_id}"
  cf_logs_bucket_name     = "benchmark-cicd-cf-logs-${local.account_id}"

  tags = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# ----------------------------------------------------------------------
# KMS Key
# ----------------------------------------------------------------------
resource "aws_kms_key" "this" {
  description             = "KMS key for encrypting S3 buckets in CI/CD pipeline"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  key_usage               = "ENCRYPT_DECRYPT"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = { AWS = "arn:aws:iam::${local.account_id}:root" }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 to use the key"
        Effect = "Allow"
        Principal = { Service = "s3.amazonaws.com" }
        Action = ["kms:Decrypt", "kms:GenerateDataKey*", "kms:Encrypt"]
        Resource = "*"
      },
      {
        Sid    = "Allow CodeBuild and CodePipeline roles to use the key"
        Effect = "Allow"
        Principal = { AWS = [aws_iam_role.codebuild.arn, aws_iam_role.codepipeline.arn] }
        Action = ["kms:Decrypt", "kms:GenerateDataKey*", "kms:Encrypt", "kms:ReEncrypt*", "kms:DescribeKey"]
        Resource = "*"
      }
    ]
  })
  tags = local.tags
}

resource "aws_kms_alias" "this" {
  name          = "alias/benchmark-cicd-key"
  target_key_id = aws_kms_key.this.key_id
}

# ----------------------------------------------------------------------
# Target S3 bucket (website files)
# ----------------------------------------------------------------------
resource "aws_s3_bucket" "target" {
  bucket = local.target_bucket_name
  force_destroy = false
  tags = merge(local.tags, { Name = local.target_bucket_name })
  lifecycle { prevent_destroy = true }
}

resource "aws_s3_bucket_versioning" "target" {
  bucket = aws_s3_bucket.target.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_public_access_block" "target" {
  bucket = aws_s3_bucket.target.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "target" {
  bucket = aws_s3_bucket.target.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.this.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_cloudfront_origin_access_control" "target" {
  name                              = "benchmark-cicd-oac"
  description                       = "OAC for target bucket"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

resource "aws_s3_bucket_policy" "target" {
  bucket = aws_s3_bucket.target.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid    = "AllowCloudFrontServicePrincipal"
      Effect = "Allow"
      Principal = { Service = "cloudfront.amazonaws.com" }
      Action   = "s3:GetObject"
      Resource = "${aws_s3_bucket.target.arn}/*"
      Condition = {
        StringEquals = { "AWS:SourceArn" = aws_cloudfront_distribution.this.arn }
      }
    }]
  })
}

# Target bucket access logging
resource "aws_s3_bucket" "target_logs" {
  bucket = local.target_logs_bucket_name
  force_destroy = true
  tags = merge(local.tags, { Name = local.target_logs_bucket_name })
}

resource "aws_s3_bucket_versioning" "target_logs" {
  bucket = aws_s3_bucket.target_logs.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_public_access_block" "target_logs" {
  bucket = aws_s3_bucket.target_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "target_logs" {
  bucket = aws_s3_bucket.target_logs.id
  rule { object_ownership = "BucketOwnerPreferred" }
}

resource "aws_s3_bucket_acl" "target_logs" {
  bucket = aws_s3_bucket.target_logs.id
  acl    = "log-delivery-write"
  depends_on = [aws_s3_bucket_ownership_controls.target_logs]
}

resource "aws_s3_bucket_lifecycle_configuration" "target_logs" {
  bucket = aws_s3_bucket.target_logs.id
  rule {
    id     = "expire-logs"
    status = "Enabled"
    filter {}
    expiration { days = 90 }
  }
}

resource "aws_s3_bucket_logging" "target" {
  bucket        = aws_s3_bucket.target.id
  target_bucket = aws_s3_bucket.target_logs.id
  target_prefix = "logs/"
}

# ----------------------------------------------------------------------
# Artifact S3 bucket
# ----------------------------------------------------------------------
resource "aws_s3_bucket" "artifact" {
  bucket = local.artifact_bucket_name
  force_destroy = false
  tags = merge(local.tags, { Name = local.artifact_bucket_name })
  lifecycle { prevent_destroy = true }
}

resource "aws_s3_bucket_versioning" "artifact" {
  bucket = aws_s3_bucket.artifact.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_public_access_block" "artifact" {
  bucket = aws_s3_bucket.artifact.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact" {
  bucket = aws_s3_bucket.artifact.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.this.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_policy" "artifact" {
  bucket = aws_s3_bucket.artifact.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid       = "DenyNonTLS"
      Effect    = "Deny"
      Principal = "*"
      Action    = "s3:*"
      Resource = [
        aws_s3_bucket.artifact.arn,
        "${aws_s3_bucket.artifact.arn}/*"
      ]
      Condition = {
        Bool = { "aws:SecureTransport" = "false" }
      }
    }]
  })
}

# Artifact bucket access logging (unconditional)
resource "aws_s3_bucket" "artifact_logs" {
  bucket = local.artifact_logs_bucket_name
  force_destroy = true
  tags = merge(local.tags, { Name = local.artifact_logs_bucket_name })
}

resource "aws_s3_bucket_versioning" "artifact_logs" {
  bucket = aws_s3_bucket.artifact_logs.id
  versioning_configuration { status = "Enabled" }
