resource "aws_s3_bucket_public_access_block" "artifact_logs" {
  bucket = aws_s3_bucket.artifact_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "artifact_logs" {
  bucket = aws_s3_bucket.artifact_logs.id
  rule { object_ownership = "BucketOwnerPreferred" }
