}

resource "aws_s3_bucket_logging" "artifact" {
  bucket        = aws_s3_bucket.artifact.id
  target_bucket = aws_s3_bucket.artifact_logs.id
  target_prefix = "logs/"
}

# ----------------------------------------------------------------------
# CloudFront access log bucket
# ----------------------------------------------------------------------
resource "aws_s3_bucket" "cf_logs" {
  bucket = local.cf_logs_bucket_name
  force_destroy = true
  tags = merge(local.tags, { Name = local.cf_logs_bucket_name })
}

resource "aws_s3_bucket_versioning" "cf_logs" {
  bucket = aws_s3_bucket.cf_logs.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_public_access_block" "cf_logs" {
  bucket = aws_s3_bucket.cf_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "cf_logs" {
  bucket = aws_s3_bucket.cf_logs.id
  rule { object_ownership = "BucketOwnerPreferred" }
}

resource "aws_s3_bucket_acl" "cf_logs" {
  bucket = aws_s3_bucket.cf_logs.id
  acl    = "log-delivery-write"
  depends_on = [aws_s3_bucket_ownership_controls.cf_logs]
}

resource "aws_s3_bucket_lifecycle_configuration" "cf_logs" {
  bucket = aws_s3_bucket.cf_logs.id
  rule {
    id     = "expire-logs"
    status = "Enabled"
    filter {}
    expiration { days = 90 }
  }
}

# ----------------------------------------------------------------------
# WAFv2 Web ACL for CloudFront
# ----------------------------------------------------------------------
resource "aws_wafv2_web_acl" "this" {
  name        = "benchmark-cicd-waf"
  description = "WAF for CloudFront distribution"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  rule {
    name     = "AllowAll"
    priority = 0
    action {
      allow {}
    }
    statement {
      byte_match_statement {
        search_string = "dummy"
        positional_constraint = "EXACTLY"
        field_to_match {
          uri_path {}
        }
        text_transformation {
          priority = 0
          type     = "NONE"
        }
      }
    }
    visibility_config {
      cloudwatch_metrics_enabled = false
      metric_name                = "AllowAllRule"
      sampled_requests_enabled   = false
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = false
    metric_name                = "BenchmarkCICDWAF"
    sampled_requests_enabled   = false
  }

  tags = local.tags
}

# ----------------------------------------------------------------------
# CloudFront Distribution
# ----------------------------------------------------------------------
resource "aws_cloudfront_distribution" "this" {
  enabled             = true
  default_root_object = "index.html"
  is_ipv6_enabled     = true
  web_acl_id          = aws_wafv2_web_acl.this.arn

  origin {
    domain_name              = aws_s3_bucket.target.bucket_regional_domain_name
    origin_id                = "S3-${aws_s3_bucket.target.id}"
    origin_access_control_id = aws_cloudfront_origin_access_control.target.id
  }

  logging_config {
    bucket = aws_s3_bucket.cf_logs.bucket_domain_name
    prefix = "cf/"
  }

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD", "OPTIONS"]
    target_origin_id = "S3-${aws_s3_bucket.target.id}"

    forwarded_values {
      query_string = false
      cookies { forward = "none" }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }

  price_class = "PriceClass_100"

  restrictions {
    geo_restriction { restriction_type = "none" }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  tags = local.tags
}

# ----------------------------------------------------------------------
# IAM Roles and Policies
# ----------------------------------------------------------------------
resource "aws_iam_role" "codebuild" {
  name = "benchmark-cicd-codebuild-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "codebuild.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
  tags = local.tags
}

resource "aws_iam_role_policy" "codebuild" {
  name = "benchmark-cicd-codebuild-policy"
  role = aws_iam_role.codebuild.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Logs"
        Effect = "Allow"
        Action = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = "arn:aws:logs:${local.region}:${local.account_id}:log-group:/aws/codebuild/*"
      },
      {
        Sid    = "S3Access"
        Effect = "Allow"
        Action = ["s3:GetObject", "s3:PutObject", "s3:GetBucketAcl", "s3:GetBucketLocation"]
        Resource = [
          aws_s3_bucket.target.arn, "${aws_s3_bucket.target.arn}/*",
          aws_s3_bucket.artifact.arn, "${aws_s3_bucket.artifact.arn}/*"
        ]
      },
      {
        Sid    = "KMSAccess"
        Effect = "Allow"
        Action = ["kms:Decrypt", "kms:GenerateDataKey*", "kms:Encrypt"]
        Resource = aws_kms_key.this.arn
      },
      {
        Sid    = "CloudFrontInvalidations"
        Effect = "Allow"
        Action = ["cloudfront:CreateInvalidation"]
        Resource = aws_cloudfront_distribution.this.arn
      },
      {
        Sid    = "SSMReadParameters"
        Effect = "Allow"
        Action = ["ssm:GetParameter", "ssm:GetParameters"]
        Resource = [
          aws_ssm_parameter.github_token.arn,
          aws_ssm_parameter.github_webhook_secret.arn
        ]
      }
    ]
  })
}

resource "aws_iam_role" "codepipeline" {
  name = "benchmark-cicd-codepipeline-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "codepipeline.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
  tags = local.tags
}

resource "aws_iam_role_policy" "codepipeline" {
  name = "benchmark-cicd-codepipeline-policy"
  role = aws_iam_role.codepipeline.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ArtifactStore"
        Effect = "Allow"
        Action = ["s3:GetObject", "s3:PutObject", "s3:ListBucket", "s3:GetBucketAcl", "s3:GetBucketLocation"]
        Resource = [aws_s3_bucket.artifact.arn, "${aws_s3_bucket.artifact.arn}/*"]
      },
      {
        Sid    = "KMSAccess"
        Effect = "Allow"
        Action = ["kms:Decrypt", "kms:GenerateDataKey*", "kms:Encrypt"]
        Resource = aws_kms_key.this.arn
      },
      {
        Sid    = "CodeBuildStart"
        Effect = "Allow"
        Action = ["codebuild:StartBuild", "codebuild:BatchGetBuilds"]
        Resource = aws_codebuild_project.this.arn
      },
      {
        Sid    = "PassRole"
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = aws_iam_role.codebuild.arn
        Condition = { StringEquals = { "iam:PassedToService" = "codebuild.amazonaws.com" } }
      },
      {
        Sid    = "SSMReadParameters"
        Effect = "Allow"
        Action = ["ssm:GetParameter", "ssm:GetParameters"]
        Resource = [aws_ssm_parameter.github_token.arn, aws_ssm_parameter.github_webhook_secret.arn]
      },
      {
        Sid    = "CodeStarConnectionAccess"
        Effect = "Allow"
        Action = "codestar-connections:UseConnection"
        Resource = var.codestar_connection_arn != "" ? var.codestar_connection_arn : "arn:aws:codestar-connections:*:*:connection/*"
      }
    ]
  })
}

# ----------------------------------------------------------------------
# SSM Parameters
# ----------------------------------------------------------------------
resource "aws_ssm_parameter" "github_token" {
  name        = "/codebuild/github-token"
  type        = "SecureString"
  value       = "placeholder"
  description = "GitHub OAuth token for CodePipeline source"
  tags        = local.tags
}

resource "aws_ssm_parameter" "github_webhook_secret" {
  name        = "/codebuild/github-webhook-secret"
  type        = "SecureString"
  value       = "placeholder"
  description = "Webhook secret for GitHub webhook HMAC authentication"
  tags        = local.tags
}

# ----------------------------------------------------------------------
# CodeBuild Project
# ----------------------------------------------------------------------
resource "aws_codebuild_project" "this" {
  name          = "benchmark-cicd-build"
  description   = "Build project for static website"
  build_timeout = 5
  service_role  = aws_iam_role.codebuild.arn

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    compute_type    = "BUILD_GENERAL1_SMALL"
    image           = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type            = "LINUX_CONTAINER"
    privileged_mode = false

    environment_variable {
      name  = "TARGET_BUCKET"
      value = aws_s3_bucket.target.id
    }

    environment_variable {
      name  = "CLOUDFRONT_DISTRIBUTION_ID"
      value = aws_cloudfront_distribution.this.id
    }

    environment_variable {
      name  = "INVALIDATION_FLAG"
      value = "true"
    }
  }

  source {
    type      = "CODEPIPELINE"
    buildspec = ""
  }

  logs_config {
    cloudwatch_logs {
      group_name  = "/aws/codebuild/benchmark-cicd-build"
      stream_name = "build-log"
    }
  }

  tags = local.tags
}

# ----------------------------------------------------------------------
# CodePipeline
# ----------------------------------------------------------------------
resource "aws_codepipeline" "this" {
  name     = "benchmark-cicd-pipeline"
  role_arn = aws_iam_role.codepipeline.arn

  artifact_store {
    location = aws_s3_bucket.artifact.id
    type     = "S3"

    encryption_key {
      id   = aws_kms_key.this.arn
      type = "KMS"
    }
  }

  stage {
    name = "Source"

    dynamic "action" {
      for_each = var.codestar_connection_arn != "" ? [1] : []
      content {
        name             = "Source"
        category         = "Source"
        owner            = "AWS"
        provider         = "CodeStarSourceConnection"
        version          = "1"
        output_artifacts = ["source_output"]
        configuration = {
          ConnectionArn    = var.codestar_connection_arn
          FullRepositoryId = "${var.github_owner}/${var.github_repo}"
          BranchName       = var.github_branch
        }
      }
    }

    dynamic "action" {
      for_each = var.codestar_connection_arn == "" ? [1] : []
      content {
        name             = "Source"
        category         = "Source"
        owner            = "ThirdParty"
        provider         = "GitHub"
        version          = "1"
        output_artifacts = ["source_output"]
        configuration = {
          Owner                = var.github_owner
          Repo                 = var.github_repo
          Branch               = var.github_branch
          OAuthToken           = aws_ssm_parameter.github_token.name
          PollForSourceChanges = "false"
        }
      }
    }
  }

  stage {
    name = "Build"
    action {
      name             = "Build"
      category         = "Build"
      owner            = "AWS"
      provider         = "CodeBuild"
      version          = "1"
      input_artifacts  = ["source_output"]
      output_artifacts = ["build_output"]
      configuration = {
        ProjectName = aws_codebuild_project.this.name
      }
    }
  }

  tags = local.tags
}

# ----------------------------------------------------------------------
# GitHub Webhook (only when not using CodeStar connection)
# ----------------------------------------------------------------------
resource "aws_codepipeline_webhook" "this" {
  count = var.codestar_connection_arn == "" ? 1 : 0

  name            = "benchmark-cicd-webhook"
  authentication  = "GITHUB_HMAC"
  target_action   = "Source"
  target_pipeline = aws_codepipeline.this.name

  authentication_configuration {
    secret_token = aws_ssm_parameter.github_webhook_secret.value
  }

  filter {
    json_path    = "$.ref"
    match_equals = "refs/heads/${var.github_branch}"
  }

  tags = local.tags
}

# ----------------------------------------------------------------------
# Pipeline Notifications (optional)
# ----------------------------------------------------------------------
resource "aws_sns_topic" "pipeline_notifications" {
  count = var.enable_pipeline_notifications ? 1 : 0
  name  = "benchmark-cicd-pipeline-notifications"
  tags  = local.tags
}

resource "aws_sns_topic_policy" "pipeline_notifications" {
  count = var.enable_pipeline_notifications ? 1 : 0
  arn   = aws_sns_topic.pipeline_notifications[0].arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid    = "AllowCodePipelinePublish"
      Effect = "Allow"
      Principal = { Service = "codepipeline.amazonaws.com" }
      Action   = "SNS:Publish"
      Resource = aws_sns_topic.pipeline_notifications[0].arn
    }]
  })
}

resource "aws_codestarnotifications_notification_rule" "this" {
  count = var.enable_pipeline_notifications ? 1 : 0

  name        = "benchmark-cicd-pipeline-notification-rule"
  detail_type = "FULL"
  event_type_ids = [
    "codepipeline-pipeline-pipeline-execution-failed",
    "codepipeline-pipeline-pipeline-execution-succeeded",
    "codepipeline-pipeline-pipeline-execution-canceled",
    "codepipeline-pipeline-pipeline-execution-started"
  ]
  resource = aws_codepipeline.this.arn

  target {
    address = aws_sns_topic.pipeline_notifications[0].arn
    type    = "SNS"
  }

  tags = local.tags
}

# ----------------------------------------------------------------------
# Variables
# ----------------------------------------------------------------------

# Must be set to the actual GitHub owner (user or organization) before apply.
variable "github_owner" {
  description = "GitHub owner (user or organization) for the repository"
  type        = string
  default     = "placeholder-owner"
}

# Must be set to the actual GitHub repository name before apply.
variable "github_repo" {
  description = "GitHub repository name"
  type        = string
  default     = "placeholder-repo"
}

variable "github_branch" {
  description = "GitHub branch to monitor"
  type        = string
  default     = "master"
}

variable "codestar_connection_arn" {
  description = "ARN of CodeStar connection (if using, leave empty to use GitHub OAuth)"
  type        = string
  default     = ""
}

variable "enable_pipeline_notifications" {
  description = "Enable pipeline notifications via SNS topic"
  type        = bool
  default     = false
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "main"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = false
}

variable "subnet_definitions" {
  description = "List of subnet group definitions. Each entry defines a group of subnets (one per AZ)."
  type = list(object({
    name                   = string
    type                   = string # "public", "private", or "intra"
    database_subnet_group  = optional(bool, false)
    elasticache_subnet_group = optional(bool, false)
  }))
  default = []
}

variable "create_resources" {
  description = "Toggle to create all resources in this module"
  type        = bool
  default     = true
}

variable "nat_gateway_per_az" {
  description = "If true, create a NAT Gateway per AZ; otherwise a single NAT Gateway"
  type        = bool
  default     = false
}

variable "flow_log_retention_days" {
  description = "Retention period in days for VPC Flow Logs CloudWatch Log Group"
  type        = number
  default     = 14
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# Locals
locals {
  az_names = data.aws_availability_zones.available.names
  az_count = length(local.az_names)

  # Determine if any subnets of each type exist
  has_public  = length([for s in var.subnet_definitions : s if s.type == "public"]) > 0
  has_private = length([for s in var.subnet_definitions : s if s.type == "private"]) > 0
  has_intra   = length([for s in var.subnet_definitions : s if s.type == "intra"]) > 0

  # Number of subnet groups * AZs
  total_subnets = length(var.subnet_definitions) * local.az_count
  # Newbits needed to address all subnets
  newbits = ceil(log(local.total_subnets + 1, 2))

  # Flatten subnet definitions into a list of per‑AZ subnets with assigned CIDR
  subnet_list = flatten([
    for s_idx, s in var.subnet_definitions : [
      for az_idx, az in local.az_names : {
        key                      = "${s.name}-${az}"
        name                     = s.name
        type                     = s.type
        availability_zone        = az
        cidr_block               = cidrsubnet(var.vpc_cidr, local.newbits, s_idx * local.az_count + az_idx)
        database_subnet_group    = s.database_subnet_group
        elasticache_subnet_group = s.elasticache_subnet_group
      }
    ]
  ])

  # Group subnets by type for route table association
  public_subnet_ids  = var.create_resources ? [for s in aws_subnet.this : s.id if s.tags["Type"] == "public"] : []
  private_subnet_ids = var.create_resources ? [for s in aws_subnet.this : s.id if s.tags["Type"] == "private"] : []
  intra_subnet_ids   = var.create_resources ? [for s in aws_subnet.this : s.id if s.tags["Type"] == "intra"] : []

  # Map subnet ID -> availability zone (for private route table association)
  subnet_az_map = var.create_resources ? { for s in aws_subnet.this : s.id => s.availability_zone } : {}

  # Map of public subnet ID per availability zone (for NAT gateway placement)
  public_subnet_per_az = var.create_resources && local.has_public ? {
    for s in aws_subnet.this : s.availability_zone => s.id if s.tags["Type"] == "public"
  } : {}

  # Keys for NAT Gateways and private route tables
  nat_gateway_keys = var.create_resources && local.has_private ? (
    var.nat_gateway_per_az ? toset(local.az_names) : toset(["single"])
  ) : toset([])

  # For DB/ElastiCache subnet groups: collect subnet IDs by definition name
  db_subnet_groups = {
    for s in var.subnet_definitions : s.name => s if s.database_subnet_group
  }
  elasticache_subnet_groups = {
    for s in var.subnet_definitions : s.name => s if s.elasticache_subnet_group
  }
}

# VPC
resource "aws_vpc" "main" {
  count = var.create_resources ? 1 : 0

  cidr_block           = var.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = var.enable_dns_support
  enable_dns_hostnames = var.enable_dns_hostnames
  assign_generated_ipv6_cidr_block = false

  tags = {
    Name = var.vpc_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Subnets
resource "aws_subnet" "this" {
  for_each = var.create_resources ? { for s in local.subnet_list : s.key => s } : {}

  vpc_id                  = aws_vpc.main[0].id
  cidr_block              = each.value.cidr_block
  availability_zone       = each.value.availability_zone
  map_public_ip_on_launch = each.value.type == "public" ? true : false

  tags = {
    Name = "${var.vpc_name}-${each.value.name}-${each.value.type}-${each.value.availability_zone}"
    Type = each.value.type
  }
}

# Internet Gateway
resource "aws_internet_gateway" "this" {
  count = var.create_resources && local.has_public ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

# Elastic IPs for NAT Gateways
resource "aws_eip" "nat" {
  for_each = local.nat_gateway_keys

  domain = "vpc"

  tags = {
    Name = "${var.vpc_name}-nat-eip-${each.key}"
  }
}

# NAT Gateways
resource "aws_nat_gateway" "this" {
  for_each = local.nat_gateway_keys

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = each.key == "single" ? local.public_subnet_ids[0] : local.public_subnet_per_az[each.key]

  tags = {
    Name = "${var.vpc_name}-nat-${each.key}"
  }

  depends_on = [aws_internet_gateway.this]
}

# Route Tables
resource "aws_route_table" "public" {
  count = var.create_resources && local.has_public ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = {
    Name = "${var.vpc_name}-public"
  }
}

resource "aws_route_table" "private" {
  for_each = local.nat_gateway_keys

  vpc_id = aws_vpc.main[0].id

  tags = {
    Name = var.nat_gateway_per_az ? "${var.vpc_name}-private-${each.key}" : "${var.vpc_name}-private"
  }
}

resource "aws_route_table" "intra" {
  count = var.create_resources && local.has_intra ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = {
    Name = "${var.vpc_name}-intra"
  }
}

# Routes
resource "aws_route" "public_internet" {
  count = var.create_resources && local.has_public ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route" "private_nat" {
  for_each = local.nat_gateway_keys

  route_table_id         = aws_route_table.private[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[each.key].id
}

# Route Table Associations
resource "aws_route_table_association" "public" {
  count = var.create_resources && local.has_public ? length(local.public_subnet_ids) : 0

  subnet_id      = local.public_subnet_ids[count.index]
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table_association" "private" {
  for_each = toset(local.private_subnet_ids)

  subnet_id      = each.key
  route_table_id = aws_route_table.private[
    var.nat_gateway_per_az ? local.subnet_az_map[each.key] : "single"
  ].id
}

resource "aws_route_table_association" "intra" {
  count = var.create_resources && local.has_intra ? length(local.intra_subnet_ids) : 0

  subnet_id      = local.intra_subnet_ids[count.index]
  route_table_id = aws_route_table.intra[0].id
}

# Database Subnet Groups
resource "aws_db_subnet_group" "this" {
  for_each = var.create_resources ? local.db_subnet_groups : {}

  name       = "${var.vpc_name}-${each.key}-db"
  subnet_ids = [for s in aws_subnet.this : s.id if s.tags["Name"] == each.key && s.tags["Type"] == "private"]

  tags = {
    Name = "${var.vpc_name}-${each.key}-db"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ElastiCache Subnet Groups
resource "aws_elasticache_subnet_group" "this" {
  for_each = var.create_resources ? local.elasticache_subnet_groups : {}

  name       = "${var.vpc_name}-${each.key}-elasticache"
  subnet_ids = [for s in aws_subnet.this : s.id if s.tags["Name"] == each.key && s.tags["Type"] == "private"]

  tags = {
    Name = "${var.vpc_name}-${each.key}-elasticache"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# VPC Flow Logs
resource "aws_kms_key" "flow_logs" {
  count = var.create_resources ? 1 : 0

  description             = "KMS key for VPC Flow Logs CloudWatch Log Group encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs Service"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/vpc/flow-logs/${var.vpc_name}"
          }
        }
      }
    ]
  })

  tags = {
    Name = "${var.vpc_name}-flow-logs-key"
  }
}

resource "aws_kms_alias" "flow_logs" {
  count = var.create_resources ? 1 : 0

  name_prefix = "alias/${var.vpc_name}-flow-logs-"
  target_key_id = aws_kms_key.flow_logs[0].key_id
}

resource "aws_cloudwatch_log_group" "flow_logs" {
  count = var.create_resources ? 1 : 0

  name              = "/aws/vpc/flow-logs/${var.vpc_name}"
  retention_in_days = var.flow_log_retention_days
  kms_key_id        = aws_kms_alias.flow_logs[0].arn

  tags = {
    Name = "${var.vpc_name}-flow-logs"
  }

  depends_on = [aws_kms_key.flow_logs]
}

resource "aws_iam_role" "flow_logs" {
  count = var.create_resources ? 1 : 0

  name_prefix = "${var.vpc_name}-flow-logs-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${var.vpc_name}-flow-logs-role"
  }
}

resource "aws_iam_policy" "flow_logs" {
  count = var.create_resources ? 1 : 0

  name        = "${var.vpc_name}-flow-logs-policy"
  description = "Policy for VPC Flow Logs to write to CloudWatch Logs and encrypt with KMS"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "${aws_cloudwatch_log_group.flow_logs[0].arn}:*"
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.flow_logs[0].arn
      }
    ]
  })

  tags = {
    Name = "${var.vpc_name}-flow-logs-policy"
  }
}

resource "aws_iam_role_policy_attachment" "flow_logs" {
  count = var.create_resources ? 1 : 0

  role       = aws_iam_role.flow_logs[0].name
  policy_arn = aws_iam_policy.flow_logs[0].arn
}

resource "aws_flow_log" "this" {
  count = var.create_resources ? 1 : 0

  log_destination        = aws_cloudwatch_log_group.flow_logs[0].arn
  log_destination_type   = "cloud-watch-logs"
  traffic_type           = "ALL"
  vpc_id                 = aws_vpc.main[0].id
  iam_role_arn           = aws_iam_role.flow_logs[0].arn

  tags = {
    Name = "${var.vpc_name}-flow-log"
  }

  depends_on = [aws_iam_role_policy_attachment.flow_logs]
}

# Outputs
output "vpc_id" {
  description = "ID of the VPC"
  value       = var.create_resources ? aws_vpc.main[0].id : null
}

output "subnet_ids_by_name" {
  description = "Map of subnet name to list of subnet IDs"
  value = var.create_resources ? {
    for name in distinct([for s in var.subnet_definitions : s.name]) :
    name => [for s in aws_subnet.this : s.id if s.tags["Name"] == name]
  } : {}
}

output "public_subnet_ids" {
  description = "List of public subnet IDs"
  value       = local.public_subnet_ids
}

output "private_subnet_ids" {
  description = "List of private subnet IDs"
  value       = local.private_subnet_ids
}

output "intra_subnet_ids" {
  description = "List of intra subnet IDs"
  value       = local.intra_subnet_ids
}

output "nat_gateway_public_ips" {
  description = "Elastic IPs of the NAT Gateways"
  value       = var.create_resources && local.has_private ? values(aws_eip.nat)[*].public_ip : []
}

output "database_subnet_group_names" {
  description = "Names of created DB subnet groups"
  value = var.create_resources ? {
    for k, v in aws_db_subnet_group.this : k => v.name
  } : {}
}

output "elasticache_subnet_group_names" {
  description = "Names of created ElastiCache subnet groups"
  value = var.create_resources ? {
    for k, v in aws_elasticache_subnet_group.this : k => v.name
  } : {}
}

