variable "queue_name" {
  description = "Name of the SQS dead-letter queue"
  type        = string
  default     = "aggregation-lambda-dead-letter-queue"
}

variable "message_retention_days" {
  description = "Message retention period in days for the SQS queue"
  type        = number
  default     = 14
}

data "aws_caller_identity" "current" {}

locals {
  retention_seconds = var.message_retention_days * 24 * 60 * 60
  kms_key_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow SQS Service to use the key"
        Effect = "Allow"
        Principal = {
          Service = "sqs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_key" "queue_encryption" {
  description             = "KMS key for SQS dead-letter queue encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  rotation_period_in_days = 365
  policy                  = local.kms_key_policy

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sqs_queue" "dead_letter_queue" {
  name                      = var.queue_name
  message_retention_seconds = local.retention_seconds
  kms_master_key_id         = aws_kms_key.queue_encryption.arn

  lifecycle {
    prevent_destroy = true
  }
}

