locals {
  log_group_name = "/aws/ssm/automation/executeScript"
  region         = data.aws_region.current.region
  account_id     = data.aws_caller_identity.current.account_id
}

resource "aws_kms_key" "ssm_automation_logs" {
  count               = var.enable_ssm_logging ? 1 : 0
  description         = "KMS key for CloudWatch Logs encryption of SSM Automation script output"
  enable_key_rotation = true
  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "ssm-automation-logs-key-policy"
    Statement = [
      {
        Sid       = "Enable IAM User Permissions"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "Allow CloudWatch Logs to use the key"
        Effect    = "Allow"
        Principal = {
          Service = "logs.${local.region}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "ssm_automation_logs" {
  count         = var.enable_ssm_logging ? 1 : 0
  name_prefix   = "alias/ssm-automation-logs-"
  target_key_id = aws_kms_key.ssm_automation_logs[0].key_id
}

resource "aws_cloudwatch_log_group" "ssm_automation_logs" {
  count             = var.enable_ssm_logging ? 1 : 0
  name              = local.log_group_name
  retention_in_days = 14
  kms_key_id        = aws_kms_alias.ssm_automation_logs[0].arn
}

resource "aws_ssm_service_setting" "ssm_automation_cloudwatch_logging_enable" {
  count         = var.enable_ssm_logging ? 1 : 0
  depends_on    = [aws_cloudwatch_log_group.ssm_automation_logs]
  setting_id    = "arn:aws:ssm:${local.region}:${local.account_id}:servicesetting/ssm/automation/cloud-watch-logging"
  setting_value = "Enabled"
}

resource "aws_ssm_service_setting" "ssm_automation_cloudwatch_logging_log_group" {
  count         = var.enable_ssm_logging ? 1 : 0
  depends_on    = [aws_cloudwatch_log_group.ssm_automation_logs]
  setting_id    = "arn:aws:ssm:${local.region}:${local.account_id}:servicesetting/ssm/automation/cloud-watch-logging-log-group"
  setting_value = aws_cloudwatch_log_group.ssm_automation_logs[0].arn
}

resource "aws_ssm_service_setting" "ssm_document_public_sharing_disabled" {
  count         = var.enable_ssm_logging ? 1 : 0
  depends_on    = [aws_cloudwatch_log_group.ssm_automation_logs]
  setting_id    = "arn:aws:ssm:${local.region}:${local.account_id}:servicesetting/ssm/documents/public-sharing"
  setting_value = "Disable"
}

