terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

data "tls_certificate" "github" {
  url = "https://token.actions.githubusercontent.com"
}

resource "aws_iam_openid_connect_provider" "github" {
  url             = "https://token.actions.githubusercontent.com"
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = concat(
    data.tls_certificate.github.certificates[*].sha1_fingerprint,
    [
      "6938fd4d98bab03faadb97b34396831e3780aea1",
      "1c58a3a8518e8759bf075b886c6ce2b1b0d9b9f3",
    ],
  )
}

variable "github_roles" {
  description = "Optional GitHub Actions federated IAM roles to create. Keys must be snake_case identifiers."
  type = map(object({
    role_name   = optional(string)
    path        = optional(string, "/")
    description = optional(string)
    policy_arns = optional(list(string), [])
    sub         = string
  }))
  default = {}

  validation {
    condition = alltrue([
      for key, _ in var.github_roles : can(regex("^[a-z][a-z0-9_]*$", key))
    ])
    error_message = "Each github_roles key must be a snake_case identifier."
  }

  validation {
    condition = alltrue([
      for role in var.github_roles : length(role.sub) > 0
    ])
    error_message = "Each GitHub-federated role must specify a non-empty sub condition."
  }
}

resource "aws_iam_role" "github_actions" {
  for_each = var.github_roles

  name        = coalesce(each.value.role_name, each.key)
  path        = coalesce(each.value.path, "/")
  description = coalesce(each.value.description, "GitHub Actions federated role for ${each.key}")

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Action    = "sts:AssumeRoleWithWebIdentity"
        Principal = {
          Federated = aws_iam_openid_connect_provider.github.arn
        }
        Condition = {
          StringEquals = {
            "token.actions.githubusercontent.com:aud" = "sts.amazonaws.com"
          }
          StringLike = {
            "token.actions.githubusercontent.com:sub" = each.value.sub
          }
        }
      }
    ]
  })

  tags = {
    Name = coalesce(each.value.role_name, each.key)
  }
}

resource "aws_iam_role_policy_attachment" "github_actions" {
  for_each = {
    for entry in flatten([
      for role_key, role in var.github_roles : [
        for idx, policy_arn in role.policy_arns : {
          id         = "${role_key}:${idx}"
          role_key   = role_key
          policy_arn = policy_arn
        }
      ]
    ]) : entry.id => entry
  }

  role       = aws_iam_role.github_actions[each.value.role_key].name
  policy_arn = each.value.policy_arn
}

