  })

  tags = {
    Name = "flow-log-kms-key"
  }
}

resource "aws_kms_alias" "flow_log" {
  name          = "alias/flow-log-key"
  target_key_id = aws_kms_key.flow_log.key_id
}

# CloudWatch Log Groups for VPC Flow Logs (encrypted with CMK)
resource "aws_cloudwatch_log_group" "dev_flow_log" {
  name              = "/aws/vpc/flow-logs/dev"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.flow_log.arn

  tags = {
    Name = "dev-flow-log-group"
  }
}

resource "aws_cloudwatch_log_group" "test_flow_log" {
  name              = "/aws/vpc/flow-logs/test"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.flow_log.arn

  tags = {
    Name = "test-flow-log-group"
  }
}

# IAM Role for VPC Flow Logs
resource "aws_iam_role" "flow_log" {
  name = "vpc-flow-logs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "vpc-flow-logs-role"
  }
}

resource "aws_iam_role_policy" "flow_log" {
  name = "vpc-flow-logs-policy"
  role = aws_iam_role.flow_log.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.dev_flow_log.arn,
          aws_cloudwatch_log_group.test_flow_log.arn,
          "${aws_cloudwatch_log_group.dev_flow_log.arn}:*",
          "${aws_cloudwatch_log_group.test_flow_log.arn}:*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = [aws_kms_key.flow_log.arn]
      }
    ]
  })
}

# VPC Flow Logs
resource "aws_flow_log" "dev" {
  vpc_id               = aws_vpc.dev.id
  log_destination      = aws_cloudwatch_log_group.dev_flow_log.arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.flow_log.arn
  traffic_type         = "ALL"

  tags = {
    Name = "dev-flow-log"
  }
}

resource "aws_flow_log" "test" {
  vpc_id               = aws_vpc.test.id
  log_destination      = aws_cloudwatch_log_group.test_flow_log.arn
  log_destination_type = "cloud-watch-logs"
  iam_role_arn         = aws_iam_role.flow_log.arn
  traffic_type         = "ALL"

  tags = {
    Name = "test-flow-log"
  }
}

