terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "cloudhealth_aws_account_id" {
  description = "AWS account ID of the CloudHealth SaaS platform"
  type        = string
  default     = "452793895869"
}

variable "cloudhealth_external_id" {
  description = "External ID used by CloudHealth to assume the IAM role"
  type        = string
  default     = "external-id-placeholder"
}

data "aws_iam_policy_document" "cloudhealth_trust_policy" {
  statement {
    sid    = "AllowCloudHealthAssumeRole"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = ["sts:AssumeRole"]

    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalAccount"
      values   = [var.cloudhealth_aws_account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [var.cloudhealth_external_id]
    }
  }
}

resource "aws_iam_role" "cloudhealth" {
  name               = "CloudHealth-IAM-Role"
  assume_role_policy = data.aws_iam_policy_document.cloudhealth_trust_policy.json
  description        = "Role for CloudHealth to perform read-only cost and usage analysis"
  tags = {
    Purpose = "CloudHealth cross-account read-only access"
  }
}

data "aws_iam_policy_document" "cloudhealth_read_only" {
  statement {
    sid    = "EC2ReadOnly"
    effect = "Allow"
    actions = [
      "ec2:Describe*",
      "ec2:Get*",
      "ec2:List*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "S3ReadOnly"
    effect = "Allow"
    actions = [
      "s3:Get*",
      "s3:List*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "RDSReadOnly"
    effect = "Allow"
    actions = [
      "rds:Describe*",
      "rds:List*",
      "rds:Download*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchReadOnly"
    effect = "Allow"
    actions = [
      "cloudwatch:Describe*",
      "cloudwatch:Get*",
      "cloudwatch:List*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CostExplorerReadOnly"
    effect = "Allow"
    actions = [
      "ce:Describe*",
      "ce:Get*",
      "ce:List*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CURReadOnly"
    effect = "Allow"
    actions = [
      "cur:Describe*",
      "cur:Get*",
      "cur:List*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "OrganizationsReadOnly"
    effect = "Allow"
    actions = [
      "organizations:Describe*",
      "organizations:List*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "TrustedAdvisorReadOnly"
    effect = "Allow"
    actions = [
      "support:Describe*",
      "support:Get*",
      "support:List*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "LambdaReadOnly"
    effect = "Allow"
    actions = [
      "lambda:Get*",
      "lambda:List*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "EBSReadOnly"
    effect = "Allow"
    actions = [
      "ebs:Get*",
      "ebs:List*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "IAMReadOnly"
    effect = "Allow"
    actions = [
      "iam:Get*",
      "iam:List*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "STSBasic"
    effect = "Allow"
    actions = [
      "sts:GetCallerIdentity"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "BudgetsReadOnly"
    effect = "Allow"
    actions = [
      "budgets:ViewBudget",
      "budgets:Describe*",
      "budgets:List*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AccountReadOnly"
    effect = "Allow"
    actions = [
      "account:Get*",
      "account:List*"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "cloudhealth" {
  name        = "CloudHealth-IAM-Role"
  description = "Customer-managed read-only policy for CloudHealth cost and usage analysis"
  policy      = data.aws_iam_policy_document.cloudhealth_read_only.json
}

resource "aws_iam_role_policy_attachment" "cloudhealth" {
  role       = aws_iam_role.cloudhealth.name
  policy_arn = aws_iam_policy.cloudhealth.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

locals {
  github_oidc_url      = "https://token.actions.githubusercontent.com"
  github_oidc_audience = "sts.amazonaws.com"
}

variable "github_repository_patterns" {
  description = "List of GitHub repository subject patterns allowed to assume the role. Empty by default so no repository can assume the role."
  type        = list(string)
  default     = []
}

variable "role_name" {
  description = "Name of the IAM role for GitHub Actions."
  type        = string
  default     = "github-actions-oidc-role"
}

data "tls_certificate" "github" {
  url = local.github_oidc_url
}

resource "aws_iam_openid_connect_provider" "github" {
  url             = local.github_oidc_url
  client_id_list  = [local.github_oidc_audience]
  thumbprint_list = [data.tls_certificate.github.certificates[0].sha1_fingerprint]
}

resource "aws_iam_role" "github_actions" {
  name                = var.role_name
  path                = "/"
  force_detach_policies = true

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.github.arn
        }
        Action    = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "token.actions.githubusercontent.com:aud" = local.github_oidc_audience
          }
          StringLike = {
            "token.actions.githubusercontent.com:sub" = var.github_repository_patterns
          }
        }
      }
    ]
  })
}

output "role_arn" {
  description = "ARN of the GitHub Actions IAM role."
  value       = aws_iam_role.github_actions.arn
}

output "role_name" {
  description = "Name of the GitHub Actions IAM role."
  value       = aws_iam_role.github_actions.name
}

output "role_path" {
  description = "Path of the GitHub Actions IAM role."
  value       = aws_iam_role.github_actions.path
}

output "role_unique_id" {
  description = "Unique ID of the GitHub Actions IAM role."
  value       = aws_iam_role.github_actions.unique_id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_iam_policy_document" "managed_force_mfa_policy" {
  statement {
    sid    = "AllowViewAccountInfo"
    effect = "Allow"
    actions = [
      "iam:GetAccountPasswordPolicy",
      "iam:GetAccountSummary"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowManageOwnPasswords"
    effect = "Allow"
    actions = [
      "iam:ChangePassword"
    ]
    resources = ["arn:aws:iam::*:user/$${aws:username}"]
  }

  statement {
    sid    = "AllowManageOwnVirtualMFADevice"
    effect = "Allow"
    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice"
    ]
    resources = [
      "arn:aws:iam::*:user/$${aws:username}",
      "arn:aws:iam::*:mfa/$${aws:username}"
    ]
  }

  statement {
    sid    = "AllowDeactivateOwnVirtualMFADevice"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice"
    ]
    resources = [
      "arn:aws:iam::*:user/$${aws:username}",
      "arn:aws:iam::*:mfa/$${aws:username}"
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid    = "AllowSelfInspectionWithMFA"
    effect = "Allow"
    actions = [
      "iam:GetUser",
      "iam:ListAccessKeys",
      "iam:ListMFADevices",
      "iam:ListSigningCertificates",
      "iam:ListSSHPublicKeys",
      "iam:ListServiceSpecificCredentials",
      "iam:ListAttachedUserPolicies",
      "iam:ListUserPolicies",
      "iam:ListGroupsForUser",
      "iam:ListUserTags",
      "iam:ListVirtualMFADevices"
    ]
    resources = [
      "arn:aws:iam::*:user/$${aws:username}",
      "*"
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid    = "DenyAllExceptUnconditionalAllowlist"
    effect = "Deny"
    not_actions = [
      "iam:GetAccountPasswordPolicy",
      "iam:GetAccountSummary",
      "iam:ChangePassword",
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice"
    ]
    resources = ["*"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }
}

resource "aws_iam_policy" "managed_force_mfa_policy" {
  name        = "managed-force-mfa-policy"
  path        = "/"
  policy      = data.aws_iam_policy_document.managed_force_mfa_policy.json
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# IAM Users
resource "aws_iam_user" "billing" {
  name = "Billing"
}

resource "aws_iam_user" "admin" {
  name = "Admin"
}

resource "aws_iam_user" "suport" {
  name = "Suport"
}

# IAM Groups
resource "aws_iam_group" "billing_group" {
  name = "BillingGroup"
}

resource "aws_iam_group" "admin_group" {
  name = "AdminGroup"
}

resource "aws_iam_group" "suport_group" {
  name = "SuportGroup"
}

# Custom IAM Policies
resource "aws_iam_policy" "billing_policy" {
  name        = "BillingPolicy"
  description = "Read-only billing, usage, budget, cost report, and pricing visibility"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "aws-portal:ViewBilling",
          "aws-portal:ViewUsage",
          "aws-portal:ViewCostAndUsage",
          "budgets:ViewBudget",
          "ce:Describe*",
          "ce:Get*",
          "cur:Get*",
          "pricing:Describe*",
          "pricing:Get*"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "suport_policy" {
  name        = "SuportPolicy"
  description = "Read-only describe, get, and list access to EC2, S3, CloudWatch, and RDS"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:Describe*",
          "ec2:Get*",
          "s3:Get*",
          "s3:List*",
          "cloudwatch:Describe*",
          "cloudwatch:Get*",
          "cloudwatch:List*",
          "rds:Describe*",
          "rds:ListTagsForResource"
        ]
        Resource = "*"
      }
    ]
  })
}

# MFA enforcement policies for groups
resource "aws_iam_group_policy" "billing_group_mfa" {
  name  = "BillingGroupMFAPolicy"
  group = aws_iam_group.billing_group.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Deny"
        NotAction = [
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:GetUser",
          "iam:ListMFADevices",
          "iam:ListVirtualMFADevices",
          "iam:ResyncMFADevice"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy" "admin_group_mfa" {
  name  = "AdminGroupMFAPolicy"
  group = aws_iam_group.admin_group.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Deny"
        NotAction = [
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:GetUser",
          "iam:ListMFADevices",
          "iam:ListVirtualMFADevices",
          "iam:ResyncMFADevice"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy" "suport_group_mfa" {
  name  = "SuportGroupMFAPolicy"
  group = aws_iam_group.suport_group.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Deny"
        NotAction = [
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:GetUser",
          "iam:ListMFADevices",
          "iam:ListVirtualMFADevices",
          "iam:ResyncMFADevice"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

# Attach policies to groups
resource "aws_iam_group_policy_attachment" "billing_policy_attachment" {
  group      = aws_iam_group.billing_group.name
  policy_arn = aws_iam_policy.billing_policy.arn
}

resource "aws_iam_group_policy_attachment" "admin_policy_attachment" {
  group      = aws_iam_group.admin_group.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

resource "aws_iam_group_policy_attachment" "suport_policy_attachment" {
  group      = aws_iam_group.suport_group.name
  policy_arn = aws_iam_policy.suport_policy.arn
}

# Add users to groups
resource "aws_iam_user_group_membership" "billing" {
  user   = aws_iam_user.billing.name
  groups = [aws_iam_group.billing_group.name]
}

resource "aws_iam_user_group_membership" "admin" {
  user   = aws_iam_user.admin.name
  groups = [aws_iam_group.admin_group.name]
}

resource "aws_iam_user_group_membership" "suport" {
  user   = aws_iam_user.suport.name
  groups = [aws_iam_group.suport_group.name]
}

# Console login profiles with generated passwords
resource "aws_iam_user_login_profile" "billing" {
  user                    = aws_iam_user.billing.name
  password_length         = 8
  password_reset_required = true
}

resource "aws_iam_user_login_profile" "admin" {
  user                    = aws_iam_user.admin.name
  password_length         = 8
  password_reset_required = true
}

resource "aws_iam_user_login_profile" "suport" {
  user                    = aws_iam_user.suport.name
  password_length         = 8
  password_reset_required = true
}

# Outputs
output "billing_username" {
  value = aws_iam_user.billing.name
}

output "billing_password" {
  value     = aws_iam_user_login_profile.billing.password
  sensitive = true
}

output "admin_username" {
  value = aws_iam_user.admin.name
}

output "admin_password" {
  value     = aws_iam_user_login_profile.admin.password
  sensitive = true
}

output "suport_username" {
  value = aws_iam_user.suport.name
}

output "suport_password" {
  value     = aws_iam_user_login_profile.suport.password
  sensitive = true
}

