data "aws_caller_identity" "current" {}

# KMS key for S3 encryption
resource "aws_kms_key" "main" {
  description             = "KMS key for Terraform state and pipeline S3 buckets"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

# Terraform state S3 bucket
resource "aws_s3_bucket" "terraform_state" {
  bucket = "my-terraform-state-bucket-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.main.arn
    }
  }
}

# DynamoDB lock table for Terraform state
resource "aws_dynamodb_table" "terraform_locks" {
  name         = "terraform-locks"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.main.arn
  }

  lifecycle {
    prevent_destroy = true
  }
}

# NLP pipeline S3 bucket (now with unique name)
resource "aws_s3_bucket" "nlp_pipeline" {
  bucket = "nlp-pipeline-bucket-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "nlp_pipeline" {
  bucket = aws_s3_bucket.nlp_pipeline.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "nlp_pipeline" {
  bucket = aws_s3_bucket.nlp_pipeline.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "nlp_pipeline" {
  bucket = aws_s3_bucket.nlp_pipeline.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.main.arn
    }
  }
}

# DynamoDB table for NLP results
resource "aws_dynamodb_table" "nlp_results" {
  name         = "NLPResults"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.main.arn
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Step Functions state machine (placeholder)
resource "aws_sfn_state_machine" "your_state_machine" {
  name     = "YourStateMachineName"
  role_arn = aws_iam_role.step_functions_service.arn

  definition = <<EOF
{
  "Comment": "Placeholder state machine",
  "StartAt": "Pass",
  "States": {
    "Pass": {
      "Type": "Pass",
      "End": true
    }
  }
}
EOF

  lifecycle {
    prevent_destroy = true
  }
}

# IAM role for Glue service
resource "aws_iam_role" "glue_service" {
  name = "glue-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "glue.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "glue_service_managed" {
  role       = aws_iam_role.glue_service.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSGlueServiceRole"
}

resource "aws_iam_policy" "glue_service_s3" {
  name        = "glue-service-s3-policy"
  description = "Inline policy for Glue service role to access nlp-pipeline-bucket"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.nlp_pipeline.arn,
          "${aws_s3_bucket.nlp_pipeline.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "glue_service_s3_attach" {
  role       = aws_iam_role.glue_service.name
  policy_arn = aws_iam_policy.glue_service_s3.arn
}

# IAM role for Comprehend service
resource "aws_iam_role" "comprehend_service" {
  name = "comprehend-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "comprehend.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "comprehend_service_s3" {
  name        = "comprehend-service-s3-policy"
  description = "Inline policy for Comprehend service role to access nlp-pipeline-bucket"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.nlp_pipeline.arn,
          "${aws_s3_bucket.nlp_pipeline.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "comprehend_service_s3_attach" {
  role       = aws_iam_role.comprehend_service.name
  policy_arn = aws_iam_policy.comprehend_service_s3.arn
}

# IAM role for Lambda execution
resource "aws_iam_role" "lambda_execution" {
  name = "lambda-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_execution_managed" {
  role       = aws_iam_role.lambda_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_policy" "lambda_execution_inline" {
  name        = "lambda-execution-inline-policy"
  description = "Inline policy for Lambda execution role"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.nlp_pipeline.arn,
          "${aws_s3_bucket.nlp_pipeline.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "dynamodb:PutItem",
          "dynamodb:UpdateItem"
        ]
        Resource = aws_dynamodb_table.nlp_results.arn
      },
      {
        Effect = "Allow"
        Action = "states:StartExecution"
        Resource = aws_sfn_state_machine.your_state_machine.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_execution_inline_attach" {
  role       = aws_iam_role.lambda_execution.name
  policy_arn = aws_iam_policy.lambda_execution_inline.arn
}

# IAM role for Step Functions service
resource "aws_iam_role" "step_functions_service" {
  name = "step-functions-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "states.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "step_functions_inline" {
  name        = "step-functions-inline-policy"
  description = "Inline policy for Step Functions service role"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "lambda:InvokeFunction"
        Resource = "arn:aws:lambda:*:*:function:*"
      },
      {
        Effect = "Allow"
        Action = "glue:StartJobRun"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "step_functions_inline_attach" {
  role       = aws_iam_role.step_functions_service.name
  policy_arn = aws_iam_policy.step_functions_inline.arn
}

# ====== S3 access logging ======

# Logging bucket (unique name)
resource "aws_s3_bucket" "access_logs" {
  bucket = "my-terraform-access-logs-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

# Versioning on logging bucket
resource "aws_s3_bucket_versioning" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Public access block on logging bucket
resource "aws_s3_bucket_public_access_block" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Bucket policy to allow S3 server access log delivery (replaces ACL)
data "aws_iam_policy_document" "access_logs_delivery" {
  statement {
    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    actions = ["s3:PutObject"]

    resources = ["${aws_s3_bucket.access_logs.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_s3_bucket_policy" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id
  policy = data.aws_iam_policy_document.access_logs_delivery.json
}

# Enable logging on Terraform state bucket
resource "aws_s3_bucket_logging" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  target_bucket = aws_s3_bucket.access_logs.id
  target_prefix = "state-logs/"
}

# Enable logging on NLP pipeline bucket
resource "aws_s3_bucket_logging" "nlp_pipeline" {
  bucket = aws_s3_bucket.nlp_pipeline.id

  target_bucket = aws_s3_bucket.access_logs.id
  target_prefix = "pipeline-logs/"
}

