terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
  }
}

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  bucket_name = "demo-artifact-store-${local.account_id}"
  logs_bucket_name = "demo-artifact-store-logs-${local.account_id}"
  ecr_repo_name = "zenml-kubernetes"
  # Use resource attributes directly in the YAML content
  zenml_stack_yaml = <<-EOT
    version: "0.12.0"
    stacks:
      default:
        artifact_store: s3://${aws_s3_bucket.artifact_store.bucket}
        container_registry: ${aws_ecr_repository.zenml_kubernetes.repository_url}
        secrets_manager: aws
    EOT
}

# KMS key for S3 artifact store SSE-KMS
resource "aws_kms_key" "artifact_store" {
  description             = "KMS key for ZenML artifact store S3 bucket SSE-KMS encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 to use the key for SSE-KMS"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = {
    managedBy   = "terraform"
    application = "demo"
  }
}

resource "aws_kms_alias" "artifact_store" {
  name          = "alias/zenml-artifact-store"
  target_key_id = aws_kms_key.artifact_store.id
}

# KMS key for ECR repository encryption
resource "aws_kms_key" "ecr_kms" {
  description             = "KMS key for ZenML ECR repository encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow ECR to use the key"
        Effect = "Allow"
        Principal = {
          Service = "ecr.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:CreateGrant",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = {
    managedBy   = "terraform"
    application = "demo"
  }
}

resource "aws_kms_alias" "ecr_kms" {
  name          = "alias/zenml-ecr"
  target_key_id = aws_kms_key.ecr_kms.id
}

# S3 bucket for artifact store
resource "aws_s3_bucket" "artifact_store" {
  bucket        = local.bucket_name
  force_destroy = true
  logging {
    target_bucket = aws_s3_bucket.artifact_store_logs.id
    target_prefix = "log/"
  }
  tags = {
    managedBy   = "terraform"
    application = "demo"
  }
}

resource "aws_s3_bucket_ownership_controls" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.artifact_store.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Logging bucket for artifact store
resource "aws_s3_bucket" "artifact_store_logs" {
  bucket        = local.logs_bucket_name
  force_destroy = true
  tags = {
    managedBy   = "terraform"
    application = "demo"
  }
}

resource "aws_s3_bucket_ownership_controls" "artifact_store_logs" {
  bucket = aws_s3_bucket.artifact_store_logs.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "artifact_store_logs" {
  bucket = aws_s3_bucket.artifact_store_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact_store_logs" {
  bucket = aws_s3_bucket.artifact_store_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "artifact_store_logs" {
  bucket = aws_s3_bucket.artifact_store_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

# ACL to grant log delivery write access (recognized by Trivy as log bucket)
resource "aws_s3_bucket_acl" "artifact_store_logs" {
  bucket = aws_s3_bucket.artifact_store_logs.id
  acl    = "log-delivery-write"
}

# ECR repository
resource "aws_ecr_repository" "zenml_kubernetes" {
  name                 = local.ecr_repo_name
  image_tag_mutability = "IMMUTABLE"
  image_scanning_configuration {
    scan_on_push = true
  }
  encryption_configuration {
    encryption_type = "KMS"
    kms_key         = aws_kms_key.ecr_kms.key_id
  }
  tags = {
    managedBy   = "terraform"
    application = "demo"
  }
}

# Local file for ZenML stack YAML
resource "local_file" "zenml_stack" {
  filename = "zenml_stack.yaml"
  content  = local.zenml_stack_yaml
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "prefix" {
  type        = string
  default     = "nim"
  description = "Prefix used for resource names."
}

resource "aws_kms_key" "ecs_task_execution_secrets" {
  description             = "Customer-managed KMS key for ECS task execution secrets"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

resource "aws_iam_role" "ecs_task_execution" {
  name = "${var.prefix}-ecs_task_execution-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution" {
  role       = aws_iam_role.ecs_task_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_secretsmanager_secret" "reposecret" {
  name        = "${var.prefix}-reposecret-"
  kms_key_id  = aws_kms_key.ecs_task_execution_secrets.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "reposecret" {
  secret_id     = aws_secretsmanager_secret.reposecret.arn
  secret_string = jsonencode({
    username = "AWS"
    password = ""
  })
}

resource "aws_iam_role_policy" "ecs_task_access_secrets_policy" {
  name   = "ECSTaskAccessSecretsPolicy"
  role   = aws_iam_role.ecs_task_execution.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "secretsmanager:GetSecretValue"
        Resource = aws_secretsmanager_secret.reposecret.arn
      },
      {
        Effect   = "Allow"
        Action   = "kms:Decrypt"
        Resource = aws_kms_key.ecs_task_execution_secrets.arn
      }
    ]
  })
}

terraform {
  required_version = ">= 1.4"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "organizational_unit_paths" {
  description = "List of slash-delimited organizational unit paths. Each path may be up to 5 levels deep. All ancestor prefixes are created automatically."
  type        = list(string)
  default     = []

  validation {
    condition = alltrue([
      for path in var.organizational_unit_paths :
      can(regex("^[^/]+(/[^/]+)*$", path)) && length(split("/", path)) <= 5
    ])
    error_message = "Each organizational unit path must contain 1 to 5 non-empty segments separated by '/', with no leading or trailing slash."
  }
}

locals {
  ou_prefixes = distinct(flatten([
    for path in var.organizational_unit_paths : [
      for depth in range(1, length(split("/", path)) + 1) :
      join("/", slice(split("/", path), 0, depth))
    ]
  ]))

  ou_parents = {
    for prefix in local.ou_prefixes :
    prefix => try(join("/", slice(split("/", prefix), 0, length(split("/", prefix)) - 1)), "")
  }
}

data "aws_organizations_organization" "org" {}

resource "terraform_data" "main" {}

resource "aws_organizations_organizational_unit" "ou" {
  for_each = local.ou_parents

  name = element(split("/", each.key), length(split("/", each.key)) - 1)

  parent_id = each.value == "" ? data.aws_organizations_organization.org.roots[0].id : aws_organizations_organizational_unit.ou[each.value].id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

resource "aws_vpc" "swe_vpc" {
  cidr_block           = "10.0.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name           = "swe-vpc"
    ResourceGroup  = "default"
  }
}

resource "aws_default_network_acl" "swe_vpc_default_acl" {
  default_network_acl_id = aws_vpc.swe_vpc.default_network_acl_id

  ingress {
    rule_no    = 100
    action     = "allow"
    cidr_block = aws_vpc.swe_vpc.cidr_block
    from_port  = 0
    to_port    = 0
    protocol   = "-1"
  }

  ingress {
    rule_no    = 200
    action     = "deny"
    cidr_block = "0.0.0.0/0"
    from_port  = 22
    to_port    = 22
    protocol   = "tcp"
  }

  ingress {
    rule_no    = 210
    action     = "deny"
    cidr_block = "0.0.0.0/0"
    from_port  = 3389
    to_port    = 3389
    protocol   = "tcp"
  }

  egress {
    rule_no    = 100
    action     = "allow"
    cidr_block = aws_vpc.swe_vpc.cidr_block
    from_port  = 0
    to_port    = 0
    protocol   = "-1"
  }

  tags = {
    Name           = "swe-vpc-default_acl"
    ResourceGroup  = "default"
  }
}

resource "aws_default_security_group" "swe_vpc_default_sg" {
  vpc_id = aws_vpc.swe_vpc.id

  ingress = []
  egress  = []

  tags = {
    Name           = "swe-vpc-default_sg"
    ResourceGroup  = "default"
  }
}

resource "aws_vpc_security_group_ingress_rule" "allow_ping" {
  security_group_id = aws_default_security_group.swe_vpc_default_sg.id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "icmp"
  from_port         = 8
  to_port           = 0
  description       = "Allow ICMP echo request from anywhere"
}

resource "aws_vpc_security_group_ingress_rule" "allow_http" {
  security_group_id = aws_default_security_group.swe_vpc_default_sg.id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80
  description       = "Allow HTTP from anywhere"
}

resource "aws_kms_key" "swe_vpc_flow_logs_kms_key" {
  description             = "KMS key for encrypting VPC flow log CloudWatch Log Group"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name           = "swe-vpc-flow-logs-kms-key"
    ResourceGroup  = "default"
  }
}

resource "aws_kms_alias" "swe_vpc_flow_logs_kms_alias" {
  name          = "alias/swe-vpc-flow-logs"
  target_key_id = aws_kms_key.swe_vpc_flow_logs_kms_key.key_id
}

resource "aws_cloudwatch_log_group" "swe_vpc_flow_logs" {
  name              = "/aws/vpc/swe-vpc-flow-logs"
  kms_key_id        = aws_kms_alias.swe_vpc_flow_logs_kms_alias.arn

  tags = {
    Name           = "swe-vpc-flow-logs"
    ResourceGroup  = "default"
  }
}

resource "aws_iam_role" "swe_vpc_flow_logs_role" {
  name = "swe-vpc-flow-logs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name           = "swe-vpc-flow-logs-role"
    ResourceGroup  = "default"
  }
}

resource "aws_iam_role_policy" "swe_vpc_flow_logs_policy" {
  name = "swe-vpc-flow-logs-policy"
  role = aws_iam_role.swe_vpc_flow_logs_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_flow_log" "swe_vpc_flow_log" {
  vpc_id               = aws_vpc.swe_vpc.id
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.swe_vpc_flow_logs.arn
  iam_role_arn         = aws_iam_role.swe_vpc_flow_logs_role.arn
  traffic_type         = "ALL"

  tags = {
    Name           = "swe-vpc-flow-log"
    ResourceGroup  = "default"
  }
}

