          aws_cloudwatch_log_group.vpc_rec_flow_logs.arn,
          "${aws_cloudwatch_log_group.vpc_dev_flow_logs.arn}:log-stream:*",
          "${aws_cloudwatch_log_group.vpc_rec_flow_logs.arn}:log-stream:*"
        ]
      },
      {
        Action = [
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_flow_log" "vpc_dev_flow_log" {
  vpc_id               = aws_vpc.vpc_dev.id
  log_destination      = aws_cloudwatch_log_group.vpc_dev_flow_logs.arn
  log_destination_type = "cloud-watch-logs"
