terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------
variable "namespace" {
  description = "Namespace (e.g. `eg` or `cp`)"
  type        = string
  default     = "default"
}

variable "environment" {
  description = "Environment (e.g. `dev`, `staging`, `prod`)"
  type        = string
  default     = "dev"
}

variable "stage" {
  description = "Stage (e.g. `build`, `deploy`, `prod`)"
  type        = string
  default     = "dev"
}

variable "name" {
  description = "Solution name (e.g. `guardduty`)"
  type        = string
  default     = "guardduty"
}

variable "attributes" {
  description = "Additional attributes (e.g. `1`)"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags (e.g. map(`BusinessUnit`,`XYZ`)"
  type        = map(string)
  default     = {}
}

variable "enable_guardduty_notifications" {
  description = "Set to true to create SNS topic and EventBridge rule for GuardDuty findings"
  type        = bool
  default     = false
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCES (static provider metadata only)
# ---------------------------------------------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------------------------------------------------
# CLOUD POSSE LABEL MODULE
# ---------------------------------------------------------------------------------------------------------------------
module "label" {
  source     = "cloudposse/label/null"
  version    = "0.25.0"
  namespace  = var.namespace
  environment = var.environment
  stage      = var.stage
  name       = var.name
  attributes = var.attributes
  tags       = var.tags
}

# ---------------------------------------------------------------------------------------------------------------------
# GUARDDUTY DETECTOR
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_guardduty_detector" "this" {
  enable                     = true
  finding_publishing_frequency = "FIFTEEN_MINUTES"
  datasources {
    s3_logs {
      enable = false
    }
  }
  tags = module.label.tags
}

# ---------------------------------------------------------------------------------------------------------------------
# OPTIONAL NOTIFICATIONS (SNS + EventBridge)
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_sns_topic" "guardduty" {
  count             = var.enable_guardduty_notifications ? 1 : 0
  name              = module.label.id
  kms_master_key_id = "alias/aws/sns"
  tags              = module.label.tags

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "sns_topic_policy" {
  count = var.enable_guardduty_notifications ? 1 : 0

  statement {
    sid    = "AllowGuardDutyToPublish"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }
    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.guardduty[0].arn]
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowEventBridgeToPublish"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.guardduty[0].arn]
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_sns_topic_policy" "guardduty" {
  count  = var.enable_guardduty_notifications ? 1 : 0
  arn    = aws_sns_topic.guardduty[0].arn
  policy = data.aws_iam_policy_document.sns_topic_policy[0].json
}

resource "aws_cloudwatch_event_rule" "guardduty" {
  count         = var.enable_guardduty_notifications ? 1 : 0
  name          = "${module.label.id}-guardduty-finding"
  description   = "Capture GuardDuty findings"
  event_pattern = jsonencode({
    source      = ["aws.guardduty"]
    detail-type = ["GuardDuty Finding"]
  })
  tags = module.label.tags
}

resource "aws_cloudwatch_event_target" "guardduty" {
  count     = var.enable_guardduty_notifications ? 1 : 0
  rule      = aws_cloudwatch_event_rule.guardduty[0].name
  arn       = aws_sns_topic.guardduty[0].arn
  target_id = "SendToSNS"
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

data "aws_caller_identity" "current" {}

resource "random_string" "suffix" {
  length  = 6
  lower   = true
  upper   = false
  numeric = true
  special = false
}

locals {
  prefix = "sudo-backup-${random_string.suffix.result}"
}

resource "aws_kms_key" "backup_kms_key" {
  description         = "KMS key for ${local.prefix} backup vault"
  enable_key_rotation = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "Allow root user access"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = ["kms:*"]
        Resource = "*"
      },
      {
        Sid       = "Allow AWS Backup service"
        Effect    = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
          "kms:CreateGrant",
          "kms:RetireGrant"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "backup_kms_alias" {
  name          = "alias/${local.prefix}-kms-key"
  target_key_id = aws_kms_key.backup_kms_key.arn
}

resource "aws_backup_vault" "backup_vault" {
  name        = "${local.prefix}-backup-vault"
  kms_key_arn = aws_kms_key.backup_kms_key.arn
  tags = {
    Name = local.prefix
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_plan" "backup_plan" {
  name = "${local.prefix}-backup-plan"
  rule {
    rule_name           = "${local.prefix}-backup-rule"
    target_vault_name   = aws_backup_vault.backup_vault.name
    schedule            = "cron(0 12 * * ? *)"
    recovery_point_tags = {
      Name = local.prefix
    }
  }
}

resource "aws_iam_role" "backup_role" {
  name = "${local.prefix}-backup-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup_role_policy_attachment" {
  role       = aws_iam_role.backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_backup_selection" "backup_selection" {
  name         = "${local.prefix}-backup-selection"
  plan_id      = aws_backup_plan.backup_plan.id
  iam_role_arn = aws_iam_role.backup_role.arn
  selection_tag {
    type  = "STRINGEQUALS"
    key   = "backup"
    value = "true"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

