terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
}

# GuardDuty Detector
resource "aws_guardduty_detector" "main" {
  enable                       = true
  finding_publishing_frequency = "FIFTEEN_MINUTES"
}

# KMS Key for GuardDuty findings export
resource "aws_kms_key" "guardduty" {
  description             = "KMS key for GuardDuty findings export"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow GuardDuty to generate data keys"
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          ArnLike = {
            "aws:SourceArn" = "arn:aws:guardduty:${local.region}:${local.account_id}:detector/${aws_guardduty_detector.main.id}"
          }
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "guardduty" {
  name          = "alias/guardduty"
  target_key_id = aws_kms_key.guardduty.id
}

# EventBridge Rule for GuardDuty findings
resource "aws_cloudwatch_event_rule" "guardduty_finding_events" {
  name        = "guardduty-finding-events"
  description = "Matches GuardDuty Finding events"
  event_pattern = jsonencode({
    source      = ["aws.guardduty"]
    detail-type = ["GuardDuty Finding"]
  })
}

# Optional S3 export bucket
variable "enable_guardduty_s3_export" {
  description = "Enable exporting GuardDuty findings to an S3 bucket"
  type        = bool
  default     = false
}

resource "aws_s3_bucket" "guardduty_findings" {
  count  = var.enable_guardduty_s3_export ? 1 : 0
  bucket = "guardduty-findings-${local.account_id}-${local.region}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "guardduty_findings" {
  count  = var.enable_guardduty_s3_export ? 1 : 0
  bucket = aws_s3_bucket.guardduty_findings[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "guardduty_findings" {
  count  = var.enable_guardduty_s3_export ? 1 : 0
  bucket = aws_s3_bucket.guardduty_findings[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.guardduty.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "guardduty_findings" {
  count  = var.enable_guardduty_s3_export ? 1 : 0
  bucket = aws_s3_bucket.guardduty_findings[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "guardduty_findings" {
  count  = var.enable_guardduty_s3_export ? 1 : 0
  bucket = aws_s3_bucket.guardduty_findings[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Allow GuardDuty to put objects"
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action = [
          "s3:PutObject"
        ]
        Resource = "${aws_s3_bucket.guardduty_findings[0].arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          ArnLike = {
            "aws:SourceArn" = "arn:aws:guardduty:${local.region}:${local.account_id}:detector/${aws_guardduty_detector.main.id}"
          }
        }
      },
      {
        Sid    = "Allow GuardDuty to get bucket location"
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action = [
          "s3:GetBucketLocation"
        ]
        Resource = aws_s3_bucket.guardduty_findings[0].arn
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          ArnLike = {
            "aws:SourceArn" = "arn:aws:guardduty:${local.region}:${local.account_id}:detector/${aws_guardduty_detector.main.id}"
          }
        }
      }
    ]
  })
}

resource "aws_guardduty_publishing_destination" "s3" {
  count            = var.enable_guardduty_s3_export ? 1 : 0
  detector_id      = aws_guardduty_detector.main.id
  destination_arn  = aws_s3_bucket.guardduty_findings[0].arn
  kms_key_arn      = aws_kms_key.guardduty.arn
  destination_type = "S3"
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

resource "aws_kms_key" "this" {
  description             = "S3 bucket encryption key"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

resource "aws_s3_bucket" "this" {
  bucket_prefix = "private-bucket-"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = "Enabled"
    mfa_delete = "Disabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "this" {
  bucket = aws_s3_bucket.this.id
  acl    = "private"

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket" "log_bucket" {
  bucket_prefix = "access-logs-"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id

  versioning_configuration {
    status     = "Enabled"
    mfa_delete = "Disabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id
  acl    = "log-delivery-write"

  depends_on = [aws_s3_bucket_ownership_controls.log_bucket]
}

resource "aws_s3_bucket_logging" "this" {
  bucket = aws_s3_bucket.this.id

  target_bucket = aws_s3_bucket.log_bucket.id
  target_prefix = "logs/"

  depends_on = [aws_s3_bucket_acl.log_bucket]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

# IAM role for full billing access
resource "aws_iam_role" "billing_full_access" {
  name = "billing-full-access"
  path = "/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

# IAM role for billing view access
resource "aws_iam_role" "billing_view_access" {
  name = "billing-view-access"
  path = "/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

# Customer managed policy for full billing access
data "aws_iam_policy_document" "billing_full_access" {
  statement {
    effect = "Allow"
    actions = [
      "aws-portal:*",
      "budgets:*",
      "payments:*",
      "aws-account-management:*"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "billing_full_access" {
  name        = "billing-full-access"
  path        = "/"
  description = "Full access to billing, usage, payment methods, and budgets"
  policy      = data.aws_iam_policy_document.billing_full_access.json
}

resource "aws_iam_role_policy_attachment" "billing_full_access" {
  role       = aws_iam_role.billing_full_access.name
  policy_arn = aws_iam_policy.billing_full_access.arn
}

# Customer managed policy for view billing access
data "aws_iam_policy_document" "billing_view_access" {
  statement {
    effect = "Allow"
    actions = [
      "aws-portal:View*",
      "aws-portal:Get*",
      "budgets:ViewBudget",
      "budgets:Describe*",
      "payments:View*",
      "payments:Get*",
      "aws-account-management:View*",
      "aws-account-management:Get*",
      "aws-account-management:List*"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "billing_view_access" {
  name        = "billing-view-access"
  path        = "/"
  description = "Read-only access to billing, usage, account, payment methods, and budgets"
  policy      = data.aws_iam_policy_document.billing_view_access.json
}

resource "aws_iam_role_policy_attachment" "billing_view_access" {
  role       = aws_iam_role.billing_view_access.name
  policy_arn = aws_iam_policy.billing_view_access.arn
}

# IAM groups
resource "aws_iam_group" "billing_full_access" {
  name = "billing-full-access"
  path = "/"
}

resource "aws_iam_group" "billing_view_access" {
  name = "billing-view-access"
  path = "/"
}

# Policies for group assume role with MFA enforcement
data "aws_iam_policy_document" "billing_full_access_assume_role" {
  statement {
    effect = "Allow"
    actions = ["sts:AssumeRole"]
    resources = [aws_iam_role.billing_full_access.arn]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "billing_full_access_assume_role" {
  name        = "billing-full-access-assume-role"
  path        = "/"
  description = "Allows members to assume the billing-full-access role with MFA"
  policy      = data.aws_iam_policy_document.billing_full_access_assume_role.json
}

resource "aws_iam_group_policy_attachment" "billing_full_access_assume_role" {
  group      = aws_iam_group.billing_full_access.name
  policy_arn = aws_iam_policy.billing_full_access_assume_role.arn
}

data "aws_iam_policy_document" "billing_view_access_assume_role" {
  statement {
    effect = "Allow"
    actions = ["sts:AssumeRole"]
    resources = [aws_iam_role.billing_view_access.arn]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "billing_view_access_assume_role" {
  name        = "billing-view-access-assume-role"
  path        = "/"
  description = "Allows members to assume the billing-view-access role with MFA"
  policy      = data.aws_iam_policy_document.billing_view_access_assume_role.json
}

resource "aws_iam_group_policy_attachment" "billing_view_access_assume_role" {
  group      = aws_iam_group.billing_view_access.name
  policy_arn = aws_iam_policy.billing_view_access_assume_role.arn
}

# Outputs
output "billing_full_access_role_arn" {
  value = aws_iam_role.billing_full_access.arn
}

output "billing_view_access_role_arn" {
  value = aws_iam_role.billing_view_access.arn
}

output "billing_full_access_group_arn" {
  value = aws_iam_group.billing_full_access.arn
}

output "billing_view_access_group_arn" {
  value = aws_iam_group.billing_view_access.arn
}

# main.tf

resource "random_pet" "cognito" {
  prefix = "cognito"
  length = 2
}

resource "random_string" "external_id" {
  length  = 16
  upper   = true
  lower   = false
  special = false
  numeric = false
}

locals {
  base_pet_name     = random_pet.cognito.id
  user_pool_name    = replace(local.base_pet_name, "-", "_")
  identity_pool_name = local.base_pet_name
  user_pool_client_name = local.user_pool_name
}

# Data sources for current partition, region, and account
data "aws_partition" "current" {}
data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

# User Pool
resource "aws_cognito_user_pool" "main" {
  name = local.user_pool_name

  mfa_configuration = "OFF"

  auto_verified_attributes = ["email"]

  schema {
    name                = "email"
    attribute_data_type = "String"
    required            = true
    mutable             = false
  }

  schema {
    name                = "phone_number"
    attribute_data_type = "String"
    required            = false
    mutable             = false
  }

  schema {
    name                = "profile_user_id"
    attribute_data_type = "String"
    required            = false
    mutable             = true
  }

  schema {
    name                = "first_name"
    attribute_data_type = "String"
    required            = false
    mutable             = true
  }

  schema {
    name                = "last_name"
    attribute_data_type = "String"
    required            = false
    mutable             = true
  }

  schema {
    name                = "gender"
    attribute_data_type = "String"
    required            = false
    mutable             = true
  }

  schema {
    name                = "age"
    attribute_data_type = "String"
    required            = false
    mutable             = true
  }

  schema {
    name                = "persona"
    attribute_data_type = "String"
    required            = false
    mutable             = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

# SMS IAM Role and Policy
resource "aws_iam_role" "sms_role" {
  name               = "${local.user_pool_name}-sms-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cognito-idp.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = random_string.external_id.result
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "sms_policy" {
  name        = "${local.user_pool_name}-sms-policy"
  description = "Policy for Cognito to publish SMS via SNS"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sns:Publish"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sms_attachment" {
  role       = aws_iam_role.sms_role.name
  policy_arn = aws_iam_policy.sms_policy.arn
}

# User Pool Client
resource "aws_cognito_user_pool_client" "main" {
  name                = local.user_pool_client_name
  user_pool_id        = aws_cognito_user_pool.main.id
  generate_secret     = false

  lifecycle {
    prevent_destroy = true
  }
}

# Identity Pool
resource "aws_cognito_identity_pool" "main" {
  identity_pool_name               = local.identity_pool_name
  allow_unauthenticated_identities = true

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.main.id
    provider_name           = aws_cognito_user_pool.main.endpoint
    server_side_token_check = false
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Authenticated Role (signed-users)
resource "aws_iam_role" "authenticated" {
  name               = "${local.user_pool_name}-authenticated-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.main.id
            "sts:ExternalId"                     = aws_cognito_identity_pool.main.id
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "authenticated" {
  name        = "${local.user_pool_name}-authenticated-policy"
  description = "Policy for authenticated Cognito identities"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "cognito-identity:*"
        Resource = "arn:${data.aws_partition.current.partition}:cognito-identity:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:identitypool/${aws_cognito_identity_pool.main.id}"
      },
      {
        Effect   = "Allow"
        Action   = "cognito-sync:*"
        Resource = "arn:${data.aws_partition.current.partition}:cognito-identity:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:identitypool/${aws_cognito_identity_pool.main.id}"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "authenticated_attachment" {
  role       = aws_iam_role.authenticated.name
  policy_arn = aws_iam_policy.authenticated.arn
}

# Unauthenticated Role (anonymous-users)
resource "aws_iam_role" "unauthenticated" {
  name               = "${local.user_pool_name}-unauthenticated-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.main.id
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "unauthenticated" {
  name        = "${local.user_pool_name}-unauthenticated-policy"
  description = "Policy for unauthenticated Cognito identities"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "cognito-identity:*"
        Resource = "arn:${data.aws_partition.current.partition}:cognito-identity:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:identitypool/${aws_cognito_identity_pool.main.id}"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "unauthenticated_attachment" {
  role       = aws_iam_role.unauthenticated.name
  policy_arn = aws_iam_policy.unauthenticated.arn
}

# Attach roles to identity pool
resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.main.id

  roles = {
    authenticated   = aws_iam_role.authenticated.arn
    unauthenticated = aws_iam_role.unauthenticated.arn
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "tags" {
  description = "Additional tags for all resources"
  type        = map(string)
  default     = {}
}

locals {
  name_prefix = "${terraform.workspace}-batch"
  common_tags = merge(
    {
      Name = local.name_prefix
    },
    var.tags
  )
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

resource "random_id" "batch" {
  byte_length = 4
  keepers = {
    workspace = terraform.workspace
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "192.168.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    {
      Name = local.name_prefix
    },
    var.tags
  )
}

# Private subnet
resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(
    {
      Name = "${local.name_prefix}-private"
    },
    var.tags
  )
}

# Public subnet
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.10.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(
    {
      Name = "${local.name_prefix}-public"
    },
    var.tags
  )
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    {
      Name = local.name_prefix
    },
    var.tags
  )
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(
    {
      Name = local.name_prefix
    },
    var.tags
  )
}

# NAT Gateway
resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = merge(
    {
      Name = local.name_prefix
    },
    var.tags
  )
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = merge(
    {
      Name = "${local.name_prefix}-public"
    },
    var.tags
  )
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Private route table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = merge(
    {
      Name = "${local.name_prefix}-private"
    },
    var.tags
  )
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

# Security Group for Batch compute environment
resource "aws_security_group" "batch" {
  name        = local.name_prefix
  description = "Security group for Batch compute environment"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
    description = "Allow HTTPS to VPC CIDR"
  }

  tags = merge(
    {
      Name = local.name_prefix
    },
    var.tags
  )
}

# IAM Roles and Policies

# ECS instance role
resource "aws_iam_role" "ecs_instance" {
  name_prefix = "${local.name_prefix}-ecs-instance-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

# Attach AWS-managed ECS for EC2 policy
resource "aws_iam_role_policy_attachment" "ecs_instance_managed" {
  role       = aws_iam_role.ecs_instance.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

# Custom S3 policy for ECS instances
resource "aws_iam_policy" "ecs_s3" {
  name_prefix = "${local.name_prefix}-ecs-s3-policy-"
  description = "Custom S3 policy for ECS instances"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "GeneralS3ReadList"
        Effect = "Allow"
        Action = [
          "s3:ListAllMyBuckets",
          "s3:GetBucketLocation"
        ]
        Resource = "*"
      },
      {
        Sid    = "ResultsBucketReadWriteDelete"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:GetObjectVersion",
          "s3:PutObjectVersion"
        ]
        Resource = [
          aws_s3_bucket.results.arn,
          "${aws_s3_bucket.results.arn}/*"
        ]
      },
      {
        Sid    = "KMSDecryptGenerateDataKey"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = [aws_kms_key.results.arn]
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "ecs_instance_custom" {
  role       = aws_iam_role.ecs_instance.name
  policy_arn = aws_iam_policy.ecs_s3.arn
}

# Instance profile
resource "aws_iam_instance_profile" "ecs" {
  name_prefix = "${local.name_prefix}-ecs-instance-profile-"
  role = aws_iam_role.ecs_instance.name

  tags = local.common_tags
}

# Batch service role
resource "aws_iam_role" "batch_service" {
  name_prefix = "${local.name_prefix}-service-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "batch.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "batch_service_managed" {
  role       = aws_iam_role.batch_service.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBatchServiceRole"
}

# KMS Key
resource "aws_kms_key" "results" {
  description             = "KMS key for S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableIAMUserPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowECSInstanceRole"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.ecs_instance.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:ReEncrypt*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowBatchServiceRole"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.batch_service.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:ReEncrypt*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogs"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowFlowLogsRole"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.flow_logs.arn
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "results" {
  name_prefix = "alias/${local.name_prefix}-"
  target_key_id = aws_kms_key.results.key_id
}

# S3 Bucket for results
resource "aws_s3_bucket" "results" {
  bucket_prefix = "benchmark-batch-results-${data.aws_caller_identity.current.account_id}-"
  force_destroy = false

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "results" {
  bucket = aws_s3_bucket.results.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "results" {
  bucket = aws_s3_bucket.results.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.results.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "results" {
  bucket = aws_s3_bucket.results.id

  versioning_configuration {
    status = "Enabled"
  }
}

# S3 bucket for server access logs
resource "aws_s3_bucket" "logs" {
  bucket_prefix = "benchmark-batch-logs-${data.aws_caller_identity.current.account_id}-"
  force_destroy = false

  tags = merge(
    {
      Name = "${local.name_prefix}-logs"
    },
    var.tags
  )
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket = aws_s3_bucket.logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "logs" {
  bucket = aws_s3_bucket.logs.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "logs" {
  bucket     = aws_s3_bucket.logs.id
  acl        = "log-delivery-write"
  depends_on = [aws_s3_bucket_ownership_controls.logs]
}

resource "aws_s3_bucket_versioning" "logs" {
  bucket = aws_s3_bucket.logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_logging" "results" {
  bucket = aws_s3_bucket.results.id

  target_bucket = aws_s3_bucket.logs.id
  target_prefix = "logs/"
}

# VPC Flow Logs
resource "aws_cloudwatch_log_group" "flow_logs" {
  name_prefix = "/aws/vpc/flow-logs/${local.name_prefix}-"
  retention_in_days = 7
  kms_key_id        = aws_kms_key.results.arn

  tags = local.common_tags
}

resource "aws_iam_role" "flow_logs" {
  name_prefix = "${local.name_prefix}-flow-logs-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "flow_logs" {
  name = "${local.name_prefix}-flow-logs-policy"
  role = aws_iam_role.flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "${aws_cloudwatch_log_group.flow_logs.arn}:*"
      }
    ]
  })
}

resource "aws_flow_log" "vpc" {
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.flow_logs.arn
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.main.id
  iam_role_arn         = aws_iam_role.flow_logs.arn

  tags = local.common_tags
}

# Batch Compute Environment
resource "aws_batch_compute_environment" "batch" {
  compute_environment_name = "${local.name_prefix}-ce-${random_id.batch.hex}"
  type                     = "MANAGED"
  state                    = "ENABLED"

  compute_resources {
    type                = "EC2"
    allocation_strategy = "BEST_FIT"
    instance_role       = aws_iam_instance_profile.ecs.arn
    instance_type       = ["optimal"]
    min_vcpus           = 0
    max_vcpus           = 4
    desired_vcpus       = 0
    security_group_ids  = [aws_security_group.batch.id]
    subnets             = [aws_subnet.private.id]
  }

  service_role = aws_iam_role.batch_service.arn

  tags = local.common_tags
}

# Batch Job Queue
resource "aws_batch_job_queue" "batch" {
  name     = "${local.name_prefix}-queue-${random_id.batch.hex}"
  state    = "ENABLED"
  priority = 1

  compute_environment_order {
    order               = 1
    compute_environment = aws_batch_compute_environment.batch.arn
  }

  tags = local.common_tags
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

import {
  to = aws_iam_group.endpoint_backup_group
  id = "endpoint-backup"
}

import {
  to = aws_iam_user.endpoint_backup
  id = "endpoint-backup"
}

import {
  to = aws_iam_policy.endpoint_backup_bucket_access
  id = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:policy/endpoint-backup-bucket-read-write-access"
}

data "aws_caller_identity" "current" {}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "aws_kms_key" "endpoint_backup_key" {
  description             = "CMK for endpoint-backup S3 bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_s3_bucket" "endpoint_backup" {
  bucket = "endpoint-backup-${data.aws_caller_identity.current.account_id}-${random_id.suffix.hex}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_logging" "endpoint_backup" {
  bucket        = aws_s3_bucket.endpoint_backup.id
  target_bucket = aws_s3_bucket.endpoint_backup_logs.id
  target_prefix = "log/"
}

resource "aws_s3_bucket_public_access_block" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.endpoint_backup_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.endpoint_backup.arn,
          "${aws_s3_bucket.endpoint_backup.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
          StringNotEquals = {
            "aws:PrincipalArn" = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/senatwo"
          }
        }
      },
      {
        Sid       = "DenyTLSBelow12"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.endpoint_backup.arn,
          "${aws_s3_bucket.endpoint_backup.arn}/*"
        ]
        Condition = {
          StringNotEquals = {
            "aws:TLSSupport"  = ["TLSv1.2", "TLSv1.3"]
            "aws:PrincipalArn" = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/senatwo"
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket" "endpoint_backup_logs" {
  bucket = "endpoint-backup-logs-${data.aws_caller_identity.current.account_id}-${random_id.suffix.hex}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "endpoint_backup_logs" {
  bucket = aws_s3_bucket.endpoint_backup_logs.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "endpoint_backup_logs" {
  depends_on = [aws_s3_bucket_ownership_controls.endpoint_backup_logs]

  bucket = aws_s3_bucket.endpoint_backup_logs.id
  acl    = "log-delivery-write"
}

resource "aws_s3_bucket_public_access_block" "endpoint_backup_logs" {
  bucket = aws_s3_bucket.endpoint_backup_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "endpoint_backup_logs" {
  bucket = aws_s3_bucket.endpoint_backup_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "endpoint_backup_logs" {
  bucket = aws_s3_bucket.endpoint_backup_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_group" "endpoint_backup_group" {
  name = "endpoint-backup"
}

resource "aws_iam_user" "endpoint_backup" {
  name = "endpoint-backup"
}

resource "aws_iam_group_membership" "endpoint_backup" {
  name  = "endpoint-backup-group-membership"
  group = aws_iam_group.endpoint_backup_group.name
  users = [aws_iam_user.endpoint_backup.name]
}

resource "aws_iam_policy" "endpoint_backup_bucket_access" {
  name        = "endpoint-backup-bucket-read-write-access"
  description = "Grants read/write/delete/version/retention/restore access to the endpoint-backup S3 bucket and decrypt/data-key access on the CMK"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3BucketAccess"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:ListBucketVersions",
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:DeleteObjectVersion",
          "s3:GetObjectRetention",
          "s3:PutObjectRetention",
          "s3:RestoreObject"
        ]
        Resource = [
          aws_s3_bucket.endpoint_backup.arn,
          "${aws_s3_bucket.endpoint_backup.arn}/*"
        ]
      },
      {
        Sid    = "KMSAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = [aws_kms_key.endpoint_backup_key.arn]
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "endpoint_backup" {
  group      = aws_iam_group.endpoint_backup_group.name
  policy_arn = aws_iam_policy.endpoint_backup_bucket_access.arn
}

resource "aws_iam_group_policy" "mfa_enforcement" {
  group = aws_iam_group.endpoint_backup_group.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "DenyWithoutMFA"
        Effect   = "Deny"
        NotAction = "iam:*"
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "unity_uds_distribution_callback_urls" {
  description = "Callback URLs for unity-uds-distribution user pool client"
  type        = list(string)
  default     = ["https://api.example.com/callback"]
}

variable "unity_uds_distribution_logout_urls" {
  description = "Logout URLs for unity-uds-distribution user pool client"
  type        = list(string)
  default     = ["https://api.example.com/logout"]
}

variable "localhost_jupyterhub_callback_urls" {
  description = "Callback URLs for localhost-jupyterhub user pool client"
  type        = list(string)
  default     = ["http://localhost:8080/callback"]
}

variable "localhost_jupyterhub_logout_urls" {
  description = "Logout URLs for localhost-jupyterhub user pool client"
  type        = list(string)
  default     = ["http://localhost:8080/logout"]
}

variable "unity_app_to_app_client_callback_urls" {
  description = "Callback URLs for unity-app-to-app-client user pool client"
  type        = list(string)
  default     = ["https://api.example.com/callback"]
}

