terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables for optional features
variable "enable_transit_gateway_attachment" {
  description = "Enable transit gateway VPC attachment"
  type        = bool
  default     = false
}

variable "transit_gateway_id" {
  description = "ID of an existing transit gateway (required if enable_transit_gateway_attachment is true)"
  type        = string
  default     = null
}

variable "enable_ipv6_egress_routing" {
  description = "Enable IPv6 egress-only internet gateway and routing"
  type        = bool
  default     = false
}

# Data source for availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# VPC
resource "aws_vpc" "vpc_terraform_testing" {
  cidr_block                       = "10.0.0.0/16"
  enable_dns_hostnames             = false
  assign_generated_ipv6_cidr_block = var.enable_ipv6_egress_routing

  tags = {
    Name        = "vpc-terraform-testing"
    app         = "terraform"
    environment = "testing"
  }
}

# Public subnets (map_public_ip_on_launch = false to satisfy security policy)
resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.vpc_terraform_testing.id
  cidr_block              = "10.0.10.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name        = "public-subnet-terraform-testing-a"
    app         = "terraform"
    environment = "testing"
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.vpc_terraform_testing.id
  cidr_block              = "10.0.20.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name        = "public-subnet-terraform-testing-b"
    app         = "terraform"
    environment = "testing"
  }
}

resource "aws_subnet" "public_c" {
  vpc_id                  = aws_vpc.vpc_terraform_testing.id
  cidr_block              = "10.0.30.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = false

  tags = {
    Name        = "public-subnet-terraform-testing-c"
    app         = "terraform"
    environment = "testing"
  }
}

# Private subnets
resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.vpc_terraform_testing.id
  cidr_block              = "10.0.11.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name        = "private-subnet-terraform-testing-a"
    app         = "terraform"
    environment = "testing"
  }
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.vpc_terraform_testing.id
  cidr_block              = "10.0.22.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name        = "private-subnet-terraform-testing-b"
    app         = "terraform"
    environment = "testing"
  }
}

resource "aws_subnet" "private_c" {
  vpc_id                  = aws_vpc.vpc_terraform_testing.id
  cidr_block              = "10.0.33.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = false

  tags = {
    Name        = "private-subnet-terraform-testing-c"
    app         = "terraform"
    environment = "testing"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.vpc_terraform_testing.id

  tags = {
    Name        = "igw-terraform-testing"
    app         = "terraform"
    environment = "testing"
  }
}

# Public Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.vpc_terraform_testing.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name        = "public-rt-terraform-testing"
    app         = "terraform"
    environment = "testing"
  }
}

# Public Route Table Associations
resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_c" {
  subnet_id      = aws_subnet.public_c.id
  route_table_id = aws_route_table.public.id
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name        = "nat-eip-terraform-testing"
    app         = "terraform"
    environment = "testing"
  }
}

# NAT Gateway
resource "aws_nat_gateway" "nat" {
  allocation_id     = aws_eip.nat.id
  subnet_id         = aws_subnet.public_a.id
  connectivity_type = "public"

  tags = {
    Name        = "nat-gw-terraform-testing"
    app         = "terraform"
    environment = "testing"
  }
}

# Private Route Table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.vpc_terraform_testing.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name        = "private-rt-terraform-testing"
    app         = "terraform"
    environment = "testing"
  }
}

# Private Route Table Associations
resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_c" {
  subnet_id      = aws_subnet.private_c.id
  route_table_id = aws_route_table.private.id
}

# DB Subnet Group
resource "aws_db_subnet_group" "db_subnet_terraform_testing" {
  name       = "db-subnet-terraform-testing"
  subnet_ids = [
    aws_subnet.private_a.id,
    aws_subnet.private_b.id,
    aws_subnet.private_c.id
  ]

  tags = {
    Name        = "db-subnet-terraform-testing"
    app         = "terraform"
    environment = "testing"
  }
}

# Optional Transit Gateway Attachment
resource "aws_ec2_transit_gateway_vpc_attachment" "tgw_attachment" {
  count = var.enable_transit_gateway_attachment && var.transit_gateway_id != null ? 1 : 0

  subnet_ids         = [aws_subnet.private_a.id, aws_subnet.private_b.id, aws_subnet.private_c.id]
  transit_gateway_id = var.transit_gateway_id
  vpc_id             = aws_vpc.vpc_terraform_testing.id

  tags = {
    Name        = "tgw-attachment-terraform-testing"
    app         = "terraform"
    environment = "testing"
  }
}

# Optional IPv6 Egress-Only Internet Gateway and Route
resource "aws_egress_only_internet_gateway" "ipv6" {
  count = var.enable_ipv6_egress_routing ? 1 : 0

  vpc_id = aws_vpc.vpc_terraform_testing.id

  tags = {
    Name        = "egress-only-igw-terraform-testing"
    app         = "terraform"
    environment = "testing"
  }
}

resource "aws_route" "ipv6_egress" {
  count = var.enable_ipv6_egress_routing ? 1 : 0

  route_table_id              = aws_route_table.private.id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.ipv6[0].id
}

# VPC Flow Logs (fix AWS-0178, AWS-0017, and deployability issues)
resource "aws_kms_key" "vpc_flow_log" {
  description             = "KMS key for VPC flow log encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 10

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = {
    Name        = "vpc-flow-log-kms-key-terraform-testing"
    app         = "terraform"
    environment = "testing"
  }
}

data "aws_caller_identity" "current" {}

resource "aws_kms_alias" "vpc_flow_log" {
  name          = "alias/vpc-flow-log-terraform-testing"
  target_key_id = aws_kms_key.vpc_flow_log.key_id
}

resource "aws_cloudwatch_log_group" "vpc_flow_log" {
  name              = "/aws/vpc-flow-logs/vpc-terraform-testing"
  retention_in_days = 14
  kms_key_id        = aws_kms_alias.vpc_flow_log.arn

  tags = {
    Name        = "vpc-flow-log-group-terraform-testing"
    app         = "terraform"
    environment = "testing"
  }
}

resource "aws_iam_role" "vpc_flow_log" {
  name = "vpc-flow-log-role-terraform-testing"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name        = "vpc-flow-log-role-terraform-testing"
    app         = "terraform"
    environment = "testing"
  }
}

resource "aws_iam_role_policy" "vpc_flow_log" {
  name = "vpc-flow-log-policy-terraform-testing"
  role = aws_iam_role.vpc_flow_log.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.vpc_flow_log.arn}:*"
      }
    ]
  })
}

resource "aws_flow_log" "vpc_flow_log" {
  log_destination        = aws_cloudwatch_log_group.vpc_flow_log.arn
  log_destination_type   = "cloud-watch-logs"
  iam_role_arn           = aws_iam_role.vpc_flow_log.arn
  traffic_type           = "REJECT"
  vpc_id                 = aws_vpc.vpc_terraform_testing.id

  tags = {
    Name        = "vpc-flow-log-terraform-testing"
    app         = "terraform"
    environment = "testing"
  }
}

# Outputs
output "vpc_id" {
  description = "ID of the created VPC"
  value       = aws_vpc.vpc_terraform_testing.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value = [
    aws_subnet.public_a.id,
    aws_subnet.public_b.id,
    aws_subnet.public_c.id
  ]
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value = [
    aws_subnet.private_a.id,
    aws_subnet.private_b.id,
    aws_subnet.private_c.id
  ]
}

output "default_security_group_id" {
  description = "ID of the VPC's default security group"
  value       = aws_vpc.vpc_terraform_testing.default_security_group_id
}

output "nat_gateway_id" {
  description = "ID of the NAT Gateway"
  value       = aws_nat_gateway.nat.id
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
  }
}

resource "random_string" "suffix" {
  length  = 5
  special = false
  upper   = true
  lower   = true
  numeric = true
}

resource "tls_private_key" "gitops" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

locals {
  repo_names = ["gitops-apps", "gitops-platform", "gitops-addons"]
}

resource "aws_codecommit_repository" "repos" {
  for_each = toset(local.repo_names)

  repository_name = each.key
  default_branch  = "main"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_user" "gitops_bridge" {
  name = "gitops-bridge-gitops"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_user_ssh_key" "gitops" {
  username   = aws_iam_user.gitops_bridge.name
  public_key = tls_private_key.gitops.public_key_openssh
  encoding   = "SSH"
  status     = "Active"
}

data "aws_iam_policy_document" "gitops_bridge" {
  statement {
    actions   = ["codecommit:GitPull", "codecommit:GitPush"]
    resources = values(aws_codecommit_repository.repos)[*].arn
    effect    = "Allow"
  }
}

resource "aws_iam_policy" "gitops_bridge" {
  name   = "gitops-bridge-gitops"
  policy = data.aws_iam_policy_document.gitops_bridge.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_group" "gitops_bridge" {
  name = "gitops-bridge"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_group_policy_attachment" "gitops_bridge" {
  group      = aws_iam_group.gitops_bridge.name
  policy_arn = aws_iam_policy.gitops_bridge.arn
}

resource "aws_iam_group_membership" "gitops_bridge" {
  name  = "gitops-bridge-membership"
  users = [aws_iam_user.gitops_bridge.name]
  group = aws_iam_group.gitops_bridge.name
}

resource "aws_iam_group_policy" "mfa_enforcement" {
  group = aws_iam_group.gitops_bridge.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DenyAllUnlessMFA"
        Effect = "Deny"
        NotAction = "iam:*"
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_kms_key" "secrets" {
  description             = "Customer-managed key for CodeCommit SSH key secret"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_secretsmanager_secret" "codecommit_key" {
  name        = "codecommit-key-${random_string.suffix.result}"
  kms_key_id  = aws_kms_key.secrets.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "codecommit_key" {
  secret_id     = aws_secretsmanager_secret.codecommit_key.id
  secret_string = tls_private_key.gitops.private_key_pem
}

resource "local_file" "private_key" {
  filename        = pathexpand("~/.ssh/gitops_ssh.pem")
  content         = tls_private_key.gitops.private_key_pem
  file_permission = "0600"
}

resource "local_file" "ssh_config" {
  filename = pathexpand("~/.ssh/config")
  content  = <<-EOT
Host git-codecommit.*.amazonaws.com
  IdentityFile ~/.ssh/gitops_ssh.pem
  User gitops-bridge-gitops
EOT
  file_permission = "0644"
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

variable "additional_ebs_volumes" {
  description = "List of additional EBS volumes to attach to the instance (optional)"
  type = list(object({
    device_name = string
    volume_size = number
    volume_type = optional(string, "gp2")
    encrypted   = optional(bool, true)
    delete_on_termination = optional(bool, true)
  }))
  default = []
}

variable "additional_network_interfaces" {
  description = "List of additional network interfaces to create and attach (optional)"
  type = list(object({
    subnet_id         = optional(string)
    security_groups   = optional(list(string), [])
    associate_public_ip = optional(bool, true)
  }))
  default = []
}

data "aws_caller_identity" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "ubuntu" {
  most_recent = true
  owners      = ["099720109477"]

  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-jammy-22.04-amd64-server-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

locals {
  vpc_cidr = "10.70.0.0/16"
  subnet_cidr = "10.70.0.0/24"

  # Pre-filter additional network interfaces that require an Elastic IP
  additional_network_interfaces_with_eip = {
    for idx, ni in var.additional_network_interfaces : idx => ni
    if try(ni.associate_public_ip, true)
  }
}

resource "tls_private_key" "main" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "benchmark-vpc"
  }
}

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "benchmark-subnet"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "benchmark-igw"
  }
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "benchmark-route-table"
  }
}

resource "aws_route_table_association" "main" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.main.id
}

resource "aws_key_pair" "main" {
  key_name   = "benchmark-d8bc612be4e0-key"
  public_key = tls_private_key.main.public_key_openssh
}

resource "aws_security_group" "main" {
  name        = "benchmark-sg"
  description = "Security group for benchmark instance"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow all outbound traffic to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "benchmark-sg"
  }
}

resource "aws_iam_role" "main" {
  name = "benchmark-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_instance_profile" "main" {
  name = "benchmark-instance-profile"
  role = aws_iam_role.main.name
}

resource "aws_instance" "main" {
  ami                         = data.aws_ami.ubuntu.id
  instance_type               = "t2.micro"
  subnet_id                   = aws_subnet.main.id
  associate_public_ip_address = true
  monitoring                  = true
  iam_instance_profile        = aws_iam_instance_profile.main.name
  key_name                    = aws_key_pair.main.key_name

  root_block_device {
    volume_size           = 10
    volume_type           = "gp2"
    encrypted             = true
    delete_on_termination = true
    kms_key_id            = "alias/aws/ebs"
  }

  metadata_options {
    http_tokens   = "required"
    http_endpoint = "enabled"
  }

  tags = {
    Name = "benchmark-instance"
  }
}

resource "aws_eip" "main" {
  domain = "vpc"

  tags = {
    Name = "benchmark-eip"
  }
}

resource "aws_eip_association" "main" {
  instance_id   = aws_instance.main.id
  allocation_id = aws_eip.main.id
}

resource "aws_cloudwatch_metric_alarm" "status_check_failed" {
  alarm_name          = "benchmark-instance-status-check-failed"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 5
  metric_name         = "StatusCheckFailed_Instance"
  namespace           = "AWS/EC2"
  period              = 60
  statistic           = "Maximum"
  threshold           = 1
  alarm_actions       = ["arn:aws:automate:us-east-1:ec2:reboot"]

  dimensions = {
    InstanceId = aws_instance.main.id
  }

  tags = {
    Name = "benchmark-alarm"
  }
}

# VPC Flow Logs
resource "aws_kms_key" "cloudwatch" {
  description         = "KMS key for CloudWatch log group encryption"
  enable_key_rotation = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable CloudWatch Logs"
        Effect = "Allow"
        Principal = {
          Service = "logs.us-east-1.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Enable EC2 EBS"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "cloudwatch" {
  name          = "alias/benchmark-cloudwatch-logs"
  target_key_id = aws_kms_key.cloudwatch.key_id
}

resource "aws_cloudwatch_log_group" "flow_log" {
  name              = "/aws/vpc/benchmark-flow-logs"
  retention_in_days = 7
  kms_key_id        = aws_kms_alias.cloudwatch.arn
}

resource "aws_iam_role" "flow_log" {
  name = "benchmark-vpc-flow-log-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "flow_log" {
  role       = aws_iam_role.flow_log.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchLogsFullAccess"
}

resource "aws_flow_log" "main" {
  log_destination      = aws_cloudwatch_log_group.flow_log.arn
  log_destination_type = "cloud-watch-logs"
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.main.id
  iam_role_arn         = aws_iam_role.flow_log.arn
}

# Optional additional EBS volumes
resource "aws_ebs_volume" "additional" {
  count = length(var.additional_ebs_volumes)

  availability_zone = aws_subnet.main.availability_zone
  size              = var.additional_ebs_volumes[count.index].volume_size
  type              = var.additional_ebs_volumes[count.index].volume_type
  encrypted         = var.additional_ebs_volumes[count.index].encrypted

  tags = {
    Name = "benchmark-ebs-${count.index}"
  }
}

resource "aws_volume_attachment" "additional" {
  count = length(var.additional_ebs_volumes)

  device_name  = var.additional_ebs_volumes[count.index].device_name
  volume_id    = aws_ebs_volume.additional[count.index].id
  instance_id  = aws_instance.main.id
  force_detach = true
}

# Optional additional network interfaces
resource "aws_network_interface" "additional" {
  for_each = { for idx, ni in var.additional_network_interfaces : idx => ni }

  subnet_id       = try(each.value.subnet_id, aws_subnet.main.id)
  security_groups = try(each.value.security_groups, [aws_security_group.main.id])

  tags = {
    Name = "benchmark-eni-${each.key}"
  }
}

resource "aws_eip" "additional" {
  for_each = local.additional_network_interfaces_with_eip

  domain = "vpc"

  tags = {
    Name = "benchmark-eip-additional-${each.key}"
  }
}

resource "aws_eip_association" "additional" {
  for_each = local.additional_network_interfaces_with_eip

  network_interface_id = aws_network_interface.additional[each.key].id
  allocation_id        = aws_eip.additional[each.key].id
}

resource "aws_network_interface_attachment" "additional" {
  for_each = { for idx, ni in var.additional_network_interfaces : idx => ni }

  instance_id          = aws_instance.main.id
  network_interface_id = aws_network_interface.additional[each.key].id
  device_index         = 1 + tonumber(each.key)
}

output "private_key_pem" {
  value     = tls_private_key.main.private_key_pem
  sensitive = true
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
      configuration_aliases = [ aws.secondary, aws.replica1, aws.replica2 ]
    }
  }
}

provider "aws" {
  region = var.primary_region
}

provider "aws" {
  alias  = "secondary"
  region = var.secondary_region
}

provider "aws" {
  alias  = "replica1"
  region = var.replica1_region
}

provider "aws" {
  alias  = "replica2"
  region = var.replica2_region
}

variable "primary_region" {
  description = "Primary source region (default us-east-1)"
  type        = string
  default     = "us-east-1"
}

variable "secondary_region" {
  description = "Second source region"
  type        = string
  default     = "us-west-2"
}

variable "replica1_region" {
  description = "First replica region"
  type        = string
  default     = "eu-west-1"
}

variable "replica2_region" {
  description = "Second replica region"
  type        = string
  default     = "ap-southeast-1"
}

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id

  # Source bucket names in primary region
  src_primary_a = "log1a.veerum-${local.account_id}"
  src_primary_b = "log1b.veerum-${local.account_id}"

  # Source bucket names in secondary region
  src_secondary_a = "log2a.veerum-${local.account_id}"
  src_secondary_b = "log2b.veerum-${local.account_id}"

  # Replica bucket names in replica1 region
  rep1_src1a = "${local.src_primary_a}-replica1-${local.account_id}"
  rep1_src1b = "${local.src_primary_b}-replica1-${local.account_id}"
  rep1_src2a = "${local.src_secondary_a}-replica1-${local.account_id}"
  rep1_src2b = "${local.src_secondary_b}-replica1-${local.account_id}"

  # Replica bucket names in replica2 region
  rep2_src1a = "${local.src_primary_a}-replica2-${local.account_id}"
  rep2_src1b = "${local.src_primary_b}-replica2-${local.account_id}"
  rep2_src2a = "${local.src_secondary_a}-replica2-${local.account_id}"
  rep2_src2b = "${local.src_secondary_b}-replica2-${local.account_id}"

  # KMS key aliases
  sourcekey1_alias  = "alias/sourcekey1"
  sourcekey2_alias  = "alias/sourcekey2"
  replicakey1_alias = "alias/replicakey1"
  replicakey2_alias = "alias/replicakey2"
  loggingkey1_alias = "alias/loggingkey1"
  loggingkey2_alias = "alias/loggingkey2"
  loggingkey3_alias = "alias/loggingkey3"
  loggingkey4_alias = "alias/loggingkey4"

  # Logging bucket names
  logging_primary   = "s3-logging-${var.primary_region}-${local.account_id}"
  logging_secondary = "s3-logging-${var.secondary_region}-${local.account_id}"
  logging_replica1  = "s3-logging-${var.replica1_region}-${local.account_id}"
  logging_replica2  = "s3-logging-${var.replica2_region}-${local.account_id}"
}

# ---------------------------------------------------------------------------
# KMS Keys for Source and Replica
# ---------------------------------------------------------------------------
resource "aws_kms_key" "sourcekey1" {
  provider = aws
  description             = "Source key 1 for primary source region"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 service to decrypt for replication"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action   = "kms:Decrypt"
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = local.account_id
            "kms:ViaService"    = "s3.${var.primary_region}.amazonaws.com"
          }
        }
      },
      {
        Sid    = "Allow replication role to decrypt"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.replication_primary.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "sourcekey1" {
  provider      = aws
  name          = local.sourcekey1_alias
  target_key_id = aws_kms_key.sourcekey1.key_id
}

resource "aws_kms_key" "sourcekey2" {
  provider = aws.secondary
  description             = "Source key 2 for secondary source region"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 service to decrypt for replication"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action   = "kms:Decrypt"
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = local.account_id
            "kms:ViaService"    = "s3.${var.secondary_region}.amazonaws.com"
          }
        }
      },
      {
        Sid    = "Allow replication role to decrypt"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.replication_secondary.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "sourcekey2" {
  provider      = aws.secondary
  name          = local.sourcekey2_alias
  target_key_id = aws_kms_key.sourcekey2.key_id
}

resource "aws_kms_key" "replicakey1" {
  provider = aws.replica1
  description             = "Replica key 1 for first replica region"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 service to encrypt for replication"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action   = "kms:Encrypt"
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = local.account_id
            "kms:ViaService"    = "s3.${var.replica1_region}.amazonaws.com"
          }
        }
      },
      {
        Sid    = "Allow replication roles to encrypt"
        Effect = "Allow"
        Principal = {
          AWS = [
            aws_iam_role.replication_primary.arn,
            aws_iam_role.replication_secondary.arn
          ]
        }
        Action = [
          "kms:Encrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "replicakey1" {
  provider      = aws.replica1
  name          = local.replicakey1_alias
  target_key_id = aws_kms_key.replicakey1.key_id
}

resource "aws_kms_key" "replicakey2" {
  provider = aws.replica2
  description             = "Replica key 2 for second replica region"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 service to encrypt for replication"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action   = "kms:Encrypt"
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = local.account_id
            "kms:ViaService"    = "s3.${var.replica2_region}.amazonaws.com"
          }
        }
      },
      {
        Sid    = "Allow replication roles to encrypt"
        Effect = "Allow"
        Principal = {
          AWS = [
            aws_iam_role.replication_primary.arn,
            aws_iam_role.replication_secondary.arn
          ]
        }
        Action = [
          "kms:Encrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "replicakey2" {
  provider      = aws.replica2
  name          = local.replicakey2_alias
  target_key_id = aws_kms_key.replicakey2.key_id
}

# ---------------------------------------------------------------------------
# KMS Keys for Logging Buckets
# ---------------------------------------------------------------------------
resource "aws_kms_key" "logging_primary" {
  provider = aws
  description             = "Logging key 1 for primary source region"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
