resource "aws_kms_alias" "logging_replica2" {
  provider      = aws.replica2
  name          = local.loggingkey4_alias
  target_key_id = aws_kms_key.logging_replica2.key_id
}

# ---------------------------------------------------------------------------
# IAM Roles and Policies
# ---------------------------------------------------------------------------
resource "aws_iam_role" "replication_primary" {
  provider = aws
  name               = "s3-replication-role-primary"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "replication_primary" {
  provider = aws
  name        = "s3-replication-policy-primary"
  description = "Policy for S3 replication role in primary source region"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ListAndReadSourceBuckets"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:ListBucket",
          "s3:GetBucketVersioning",
          "s3:GetBucketLocation"
        ]
        Resource = [
          "arn:aws:s3:::${local.src_primary_a}",
          "arn:aws:s3:::${local.src_primary_b}",
          "arn:aws:s3:::${local.src_primary_a}/*",
          "arn:aws:s3:::${local.src_primary_b}/*"
        ]
      },
      {
        Sid    = "ReplicateToReplicaBuckets"
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:PutObjectAcl",
          "s3:PutObjectVersionAcl",
          "s3:ReplicateObject",
          "s3:ReplicateDelete"
        ]
        Resource = [
          "arn:aws:s3:::${local.rep1_src1a}/*",
          "arn:aws:s3:::${local.rep1_src1b}/*",
          "arn:aws:s3:::${local.rep1_src2a}/*",
          "arn:aws:s3:::${local.rep1_src2b}/*",
          "arn:aws:s3:::${local.rep2_src1a}/*",
          "arn:aws:s3:::${local.rep2_src1b}/*",
          "arn:aws:s3:::${local.rep2_src2a}/*",
          "arn:aws:s3:::${local.rep2_src2b}/*"
        ]
      },
      {
        Sid    = "DecryptFromSourceKey"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.sourcekey1.arn
      },
      {
        Sid    = "EncryptToReplicaKeys"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:DescribeKey"
        ]
        Resource = [
          aws_kms_key.replicakey1.arn,
          aws_kms_key.replicakey2.arn
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication_primary" {
  provider   = aws
  role       = aws_iam_role.replication_primary.name
  policy_arn = aws_iam_policy.replication_primary.arn
}

resource "aws_iam_role" "replication_secondary" {
  provider = aws.secondary
  name               = "s3-replication-role-secondary"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "replication_secondary" {
  provider = aws.secondary
  name        = "s3-replication-policy-secondary"
  description = "Policy for S3 replication role in secondary source region"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ListAndReadSourceBuckets"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:ListBucket",
          "s3:GetBucketVersioning",
          "s3:GetBucketLocation"
        ]
        Resource = [
          "arn:aws:s3:::${local.src_secondary_a}",
          "arn:aws:s3:::${local.src_secondary_b}",
          "arn:aws:s3:::${local.src_secondary_a}/*",
          "arn:aws:s3:::${local.src_secondary_b}/*"
        ]
      },
      {
        Sid    = "ReplicateToReplicaBuckets"
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:PutObjectAcl",
          "s3:PutObjectVersionAcl",
          "s3:ReplicateObject",
          "s3:ReplicateDelete"
        ]
        Resource = [
          "arn:aws:s3:::${local.rep1_src1a}/*",
          "arn:aws:s3:::${local.rep1_src1b}/*",
          "arn:aws:s3:::${local.rep1_src2a}/*",
          "arn:aws:s3:::${local.rep1_src2b}/*",
          "arn:aws:s3:::${local.rep2_src1a}/*",
          "arn:aws:s3:::${local.rep2_src1b}/*",
          "arn:aws:s3:::${local.rep2_src2a}/*",
          "arn:aws:s3:::${local.rep2_src2b}/*"
        ]
      },
      {
        Sid    = "DecryptFromSourceKey"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.sourcekey2.arn
      },
      {
        Sid    = "EncryptToReplicaKeys"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:DescribeKey"
        ]
        Resource = [
          aws_kms_key.replicakey1.arn,
          aws_kms_key.replicakey2.arn
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication_secondary" {
  provider   = aws.secondary
  role       = aws_iam_role.replication_secondary.name
  policy_arn = aws_iam_policy.replication_secondary.arn
}

# ---------------------------------------------------------------------------
# Logging Buckets (one per region)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "logging_primary" {
  provider = aws
  bucket   = local.logging_primary
  tags = {
    Env = "dev"
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "logging_primary" {
  provider = aws
  bucket   = aws_s3_bucket.logging_primary.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "logging_primary" {
  provider = aws
  bucket   = aws_s3_bucket.logging_primary.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging_primary" {
  provider = aws
  bucket   = aws_s3_bucket.logging_primary.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.logging_primary.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_logging" "logging_primary" {
  provider = aws
  bucket   = aws_s3_bucket.logging_primary.id
  target_bucket = aws_s3_bucket.logging_primary.id
  target_prefix = "self-log/"
}

