# ---------------------------------------------------------------------------
# Replication Configurations - Primary Source Buckets
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_replication_configuration" "src_primary_a" {
  provider = aws
  bucket = aws_s3_bucket.src_primary_a.id
  role   = aws_iam_role.replication_primary.arn

  rule {
    id       = "replicate-to-replica1"
    status   = "Enabled"
    priority = 1

    filter {}

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.replica1_src1a.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replicakey1.arn
      }
    }
  }

  rule {
    id       = "replicate-to-replica2"
    status   = "Enabled"
    priority = 2

    filter {}

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.replica2_src1a.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replicakey2.arn
      }
    }
  }
}

