terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.0"
    }
  }
}

# Variables
variable "module_repo_url" {
  description = "Repository URL for the module"
  type        = string
  default     = "https://github.com/example/repo"
}

# Optional findings filter
variable "create_findings_filter" {
  description = "Set to true to create a GuardDuty findings filter"
  type        = bool
  default     = false
}

variable "findings_filter_name" {
  description = "Name for the findings filter (required if create_findings_filter is true)"
  type        = string
  default     = ""
}

variable "findings_filter_action" {
  description = "Action for the findings filter (ARCHIVE or NOOP)"
  type        = string
  default     = "ARCHIVE"
}

variable "findings_filter_rank" {
  description = "Rank for the findings filter (required)"
  type        = number
  default     = 1
}

variable "findings_filter_criteria" {
  description = "List of criterion objects for the filter. Each object supports: field (string), equals (list(string)), not_equals (list(string)), greater_than (number), less_than (number)."
  type = list(object({
    field       = string
    equals      = optional(list(string))
    not_equals  = optional(list(string))
    greater_than = optional(number)
    less_than   = optional(number)
  }))
  default = []
}

# Optional trusted IP set
variable "create_trusted_ipset" {
  description = "Set to true to create a GuardDuty trusted IP set"
  type        = bool
  default     = false
}

variable "trusted_ipset_name" {
  description = "Name for the trusted IP set"
  type        = string
  default     = ""
}

variable "trusted_ipset_location" {
  description = "S3 URI of the trusted IP list file"
  type        = string
  default     = ""
}

# Optional threat intelligence set
variable "create_threatintel_set" {
  description = "Set to true to create a GuardDuty threat intelligence set"
  type        = bool
  default     = false
}

variable "threatintel_set_name" {
  description = "Name for the threat intelligence set"
  type        = string
  default     = ""
}

variable "threatintel_set_location" {
  description = "S3 URI of the threat intelligence list file"
  type        = string
  default     = ""
}

# Optional malware protection plan for S3
variable "create_malware_protection_plan" {
  description = "Set to true to create a GuardDuty malware protection plan for S3"
  type        = bool
  default     = false
}

variable "malware_protection_plan_s3_bucket_name" {
  description = "Name of the S3 bucket to protect"
  type        = string
  default     = ""
}

variable "malware_protection_plan_role_arn" {
  description = "ARN of the IAM role for the malware protection plan"
  type        = string
  default     = ""
}

# Optional export bucket
variable "create_export_bucket" {
  description = "Set to true to create an S3 bucket for GuardDuty findings export"
  type        = bool
  default     = false
}

variable "export_bucket_name" {
  description = "Name of the export S3 bucket"
  type        = string
  default     = ""
}

variable "export_bucket_logging_bucket" {
  description = "Name of the S3 bucket for access logs (optional, must exist)"
  type        = string
  default     = ""
}

variable "enable_replication" {
  description = "Enable cross-region replication for the export bucket"
  type        = bool
  default     = false
}

variable "replication_destination_bucket_arn" {
  description = "ARN of the destination bucket for replication"
  type        = string
  default     = ""
}

# Main GuardDuty Detector
resource "aws_guardduty_detector" "main" {
  enable                       = true
  finding_publishing_frequency = "FIFTEEN_MINUTES"

  tags = {
    module_repo_url = var.module_repo_url
  }
}

# Detector Features
resource "aws_guardduty_detector_feature" "s3_data_events" {
  detector_id = aws_guardduty_detector.main.id
  name        = "S3_DATA_EVENTS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "rds_login_events" {
  detector_id = aws_guardduty_detector.main.id
  name        = "RDS_LOGIN_EVENTS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "lambda_network_logs" {
  detector_id = aws_guardduty_detector.main.id
  name        = "LAMBDA_NETWORK_LOGS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "eks_audit_logs" {
  detector_id = aws_guardduty_detector.main.id
  name        = "EKS_AUDIT_LOGS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "ebs_malware_protection" {
  detector_id = aws_guardduty_detector.main.id
  name        = "EBS_MALWARE_PROTECTION"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "runtime_monitoring" {
  detector_id = aws_guardduty_detector.main.id
  name        = "RUNTIME_MONITORING"
  status      = "ENABLED"

  additional_configuration {
    name   = "EKS_ADDON_MANAGEMENT"
    status = "DISABLED"
  }

  additional_configuration {
    name   = "ECS_FARGATE_AGENT_MANAGEMENT"
    status = "DISABLED"
  }

  additional_configuration {
    name   = "EC2_AGENT_MANAGEMENT"
    status = "DISABLED"
  }
}

# CLI command to disable EBS snapshot preservation using JSON input
resource "null_resource" "disable_ebs_snapshot_retention" {
  depends_on = [
    aws_guardduty_detector_feature.s3_data_events,
    aws_guardduty_detector_feature.rds_login_events,
    aws_guardduty_detector_feature.lambda_network_logs,
    aws_guardduty_detector_feature.eks_audit_logs,
    aws_guardduty_detector_feature.ebs_malware_protection,
    aws_guardduty_detector_feature.runtime_monitoring
  ]

  provisioner "local-exec" {
    command = "aws guardduty update-malware-scan-settings --cli-input-json '${jsonencode({"DetectorId": aws_guardduty_detector.main.id, "EbsSnapshotPreservation": "NO_RETENTION"})}'"
  }
}

# Optional findings filter
resource "aws_guardduty_filter" "findings_filter" {
  count = var.create_findings_filter ? 1 : 0

  detector_id = aws_guardduty_detector.main.id
  name        = var.findings_filter_name
  action      = var.findings_filter_action
  rank        = var.findings_filter_rank

  finding_criteria {
    dynamic "criterion" {
      for_each = var.findings_filter_criteria
      content {
        field        = criterion.value.field
        equals       = criterion.value.equals
        not_equals   = criterion.value.not_equals
        greater_than = criterion.value.greater_than
        less_than    = criterion.value.less_than
      }
    }
  }
}

# Optional trusted IP set
resource "aws_guardduty_ipset" "trusted_ipset" {
  count = var.create_trusted_ipset ? 1 : 0

  activate     = true
  detector_id  = aws_guardduty_detector.main.id
  format       = "TXT"
  location     = var.trusted_ipset_location
  name         = var.trusted_ipset_name
}

# Optional threat intelligence set
resource "aws_guardduty_threatintelset" "threatintel_set" {
  count = var.create_threatintel_set ? 1 : 0

  activate     = true
  detector_id  = aws_guardduty_detector.main.id
  format       = "TXT"
  location     = var.threatintel_set_location
  name         = var.threatintel_set_name
}

# Optional malware protection plan for S3
resource "aws_guardduty_malware_protection_plan" "s3_plan" {
  count = var.create_malware_protection_plan ? 1 : 0

  role = var.malware_protection_plan_role_arn

  protected_resource {
    s3_bucket {
      bucket_name = var.malware_protection_plan_s3_bucket_name
    }
  }
}

# Optional export bucket and related resources
resource "aws_kms_key" "export" {
  count = var.create_export_bucket ? 1 : 0

  description             = "KMS key for GuardDuty export bucket encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

resource "aws_s3_bucket" "export" {
  count = var.create_export_bucket ? 1 : 0

  bucket = var.export_bucket_name
}

resource "aws_s3_bucket_public_access_block" "export" {
  count = var.create_export_bucket ? 1 : 0

  bucket = aws_s3_bucket.export[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "export" {
  count = var.create_export_bucket ? 1 : 0

  bucket = aws_s3_bucket.export[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "export" {
  count = var.create_export_bucket ? 1 : 0

  bucket = aws_s3_bucket.export[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.export[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_logging" "export" {
  count = var.create_export_bucket && var.export_bucket_logging_bucket != "" ? 1 : 0

  bucket = aws_s3_bucket.export[0].id

  target_bucket = var.export_bucket_logging_bucket
  target_prefix = "log/"
}

# Cross-region replication resources
resource "aws_iam_role" "replication" {
  count = var.create_export_bucket && var.enable_replication && var.replication_destination_bucket_arn != "" ? 1 : 0

  name = "guardduty-export-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
}

data "aws_iam_policy_document" "replication" {
  count = var.create_export_bucket && var.enable_replication && var.replication_destination_bucket_arn != "" ? 1 : 0

  statement {
    actions   = ["s3:GetReplicationConfiguration", "s3:ListBucket"]
    resources = [aws_s3_bucket.export[0].arn]
  }

  statement {
    actions   = ["s3:GetObjectVersionForReplication", "s3:GetObjectVersionAcl", "s3:GetObjectVersionTagging"]
    resources = ["${aws_s3_bucket.export[0].arn}/*"]
  }

  statement {
    actions   = ["s3:ReplicateObject", "s3:ReplicateDelete", "s3:ReplicateTags"]
    resources = ["${var.replication_destination_bucket_arn}/*"]
  }
}

resource "aws_iam_role_policy" "replication" {
  count = var.create_export_bucket && var.enable_replication && var.replication_destination_bucket_arn != "" ? 1 : 0

  role   = aws_iam_role.replication[0].name
  policy = data.aws_iam_policy_document.replication[0].json
}

resource "aws_s3_bucket_replication_configuration" "export" {
  count = var.create_export_bucket && var.enable_replication && var.replication_destination_bucket_arn != "" ? 1 : 0

  bucket = aws_s3_bucket.export[0].id
  role   = aws_iam_role.replication[0].arn

  rule {
    id     = "GuardDutyExportReplication"
    status = "Enabled"

    destination {
      bucket = var.replication_destination_bucket_arn
    }
  }
}
